def borrar_apis_json():
    """Solo con la confirmacion de Leandro (boton de Ajustes -> Claves) y solo
    si todas sus claves ya estan en el almacen."""
    faltan = []
    for a in load_apis():
        key = str((a or {}).get("key") or "").strip()
        if key and not any(cred_clave(c["cuenta"]) == key for c in cred_lista()):
            faltan.append(str((a or {}).get("name") or "?"))
    if faltan:
        return False, "no lo borro: estas claves de apis.json no están en el almacén: " + ", ".join(faltan)
    try:
        APIS_FILE.unlink()
    except OSError as e:
        return False, f"no se pudo borrar ({type(e).__name__})"
    log("claves: apis.json (texto plano) borrado con tu confirmación; sus claves siguen en el almacén")
    return True, "apis.json borrado."


def mask_key(key):
    """Muestra solo los ultimos 4 caracteres de una clave."""
    k = str(key)
    return ("•" * max(0, len(k) - 4)) + k[-4:] if len(k) > 4 else "•" * len(k)


def import_api_files():
    """Toma los archivos que Growi empuja por el puente (inbox/apis/*.json:
    name o provider, key y, si quiere, etiqueta y base_url) y los guarda en el
    almacen de claves (nunca en un JSON). Borra el archivo tras importarlo para
    que la clave no quede dando vueltas en el Inbox. Devuelve cuantas se
    añadieron."""
    api_inbox = INBOX / "apis"
    if not api_inbox.is_dir():
        return 0
    added = 0
    for p in sorted(api_inbox.glob("*.json")):
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            name = str(data.get("name", "")).strip()
            key = str(data.get("key", "")).strip()
            if not (name or data.get("provider")) or not key or len(name) > 80:
                raise ValueError("nombre o clave invalidos")
            prov = data.get("provider") if data.get("provider") in CRED_PROVIDERS else cred_proveedor_de(name)
            if not prov:
                raise ValueError(f"'{name}' no es de ningún proveedor conocido ({', '.join(CRED_ORDER)})")
            ok, msg = cred_guardar(prov, str(data.get("etiqueta") or "principal"), data.get("base_url"), key)
            if not ok:
                raise ValueError(msg)
            added += 1
            log(f"APIs: clave de {prov} añadida desde WhatsApp (en el almacén de claves, solo en este PC)")
        except Exception as e:
            log(f"APIs: no se pudo importar {p.name} ({_scrub(str(e), '')})")
        finally:
            try:
                p.unlink()
            except OSError:
                pass
    if added and _root is not None:
        try:
            _root.after(0, refresh_apis_ui)
        except Exception:
            pass
    return added


