# ---------------------------------------------------------------- skills
def list_skills():
    """Lee ~/.claude/skills/: cada carpeta con SKILL.md es una skill."""
    base = HOME_DIR / ".claude" / "skills"
    out = []
    if not base.is_dir():
        return out
    for folder in sorted(base.iterdir()):
        if not folder.is_dir():
            continue
        skill_file = folder / "SKILL.md"
        name = folder.name
        desc = ""
        if skill_file.is_file():
            try:
                text = skill_file.read_text(encoding="utf-8", errors="replace")
                if text.startswith("---"):
                    end = text.find("---", 3)
                    if end > 0:
                        for line in text[3:end].splitlines():
                            if line.strip().lower().startswith("description:"):
                                desc = line.split(":", 1)[1].strip().strip("\"'")
                            if line.strip().lower().startswith("name:"):
                                name = line.split(":", 1)[1].strip().strip("\"'")
                if not desc:
                    for line in text.splitlines():
                        if line.strip() and not line.startswith("#") and not line.startswith("---"):
                            desc = line.strip()
                            break
            except OSError:
                pass
        out.append((name, desc, str(folder)))
    return out


# ---------------------------------------------------------------- skills nativas de Bridge
# (t-skills-nativas, 0.3.0) Carpeta propia skills\ junto al programa: cada
# skill es una carpeta con su SKILL.md (frontmatter YAML: name, description,
# version, requires) y sus scripts de apoyo al lado. Sin marketplace y sin
# descargas: las skills entran solo escritas por Leandro/Growi o copiadas a
# mano por Leandro. OpenClaw NO se usa: de su diseno solo se tomaron como
# referencia los limites del descubrimiento, el escaneo de secretos literales
# y el workshop en modo «propose».
#   skills\<nombre>\             propia      (del proyecto: manda sobre las demas)
#   skills\_equipo\<nombre>\     del equipo  (del usuario: copiadas a mano por Leandro)
#   skills\_incluidas\<nombre>\  incluida    (vienen con Bridge)
#   skills\_borradores\          lo que propone el runner: NUNCA se carga ni se activa
# Al motor no le llega el indice entero: el runner elige por la DESCRIPCION
# (no por el nombre) hasta 3 skills y le pasa solo el cuerpo de esas,
# recortado. Nada de «always: true».
SKILLS_DIR = Path(os.environ.get("GROWI_BRIDGE_SKILLS") or (APP_DIR / "skills"))
SKILL_ORIGENES = (("propia", "", "propia"), ("equipo", "_equipo", "del equipo"),
                  ("incluida", "_incluidas", "incluida"))
SKILL_ORIGEN_TXT = {o: t for o, _s, t in SKILL_ORIGENES}
SKILLS_BORRADORES = "_borradores"
SKILL_MAX_PROF = 6            # niveles por debajo de cada raiz
SKILL_MAX_N = 200             # skills como mucho (lo demas no se lee y se avisa)
SKILL_MAX_BYTES = 256 * 1024  # por SKILL.md
SKILL_MAX_ACTIVAS = 3
SKILL_PROMPT_MAX = 6000       # caracteres del cuerpo de cada skill activada
SKILL_DESC_MAX = 1024
SKILL_APOYO_MAX = 100         # archivos de apoyo que se escanean por skill
REDACTADO = "[REDACTED CREDENTIAL]"
_SKILL_NOMBRE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$")
_SKILL_VERSION_RE = re.compile(r"^\d+(\.\d+){0,3}([-+][0-9A-Za-z.-]+)?$")
_SKILL_ENV_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]{0,127}$")
_SKILL_BIN_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$")
_SKILL_CLAVES = {"name", "description", "version", "requires", "primaryEnv", "always", "borrador"}
_SKILL_REQ_CLAVES = {"env", "bins", "primaryEnv"}
# Secretos literales (escaneo tipo «literal-secret»): si aparece uno, la skill
# es sospechosa, no se carga y la evidencia se redacta.
_SECRETO_RES = (
    ("clave tipo sk-", re.compile(r"(?<![A-Za-z0-9_-])sk-[A-Za-z0-9][A-Za-z0-9_-]{5,}")),
    ("token de GitHub (gh*_)", re.compile(r"(?<![A-Za-z0-9_])gh[pousr]_[A-Za-z0-9]{8,}")),
    ("token de GitHub (github_pat_)", re.compile(r"(?<![A-Za-z0-9_])github_pat_[A-Za-z0-9_]{8,}")),
    ("token de Slack (xox?-)", re.compile(r"(?<![A-Za-z0-9_])xox[baprs]-[A-Za-z0-9-]{6,}")),
    ("clave de Google (AIza)", re.compile(r"(?<![A-Za-z0-9_])AIza[0-9A-Za-z_-]{10,}")),
    ("clave privada (BEGIN ... PRIVATE KEY)", re.compile(r"-----BEGIN[A-Z0-9 ]*PRIVATE KEY-----")),
    ("clave de Tripo (tsk_)", re.compile(r"(?<![A-Za-z0-9_])tsk_[A-Za-z0-9_-]{8,}")),
)
_SKX = {"lock": threading.Lock(), "estado": "carga", "skills": [], "rechazadas": [], "avisos": [],
        "borradores": [], "at": None, "error": None, "ms": None, "motivo": None}
_SKILLS_ACT = {}  # task_id -> registro de la activacion (va al .result.json)


# -- YAML minimo (sin dependencias): mapas por sangria, listas «- x», listas
# en linea [a, b], escalares con o sin comillas, | y >. Basta para el
# frontmatter de una skill; lo que no entiende es un error con su linea.
def _yaml_escalar(v, n):
    v = v.strip()
    if v[:1] == '"':
        i, esc = 1, False
        while i < len(v):
            if esc:
                esc = False
            elif v[i] == "\\":
                esc = True
            elif v[i] == '"':
                break
            i += 1
        else:
            raise ValueError(f"línea {n}: comillas sin cerrar")
        resto = v[i + 1:].strip()
        if resto and not resto.startswith("#"):
            raise ValueError(f"línea {n}: texto después de las comillas")
        try:
            return json.loads(v[:i + 1])
        except ValueError:
            raise ValueError(f"línea {n}: escape no válido entre comillas")
    if v[:1] == "'":
        j = 1
        while True:
            j = v.find("'", j)
            if j < 0:
                raise ValueError(f"línea {n}: comillas sin cerrar")
            if v[j + 1:j + 2] == "'":
                j += 2
                continue
            break
        resto = v[j + 1:].strip()
        if resto and not resto.startswith("#"):
            raise ValueError(f"línea {n}: texto después de las comillas")
        return v[1:j].replace("''", "'")
    if " #" in v:
        v = v.split(" #", 1)[0].rstrip()
    if v.startswith("["):
        if not v.endswith("]"):
            raise ValueError(f"línea {n}: lista en línea sin cerrar")
        dentro = v[1:-1].strip()
        if not dentro:
            return []
        partes, cur, q = [], "", None
        for ch in dentro:
            if q:
                cur += ch
                if ch == q:
                    q = None
            elif ch in "\"'":
                q = ch
                cur += ch
            elif ch == ",":
                partes.append(cur)
                cur = ""
            else:
                cur += ch
        partes.append(cur)
        return [_yaml_escalar(p, n) for p in partes if p.strip()]
    if v.startswith("{"):
        if v.replace(" ", "") == "{}":
            return {}
        raise ValueError(f"línea {n}: mapa en línea {{...}} no soportado (usa un bloque con sangría)")
    if v[:1] in ("&", "*", "!", "%", "@", "`"):
        raise ValueError(f"línea {n}: «{v[:1]}» no está soportado en el frontmatter")
    low = v.lower()
    if low in ("true", "yes"):
        return True
    if low in ("false", "no"):
        return False
    if low in ("null", "~", ""):
        return None
    return v


def yaml_minimo(texto):
    lineas = []
    for n, raw in enumerate(texto.split("\n"), 1):
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        sang = len(raw) - len(raw.lstrip(" "))
        if raw[sang:sang + 1] == "\t":
            raise ValueError(f"línea {n}: tabulador en la sangría (usa espacios)")
        lineas.append((sang, raw.strip(), n))
    if not lineas:
        return {}
    pos = [0]

    def bloque(ind):
        sang, txt, n = lineas[pos[0]]
        if txt == "-" or txt.startswith("- "):
            out = []
            while pos[0] < len(lineas):
                sang, txt, n = lineas[pos[0]]
                if sang < ind:
                    break
                if sang > ind:
                    raise ValueError(f"línea {n}: sangría inesperada")
                if not (txt == "-" or txt.startswith("- ")):
                    break
                pos[0] += 1
                item = txt[1:].strip()
                if item:
                    if re.match(r"^[A-Za-z_][\w.-]*\s*:(\s|$)", item) and item[:1] not in "\"'":
                        raise ValueError(f"línea {n}: mapas dentro de una lista no están soportados")
                    out.append(_yaml_escalar(item, n))
                elif pos[0] < len(lineas) and lineas[pos[0]][0] > ind:
                    out.append(bloque(lineas[pos[0]][0]))
                else:
                    out.append(None)
            return out
        out = {}
        while pos[0] < len(lineas):
            sang, txt, n = lineas[pos[0]]
            if sang < ind:
                break
            if sang > ind:
                raise ValueError(f"línea {n}: sangría inesperada")
            m = re.match(r"^([A-Za-z_][\w.-]*)\s*:(?:\s+(.*))?$", txt)
            if not m:
                raise ValueError(f"línea {n}: se esperaba «clave: valor» y hay «{txt[:40]}»")
            k, v = m.group(1), (m.group(2) or "").strip()
            if k in out:
                raise ValueError(f"línea {n}: la clave «{k}» está repetida")
            pos[0] += 1
            if v[:1] in ("|", ">") and re.match(r"^[|>][+-]?$", v):
                partes = []
                while pos[0] < len(lineas) and lineas[pos[0]][0] > ind:
                    partes.append(lineas[pos[0]][1])
                    pos[0] += 1
                out[k] = ("\n" if v[0] == "|" else " ").join(partes)
            elif v and not v.startswith("#"):
                out[k] = _yaml_escalar(v, n)
            elif pos[0] < len(lineas) and lineas[pos[0]][0] > ind:
                out[k] = bloque(lineas[pos[0]][0])
            elif (pos[0] < len(lineas) and lineas[pos[0]][0] == ind
                  and (lineas[pos[0]][1] == "-" or lineas[pos[0]][1].startswith("- "))):
                out[k] = bloque(ind)
            else:
                out[k] = None
        return out

    val = bloque(lineas[0][0])
    if pos[0] < len(lineas):
        raise ValueError(f"línea {lineas[pos[0]][2]}: sangría inesperada")
    if not isinstance(val, dict):
        raise ValueError("el frontmatter tiene que ser un bloque «clave: valor»")
    return val


def skill_partir(texto):
    """(frontmatter, cuerpo). Error claro si no hay bloque --- ... ---."""
    t = texto.lstrip("﻿").replace("\r\n", "\n")
    lineas = t.split("\n")
    if not lineas or lineas[0].strip() != "---":
        raise ValueError("no empieza con el bloque de frontmatter (una línea «---»)")
    for i in range(1, len(lineas)):
        if lineas[i].strip() in ("---", "..."):
            return "\n".join(lineas[1:i]), "\n".join(lineas[i + 1:])
    raise ValueError("el frontmatter no se cierra con otra línea «---»")


def skill_escanear_secretos(texto, archivo):
    """Hallazgos [{archivo, linea, tipo, evidencia}] con la evidencia YA
    redactada (el secreto no sale nunca: ni en la ventana ni en el registro)."""
    out = []
    for n, linea in enumerate(texto.split("\n"), 1):
        for tipo, rx in _SECRETO_RES:
            if rx.search(linea):
                red = linea
                for _t, rx2 in _SECRETO_RES:
                    red = rx2.sub(REDACTADO, red)
                red = red.strip()
                out.append({"archivo": archivo, "linea": n, "tipo": tipo,
                            "evidencia": red if len(red) <= 160 else red[:159] + "…"})
                break
    return out


def skill_validar_meta(meta):
    """(problemas, avisos, requires_normalizado). Los motivos son exactos."""
    prob, av = [], []
    for k in ("name", "description", "version"):
        v = meta.get(k)
        if k not in meta:
            prob.append(f"falta «{k}»")
        elif v is None or (isinstance(v, str) and not v.strip()):
            prob.append(f"«{k}» está vacío")
        elif not isinstance(v, str):
            prob.append(f"«{k}» tiene que ser un texto, no {type(v).__name__}")
    name, desc, ver = meta.get("name"), meta.get("description"), meta.get("version")
    if isinstance(name, str) and name.strip() and not _SKILL_NOMBRE_RE.match(name.strip()):
        prob.append(f"«name» no vale ('{name.strip()[:40]}'): solo letras, números, - _ . y hasta 64")
    if isinstance(desc, str) and len(desc) > SKILL_DESC_MAX:
        prob.append(f"«description» es demasiado larga ({len(desc)} caracteres; máximo {SKILL_DESC_MAX})")
    if isinstance(desc, str) and desc.strip() and len(desc.split()) < 4:
        prob.append("«description» es demasiado corta (menos de 4 palabras): el runner elige por ella")
    if isinstance(ver, str) and ver.strip() and not _SKILL_VERSION_RE.match(ver.strip()):
        prob.append(f"«version» no tiene formato de versión ('{ver.strip()[:20]}'): usa algo como 1.0.0")
    for k in sorted(set(meta) - _SKILL_CLAVES):
        av.append(f"clave desconocida «{k}» (se ignora)")
    if meta.get("always") not in (None, False):
        av.append("«always» no se respeta: en Bridge cada skill se activa solo cuando la tarea la pide")
    req = {"env": [], "bins": [], "primaryEnv": None}
    r = meta.get("requires")
    if r is not None and not isinstance(r, dict):
        prob.append("«requires» tiene que ser un bloque con env, bins y primaryEnv")
        r = {}
    r = r or {}
    for k in sorted(set(r) - _SKILL_REQ_CLAVES):
        prob.append(f"«requires» tiene una clave desconocida «{k}» (valen env, bins, primaryEnv)")
    for k, rx, que in (("env", _SKILL_ENV_RE, "nombre de variable"), ("bins", _SKILL_BIN_RE, "nombre de programa")):
        v = r.get(k)
        if v is None:
            continue
        if not isinstance(v, list):
            prob.append(f"«requires.{k}» tiene que ser una lista")
            continue
        for x in v:
            if not isinstance(x, str) or not rx.match(x.strip()):
                prob.append(f"«requires.{k}»: '{str(x)[:40]}' no es un {que} válido"
                            + (" (sin rutas: el programa se busca en el PATH)" if k == "bins" else ""))
            else:
                req[k].append(x.strip())
    pe = r.get("primaryEnv", meta.get("primaryEnv"))
    if pe is not None:
        if not isinstance(pe, str) or not _SKILL_ENV_RE.match(pe.strip()):
            prob.append(f"«primaryEnv»: '{str(pe)[:40]}' no es un nombre de variable válido")
        else:
            req["primaryEnv"] = pe.strip()
            if req["primaryEnv"] not in req["env"]:
                req["env"].append(req["primaryEnv"])
    return prob, av, req


def _skill_es_enlace(p):
    try:
        if os.path.islink(p):
            return True
        j = getattr(os.path, "isjunction", None)
        return bool(j and j(p))
    except OSError:
        return True


def _skill_dentro(p, raiz_real):
    rc = os.path.normcase(os.path.realpath(p))
    rr = os.path.normcase(raiz_real).rstrip("\\/")
    return rc == rr or rc.startswith(rr + os.sep)


def _skill_rel(p):
    try:
        return str(Path(p).relative_to(SKILLS_DIR))
    except ValueError:
        return str(p)


def _skill_escanear_apoyo(d, raiz_real):
    """Escanea los archivos de apoyo de la skill (texto) buscando secretos."""
    out, vistos = [], 0
    for base, dirs, files in os.walk(d, followlinks=False):
        dirs[:] = sorted(x for x in dirs if not _skill_es_enlace(os.path.join(base, x)))
        if len(Path(base).relative_to(d).parts) >= SKILL_MAX_PROF:
            dirs[:] = []
        for f in sorted(files):
            if f == "SKILL.md" and Path(base) == d:
                continue
            fp = os.path.join(base, f)
            vistos += 1
            if vistos > SKILL_APOYO_MAX:
                return out
            if _skill_es_enlace(fp) or not _skill_dentro(fp, raiz_real):
                out.append({"archivo": _skill_rel(fp), "linea": 0, "tipo": "enlace",
                            "evidencia": "enlace simbólico o fuera de skills\\: no se sigue"})
                continue
            try:
                if os.path.getsize(fp) > 2 * 1024 * 1024:
                    continue
                raw = open(fp, "rb").read()
            except OSError:
                continue
            if b"\x00" in raw[:4096]:
                continue  # binario
            out += skill_escanear_secretos(raw.decode("utf-8", errors="replace"), _skill_rel(fp))
    return out


def _skill_leer(origen, d, raiz_real, borrador=False):
    """Lee y valida una skill. Nunca lanza: una skill mala sale con su motivo."""
    f = Path(d) / "SKILL.md"
    it = {"origen": origen, "origen_txt": "borrador" if borrador else SKILL_ORIGEN_TXT.get(origen, origen),
          "carpeta": str(d), "rel": _skill_rel(d), "archivo": str(f), "estado": "ok", "motivos": [],
          "avisos": [], "secretos": [], "name": Path(d).name, "description": "", "version": "",
          "requires": {"env": [], "bins": [], "primaryEnv": None}}
    try:
        if _skill_es_enlace(f):
            raise ValueError("SKILL.md es un enlace simbólico: no se sigue")
        if not _skill_dentro(f, raiz_real):
            raise ValueError("SKILL.md se sale de la carpeta skills\\")
        st = f.stat()
        if st.st_size > SKILL_MAX_BYTES:
            raise ValueError(f"SKILL.md pesa {st.st_size // 1024} KB (máximo {SKILL_MAX_BYTES // 1024} KB)")
        raw = f.read_bytes()
        try:
            texto = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("SKILL.md no está en UTF-8")
        it.update(bytes=st.st_size, mtime=st.st_mtime, sha=hashlib.sha256(raw).hexdigest()[:16])
        sec = skill_escanear_secretos(texto, _skill_rel(f)) + _skill_escanear_apoyo(Path(d), raiz_real)
        try:
            fm, _cuerpo = skill_partir(texto)
            meta = yaml_minimo(fm)
        except ValueError as e:
            if sec:
                meta = {}
            else:
                raise ValueError(f"frontmatter roto: {e}")
        if isinstance(meta.get("name"), str) and meta["name"].strip():
            it["name"] = meta["name"].strip()
        if sec:
            it.update(estado="sospechosa", secretos=sec)
            it["motivos"].append(f"tiene {len(sec)} secreto(s) literal(es) ({sec[0]['tipo']}): "
                                 "es sospechosa y no se carga")
            return it
        prob, av, req = skill_validar_meta(meta)
        it["avisos"] += av
        if isinstance(meta.get("description"), str):
            it["description"] = " ".join(meta["description"].split())
        if isinstance(meta.get("version"), str):
            it["version"] = meta["version"].strip()
        it["requires"] = req
        if meta.get("borrador") is True and not borrador:
            prob.append("es un borrador («borrador: true»): apruébalo desde la app (Skills, Borradores)")
        if prob:
            it.update(estado="invalida")
            it["motivos"] += prob
        if it["name"] != Path(d).name and not borrador:
            it["avisos"].append(f"la carpeta se llama «{Path(d).name}» y la skill «{it['name']}»")
    except Exception as e:
        it.update(estado="invalida")
        it["motivos"].append(str(e) if isinstance(e, (ValueError, OSError)) else f"{type(e).__name__}: {e}")
    return it


def _skills_descubrir(raiz_real):
    """[(origen, carpeta)] y rechazos de rutas. Limites: 6 niveles, 200 skills."""
    hallados, rech, avisos = [], [], []
    for oid, sub, _t in SKILL_ORIGENES:
        base = SKILLS_DIR / sub if sub else SKILLS_DIR
        if sub and not base.is_dir():
            continue
        if sub and (_skill_es_enlace(base) or not _skill_dentro(base, raiz_real)):
            rech.append({"rel": sub, "motivo": "es un enlace simbólico o se sale de skills\\: no se sigue"})
            continue
        pila = [(base, 0)]
        while pila:
            d, prof = pila.pop()
            if prof > 0 and (d / "SKILL.md").exists():
                hallados.append((oid, d))
                continue  # no se baja dentro de una skill: lo de dentro es su apoyo
            if prof >= SKILL_MAX_PROF:
                avisos.append(f"{_skill_rel(d)}: más de {SKILL_MAX_PROF} niveles, no se busca más adentro")
                continue
            try:
                hijos = sorted(os.scandir(d), key=lambda e: e.name.lower(), reverse=True)
            except OSError as e:
                avisos.append(f"{_skill_rel(d)}: no se pudo abrir ({e.strerror or e})")
                continue
            for e in hijos:
                if e.name.startswith("."):
                    continue
                if oid == "propia" and prof == 0 and e.name.startswith("_"):
                    continue  # _equipo, _incluidas, _borradores: raices aparte
                if _skill_es_enlace(e.path):
                    if os.path.isdir(e.path):
                        rech.append({"rel": _skill_rel(e.path),
                                     "motivo": "es un enlace simbólico o una unión de carpetas: no se sigue"})
                    continue
                if not e.is_dir(follow_symlinks=False):
                    continue
                if not _skill_dentro(e.path, raiz_real):
                    rech.append({"rel": _skill_rel(e.path), "motivo": "se sale de la carpeta skills\\"})
                    continue
                pila.append((Path(e.path), prof + 1))
            if len(hallados) > SKILL_MAX_N:
                break
    if len(hallados) > SKILL_MAX_N:
        avisos.append(f"hay más de {SKILL_MAX_N} skills: solo se leyeron las primeras {SKILL_MAX_N}")
        hallados = hallados[:SKILL_MAX_N]
    return hallados, rech, avisos


def skills_borradores():
    base = SKILLS_DIR / SKILLS_BORRADORES
    out = []
    if not base.is_dir() or _skill_es_enlace(base):
        return out
    raiz_real = os.path.realpath(SKILLS_DIR)
    for e in sorted(os.scandir(base), key=lambda e: e.name.lower()):
        if not e.is_dir(follow_symlinks=False) or _skill_es_enlace(e.path) or e.name.startswith("."):
            continue
        if not (Path(e.path) / "SKILL.md").is_file():
            continue
        it = _skill_leer("borrador", Path(e.path), raiz_real, borrador=True)
        try:
            it["meta_borrador"] = json.loads((Path(e.path) / "BORRADOR.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            it["meta_borrador"] = {}
        out.append(it)
    return out


def skills_indexar(motivo="arranque"):
    """(Re)construye el indice en memoria: nombre + descripcion + requisitos
    de cada skill valida (el cuerpo NO: se lee al activarla). Precedencia:
    propia > del equipo > incluida. Nunca lanza."""
    t0 = time.perf_counter()
    with _SKX["lock"]:
        try:
            if not SKILLS_DIR.is_dir():
                _SKX.update(estado="sin_carpeta", skills=[], rechazadas=[], avisos=[], borradores=[],
                            error=f"{SKILLS_DIR} no existe o no se puede abrir")
            else:
                raiz_real = os.path.realpath(SKILLS_DIR)
                hallados, rech, avisos = _skills_descubrir(raiz_real)
                leidas = [_skill_leer(o, d, raiz_real) for o, d in hallados]
                orden = {o: i for i, (o, _s, _t) in enumerate(SKILL_ORIGENES)}
                buenas, ganadora = [], {}
                for it in sorted((x for x in leidas if x["estado"] == "ok"), key=lambda x: orden[x["origen"]]):
                    k = it["name"].lower()
                    if k in ganadora:
                        g = ganadora[k]
                        it["estado"] = "tapada"
                        it["motivos"].append(f"la tapa la skill «{g['name']}» ({g['origen_txt']}) en "
                                             f"skills\\{g['rel']}")
                        continue
                    ganadora[k] = it
                    it["_tok"] = _skill_tokens(it["description"])
                    buenas.append(it)
                malas = [x for x in leidas if x["estado"] != "ok"] + [
                    dict(x, estado="ruta", motivos=[x["motivo"]], name=x["rel"], origen_txt="ruta no válida")
                    for x in rech]
                _SKX.update(estado="contenido" if (buenas or malas) else "vacio",
                            skills=sorted(buenas, key=lambda x: x["name"].lower()), rechazadas=malas,
                            avisos=avisos, borradores=skills_borradores(), error=None)
        except Exception as e:
            _SKX.update(estado="error", error=f"{type(e).__name__}: {e}")
        _SKX.update(at=_now_iso(), ms=round((time.perf_counter() - t0) * 1000), motivo=motivo)
        n_ok, n_mal = len(_SKX["skills"]), len(_SKX["rechazadas"])
    log(f"skills: índice ({motivo}): {n_ok} cargada(s), {n_mal} no se cargaron, "
        f"{len(_SKX['borradores'])} borrador(es) [{_SKX['estado']}, {_SKX['ms']} ms]"
        + (f"; {_SKX['error']}" if _SKX.get("error") else ""))
    for x in _SKX["rechazadas"]:
        log(f"skills: NO se carga {x.get('rel')}: " + "; ".join(x.get("motivos") or [])[:300]
            + ("".join(f" | evidencia (redactada) {s['archivo']} línea {s['linea']}: {s['evidencia']}"
                       for s in (x.get("secretos") or [])[:3])))
    return _SKX


def skills_indice():
    """El indice actual (lo construye la primera vez)."""
    if _SKX["at"] is None:
        skills_indexar("primer uso")
    return _SKX


def _skills_bridge_firma():
    """Huella de skills\\ (para reconstruir el indice al cambiar algo)."""
    out = []
    try:
        for base, dirs, files in os.walk(SKILLS_DIR, followlinks=False):
            prof = len(Path(base).relative_to(SKILLS_DIR).parts)
            dirs[:] = sorted(dirs) if prof < SKILL_MAX_PROF + 2 else []
            for f in files:
                if f in ("SKILL.md", "BORRADOR.json") or prof <= 1:
                    try:
                        st = os.stat(os.path.join(base, f))
                        out.append((os.path.join(base, f), st.st_mtime_ns, st.st_size))
                    except OSError:
                        pass
            out.append((base, len(dirs)))
            if len(out) > 5000:
                break
    except (OSError, ValueError):
        return ("error",)
    return tuple(out) if SKILLS_DIR.is_dir() else ("sin_carpeta",)


# -- requisitos comprobados en vivo (cada vez que se muestran o se activa)
def _env_en_windows(nombre):
    try:
        import winreg
    except ImportError:
        return None
    for raiz, sub in ((winreg.HKEY_CURRENT_USER, r"Environment"),
                      (winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Control\Session Manager\Environment")):
        try:
            with winreg.OpenKey(raiz, sub) as k:
                v, _t = winreg.QueryValueEx(k, nombre)
                if str(v).strip():
                    return "usuario" if raiz == winreg.HKEY_CURRENT_USER else "sistema"
        except OSError:
            continue
    return None


def skill_requisitos(sk):
    """[{tipo, nombre, ok, detalle}] comprobado ahora mismo (nunca el valor)."""
    out = []
    req = sk.get("requires") or {}
    for b in req.get("bins") or []:
        p = shutil.which(b)
        out.append({"tipo": "programa", "nombre": b, "ok": bool(p),
                    "detalle": f"está ({p})" if p else "falta: no está en el PATH"})
    for v in req.get("env") or []:
        principal = v == req.get("primaryEnv")
        if os.environ.get(v, "").strip():
            det = "está (la app la ve; el valor no se muestra)"
            ok = True
        else:
            dondew = _env_en_windows(v)
            ok = False
            det = (f"falta en la app (está en las variables de {dondew} de Windows: "
                   "cierra y vuelve a abrir la app)" if dondew else "falta: la variable no existe")
        out.append({"tipo": "variable", "nombre": v, "ok": ok, "principal": principal, "detalle": det})
    return out


# -- activacion por descripcion (no por nombre), deterministica y $0
_SKILL_STOP = set("""
para pero porque sobre desde donde cuando como cual cuales esta este esto estos estas esas esos
tambien todo toda todos todas hace hacer haga hazlo usar usando quiero necesito favor puedes
cosa cosas tarea tareas skill skills algo nada mucho poco solo cada otro otra otros otras entre
hasta según segun luego antes despues mismo misma tiene tener sera seria with from that this
into your have will using what when which there their them then than also about only just like
make sure please very more most some such each other these those
""".split())


def _skill_tokens(texto):
    t = unicodedata.normalize("NFKD", str(texto or "").lower())
    t = "".join(c for c in t if not unicodedata.combining(c))
    out = set()
    for w in re.findall(r"[a-z0-9]+", t):
        if len(w) < 4 or w.isdigit() or w in _SKILL_STOP:
            continue
        out.add(w[:6])  # raiz corta: «carruseles» y «carrusel» cuentan igual
    return out


def skills_para_texto(texto, maximo=None):
    """Las skills pertinentes para un encargo, elegidas SOLO por su
    descripcion: palabras en comun (raiz de 6 letras) pesadas por lo raras que
    son en el indice. Hace falta un minimo de coincidencias (2 por defecto) y,
    para la 2.a y la 3.a, al menos el 40 % de la puntuacion de la mejor.
    Devuelve [(skill, puntuacion, coincidencias)] ordenado, maximo 3."""
    s = load_settings()
    try:
        maximo = max(0, min(SKILL_MAX_ACTIVAS, int(maximo if maximo is not None
                                                    else s.get("skills_max_activas", SKILL_MAX_ACTIVAS))))
    except (TypeError, ValueError):
        maximo = SKILL_MAX_ACTIVAS
    try:
        minimo = max(1, int(s.get("skills_min_coincidencias", 2)))
    except (TypeError, ValueError):
        minimo = 2
    idx = [x for x in skills_indice()["skills"]]
    if not idx or not maximo:
        return []
    import math
    df = {}
    for sk in idx:
        for t in sk["_tok"]:
            df[t] = df.get(t, 0) + 1
    q = _skill_tokens(texto)
    cand = []
    for sk in idx:
        comun = q & sk["_tok"]
        if len(comun) < minimo:
            continue
        punt = sum(1.0 + math.log(len(idx) / df[t]) for t in comun)
        cand.append((sk, round(punt, 2), sorted(comun)))
    cand.sort(key=lambda c: (-c[1], c[0]["name"].lower()))
    try:
        corte = float(s.get("skills_corte_relativo", 0.4))
    except (TypeError, ValueError):
        corte = 0.4
    if cand:  # las de relleno no entran: hace falta al menos el 40 % de la mejor
        cand = [c for c in cand if c[1] >= cand[0][1] * corte]
    return cand[:maximo]


def _skill_cuerpo(sk):
    """Relee el SKILL.md al activarla: si cambio desde el indice, se vuelve a
    validar entero (y a escanear secretos) antes de pasarlo al motor."""
    raiz_real = os.path.realpath(SKILLS_DIR)
    it = _skill_leer(sk["origen"], Path(sk["carpeta"]), raiz_real)
    if it["estado"] != "ok":
        return None, "; ".join(it["motivos"])[:200]
    try:
        _fm, cuerpo = skill_partir(Path(it["archivo"]).read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return None, str(e)
    return cuerpo.strip(), None


def skills_bloque_prompt(task):
    """(texto_para_el_principio_del_prompt, registro). El motor recibe la skill
    por el hueco {prompt} de su descriptor (engines.json esquema 2 no tiene un
    hueco propio para skills): es texto al principio del prompt, igual para
    todos los motores."""
    if not isinstance(task, dict) or task.get("ollama_action"):
        return "", None
    reg = task.get("_skills_reg")
    if reg is not None:
        return task.get("_skills_txt", ""), reg
    s = load_settings()
    try:
        tope = max(500, int(s.get("skills_max_caracteres", SKILL_PROMPT_MAX)))
    except (TypeError, ValueError):
        tope = SKILL_PROMPT_MAX
    idx = skills_indice()
    reg = {"mecanismo": "texto al principio del prompt (hueco {prompt} del descriptor del motor)",
           "indice": {"estado": idx["estado"], "cargadas": len(idx["skills"]), "leido_en": idx["at"]},
           "activadas": [], "descartadas": []}
    partes = []
    if task.get("skills") is False:
        reg["desactivadas_por_la_tarea"] = True
    else:
        for sk, punt, comun in asis_skills_cands(task, skills_para_texto(task.get("prompt") or "")):
            cuerpo, err = _skill_cuerpo(sk)
            if cuerpo is None:
                reg["descartadas"].append({"nombre": sk["name"], "motivo": err})
                continue
            recortada = len(cuerpo) > tope
            if recortada:
                cuerpo = cuerpo[:tope].rstrip() + (f"\n[… recortada a {tope} caracteres; la skill completa "
                                                   f"está en {sk['archivo']}]")
            reqs = skill_requisitos(sk)
            faltan = [f"{r['tipo']} {r['nombre']}" for r in reqs if not r["ok"]]
            partes.append(f"--- Skill «{sk['name']}» v{sk['version']} ({sk['origen_txt']}; carpeta "
                          f"{sk['carpeta']}; sus scripts de apoyo están ahí)"
                          + (f" — OJO, falta en este PC: {', '.join(faltan)}" if faltan else "")
                          + f" ---\n{cuerpo}\n--- Fin de la skill «{sk['name']}» ---")
            reg["activadas"].append({"nombre": sk["name"], "version": sk["version"], "origen": sk["origen_txt"],
                                     "carpeta": sk["carpeta"], "puntuacion": punt, "coincidencias": comun,
                                     "caracteres_en_prompt": len(cuerpo), "recortada": recortada,
                                     "requisitos_faltantes": faltan})
    txt = ""
    if partes:
        txt = ("Skills de Growi Bridge para esta tarea (el runner las eligió por su descripción; "
               "síguelas si sirven):\n" + "\n\n".join(partes) + "\n\n")
    # Workshop: la pregunta solo va cuando no se activo ninguna skill y el
    # encargo no es trivial (medido con Hermes 8B: si va siempre, un modelo
    # pequeno la contesta aunque ya tenga la skill o el encargo sea «tres frutas»).
    try:
        min_pal = int(s.get("skills_workshop_min_palabras", 5))
    except (TypeError, ValueError):
        min_pal = 5
    reg["workshop"] = (s.get("skills_workshop", True) is not False and not reg["activadas"]
                       and task.get("skills") is not False
                       and len(_skill_tokens(task.get("prompt") or "")) >= min_pal)
    if reg["workshop"]:
        txt += ("Solo si de verdad no supiste hacer bien esta tarea por falta de una guía (una skill), añade al "
                "final de tu respuesta UNA línea así: SKILL_QUE_FALTA: nombre-corto | para qué serviría, en una "
                "frase. Si pudiste hacerla, no escribas nada de esto. Bridge la guarda como borrador para que el "
                "usuario la revise; no la crees ni la instales tú.\n\n")
    task["_skills_reg"], task["_skills_txt"] = reg, txt
    if task.get("id"):
        _SKILLS_ACT[str(task["id"])] = reg
        while len(_SKILLS_ACT) > 300:
            _SKILLS_ACT.pop(next(iter(_SKILLS_ACT)))
    if reg["activadas"]:
        log(f"skills [{task.get('id')}]: activadas por descripción: "
            + ", ".join(f"{a['nombre']} ({a['puntuacion']}: {', '.join(a['coincidencias'][:6])})"
                        for a in reg["activadas"]))
    return txt, reg


# -- workshop SIEMPRE en modo propose: borrador en skills\_borradores\, nunca activo
_SKILL_FALTA_RE = re.compile(r"^[\s>*_`-]*SKILL_QUE_FALTA:\s*(.+?)\s*$", re.M)


def _skill_slug(txt):
    t = unicodedata.normalize("NFKD", str(txt or "").lower())
    t = "".join(c for c in t if not unicodedata.combining(c))
    return re.sub(r"-+", "-", re.sub(r"[^a-z0-9]+", "-", t)).strip("-")[:48]


def skill_proponer_borrador(nombre, descripcion, tarea=None, motivo="", detalle=""):
    """Escribe un BORRADOR (no activo) y avisa. Nunca instala ni activa nada.
    {"creado": bool, "carpeta"?, "motivo"?}"""
    nombre = _skill_slug(nombre)
    descripcion = " ".join(str(descripcion or "").split())[:300]
    for _t, rx in _SECRETO_RES:
        descripcion = rx.sub(REDACTADO, descripcion)
    if not nombre or len(descripcion.split()) < 4:
        return {"creado": False, "motivo": "la propuesta no trae nombre o una descripción de al menos 4 palabras"}
    if any(x["name"].lower() == nombre for x in skills_indice()["skills"]):
        return {"creado": False, "motivo": f"ya hay una skill activa «{nombre}»"}
    for b in skills_borradores():
        if b["name"].lower() == nombre and (b.get("meta_borrador") or {}).get("estado", "pendiente") == "pendiente":
            return {"creado": False, "motivo": f"ya hay un borrador pendiente «{nombre}»", "carpeta": b["carpeta"]}
    base = SKILLS_DIR / SKILLS_BORRADORES
    d = base / f"{nombre}-{datetime.now().strftime('%Y%m%d-%H%M%S')}"
    if d.exists():
        return {"creado": False, "motivo": "ya existe esa carpeta de borrador"}
    d.mkdir(parents=True)
    ahora = _now_iso()
    (d / "SKILL.md").write_text(
        "---\n"
        f"name: {nombre}\n"
        f"description: {json.dumps(descripcion, ensure_ascii=False)}\n"
        "version: 0.0.1\n"
        "requires:\n  env: []\n  bins: []\n"
        "borrador: true\n"
        "---\n\n"
        f"# {nombre} (BORRADOR: no está activo)\n\n"
        f"Lo propuso el runner de Growi Bridge el {ahora[:16].replace('T', ' ')}"
        + (f" en la tarea `{tarea}`" if tarea else "") + (f" ({motivo})" if motivo else "") + ".\n\n"
        "Este borrador no se carga ni se activa. Escribe aquí cómo se hace la tarea (pasos, comandos, "
        "qué comprobar) y, cuando esté bien, apruébalo en la app: Skills, Borradores, «Aprobar».\n"
        + (f"\n## Lo que dijo el motor\n\n{detalle.strip()[:1500]}\n" if detalle.strip() else ""),
        encoding="utf-8")
    meta = {"nombre": nombre, "descripcion": descripcion, "tarea": tarea, "motivo": motivo, "creado": ahora,
            "estado": "pendiente", "activo": False}
    (d / "BORRADOR.json").write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        with open(OUTBOX / "skills-borradores.jsonl", "a", encoding="utf-8") as fh:
            fh.write(json.dumps(dict(meta, evento="propuesto", carpeta=str(d)), ensure_ascii=False) + "\n")
    except OSError:
        pass
    log(f"skills: workshop: borrador «{nombre}» propuesto en {d} (NO activo; lo aprueba el usuario)"
        + (f" [tarea {tarea}]" if tarea else ""))
    try:
        toast(f"Growi propone la skill {nombre}", ("page", "skills"))
    except Exception:
        pass
    try:
        _SKX["borradores"] = skills_borradores()
        _ui_call(_skb_render)
    except Exception:
        pass
    return {"creado": True, "carpeta": str(d), "nombre": nombre}


def skills_workshop_de_resultado(result):
    """Si el motor dijo SKILL_QUE_FALTA, se propone el borrador (nunca se activa)."""
    if not isinstance(result, dict) or result.get("skill_propuesta") is not None:
        return None
    m = _SKILL_FALTA_RE.search(str(result.get("result") or ""))
    if not m:
        return None
    reg = _SKILLS_ACT.get(str(result.get("id"))) or {}
    if reg.get("activadas") or not reg.get("workshop"):
        # No se le pregunto (ya tenia skills o el encargo era corto): no cuenta.
        result["skill_propuesta"] = {"creado": False, "motivo": "el motor escribió SKILL_QUE_FALTA sin que se le "
                                     "preguntara (ya tenía skills activadas o el encargo era corto): se ignora"}
        return None
    nom, _, desc = m.group(1).partition("|")
    r = skill_proponer_borrador(nom, desc, tarea=result.get("id"),
                                motivo="el motor dijo que le faltaba una skill", detalle=m.group(0))
    result["skill_propuesta"] = r
    return r


def skill_aprobar_borrador(carpeta):
    """Leandro aprueba un borrador desde la app: se valida y se COPIA a
    skills\\<nombre>\\ (el borrador queda marcado «aprobado»; no se borra nada)."""
    d = Path(carpeta)
    base = SKILLS_DIR / SKILLS_BORRADORES
    if not _skill_dentro(d, os.path.realpath(base)) or _skill_es_enlace(d):
        return False, "esa carpeta no es un borrador de skills\\_borradores"
    it = _skill_leer("propia", d, os.path.realpath(SKILLS_DIR), borrador=True)
    if it["estado"] != "ok":
        return False, "no pasa la validación: " + "; ".join(it["motivos"])
    destino = SKILLS_DIR / _skill_slug(it["name"])
    if destino.exists():
        return False, f"ya hay una carpeta {destino}: cámbiale el nombre al borrador"
    shutil.copytree(d, destino, ignore=shutil.ignore_patterns("BORRADOR.json"))
    sk = destino / "SKILL.md"
    txt = sk.read_text(encoding="utf-8")
    fm, cuerpo = skill_partir(txt)
    fm = "\n".join(x for x in fm.split("\n") if not re.match(r"^borrador\s*:", x))
    sk.write_text(f"---\n{fm}\n---\n{cuerpo}", encoding="utf-8")
    mb = d / "BORRADOR.json"
    try:
        meta = json.loads(mb.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        meta = {}
    meta.update(estado="aprobado", aprobado_en=_now_iso(), copiado_a=str(destino))
    mb.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        with open(OUTBOX / "skills-borradores.jsonl", "a", encoding="utf-8") as fh:
            fh.write(json.dumps(dict(meta, evento="aprobado", carpeta=str(d)), ensure_ascii=False) + "\n")
    except OSError:
        pass
    log(f"skills: borrador {d.name} aprobado por el usuario: copiado a {destino}")
    skills_indexar("borrador aprobado")
    return True, str(destino)


def skills_validar_todo():
    """«Validar skills»: recorre skills\\ entera (borradores incluidos) y dice
    cuales pasan y cuales no, con el motivo exacto. Lo deja tambien en
    share\\outbox\\skills-validacion.json."""
    idx = skills_indexar("validar skills")
    filas = []
    for x in idx["skills"]:
        filas.append({"skill": x["name"], "ruta": x["rel"], "origen": x["origen_txt"], "pasa": True,
                      "motivo": "; ".join(x["avisos"]) or "frontmatter válido, sin secretos"})
    for x in idx["rechazadas"]:
        tapada = x.get("estado") == "tapada"  # valida, pero manda otra del mismo nombre
        filas.append({"skill": x.get("name"), "ruta": x.get("rel"), "origen": x.get("origen_txt"),
                      "pasa": tapada, "estado": x.get("estado"),
                      "motivo": ("válida, pero no se carga: " if tapada else "") + "; ".join(x.get("motivos") or []),
                      "evidencia": [f"{s['archivo']} línea {s['linea']}: {s['evidencia']}"
                                    for s in (x.get("secretos") or [])]})
    for x in idx["borradores"]:
        filas.append({"skill": x["name"], "ruta": x["rel"], "origen": "borrador (no se carga)",
                      "pasa": x["estado"] == "ok", "estado": x["estado"],
                      "motivo": "; ".join(x["motivos"]) or "borrador válido (no se carga hasta que lo apruebes)"})
    rep = {"at": _now_iso(), "carpeta": str(SKILLS_DIR), "estado_indice": idx["estado"],
           "error": idx.get("error"), "avisos": idx["avisos"],
           "pasan": sum(1 for f in filas if f["pasa"]), "no_pasan": sum(1 for f in filas if not f["pasa"]),
           "filas": filas}
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        (OUTBOX / "skills-validacion.json").write_text(json.dumps(rep, ensure_ascii=False, indent=2),
                                                       encoding="utf-8")
    except OSError:
        pass
    return rep


def skills_resumen():
    """Para el panel del gateway (/gateway/estado)."""
    idx = _SKX
    return {"estado": idx["estado"], "carpeta": str(SKILLS_DIR), "cargadas": [x["name"] for x in idx["skills"]],
            "no_cargadas": len(idx["rechazadas"]),
            "borradores_pendientes": sum(1 for b in idx["borradores"]
                                         if (b.get("meta_borrador") or {}).get("estado", "pendiente") == "pendiente"),
            "leido_en": idx["at"]}


PRUEBA_SECRETO_FALSO = "sk-ant-falso123"  # clave FALSA de la autoprueba: no es de nada


def _cli_probar_skills():
    """--probar-skills: autoprueba en una carpeta temporal propia (nunca la
    skills\\ real): skill valida, rota (sin description), con el secreto falso
    'sk-ant-falso123', con un programa que no existe y el workshop. Dice PASA /
    FALLA por punto y comprueba que el secreto no sale en ninguna parte."""
    import tempfile
    global SKILLS_DIR, OUTBOX
    viejo = (SKILLS_DIR, OUTBOX, dict(_SKX), dict(_SKILLS_ACT))
    fallos, L = 0, []

    def ok(cond, txt):
        nonlocal fallos
        fallos += 0 if cond else 1
        L.append(f"{'PASA ' if cond else 'FALLA'}  {txt}")

    with tempfile.TemporaryDirectory(prefix="growi-skills-prueba-") as tmp:
        SKILLS_DIR, OUTBOX = Path(tmp) / "skills", Path(tmp) / "outbox"

        def w(rel, txt):
            p = SKILLS_DIR / rel / "SKILL.md"
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(txt, encoding="utf-8")

        w("prueba-acuarela", "---\nname: prueba-acuarela\ndescription: \"Pintar acuarelas digitales de "
                             "guacamayas con pinceles húmedos y una paleta tropical.\"\nversion: 1.0.0\n"
                             "requires:\n  env: []\n  bins: [python]\n---\nMARCA-ACUARELA\n")
        w("rota", "---\nname: rota\nversion: 1.0.0\n---\nsin description\n")
        w("con-secreto", "---\nname: con-secreto\ndescription: \"Skill de prueba con un secreto literal pegado.\"\n"
                         f"version: 1.0.0\n---\nANTHROPIC_API_KEY={PRUEBA_SECRETO_FALSO}\n")
        w("sin-programa", "---\nname: sin-programa\ndescription: \"Renderizar maquetas con un programa que no "
                          "existe.\"\nversion: 1.0.0\nrequires:\n  bins: [programa-que-no-existe-xyz]\n---\nx\n")
        try:
            idx = skills_indexar("autoprueba")
            nombres = [x["name"] for x in idx["skills"]]
            mal = {x.get("name"): x for x in idx["rechazadas"]}
            ok("prueba-acuarela" in nombres, "(b) la skill válida está en el índice")
            pa = next((x for x in idx["skills"] if x["name"] == "prueba-acuarela"), None)
            reqs = skill_requisitos(pa) if pa else []
            ok(bool(reqs) and all(r["ok"] for r in reqs), "(b) sus requisitos se cumplen (verde)")
            ok("rota" in mal and "falta «description»" in "; ".join(mal["rota"]["motivos"]),
               "(c) la skill sin description se reporta: " + "; ".join((mal.get("rota") or {}).get("motivos") or []))
            ok(len(nombres) >= 2, "(c) las demás siguen cargando")
            cs = mal.get("con-secreto") or {}
            ev = " | ".join(s["evidencia"] for s in cs.get("secretos") or [])
            ok(cs.get("estado") == "sospechosa" and "con-secreto" not in nombres,
               "(d) la del secreto 'sk-ant-falso123' es sospechosa y no se carga")
            ok(REDACTADO in ev and PRUEBA_SECRETO_FALSO not in ev, f"(d) evidencia redactada: {ev}")
            sp = next((x for x in idx["skills"] if x["name"] == "sin-programa"), None)
            r2 = skill_requisitos(sp) if sp else []
            ok(any(not r["ok"] and r["nombre"] == "programa-que-no-existe-xyz" for r in r2),
               "(f) el programa que no existe sale como faltante")
            t1 = {"id": "autoprueba-e1", "prompt": "Pinta una acuarela digital de una guacamaya con pinceles "
                                                   "húmedos y una paleta tropical."}
            t2 = {"id": "autoprueba-e2", "prompt": "Escribe tres frutas, una por linea."}
            txt1, reg1 = skills_bloque_prompt(t1)
            _txt2, reg2 = skills_bloque_prompt(t2)
            ok([a["nombre"] for a in reg1["activadas"]] == ["prueba-acuarela"] and "MARCA-ACUARELA" in txt1,
               "(e) la tarea de acuarelas activa la skill y su cuerpo va al prompt")
            ok(reg2["activadas"] == [], "(e) la tarea de las frutas no activa ninguna")
            res = {"id": "autoprueba-g1", "result": "SKILL_QUE_FALTA: render-ceramica | Renderizar piezas de "
                                                   "ceramica 3D con esmaltes realistas"}
            _SKILLS_ACT["autoprueba-g1"] = {"activadas": [], "workshop": True}
            skills_workshop_de_resultado(res)
            borr = list((SKILLS_DIR / SKILLS_BORRADORES).glob("render-ceramica-*/SKILL.md"))
            ok(bool(borr) and (res.get("skill_propuesta") or {}).get("creado"),
               "(g) el workshop deja un borrador en skills/_borradores/")
            idx = skills_indexar("autoprueba tras el borrador")
            _t, reg3 = skills_bloque_prompt({"id": "autoprueba-g2", "prompt": "Renderizar piezas de ceramica 3D "
                                                                             "con esmaltes realistas."})
            ok("render-ceramica" not in [x["name"] for x in idx["skills"]] and not reg3["activadas"],
               "(g) el borrador NO se activa solo")
            salida = ev + json.dumps({k: v for k, v in idx.items() if k != "lock"}, default=str, ensure_ascii=False)
            ok(PRUEBA_SECRETO_FALSO not in salida, "(d) el secreto falso no aparece en el índice ni en la evidencia")
        finally:
            SKILLS_DIR, OUTBOX = viejo[0], viejo[1]
            _SKX.clear()
            _SKX.update(viejo[2])
            _SKILLS_ACT.clear()
            _SKILLS_ACT.update(viejo[3])
    print("\n".join(L))
    print(f"Autoprueba de skills: {'OK' if not fallos else f'{fallos} FALLO(S)'} "
          "(carpeta temporal propia; la skills\\ real no se tocó)")
    return 0 if not fallos else 1


# -- siembra de las skills curadas (t-skills-semilla, 0.3.0). Growi las
# redacta en la VM desde el trabajo real y las deja en
# share\inbox\skills-semilla\<nombre>\; aqui solo se RECIBEN, se VALIDAN (el
# mismo escaneo que el indice) y se INSTALAN en skills\<nombre>\ (propia: manda
# sobre _equipo e _incluidas). Nada se descarga y nada se escribe de la nada:
# la que no llego queda FALTA con quien la aporta.
SKILLS_SEMILLA_ESPERADAS = ("blender", "tripo", "canva", "meta-ads", "documentos-humanos", "aqualine",
                            "summit-maker")
SKILLS_RESPALDOS = "_respaldos"  # skills\_respaldos\<nombre>.bak-<fecha>\: empieza por _, nunca se carga
_SKILL_CMD_RE = re.compile(r"(?:\bpython3?(?:\.exe)?|--python|\bbash|\bsh|-File)\s+[\"']?"
                           r"([^\s\"'`|;<>]+\.(?:py|sh|ps1|bat|cmd))\b", re.I)
_SKILL_SUBDIR_RE = re.compile(r"(?<![\w/\\~.:-])((?:bin|scripts|references|templates|assets)/[\w./-]+\.\w+)")
_SKILL_ABS_RE = re.compile(r"(?:(?<![\w.~-])/|[A-Za-z]:\\|~/)[^\s`'\"|()]*?([\w.-]+\.(?:py|sh|ps1|bat|cmd))\b")


def skill_scripts_citados(texto, carpeta):
    """(faltan, externas) de los archivos de apoyo que cita el SKILL.md con
    ruta relativa (en un comando python/bash o bajo bin/, references/...).
    Si el mismo archivo se cita tambien con ruta absoluta (de la VM o de otra
    carpeta del PC), es una referencia externa: no viaja con la skill."""
    absolutos = {m.group(1).lower() for m in _SKILL_ABS_RE.finditer(texto)}
    rel = []
    for rx in (_SKILL_CMD_RE, _SKILL_SUBDIR_RE):
        for m in rx.finditer(texto):
            r = m.group(1).replace("\\", "/")
            if r.startswith(("/", "~")) or re.match(r"^[A-Za-z]:", r) or r in rel:
                continue  # absoluta (de la VM o de otra carpeta) o repetida
            rel.append(r)
    faltan, externas = [], []
    for r in rel:
        p = Path(carpeta) / r.lstrip("./")
        dentro = _skill_dentro(p, os.path.realpath(carpeta))
        if dentro and p.is_file():
            continue
        (externas if Path(r).name.lower() in absolutos else faltan).append(r)
    return faltan, externas


def _skill_huella(d):
    """{ruta relativa: sha256} de los archivos de una carpeta (sin __pycache__)."""
    out = {}
    for base, dirs, files in os.walk(d, followlinks=False):
        dirs[:] = sorted(x for x in dirs if x != "__pycache__")
        for f in sorted(files):
            if f.endswith(".pyc"):
                continue
            fp = os.path.join(base, f)
            out[os.path.relpath(fp, d).replace("\\", "/")] = hashlib.sha256(open(fp, "rb").read()).hexdigest()
    return out


def skills_sembrar(origen=None, en_seco=False):
    """RECIBIR / VALIDAR / INSTALAR cada skill semilla, por separado. Una que
    falla no para a las demas. Devuelve el informe (tambien en
    share\\outbox\\skills-semilla-informe.json)."""
    origen = Path(origen) if origen else INBOX / "skills-semilla"
    fecha = time.strftime("%Y%m%d-%H%M%S")
    llegadas = sorted(e.name for e in os.scandir(origen) if e.is_dir(follow_symlinks=False)
                      and not e.name.startswith((".", "_"))) if origen.is_dir() else []
    nombres = list(SKILLS_SEMILLA_ESPERADAS) + [n for n in llegadas if n not in SKILLS_SEMILLA_ESPERADAS]
    raiz_origen = os.path.realpath(origen) if origen.is_dir() else ""
    filas = []
    for n in nombres:
        f = {"skill": n, "esperada": n in SKILLS_SEMILLA_ESPERADAS, "estado": None,
             "recibir": {}, "validar": {}, "instalar": {}}
        filas.append(f)
        d = origen / n
        # 1. RECIBIR
        if not d.is_dir() or _skill_es_enlace(d) or not (d / "SKILL.md").is_file():
            f["recibir"] = {"ok": False, "detalle": (f"no llegó {d}\\SKILL.md" if d.is_dir() else f"no llegó {d}")
                            + ". La aporta Growi desde la VM: redactarla del trabajo real (MEMORY.md, informes, "
                              "repos) y dejarla en share\\inbox\\skills-semilla\\. Aquí no se escribe."}
            f["estado"] = "FALTA"
            continue
        archivos = sorted(_skill_huella(d))
        f["recibir"] = {"ok": True, "detalle": f"{len(archivos)} archivo(s): " + ", ".join(archivos)}
        # 2. VALIDAR (mismo lector que el indice: frontmatter, 256 KB, secretos, enlaces)
        it = _skill_leer("propia", d, raiz_origen)
        motivos = list(it["motivos"])
        meta = {}
        try:
            meta = yaml_minimo(skill_partir((d / "SKILL.md").read_text(encoding="utf-8"))[0])
        except (OSError, ValueError, UnicodeDecodeError):
            pass
        if it["estado"] == "ok" and "requires" not in meta:
            motivos.append("falta «requires» (aunque sea con env: [] y bins: [])")
        if it["estado"] == "ok" and it["name"] != n:
            motivos.append(f"la carpeta se llama «{n}» y la skill «{it['name']}»: tienen que coincidir")
        try:
            faltan, externas = skill_scripts_citados((d / "SKILL.md").read_text(encoding="utf-8"), d)
        except (OSError, UnicodeDecodeError):
            faltan, externas = [], []
        motivos += [f"cita «{r}» y no está junto a la skill" for r in faltan]
        f["validar"] = {"ok": not motivos, "motivos": motivos, "avisos": it["avisos"],
                        "bytes_skill_md": it.get("bytes"), "version": it.get("version"),
                        "description": it.get("description"), "requires": it.get("requires"),
                        "referencias_externas": externas,
                        "evidencia_secretos": [f"{s['archivo']} línea {s['linea']}: {s['evidencia']}"
                                               for s in it.get("secretos") or []]}
        if motivos:
            f["estado"] = "NO SE INSTALA"
            f["instalar"] = {"ok": False, "detalle": "no pasó la validación: " + "; ".join(motivos)}
            continue
        # 3. INSTALAR en skills\<nombre>\ (propia)
        dest = SKILLS_DIR / n
        hs = _skill_huella(d)
        tapa = [f"skills\\{sub}\\{n}" for _o, sub, _t in SKILL_ORIGENES if sub and (SKILLS_DIR / sub / n).is_dir()]
        ins = {"ok": True, "destino": str(dest), "respaldo": None,
               "precedencia": "propia: manda" + (f" (tapa a {', '.join(tapa)})" if tapa else "")}
        if dest.exists() and _skill_huella(dest) == hs:
            ins.update(accion="ya estaba igual", detalle="ya instalada con el mismo contenido: no se toca")
        elif en_seco:
            ins.update(accion="en seco", detalle="validada; no se copió (--en-seco)"
                       + (" — ya existe otra distinta: se respaldaría" if dest.exists() else ""))
        else:
            try:
                SKILLS_DIR.mkdir(parents=True, exist_ok=True)
                if dest.exists():  # distinta (quizá editada a mano por Leandro): se respalda, no se pisa
                    resp = SKILLS_DIR / SKILLS_RESPALDOS / f"{n}.bak-{fecha}"
                    resp.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(dest), str(resp))
                    ins["respaldo"] = str(resp)
                shutil.copytree(d, dest, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
                igual = _skill_huella(dest) == hs
                rel = _skill_leer("propia", dest, os.path.realpath(SKILLS_DIR))
                ins.update(accion="actualizada" if ins["respaldo"] else "instalada",
                           ok=igual and rel["estado"] == "ok",
                           detalle=("copiada y comprobada (mismo sha256 en los "
                                    f"{len(hs)} archivo(s); se relee válida)" if igual and rel["estado"] == "ok"
                                    else "la copia no coincide o no se relee válida: " + "; ".join(rel["motivos"]))
                           + (f". AVISO: ya había una distinta; la anterior quedó en {ins['respaldo']}"
                              if ins["respaldo"] else ""))
            except OSError as e:
                ins.update(ok=False, accion="error", detalle=f"no se pudo copiar: {e}")
        f["instalar"] = ins
        f["estado"] = ("INSTALADA" if ins["ok"] and ins["accion"] in ("instalada", "actualizada", "ya estaba igual")
                       else "VALIDADA" if ins["ok"] else "ERROR AL INSTALAR")
    if not en_seco:
        skills_indexar("siembra de skills")
    rep = {"at": _now_iso(), "origen": str(origen), "destino": str(SKILLS_DIR), "en_seco": en_seco,
           "resumen": {k: sum(1 for x in filas if x["estado"] == k)
                       for k in ("INSTALADA", "VALIDADA", "FALTA", "NO SE INSTALA", "ERROR AL INSTALAR")},
           "filas": filas}
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        (OUTBOX / "skills-semilla-informe.json").write_text(json.dumps(rep, ensure_ascii=False, indent=2),
                                                           encoding="utf-8")
    except OSError:
        pass
    log(f"skills: siembra desde {origen}: " + ", ".join(f"{x['skill']} {x['estado']}" for x in filas))
    return rep


def _cli_skills(args):
    """--validar-skills | --skills-indice | --skills-activar "texto" (sin ventana)."""
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    op = args[0]
    if op == "--validar-skills":
        rep = skills_validar_todo()
        print(f"Carpeta: {rep['carpeta']} (índice: {rep['estado_indice']})")
        for f in rep["filas"]:
            print(f"{'PASA   ' if f['pasa'] else 'NO PASA'}  {f['skill']}  [{f['origen']}]  {f['ruta']}: {f['motivo']}")
            for ev in f.get("evidencia") or []:
                print(f"         evidencia (redactada): {ev}")
        for a in rep["avisos"]:
            print(f"AVISO    {a}")
        print(f"Pasan {rep['pasan']}, no pasan {rep['no_pasan']}. Informe: {OUTBOX / 'skills-validacion.json'}")
        return 0
    if op == "--skills-indice":
        idx = skills_indexar("consola")
        out = [{"name": x["name"], "description": x["description"], "version": x["version"],
                "origen": x["origen_txt"], "requires": x["requires"], "requisitos_en_vivo": skill_requisitos(x)}
               for x in idx["skills"]]
        print(json.dumps({"estado": idx["estado"], "skills": out,
                          "no_cargadas": [{"ruta": x.get("rel"), "estado": x.get("estado"),
                                           "motivos": x.get("motivos")} for x in idx["rechazadas"]]},
                         ensure_ascii=False, indent=2))
        return 0
    if op == "--probar-skills":
        return _cli_probar_skills()
    if op == "--sembrar-skills":
        resto = [a for a in args[1:] if a != "--en-seco"]
        rep = skills_sembrar(resto[0] if resto else None, en_seco="--en-seco" in args)
        print(f"Origen: {rep['origen']}\nDestino: {rep['destino']}" + ("  (EN SECO: no se copia nada)"
                                                                     if rep["en_seco"] else ""))
        for f in rep["filas"]:
            print(f"\n== {f['skill']}: {f['estado']}")
            for paso in ("recibir", "validar", "instalar"):
                p = f[paso]
                if not p:
                    continue
                det = p.get("detalle") or ("; ".join(p.get("motivos") or []) or "frontmatter válido, sin "
                                           "secretos, ≤ 256 KB, scripts citados presentes")
                print(f"   {paso.upper():9}{'OK ' if p.get('ok') else 'NO '} {det}")
                for x in p.get("referencias_externas") or []:
                    print(f"            referencia externa (no viaja con la skill): {x}")
                for x in p.get("evidencia_secretos") or []:
                    print(f"            evidencia (redactada): {x}")
                if p.get("precedencia"):
                    print(f"            precedencia: {p['precedencia']}")
        print("\nResumen: " + ", ".join(f"{k} {v}" for k, v in rep["resumen"].items())
              + f". Informe: {OUTBOX / 'skills-semilla-informe.json'}")
        return 0 if not rep["resumen"]["NO SE INSTALA"] and not rep["resumen"]["ERROR AL INSTALAR"] else 1
    if op == "--skills-activar":
        texto = " ".join(args[1:])
        sel = skills_para_texto(texto)
        print(f"Encargo: {texto}")
        print("Se activarían: " + (", ".join(f"{sk['name']} ({p}: {', '.join(c)})" for sk, p, c in sel)
                                   if sel else "ninguna"))
        return 0
    return 2


# ---------------------------------------------------------------- updates
UPDATE_FILES = ["growi-bridge.py", "growi.ico", "growi-tray.png", "growi-header.png",
                "growi.png", "instalar-growi-bridge.bat", "iniciar-growi-bridge.bat",
                "probar-growi-bridge.bat", "LEEME-growi-bridge.md", "VERSION",
                "DESIGN.md", "notas-mobbin.md", "models-catalog.json", "README.md",
                "engines.json", "availability.json", "riesgos.json", "PROTOCOLO-PRUEBA-CORTE.md",
                "politicas.ejemplo.json"]


def _update_repo():
    """Repositorio de donde se baja la app. Por defecto el publico de Growi
    Bridge; quien use un fork lo cambia en settings.json (update_repo)."""
    repo = str(load_settings().get("update_repo") or "").strip()
    return repo if re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo) else GITHUB_REPO


def _version_tuple(v):
    """Tupla comparable de una version. Soporta pre-release: 0.1.0-alpha
    -> (0, 1, 0, 0); 0.1.0 -> (0, 1, 0, 3); 2.3 -> (2, 3, 0, 3)."""
    s = str(v).strip().lstrip("v")
    pre = 3
    if "-" in s:
        s, tag = s.split("-", 1)
        pre = {"alpha": 0, "beta": 1, "rc": 2}.get(tag.strip().lower(), 0)
    parts = []
    for p in s.split("."):
        try:
            parts.append(int(p))
        except ValueError:
            parts.append(0)
    while len(parts) < 3:
        parts.append(0)
    parts.append(pre)
    return tuple(parts)


def check_update_available():
    """Compara con VERSION en GitHub (raw). Devuelve la version nueva o ''.
    Migracion de numeracion: la app paso de la linea 2.x a la 0.x (Alpha);
    cualquier 0.x se considera mas nueva que cualquier 2.x."""
    url = f"https://raw.githubusercontent.com/{_update_repo()}/main/VERSION"
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "GrowiBridge"})
        with urllib.request.urlopen(req, timeout=15) as r:
            remote = r.read().decode("utf-8", errors="replace").strip()
        if not remote:
            return ""
        if VERSION.startswith("2.") and remote.startswith("0."):
            return remote
        if _version_tuple(remote) > _version_tuple(VERSION):
            return remote
    except Exception as e:
        log(f"actualizaciones: no se pudo comprobar ({type(e).__name__})")
    return ""


def download_update(version):
    """Baja TODOS los archivos de la nueva version y deja el actualizador
    listo (actualizar.bat mueve cada .new a su sitio y relanza la app).
    True si quedo todo, False si algo fallo. Los archivos opcionales
    (catalogo de modelos, README) se saltan si el repo aun no los tiene."""
    optional = {"models-catalog.json", "README.md", "riesgos.json", "PROTOCOLO-PRUEBA-CORTE.md",
                "politicas.ejemplo.json"}
    got = []
    for name in UPDATE_FILES:
        url = f"https://raw.githubusercontent.com/{_update_repo()}/main/{name}"
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "GrowiBridge"})
            with urllib.request.urlopen(req, timeout=60) as r:
                data = r.read()
            if name == "growi-bridge.py" and (b"Growi Bridge" not in data[:2000]
                                             or len(data) < 10000):
                log("actualizaciones: growi-bridge.py descargado invalido")
                return False
            (APP_DIR / (name + ".new")).write_bytes(data)
            got.append(name)
        except Exception as e:
            if name in optional:
                log(f"actualizaciones: {name} no está en el repo, se deja el actual")
                continue
            log(f"actualizaciones: fallo al bajar {name} ({e})")
            return False
    lines = ["@echo off", "timeout /t 2 /nobreak >nul"]
    for name in got:
        lines.append(f'move /y "{name}.new" "{name}"')
    lines += ["start /b pythonw growi-bridge.py", 'del "%~f0"']
    (APP_DIR / "actualizar.bat").write_text("\r\n".join(lines) + "\r\n",
                                            encoding="utf-8")
    return True


def _do_auto_update():
    """Auto-update (sin preguntar): lo dispara _tick cuando el hilo de
    fondo dejo una version lista en state['auto_update_ready']."""
    version = state.get("auto_update_ready", "")
    state["auto_update_ready"] = ""
    if not version or not load_settings().get("auto_update"):
        return
    if not download_update(version):
        return
    log(f"actualizaciones: auto-update a v{version}, reiniciando...")
    try:
        subprocess.Popen(["cmd", "/c", "actualizar.bat"], cwd=str(APP_DIR))
    except Exception:
        return
    quit_app()


def _auto_update_loop():
    """Hilo de fondo: cada 6 h comprueba si hay version nueva. Si la
    actualizacion automatica esta activada, deja la version lista para que
    _tick la instale sola; si no, solo avisa en la ventana."""
    time.sleep(60)
    while True:
        try:
            if load_settings().get("auto_update"):
                remote = check_update_available()
                if remote:
                    state["update_available"] = remote
                    state["update_checked"] = True
                    state["auto_update_ready"] = remote
                    log(f"actualizaciones: v{remote} lista, auto-update en curso")
        except Exception:
            pass
        time.sleep(6 * 3600)

# ---------------------------------------------------------------- puente (HTTP)
def box_dir(box):
    d = SHARE / box
    d.mkdir(parents=True, exist_ok=True)
    return d


def safe_name(name):
    if not name:
        return None
    parts = [p for p in name.replace("\\", "/").split("/") if p not in ("", ".")]
    if not parts or any(p == ".." for p in parts):
        return None
    return "/".join(parts)


class BridgeHandler(BaseHTTPRequestHandler):
    """Plano de control del gateway (puente VM-PC + /gateway/*). Escucha solo
    en 127.0.0.1 (y, si hay tunel, en la IP de Tailscale de este PC; nunca en
    0.0.0.0). Venir de 127.0.0.1 NO da confianza (CVE-2026-25253): cada
    peticion lleva el token, y una que trae Origin, Sec-Fetch-Site de otro
    sitio, un Host ajeno o pide WebSocket se rechaza aunque traiga el token."""
    server_version = "GrowiBridge/2.0"
    SECRET = ""
    BOXES = ("inbox", "outbox")

    def _auth(self):
        got = self.headers.get("X-Shared-Secret") or ""
        bearer = self.headers.get("Authorization") or ""
        if not got and bearer.lower().startswith("bearer "):
            got = bearer[7:].strip()
        return bool(self.SECRET) and hmac.compare_digest(got.encode("utf-8"), self.SECRET.encode("utf-8"))

    def _guard(self):
        """None si pasa; si no, (codigo, motivo). El orden importa: Origin y
        Host se miran ANTES que el token (una web ajena nunca entra)."""
        h = self.headers
        if (h.get("Upgrade") or "").strip():
            return 400, "el plano de control no acepta WebSocket"
        origin = (h.get("Origin") or "").strip()
        if origin and origin not in gateway_origenes():
            return 403, f"origen no permitido ({origin[:80]})"
        if (h.get("Sec-Fetch-Site") or "").strip().lower() in ("cross-site", "same-site"):
            return 403, "petición de otra web (Sec-Fetch-Site)"
        host = (h.get("Host") or "").strip().lower()
        if host and not gateway_host_ok(host):
            return 403, f"host no permitido ({host[:80]})"
        if not self._auth():
            return 401, "sin token o token incorrecto"
        return None

    def _rechazar(self):
        bad = self._guard()
        if bad is None:
            return False
        gateway_rechazo(self.client_address[0] if self.client_address else "?", self.command, self.path, bad[1])
        self._json({"error": "unauthorized" if bad[0] == 401 else "forbidden", "motivo": bad[1]}, bad[0])
        return True

    def _json(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _box(self, qs):
        box = (qs.get("box") or [""])[0]
        return box if box in self.BOXES else None

    def do_OPTIONS(self):
        # Preflight CORS de una web: nunca se contesta con permisos.
        self._rechazar() or self._json({"error": "forbidden", "motivo": "sin CORS"}, 403)

    def do_GET(self):
        if self._rechazar():
            return
        u = urlparse(self.path)
        qs = parse_qs(u.query)
        if u.path == "/ping":
            return self._json({"ok": True})
        if u.path == "/gateway/salud":
            return self._json({"ok": True, "pid": os.getpid(), "puerto": BRIDGE_PORT, "carril": LANE})
        if u.path == "/gateway/estado":
            try:
                return self._json(gateway_estado())
            except Exception as e:
                log(f"gateway: /gateway/estado fallo ({type(e).__name__}: {e})")
                return self._json({"error": f"{type(e).__name__}: {e}"}, 500)
        if u.path == "/list":
            box = self._box(qs)
            if not box:
                return self._json({"error": "box invalido"}, 400)
            files = []
            d = box_dir(box)
            for root, _dirs, fnames in os.walk(d):
                for fn in fnames:
                    p = os.path.join(root, fn)
                    rel = os.path.relpath(p, d).replace(os.sep, "/")
                    st = os.stat(p)
                    files.append({"name": rel, "size": st.st_size, "mtime": st.st_mtime})
            files.sort(key=lambda x: x["name"])
            return self._json({"files": files})
        if u.path == "/get":
            box = self._box(qs)
            name = safe_name((qs.get("name") or [""])[0])
            if not box or not name:
                return self._json({"error": "parametros invalidos"}, 400)
            p = os.path.join(box_dir(box), *name.split("/"))
            if not os.path.isfile(p):
                return self._json({"error": "no existe"}, 404)
            with open(p, "rb") as f:
                data = f.read()
            note_transfer("up", f"{box}/{name}", len(data))
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return
        return self._json({"error": "no encontrado"}, 404)

    def do_POST(self):
        if self._rechazar():
            return
        u = urlparse(self.path)
        qs = parse_qs(u.query)
        if u.path == "/put":
            box = self._box(qs)
            name = safe_name((qs.get("name") or [""])[0])
            if not box or not name:
                return self._json({"error": "parametros invalidos"}, 400)
            length = int(self.headers.get("Content-Length", 0) or 0)
            data = self.rfile.read(length) if length > 0 else b""
            p = os.path.join(box_dir(box), *name.split("/"))
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f:
                f.write(data)
            note_transfer("down", f"{box}/{name}", len(data))
            return self._json({"ok": True, "name": name, "size": len(data)})
        return self._json({"error": "no encontrado"}, 404)

    def log_message(self, *a):
        pass


# ---------------------------------------------------------------- modelos
# Growi Bridge junta lo que aporta Ollama (modelos que viven y corren en el
# PC) con la forma de trabajar de un agente estilo OpenClaw (un solo
# asistente que usa herramientas, tiene habilidades, te habla por varios
# canales y cumple tus reglas). Todo lo que hace la pestana Modelos lo puede
# hacer tambien el asistente desde la VM con tasks "ollama_action"
# (pull / rm / list): la ventana y el asistente mueven los mismos botones.
CATALOG_FILE = APP_DIR / "models-catalog.json"
PC_SPECS_FILE = APP_DIR / "pc-specs.json"
RULES_FILE = APP_DIR / "rules.json"
MODEL_ACTIONS = ("pull", "rm", "list")
# Misma regla que los ids del runner + "/" y ":" (los nombres de Ollama los
# llevan). Debe empezar por letra o numero: nada de "-flag" ni rutas.
MODEL_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._/:-]{0,199}")
DEFAULT_RULES = ["Pregúntame antes de gastar dinero",
                 "No borres nada sin pedirme permiso"]
MODEL_JOBS = {}  # id del task -> {"action", "model", "line", "status"}
_NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)
_ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]")
# Lanzamiento oculto (t-checkpoint-ronda-030 §6): ningun motor abre ni hace
# parpadear una consola. CREATE_NO_WINDOW (0x08000000) + STARTUPINFO con
# wShowWindow=SW_HIDE. Si un lanzamiento falla, el error va al resultado y al
# registro; nunca se reintenta con ventana visible.
SW_HIDE = 0
OCULTO_TXT = "CREATE_NO_WINDOW (0x08000000) + STARTUPINFO SW_HIDE"


def _oculto(extra_flags=0):
    """kwargs de subprocess para lanzar sin ventana de consola."""
    kw = {"creationflags": _NO_WINDOW | extra_flags}
    if os.name == "nt":
        si = subprocess.STARTUPINFO()
        si.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        si.wShowWindow = SW_HIDE
        kw["startupinfo"] = si
    return kw


def _lanzamiento(proc):
    """Lo que el resultado guarda del lanzamiento (evidencia del flag)."""
    return {"oculto": True, "creationflags": hex(_NO_WINDOW), "sw_hide": os.name == "nt",
            "pid": proc.pid, "como": OCULTO_TXT}


def valid_model_name(name):
    """Solo letras, numeros, - _ . / : (sin URLs, sin '..', sin flags)."""
    return (isinstance(name, str) and bool(MODEL_NAME_RE.fullmatch(name))
            and ".." not in name and "//" not in name)


def ollama_exe():
    exe = shutil.which("ollama")
    if exe:
        return exe
    cand = Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "Ollama" / "ollama.exe"
    return str(cand) if cand.is_file() else None


def default_ollama_model():
    """El modelo local elegido en la pestana Modelos (settings.json)."""
    m = str(load_settings().get("ollama_model") or "").strip()
    return m if valid_model_name(m) else ""


def _same_model(a, b):
    """'mistral' y 'mistral:latest' son el mismo modelo para Ollama."""
    def _norm(n):
        n = (n or "").strip().lower()
        last = n.rsplit("/", 1)[-1]
        return n if ":" in last else n + ":latest"
    return _norm(a) == _norm(b)


def _size_to_gb(text):
    m = re.match(r"\s*([\d.]+)\s*(KB|MB|GB|TB)", text or "", re.I)
    if not m:
        return None
    mult = {"KB": 1e-6, "MB": 1e-3, "GB": 1.0, "TB": 1000.0}[m.group(2).upper()]
    return round(float(m.group(1)) * mult, 2)


def _ago_es(text):
    """'5 days ago' -> 'hace 5 días' (la salida de ollama list viene en inglés)."""
    t = (text or "").strip()
    m = re.match(r"(\d+|an?|about an?)\s+(second|minute|hour|day|week|month|year)s?\s+ago", t, re.I)
    if not m:
        return t
    n = m.group(1).lower()
    n = "1" if n.startswith(("a", "an", "about")) else n
    unit = {"second": ("segundo", "segundos"), "minute": ("minuto", "minutos"),
            "hour": ("hora", "horas"), "day": ("día", "días"),
            "week": ("semana", "semanas"), "month": ("mes", "meses"),
            "year": ("año", "años")}[m.group(2).lower()]
    return f"hace {n} {unit[0] if n == '1' else unit[1]}"


def parse_ollama_list(text):
    """Convierte la salida de `ollama list` en filas {name, size, size_gb,
    modified}. Ignora la cabecera y cualquier linea rara."""
    out = []
    for line in (text or "").splitlines():
        line = line.strip()
        if not line or line.upper().startswith("NAME"):
            continue
        cols = re.split(r"\s{2,}", line)
        if not cols or not valid_model_name(cols[0]):
            continue
        size = cols[2] if len(cols) > 2 else ""
        out.append({"name": cols[0], "id": cols[1] if len(cols) > 1 else "",
                    "size": size, "size_gb": _size_to_gb(size),
                    "modified": _ago_es(cols[3]) if len(cols) > 3 else ""})
    return out


def _clean_line(raw):
    """Quita colores/cursor y el spinner (⠋⠙⠹…) de la salida de ollama."""
    text = _ANSI_RE.sub("", raw.decode("utf-8", "replace"))
    text = re.sub(r"[⠀-⣿]", "", text).strip()
    # ollama redibuja la misma linea: "pulling manifest  pulling manifest" -> una vez
    return re.sub(r"^(.+?)(?:\s+\1)+$", r"\1", text)


def _run_capture(cmd, timeout_s, cwd=None):
    """Como subprocess.run(capture_output=True) pero con archivos temporales
    en vez de tuberias: si `ollama` arranca su servidor de fondo, ese
    servidor hereda la salida y con tuberias Python esperaria para siempre.
    Devuelve (codigo, stdout, stderr); lanza TimeoutExpired como run()."""
    import tempfile
    with tempfile.TemporaryFile() as out, tempfile.TemporaryFile() as err:
        proc = subprocess.Popen(cmd, stdout=out, stderr=err, stdin=subprocess.DEVNULL,
                                cwd=cwd, **_oculto())
        try:
            rc = proc.wait(timeout=timeout_s)
        except subprocess.TimeoutExpired:
            proc.kill()
            raise
        out.seek(0)
        err.seek(0)
        return (rc, out.read().decode("utf-8", "replace"),
                err.read().decode("utf-8", "replace"))


def run_model_action(action, model=None, timeout_s=3600, job_id=None):
    """Corre `ollama pull|rm|list` (nunca otra cosa, nunca por shell).
    Devuelve (ok, salida, error). El pull va con progreso en MODEL_JOBS y
    en el registro (cada 10 %), y en outbox/runner-results/<id>.progress.json
    para que el asistente lo vea desde la VM."""
    if action not in MODEL_ACTIONS:
        return False, "", f"acción no permitida: {action}"
    if action != "list" and not valid_model_name(model):
        return False, "", ("nombre de modelo no válido (solo letras, números, "
                           "- _ . / :)")
    exe = ollama_exe()
    if not exe:
        return False, "", "Ollama no está instalado en este PC (ollama.com, gratis)"
    cmd = [exe, action] + ([model] if action != "list" else [])
    if action != "pull":
        try:
            rc, stdout, stderr = _run_capture(cmd, timeout_s)
        except subprocess.TimeoutExpired:
            return False, "", f"ollama {action} tardó más de {max(1, timeout_s // 60)} min"
        except Exception as e:
            return False, "", f"{type(e).__name__}: {e}"
        out = _ANSI_RE.sub("", stdout).strip()
        if rc != 0:
            err = [l for l in _ANSI_RE.sub("", stderr).splitlines()
                   if l.strip() and "level=" not in l]
            return False, out, (err[-1].strip() if err else
                                f"ollama salió con código {rc}")
        return True, out, None
    # pull: lee la salida a trozos para mostrar el progreso sin esperar al final.
    key = job_id or model
    job = MODEL_JOBS.setdefault(key, {})
    job.update(action="pull", model=model, line="Preparando…", status="running")
    progress_file = RESULTS / f"{key}.progress.json"
    seen = []
    last = {"bucket": None, "write": 0.0}

    try:
        # Con tuberia para ver el progreso al momento; se espera al proceso
        # (proc.wait), no a la tuberia, asi que no se cuelga aunque ollama
        # arranque su servidor de fondo.
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                stdin=subprocess.DEVNULL, **_oculto())
        _track_launch(proc, f"Modelos: instalando {model}")
    except Exception as e:
        job["status"] = "error"
        return False, "", f"{type(e).__name__}: {e}"

    def _reader():
        buf = b""
        while True:
            try:
                chunk = proc.stdout.read1(4096)
            except Exception:
                break
            if not chunk:
                break
            buf += chunk
            parts = re.split(rb"[\r\n]", buf)
            buf = parts[-1]
            for raw in parts[:-1]:
                t = _clean_line(raw)
                if not t or "level=" in t:
                    continue
                job["line"] = t
                pct = re.search(r"(\d{1,3})%", t)
                if pct:
                    bucket = (t.split(":")[0], int(pct.group(1)) // 10)
                    if bucket != last["bucket"]:
                        last["bucket"] = bucket
                        log(f"modelos: descargando {model}: {pct.group(1)}%")
                elif not seen or seen[-1] != t:
                    seen.append(t)
                now = time.time()
                if now - last["write"] >= 5:
                    last["write"] = now
                    try:
                        RESULTS.mkdir(parents=True, exist_ok=True)
                        progress_file.write_text(json.dumps(
                            {"id": key, "model": model, "line": t, "at": _now_iso()},
                            ensure_ascii=False), encoding="utf-8")
                    except OSError:
                        pass
        t = _clean_line(buf)
        if t:
            job["line"] = t
            seen.append(t)

    th = threading.Thread(target=_reader, daemon=True)
    th.start()
    try:
        rc = proc.wait(timeout=timeout_s)
    except subprocess.TimeoutExpired:
        proc.kill()
        th.join(5)
        job["status"] = "error"
        _rm_quiet(progress_file)
        return False, "\n".join(seen[-20:]), f"timeout de {max(1, timeout_s // 60)} min"
    th.join(10)
    _rm_quiet(progress_file)
    out = "\n".join(seen[-20:])
    job["status"] = "ok" if rc == 0 else "error"
    if rc != 0:
        return False, out, (seen[-1] if seen else f"ollama salió con código {rc}")
    return True, out, None


def _rm_quiet(path):
    try:
        Path(path).unlink()
    except OSError:
        pass


def load_catalog():
    """Libreria curada de modelos (models-catalog.json junto al programa).
    Se amplia editando el archivo, sin tocar codigo. Los campos del semaforo
    de VRAM los rellena models_catalog_to_json()."""
    out = []
    for m in models_catalog_to_json().get("models", []):
        try:
            size = float(m.get("size_gb") or 0)
            e = {"id": m["id"], "name": str(m.get("name") or m["id"]),
                 "size_gb": size,
                 "vram_gb": float(m.get("vram_gb") or round(size * 1.15, 1)),
                 "use": str(m.get("use") or ""),
                 "kind": str(m.get("kind") or "")}
            # Semaforo de VRAM por piezas (t-semaforo-vram-v2): arquitectura y
            # pesos medidos/estimados. Sin ellos el modelo sale en gris.
            for k in VRAM_CAMPOS:
                if m.get(k) is not None:
                    e[k] = m[k]
            # El GGUF fijado (repo, revision, archivo, bytes, sha256) que usa
            # el librero (descargador GGUF) para bajarlo y comprobarlo.
            if isinstance(m.get("gguf"), dict):
                e["gguf"] = m["gguf"]
            out.append(e)
        except (AttributeError, TypeError, ValueError):
            continue
    return out


def models_catalog_to_json(path=None):
    """Funcion principal del catalogo (t-semaforo-vram-v2): lee
    models-catalog.json y devuelve el diccionario {"models": [...], ...} con
    cada modelo actualizado con los campos nuevos y sus valores calculados:
    weights_vram_mib, kv_mib_medido, kv_mib_8k_medido, buffers_mib, mmproj_mib
    y vram_gb (una subfuncion por campo, abajo). Lo medido en el archivo manda;
    lo que falta se estima y se marca en «<campo>_fuente» (calculado). No
    escribe nada: el archivo no se toca. Sin archivo o roto -> {"models": []}."""
    try:
        data = json.loads(Path(path or CATALOG_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {"models": []}
    if isinstance(data, list):
        data = {"models": data}
    if not isinstance(data, dict):
        return {"models": []}
    out = dict(data)
    out["models"] = []
    for m in data.get("models") if isinstance(data.get("models"), list) else []:
        try:
            if not valid_model_name(m.get("id")):
                continue
            e = dict(m)
            for campo, fn in (("weights_vram_mib", weights_vram_mib),
                              ("kv_mib_medido", kv_mib_medido),
                              ("kv_mib_8k_medido", kv_mib_8k_medido),
                              ("buffers_mib", buffers_mib),
                              ("mmproj_mib", mmproj_mib)):
                val = fn(m)
                if m.get(campo) is None and val not in (None, {}):
                    e.setdefault(f"{campo}_fuente", "calculado por models_catalog_to_json")
                e[campo] = val
            e["vram_gb"] = vram_gb(e)
            out["models"].append(e)
        except (AttributeError, TypeError, ValueError):
            continue
    return out


# --- semaforo de VRAM por piezas (t-semaforo-vram-v2)
# VRAM = pesos en VRAM + cache KV(contexto) + buffers de computo + mmproj
# (+ reserva del SO). Sustituye al "tamano x 1,15" de la 0.2.0, que solo
# acertaba con Hermes 3 8B a 8k. Medido en este PC (RTX 3060 Laptop, 6144 MiB,
# llama-server build 11873): Hermes 3 8B a 8k = 4403 + 1024 + 124 = 5551 MiB.
# KV por token = 2 (K y V) x capas x cabezas KV x dim de cabeza x bytes del tipo.
# Con -np automatico llama-server abre 4 slots con la cache UNIFICADA
# (kv_unified = true, n_ctx_slot = --ctx-size): la KV es la de --ctx-size una
# vez, no x4, y una sola peticion puede usar todo el contexto. Si algun dia
# se arranca con --no-kv-unified, cada slot tendria --ctx-size / slots.
CTX_PASOS = (4096, 8192, 16384)   # nunca se promete mas de 16k en la pestana
KV_BYTES = {"f16": 2.0, "q8_0": 34 / 32, "q4_0": 18 / 32}
BUFFERS_DEF_MIB = 256             # buffers de computo si no estan medidos
RESERVA_SO_MIB = 0                # la VRAM libre (nvidia-smi) ya la descuenta
CUDA_CONTEXTO_MIB = 122           # medido: lo que suma el contexto CUDA al cargar
VRAM_CAMPOS = ("layers", "kv_heads", "head_dim", "ctx_default", "ctx_max_recomendado",
               "weights_vram_mib", "buffers_mib", "mmproj_mib", "kv_type_default",
               "sliding_window", "kv_mib_medido", "kv_mib_8k_medido")


def kv_mib(m, ctx):
    """(MiB de la cache KV para ctx tokens, exacto). Lo medido en el log de
    llama-server manda; si no, la formula. Con ventana deslizante (Gemma 3)
    la formula ingenua es solo una cota alta: exacto=False."""
    med = (m.get("kv_mib_medido") or {}).get(str(ctx))
    if med is None and ctx == 8192:
        med = m.get("kv_mib_8k_medido")
    if med is not None:
        return float(med), True
    per_tok = (2 * int(m["layers"]) * int(m["kv_heads"]) * int(m["head_dim"])
               * KV_BYTES.get(str(m.get("kv_type_default") or "f16"), 2.0))
    return per_tok * ctx / 1048576, not m.get("sliding_window")


def vram_need_mib(m, ctx):
    """Desglose {pesos, kv, buffers, mmproj, reserva, total, exacto} en MiB
    para ctx tokens, o None si al modelo le faltan datos de arquitectura."""
    try:
        pesos = float(m["weights_vram_mib"])
        kv, exacto = kv_mib(m, ctx)
    except (KeyError, TypeError, ValueError):
        return None
    buf = float(m["buffers_mib"] if m.get("buffers_mib") is not None else BUFFERS_DEF_MIB)
    mm = float(m.get("mmproj_mib") or 0)
    tot = pesos + kv + buf + mm + RESERVA_SO_MIB
    return {"pesos": pesos, "kv": kv, "buffers": buf, "mmproj": mm,
            "reserva": RESERVA_SO_MIB, "total": tot, "exacto": exacto}


# --- subfunciones de models_catalog_to_json: una por campo nuevo del catalogo.
# Cada una recibe la entrada tal como viene en models-catalog.json.
_MIB = 1048576


def weights_vram_mib(m):
    """Pesos en VRAM (MiB). 1) el valor del catalogo (medido en el log de
    llama-server: «CUDA0 model buffer size»); 2) si no, el GGUF de Hugging
    Face (gguf.bytes), cota alta; 3) si no, size_gb. None si no hay nada."""
    if m.get("weights_vram_mib") is not None:
        return float(m["weights_vram_mib"])
    b = (m.get("gguf") or {}).get("bytes")
    if b:
        return float(round(int(b) / _MIB))
    if m.get("size_gb"):
        return float(round(float(m["size_gb"]) * 1e9 / _MIB))
    return None


def kv_mib_medido(m):
    """Cache KV medida por contexto {"4096": MiB, "8192": MiB, ...} (log de
    llama-server: «KV buffer size», sumando todas las capas). Incluye el valor
    suelto kv_mib_8k_medido. {} si no se ha medido: entonces manda la formula."""
    med = {str(k): float(v) for k, v in (m.get("kv_mib_medido") or {}).items() if v is not None}
    if m.get("kv_mib_8k_medido") is not None:
        med.setdefault("8192", float(m["kv_mib_8k_medido"]))
    return med


def kv_mib_8k_medido(m):
    """La KV medida a 8k (MiB) o None si esta pendiente de medir (Gemma 3:
    la ventana deslizante hace que la formula ingenua sobreestime)."""
    return kv_mib_medido(m).get("8192")


def buffers_mib(m):
    """Buffers de computo (MiB): el medido («CUDA0 compute buffer size») o,
    si no, BUFFERS_DEF_MIB (256, dentro del 0,12-0,5 GB tipico)."""
    if m.get("buffers_mib") is not None:
        return float(m["buffers_mib"])
    return float(BUFFERS_DEF_MIB)


def mmproj_mib(m):
    """Proyector de vision (MiB): el del catalogo, o el tamaño del mmproj del
    GGUF (gguf.mmproj.bytes); 0 si el modelo no ve imagenes."""
    if m.get("mmproj_mib") is not None:
        return float(m["mmproj_mib"])
    b = ((m.get("gguf") or {}).get("mmproj") or {}).get("bytes")
    return float(round(int(b) / _MIB)) if b else 0.0


def vram_gb(m):
    """VRAM total (GB = MiB/1024, 1 decimal) a ctx_default con la formula por
    piezas: pesos + KV + buffers + mmproj. Sin datos de arquitectura cae al
    vram_gb del archivo (la cifra vieja de la 0.2.0), o None."""
    e = dict(m)
    for campo, fn in (("weights_vram_mib", weights_vram_mib), ("kv_mib_medido", kv_mib_medido),
                      ("buffers_mib", buffers_mib), ("mmproj_mib", mmproj_mib)):
        e[campo] = fn(m)
    need = vram_need_mib(e, int(m.get("ctx_default") or 8192))
    if need:
        return round(need["total"] / 1024, 1)
    return float(m["vram_gb"]) if m.get("vram_gb") is not None else None


def vram_color(total_mib, vram_mib):
    """verde <= 80 %, naranja 80-100 %, rojo > 100 % (no cabe)."""
    pct = total_mib / vram_mib * 100
    return ("green" if pct <= 80 else "orange" if pct <= 100 else "red"), pct


def ctx_k(ctx):
    return f"{ctx // 1024}k"


def ctx_que_cabe(m, vram_mib, extra_mib=0):
    """El mayor contexto de CTX_PASOS (sin pasar ctx_max_recomendado) cuyo
    total + extra_mib cabe en vram_mib; 0 si no cabe ni el mas pequeno."""
    tope = int(m.get("ctx_max_recomendado") or CTX_PASOS[-1])
    best = 0
    for ctx in CTX_PASOS:
        need = vram_need_mib(m, ctx)
        if ctx <= tope and need and need["total"] + extra_mib <= vram_mib:
            best = ctx
    return best


def model_vram_plan(m, specs, free_mib=None, installed=False):
    """Lo que la pestana Modelos dice de un modelo: color, motivo, contexto
    que cabe en el PC (VRAM total) y ahora mismo (VRAM libre de nvidia-smi),
    la tabla por contexto y el aviso de cerrar el navegador. Sin GPU o sin
    datos de arquitectura cae al semaforo de siempre (model_fit)."""
    gpu = (specs or {}).get("gpu") or {}
    tot = gpu.get("vram_total_mib") or (gpu.get("vram_total_gb") or 0) * 1024
    if free_mib is None:
        free_mib = gpu.get("vram_free_mib") or (
            gpu["vram_free_gb"] * 1024 if gpu.get("vram_free_gb") is not None else None)
    plan = {"pasos": [], "ctx_pc": 0, "ctx_ahora": None, "ctx_anuncio": 0, "need": None,
            "aviso": "", "free_mib": free_mib, "exacto": True, "pct": None}
    if not specs or not tot or not vram_need_mib(m, CTX_PASOS[0]):
        if specs and gpu and not vram_need_mib(m, CTX_PASOS[0]):
            plan["color"], plan["reason"] = "gray", ("Sin datos de su arquitectura (capas, "
                                                     "cabezas KV): no sé qué contexto le cabe")
        else:
            plan["color"], plan["reason"] = model_fit(m.get("vram_gb"), m.get("size_gb"), specs,
                                                      installed=installed)
        return plan
    tope = int(m.get("ctx_max_recomendado") or CTX_PASOS[-1])
    for ctx in CTX_PASOS:
        if ctx > tope:
            continue
        need = vram_need_mib(m, ctx)
        color, pct = vram_color(need["total"], tot)
        plan["pasos"].append({"ctx": ctx, "total": need["total"], "pct": pct, "color": color,
                              "exacto": need["exacto"]})
    plan["ctx_pc"] = ctx_que_cabe(m, tot)
    # El contexto anunciado es el que cabe (como mucho el de por defecto del
    # modelo); si no cabe ni el mas pequeno, se explica con ese.
    dflt = int(m.get("ctx_default") or 8192)
    ctx_anuncio = max([c for c in CTX_PASOS if c <= min(plan["ctx_pc"], dflt)] or [CTX_PASOS[0]])
    need = vram_need_mib(m, ctx_anuncio)
    color, pct = vram_color(need["total"], tot)
    plan.update(need=need, ctx_anuncio=ctx_anuncio, exacto=need["exacto"], color=color, pct=pct)
    aprox = "" if need["exacto"] else " (aprox.: ventana deslizante, pendiente de medir)"
    if not plan["ctx_pc"]:
        plan["reason"] = (f"No cabe: necesita {_gb(need['total'] / 1024)} GB de VRAM con "
                          f"{ctx_k(ctx_anuncio)} de contexto y tu tarjeta tiene {_gb(tot / 1024)} GB")
    elif color == "green":
        plan["reason"] = f"Cabe holgado: usa ~{round(pct)}% de tu VRAM con {ctx_k(ctx_anuncio)}{aprox}"
    else:
        plan["reason"] = f"Va justo: usa ~{round(pct)}% de tu VRAM con {ctx_k(ctx_anuncio)}{aprox}"
    disk, size = specs.get("disk_free_gb"), m.get("size_gb")
    if not installed and size and disk is not None and size > disk:
        plan["color"] = "red"
        plan["reason"] = f"No cabe: necesita {_gb(size)} GB de disco y tienes {_gb(disk)} GB libres"
    if free_mib is not None and plan["ctx_pc"]:
        # Al cargar se suma el contexto CUDA (medido ~122 MiB) a lo de la tabla.
        plan["ctx_ahora"] = ctx_que_cabe(m, free_mib, CUDA_CONTEXTO_MIB)
        if plan["ctx_ahora"] < plan["ctx_pc"]:
            plan["aviso"] = (f"Cierra el navegador u otras apps que usen la tarjeta de video "
                             f"para llegar a {ctx_k(plan['ctx_pc'])}.")
    return plan


def friendly_model_name(name, catalog=None):
    """Nombre normal de un modelo (sin etiquetas tecnicas)."""
    for m in catalog if catalog is not None else load_catalog():
        if _same_model(m["id"], name):
            return m["name"]
    base = name.rsplit("/", 1)[-1]
    base, _, tag = base.partition(":")
    base = re.sub(r"-?GGUF$", "", base, flags=re.I).replace("-", " ").replace("_", " ")
    if tag and tag != "latest" and re.fullmatch(r"\d+(\.\d+)?b", tag, re.I):
        base += " " + tag.upper()
    return base.strip() or name


# --- especificaciones del PC (todo local, sin gastar nada)
def _gpu_query():
    smi = shutil.which("nvidia-smi")
    if not smi:
        cand = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32" / "nvidia-smi.exe"
        smi = str(cand) if cand.is_file() else None
    if not smi:
        return None
    try:
        p = subprocess.run([smi, "--query-gpu=name,memory.total,memory.free",
                            "--format=csv,noheader,nounits"],
                           capture_output=True, text=True, timeout=15,
                           creationflags=_NO_WINDOW)
        line = next((l for l in (p.stdout or "").splitlines() if l.strip()), "")
        name, total, free = [x.strip() for x in line.split(",")[:3]]
        return {"name": name, "vram_total_gb": round(int(float(total)) / 1024, 1),
                "vram_free_gb": round(int(float(free)) / 1024, 1),
                "vram_total_mib": int(float(total)), "vram_free_mib": int(float(free))}
    except Exception:
        return None


def gpu_free_vram_gb():
    g = _gpu_query()
    return g["vram_free_gb"] if g else None


def detect_pc_specs():
    """GPU (nvidia-smi), RAM, CPU, disco libre y version de Ollama. Guarda el
    resultado en pc-specs.json y lo devuelve."""
    specs = {"detected_at": _now_iso(), "gpu": _gpu_query()}
    try:
        import ctypes

        class _MEM(ctypes.Structure):
            _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]
        st = _MEM()
        st.dwLength = ctypes.sizeof(_MEM)
        ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(st))
        specs["ram_total_gb"] = round(st.ullTotalPhys / 1024 ** 3, 1)
        specs["ram_free_gb"] = round(st.ullAvailPhys / 1024 ** 3, 1)
    except Exception:
        specs["ram_total_gb"] = specs["ram_free_gb"] = None
    cpu = {"name": "", "cores": None, "threads": os.cpu_count()}
    try:
        import winreg
        k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                           r"HARDWARE\DESCRIPTION\System\CentralProcessor\0")
        cpu["name"] = str(winreg.QueryValueEx(k, "ProcessorNameString")[0]).strip()
        winreg.CloseKey(k)
    except Exception:
        pass
    try:
        p = subprocess.run(["powershell", "-NoProfile", "-Command",
                            "(Get-CimInstance Win32_Processor | Measure-Object "
                            "-Property NumberOfCores -Sum).Sum"],
                           capture_output=True, text=True, timeout=20,
                           creationflags=_NO_WINDOW)
        cpu["cores"] = int((p.stdout or "").strip())
    except Exception:
        pass
    specs["cpu"] = cpu
    try:
        drive = Path.home().anchor or "C:\\"
        specs["disk_drive"] = drive
        specs["disk_free_gb"] = round(shutil.disk_usage(drive).free / 1024 ** 3, 1)
    except Exception:
        specs["disk_free_gb"] = None
    specs["ollama_version"] = ""
    exe = ollama_exe()
    if exe:
        try:
            _rc, so, se = _run_capture([exe, "--version"], 20)
            m = re.search(r"version is (\d+\.\d+\.\d+)", so + se) or \
                re.search(r"(\d+\.\d+\.\d+)", so + se)
            specs["ollama_version"] = m.group(1) if m else ""
        except Exception:
            pass
    try:
        PC_SPECS_FILE.write_text(json.dumps(specs, ensure_ascii=False, indent=2),
                                 encoding="utf-8")
    except OSError:
        pass
    return specs


def load_pc_specs():
    try:
        data = json.loads(PC_SPECS_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except (OSError, ValueError):
        return None


def _gb(x):
    s = f"{x:.1f}"
    return s[:-2] if s.endswith(".0") else s


def _y_join(parts):
    """['a', 'b', 'c'] -> 'a, b y c' (enumeracion en espanol)."""
    parts = [str(x) for x in parts if x]
    if len(parts) <= 1:
        return "".join(parts)
    return ", ".join(parts[:-1]) + " y " + parts[-1]


def pc_specs_summary(specs):
    """'RTX 3060 Laptop con 6 GB de VRAM, 16 GB de RAM y 100 GB libres'."""
    if not specs:
        return "Aún no comprobé tu PC."
    parts = []
    gpu = specs.get("gpu")
    if gpu:
        name = re.sub(r"\b(NVIDIA|GeForce|GPU)\b", "", gpu.get("name", "")).strip()
        parts += [re.sub(r"\s+", " ", name) or "GPU NVIDIA",
                  f"{_gb(gpu.get('vram_total_gb') or 0)} GB VRAM"]
    else:
        parts.append("Sin GPU dedicada (los modelos corren en el procesador)")
    if specs.get("ram_total_gb"):
        parts.append(f"{round(specs['ram_total_gb'])} GB RAM")
    if specs.get("disk_free_gb") is not None:
        parts.append(f"{round(specs['disk_free_gb'])} GB libres")
    return _y_join(parts)


def model_fit(vram_need, size_gb, specs, installed=False):
    """Semaforo: (color, motivo). color: green / orange / red / gray.
    Con GPU: verde <= 80 % de la VRAM total, naranja 80-100 %, rojo si no
    cabe (o si no cabe en el disco). Sin GPU usa la RAM (corre en CPU):
    verde <= 50 %, naranja 50-90 %, rojo por encima."""
    if not specs:
        return "gray", "Pulsa Comprobar mi PC para ver si cabe"
    vram_need = float(vram_need or 0)
    gpu = specs.get("gpu")
    disk = specs.get("disk_free_gb")
    disk_red = (not installed and size_gb and disk is not None and size_gb > disk)
    if gpu and gpu.get("vram_total_gb"):
        tot = float(gpu["vram_total_gb"])
        if vram_need > tot:
            return "red", f"No cabe: necesita {_gb(vram_need)} GB de VRAM y tienes {_gb(tot)} GB"
        if disk_red:
            return "red", f"No cabe: necesita {_gb(size_gb)} GB de disco y tienes {_gb(disk)} GB libres"
        pct = vram_need / tot * 100
        if pct <= 80:
            return "green", "Cabe holgado"
        return "orange", f"Va justo: usa ~{round(pct)}% de tu VRAM"
    ram = specs.get("ram_total_gb")
    if not ram:
        return "gray", "No pude leer la memoria de tu PC"
    if vram_need > ram * 0.9:
        return "red", (f"No cabe: necesita {_gb(vram_need)} GB de RAM y tienes "
                       f"{_gb(ram)} GB (sin GPU, corre en CPU)")
    if disk_red:
        return "red", f"No cabe: necesita {_gb(size_gb)} GB de disco y tienes {_gb(disk)} GB libres"
    pct = vram_need / ram * 100
    if pct <= 50:
        return "green", "Cabe holgado (sin GPU, corre en CPU)"
    return "orange", f"Va justo: usa ~{round(pct)}% de tu RAM (sin GPU, corre en CPU)"


# --- reglas (las instrucciones del agente, en palabras del usuario)
def load_rules():
    try:
        data = json.loads(RULES_FILE.read_text(encoding="utf-8"))
        if isinstance(data, list):
            return [{"text": str(r.get("text", "")).strip()[:300],
                     "on": bool(r.get("on", True))}
                    for r in data if isinstance(r, dict) and str(r.get("text", "")).strip()]
    except FileNotFoundError:
        rules = [{"text": t, "on": True} for t in DEFAULT_RULES]
        save_rules(rules)
        return rules
    except (OSError, ValueError):
        pass
    return [{"text": t, "on": True} for t in DEFAULT_RULES]


def save_rules(rules):
    try:
        RULES_FILE.write_text(json.dumps(rules, ensure_ascii=False, indent=2),
                              encoding="utf-8")
    except OSError:
        pass


# --- habilidades (herramientas del runner + skills de Claude Code)
TOOL_ABILITIES = (
    ("Read", "Leer tus archivos", "Abre y lee archivos de tus carpetas permitidas."),
    ("Write", "Crear archivos", "Guarda archivos nuevos en tus carpetas permitidas."),
    ("Edit", "Editar tus archivos", "Cambia archivos que ya existen."),
    ("Bash", "Usar los programas del PC", "Abre programas y hace tareas en tu PC."),
    ("WebSearch", "Buscar en internet", "Busca información actualizada en la web."),
    ("WebFetch", "Abrir páginas web", "Lee una página que le indiques."),
)
SKILL_FRIENDLY = {
    "hypit": ("Hacer videos", "Dirige y produce videos de principio a fin."),
}


def list_abilities():
    """Lo que el agente puede hacer, en palabras normales, con su estado.
    Los nombres se pueden cambiar en settings.json (ability_names)."""
    s = load_settings()
    off = set(s.get("disabled_abilities") or [])
    names = s.get("ability_names") or {}
    out = []
    for tool, name, desc in TOOL_ABILITIES:
        key = f"tool:{tool}"
        out.append({"key": key, "name": name, "desc": desc, "on": key not in off})
    base = HOME_DIR / ".claude" / "skills"
    if base.is_dir():
        for folder in sorted(base.iterdir()):
            if not (folder / "SKILL.md").is_file():
                continue
            key = f"skill:{folder.name}"
            custom = names.get(folder.name)
            if isinstance(custom, (list, tuple)) and len(custom) >= 2:
                name, desc = str(custom[0]), str(custom[1])
            elif folder.name in SKILL_FRIENDLY:
                name, desc = SKILL_FRIENDLY[folder.name]
            else:
                name = folder.name.replace("-", " ").replace("_", " ").strip().capitalize()
                desc = "Una habilidad extra que instalaste."
            out.append({"key": key, "name": name, "desc": desc, "on": key not in off})
    return out


def disabled_abilities():
    return set(load_settings().get("disabled_abilities") or [])


def rules_prefix():
    """Lo que va AL PRINCIPIO de cada prompt (Claude, Ollama y APIs): las
    reglas activas del usuario y las habilidades que apago."""
    lines = []
    active = [r["text"] for r in load_rules() if r["on"]]
    if active:
        who = str(load_settings().get("user_name") or "").strip()
        lines.append(f"Reglas de {who}:" if who else "Reglas del usuario:")
        lines += [f"- {t}" for t in active]
    off_skills = [a["name"] for a in list_abilities()
                  if not a["on"] and a["key"].startswith("skill:")]
    if off_skills:
        lines.append("No uses estas habilidades (el usuario las apagó): "
                     + ", ".join(off_skills))
    return ("\n".join(lines) + "\n\n") if lines else ""


