def cred_slug(text):
    """«Trabajo 2» -> trabajo-2 (minusculas, sin tildes ni espacios)."""
    import unicodedata
    t = unicodedata.normalize("NFKD", str(text or "")).encode("ascii", "ignore").decode("ascii").lower()
    return re.sub(r"[^a-z0-9]+", "-", t).strip("-")[:40]


def cred_cuenta(proveedor, etiqueta):
    return f"{proveedor}-{cred_slug(etiqueta)}"


def cred_proveedor_de(nombre):
    n = str(nombre or "").strip().lower()
    return n if n in CRED_PROVIDERS else CRED_ALIASES.get(n)


def cred_validar_url(url):
    """(url_normalizada, None) o (None, motivo). https:// (http:// solo para
    127.0.0.1/localhost), sin usuario:clave@, sin ?parametros, sin barra final."""
    u = str(url or "").strip()
    if not u:
        return None, "falta la URL base"
    try:
        p = urllib.parse.urlsplit(u)
    except ValueError:
        return None, "la URL base no se entiende"
    if p.scheme not in ("https", "http"):
        return None, "la URL base debe empezar por https://"
    if "@" in p.netloc:
        return None, ("la URL base trae un usuario o una clave incrustados (…://usuario:clave@…). "
                      "No se guarda así: la clave va en su campo, nunca dentro de la URL")
    try:
        host = (p.hostname or "").lower()
        p.port
    except ValueError:
        return None, "el puerto de la URL base no es válido"
    if not host:
        return None, "a la URL base le falta el servidor (https://servidor/...)"
    if p.scheme == "http" and host not in ("127.0.0.1", "localhost"):
        return None, "http:// solo se acepta para 127.0.0.1 o localhost; para internet usa https://"
    if p.query or p.fragment:
        return None, "la URL base no puede llevar ?parámetros ni # (ahí podría ir una clave)"
    path = re.sub(r"/{2,}", "/", p.path).rstrip("/")
    return f"{p.scheme}://{p.netloc.lower()}{path}", None


def cred_via():
    """'keyring' (Administrador de credenciales) o 'dpapi' (respaldo), con el motivo."""
    if _CRED_VIA["via"]:
        return _CRED_VIA["via"]
    forzado = os.environ.get("GROWI_BRIDGE_CRED_BACKEND", "").strip().lower()
    if forzado == "dpapi":
        _CRED_VIA.update(via="dpapi", motivo="forzado con GROWI_BRIDGE_CRED_BACKEND=dpapi")
    elif forzado == "ayudante":
        _CRED_VIA.update(via="ayudante", motivo="", detalle="keyring a través del ayudante sin elevación "
                                                             "(forzado con GROWI_BRIDGE_CRED_BACKEND=ayudante)")
    else:
        try:
            import keyring
            kr = keyring.get_keyring()
            nombre = f"{type(kr).__module__}.{type(kr).__name__}"
            if nombre == "keyring.backends.Windows.WinVaultKeyring":
                try:
                    from importlib.metadata import version as _v
                    ver = _v("keyring")
                except Exception:
                    ver = "?"
                # Prueba real (escribe, lee y borra una entrada de prueba): en una
                # sesion sin almacen (p. ej. la app elevada, visto el 26 oct 2026)
                # CredWrite falla con 1312 aunque keyring importe bien.
                t = f"{CRED_SERVICE}/_prueba-almacen"
                try:
                    keyring.set_password(t, "_prueba-almacen", "growi-bridge-prueba")
                    okp = keyring.get_password(t, "_prueba-almacen") == "growi-bridge-prueba"
                    keyring.delete_password(t, "_prueba-almacen")
                    err = None if okp else "la entrada de prueba no se leyó igual"
                except Exception as e:
                    err = f"{type(e).__name__}: {str(e)[:160]}"
                if err:
                    # La app elevada no puede (1312), pero un proceso SIN elevacion
                    # de la misma sesion si: el ayudante (lanzado por explorer).
                    aerr = _ayudante_probar() if os.name == "nt" else "solo en Windows"
                    if aerr is None:
                        _CRED_VIA.update(via="ayudante", motivo="", detalle=(
                            f"keyring {ver}, WinVaultKeyring, a través de un ayudante sin elevación: la app corre "
                            f"como administrador y Windows no le deja guardar credenciales directamente ({err})"))
                    else:
                        _CRED_VIA.update(via="dpapi", motivo=(
                            f"keyring {ver} no puede escribir en el Administrador de credenciales en esta sesión "
                            f"({err}) y el ayudante sin elevación tampoco ({aerr})"))
                else:
                    _CRED_VIA.update(via="keyring", motivo="", detalle=f"keyring {ver}, WinVaultKeyring")
            else:
                _CRED_VIA.update(via="dpapi", motivo=f"keyring no trae el backend del Administrador de "
                                                     f"credenciales (tiene {nombre})")
        except Exception as e:
            _CRED_VIA.update(via="dpapi", motivo=f"keyring no se pudo importar ({type(e).__name__})")
    if _CRED_VIA["via"] == "dpapi":
        _CRED_VIA["detalle"] = f"DPAPI con ctypes, archivo {CRED_DPAPI_FILE.name}"
    log(f"claves: almacén = {_CRED_VIA['via']} ({_CRED_VIA['detalle']}"
        + (f"; motivo: {_CRED_VIA['motivo']}" if _CRED_VIA["motivo"] else "") + ")")
    return _CRED_VIA["via"]


def _dpapi(data, cifrar):
    import ctypes
    from ctypes import wintypes

    class BLOB(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_char))]
    c32, k32 = ctypes.windll.crypt32, ctypes.windll.kernel32
    k32.LocalFree.argtypes = [ctypes.c_void_p]
    fn = c32.CryptProtectData if cifrar else c32.CryptUnprotectData
    fn.argtypes = [ctypes.POINTER(BLOB), ctypes.c_wchar_p, ctypes.POINTER(BLOB), ctypes.c_void_p,
                   ctypes.c_void_p, wintypes.DWORD, ctypes.POINTER(BLOB)]
    fn.restype = wintypes.BOOL
    buf = ctypes.create_string_buffer(data, len(data))
    ent_b = b"growi-bridge-credenciales"
    ebuf = ctypes.create_string_buffer(ent_b, len(ent_b))
    inp = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_char)))
    ent = BLOB(len(ent_b), ctypes.cast(ebuf, ctypes.POINTER(ctypes.c_char)))
    out = BLOB()
    if not fn(ctypes.byref(inp), "growi-bridge" if cifrar else None, ctypes.byref(ent), None, None,
              0x1, ctypes.byref(out)):  # 0x1 = CRYPTPROTECT_UI_FORBIDDEN
        raise OSError(f"DPAPI falló (error {ctypes.GetLastError()})")
    try:
        return ctypes.string_at(out.pbData, out.cbData)
    finally:
        k32.LocalFree(ctypes.cast(out.pbData, ctypes.c_void_p))


def _dpapi_leer_archivo():
    try:
        d = json.loads(CRED_DPAPI_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


# ---- ayudante sin elevacion (Administrador de credenciales desde la app elevada)
# La app corre elevada («Administrador: sí») y CredWrite persistente le da 1312;
# un proceso de la misma sesion SIN elevacion si puede. explorer.exe lanza un
# .vbs (sin elevacion, sin ventana) que corre «growi-bridge.py --cred-ayudante
# <carpeta>»: lee las peticiones y responde. La clave viaja SOLO cifrada con
# DPAPI (el mismo usuario descifra en los dos lados) y los archivos de
# peticion/respuesta se borran al leerlos. En memoria de la app se guarda la
# clave ya leida (nunca en disco) para no lanzar el ayudante en cada uso.
CRED_AYUDANTE_DIR = APP_DIR / "cred-ayudante"
_CRED_MEM = {}


def _ayudante_vbs():
    py = Path(sys.executable)
    pyw = py.with_name("pythonw.exe") if py.with_name("pythonw.exe").is_file() else py
    vbs = CRED_AYUDANTE_DIR / "ayudante.vbs"
    q = '"'
    cmd = (f'{q}{q}{pyw}{q}{q} {q}{q}{Path(__file__).resolve()}{q}{q} --cred-ayudante '
           f'{q}{q}{CRED_AYUDANTE_DIR}{q}{q}')
    txt = f'CreateObject("WScript.Shell").Run "{cmd}", 0, False\r\n'
    if not vbs.is_file() or vbs.read_text(encoding="utf-8", errors="replace") != txt:
        vbs.write_text(txt, encoding="utf-8", newline="")
    return vbs


def _ayudante(op, cuenta="", clave=None, timeout=25):
    """(ok, clave_o_None, error). op: set / get / del / probe."""
    import base64
    import uuid
    CRED_AYUDANTE_DIR.mkdir(parents=True, exist_ok=True)
    rid = uuid.uuid4().hex[:12]
    req = {"id": rid, "op": op, "cuenta": cuenta}
    if clave is not None:
        req["blob"] = base64.b64encode(_dpapi(clave.encode("utf-8"), True)).decode("ascii")
    tmp = CRED_AYUDANTE_DIR / f"{rid}.req.tmp"
    tmp.write_text(json.dumps(req), encoding="utf-8")
    tmp.replace(CRED_AYUDANTE_DIR / f"{rid}.req.json")
    resp = CRED_AYUDANTE_DIR / f"{rid}.resp.json"
    try:
        subprocess.Popen(["explorer.exe", str(_ayudante_vbs())], **_oculto())
    except Exception as e:
        (CRED_AYUDANTE_DIR / f"{rid}.req.json").unlink(missing_ok=True)
        return False, None, f"no se pudo lanzar el ayudante ({type(e).__name__})"
    t0 = time.time()
    while time.time() - t0 < timeout:
        if resp.is_file():
            try:
                d = json.loads(resp.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                time.sleep(0.1)
                continue
            resp.unlink(missing_ok=True)
            val = None
            if d.get("blob"):
                val = _dpapi(base64.b64decode(d["blob"]), False).decode("utf-8")
            return bool(d.get("ok")), val, d.get("err")
        time.sleep(0.15)
    (CRED_AYUDANTE_DIR / f"{rid}.req.json").unlink(missing_ok=True)
    return False, None, f"el ayudante no respondió en {timeout} s"


def _ayudante_probar():
    """None si el ayudante escribe, lee y borra en el Administrador; si no, el motivo."""
    try:
        ok, _v, err = _ayudante("probe")
        return None if ok else (err or "falló")
    except Exception as e:
        return f"{type(e).__name__}: {str(e)[:120]}"


def _cli_cred_ayudante(carpeta):
    """Proceso SIN elevacion: atiende las peticiones de la carpeta y sale."""
    import base64
    import keyring
    d = Path(carpeta)
    for _ronda in range(3):
        for f in sorted(d.glob("*.req.json")):
            try:
                req = json.loads(f.read_text(encoding="utf-8"))
                f.unlink()
            except (OSError, ValueError):
                continue
            out = {"id": req.get("id"), "ok": False}
            try:
                op, cu = req.get("op"), str(req.get("cuenta") or "")
                srv = f"{CRED_SERVICE}/{cu}"
                if op == "set":
                    clave = _dpapi(base64.b64decode(req["blob"]), False).decode("utf-8")
                    _keyring_set_limpio(srv, cu, clave)
                    out["ok"] = keyring.get_password(srv, cu) == clave
                elif op == "get":
                    v = keyring.get_password(srv, cu)
                    out["ok"] = True
                    if v:
                        out["blob"] = base64.b64encode(_dpapi(v.encode("utf-8"), True)).decode("ascii")
                elif op == "del":
                    try:
                        keyring.delete_password(srv, cu)
                    except Exception:
                        pass
                    out["ok"] = keyring.get_password(srv, cu) is None
                elif op == "probe":
                    t = f"{CRED_SERVICE}/_prueba-almacen"
                    keyring.set_password(t, "_prueba-almacen", "growi-bridge-prueba")
                    okp = keyring.get_password(t, "_prueba-almacen") == "growi-bridge-prueba"
                    keyring.delete_password(t, "_prueba-almacen")
                    out["ok"] = okp
            except Exception as e:
                out["err"] = f"{type(e).__name__}: {str(e)[:160]}"
            tmp = d / f"{req.get('id')}.resp.tmp"
            tmp.write_text(json.dumps(out), encoding="utf-8")
            tmp.replace(d / f"{req.get('id')}.resp.json")
        time.sleep(0.3)
    return 0


def _keyring_set_limpio(srv, cuenta, clave):
    """Reemplazar sin dejar la vieja: con una entrada ya existente, keyring
    (Windows) copia la anterior a «cuenta@servicio» antes de escribir; se borra
    primero (delete_password quita las dos)."""
    import keyring
    try:
        keyring.delete_password(srv, cuenta)
    except Exception:
        pass
    keyring.set_password(srv, cuenta, clave)


def _sec_set(cuenta, clave):
    via = cred_via()
    if via == "keyring":
        _keyring_set_limpio(f"{CRED_SERVICE}/{cuenta}", cuenta, clave)
        return
    if via == "ayudante":
        ok, _v, err = _ayudante("set", cuenta, clave)
        if not ok:
            raise OSError(err or "el ayudante no pudo guardarla")
        _CRED_MEM[cuenta] = clave
        return
    import base64
    d = _dpapi_leer_archivo()
    d[cuenta] = base64.b64encode(_dpapi(clave.encode("utf-8"), True)).decode("ascii")
    CRED_DPAPI_FILE.write_text(json.dumps(d, indent=2), encoding="utf-8")


def _sec_get_en(via, cuenta):
    if via == "keyring":
        import keyring
        v = keyring.get_password(f"{CRED_SERVICE}/{cuenta}", cuenta)
        return v.strip() if v else None
    if via == "ayudante":
        if cuenta in _CRED_MEM:
            return _CRED_MEM[cuenta]
        ok, v, err = _ayudante("get", cuenta)
        if not ok:
            raise OSError(err or "el ayudante no respondió")
        if v:
            _CRED_MEM[cuenta] = v.strip()
        return v.strip() if v else None
    import base64
    b = _dpapi_leer_archivo().get(cuenta)
    return _dpapi(base64.b64decode(b), False).decode("utf-8").strip() if b else None


def _sec_get(cuenta):
    """Primero el almacen de esta sesion; si no esta, el respaldo DPAPI (una
    clave guardada con el respaldo sigue sirviendo si otro dia keyring va)."""
    primero = cred_via()
    otros = [v for v in ("dpapi", "keyring") if v != primero and not (primero == "ayudante" and v == "keyring")]
    for via in [primero] + otros:
        try:
            v = _sec_get_en(via, cuenta)
            if v:
                return v
        except Exception as e:
            if via == primero:
                log(f"claves: no se pudo leer la clave {cuenta} del almacén {via} ({type(e).__name__}: {e})")
    return None


def _sec_del(cuenta):
    """Borra esa cuenta de todos los almacenes. True si ya no esta en ninguno."""
    _CRED_MEM.pop(cuenta, None)
    if cred_via() == "ayudante":
        ok, _v, err = _ayudante("del", cuenta)
        if not ok:
            log(f"claves: el ayudante no pudo borrar {cuenta} del Administrador de credenciales ({err})")
            return False
    else:
        try:
            import keyring
            import keyring.errors
            try:
                keyring.delete_password(f"{CRED_SERVICE}/{cuenta}", cuenta)
            except keyring.errors.PasswordDeleteError:
                pass
        except Exception as e:
            if cred_via() == "keyring":
                log(f"claves: no se pudo borrar {cuenta} del Administrador de credenciales ({type(e).__name__})")
    try:
        d = _dpapi_leer_archivo()
        if d.pop(cuenta, None) is not None:
            CRED_DPAPI_FILE.write_text(json.dumps(d, indent=2), encoding="utf-8")
    except Exception as e:
        log(f"claves: no se pudo borrar {cuenta} del archivo DPAPI ({type(e).__name__})")
    return _sec_get(cuenta) is None


def cred_lista():
    """Las claves guardadas (solo datos, nunca la clave), con su cuenta."""
    raw = load_settings().get("credenciales")
    out = []
    for c in raw if isinstance(raw, list) else []:
        if isinstance(c, dict) and c.get("proveedor") in CRED_PROVIDERS and cred_slug(c.get("etiqueta")):
            out.append({"proveedor": c["proveedor"], "etiqueta": str(c["etiqueta"]),
                        "base_url": str(c.get("base_url") or CRED_PROVIDERS[c["proveedor"]]["base"]),
                        "ultimos4": str(c.get("ultimos4") or "????")[-4:], "activa": bool(c.get("activa")),
                        "cuenta": cred_cuenta(c["proveedor"], c["etiqueta"])})
    return out


def cred_get(cuenta):
    return next((c for c in cred_lista() if c["cuenta"] == cuenta), None)


def cred_activa(proveedor):
    """La clave activa de ese proveedor (una sola), o None."""
    return next((c for c in cred_lista() if c["proveedor"] == proveedor and c["activa"]), None)


def _cred_escribir(lista):
    s = load_settings()
    s["credenciales"] = [{"proveedor": c["proveedor"], "etiqueta": c["etiqueta"], "base_url": c["base_url"],
                          "ultimos4": c["ultimos4"], "activa": bool(c["activa"])} for c in lista]
    save_settings(s)
    _GW_ESTADO_CACHE["motores"] = None


def cred_guardar(proveedor, etiqueta, base_url, clave):
    """Guarda (o reemplaza, con la misma etiqueta) una clave. (ok, mensaje)."""
    if proveedor not in CRED_PROVIDERS:
        return False, "elige un proveedor"
    etiqueta = str(etiqueta or "").strip()
    if not cred_slug(etiqueta):
        return False, "ponle una etiqueta (personal, trabajo, respaldo…)"
    clave = str(clave or "").strip()
    if len(clave) < 8 or any(ch.isspace() for ch in clave):
        return False, "la clave está vacía, es muy corta o tiene espacios dentro"
    base, err = cred_validar_url(base_url or CRED_PROVIDERS[proveedor]["base"])
    if err:
        return False, err
    cuenta = cred_cuenta(proveedor, etiqueta)
    try:
        _sec_set(cuenta, clave)
    except Exception as e:
        return False, _scrub(f"no se pudo guardar en el almacén ({type(e).__name__}: {e})", clave)[:200]
    if _sec_get(cuenta) != clave:
        return False, "se guardó pero al leerla de vuelta no coincide: no la uses todavía"
    lista = cred_lista()
    vieja = next((c for c in lista if c["cuenta"] == cuenta), None)
    lista = [c for c in lista if c["cuenta"] != cuenta]
    activa = vieja["activa"] if vieja else not any(c["proveedor"] == proveedor and c["activa"] for c in lista)
    lista.append({"proveedor": proveedor, "etiqueta": etiqueta, "base_url": base, "ultimos4": clave[-4:],
                  "activa": activa, "cuenta": cuenta})
    _cred_escribir(lista)
    log(f"claves: guardada {proveedor} «{etiqueta}» (cuenta {cuenta}, ••••{clave[-4:]}, {base}, "
        f"almacén {cred_via()})" + (" — reemplaza a la anterior con esa etiqueta" if vieja else "")
        + (" — es la activa" if activa else ""))
    if proveedor == "tripo":
        # Saldo de referencia del aviso del 25 %: el de esta clave al guardarla.
        s = load_settings()
        if isinstance(s.get("tripo_saldo_ref"), dict) and s["tripo_saldo_ref"].pop(cuenta, None) is not None:
            save_settings(s)
        if activa:
            threading.Thread(target=_tripo_leer_y_pintar, daemon=True).start()
    return True, ("Reemplazada: la clave anterior con esa etiqueta se sobrescribió." if vieja else "Guardada.") \
        + (" Es la activa de " + CRED_PROVIDERS[proveedor]["label"] + "." if activa else "")


def cred_activar(cuenta):
    lista = cred_lista()
    c = next((x for x in lista if x["cuenta"] == cuenta), None)
    if c is None:
        return False
    for x in lista:
        if x["proveedor"] == c["proveedor"]:
            x["activa"] = x["cuenta"] == cuenta
    _cred_escribir(lista)
    log(f"claves: {c['proveedor']} usa ahora la clave «{c['etiqueta']}» (••••{c['ultimos4']}); vale desde "
        "el siguiente uso (lo que ya corre sigue con la suya)")
    return True


def cred_cambiar_url(cuenta, url):
    base, err = cred_validar_url(url)
    if err:
        return False, err
    lista = cred_lista()
    for x in lista:
        if x["cuenta"] == cuenta:
            x["base_url"] = base
            _cred_escribir(lista)
            log(f"claves: {x['proveedor']} «{x['etiqueta']}» apunta ahora a {base}")
            return True, f"URL base guardada: {base}"
    return False, "esa clave ya no existe"


def cred_borrar(cuenta):
    """Borra SOLO esa clave (almacen + settings.json). (ok, mensaje)."""
    c = cred_get(cuenta)
    if c is None:
        return False, "esa clave ya no existe"
    if not _sec_del(cuenta):
        return False, "no se pudo borrar del almacén; no toqué nada más"
    _cred_escribir([x for x in cred_lista() if x["cuenta"] != cuenta])
    s = load_settings()
    for k in ("credenciales_topes", "credenciales_avisos", "credenciales_pruebas"):
        if isinstance(s.get(k), dict) and cuenta in s[k]:
            s[k].pop(cuenta, None)
    save_settings(s)
    log(f"claves: borrada {c['proveedor']} «{c['etiqueta']}» (••••{c['ultimos4']}) de este PC; las demás "
        f"claves de {c['proveedor']} siguen igual. En el servidor NO queda invalidada: revócala en "
        f"{CRED_PROVIDERS[c['proveedor']]['panel']}")
    return True, "Borrada de este PC."


def cred_clave(cuenta):
    return _sec_get(cuenta)


# ---- gasto por clave (desde los .result.json del runner; nunca inventado)
def _mes():
    return datetime.now().astimezone().strftime("%Y-%m")


def cred_topes():
    t = load_settings().get("credenciales_topes")
    return {k: float(v) for k, v in (t.items() if isinstance(t, dict) else [])
            if isinstance(v, (int, float)) and v >= 0}


def cred_set_tope(cuenta, valor):
    s = load_settings()
    t = s.get("credenciales_topes") if isinstance(s.get("credenciales_topes"), dict) else {}
    if valor is None:
        t.pop(cuenta, None)
    else:
        t[cuenta] = round(float(valor), 2)
    s["credenciales_topes"] = t
    save_settings(s)
    log(f"claves: tope mensual de {cuenta}: " + ("sin tope" if valor is None else f"${float(valor):.2f}"))


def gasto_de_resultado(result):
    """{cuenta, etiqueta, proveedor, usd, fuente} para el result de una tarea
    que uso una clave (credencial_usada con cuenta), o None. usd: el cost_usd
    del motor; si no lo da, tokens x precio de lista de engines.json; si no hay
    precio, None (se cuenta como «sin precio», no se inventa)."""
    cu = result.get("credencial_usada") if isinstance(result, dict) else None
    if not isinstance(cu, dict) or not cu.get("cuenta"):
        return None
    usd, fuente = None, "sin precio: el proveedor no dio costo y engines.json no tiene precio para ese modelo"
    if isinstance(result.get("cost_usd"), (int, float)):
        usd, fuente = float(result["cost_usd"]), "cost_usd del motor"
    elif result.get("status") != "ok" and not isinstance(result.get("uso"), dict):
        usd, fuente = 0.0, "la llamada falló y el proveedor no reportó uso (401, red…): no consta gasto"
    else:
        uso = result.get("uso") if isinstance(result.get("uso"), dict) else {}
        tin, tout = uso.get("tokens_in"), uso.get("tokens_out")
        model = uso.get("modelo_real") or str(result.get("modelo") or "").split(":")[-1]
        if isinstance(tin, int) or isinstance(tout, int):
            est = estimate_cost(model, {"input": tin or 0, "output": tout or 0, "cache_5m": 0, "cache_1h": 0,
                                        "cache_read": 0})
            if est is not None:
                usd, fuente = round(est, 6), f"tokens de la respuesta x precio de lista de {model} (engines.json)"
    return {"cuenta": cu["cuenta"], "etiqueta": cu.get("etiqueta"), "proveedor": cu.get("proveedor"),
            "usd": usd, "fuente": fuente}


def cred_gasto_mes():
    """{cuenta: {usd, usos, sin_precio}} del mes actual + "__max_equiv__" (la
    sesion Max del motor claude, en $ equivalente, nunca $ real)."""
    try:
        files = list(RESULTS.glob("*.result.json"))
        huella = (len(files), max((f.stat().st_mtime for f in files), default=0), _mes())
    except OSError:
        files, huella = [], None
    if huella is not None and _CRED_GASTO_CACHE["huella"] == huella:
        return _CRED_GASTO_CACHE["datos"]
    mes, plan, out = _mes(), _claude_plan(), {"__max_equiv__": 0.0}
    for f in files:
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(d, dict) or str(d.get("finished_at") or "")[:7] != mes:
            continue
        g = d.get("gasto_clave") if isinstance(d.get("gasto_clave"), dict) else None
        if g and g.get("cuenta"):
            e = out.setdefault(g["cuenta"], {"usd": 0.0, "usos": 0, "sin_precio": 0})
            e["usos"] += 1
            if isinstance(g.get("usd"), (int, float)):
                e["usd"] += float(g["usd"])
            else:
                e["sin_precio"] += 1
        elif _money_kind(d, plan) == "equiv" and isinstance(d.get("cost_usd"), (int, float)):
            out["__max_equiv__"] += float(d["cost_usd"])
    _CRED_GASTO_CACHE.update(huella=huella, datos=out)
    return out


def cred_puede_usar(cuenta):
    """(ok, motivo_si_no, aviso_o_None, nivel). Bloquea SOLO esa clave al 100 %
    de su tope; aviso al 75 % y al 90 %; sin tope: aviso antes de cada uso."""
    c = cred_get(cuenta) or {"etiqueta": cuenta, "proveedor": "?"}
    g = (cred_gasto_mes().get(cuenta) or {}).get("usd", 0.0)
    tope = cred_topes().get(cuenta)
    quien = f"la clave «{c['etiqueta']}» de {CRED_PROVIDERS.get(c['proveedor'], {}).get('label', c['proveedor'])}"
    if tope is None:
        return True, "", (f"{quien} no tiene tope mensual: este uso gasta dinero real "
                          f"(lleva ${g:.2f} este mes)"), "sin_tope"
    if g >= tope:
        return False, (f"tope mensual alcanzado: {quien} lleva ${g:.2f} de ${tope:.2f}. Súbele el tope en "
                       "Ajustes → Claves o activa otra clave de ese proveedor"), None, 100
    pct = g / tope if tope else 1.0
    nivel = 90 if pct >= 0.9 else 75 if pct >= 0.75 else 0
    return True, "", (f"{quien} va por el {int(pct * 100)} % de su tope (${g:.2f} de ${tope:.2f})"
                      if nivel else None), nivel


def cred_avisar(cuenta, aviso, nivel):
    """Aviso antes del uso: al log siempre; a la bandeja, sin tope en cada uso
    y al 75/90 % una vez al mes por nivel."""
    if not aviso:
        return
    log(f"claves: aviso: {aviso}")
    if nivel != "sin_tope":
        s = load_settings()
        av = s.get("credenciales_avisos") if isinstance(s.get("credenciales_avisos"), dict) else {}
        prev = av.get(cuenta) if isinstance(av.get(cuenta), dict) else {}
        if prev.get("mes") == _mes() and int(prev.get("nivel") or 0) >= int(nivel):
            return
        av[cuenta] = {"mes": _mes(), "nivel": int(nivel)}
        s["credenciales_avisos"] = av
        save_settings(s)
    try:
        toast(aviso[:140])
    except Exception:
        pass


def _cred_url(c, ruta):
    """URL hacia la base_url de ESA clave (allowlist: la clave solo va ahi)."""
    base, err = cred_validar_url(c.get("base_url"))
    if err:
        raise ValueError(f"URL base no válida: {err}")
    return base + ruta


def _cred_headers(proveedor, clave):
    h = {"User-Agent": "GrowiBridge", "Content-Type": "application/json"}
    kind = CRED_PROVIDERS[proveedor]["kind"]
    if kind == "anthropic":
        h.update({"x-api-key": clave, "anthropic-version": "2023-06-01"})
    elif kind == "gemini":
        h["x-goog-api-key"] = clave  # en cabecera: la clave nunca va en la URL (ni en un log)
    elif kind == "elevenlabs":
        h["xi-api-key"] = clave
    else:
        h["Authorization"] = f"Bearer {clave}"
    return h


def _cred_open(req, timeout):
    """urlopen; a 127.0.0.1/localhost sin proxy (el proxy local devuelve 500 falsos)."""
    host = (urllib.parse.urlsplit(req.full_url).hostname or "").lower()
    if host in ("127.0.0.1", "localhost"):
        return urllib.request.build_opener(urllib.request.ProxyHandler({})).open(req, timeout=timeout)
    return urllib.request.urlopen(req, timeout=timeout)


def cred_probar(cuenta):
    """Prueba SIN GASTAR contra la base_url de esa clave: solo pide la lista de
    modelos / el saldo / los datos de la clave; nunca inferencia. (ok, texto)."""
    c = cred_get(cuenta)
    if c is None:
        return False, "Esa clave ya no existe."
    clave = cred_clave(cuenta)
    if not clave:
        return False, f"No encuentro la clave en el almacén ({cred_via()}). No se llamó a nada."
    info = CRED_PROVIDERS[c["proveedor"]]
    pre = ""
    if c["proveedor"] == "anthropic" and not clave.startswith("sk-ant-"):
        pre = "Ojo: no tiene el formato de Anthropic (sk-ant-…). "
    try:
        url = _cred_url(c, info["test"])
    except ValueError as e:
        return False, f"{e}. No se llamó a nada, no se gastó nada."
    sp = urllib.parse.urlsplit(url)
    que = {"/key": "los datos de la clave", "/v3/account/balance": "el saldo",
           "/openapi/v1/balance": "el saldo"}.get(info["test"], "la lista de modelos")
    log(f"claves: probar {c['proveedor']} «{c['etiqueta']}» (••••{c['ultimos4']}) -> GET "
        f"{sp.scheme}://{sp.netloc}{sp.path} (host {sp.netloc}; sin gastar: solo {que})")
    nada = " No se gastó nada (solo se pidió " + que + ")."
    try:
        with _cred_open(urllib.request.Request(url, headers=_cred_headers(c["proveedor"], clave)), 20) as r:
            r.read(2000)
            code = r.status
        txt, ok = f"{pre}Clave válida ({code}).{nada}", True
    except urllib.error.HTTPError as e:
        detalle = ""
        try:
            err = json.loads(e.read(4000).decode("utf-8", "replace"))
            ee = err.get("error") if isinstance(err, dict) else None
            detalle = (ee.get("message") or ee.get("type") or "") if isinstance(ee, dict) else str(ee or err.get("message") or "")
        except Exception:
            pass
        detalle = _scrub(detalle, clave)[:200]
        base = {401: "Clave incorrecta (401)", 403: "Sin permiso (403)",
                429: "Límite de uso alcanzado (429)"}.get(e.code, f"El proveedor respondió {e.code}")
        txt, ok = f"{pre}{base}" + (f": «{detalle}»" if detalle else "") + "." + nada, False
    except urllib.error.URLError as e:
        txt, ok = (_scrub(f"{pre}Error de red ({getattr(e, 'reason', e)}): revisa el proxy o la conexión. "
                          "No se gastó nada.", clave)[:300], False)
    except Exception as e:
        txt, ok = _scrub(f"{pre}Falló ({type(e).__name__}). No se gastó nada.", clave)[:200], False
    log(f"claves: prueba de {c['proveedor']} «{c['etiqueta']}» en {sp.netloc}: {txt}")
    s = load_settings()
    pr = s.get("credenciales_pruebas") if isinstance(s.get("credenciales_pruebas"), dict) else {}
    pr[cuenta] = {"ok": ok, "texto": txt, "host": sp.netloc, "at": _now_iso()}
    s["credenciales_pruebas"] = pr
    save_settings(s)
    return ok, txt


# ---- Saldo Tripo (t-saldo-tripo, 0.3.0)
# Medidor de creditos de Tripo en la pestana Modelos: saldo REAL por API,
# generaciones estimadas a las dos calidades, aviso al 25 % del saldo de
# referencia, costo ANTES de cada generacion y registro de gasto por
# generacion (tripo-gasto.jsonl, junto a runner-results). La clave es SIEMPRE
# la de la credencial Tripo ACTIVA (Ajustes -> Claves, entrada
# growi-bridge/tripo-<etiqueta>) y va a la base URL de ESA credencial; se lee
# del almacen en el momento de la llamada y solo se le pasa a un subproceso
# por la variable de entorno TRIPO_API_KEY (nunca a un archivo, a
# engines.json, al log ni al prompt). En el Registro: tsk_…ultimos 4.
# API leida en developers.tripo3d.ai (27 oct 2026):
#   GET  /v3/account/balance -> {"code":0,"data":{"balance":..,"frozen":..}}
#        (consulta de solo lectura: no crea tareas ni gasta).
#   POST /v3/generation/{text,image,multiview}-to-model -> {"data":{"task_id":..}}
#   GET  /v3/tasks/{id} -> status queued/running/success/failed/cancelled y
#        credits_consumed (el costo real). Al crear la tarea se CONGELAN los
#        creditos; si falla o se cancela vuelven al saldo (no se cobra).
#   POST /v3/files (multipart) -> file_token de una foto local.
# La API no publica el costo ANTES de generar: se usa la tabla observada
# (~10 estandar / ~55 alta) hasta que el registro tenga gastos reales de esa
# calidad; desde entonces, la media real (nunca una tabla inventada).
TRIPO_COSTO_TABLA = {"estandar": 10.0, "alta": 55.0}
TRIPO_CALIDADES = (("estandar", "Estándar"), ("alta", "Alta calidad"))
TRIPO_CALIDAD_TXT = {"estandar": "calidad estándar", "alta": "alta calidad"}
TRIPO_TIPOS = (("multiview", "Multiview (2–4 fotos)"), ("imagen", "Imagen a 3D"), ("texto", "Texto a 3D"))
TRIPO_TIPO_TXT = {"multiview": "multiview", "imagen": "imagen a 3D", "texto": "texto a 3D"}
TRIPO_SALDO_VERIFICADO = {"creditos": 370.0, "at": "2026-10-25"}  # verificado a mano, no en vivo
TRIPO_AVISO_PCT = 25
TRIPO_RECARGA_TXT = "$10-20"
TRIPO_GASTO_FILE = OUTBOX / "tripo-gasto.jsonl"
TRIPO_MODELOS_DIR = OUTBOX / "tripo"
TRIPO_GET_SOLO_LECTURA = ("/v3/account/balance", "/v3/tasks/")
TRIPO_RUTAS = {"texto": "/v3/generation/text-to-model", "imagen": "/v3/generation/image-to-model",
               "multiview": "/v3/generation/multiview-to-model"}
TRIPO_MODELO = "v3.1-20260211"
TRIPO_VISTAS = ("front", "left", "back", "right")
_TRIPO = {"lectura": None, "leyendo": False, "gen": None, "dlg": None, "kit": None, "ctk": False}


def tripo_mask(ultimos4):
    """tsk_…ultimos 4: lo unico de la clave que llega a un log o a la pantalla."""
    return "tsk_…" + str(ultimos4 or "????")[-4:]


def _tripo_fecha(iso, hora=True):
    try:
        d = datetime.fromisoformat(str(iso).replace("Z", "+00:00"))
        if d.tzinfo is not None:
            d = d.astimezone()
    except (TypeError, ValueError):
        return str(iso or "—")
    mes = ("ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic")[d.month - 1]
    txt = f"{d.day} {mes} {d.year}"
    return txt + (d.strftime(" %H:%M") if hora and len(str(iso)) > 10 else "")


def _tripo_num(x):
    """370 -> «370»; 52.5 -> «52,5» (los creditos llevan hasta 2 decimales)."""
    x = float(x)
    return f"{x:,.0f}".replace(",", ".") if abs(x - round(x)) < 0.005 else f"{x:.2f}".rstrip("0").replace(".", ",")


def tripo_aviso_pct():
    """Umbral del aviso (en % del saldo de referencia). Vive en settings.json
    (tripo_aviso_pct) para poder cambiarlo; si falta, se escribe el 25."""
    s = load_settings()
    v = s.get("tripo_aviso_pct")
    if isinstance(v, bool) or not isinstance(v, (int, float)) or not 0 < v < 100:
        if "tripo_aviso_pct" not in s:
            s["tripo_aviso_pct"] = TRIPO_AVISO_PCT
            save_settings(s)
        v = TRIPO_AVISO_PCT
    return v


def tripo_gens(creditos, costo):
    """Generaciones que caben, redondeadas («~»), y las completas que de
    verdad alcanzan."""
    if not costo or costo <= 0:
        return 0, 0
    c = max(0.0, float(creditos))
    return int(c / costo + 0.5), int(c // costo)


def _tripo_es_local(base_url):
    return (urllib.parse.urlsplit(str(base_url or "")).hostname or "").lower() in ("127.0.0.1", "localhost")


# -- registro de gasto (una linea por evento; la ultima de cada id manda)
def tripo_gasto_registrar(entry):
    try:
        TRIPO_GASTO_FILE.parent.mkdir(parents=True, exist_ok=True)
        with open(TRIPO_GASTO_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    except OSError as e:
        log(f"tripo: no se pudo escribir {TRIPO_GASTO_FILE.name} ({e})")


def tripo_gasto_leer():
    """Las generaciones registradas (la ultima linea de cada id), en orden."""
    por_id = {}
    try:
        with open(TRIPO_GASTO_FILE, encoding="utf-8") as f:
            for ln in f:
                try:
                    e = json.loads(ln)
                except ValueError:
                    continue
                if isinstance(e, dict) and e.get("id"):
                    por_id[e["id"]] = e
    except OSError:
        pass
    return list(por_id.values())


def tripo_gasto_resumen():
    """Gasto acumulado del registro, por clave (etiqueta). Las simuladas
    (contra un servidor local) se cuentan aparte y nunca calibran nada."""
    out = {"n": 0, "reales": 0.0, "estimados_sin_dato": 0.0, "fallidas": 0, "simuladas": 0, "por_clave": {}}
    for e in tripo_gasto_leer():
        if e.get("simulada"):
            out["simuladas"] += 1
            continue
        out["n"] += 1
        k = out["por_clave"].setdefault(e.get("clave_etiqueta") or "?", {"n": 0, "reales": 0.0})
        k["n"] += 1
        if e.get("estado") != "ok":
            out["fallidas"] += 1
        r = e.get("creditos_reales")
        if isinstance(r, (int, float)):
            out["reales"] += r
            k["reales"] += r
        elif e.get("estado") in ("ok", "en_curso"):
            out["estimados_sin_dato"] += float(e.get("creditos_estimados") or 0)
    return out


def tripo_costo_estimado(calidad, tipo=None):
    """Costo de UNA generacion: la media real de las ultimas (hasta 5) de esa
    calidad (y tipo, si las hay) que devolvio la API; si no hay ninguna, la
    tabla observada. {"creditos", "fuente", "medido"}."""
    reales = [e for e in tripo_gasto_leer()
              if not e.get("simulada") and e.get("estado") == "ok" and e.get("calidad") == calidad
              and isinstance(e.get("creditos_reales"), (int, float)) and e["creditos_reales"] > 0]
    del_tipo = [e for e in reales if e.get("tipo") == tipo] if tipo else []
    usar = (del_tipo or reales)[-5:]
    if usar:
        media = round(sum(e["creditos_reales"] for e in usar) / len(usar), 2)
        que = f"{TRIPO_TIPO_TXT.get(tipo, tipo)} en {TRIPO_CALIDAD_TXT[calidad]}" if del_tipo else TRIPO_CALIDAD_TXT[calidad]
        return {"creditos": media, "medido": True,
                "fuente": f"medido: media del costo real de tus {len(usar)} última(s) de {que}"}
    return {"creditos": TRIPO_COSTO_TABLA[calidad], "medido": False,
            "fuente": "estimado: ~10 estándar / ~55 alta, observado en Tripo Studio (la API no da el "
                      "precio antes de generar)"}


# -- lectura del saldo (solo lectura, en un subproceso con la clave en su entorno)
def _tripo_sub(args, key, timeout):
    """Corre growi-bridge.py <args> <salida.json> con TRIPO_API_KEY SOLO en el
    entorno del subproceso y devuelve lo que escribio (sin la clave)."""
    import tempfile
    tmp = Path(tempfile.mkdtemp(prefix="growi-tripo-"))
    dst = tmp / "salida.json"
    env = dict(os.environ)
    env["TRIPO_API_KEY"] = key
    try:
        p = subprocess.run([sys.executable, str(Path(__file__).resolve())] + list(args) + [str(dst)],
                           capture_output=True, timeout=timeout, cwd=str(APP_DIR), env=env, **_oculto())
        try:
            return json.loads(dst.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            err = (p.stderr or b"").decode("utf-8", "replace")[-300:]
            return {"ok": False, "error": _scrub(f"el subproceso no devolvió datos ({err.strip() or p.returncode})", key)}
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "la consulta tardó demasiado y se cortó"}
    finally:
        env.pop("TRIPO_API_KEY", None)
        try:
            dst.unlink()
        except OSError:
            pass
        try:
            tmp.rmdir()
        except OSError:
            pass


def tripo_leer_saldo(manual=False):
    """Lee el saldo REAL de la credencial Tripo activa (GET /v3/account/balance,
    solo lectura). Sin clave guardada no llama a nada. Tras un 401 no vuelve a
    intentarlo solo (solo con «Volver a leer» o al cambiar la clave)."""
    lec = {"at": _now_iso(), "ok": False, "en_vivo": False}
    c = cred_activa("tripo")
    if c is None:
        lec.update(motivo="sin_clave", texto="saldo no disponible — falta guardar la clave en Ajustes → APIs")
        _TRIPO["lectura"] = lec
        return lec
    lec.update(cuenta=c["cuenta"], etiqueta=c["etiqueta"], ultimos4=c["ultimos4"], base_url=c["base_url"])
    host = urllib.parse.urlsplit(c["base_url"]).netloc
    quien = f"«{c['etiqueta']}» ({tripo_mask(c['ultimos4'])})"
    s = load_settings()
    rech = s.get("tripo_clave_rechazada") if isinstance(s.get("tripo_clave_rechazada"), dict) else None
    if rech and rech.get("cuenta") == c["cuenta"] and rech.get("ultimos4") == c["ultimos4"] and not manual:
        lec.update(motivo="invalida", http=rech.get("http"),
                   texto=f"clave inválida o revocada ({rech.get('http') or 401}, visto el "
                         f"{_tripo_fecha(rech.get('at'))}): no se vuelve a intentar sola. Cámbiala en "
                         "Ajustes → APIs o pulsa «Volver a leer».")
        _TRIPO["lectura"] = lec
        return lec
    key = cred_clave(c["cuenta"])
    if not key:
        lec.update(motivo="sin_clave", texto=f"saldo no disponible — la clave {quien} está en la lista pero no "
                                             f"en el almacén ({cred_via()}): vuelve a guardarla en Ajustes → APIs")
        _TRIPO["lectura"] = lec
        return lec
    log(f"tripo: leyendo el saldo de {quien} -> GET {host}/v3/account/balance (solo lectura, no gasta)")
    r = _tripo_sub(["--tripo-saldo", c["base_url"]], key, 90)
    key = None
    s = load_settings()
    if r.get("ok"):
        cr = float(r["creditos"])
        lec.update(ok=True, en_vivo=True, creditos=cr, congelados=float(r.get("congelados") or 0))
        s["tripo_saldo"] = {"cuenta": c["cuenta"], "etiqueta": c["etiqueta"], "ultimos4": c["ultimos4"],
                            "creditos": cr, "congelados": lec["congelados"], "at": lec["at"],
                            # Guardado = ya no es en vivo: asi se muestra si la proxima lectura falla.
                            "estado": "último saldo leído, no en vivo"}
        refs = s.get("tripo_saldo_ref") if isinstance(s.get("tripo_saldo_ref"), dict) else {}
        ref = refs.get(c["cuenta"]) if isinstance(refs.get(c["cuenta"]), dict) else None
        if ref is None or ref.get("ultimos4") != c["ultimos4"] or cr > float(ref.get("creditos") or 0):
            # Referencia = el saldo de la primera lectura con esta clave (o el
            # de despues de una recarga, si sube).
            refs[c["cuenta"]] = {"creditos": cr, "at": lec["at"], "ultimos4": c["ultimos4"],
                                 "motivo": "recarga" if ref and ref.get("ultimos4") == c["ultimos4"] else "clave guardada"}
            s["tripo_saldo_ref"] = refs
        if rech and rech.get("cuenta") == c["cuenta"]:
            s.pop("tripo_clave_rechazada", None)
        save_settings(s)
        log(f"tripo: saldo de {quien} en {host}: {_tripo_num(cr)} créditos (+{_tripo_num(lec['congelados'])} "
            "congelados por tareas en curso); no se gastó nada")
    elif r.get("http") == 401 or r.get("codigo") in (1000, 1001):
        lec.update(motivo="invalida", http=r.get("http") or 401,
                   texto=f"clave inválida o revocada ({r.get('http') or 401}): no se vuelve a intentar sola. "
                         "Cámbiala en Ajustes → APIs o pulsa «Volver a leer».")
        s["tripo_clave_rechazada"] = {"cuenta": c["cuenta"], "ultimos4": c["ultimos4"], "at": lec["at"],
                                      "http": r.get("http") or 401}
        save_settings(s)
        log(f"tripo: {host} rechazó la clave {quien} ({r.get('http') or 401}): marcada «clave inválida o "
            "revocada»; no se reintenta sola")
    else:
        lec.update(motivo="error", http=r.get("http"),
                   texto=f"no se pudo leer el saldo: {r.get('error') or 'sin respuesta'}")
        log(f"tripo: no se pudo leer el saldo de {quien} en {host}: {r.get('error') or 'sin respuesta'}")
    _TRIPO["lectura"] = lec
    return lec


def tripo_estado():
    """Todo lo que muestra el medidor, calculado de la ultima lectura (o del
    ultimo saldo conocido, que se marca «no en vivo»)."""
    s = load_settings()
    c = cred_activa("tripo")
    lec = _TRIPO.get("lectura")
    if lec and lec.get("cuenta") != (c or {}).get("cuenta"):
        lec = None  # se cambio (o se borro) la clave activa: esa lectura ya no vale
    ult = s.get("tripo_saldo") if isinstance(s.get("tripo_saldo"), dict) else None
    if ult and (c is None or ult.get("cuenta") != c["cuenta"]):
        ult = None
    st = {"clave": c, "lectura": lec, "pct": tripo_aviso_pct()}
    if lec and lec.get("ok"):
        st.update(creditos=lec["creditos"], congelados=lec.get("congelados") or 0, en_vivo=True,
                  at=lec["at"], fuente="en vivo")
    elif ult:
        st.update(creditos=float(ult["creditos"]), congelados=0, en_vivo=False, at=ult.get("at"),
                  fuente=f"último saldo leído, no en vivo (leído el {_tripo_fecha(ult.get('at'))})")
    else:
        st.update(creditos=TRIPO_SALDO_VERIFICADO["creditos"], congelados=0, en_vivo=False,
                  at=TRIPO_SALDO_VERIFICADO["at"],
                  fuente=f"último saldo verificado, no en vivo ({_tripo_fecha(TRIPO_SALDO_VERIFICADO['at'])})")
    if lec and not lec.get("ok"):
        st["problema"] = lec.get("texto")
        st["motivo"] = lec.get("motivo")
    elif c is None:
        st["problema"] = "saldo no disponible — falta guardar la clave en Ajustes → APIs"
        st["motivo"] = "sin_clave"
    refs = s.get("tripo_saldo_ref") if isinstance(s.get("tripo_saldo_ref"), dict) else {}
    ref = refs.get(c["cuenta"]) if c and isinstance(refs.get(c["cuenta"]), dict) else None
    st["ref"] = float(ref["creditos"]) if ref else TRIPO_SALDO_VERIFICADO["creditos"]
    st["ref_txt"] = (f"del saldo de cuando guardaste la clave ({_tripo_num(ref['creditos'])} créditos, "
                     f"{_tripo_fecha(ref.get('at'), False)})" if ref
                     else f"de {_tripo_num(TRIPO_SALDO_VERIFICADO['creditos'])} créditos (sin otro dato)")
    st["costos"] = {q: tripo_costo_estimado(q) for q, _l in TRIPO_CALIDADES}
    st["gens"] = {q: tripo_gens(st["creditos"], st["costos"][q]["creditos"]) for q, _l in TRIPO_CALIDADES}
    st["aviso"] = st["creditos"] <= st["ref"] * st["pct"] / 100.0
    st["aviso_txt"] = tripo_aviso_texto(st) if st["aviso"] else ""
    return st


def tripo_aviso_texto(st):
    pct = _tripo_num(st["pct"])
    return (f"Te queda el {pct}% o menos de tu saldo Tripo ({_tripo_num(st['creditos'])} créditos, "
            f"~{st['gens']['alta'][0]} generaciones de alta calidad). La próxima recarga ronda {TRIPO_RECARGA_TXT}."
            + ("" if st["en_vivo"] else " (Con el último saldo conocido, no en vivo.)"))


def tripo_gens_txt(st, creditos=None):
    cr = st["creditos"] if creditos is None else creditos
    partes = []
    for q, _l in TRIPO_CALIDADES:
        costo = st["costos"][q]["creditos"]
        aprox, enteras = tripo_gens(cr, costo)
        partes.append(f"~{aprox} a {TRIPO_CALIDAD_TXT[q]} (~{_tripo_num(costo)} créditos c/u"
                      + (f"; {enteras} completas" if enteras != aprox else "") + ")")
    return ", ".join(partes)


def tripo_costo_texto(st, calidad, tipo=None):
    """«Esta generación cuesta ~10 créditos, te quedan 360…» (antes de lanzar)."""
    est = tripo_costo_estimado(calidad, tipo)
    quedan = st["creditos"] - est["creditos"]
    txt = (f"Esta generación cuesta ~{_tripo_num(est['creditos'])} créditos en {TRIPO_CALIDAD_TXT[calidad]}, "
           f"te quedan {_tripo_num(max(0, quedan))}" + ("" if st["en_vivo"] else " (según el saldo no en vivo)")
           + f". Después: {tripo_gens_txt(st, max(0, quedan))}.")
    return txt, est, quedan


def migrar_apis_json():
    """apis.json de la 0.2.0 (una clave por servicio, en texto plano) -> una
    clave con etiqueta «principal» y su base URL por defecto, sin volver a
    pegarla. No borra apis.json (lo borra Leandro desde Ajustes -> Claves)."""
    if not APIS_FILE.is_file():
        return 0
    hechas = 0
    for a in load_apis():
        if not isinstance(a, dict):
            continue
        nombre = str(a.get("name") or "").strip()
        key = str(a.get("key") or "").strip()
        prov = a.get("provider") if a.get("provider") in CRED_PROVIDERS else cred_proveedor_de(nombre)
        if not key:
            continue
        if not prov:
            log(f"claves: migración: «{nombre}» de apis.json no es de ningún proveedor conocido; queda sin migrar")
            continue
        ya = [c for c in cred_lista() if c["proveedor"] == prov]
        if any(cred_clave(c["cuenta"]) == key for c in ya):
            continue
        etq = "principal" if not any(c["cuenta"] == f"{prov}-principal" for c in ya) else f"principal {len(ya) + 1}"
        ok, msg = cred_guardar(prov, etq, None, key)
        log(f"claves: migración de apis.json: {prov} «{etq}»: {msg if ok else 'falló: ' + msg}")
        hechas += 1 if ok else 0
    return hechas


def api_cred(provider):
    """(clave, credencial) de la clave ACTIVA de ese proveedor, o ("", None)."""
    c = cred_activa(provider)
    if c is None:
        return "", None
    return cred_clave(c["cuenta"]) or "", c


def api_key_for(provider):
    return api_cred(provider)[0]


def api_model_for(provider):
    """Modelo por defecto de cada proveedor (se cambia en settings.json,
    clave api_models)."""
    custom = (load_settings().get("api_models") or {}).get(provider)
    if isinstance(custom, str) and valid_model_name(custom):
        return custom
    return API_PROVIDERS[provider]["model"]


def _api_headers(provider, key):
    h = {"User-Agent": "GrowiBridge", "Content-Type": "application/json"}
    if provider == "anthropic":
        h.update({"x-api-key": key, "anthropic-version": "2023-06-01"})
    else:
        # Gemini tambien acepta Bearer en su ruta compatible con OpenAI.
        h["Authorization"] = f"Bearer {key}"
    return h


def _scrub(text, key):
    """Quita cualquier rastro de la clave de un mensaje de error."""
    t = str(text or "")
    if key:
        t = t.replace(key, mask_key(key))
    return re.sub(r"(sk|gsk|AIza|sk-ant|sk-or)[-_A-Za-z0-9]{8,}", r"\1-…", t)


def _http_reason(code):
    return {400: "petición rechazada (400)", 401: "clave rechazada (401)",
            403: "sin permiso (403)", 404: "no encontrado (404)",
            429: "límite de uso alcanzado (429)"}.get(
        code, f"el servicio falló ({code})" if code >= 500 else f"error {code}")


def test_api(provider):
    """Prueba sin gastar de la clave ACTIVA de ese proveedor, contra SU base
    URL (cred_probar). Devuelve (ok, motivo corto)."""
    if provider not in CRED_PROVIDERS:
        return False, "proveedor desconocido"
    c = cred_activa(provider)
    if c is None:
        return False, "falta la clave (ninguna activa en Ajustes → Claves)"
    return cred_probar(c["cuenta"])


def _run_api(task):
    """Motor por API: model 'api:<proveedor>:<modelo>'. OpenAI, Groq,
    OpenRouter y Gemini por /chat/completions (Bearer); Anthropic por
    /v1/messages. Un turno; cost_usd = null (lo cobra el proveedor)."""
    started = _now_iso()
    t0 = time.time()
    _, provider, model = task["model"].split(":", 2)
    info = API_PROVIDERS[provider]
    result = {
        "runner": f"growi-bridge/{VERSION}", "id": task["id"], "status": "error",
        "started_at": started, "finished_at": None, "duration_s": None,
        "exit_code": None, "result": "", "cost_usd": None, "num_turns": 1,
        "session_id": None, "stderr": "", "error": None,
    }
    # La clave ACTIVA de ese proveedor (Ajustes -> Claves), a SU base_url.
    key, cred = api_cred(provider)
    puede = cred_puede_usar(cred["cuenta"]) if cred and key else None
    if cred is None:
        result["error"] = f"no hay ninguna clave activa de {info['label']} (Ajustes → Claves)"
    elif not key:
        result["error"] = (f"la clave activa «{cred['etiqueta']}» de {info['label']} no está en el "
                           f"almacén ({cred_via()})")
    elif not puede[0]:
        result["error"] = puede[1]
        log(f"runner [{task['id']}]: bloqueado: {puede[1]}")
    else:
        cred_avisar(cred["cuenta"], puede[2], puede[3])
        result["credencial_usada"] = {"proveedor": provider, "etiqueta": cred["etiqueta"],
                                      "cuenta": cred["cuenta"], "ultimos4": cred["ultimos4"]}
        prompt = prompt_de_tarea(task)
        cp = CRED_PROVIDERS[provider]
        url = _cred_url(cred, cp["chat"])
        if info["kind"] == "anthropic":
            body = {"model": model, "max_tokens": 4096,
                    "messages": [{"role": "user", "content": prompt}]}
        else:
            body = {"model": model, "messages": [{"role": "user", "content": prompt}]}
        log(f"runner [{task['id']}]: llamando a {info['label']} ({model}) con la clave «{cred['etiqueta']}» "
            f"(••••{cred['ultimos4']}) en {urllib.parse.urlsplit(url).netloc}")
        req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"),
                                     headers=_cred_headers(provider, key), method="POST")
        try:
            with _cred_open(req, task["timeout_min"] * 60) as r:
                data = json.loads(r.read().decode("utf-8", "replace"))
            if info["kind"] == "anthropic":
                text = "".join(b.get("text", "") for b in data.get("content", [])
                               if isinstance(b, dict))
            else:
                text = data["choices"][0]["message"]["content"] or ""
            result["result"] = str(text)[:MAX_RESULT_CHARS]
            result["status"] = "ok"
            result["exit_code"] = 0
            us = data.get("usage") if isinstance(data.get("usage"), dict) else {}
            tin = us.get("input_tokens", us.get("prompt_tokens"))
            tout = us.get("output_tokens", us.get("completion_tokens"))
            if isinstance(tin, int) or isinstance(tout, int):
                result["uso"] = {"tokens_in": tin or 0, "tokens_out": tout or 0, "modelo_real": model,
                                 "por_modelo": {model: {"tokens_in": tin or 0, "tokens_out": tout or 0,
                                                        "cost_usd": None}},
                                 "fuente": "al cerrar"}
                live_tokens("tarea", model, tin, tout, modo="al cerrar")
        except urllib.error.HTTPError as e:
            detail = ""
            try:
                err = json.loads(e.read().decode("utf-8", "replace"))
                detail = (err.get("error") or {}).get("message", "") \
                    if isinstance(err.get("error"), dict) else str(err.get("error", ""))
            except Exception:
                pass
            result["error"] = _scrub(f"{info['label']}: {_http_reason(e.code)}"
                                     + (f" — {detail[:200]}" if detail else ""), key)
        except urllib.error.URLError as e:
            result["error"] = _scrub(f"{info['label']}: sin conexión ({getattr(e, 'reason', e)})", key)
        except Exception as e:
            result["error"] = _scrub(f"{info['label']}: {type(e).__name__}: {e}", key)[:300]
    result["finished_at"] = _now_iso()
    result["duration_s"] = round(time.time() - t0, 1)
    return result


# ---------------------------------------------------------------- runner
POLL_SECONDS = 5
HEARTBEAT_SECONDS = 60
MAX_PROMPT_CHARS = 100_000
DEFAULT_TIMEOUT_MIN = 30
MAX_TIMEOUT_MIN = 120
# Sin un evento del motor en este tiempo, el intento se da por colgado y se
# mata (arbol completo). Es inactividad, no duracion: el limite total sigue
# siendo timeout_min. Solo para pruebas: GROWI_NO_PROGRESS_S.
NO_PROGRESS_TIMEOUT_S = 300
NO_PROGRESS_TXT = "lanzamiento sin progreso en 5 min"
MAX_RESULT_CHARS = 20_000
MAX_STDERR_CHARS = 2_000
ALLOWED_MODELS = {"sonnet", "opus", "haiku"}
SAFE_ID_CHARS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")


def _now_iso():
    return datetime.now().astimezone().isoformat(timespec="seconds")


def _ts_iso(t):
    return datetime.fromtimestamp(t).astimezone().isoformat(timespec="seconds")


def no_progress_s():
    try:
        v = int(os.environ.get("GROWI_NO_PROGRESS_S") or NO_PROGRESS_TIMEOUT_S)
        return v if v > 0 else NO_PROGRESS_TIMEOUT_S
    except ValueError:
        return NO_PROGRESS_TIMEOUT_S


def _safe_id(task_id):
    return (
        isinstance(task_id, str)
        and 1 <= len(task_id) <= 80
        and all(c in SAFE_ID_CHARS for c in task_id)
        and ".." not in task_id
    )


def _inside_any(cwd, roots):
    try:
        cwd_s = str(cwd)
        for r in roots:
            r_s = str(Path(r).resolve())
            if os.path.commonpath([cwd_s, r_s]) == r_s:
                return True
    except ValueError:
        pass
    return False


# ---------------------------------------------------------------- carriles
# Carril B: copia de la app en otra carpeta, con su puerto y su cola, para
# trabajo que NO toca los archivos del carril A (verificaciones, documentos,
# prototipos en su carpeta). No es paralelo de codigo: es separacion de
# carpetas con esta guardia. Los carriles no se fusionan solos.
LANE_A_DIR = Path(os.environ.get("GROWI_BRIDGE_LANE_A_DIR") or (HOME_DIR / "growi-bridge"))
# Carril B: solo los motores con "carril_b": true en engines.json (nube; la
# VRAM es del carril A).
LANE_A_ESPERA_MAX_S = 600
LANE_A_STATUS_VIEJO_S = 180


def _lane_norm(path, base=None):
    pth = Path(str(path)).expanduser()
    if not pth.is_absolute():
        pth = Path(base or APP_DIR) / pth
    return os.path.normcase(os.path.abspath(str(pth)))


def _lane_inside(path_n, root):
    root_n = _lane_norm(root)
    try:
        return os.path.commonpath([path_n, root_n]) == root_n
    except ValueError:
        return False


def _lane_b_prohibidos():
    """(archivos, carpetas) que un task del carril B nunca puede tocar."""
    files = [d / n for d in (LANE_A_DIR, APP_DIR)
             for n in ("growi-bridge.py", "runner.py", "engines.json", "settings.json")]
    files.append(LANE_A_DIR / "share" / "inbox" / "runner" / "runner.py")
    dirs = [LANE_A_DIR / "share" / "inbox" / "growi-bridge-app"]
    return files, dirs


def _lane_guard(data):
    """None si el task puede correr en este carril; si no, el motivo exacto."""
    lane = str(data.get("lane") or "").strip().lower()
    if LANE == "a":
        if lane in ("", "a"):
            return None
        return (f'este task trae "lane": "{data.get("lane")}" y este es el carril A '
                f'(puerto {BRIDGE_PORT}); los del carril B van a growi-bridge-lane2 (puerto 8788)')
    if lane != "b":
        return ('carril B: rechazado sin ejecutar: el task no trae "lane": "b"'
                + (f' (trae "lane": "{data.get("lane")}")' if lane else "")
                + '. Este carril solo corre tareas marcadas para él')
    if "ollama_action" in data:
        return ("carril B: rechazado sin ejecutar: pide modelos locales (ollama_action). El "
                "carril B nunca usa llama-server ni ollama: dos modelos locales a la vez en "
                "6 GB de VRAM se pelean la memoria")
    archivos = data.get("archivos")
    if (not isinstance(archivos, list) or not archivos
            or not all(isinstance(a, str) and a.strip() for a in archivos)):
        return ('carril B: rechazado sin ejecutar: falta la lista "archivos" (los archivos que '
                'la tarea va a tocar), o está vacía o no es una lista de rutas')
    files, dirs = _lane_b_prohibidos()
    prohib = {_lane_norm(f) for f in files}
    for a in archivos:
        an = _lane_norm(a.strip())
        if an in prohib or any(_lane_inside(an, d) for d in dirs):
            return (f"carril B: rechazado sin ejecutar: declara {a} en \"archivos\", que está en "
                    "la lista prohibida (growi-bridge.py, runner.py, engines.json, settings.json "
                    "y share\\inbox\\growi-bridge-app del carril A, y el código del propio carril B)")
        if not _lane_inside(an, APP_DIR):
            return (f"carril B: rechazado sin ejecutar: declara {a} en \"archivos\", que está "
                    f"fuera de la carpeta del carril B ({APP_DIR})")
    lee = data.get("lee")
    if lee is not None and (not isinstance(lee, list)
                            or not all(isinstance(x, str) and x.strip() for x in lee)):
        return 'carril B: rechazado sin ejecutar: "lee" debe ser una lista de rutas'
    cwd = _lane_norm(data.get("cwd") or APP_DIR)
    if not _lane_inside(cwd, APP_DIR):
        return (f"carril B: rechazado sin ejecutar: cwd {data.get('cwd')} está fuera de la "
                f"carpeta del carril B ({APP_DIR})")
    return None


def _lane_lee_carril_a(data):
    """True si la tarea declara que lee archivos del carril A."""
    if data.get("lee_carril_a") is True:
        return True
    return any(_lane_inside(_lane_norm(x), LANE_A_DIR) for x in (data.get("lee") or []))


def _lane_a_libre():
    """(libre, detalle) segun runner-status.json del carril A: libre solo con
    current null y un latido reciente (un latido viejo no prueba nada)."""
    path = LANE_A_DIR / "share" / "outbox" / "runner-status.json"
    try:
        st = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return False, f"no pude leer {path} ({type(e).__name__})"
    if st.get("current"):
        cur = st["current"]
        return False, f"el carril A trabaja en {cur.get('id') if isinstance(cur, dict) else cur}"
    try:
        edad = time.time() - datetime.fromisoformat(str(st.get("last_poll"))).timestamp()
    except (TypeError, ValueError):
        return False, "runner-status.json del carril A sin last_poll válido"
    if edad > LANE_A_STATUS_VIEJO_S:
        return False, (f"el latido del carril A tiene {int(edad)} s (más de "
                       f"{LANE_A_STATUS_VIEJO_S} s): no puedo confirmar que esté libre")
    return True, "carril A libre (current null, latido de hace %d s)" % int(edad)


def _lane_b_espera_a(task):
    """Regla de verificacion: si la tarea lee archivos del carril A, espera a
    que el carril A este libre (max. 10 min). None si puede seguir; si no,
    el motivo."""
    if LANE != "b" or not task.get("lee_carril_a"):
        return None
    t0 = time.time()
    while True:
        libre, det = _lane_a_libre()
        if libre:
            log(f"runner [{task['id']}]: {det}; la tarea puede leer el carril A")
            return None
        if time.time() - t0 >= LANE_A_ESPERA_MAX_S:
            return (f"carril B: no se ejecutó: la tarea lee archivos del carril A y el carril A "
                    f"no quedó libre en {LANE_A_ESPERA_MAX_S // 60} min ({det}); no leo archivos "
                    "a mitad de escritura")
        state["paso"] = f"esperando a que el carril A quede libre ({det})"
        log(f"runner [{task['id']}]: espera al carril A: {det}")
        time.sleep(15)


def _lane_snapshot():
    """Huella (tamaño, mtime) de lo prohibido, para avisar si cambió durante
    una tarea del carril B (el carril A también puede cambiarlo: es un aviso)."""
    files, dirs = _lane_b_prohibidos()
    files = [f for f in files if f != APP_DIR / "settings.json"]  # lo escribe la propia app
    snap = {}
    for f in files:
        try:
            st = f.stat()
            snap[str(f)] = (st.st_size, st.st_mtime)
        except OSError:
            snap[str(f)] = None
    for d in dirs:
        try:
            for f in d.iterdir():
                if f.is_file():
                    st = f.stat()
                    snap[str(f)] = (st.st_size, st.st_mtime)
        except OSError:
            pass
    return snap


def validate_task(data):
    if not isinstance(data, dict):
        return None, "el task.json no es un objeto JSON"
    task_id = data.get("id")
    if not _safe_id(task_id):
        return None, "id invalido o ausente (solo letras, numeros, - _ .)"
    lane_err = _lane_guard(data)
    if lane_err:
        return None, lane_err
    if "ollama_action" in data:
        return _validate_model_task(data, task_id)
    prompt = data.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        return None, "prompt vacio o ausente"
    if len(prompt) > MAX_PROMPT_CHARS:
        return None, f"prompt demasiado largo ({len(prompt)} > {MAX_PROMPT_CHARS})"
    asis, asis_err = asis_para_tarea(data)  # asistente (perfil): el que dice la tarea o el activo
    if asis_err:
        return None, asis_err
    cwd_raw = data.get("cwd") or asis_cwd_defecto(asis) or str(APP_DIR if LANE == "b" else INBOX)
    try:
        cwd = Path(cwd_raw).expanduser().resolve()
    except OSError:
        return None, f"cwd invalido: {cwd_raw}"
    if not cwd.is_dir():
        return None, f"cwd no existe o no es carpeta: {cwd}"
    if not _inside_any(cwd, load_folders()) and not es_worktree_agente(cwd):
        return None, f"cwd fuera de las carpetas permitidas: {cwd}"
    if asis is not None and not _inside_any(cwd, asis_raices(asis)):
        return None, asis_fuera_txt(asis, cwd)  # las carpetas que ve el asistente
    # Motor: el campo "motor" (engines.json). Sin el, como antes: model
    # "ollama:<m>" -> motor ollama, "api:..." -> APIs, lo demas -> claude.
    model = data.get("modelo") if data.get("modelo") is not None else data.get("model")
    motor = data.get("motor")
    enrutado = None
    # Ciclo de vida del motor local (t-ciclo-vida-llama): "modelo_local" = el
    # .gguf (sin extension) que el runner carga antes de ejecutar; manda sobre
    # "modelo". Sin "motor", va al motor con servidor de engines.json.
    modelo_local = data.get("modelo_local")
    if modelo_local is not None:
        if not isinstance(modelo_local, str) or not valid_model_name(modelo_local) or "/" in modelo_local:
            return None, f"modelo_local no válido: {modelo_local!r} (es el nombre del .gguf sin extensión)"
        if motor is None:
            locales = motores_con_servidor()
            if not locales:
                return None, "modelo_local pedido, pero ningún motor de engines.json tiene servidor local"
            motor = locales[0]
        if motor != AUTO and not (get_engine(motor) or {}).get("servidor"):
            return None, (f"modelo_local solo vale con un motor local con servidor ({', '.join(motores_con_servidor()) or 'ninguno'}); "
                          f"el motor {motor} no carga modelos locales")
        model = modelo_local
    liberar_vram = data.get("liberar_vram")
    if liberar_vram is True:
        liberar_vram = "antes"
    elif liberar_vram == "después":
        liberar_vram = "despues"
    if liberar_vram not in (None, False, "antes", "despues"):
        return None, 'liberar_vram debe ser true, "antes" o "despues"'
    if motor is None and model is None and asis is not None:
        motor = asis_motor_tarea(asis)  # el modelo por defecto del asistente (None: el de siempre)
    if motor == AUTO or (motor is None and model is None and global_auto()):
        # Modo Automatico: reglas de engines.json -> router ($0, sin modelo).
        crit0 = data.get("criterios")
        crit0 = [crit0] if isinstance(crit0, str) else crit0 if isinstance(crit0, list) else []
        enrutado, err = route_task(prompt, crit0)
        if enrutado:
            data["_enrutado"] = enrutado
        if err:
            return None, err
        motor, model = enrutado["motor"], enrutado.get("modelo")
        log(f"router [{task_id}]: Automático -> {enrutado['motivo']}")
    elif isinstance(data.get("enrutado"), dict) and data["enrutado"].get("elegido"):
        # Ronda o fase de una tarea Automatica: hereda la eleccion, no se re-enruta.
        e = data["enrutado"]
        enrutado = {"elegido": str(e["elegido"])[:40], "motivo": str(e.get("motivo") or "")[:400]}
    if motor is None:
        # Forma vieja: "model": "<motor>:<modelo>" (p. ej. "ollama:default")
        # -> ese motor; "api:..." -> APIs; sin nada -> el de por defecto.
        pref = model.split(":", 1)[0] if isinstance(model, str) and ":" in model else None
        if pref == "api":
            motor = "api"
        elif pref and pref in engine_ids():
            motor, model = pref, model.split(":", 1)[1]
        else:
            motor = default_motor()
    if not isinstance(motor, str) or not _safe_id(motor):
        return None, f"motor invalido: {motor}"
    eng = get_engine(motor)
    if LANE == "b" and not (eng or {}).get("carril_b"):
        return None, (f"carril B: rechazado sin ejecutar: el motor '{motor}' no es de nube. El "
                      "carril B solo usa los motores con carril_b en engines.json (claude, codex); "
                      "nunca llama-server ni ollama (dos modelos locales a la vez en 6 GB de VRAM "
                      "se pelean la memoria)")
    if motor != "api" and eng is None:
        return None, (f"el motor '{motor}' no existe en engines.json "
                      f"(hay: {', '.join(engine_ids())})")
    if motor in motores_apagados():
        return None, f"el motor '{motor}' está desactivado (actívalo en Modelos → Motores)"
    permitidos = ((eng or {}).get("modelo") or {}).get("permitidos")
    if motor != "api" and not permitidos:
        if model in ("", "default"):
            model = None
        if model is not None and not valid_model_name(model):
            return None, f"modelo no valido para {motor}: {model}"
    if permitidos and model is not None:
        # modelo.permitidos del descriptor ('claude-*' = cualquiera que empiece asi)
        import fnmatch
        if not isinstance(model, str) or not any(fnmatch.fnmatchcase(model, str(p)) for p in permitidos):
            return None, f"model no permitido: {model}"
    if motor == "api":
        if not isinstance(model, str) or not model.startswith("api:"):
            return None, "model api invalido: usa api:<proveedor>:<modelo>"
        parts = model.split(":", 2)
        if len(parts) != 3 or parts[1] not in API_PROVIDERS:
            return None, ("model api invalido: usa api:<proveedor>:<modelo> con "
                          "proveedor " + "/".join(API_ORDER))
        if parts[2] in ("", "default"):
            model = f"api:{parts[1]}:{api_model_for(parts[1])}"
        elif not valid_model_name(parts[2]):
            return None, f"modelo de API no valido: {parts[2]}"
    allowed_tools = data.get("allowed_tools")
    if allowed_tools is not None and (
        not isinstance(allowed_tools, str) or not allowed_tools.strip()
    ):
        return None, "allowed_tools debe ser texto no vacio"
    permission_mode = data.get("permission_mode")
    if permission_mode is not None and permission_mode not in (
        "acceptEdits", "plan", "default", "bypassPermissions",
    ):
        return None, f"permission_mode no permitido: {permission_mode}"
    por_modo = ((eng or {}).get("permisos") or {}).get("por_modo")
    if isinstance(por_modo, dict) and (permission_mode or "") not in por_modo:
        return None, (f"el motor {motor} no acepta permission_mode={permission_mode} "
                      f"(acepta: {', '.join(k or 'ninguno' for k in por_modo)})")
    session_id = data.get("session_id")
    if session_id is not None and not _safe_id(session_id):
        return None, f"session_id invalido: {session_id}"
    try:
        timeout_min = int(data.get("timeout_min") or (eng or {}).get("timeout_min")
                          or DEFAULT_TIMEOUT_MIN)
    except (TypeError, ValueError):
        return None, "timeout_min debe ser un numero"
    timeout_min = max(1, min(MAX_TIMEOUT_MIN, timeout_min))
    # Orquestacion: criterios de aceptacion, rondas de correccion y fases.
    # Frases (las juzga el juez) y objetos tipados (los comprueba el codigo):
    # un tipado mal formado se rechaza aqui, al encolar, con su motivo claro.
    criterios, criterios_tipados, crit_err = separar_criterios(data.get("criterios"), cwd)
    if crit_err:
        return None, crit_err
    try:
        ronda = int(data.get("ronda") or 0)
    except (TypeError, ValueError):
        return None, "ronda debe ser un numero"
    if not 0 <= ronda <= MAX_ROUNDS:
        return None, f"ronda fuera de rango (0 a {MAX_ROUNDS})"
    refs = {}
    for k in ("tarea_padre", "raiz", "fase_base", "fase_anterior"):
        v = data.get(k)
        if v is not None and not _safe_id(v):
            return None, f"{k} invalido: {v}"
        refs[k] = v
    fase = data.get("fase")
    if fase is not None and (not isinstance(fase, str) or len(fase) > 80):
        return None, "fase debe ser un texto corto (p. ej. 'fase 1 de 3')"
    sig = data.get("siguiente_fase")
    if sig is not None:
        sp = sig.get("prompt") if isinstance(sig, dict) else sig
        if not isinstance(sp, str) or not sp.strip() or len(sp) > MAX_PROMPT_CHARS:
            return None, "siguiente_fase debe ser el prompt de la fase siguiente (o {\"prompt\": ...})"
    sensible = data.get("sensible") or []
    if isinstance(sensible, str):
        sensible = [sensible]
    if not isinstance(sensible, list) or not all(s in SENSITIVE for s in sensible):
        return None, f"sensible debe ser una lista de: {', '.join(SENSITIVE)}"
    # Acciones declaradas (tipo de riesgos.json + alcance): lo mas fiable para el nivel R0-R3.
    acciones = data.get("acciones") or []
    if isinstance(acciones, dict):
        acciones = [acciones]
    if not isinstance(acciones, list) or not all(isinstance(a, dict) and isinstance(a.get("tipo"), str)
                                                  for a in acciones):
        return None, 'acciones debe ser una lista de {"tipo": ..., "ruta"?: ..., "usd"?: ...}'
    acciones = [{k: a[k] for k in ("tipo", "ruta", "usd", "recursivo", "destino") if k in a}
                for a in acciones[:20]]
    canal = data.get("canal")
    if canal is not None and (not isinstance(canal, str) or not _safe_id(canal)):
        return None, f"canal invalido: {canal}"
    return {
        "id": task_id, "prompt": prompt, "cwd": str(cwd),
        "model": model if motor == "api" or permitidos else None,
        "motor": motor, "modelo": model if motor != "api" else model,
        "allowed_tools": allowed_tools, "permission_mode": permission_mode,
        "session_id": session_id, "timeout_min": timeout_min,
        "criterios": criterios, "criterios_tipados": criterios_tipados, "ronda": ronda,
        "tarea_padre": refs["tarea_padre"], "raiz": refs["raiz"] or task_id,
        "fase": fase, "siguiente_fase": sig, "fase_base": refs["fase_base"],
        "fase_anterior": refs["fase_anterior"], "sensible": sensible,
        "acciones": acciones, "canal": canal,
        "modelo_local": modelo_local, "liberar_vram": liberar_vram or None,
        # true (completa, con juez) | false (sin revision) | "solo_checks"
        # (solo checks deterministas, sin juez: t-revision-solo-checks).
        "revisar": ("solo_checks" if str(data.get("revisar")).strip().lower() in ("solo_checks", "solo-checks")
                    else data.get("revisar", True) is not False),
        "memoria": data.get("memoria", True) is not False,
        "herramienta": data.get("herramienta") if isinstance(data.get("herramienta"), dict) else None,
        "dag": data.get("dag") if isinstance(data.get("dag"), dict) else None,
        "presupuesto_max_usd": (float(data["presupuesto_max_usd"]) if isinstance(data.get("presupuesto_max_usd"),
                                                                                  (int, float))
                                and data["presupuesto_max_usd"] > 0 else
                                # «no gastes más de $X en esto» dicho en el encargo
                                (float(_m.group(1).replace(",", ".")) if (_m := _FRENO_RE.search(
                                    str(data.get("prompt") or ""))) else None)),
        "proyecto": str(data["proyecto"])[:60] if data.get("proyecto") else None,
        "enrutado": enrutado,
        "asistente": asis["id"] if asis else None,
        "lane": LANE if LANE == "b" else (data.get("lane") or None),
        "archivos": data.get("archivos") if LANE == "b" else None,
        "lee": data.get("lee") if LANE == "b" else None,
        "lee_carril_a": LANE == "b" and _lane_lee_carril_a(data),
        # t-router-fallbacks: «si Claude no responde, sigue con el siguiente» (declarado) y por donde paso
        "degradacion": data.get("degradacion") if isinstance(data.get("degradacion"), (bool, str, dict)) else None,
        "ruta_motor": data.get("ruta_motor") if isinstance(data.get("ruta_motor"), dict) else None,
        "run_id": str(data.get("run_id") or refs["raiz"] or task_id),
    }, None


def _validate_model_task(data, task_id):
    """Task de modelos: {"ollama_action": "pull"|"rm"|"list", "model": ...}.
    No pasa por Claude Code. El modelo pasa la validacion estricta."""
    action = data.get("ollama_action")
    if action not in MODEL_ACTIONS:
        return None, f"ollama_action no permitida: {action} (usa pull, rm o list)"
    model = data.get("model")
    if action in ("pull", "rm"):
        if not valid_model_name(model):
            return None, ("model invalido para ollama_action (solo letras, numeros, "
                          "- _ . / :; sin URLs ni rutas)")
    else:
        model = None
    try:
        timeout_min = int(data.get("timeout_min") or (60 if action == "pull" else 5))
    except (TypeError, ValueError):
        return None, "timeout_min debe ser un numero"
    timeout_min = max(1, min(MAX_TIMEOUT_MIN, timeout_min))
    return {"id": task_id, "ollama_action": action, "model_name": model,
            "model": None, "prompt": "", "cwd": str(INBOX),
            "timeout_min": timeout_min}, None


def run_model_task(task):
    """Ejecuta una accion de modelos y devuelve el resultado en el mismo
    esquema que las tareas de Claude (cost_usd 0.0)."""
    started = _now_iso()
    t0 = time.time()
    action, model = task["ollama_action"], task.get("model_name")
    log(f"runner [{task['id']}]: modelos: ollama {action}{' ' + model if model else ''}")
    ok, out, err = run_model_action(action, model, task["timeout_min"] * 60,
                                    job_id=task["id"])
    if ok and action == "pull":
        ok2, listing, _e = run_model_action("list", timeout_s=60)
        if ok2 and any(_same_model(m["name"], model) for m in parse_ollama_list(listing)):
            out = (out + "\n\nVerificado con ollama list: el modelo ya está instalado.").strip()
        else:
            ok, err = False, "la descarga terminó pero el modelo no aparece en ollama list"
    if ok and action == "rm" and _same_model(default_ollama_model(), model or ""):
        s = load_settings()
        s.pop("ollama_model", None)
        save_settings(s)
        log("modelos: el modelo por defecto se borró; elige otro en Modelos")
    return {
        "runner": f"growi-bridge/{VERSION}", "id": task["id"],
        "status": "ok" if ok else "error", "started_at": started,
        "finished_at": _now_iso(), "duration_s": round(time.time() - t0, 1),
        "exit_code": 0 if ok else 1, "result": (out or "")[:MAX_RESULT_CHARS],
        "cost_usd": 0.0, "num_turns": 0, "session_id": None, "stderr": "",
        "error": err, "ollama_action": action, "model": model,
    }


# ---------------------------------------------------------------- motores (engines.json)
# Un corredor, muchos motores: cada task elige su motor con "motor" (por
# defecto "claude"). engines.json dice como se lanza cada uno, como se le
# pasa el modelo, como se reanuda la sesion y como se lee el resultado. El
# resultado es el MISMO para todos (id, status, started_at, finished_at,
# duration_s, exit_code, result, cost_usd, num_turns, session_id, stderr,
# error). Modo seguro: ningun motor lleva bypassPermissions ni --yolo por
# defecto; los permisos los pide cada tarea.
ENGINES_FILE = APP_DIR / "engines.json"
SESSIONS_DIR = APP_DIR / "sesiones"  # historial de los motores sin sesion propia
WAITING = TASKS / "esperando"        # tareas que esperan tu aprobacion
MAX_ROUNDS = 3
LOCAL_HOSTS = ("127.0.0.1", "localhost")
_PH_RE = re.compile(r"\{(\w+)\}")
# Si falta engines.json o esta roto, el runner sigue con Claude como antes.
_FALLBACK_ENGINES = {
    "por_defecto": "claude",
    "revision": {"orden": [{"motor": "claude", "modelo": "haiku",
                            "allowed_tools": "Read,Glob,Grep"}], "max_rondas": MAX_ROUNDS},
    "motores": {"claude": {
        "nombre": "Claude", "tipo": "cli_sincrono", "binario": "claude",
        "comando": ["{binario}", "-p", "{prompt}", "--output-format", "json"],
        "prompt_por": "argumento",
        "modelo": {"opcional": ["--model", "{modelo}"], "por_defecto": None},
        "sesion": {"tipo": "nativa", "opcional": ["--resume", "{session_id}"]},
        "permisos": {"opcionales": [["--allowedTools", "{allowed_tools}"],
                                    ["--disallowedTools", "{disallowed_tools}"],
                                    ["--permission-mode", "{permission_mode}"]]},
        "salida": {"formato": "json", "texto": "result",
                   "costo": ["total_cost_usd", "cost_usd"], "turnos": "num_turns",
                   "sesion": "session_id", "error_si": "is_error"},
        "timeout_min": DEFAULT_TIMEOUT_MIN, "entorno": {}, "healthcheck": {"tipo": "binario"}}},
}
_eng_cache = {"mtime": None, "data": None, "err": None}
# Lo que esta corriendo ahora (para el boton Parar, que lo mata de verdad).
_RUN = {"proc": None, "conn": None, "stop": False, "id": None, "ck": None}
# Ultima actividad del motor de la tarea en curso (cada evento stream-json o
# trozo HTTP): la usan el vigilante de inactividad, el latido y el vivo.
_ACT = {"t": 0.0, "started_at": None}


def _act_touch():
    _ACT["t"] = time.time()


# Procesos que lanzo la app (pid -> (quien lo lanzo, hora)), para la pestana
# Recursos.
_LAUNCHED = {}


# ---- consumo en vivo (outbox/runner-live.json)
# Mientras una tarea corre, el hilo lector del motor va sumando lo que
# reporta el propio motor (tokens de cada mensaje) y el archivo se reescribe
# cada ~5 s. Es la unica fuente de verdad en vivo: la ventana lo lee, no
# calcula nada por su cuenta. Nunca se inventan numeros: si el motor no
# reporta uso, el vivo queda 'sin vivo' y solo cuenta el tiempo.
LIVE_FILE = OUTBOX / "runner-live.json"
LIVE_EVERY_S = 5
_LIVE_LOCK = threading.RLock()
_LIVE = {"d": None, "written": 0.0, "t0": 0.0, "acc": {}, "rol": "tarea"}
_HB = {"t": 0.0}
_STATUS_LOCK = threading.Lock()


def _price_table():
    p = load_engines()[0].get("precios")
    return p if isinstance(p, dict) else {}


def _price_for(model):
    """Precio por token a precio de lista de cada tipo de token, o None si
    engines.json no tiene precio para ese modelo."""
    tab = _price_table()
    pm = tab.get("por_millon") or {}
    m = str(model or "")
    m = (tab.get("alias") or {}).get(m, m)
    e = pm.get(m)
    if not isinstance(e, dict):
        for fam in ("opus", "sonnet", "haiku"):
            if fam in m.lower():
                e = next((v for k, v in pm.items() if fam in k and isinstance(v, dict)), None)
                break
    try:
        f = _price_table().get("factores") or {}
        pin = float(e["entrada"]) / 1e6
        own = {k: e.get(k) for k in ("cache_lectura", "cache_escritura_5m", "cache_escritura_1h")}
        return {"input": pin, "output": float(e["salida"]) / 1e6,
                "cache_read": float(own["cache_lectura"]) / 1e6 if own["cache_lectura"] is not None
                else pin * float(f.get("cache_lectura", 0.1)),
                "cache_5m": float(own["cache_escritura_5m"]) / 1e6 if own["cache_escritura_5m"] is not None
                else pin * float(f.get("cache_escritura_5m", 1.25)),
                "cache_1h": float(own["cache_escritura_1h"]) / 1e6 if own["cache_escritura_1h"] is not None
                else pin * float(f.get("cache_escritura_1h", 2.0))}
    except (TypeError, KeyError, ValueError):
        return None


def estimate_cost(model, u):
    """Costo a precio de lista de un uso normalizado (ver _usage_norm), o
    None si no hay precio para el modelo."""
    pr = _price_for(model)
    if pr is None:
        return None
    return sum(u.get(k, 0) * pr[k] for k in ("input", "cache_5m", "cache_1h", "cache_read", "output"))


def _usage_norm(us):
    """usage de Anthropic/Claude Code -> {input, cache_5m, cache_1h,
    cache_read, output}."""
    us = us if isinstance(us, dict) else {}
    cc = us.get("cache_creation") if isinstance(us.get("cache_creation"), dict) else {}
    total_cc = int(us.get("cache_creation_input_tokens") or 0)
    c1h = int(cc.get("ephemeral_1h_input_tokens") or 0)
    c5m = int(cc.get("ephemeral_5m_input_tokens") or 0)
    if total_cc and not (c1h or c5m):
        c5m = total_cc
    return {"input": int(us.get("input_tokens") or 0), "cache_5m": c5m, "cache_1h": c1h,
            "cache_read": int(us.get("cache_read_input_tokens") or 0),
            "output": int(us.get("output_tokens") or 0), "_split": bool(c1h or c5m) and bool(cc)}


def _merge_usage(prev, u):
    """Mismo mensaje visto dos veces (inicio y final): el mayor de cada campo.
    El final (message_delta) no trae el desglose de cache 5 min / 1 h: se
    conserva el del que si lo trajo, para no contar la cache dos veces."""
    out = {k: max(int(prev.get(k, 0)), int(u.get(k, 0))) for k in ("input", "cache_read", "output")}
    total = max(prev.get("cache_5m", 0) + prev.get("cache_1h", 0), u.get("cache_5m", 0) + u.get("cache_1h", 0))
    src = u if u.get("_split") else prev if prev.get("_split") else None
    c1h = min(src.get("cache_1h", 0), total) if src else 0
    out.update(cache_1h=c1h, cache_5m=total - c1h, _split=bool(src))
    return out


def _tok_in(u):
    return u.get("input", 0) + u.get("cache_5m", 0) + u.get("cache_1h", 0) + u.get("cache_read", 0)


def _live_dinero(motor_id, model=None):
    """real (API con tu clave) / equiv (sesion Max, a precio de lista) /
    local ($0) / otro."""
    return _money_kind({"motor": motor_id, "modelo": model or ""}, _claude_plan())


def _live_blank(motor_id, modelo):
    return {"motor": motor_id, "modelo": modelo, "modelo_real": None,
            "tokens_in": 0, "tokens_out": 0, "cost_usd_estimado": None,
            "cost_usd_final": None, "modo_vivo": "esperando", "por_modelo": {},
            "dinero": _live_dinero(motor_id, modelo)}


def live_start(task, motor_id, modelo):
    """Empieza el vivo de una tarea (estado 'en curso')."""
    with _LIVE_LOCK:
        d = {"task_id": task["id"], "raiz": task.get("raiz") or task["id"],
             "estado": "en curso", "started_at": _now_iso(), "elapsed_s": 0,
             "ronda": task.get("ronda", 0), "tarea_padre": task.get("tarea_padre"),
             "revision": None, "nota": None}
        d.update(_live_blank(motor_id, modelo))
        if d["dinero"] == "local":
            d["cost_usd_estimado"] = 0.0
        _LIVE.update(d=d, t0=time.time(), acc={"tarea": {}, "revision": {}}, rol="tarea", written=0.0)
    live_write(force=True)


def _live_part(rol):
    d = _LIVE["d"]
    if d is None:
        return None
    if rol == "revision":
        return d.get("revision")
    return d


def live_set(rol="tarea", **kw):
    with _LIVE_LOCK:
        part = _live_part(rol)
        if part is not None:
            part.update(kw)
    live_write()


def live_review_start(motor_id, modelo):
    """La revision corre aparte: sus tokens no se mezclan con los de la tarea."""
    with _LIVE_LOCK:
        d = _LIVE["d"]
        if d is None:
            return
        d["estado"] = "revisando"
        d["revision"] = _live_blank(motor_id, modelo)
        if d["revision"]["dinero"] == "local":
            d["revision"]["cost_usd_estimado"] = 0.0
        _LIVE["acc"]["revision"] = {}
    live_write(force=True)


def _live_recalc(rol):
    """Totales desde lo acumulado por mensaje (cada mensaje cuenta una vez)."""
    part = _live_part(rol)
    if part is None:
        return
    msgs = _LIVE["acc"].get(rol) or {}
    por, tin, tout, cost, sin_precio = {}, 0, 0, 0.0, False
    local = part.get("dinero") == "local"
    for model, u in msgs.values():
        b = por.setdefault(model or "?", {"tokens_in": 0, "tokens_out": 0, "cost_usd_estimado": 0.0})
        b["tokens_in"] += _tok_in(u)
        b["tokens_out"] += u.get("output", 0)
        tin += _tok_in(u)
        tout += u.get("output", 0)
        c = 0.0 if local else estimate_cost(model, u)
        if c is None:
            sin_precio = True
            b["cost_usd_estimado"] = None
        else:
            cost += c
            if b["cost_usd_estimado"] is not None:
                b["cost_usd_estimado"] = round(b["cost_usd_estimado"] + c, 6)
    part.update(tokens_in=tin, tokens_out=tout, por_modelo=por,
                cost_usd_estimado=None if sin_precio else round(cost, 6))


def live_msg(rol, key, model, u):
    """Uso de un mensaje del motor (el mismo mensaje puede llegar varias
    veces: se queda el mayor de cada campo)."""
    with _LIVE_LOCK:
        part = _live_part(rol)
        if part is None:
            return
        acc = _LIVE["acc"].setdefault(rol, {})
        prev = acc.get(key)
        if prev is not None:
            model = model or prev[0]
            u = _merge_usage(prev[1], u)
        acc[key] = (model, u)
        if model:
            part["modelo_real"] = model
        part["modo_vivo"] = "en vivo"
        _live_recalc(rol)
    live_write()


def live_tokens(rol, model, tin, tout, modo="en vivo"):
    """Motores locales/API: totales directos (los locales cuestan $0)."""
    with _LIVE_LOCK:
        part = _live_part(rol)
        if part is None:
            return
        part.update(tokens_in=int(tin or 0), tokens_out=int(tout or 0), modo_vivo=modo)
        if model:
            part["modelo_real"] = model
            part["por_modelo"] = {model: {"tokens_in": int(tin or 0), "tokens_out": int(tout or 0),
                                          "cost_usd_estimado": part.get("cost_usd_estimado")}}
    live_write()


def live_final(rol, cost_final, uso=None):
    """Cierra los numeros de la tarea (o de la revision) con lo que reporto
    el motor al terminar. cost_final None = el motor no dio costo."""
    with _LIVE_LOCK:
        part = _live_part(rol)
        if part is None:
            return
        if isinstance(uso, dict) and (uso.get("tokens_in") or uso.get("tokens_out")):
            part["tokens_in"], part["tokens_out"] = uso.get("tokens_in", 0), uso.get("tokens_out", 0)
            if uso.get("por_modelo"):
                part["por_modelo"] = uso["por_modelo"]
            if uso.get("modelo_real"):
                part["modelo_real"] = uso["modelo_real"]
        if isinstance(cost_final, (int, float)):
            part["cost_usd_final"] = round(float(cost_final), 6)
        elif part.get("dinero") == "local":
            part["cost_usd_final"] = 0.0
    live_write(force=True)


def live_finish(nota=None):
    with _LIVE_LOCK:
        d = _LIVE["d"]
        if d is None:
            return
        d["estado"] = "terminado"
        if nota:
            d["nota"] = nota
    live_write(force=True)


def live_write(force=False):
    """Escribe runner-live.json (como mucho cada ~5 s salvo force)."""
    with _LIVE_LOCK:
        d = _LIVE["d"]
        if d is None or (not force and time.time() - _LIVE["written"] < LIVE_EVERY_S):
            return
        if d.get("estado") != "terminado":
            d["elapsed_s"] = round(time.time() - _LIVE["t0"], 1)
            if _ACT["t"]:
                d["ultima_actividad"] = _ts_iso(_ACT["t"])
                d["idle_s"] = round(time.time() - _ACT["t"])
        d["actualizado"] = _now_iso()
        _LIVE["written"] = time.time()
        text = json.dumps(d, ensure_ascii=False, indent=2)
        try:
            OUTBOX.mkdir(parents=True, exist_ok=True)
            tmp = LIVE_FILE.with_suffix(".tmp")
            tmp.write_text(text, encoding="utf-8")
            for i in range(5):
                try:
                    os.replace(tmp, LIVE_FILE)
                    break
                except PermissionError:  # alguien lo esta leyendo en ese instante
                    time.sleep(0.1 * (i + 1))
        except OSError:
            pass


def read_live():
    """Lo que hay en runner-live.json (o None)."""
    try:
        d = json.loads(LIVE_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None


def _uso_from_result_event(ev):
    """Del mensaje final de Claude Code: tokens totales y por modelo."""
    u = _usage_norm(ev.get("usage"))
    por = {}
    for m, mu in (ev.get("modelUsage") or {}).items():
        if not isinstance(mu, dict):
            continue
        por[m] = {"tokens_in": int(mu.get("inputTokens") or 0) + int(mu.get("cacheReadInputTokens") or 0)
                  + int(mu.get("cacheCreationInputTokens") or 0),
                  "tokens_out": int(mu.get("outputTokens") or 0),
                  "cost_usd": mu.get("costUSD") if isinstance(mu.get("costUSD"), (int, float)) else None}
    tin, tout = _tok_in(u), u["output"]
    if por and not (tin or tout):
        tin = sum(v["tokens_in"] for v in por.values())
        tout = sum(v["tokens_out"] for v in por.values())
    main = max(por, key=lambda k: por[k]["tokens_out"] + por[k]["tokens_in"]) if por else None
    if not (tin or tout or por):
        return None
    return {"tokens_in": tin, "tokens_out": tout, "modelo_real": main, "por_modelo": por,
            "detalle": {k: v for k, v in u.items() if not k.startswith("_")}}


def _track_launch(proc, who):
    try:
        _LAUNCHED[proc.pid] = (who, time.time())
        if len(_LAUNCHED) > 200:
            _LAUNCHED.pop(next(iter(_LAUNCHED)), None)
    except Exception:
        pass


_llama_lock = threading.Lock()
_FAM_LOCK = threading.Lock()


def _ensure_no_proxy(env=None):
    """127.0.0.1 nunca va por el proxy: en este PC hay un proxy local que
    intercepta localhost y devuelve un 500 falso."""
    env = os.environ if env is None else env
    for k in ("NO_PROXY", "no_proxy"):
        cur = [x.strip() for x in (env.get(k) or "").split(",") if x.strip()]
        for h in LOCAL_HOSTS:
            if h not in cur:
                cur.append(h)
        env[k] = ",".join(cur)
    return env


_ensure_no_proxy()


def load_engines():
    """(config, aviso). Relee engines.json solo si cambio. Dentro de una
    tarea, la copia con la que empezo (recarga en caliente sin cambiarle la
    config a lo que ya corre)."""
    snap = _cfg_snap()
    if snap is not None:
        return snap["eng"], snap["eng_err"]
    try:
        mt = ENGINES_FILE.stat().st_mtime
    except OSError:
        mt = None
    if _eng_cache["data"] is not None and mt == _eng_cache["mtime"]:
        return _eng_cache["data"], _eng_cache["err"]
    data, err = _FALLBACK_ENGINES, None
    if mt is None:
        err = "falta engines.json junto a growi-bridge.py: solo está Claude"
    else:
        try:
            raw = json.loads(ENGINES_FILE.read_text(encoding="utf-8"))
            if not isinstance(raw, dict) or not isinstance(raw.get("motores"), dict):
                raise ValueError("falta la sección 'motores'")
            data = raw
        except (OSError, ValueError) as e:
            prev = _eng_cache["data"]
            if prev is not None and prev is not _FALLBACK_ENGINES:
                # Recarga en caliente: un engines.json a medio guardar (o con
                # un error) no deja a la app sin motores: sigue la ultima buena.
                err = f"engines.json no se pudo leer ({e}): sigo con la última versión buena"
                if err != _eng_cache["err"]:
                    log(f"motores AVISO: {err}")
                _eng_cache.update(mtime=mt, err=err)
                return prev, err
            err = f"engines.json no se pudo leer ({e}): solo está Claude"
    if err and err != _eng_cache["err"]:
        log(f"motores AVISO: {err}")
    _eng_cache.update(mtime=mt, data=data, err=err, rt={})
    return data, err


def engine_raw(motor_id):
    """El descriptor tal cual esta en engines.json (o None)."""
    eng = (load_engines()[0].get("motores") or {}).get(motor_id)
    return eng if isinstance(eng, dict) else None


def get_engine(motor_id):
    """El motor listo para correr: el descriptor v2 traducido a la forma que
    usan los ejecutores (un descriptor mal formado sale con tipo
    '_mal_formado' y sus problemas, nunca rompe el runner)."""
    raw = engine_raw(motor_id)
    if raw is None:
        return None
    snap = _cfg_snap()
    rt = snap.setdefault("rt", {}) if snap is not None else _eng_cache.setdefault("rt", {})
    if motor_id not in rt:
        rt[motor_id] = runtime_engine(motor_id, raw)
    return rt[motor_id]


def engine_ids():
    return [k for k in (load_engines()[0].get("motores") or {}) if not k.startswith("_")]


def default_motor():
    """El principal: el que elegiste al apagar el de engines.json, o el de engines.json."""
    try:
        s = load_settings()
        p = s.get("motor_principal")
        if p and p not in (s.get("motores_off") or []) and p in (load_engines()[0].get("motores") or {}):
            return str(p)
    except Exception:
        pass
    return str(load_engines()[0].get("por_defecto") or "claude")


# ---- descriptor generico (engines.json esquema 2)
# Los motores se DESCRIBEN con datos (decision 17 de INVESTIGACION-0.3.0):
# el runner no tiene codigo especial por motor. Un descriptor v2 lleva
# invocacion, formato_salida, extraer, reanudar, errores, requisitos,
# base_url, credencial_ref y capacidades (ver "_esquema" en engines.json).
# runtime_engine() lo traduce a la forma que usan los ejecutores de siempre
# (cli_sincrono / api_sincrona / api_asincrona). Un motor sin "invocacion"
# es de la forma v1 y pasa tal cual (motores de prueba viejos).
FORMATOS_SALIDA = {"json_final": "json", "json_por_lineas": "jsonl", "texto_plano": "texto"}
TIPOS_INVOCACION = {"comando": "cli_sincrono", "http": "api_sincrona",
                    "http_asincrono": "api_asincrona"}
HUECOS_COMANDO = {"binario", "prompt", "cwd", "session", "model", "modelo", "session_id",
                  "permisos", "opcionales", "allowed_tools", "disallowed_tools",
                  "permission_mode"}
REANUDAR_MODOS = ("en_plantilla", "argumento", "plantilla", "historial_local")
CAPACIDADES = ("streaming", "reanudar", "costo", "herramientas", "habilidades_growi")
# Errores por defecto de un motor nuevo (los mismos criterios que la cola).
ERRORES_POR_DEFECTO = {
    "transitorio": [r"\b429\b", r"\b5(?:00|02|03|04|29)\b", r"timed? ?out|timeout",
                    r"sin respuesta", r"no responde", r"conexi[oó]n cortada", r"overloaded",
                    r"rate.?limit"],
    "definitivo": [r"\b40[013]\b", r"falta la clave", r"sin credencial", r"no encuentro '",
                   r"no est[aá] instalado", r"descriptor mal formado", r"configuraci[oó]n"],
}


def _huecos(obj):
    """Todos los {huecos} de una plantilla (listas anidadas incluidas)."""
    if isinstance(obj, str):
        return set(_PH_RE.findall(obj))
    if isinstance(obj, list):
        return set().union(*[_huecos(x) for x in obj]) if obj else set()
    if isinstance(obj, dict):
        return set().union(*[_huecos(v) for k, v in obj.items() if not str(k).startswith("_")]) \
            if obj else set()
    return set()


def _extraer_ok(spec, nombre):
    """Problema de una regla de extraer (o None si esta bien)."""
    if spec is None or spec == "no_lo_da" or spec == "historial_local":
        return None
    if isinstance(spec, (str, list)):
        return None
    if isinstance(spec, dict):
        if not any(k in spec for k in ("ruta", "fijo", "contar_evento", "evento", "eventos")):
            return f"extraer.{nombre}: falta ruta, fijo, evento o contar_evento"
        return None
    return f"extraer.{nombre}: debe ser una ruta, un objeto o \"no_lo_da\""


def validar_descriptor(motor_id, d):
    """Lista de problemas del descriptor (vacia = bien formado)."""
    p = []
    if not isinstance(d, dict):
        return ["no es un objeto JSON"]
    if not isinstance(d.get("nombre"), str) or not d["nombre"].strip():
        p.append("falta nombre")
    if d.get("id") not in (None, motor_id):
        p.append(f"id '{d.get('id')}' no coincide con la clave '{motor_id}'")
    inv = d.get("invocacion")
    if not isinstance(inv, dict) or inv.get("tipo") not in TIPOS_INVOCACION:
        return p + ["invocacion.tipo debe ser comando, http o http_asincrono"]
    t = inv["tipo"]
    base = d.get("base_url")
    if base is not None and not (isinstance(base, str) and re.match(r"https?://[^\s/]+", base)):
        p.append(f"base_url no es una URL http(s): {base!r}")
    req = d.get("requisitos") if isinstance(d.get("requisitos"), dict) else {}
    if t == "comando":
        tpl = inv.get("plantilla")
        if not isinstance(tpl, list) or not tpl or not all(
                isinstance(x, str) or (isinstance(x, list) and x and all(isinstance(y, str) for y in x))
                for x in tpl):
            p.append("invocacion.plantilla debe ser una lista de textos (una sublista = opcional)")
        else:
            raros = _huecos(tpl) - HUECOS_COMANDO
            if raros:
                p.append("hueco desconocido en la plantilla: " + ", ".join("{" + h + "}" for h in sorted(raros)))
            if tpl[0] != "{binario}":
                p.append("la plantilla debe empezar por {binario}")
        if not isinstance(req.get("binario"), str) or not req["binario"].strip():
            p.append("falta requisitos.binario")
        if d.get("formato_salida") not in FORMATOS_SALIDA:
            p.append("formato_salida debe ser json_por_lineas, json_final o texto_plano")
        if inv.get("prompt_por") not in (None, "argumento", "stdin"):
            p.append("invocacion.prompt_por debe ser argumento o stdin")
    elif t == "http":
        if not isinstance(base, str):
            p.append("falta base_url")
        if not isinstance(inv.get("ruta"), str):
            p.append("falta invocacion.ruta")
        if not isinstance(inv.get("cuerpo"), dict):
            p.append("falta invocacion.cuerpo")
    else:
        if not isinstance(base, str):
            p.append("falta base_url")
        for k in ("crear", "estado"):
            if not isinstance(inv.get(k), dict) or not isinstance(inv[k].get("ruta") or inv[k].get("url"), str):
                p.append(f"falta invocacion.{k}.ruta")
    ext = d.get("extraer")
    if not isinstance(ext, dict):
        p.append("falta extraer (cómo sacar texto, costo y turnos)")
    else:
        for k in ("costo", "turnos"):
            if k not in ext:
                p.append(f"falta extraer.{k} (pon \"no_lo_da\" si el motor no lo da)")
        for k, v in ext.items():
            e = _extraer_ok(v, k) if k in ("texto", "costo", "turnos", "sesion") else None
            if e:
                p.append(e)
        if t == "comando" and d.get("formato_salida") != "texto_plano" and not ext.get("texto"):
            p.append("falta extraer.texto (dónde está la respuesta en el JSON)")
    r = d.get("reanudar")
    if r != "no_soporta" and not (isinstance(r, dict) and r.get("modo") in REANUDAR_MODOS):
        p.append("reanudar debe ser \"no_soporta\" o {\"modo\": " + " | ".join(REANUDAR_MODOS) + "}")
    elif isinstance(r, dict):
        if r["modo"] == "argumento" and not (isinstance(r.get("args"), list) and "session" in _huecos(r["args"])):
            p.append("reanudar.args debe llevar {session}")
        if r["modo"] == "plantilla" and not (isinstance(r.get("plantilla"), list) and r["plantilla"]):
            p.append("falta reanudar.plantilla")
        if r["modo"] == "en_plantilla" and t == "comando" and "session" not in _huecos(inv.get("plantilla")):
            p.append("reanudar en_plantilla pero la plantilla no lleva {session}")
    err = d.get("errores")
    if err is not None:
        if not isinstance(err, dict):
            p.append("errores debe ser {transitorio: [...], definitivo: [...]}")
        else:
            for k in ("transitorio", "definitivo"):
                for pat in err.get(k) or []:
                    try:
                        re.compile(str(pat))
                    except re.error as e:
                        p.append(f"errores.{k}: patrón inválido {pat!r} ({e})")
            for pat in err.get("auth") or []:
                try:
                    re.compile(str(pat))
                except re.error as e:
                    p.append(f"errores.auth: patrón inválido {pat!r} ({e})")
    au = d.get("autenticacion")
    if au is not None:
        sc = au.get("sesion_cli") if isinstance(au, dict) else None
        if not isinstance(au, dict) or (sc is not None and not (
                isinstance(sc, dict) and isinstance(sc.get("comprobar"), list) and sc["comprobar"]
                and all(isinstance(x, str) for x in sc["comprobar"]))):
            p.append("autenticacion.sesion_cli.comprobar debe ser una lista de textos (p. ej. "
                     "[\"{binario}\", \"models\"])")
        elif isinstance(sc, dict):
            try:
                re.compile(str(sc.get("sin_sesion_si") or ""))
            except re.error as e:
                p.append(f"autenticacion.sesion_cli.sin_sesion_si: patrón inválido ({e})")
        if isinstance(au, dict) and au.get("preferencia") is not None and not (
                isinstance(au["preferencia"], list)
                and all(x in ("sesion_cli", "clave") for x in au["preferencia"])):
            p.append("autenticacion.preferencia debe ser una lista con sesion_cli y/o clave")
    if d.get("timeout_min") is not None and not isinstance(d.get("timeout_min"), (int, float)):
        p.append("timeout_min debe ser un número")
    if d.get("entorno") is not None and not isinstance(d.get("entorno"), dict):
        p.append("entorno debe ser un objeto")
    cr = d.get("credencial_ref")
    if cr is not None and not (isinstance(cr, dict) and all(
            isinstance(cr.get(k), str) and cr[k].strip() for k in ("proveedor", "etiqueta"))):
        p.append("credencial_ref debe ser null o {proveedor, etiqueta}")
    if d.get("fallback") is not None and not isinstance(d.get("fallback"), list):
        p.append("fallback debe ser una lista de motores")
    return p


def _url_join(base, ruta):
    ruta = str(ruta or "")
    if re.match(r"https?://", ruta):
        return ruta
    return str(base or "").rstrip("/") + "/" + ruta.lstrip("/")


def runtime_engine(motor_id, d):
    """Descriptor v2 -> forma de los ejecutores. v1 pasa tal cual."""
    if not isinstance(d, dict):
        return {"id": motor_id, "nombre": motor_id, "tipo": "_mal_formado",
                "_problemas": ["no es un objeto JSON"], "_v2": d}
    if "invocacion" not in d:
        return dict(d, id=motor_id, _v1=True)
    probs = validar_descriptor(motor_id, d)
    if probs:
        return {"id": motor_id, "nombre": d.get("nombre") or motor_id, "tipo": "_mal_formado",
                "_problemas": probs, "_v2": d}
    inv, ext = d["invocacion"], d.get("extraer") or {}
    req = d.get("requisitos") if isinstance(d.get("requisitos"), dict) else {}
    base = d.get("base_url")
    rt = {"id": motor_id, "_v2": d, "tipo": TIPOS_INVOCACION[inv["tipo"]]}
    # Bloques de datos que el v2 comparte con la forma de los ejecutores.
    for k in ("nombre", "descripcion", "especialidad", "sensible", "vivo", "servidor",
              "cuerpo_revision", "timeout_min", "entorno", "credencial_ref", "credencial_como",
              "capacidades", "errores", "carril_b", "en_selector", "contexto", "esquema_rubrica_en",
              "autenticacion", "frase_selector"):
        if k in d:
            rt[k] = d[k]
    mod = d.get("modelo") if isinstance(d.get("modelo"), dict) else {}
    rt["modelo"] = {k: v for k, v in mod.items() if k != "opcional"}
    perm = d.get("permisos") if isinstance(d.get("permisos"), dict) else {}
    rt["permisos"] = {k: v for k, v in perm.items() if k not in ("opcionales", "modos")}
    hc = dict(d.get("healthcheck") or {})
    if hc.get("ruta") and base:
        hc["url"] = _url_join(base, hc["ruta"])
    rt["healthcheck"] = hc
    r = d.get("reanudar")
    if inv["tipo"] == "comando":
        rt["binario"] = req.get("binario")
        if req.get("script_npm"):
            rt["script_npm"] = req["script_npm"]
        rt["comando"] = inv["plantilla"]
        rt["prompt_por"] = inv.get("prompt_por") or (
            "argumento" if "prompt" in _huecos(inv["plantilla"]) else "stdin")
        if isinstance(r, dict) and r["modo"] == "plantilla":
            rt["comando_reanudar"] = r["plantilla"]
            rt["sesion"] = {"tipo": "nativa"}
        elif isinstance(r, dict) and r["modo"] == "argumento":
            rt["sesion"] = {"tipo": "nativa", "opcional": r["args"]}
        elif isinstance(r, dict):
            rt["sesion"] = {"tipo": "nativa"}
        else:
            rt["sesion"] = {"tipo": "no_soporta"}
        rt["salida"] = dict(ext, formato=FORMATOS_SALIDA[d["formato_salida"]])
    elif inv["tipo"] == "http":
        rt["url"] = _url_join(base, inv["ruta"])
        rt["metodo"] = inv.get("metodo") or "POST"
        rt["cuerpo"] = inv["cuerpo"]
        rt["sesion"] = {"tipo": "historial_local" if isinstance(r, dict) else "no_soporta"}
        rt["salida"] = dict(ext, formato="json")
    else:
        for k in ("crear", "estado"):
            blk = dict(inv[k])
            blk["url"] = _url_join(base, blk.get("ruta") or blk.get("url"))
            rt[k] = blk
        rt["descargar"] = dict(inv.get("descargar") or {})
        rt["sesion"] = {"tipo": "no_soporta"}
        rt["salida"] = dict(ext, formato="json")
    return rt


def _cap(eng, nombre):
    """Capacidad declarada (v1 sin capacidades: lo que hacia antes)."""
    caps = eng.get("capacidades") if isinstance(eng.get("capacidades"), dict) else None
    if caps is not None and nombre in caps:
        return bool(caps[nombre])
    if nombre == "herramientas":
        return eng.get("tipo") == "cli_sincrono"
    if nombre == "streaming":
        return isinstance(eng.get("vivo"), dict)
    if nombre == "reanudar":
        return (eng.get("sesion") or {}).get("tipo") not in (None, "no_soporta")
    return False


def soporta_reanudar(eng):
    return bool(eng) and (eng.get("sesion") or {}).get("tipo") not in (None, "no_soporta")


def clasificar_error(eng, error):
    """'transitorio' / 'definitivo' segun los patrones del descriptor, o None
    si no encaja ninguno (entonces decide la cola con sus reglas de siempre)."""
    err = str(error or "")
    if not err:
        return None
    pats = eng.get("errores") if isinstance((eng or {}).get("errores"), dict) else {}
    for tipo in ("definitivo", "transitorio"):
        for pat in pats.get(tipo) or []:
            try:
                if re.search(str(pat), err, re.I):
                    return tipo
            except re.error:
                continue
    return None


# ---- credenciales (Administrador de credenciales de Windows, solo lectura)
# credencial_ref = {proveedor, etiqueta}. El destino en el Administrador de
# credenciales es growi-bridge/<proveedor>/<etiqueta> (credencial generica;
# la clave va en el secreto; si el comentario es JSON con base_url, esa URL
# cambia la del descriptor). Guardar y elegir la clave activa es de
# t-credenciales-keyring; aqui solo se LEE y nunca por el proveedor solo
# (puede haber varias claves del mismo proveedor).
CRED_PREFIX = "growi-bridge"
_CRED_BACKEND = {"leer": None, "listar": None}  # las pruebas pueden cambiarlos


def _cred_target(proveedor, etiqueta):
    return f"{CRED_PREFIX}/{proveedor}/{etiqueta}"


def _wincred_read(target):
    """(secreto, comentario) o (None, motivo)."""
    try:
        import ctypes
        from ctypes import wintypes

        class CREDENTIAL(ctypes.Structure):
            _fields_ = [("Flags", wintypes.DWORD), ("Type", wintypes.DWORD),
                        ("TargetName", wintypes.LPWSTR), ("Comment", wintypes.LPWSTR),
                        ("LastWritten", wintypes.FILETIME), ("CredentialBlobSize", wintypes.DWORD),
                        ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
                        ("Persist", wintypes.DWORD), ("AttributeCount", wintypes.DWORD),
                        ("Attributes", ctypes.c_void_p), ("TargetAlias", wintypes.LPWSTR),
                        ("UserName", wintypes.LPWSTR)]
        adv = ctypes.windll.advapi32
        p = ctypes.POINTER(CREDENTIAL)()
        if not adv.CredReadW(ctypes.c_wchar_p(target), 1, 0, ctypes.byref(p)):
            return None, "no está guardada"
        try:
            c = p.contents
            raw = ctypes.string_at(c.CredentialBlob, c.CredentialBlobSize)
            try:
                secret = raw.decode("utf-16-le") if len(raw) % 2 == 0 and b"\x00" in raw else raw.decode("utf-8")
            except UnicodeDecodeError:
                secret = raw.decode("utf-8", "replace")
            return secret.strip(), c.Comment or ""
        finally:
            adv.CredFree(p)
    except Exception as e:
        return None, f"no se pudo leer el Administrador de credenciales ({type(e).__name__})"


def _wincred_list():
    """[(proveedor, etiqueta)] de las guardadas como growi-bridge/*/*. Solo
    nombres: los secretos no se tocan."""
    out = []
    try:
        import ctypes
        from ctypes import wintypes

        class CRED(ctypes.Structure):
            _fields_ = [("Flags", wintypes.DWORD), ("Type", wintypes.DWORD),
                        ("TargetName", wintypes.LPWSTR)]
        adv = ctypes.windll.advapi32
        n = wintypes.DWORD()
        arr = ctypes.POINTER(ctypes.POINTER(CRED))()
        if not adv.CredEnumerateW(ctypes.c_wchar_p(CRED_PREFIX + "/*"), 0, ctypes.byref(n),
                                  ctypes.byref(arr)):
            return out
        try:
            for i in range(n.value):
                parts = (arr[i].contents.TargetName or "").split("/")
                if len(parts) == 3 and parts[0] == CRED_PREFIX and parts[1] and parts[2]:
                    out.append((parts[1], parts[2]))
        finally:
            adv.CredFree(arr)
    except Exception:
        pass
    return sorted(set(out))


def credenciales_guardadas():
    """[(proveedor, etiqueta)]: las de Ajustes -> Claves (keyring/DPAPI) y, por
    compatibilidad, las del destino provisional growi-bridge/<p>/<e>."""
    fn = _CRED_BACKEND.get("listar") or _wincred_list
    try:
        viejas = list(fn())
    except Exception:
        viejas = []
    if _CRED_BACKEND.get("listar"):
        return viejas
    return sorted(set([(c["proveedor"], c["etiqueta"]) for c in cred_lista()] + viejas))


def _cred_ref_key(ref):
    return f"{ref.get('proveedor')}/{ref.get('etiqueta')}"


def credencial_activa(ref):
    """La etiqueta que de verdad se usa para esta credencial_ref. Ajustes ->
    Claves puede apuntar la referencia a otra clave guardada DEL MISMO
    proveedor (settings.json -> credenciales_activas: {"proveedor/etiqueta":
    "otra-etiqueta"}; solo nombres, ninguna clave). La resolucion sigue siendo
    por la referencia completa, nunca por el proveedor solo: dos motores del
    mismo proveedor con referencias distintas pueden usar claves distintas."""
    act = (load_settings().get("credenciales_activas") or {})
    elegida = act.get(_cred_ref_key(ref)) if isinstance(act, dict) else None
    return elegida if isinstance(elegida, str) and elegida.strip() else ref["etiqueta"]


def resolver_credencial(ref):
    """(clave, base_url, motivo). El motor usa SIEMPRE la clave ACTIVA de su
    proveedor (Ajustes -> Claves), a la base_url de esa clave; si Leandro
    cambia la activa, el siguiente uso ya va por la nueva. Al 100 % del tope
    de esa clave, no disponible (las demas claves del proveedor siguen)."""
    if not isinstance(ref, dict) or not ref.get("proveedor") or not ref.get("etiqueta"):
        return None, None, "credencial_ref incompleta (hace falta proveedor y etiqueta)"
    if not _CRED_BACKEND.get("leer"):
        c = cred_activa(ref["proveedor"])
        if c is not None:
            secret = cred_clave(c["cuenta"])
            if not secret:
                return None, None, (f"sin credencial: la clave activa «{c['etiqueta']}» de {ref['proveedor']} "
                                    f"no está en el almacén ({cred_via()})")
            ok, why, aviso, nivel = cred_puede_usar(c["cuenta"])
            if not ok:
                return None, None, f"sin credencial: {why}"
            if _cfg_snap() is not None:  # una tarea: queda escrito que clave uso (solo los 4 ultimos)
                usada = {"proveedor": ref["proveedor"], "referencia": ref["etiqueta"], "etiqueta": c["etiqueta"],
                         "cuenta": c["cuenta"], "ultimos4": secret[-4:]}
                if _cfg_snap().get("cred_usada") != usada:
                    _cfg_snap()["cred_usada"] = usada
                    log(f"credencial: la tarea usa la clave activa de {ref['proveedor']}: «{c['etiqueta']}» "
                        f"(••••{secret[-4:]}) en {c['base_url']}")
                    cred_avisar(c["cuenta"], aviso, nivel)
            return secret, c["base_url"], "guardada"
        if not any(p == ref["proveedor"] for p, _e in credenciales_guardadas()):
            return None, None, (f"sin credencial: no hay ninguna clave de {ref['proveedor']} guardada "
                                "(Ajustes → Claves)")
        if any(c["proveedor"] == ref["proveedor"] for c in cred_lista()):
            return None, None, (f"sin credencial: ninguna clave de {ref['proveedor']} está activa "
                                "(Ajustes → Claves → «Usar esta»)")
    fn = _CRED_BACKEND.get("leer") or _wincred_read
    etq = credencial_activa(ref)
    secret, extra = fn(_cred_target(ref["proveedor"], etq))
    if not secret:
        cual = f"«{etq}»" + (f" (la activa para «{ref['etiqueta']}»)" if etq != ref["etiqueta"] else "")
        return None, None, (f"sin credencial: falta la clave {cual} de {ref['proveedor']} "
                            f"en el Administrador de credenciales ({extra})")
    base = None
    try:
        meta = json.loads(extra) if extra and extra.strip().startswith("{") else {}
        base = meta.get("base_url") if isinstance(meta.get("base_url"), str) else None
    except ValueError:
        pass
    if _cfg_snap() is not None:  # una tarea: queda escrito que clave uso (solo los 4 ultimos)
        usada = {"proveedor": ref["proveedor"], "referencia": ref["etiqueta"], "etiqueta": etq,
                 "ultimos4": secret[-4:]}
        if _cfg_snap().get("cred_usada") != usada:
            _cfg_snap()["cred_usada"] = usada
            log(f"credencial: la tarea usa {ref['proveedor']}/{ref['etiqueta']} -> clave activa «{etq}» "
                f"(••••{secret[-4:]})")
    return secret, base, "guardada"


def credencial_info(ref):
    """Lo que el panel muestra de una credencial_ref: proveedor, etiqueta
    activa y los 4 ultimos caracteres (nunca la clave)."""
    if not isinstance(ref, dict) or not ref.get("proveedor") or not ref.get("etiqueta"):
        return None
    c = None if _CRED_BACKEND.get("leer") else cred_activa(ref["proveedor"])
    if c is not None:
        secret = cred_clave(c["cuenta"])
        return {"proveedor": ref["proveedor"], "referencia": ref["etiqueta"], "activa": c["etiqueta"],
                "guardada": bool(secret), "ultimos4": c["ultimos4"], "base_url_credencial": c["base_url"],
                "motivo": "guardada" if secret else f"no está en el almacén ({cred_via()})"}
    fn = _CRED_BACKEND.get("leer") or _wincred_read
    etq = credencial_activa(ref)
    secret, extra = fn(_cred_target(ref["proveedor"], etq))
    base = None
    if secret:
        try:
            meta = json.loads(extra) if extra and extra.strip().startswith("{") else {}
            base = meta.get("base_url") if isinstance(meta.get("base_url"), str) else None
        except ValueError:
            pass
    return {"proveedor": ref["proveedor"], "referencia": ref["etiqueta"], "activa": etq,
            "guardada": bool(secret), "ultimos4": secret[-4:] if secret else None,
            "base_url_credencial": base,
            "motivo": "guardada" if secret else f"no está guardada ({extra})"}


def cred_texto(ref):
    """'gemini + gemini-personal' / 'no usa clave'."""
    if not isinstance(ref, dict):
        return "no usa clave"
    return f"{ref.get('proveedor')} + {ref.get('etiqueta')}"


def _app_path(p):
    p = Path(str(p or ""))
    return p if p.is_absolute() else APP_DIR / p


def _fill(obj, vars_):
    """Rellena {prompt}, {modelo}... en una plantilla de engines.json. Un
    texto que es solo "{x}" se cambia por el valor tal cual (lista, dict)."""
    if isinstance(obj, str):
        m = _PH_RE.fullmatch(obj)
        if m and m.group(1) in vars_:
            return vars_[m.group(1)]
        return _PH_RE.sub(lambda mm: str(vars_[mm.group(1)])
                          if mm.group(1) in vars_ and not isinstance(vars_[mm.group(1)], (list, dict))
                          else mm.group(0), obj)
    if isinstance(obj, list):
        return [_fill(x, vars_) for x in obj]
    if isinstance(obj, dict):
        return {k: _fill(v, vars_) for k, v in obj.items() if not str(k).startswith("_")}
    return obj


def _get_path(data, path):
    """'choices.0.message.content' -> data['choices'][0]['message']['content']."""
    cur = data
    for part in str(path or "").split("."):
        if isinstance(cur, list) and part.isdigit() and int(part) < len(cur):
            cur = cur[int(part)]
        elif isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return None
    return cur


def _deep_merge(a, b):
    out = dict(a)
    for k, v in (b or {}).items():
        out[k] = _deep_merge(out[k], v) if isinstance(v, dict) and isinstance(out.get(k), dict) else v
    return out


# ---- acceso: sesion propia del CLI (OAuth que guarda el programa) o clave
# autenticacion.sesion_cli del descriptor dice como comprobar, sin gastar,
# que el programa tiene su sesion iniciada (p. ej. ["{binario}", "models"]:
# sale con error y "sign in" si no la tiene). Con sesion valida el motor esta
# disponible SIN clave; si no, usa la clave de credencial_ref (si la hay). El
# Bridge nunca toca el token de esa sesion: lo guarda y renueva el CLI.
# Ejemplo (motor gemini): la ficha lee la version con `agy --version`
# (requisitos.version_comando) y las tareas corren
# `agy -p ... --output-format json` (invocacion.plantilla del descriptor).
_SESION_CLI = {}  # motor_id -> {"t": epoch, "ok": bool, "motivo": str}
_SESION_TTL_OK, _SESION_TTL_MAL = 600, 120


def _sesion_cli(eng, fresca=False):
    """(ok, motivo) de la sesion propia del CLI, o (None, '') si el descriptor
    no la declara. Se guarda unos minutos: comprobarla lanza el programa."""
    sc = (eng.get("autenticacion") or {}).get("sesion_cli") if isinstance(eng.get("autenticacion"), dict) else None
    if not isinstance(sc, dict):
        return None, ""
    mid = str(eng.get("id") or "")
    c = _SESION_CLI.get(mid)
    if c and not fresca and time.time() - c["t"] < (_SESION_TTL_OK if c["ok"] else _SESION_TTL_MAL):
        return c["ok"], c["motivo"]
    base = _resolve_binary(eng)
    if not base:
        ok, why = False, f"no está instalado: no encuentro '{eng.get('binario')}' en el PATH"
    else:
        cmd = []
        for x in sc["comprobar"]:
            cmd += base if x == "{binario}" else [str(x)]
        try:
            r = subprocess.run(cmd, capture_output=True, timeout=float(sc.get("timeout_s") or 30),
                               stdin=subprocess.DEVNULL, env=_ensure_no_proxy(dict(os.environ)), **_oculto())
            txt = _ANSI_RE.sub("", (r.stdout or b"").decode("utf-8", "replace")
                               + (r.stderr or b"").decode("utf-8", "replace"))
            pat = str(sc.get("sin_sesion_si") or "")
            sin = bool(pat) and re.search(pat, txt, re.I)
            if r.returncode == 0 and not sin:
                ok, why = True, f"{sc.get('nombre') or 'sesión del programa'} iniciada"
                detalle = ""
            else:
                linea = next((x.strip() for x in txt.splitlines() if re.search(pat or r"\S", x, re.I)), "")
                ok, why = False, f"sin {sc.get('nombre') or 'sesión del programa'}"
                detalle = f"el programa dice: «{linea[:160]}»" if linea else f"salió con código {r.returncode}"
        except subprocess.TimeoutExpired:
            ok, why, detalle = False, f"no pude comprobar la {sc.get('nombre') or 'sesión'}: tardó demasiado", ""
        except OSError as e:
            ok, why, detalle = False, f"no pude comprobar la {sc.get('nombre') or 'sesión'}", str(e)
    _SESION_CLI[mid] = {"t": time.time(), "ok": ok, "motivo": why, "detalle": detalle}
    return ok, why


def sesion_cli_detalle(eng):
    """Lo que dijo el programa en la ultima comprobacion (para la ficha)."""
    return str((_SESION_CLI.get(str(eng.get("id") or "")) or {}).get("detalle") or "")


def sesion_cli_caducada(eng, motivo):
    """Una tarea vio 401 / sesion caducada: la proxima comprobacion la repite."""
    mid = str(eng.get("id") or "")
    if mid:
        _SESION_CLI[mid] = {"t": time.time(), "ok": False, "motivo": motivo}


def acceso_motor(eng, fresca=False):
    """Como entra este motor: {"modo": "sesion_cli" | "clave" | None,
    "ok": bool, "motivo": str}. Sin autenticacion en el descriptor: la clave
    de credencial_ref, como siempre. Con ella: en el orden de preferencia
    (por defecto, primero la sesion del CLI y luego la clave)."""
    au = eng.get("autenticacion") if isinstance(eng.get("autenticacion"), dict) else {}
    cr = eng.get("credencial_ref")
    if not au.get("sesion_cli"):
        if not cr:
            return {"modo": None, "ok": True, "motivo": ""}
        key, _b, why = resolver_credencial(cr)
        return {"modo": "clave", "ok": bool(key), "motivo": "clave guardada" if key else why}
    orden = au.get("preferencia") or ["sesion_cli", "clave"]
    motivos = []
    for modo in orden:
        if modo == "sesion_cli":
            ok, why = _sesion_cli(eng, fresca)
            if ok:
                return {"modo": "sesion_cli", "ok": True, "motivo": why}
            motivos.append(why)
        elif modo == "clave" and cr:
            key, _b, why = resolver_credencial(cr)
            if key:
                return {"modo": "clave", "ok": True, "motivo": f"clave {cred_texto(cr)} guardada"}
            motivos.append(why)
    como = (au.get("sesion_cli") or {}).get("como_iniciar")
    return {"modo": None, "ok": False,
            "motivo": "; ".join(m for m in motivos if m)
                      + (". Cómo entrar: lo dice la ficha del motor (Modelos → Motores)" if como else "")}


def _engine_env(eng, task=None, rol=None):
    env = dict(os.environ)
    if task is not None:
        # Para el gate de calidad (Stop hook de Claude Code, gate-calidad.py):
        # nombra su log gate-calidad-<id>.log y no corre en la sesion del juez.
        env["GROWI_TAREA_ID"] = str(task.get("id") or "")
        env["GROWI_TAREA_ROL"] = str(rol or "tarea")
    for k, v in (eng.get("entorno") or {}).items():
        if k not in ("NO_PROXY", "no_proxy"):
            env[str(k)] = str(v)
    # Credencial por variable de entorno (credencial_como.entorno): solo la
    # clave de credencial_ref, nunca la de otro motor del mismo proveedor.
    como = eng.get("credencial_como") if isinstance(eng.get("credencial_como"), dict) else {}
    au = eng.get("autenticacion") if isinstance(eng.get("autenticacion"), dict) else {}
    if au.get("sesion_cli") and acceso_motor(eng)["modo"] == "sesion_cli":
        # Entra con la sesion del CLI: ninguna clave en su entorno (si no,
        # el programa preferiria la clave a la sesion).
        for var in [como.get("entorno")] + list(au.get("quitar_entorno") or []):
            if var:
                env.pop(str(var), None)
    elif como.get("entorno") and eng.get("credencial_ref"):
        key, _b, _m = resolver_credencial(eng["credencial_ref"])
        if key:
            env[str(como["entorno"])] = key
    return _ensure_no_proxy(env)


def _claude_abs():
    """Ruta absoluta de Claude Code si existe (t-runner-path-045). El PATH del
    proceso puede no traer .local\bin (app elevada relanzada desde una terminal
    vieja); la ruta conocida no depende de el. Si no existe, el PATH es respaldo."""
    p = Path(os.environ.get("USERPROFILE") or Path.home()) / ".local" / "bin" / "claude.exe"
    return str(p) if p.is_file() else None


def _resolve_binary(eng):
    """Ruta del binario como lista de argumentos. Un .cmd de npm (codex) se
    lanza con node + su script: un .cmd con argumentos pasaria por cmd.exe,
    y un prompt con & o | podria colarse como comando."""
    exe = _claude_abs() if str(eng.get("binario") or "") == "claude" else None
    exe = exe or shutil.which(str(eng.get("binario") or ""))
    if not exe:
        return None
    if exe.lower().endswith((".cmd", ".bat")):
        node = shutil.which("node")
        script = Path(exe).parent / str(eng.get("script_npm") or "")
        if node and eng.get("script_npm") and script.is_file():
            return [node, str(script)]
        return None
    return [exe]


def _named_api_key(name):
    """Forma v1 (clave_api por nombre): la clave ACTIVA de ese proveedor."""
    prov = cred_proveedor_de(name)
    return api_key_for(prov) if prov else ""


# ---- llamadas HTTP a 127.0.0.1 (llama-server, Ollama)
class LocalCallError(Exception):
    """Fallo de una llamada local, con el motivo dicho claro (proxy,
    codificacion, servidor apagado...)."""


def _explain_local_error(code, headers, data, text, where):
    hdrs = {k.lower(): v for k, v in headers}
    msg = ""
    if isinstance(data, dict):
        e = data.get("error")
        msg = str(e.get("message", "")) if isinstance(e, dict) else str(e or data.get("message") or "")
    proxyish = (any(h in hdrs for h in ("via", "proxy-agent", "proxy-connection", "x-proxy-id"))
                or "proxy" in (hdrs.get("server", "") + text[:300]).lower())
    loading = code == 503 and "loading" in msg.lower()
    if code == 407 or (code in (500, 502, 503, 504) and not loading and (data is None or proxyish)):
        why = "trae cabeceras de proxy" if proxyish else "no es la respuesta JSON del motor"
        return (f"PROXY: {where} respondió {code} y la respuesta {why} ({text[:120]!r}). "
                "La llamada iba directa y con NO_PROXY=127.0.0.1: algo en este PC intercepta "
                "127.0.0.1 (el proxy local).")
    if code == 400 and any(w in (msg + text).lower() for w in
                           ("json", "utf", "parse", "decode", "unicode", "codec", "invalid")):
        return (f"CODIFICACIÓN: {where} rechazó el JSON (400: {(msg or text)[:160]}). El cuerpo se "
                "mandó en UTF-8; revisa caracteres raros en el prompt.")
    if loading:
        return f"{where} todavía está cargando el modelo (503)"
    return f"{where} respondió {code}: {(msg or text)[:200]}"


def _http_local(method, url, body=None, timeout=60, track=False):
    """GET/POST a 127.0.0.1 sin proxy (http.client no usa ningun proxy y
    ademas NO_PROXY=127.0.0.1) y con el JSON en UTF-8. Devuelve el JSON."""
    import http.client
    u = urlparse(url)
    host, port = u.hostname or "", u.port or 80
    if host not in LOCAL_HOSTS:
        raise LocalCallError(f"{url} no es una dirección local")
    where = f"{host}:{port}"
    _ensure_no_proxy()
    headers = {"Accept": "application/json", "User-Agent": "GrowiBridge"}
    payload = None
    if body is not None:
        text = json.dumps(body, ensure_ascii=False)
        # surrogates sueltos (texto pegado roto) no son UTF-8: se cambian por
        # '?' en vez de mandar bytes que el servidor rechazaria con un 400.
        payload = text.encode("utf-8", "replace")
        headers["Content-Type"] = "application/json; charset=utf-8"
    conn = http.client.HTTPConnection(host, port, timeout=timeout)
    if track:
        _RUN["conn"] = conn
    try:
        try:
            with _llama_uso(method, port, u.path):  # para el apagado por inactividad
                conn.request(method, u.path + (("?" + u.query) if u.query else ""),
                             body=payload, headers=headers)
                resp = conn.getresponse()
                raw = resp.read()
        except ConnectionRefusedError:
            raise LocalCallError(f"no responde: nada escucha en {where} (servidor apagado)")
        except TimeoutError:
            raise LocalCallError(f"sin respuesta de {where} en {timeout:.0f} s")
        except (OSError, http.client.HTTPException) as e:
            if _RUN.get("stop"):
                raise LocalCallError("parado por el usuario (se cortó la conexión con el motor)")
            raise LocalCallError(f"conexión cortada con {where} ({type(e).__name__}: {e})")
    finally:
        if track:
            _RUN["conn"] = None
        conn.close()
    text = raw.decode("utf-8", "replace")
    try:
        data = json.loads(text) if text.strip() else None
    except ValueError:
        data = None
    if 200 <= resp.status < 300:
        if data is None:
            raise LocalCallError(f"PROXY: {where} respondió {resp.status} pero sin JSON "
                                 f"({text[:120]!r}); ¿el proxy local en medio?")
        return data
    raise LocalCallError(_explain_local_error(resp.status, resp.getheaders(), data, text, where))


class _NoStream(Exception):
    """El servidor no contesto en streaming: se repite sin streaming."""


def _first_num(data, paths):
    for p in paths if isinstance(paths, list) else [paths]:
        v = _get_path(data, p) if p else None
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return int(v)
    return None


def _http_local_stream(url, body, timeout, vivo, on_piece, idle=None):
    """POST en streaming a 127.0.0.1 (SSE de llama-server o NDJSON de
    Ollama). Llama on_piece(n_trozos) segun llegan. Devuelve (texto,
    tokens_entrada, tokens_salida); los tokens son los que el servidor
    reporta al final (None si no los reporta). idle = segundos maximos sin
    recibir nada (inactividad): al pasarlos, LocalCallError(NO_PROGRESS_TXT)."""
    sock_timeout = min(timeout, idle) if idle else timeout
    import http.client
    u = urlparse(url)
    host, port = u.hostname or "", u.port or 80
    if host not in LOCAL_HOSTS:
        raise LocalCallError(f"{url} no es una dirección local")
    where = f"{host}:{port}"
    _ensure_no_proxy()
    payload = json.dumps(body, ensure_ascii=False).encode("utf-8", "replace")
    headers = {"Accept": "text/event-stream, application/x-ndjson, application/json",
               "User-Agent": "GrowiBridge", "Content-Type": "application/json; charset=utf-8"}
    fmt = vivo.get("formato", "sse")
    conn = http.client.HTTPConnection(host, port, timeout=sock_timeout)
    _RUN["conn"] = conn
    parts, n, tin, tout, deadline = [], 0, None, None, time.time() + timeout
    uso = _llama_uso("POST", port, u.path).__enter__()  # para el apagado por inactividad
    try:
        try:
            conn.request("POST", u.path + (("?" + u.query) if u.query else ""),
                         body=payload, headers=headers)
            resp = conn.getresponse()
            if not 200 <= resp.status < 300:
                raw = resp.read()
                text = raw.decode("utf-8", "replace")
                try:
                    data = json.loads(text) if text.strip() else None
                except ValueError:
                    data = None
                raise LocalCallError(_explain_local_error(resp.status, resp.getheaders(), data,
                                                          text, where))
            while True:
                if time.time() > deadline:
                    raise LocalCallError(f"sin respuesta completa de {where} en {timeout:.0f} s")
                line = resp.readline()
                if not line:
                    break
                _act_touch()
                s = line.decode("utf-8", "replace").strip()
                if not s:
                    continue
                if fmt == "sse":
                    if not s.startswith("data:"):
                        continue
                    s = s[5:].strip()
                    if s == "[DONE]":
                        break
                try:
                    obj = json.loads(s)
                except ValueError:
                    if not n:
                        raise _NoStream(s[:120])
                    continue
                if not isinstance(obj, dict):
                    continue
                if obj.get("error"):
                    e = obj["error"]
                    raise LocalCallError(f"{where} dijo: "
                                         + str(e.get("message", e) if isinstance(e, dict) else e)[:200])
                piece = _get_path(obj, vivo.get("trozo"))
                if isinstance(piece, str) and piece:
                    parts.append(piece)
                    n += 1
                    on_piece(n)
                tin = _first_num(obj, vivo.get("uso_in")) or tin
                tout = _first_num(obj, vivo.get("uso_out")) or tout
                if vivo.get("fin") and obj.get(vivo["fin"]) is True:
                    break
        except ConnectionRefusedError:
            raise LocalCallError(f"no responde: nada escucha en {where} (servidor apagado)")
        except TimeoutError:
            if sock_timeout < timeout:
                raise LocalCallError(NO_PROGRESS_TXT)
            raise LocalCallError(f"sin respuesta de {where} en {timeout:.0f} s")
        except (OSError, http.client.HTTPException) as e:
            if _RUN.get("stop"):
                raise LocalCallError("parado por el usuario (se cortó la conexión con el motor)")
            raise LocalCallError(f"conexión cortada con {where} ({type(e).__name__}: {e})")
    finally:
        uso.__exit__()
        _RUN["conn"] = None
        conn.close()
    if not n and tin is None and tout is None:
        raise _NoStream("sin trozos")
    return "".join(parts), tin, tout


def _health(eng, timeout=2):
    hc = (eng.get("healthcheck") or {}).get("url")
    if not hc:
        return False, "engines.json no dice cómo comprobarlo"
    try:
        _http_local("GET", hc, timeout=timeout)
        return True, ""
    except LocalCallError as e:
        return False, str(e)


def _llama_installed(eng):
    srv = eng.get("servidor") or {}
    exe, gguf = _app_path(srv.get("exe")), _app_path(srv.get("gguf"))
    if srv.get("exe") and srv.get("gguf") and exe.is_file() and gguf.is_file():
        return True, ""
    falta = []
    if not exe.is_file():
        falta.append(f"falta {exe}")
    if not gguf.is_file():
        falta.append(f"falta {gguf}")
    return False, ("llama-server no está instalado (" + "; ".join(falta) + "). "
                   + str(srv.get("como_instalar") or ""))


# --- Servidor en modo router (t-router-llama-server, 0.3.0) ---------------
# servidor.modo = "router": UN proceso padre en un solo puerto de 127.0.0.1
# (--models-dir models --models-max 1 --models-preset models-preset.ini, sin
# -m) y un hijo por modelo cargado, que el router pone en otro puerto de
# 127.0.0.1 (nunca 0.0.0.0). Cada peticion lleva "model": "<nombre>" (el
# .gguf sin extension); sin el, el router contesta 400. /health solo dice que
# el ROUTER vive: si un modelo esta listo lo dice GET /models (loaded /
# unloaded / loading). Medido en el build 11873 (26 oct 2026): POST
# /models/load y /models/unload funcionan; el router solo descubre los .gguf
# al arrancar; un archivo con «mmproj» en el nombre no sale como modelo (va
# en el preset de su modelo). Nada aqui depende del nombre del motor.
_SRV = {"proc": None, "modelos": {}, "hora": 0.0, "rol": None, "cargando": None, "adoptado": None}
# "sleeping": medido el 26 oct 2026 con --sleep-idle-seconds en el router (la
# VRAM baja a ~117 MiB y el modelo despierta con la siguiente peticion).
SRV_ESTADO_TXT = {"loaded": "cargado", "unloaded": "sin cargar", "loading": "cargando…",
                  "sleeping": "dormido (VRAM libre; despierta al usarlo)"}
# Textos fijos que ve el usuario (banner, ficha, avisos, registro):
SRV_AVISO_CARGA = "cargando modelo..."   # mientras GET /models dice loading
SRV_LOCAL_LISTO = "local listo"          # solo con GET /models = loaded, nunca por /health


def _srv_es_router(eng):
    return str(((eng or {}).get("servidor") or {}).get("modo") or "") == "router"


def _srv_cfg(eng):
    r = ((eng.get("servidor") or {}).get("router") or {})
    hc = urlparse(str((eng.get("healthcheck") or {}).get("url") or ""))
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else eng
    base = str(d.get("base_url") or (f"{hc.scheme}://{hc.netloc}" if hc.netloc else "")).rstrip("/")
    return {"base": base, "modelos": r.get("modelos") or "/models", "cargar": r.get("cargar") or "/models/load",
            "descargar": r.get("descargar") or "/models/unload",
            "espera_carga_s": float(r.get("espera_carga_s") or 300)}


def _srv_modelo_defecto(eng):
    return str((eng.get("modelo") or {}).get("por_defecto") or "") or \
        Path(str((eng.get("servidor") or {}).get("gguf") or "")).stem


def srv_modelos(eng, timeout=3):
    """GET /models del router -> {nombre: loaded | unloaded | loading}. Es la
    fuente de verdad de que modelo esta listo (no /health). Un llama-server
    mono-modelo no da 'status': su unico modelo cuenta como cargado."""
    c = _srv_cfg(eng)
    data = _http_local("GET", _url_join(c["base"], c["modelos"]), timeout=timeout)
    out = {}
    for m in (data or {}).get("data") or []:
        if isinstance(m, dict) and m.get("id"):
            st = m.get("status")
            out[str(m["id"])] = str(st.get("value") if isinstance(st, dict) else "loaded")
    _SRV.update(modelos=out, hora=time.time())
    return out


def srv_rol(eng, timeout=2):
    """'router' o 'mono' (llama-server arrancado con -m, p. ej. por la 0.2.0)."""
    try:
        p = _http_local("GET", _url_join(_srv_cfg(eng)["base"], "/props"), timeout=timeout)
        _SRV["rol"] = "router" if str((p or {}).get("role") or "") == "router" else "mono"
    except LocalCallError:
        _SRV["rol"] = None
    return _SRV["rol"]


def srv_estado_texto(eng, fresco=True):
    """'hermes-3-8b-q4_k_m: cargado · Qwen3-…: sin cargar' para la ficha de
    Modelos. Sin consultar si el router no contesto hace poco."""
    try:
        est = srv_modelos(eng, timeout=1) if fresco else _SRV["modelos"]
    except LocalCallError as e:
        return None, f"router apagado: ningún modelo cargado ({e})"[:200]
    if not est:
        return {}, "el router no ve ningún .gguf en models\\"
    return est, ", ".join(f"{k}: {SRV_ESTADO_TXT.get(v, v)} ({v})" for k, v in est.items())


def _srv_post(eng, que, model, timeout=10):
    c = _srv_cfg(eng)
    return _http_local("POST", _url_join(c["base"], c[que]), {"model": model}, timeout=timeout)


def srv_descargar_modelo(eng, model):
    """POST /models/unload: libera la VRAM de ese modelo sin matar el router."""
    try:
        if srv_modelos(eng).get(model) in (None, "unloaded"):
            return True, f"{model} ya estaba sin cargar"
        _srv_post(eng, "descargar", model)
        # El unload es asincrono (medido 26 oct 2026: justo despues GET /models
        # aun dice loaded con la VRAM a medio bajar): se espera a verlo unloaded.
        t0 = time.time()
        while time.time() - t0 < 30 and srv_modelos(eng).get(model) in ("loaded", "loading", "sleeping"):
            time.sleep(0.3)
        st = srv_modelos(eng).get(model)
    except LocalCallError as e:
        return False, f"no se pudo descargar {model}: {e}"
    log(f"motores: modelo {model} descargado del router (POST /models/unload → {st} en "
        f"{time.time() - t0:.1f} s)")
    return st not in ("loaded", "loading"), f"{model} descargado ({st} en {time.time() - t0:.1f} s)"


def srv_cargar_modelo(eng, model, aviso=None):
    """POST /models/load y espera a GET /models = loaded. La primera carga
    desde disco tarda de ~1 s a mas de un minuto: se avisa «cargando
    modelo…» en el banner (state['paso']) y en el vivo, y se espera hasta
    router.espera_carga_s (300 s), no los 10 s de una peticion normal.
    (ok, nota). Con --models-max 1 el router descarga el anterior solo."""
    c = _srv_cfg(eng)
    try:
        est = srv_modelos(eng)
    except LocalCallError as e:
        return False, f"el router no contesta GET {c['modelos']}: {e}"
    if model not in est:
        hay = ", ".join(est) or "ninguno"
        f = MODELS_DIR / f"{model}.gguf"
        if not f.is_file():
            return False, _srv_no_instalado(eng, model)
        if _srv_reiniciar(eng):
            return srv_cargar_modelo(eng, model, aviso)
        return False, (f"el router no tiene el modelo «{model}» (tiene: {hay}); el .gguf está en "
                       "models\\ pero el router solo ve los que había al arrancar y no lo arrancó "
                       "esta app: páralo (Modelos → Motor local → Parar) y se vuelve a arrancar solo")
    if est[model] == "loaded":
        return True, ""
    if est[model] == "sleeping":
        # --sleep-idle-seconds (no se usa por defecto): la peticion lo despierta.
        return True, f"{model} estaba dormido (sleeping): lo despierta la primera petición"
    prev, t0 = state.get("paso"), time.time()
    log(f"motores: cargando modelo {model} en el router (POST {c['cargar']}; antes: {est})")
    _SRV["cargando"] = (model, t0)
    try:
        # Cambio de modelo: primero se descarga el que esta (POST /models/unload)
        # y luego se carga el pedido, sin matar el proceso. Con --models-max 1 el
        # router lo haria solo; asi queda en el registro y la VRAM baja antes.
        for otro, st in est.items():
            if otro != model and st in ("loaded", "loading", "sleeping"):
                ok_u, n_u = srv_descargar_modelo(eng, otro)
                log(f"motores: cambio de modelo {otro} → {model}: {n_u}")
        if est[model] != "loading":
            _srv_post(eng, "cargar", model)
        visto = False
        while time.time() - t0 < c["espera_carga_s"]:
            secs = int(time.time() - t0)
            txt = (f"{SRV_AVISO_CARGA} {model} ({secs} s; la primera vez desde disco puede tardar "
                   "más de un minuto)")
            state["paso"] = txt
            if aviso:
                aviso(txt)
            if _RUN.get("stop"):
                return False, f"parado por el usuario mientras cargaba {model}"
            st = srv_modelos(eng).get(model)
            if st == "loaded":
                secs = round(time.time() - t0, 1)
                note = (f"{SRV_LOCAL_LISTO}: modelo {model} cargado en el router en {secs} s "
                        f"(GET {c['modelos']}: loaded)")
                log(f"motores: {note}")
                lib_note_started(MODELS_DIR / f"{model}.gguf")
                return True, note
            if st == "loading":
                visto = True
            elif visto or time.time() - t0 > 15:
                return False, f"el router no pudo cargar {model} (volvió a «{st}»); mira llama\\llama-server.log"
            time.sleep(1)
        return False, f"{model} no terminó de cargar en {c['espera_carga_s']:.0f} s"
    except LocalCallError as e:
        return False, f"no se pudo cargar {model}: {e}"
    finally:
        state["paso"] = prev
        _SRV["cargando"] = None


def _srv_reiniciar(eng):
    """Solo si el router lo arranco esta app y no hay un modelo cargandose:
    lo cierra (el siguiente ensure_llama_server lo vuelve a arrancar y ve los .gguf
    nuevos). Nunca mata un llama-server ajeno."""
    p = _SRV.get("proc")
    if p is None or p.poll() is not None:
        return False
    try:
        if "loading" in srv_modelos(eng).values():
            return False
    except LocalCallError:
        pass
    log(f"motores: reinicio el router (pid {p.pid}) para que vea los .gguf nuevos de models\\")
    try:
        subprocess.run(["taskkill", "/PID", str(p.pid), "/T", "/F"], capture_output=True, timeout=20,
                       **_oculto())
    except Exception:
        p.kill()
    p.wait(timeout=20)
    _SRV["proc"] = None
    ok, _w = ensure_llama_server(eng)
    return ok


def srv_preset_sync(eng):
    """models-preset.ini (--models-preset): una seccion por modelo con su -c,
    -ngl, -np, --mmproj y --cache-type-k/v. Sin preset todos comparten los
    flags globales (un ctx 8192 para Hermes seria un ctx 8192 para el
    embedder). Las secciones que ya estan NO se tocan (lo editado a mano
    manda); solo se anaden las de los .gguf de models\\ que aun no tienen,
    con los datos del catalogo. -> lista de secciones anadidas."""
    srv = eng.get("servidor") or {}
    if not srv.get("preset"):
        return []
    ini = _app_path(srv["preset"])
    try:
        txt = ini.read_text(encoding="utf-8")
    except OSError:
        txt = ("; Presets por modelo del router de llama-server (--models-preset). Lo crea\n"
               "; Growi Bridge; puedes editarlo: una seccion que ya existe no se pisa.\n"
               "; Claves = flags largos sin '--'. -np 1: una tarea a la vez y el contexto\n"
               "; entero (-c) para ella; si subes np, -c se reparte entre los slots.\n"
               "version = 1\n\n[*]\nn-gpu-layers = 99\nparallel = 1\n")
    hay = {s.strip().lower() for s in re.findall(r"^\s*\[([^\]]+)\]", txt, flags=re.M)}
    por_archivo = {}
    for m in load_catalog():
        g = m.get("gguf") or {}
        if g.get("archivo"):
            por_archivo[Path(str(g["archivo"])).stem.lower()] = m
    for e in lib_load()["modelos"]:
        cat = next((m for m in load_catalog() if m.get("id") == e.get("id")), None)
        if cat and e.get("filename"):
            por_archivo[Path(str(e["filename"])).stem.lower()] = dict(cat, _mmproj_local=(
                (e.get("mmproj") or {}).get("filename")))
    nuevas = []
    for f in sorted(MODELS_DIR.glob("*.gguf")) if MODELS_DIR.is_dir() else []:
        if "mmproj" in f.name.lower() or f.stem.lower() in hay:
            continue
        cat = por_archivo.get(f.stem.lower()) or {}
        emb = str(cat.get("kind") or "").startswith("embed")
        ctx = int(cat.get("ctx_router") or (2048 if emb else min(int(cat.get("ctx_default") or 8192), 8192)))
        sec = [f"\n[{f.stem}]", f"; {cat.get('name') or 'sin ficha en el catálogo'}"
               + (" (embeddings)" if emb else ""), f"ctx-size = {ctx}", "parallel = 1", "n-gpu-layers = 99"]
        if emb:
            sec += ["embeddings = true", "pooling = last"]
        mm = cat.get("_mmproj_local")
        if not mm and isinstance((cat.get("gguf") or {}).get("mmproj"), dict):
            mm = f"{f.stem}.{cat['gguf']['mmproj'].get('archivo')}"
        if mm and (MODELS_DIR / mm).is_file():
            sec.append(f"mmproj = {MODELS_DIR / mm}")
        kv = str(cat.get("kv_type_default") or "f16")
        if kv != "f16":
            sec += [f"cache-type-k = {kv}", f"cache-type-v = {kv}"]
        txt = txt.rstrip("\n") + "\n" + "\n".join(sec) + "\n"
        nuevas.append(f.stem)
    if nuevas or not ini.is_file():
        try:
            ini.write_text(txt, encoding="utf-8")
        except OSError as e:
            # Sin preset nuevo el router arranca igual (con los flags de [*]).
            log(f"motores: no pude escribir {ini.name} ({e}); el router usa el que había")
            return []
        log(f"motores: models-preset.ini: añadidas {', '.join(nuevas) or 'la cabecera'}")
    return nuevas


def ensure_llama_server(eng, model=None):
    """LA UNICA PUERTA para arrancar el servidor local (t-llama-ciclo-vida-048):
    tareas, memoria, comando IA, probar un motor, boton Arrancar de Modelos,
    cambio de modelo y reinicio del router pasan por aqui; nada arranca
    llama-server al abrir la app, y el revisor no lo arranca (si esta
    apagado lo salta y sigue con el siguiente de revision.orden). Motor con bloque 'servidor' (hoy llama-server): si no
    responde, lo arranca oculto con el exe y los args del descriptor y espera
    a que conteste (servidor.espera_s). En modo router ademas carga el modelo
    que pide la tarea (GET /models es quien dice si esta listo, no /health).
    Si queda encendido, el vigilante lo apaga tras servidor.inactividad_min
    sin peticiones. Nada aqui depende del nombre del motor. Al terminar, el
    banner vuelve al paso que tenia (no se queda en «Arrancando…»)."""
    paso0 = state.get("paso")
    try:
        ok, nota = _ensure_llama_server_arrancar(eng, model)
    finally:
        state["paso"] = paso0
    if ok:
        # Quien llama aqui va a pedirle algo enseguida: cuenta como uso, asi el
        # vigilante no lo apaga entre este «listo» y la peticion.
        _llama_uso_marca()
        _llama_vigilar(eng)
    return ok, nota


def _ensure_llama_server_arrancar(eng, model=None):
    """Solo la llama ensure_llama_server(): aqui esta el unico Popen del exe."""
    if model and _srv_es_router(eng) and not _srv_gguf(eng, model):
        # Modelo no instalado: error claro que apunta al descargador, sin
        # arrancar el router ni ocupar VRAM para nada.
        return False, _srv_no_instalado(eng, model)
    ok, why = _health(eng)
    if ok:
        return _srv_modelo_listo(eng, model, "")
    inst, msg = _llama_installed(eng)
    if not inst:
        return False, msg
    srv = eng["servidor"]
    name = eng.get("nombre") or eng.get("id") or "el servidor local"
    with _llama_lock:
        ok, why = _health(eng)
        if ok:
            return _srv_modelo_listo(eng, model, "")
        # Sin doble instancia: antes de lanzar, ¿hay algo en el puerto o
        # huerfanos del mismo exe? (t-ciclo-vida-llama)
        listo, why2 = _srv_puerto_antes_de_lanzar(eng)
        if listo is not None:
            return _srv_modelo_listo(eng, model, "") if listo else (False, why2)
        exe, gguf = _app_path(srv["exe"]), _app_path(srv["gguf"])
        router = _srv_es_router(eng)
        if router:
            srv_preset_sync(eng)
        huecos = {"{gguf}": str(gguf), "{models_dir}": str(_app_path(srv.get("models_dir") or "models")),
                  "{preset}": str(_app_path(srv.get("preset") or "models-preset.ini"))}
        args = [str(exe)]
        for a in srv.get("args") or []:
            a = str(a)
            for k, v in huecos.items():
                a = a.replace(k, v)
            args.append(a)
        logp = _app_path(srv.get("log") or "llama/llama-server.log")
        state["paso"] = f"Arrancando {exe.stem} ({name})…"
        log(f"motores: {exe.stem} no respondía ({why}); lo arranco oculto: {exe.name} "
            + ("en modo router (" + " ".join(args[1:]) + ")" if router else f"-m {gguf.name}"))
        t0 = time.time()
        try:
            logf = open(logp, "ab")
            proc = subprocess.Popen(
                args, cwd=str(exe.parent), stdout=logf, stderr=logf, stdin=subprocess.DEVNULL,
                env=_engine_env(eng), **_oculto(getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)))
            logf.close()
            _track_launch(proc, f"runner: motor {name} ({exe.stem})")
            if router:
                _SRV["proc"] = proc
            log(f"motores: {exe.name} lanzado oculto ({OCULTO_TXT}), pid {proc.pid}")
        except OSError as e:
            log(f"motores: no se pudo lanzar {exe.name} oculto ({e}); no se reintenta con ventana visible")
            return False, f"no se pudo arrancar {exe.stem} ({e})"
        wait_s = llama_cfg(eng)["espera_s"]
        donde = urlparse(str((eng.get("healthcheck") or {}).get("url") or "")).netloc or "su puerto"
        while time.time() - t0 < wait_s:
            if proc.poll() is not None:
                tail = ""
                try:
                    tail = logp.read_text(encoding="utf-8", errors="replace")[-400:]
                except OSError:
                    pass
                return False, f"{exe.stem} se cerró al arrancar (código {proc.returncode}): {tail}"
            if _RUN.get("stop"):
                return False, f"parado por el usuario mientras arrancaba {exe.stem}"
            ok, why = _health(eng, timeout=2)
            if ok:
                secs = round(time.time() - t0, 1)
                note = (f"{exe.stem} no respondía en {donde}; el runner lo arrancó solo "
                        f"(pid {proc.pid}, listo en {secs} s)")
                state["llama_autostart"] = f"{_now_iso()}: {note}"
                log(f"motores: {note}")
                if not router:
                    lib_note_started(gguf)  # el librero ya puede ofrecer borrar su .bak
                    return True, note
                # /health del router = router vivo, NO modelo listo: se
                # espera a que GET /models conteste antes de cargar nada.
                while time.time() - t0 < wait_s:
                    try:
                        srv_modelos(eng)
                        break
                    except LocalCallError as e:
                        why = str(e)
                        time.sleep(1)
                else:
                    return False, f"el router arrancó pero GET /models no contestó en {wait_s:.0f} s: {why}"
                return _srv_modelo_listo(eng, model, note)
            time.sleep(1)
        return False, f"{exe.stem} arrancó (pid {proc.pid}) pero no respondió en {wait_s:.0f} s: {why}"


def _srv_modelo_listo(eng, model, note):
    """Tras /health OK: en modo router, carga el modelo (o el por defecto) y
    solo entonces da el motor por listo. Un llama-server mono-modelo (p. ej.
    el que dejo arrancado la 0.2.0) ya tiene su modelo: se usa tal cual."""
    if not _srv_es_router(eng) or srv_rol(eng) == "mono":
        return True, note
    en_tarea = bool(state.get("current"))  # desde el boton de la app no hay vivo de tarea que avisar
    ok, n2 = srv_cargar_modelo(eng, model or _srv_modelo_defecto(eng),
                               aviso=(lambda t: live_set("tarea", nota=t)) if en_tarea else None)
    if ok and n2 and en_tarea:
        live_set("tarea", nota="")
    return ok, "; ".join(x for x in (note, n2) if x)


# --- Bajo demanda y apagado por inactividad (t-llama-ciclo-vida-048) -------
# El 29 oct 2026 el modelo local (~5,2 GB de RAM + 47 % de CPU al arrancar)
# colapso un PC de 16 GB. Ahora: nada lo arranca al abrir la app; lo arranca
# ensure_llama_server() cuando alguien le va a pedir algo, y el vigilante lo
# apaga tras servidor.inactividad_min sin peticiones. Peticion = POST de
# inferencia al puerto del servidor (chat, completions, embeddings, carga de
# modelo); /health, GET /models y /props no cuentan (el panel de Modelos los
# consulta solo, y si contaran nunca se apagaria). Nunca se apaga con una
# peticion en curso: el contador de las del Bridge y, si el servidor lo da,
# GET /slots (is_processing) para las de fuera.
LLAMA_INACTIVIDAD_MIN = 15   # por defecto; manda servidor.inactividad_min
LLAMA_ESPERA_S = 120         # por defecto; manda servidor.espera_s
_LLAMA_NO_USO = ("/models/unload",)
_LLAMA_VIDA: dict = {"activas": 0, "ultima": 0.0, "apagando": False, "hilo": None, "puertos": set()}
_LLAMA_VIDA_LOCK = threading.Lock()


def llama_cfg(eng):
    """Toda la configuracion del servidor local, de UN sitio: el bloque
    'servidor' del motor en engines.json (exe, gguf, args con el puerto y los
    flags; las capas en GPU de cada modelo van en su preset). Para pruebas,
    GROWI_LLAMA_INACTIVIDAD_MIN y GROWI_LLAMA_ESPERA_S pisan el descriptor
    (admiten decimales: 0.5 = 30 s). inactividad_min 0 = no apagar nunca."""
    srv = (eng or {}).get("servidor") or {}

    def num(env, clave, defecto):
        for v in (os.environ.get(env), srv.get(clave)):
            try:
                if v not in (None, ""):
                    return max(0.0, float(v))
            except (TypeError, ValueError):
                pass
        return float(defecto)
    return {"exe": _srv_exe(eng), "gguf": _app_path(srv.get("gguf")), "models_dir": _srv_models_dir(eng),
            "puerto": _srv_puerto(eng), "args": [str(a) for a in srv.get("args") or []],
            "log": _app_path(srv.get("log") or "llama/llama-server.log"),
            "espera_s": num("GROWI_LLAMA_ESPERA_S", "espera_s", LLAMA_ESPERA_S) or LLAMA_ESPERA_S,
            "inactividad_min": num("GROWI_LLAMA_INACTIVIDAD_MIN", "inactividad_min", LLAMA_INACTIVIDAD_MIN)}


def _llama_uso_marca():
    with _LLAMA_VIDA_LOCK:
        _LLAMA_VIDA["ultima"] = time.time()


class _llama_uso:
    """Envuelve cada llamada HTTP local: si es una peticion de inferencia a un
    servidor vigilado, la cuenta como en curso mientras dura y apunta la hora
    de la ultima. Si el vigilante esta apagandolo justo ahora, espera a que
    termine (la peticion fallara con «no responde» y el reintento lo vuelve a
    arrancar por ensure_llama_server)."""

    def __init__(self, method, port, path):
        self.cuenta = (str(method).upper() == "POST" and port in _LLAMA_VIDA["puertos"]
                       and not str(path).startswith(_LLAMA_NO_USO))

    def __enter__(self):
        if self.cuenta:
            t0 = time.time()
            while _LLAMA_VIDA["apagando"] and time.time() - t0 < 30:
                time.sleep(0.2)
            with _LLAMA_VIDA_LOCK:
                _LLAMA_VIDA["activas"] += 1
                _LLAMA_VIDA["ultima"] = time.time()
        return self

    def __exit__(self, *_exc):
        if self.cuenta:
            with _LLAMA_VIDA_LOCK:
                _LLAMA_VIDA["activas"] = max(0, _LLAMA_VIDA["activas"] - 1)
                _LLAMA_VIDA["ultima"] = time.time()
        return False


def _llama_vigilar(eng):
    """Pone el vigilante de inactividad de ese servidor (uno solo a la vez)."""
    cfg = llama_cfg(eng)
    with _LLAMA_VIDA_LOCK:
        _LLAMA_VIDA["puertos"].add(cfg["puerto"])
        h = _LLAMA_VIDA["hilo"]
        if cfg["inactividad_min"] <= 0 or (h is not None and h.is_alive()):
            return
        h = threading.Thread(target=_llama_vigilante, args=(eng,), name="llama-inactividad", daemon=True)
        _LLAMA_VIDA["hilo"] = h
    h.start()


def _llama_slots_ocupados(eng):
    """GET /slots: ¿algun slot esta generando? Cubre peticiones que no pasan por
    el Bridge (un curl, otro programa). En modo router se pregunta por cada
    modelo cargado. -> True / False / None (el servidor no lo dice)."""
    base = _srv_cfg(eng)["base"]
    rutas = ["/slots"]
    if _srv_es_router(eng):
        rutas += [f"/slots?model={m}" for m, st in (_SRV.get("modelos") or {}).items() if st != "unloaded"]
    visto = None
    for r in rutas:
        try:
            data = _http_local("GET", _url_join(base, r), timeout=2)
        except LocalCallError:
            continue
        if isinstance(data, list):
            visto = bool(visto) or any(isinstance(s, dict) and s.get("is_processing") for s in data)
            if visto:
                return True
    return visto


def _llama_vigilante(eng):
    """Hilo: con el servidor encendido mira cada poco si lleva inactividad_min
    sin peticiones; entonces, sin ninguna en curso, lo para con srv_parar (solo
    el exe del descriptor en su puerto, con su arbol) y se acaba. Tambien se
    acaba si el servidor ya no esta (lo paro Leandro o se cerro)."""
    cfg = llama_cfg(eng)
    lim = cfg["inactividad_min"] * 60
    paso = max(1.0, min(30.0, lim / 6))
    log(f"motores: vigilante de inactividad de {cfg['exe'].stem} (puerto {cfg['puerto']}): lo apago tras "
        f"{cfg['inactividad_min']:g} min sin peticiones")
    fallos = 0
    try:
        while True:
            time.sleep(paso)
            if _llama_lock.locked() or _SRV.get("cargando"):
                continue  # arrancando o cargando un modelo: eso no es inactividad
            if not _health(eng, timeout=2)[0]:
                fallos += 1
                if fallos >= 2 and not srv_procesos(eng)["oyente"]:
                    log(f"motores: vigilante de inactividad: {cfg['exe'].stem} ya no está encendido; termino")
                    return
                continue
            fallos = 0
            with _LLAMA_VIDA_LOCK:
                quieto = time.time() - _LLAMA_VIDA["ultima"]
                activas = _LLAMA_VIDA["activas"]
            if activas or quieto < lim:
                continue
            if _llama_slots_ocupados(eng):
                log(f"motores: {cfg['exe'].stem} lleva {quieto / 60:.1f} min sin peticiones del Bridge, pero "
                    "GET /slots dice que está generando (una petición de fuera): no lo apago")
                _llama_uso_marca()
                continue
            with _LLAMA_VIDA_LOCK:
                if _LLAMA_VIDA["activas"] or time.time() - _LLAMA_VIDA["ultima"] < lim:
                    continue  # llego una peticion mientras miraba /slots
                _LLAMA_VIDA["apagando"] = True
            try:
                if not srv_procesos(eng)["nuestro"]:
                    log(f"motores: el puerto {cfg['puerto']} no es del {cfg['exe'].name} del Bridge: el vigilante "
                        "de inactividad no lo toca")
                    return
                ok, nota = srv_parar(eng, f"{cfg['inactividad_min']:g} min sin peticiones: apagado por inactividad")
                state["llama_autostop"] = f"{_now_iso()}: {nota}"
                log(f"motores: apagado por inactividad ({'ok' if ok else 'a medias'}); se vuelve a arrancar solo "
                    "con la próxima petición o con Modelos → Motor local → Arrancar")
            finally:
                with _LLAMA_VIDA_LOCK:
                    _LLAMA_VIDA["apagando"] = False
            return
    finally:
        with _LLAMA_VIDA_LOCK:
            if _LLAMA_VIDA["hilo"] is threading.current_thread():
                _LLAMA_VIDA["hilo"] = None


# --- Ciclo de vida del servidor local (t-ciclo-vida-llama, 0.3.0) ---------
# Arrancar, parar, cambiar de modelo y liberar VRAM para CUALQUIER motor con
# bloque "servidor" en engines.json (hoy llama-server); nada mira el nombre
# del motor. Nunca se mata a ciegas: solo el proceso que es EL MISMO exe del
# descriptor y escucha en SU puerto, su arbol de hijos y los huerfanos de ese
# mismo exe. Ollama trae su propio llama-server.exe (otra ruta, otro puerto):
# ese no se toca. La VRAM se libera solo cuando la tarea lo pide
# ("liberar_vram") o cuando Leandro pulsa el boton, nunca a escondidas.
SRV_NO_RESPONDE = "el motor local no responde"


def motores_con_servidor():
    """ids de engines.json con bloque 'servidor' (los que el runner arranca)."""
    return [m for m in engine_ids() if (get_engine(m) or {}).get("servidor")]


def _srv_puerto(eng):
    u = urlparse(_srv_cfg(eng)["base"] or str((eng.get("healthcheck") or {}).get("url") or ""))
    return u.port or (443 if u.scheme == "https" else 80)


def _srv_exe(eng):
    return _app_path((eng.get("servidor") or {}).get("exe"))


def _srv_models_dir(eng):
    return _app_path((eng.get("servidor") or {}).get("models_dir") or "models")


def _srv_gguf(eng, model):
    """El .gguf de ese modelo en la carpeta del router (nombre = archivo sin .gguf)."""
    d = _srv_models_dir(eng)
    f = d / f"{model}.gguf"
    if f.is_file():
        return f
    try:
        return next((g for g in d.rglob("*.gguf") if g.stem.lower() == str(model).lower()), None)
    except OSError:
        return None


def _srv_no_instalado(eng, model):
    d = _srv_models_dir(eng)
    try:
        hay = sorted(g.stem for g in d.glob("*.gguf") if "mmproj" not in g.name.lower())
    except OSError:
        hay = []
    return (f"el modelo local «{model}» no está instalado: no hay {model}.gguf en {d}. Bájalo con el "
            "descargador (Modelos → Librería → Instalar) y vuelve a lanzar la tarea. Instalados: "
            + (", ".join(hay) or "ninguno"))


def _srv_exe_de(pid):
    """Ruta del exe de un proceso (QueryFullProcessImageNameW, sin psutil). None si no se puede."""
    if not pid:
        return None
    import ctypes
    from ctypes import wintypes
    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    k32.OpenProcess.restype = wintypes.HANDLE
    k32.OpenProcess.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
    h = k32.OpenProcess(0x1000, False, int(pid))  # PROCESS_QUERY_LIMITED_INFORMATION
    if not h:
        return None
    try:
        buf, n = ctypes.create_unicode_buffer(32768), wintypes.DWORD(32768)
        if k32.QueryFullProcessImageNameW(wintypes.HANDLE(h), 0, buf, ctypes.byref(n)):
            return buf.value
    finally:
        k32.CloseHandle(wintypes.HANDLE(h))
    return None


def _srv_oyente(puerto):
    """pid que escucha en el puerto TCP (127.0.0.1, 0.0.0.0 o ::), o None (netstat -ano)."""
    try:
        out = subprocess.run(["netstat", "-ano", "-p", "TCP"], capture_output=True, text=True,
                             timeout=15, **_oculto()).stdout or ""
    except Exception:
        return None
    for ln in out.splitlines():
        c = ln.split()
        if (len(c) >= 5 and c[0].upper() == "TCP" and c[1].rsplit(":", 1)[-1] == str(puerto)
                and c[2] in ("0.0.0.0:0", "[::]:0") and c[-1].isdigit()):
            return int(c[-1])
    return None


def _srv_cmdline(pid):
    ps = _res_psutil()
    if not ps:
        return None
    try:
        return [str(a) for a in ps.Process(pid).cmdline()]
    except Exception:
        return None


def srv_procesos(eng):
    """Quien es quien en el puerto del motor y que procesos del MISMO exe hay.
    -> {"exe", "puerto", "oyente" (pid|None), "oyente_exe", "nuestro" (el
    oyente es el exe del descriptor), "arbol" (oyente + hijos), "huerfanos",
    "otros" (mismo exe en otro puerto: p. ej. un router de prueba; no se
    tocan), "edad_s" (del oyente)}. Huerfano = mismo exe y (a) otro servidor
    en NUESTRO puerto que no es el que escucha (dos peleando por el 8080) o
    (b) un hijo de modelo (-m) cuyo router ya no existe (sigue con la VRAM)."""
    exe = _srv_exe(eng)
    try:
        exe_n = os.path.normcase(str(exe.resolve()))
    except OSError:
        exe_n = os.path.normcase(str(exe))
    puerto = _srv_puerto(eng)
    oy = _srv_oyente(puerto)
    snap = _res_snapshot() or {}
    mios = {}
    for pid, r in snap.items():
        if str(r.get("name") or "").lower() == exe.name.lower():
            ruta = _srv_exe_de(pid)
            if ruta and os.path.normcase(ruta) == exe_n:
                mios[pid] = r
    out = {"exe": str(exe), "puerto": puerto, "oyente": oy, "oyente_exe": _srv_exe_de(oy) if oy else None,
           "nuestro": bool(oy and oy in mios), "arbol": [], "huerfanos": [], "otros": [],
           "edad_s": (time.time() - snap[oy]["ct"]) if oy in snap and snap[oy].get("ct") else None}
    arbol = {oy} if out["nuestro"] else set()
    while True:
        nuevos = {p for p, r in mios.items() if r.get("ppid") in arbol and p not in arbol}
        if not nuevos:
            break
        arbol |= nuevos
    out["arbol"] = sorted(arbol)
    for pid, r in mios.items():
        if pid in arbol or r.get("ppid") in mios:
            continue  # del router vivo, o hijo de otro servidor del mismo exe
        args = _srv_cmdline(pid)
        if args is None:
            continue  # sin linea de comandos no se sabe de quien es: no se toca
        low = [a.lower() for a in args]
        port_arg = low[low.index("--port") + 1] if "--port" in low and low.index("--port") + 1 < len(low) else None
        es_hijo = "-m" in low or "--model" in low
        if port_arg == str(puerto) or (es_hijo and _srv_es_router(eng)):
            out["huerfanos"].append(pid)
        else:
            out["otros"].append(pid)
    return out


def _srv_matar(pid):
    """taskkill /T /F: el proceso y TODO su arbol (los hijos de modelo del router)."""
    try:
        r = subprocess.run(["taskkill", "/PID", str(pid), "/T", "/F"], capture_output=True, text=True,
                           timeout=20, **_oculto())
        return r.returncode == 0
    except Exception:
        return False


def _srv_vram():
    """(usada, total) en MiB segun nvidia-smi, o None. Nunca se inventa."""
    smi = _nvidia_smi()
    if not smi:
        return None
    try:
        p = subprocess.run([smi, "--query-gpu=memory.used,memory.total", "--format=csv,noheader,nounits"],
                           capture_output=True, text=True, timeout=8, creationflags=_NO_WINDOW)
        u, t = [int(float(x)) for x in next(l for l in p.stdout.splitlines() if l.strip()).split(",")[:2]]
        return u, t
    except Exception:
        return None


def _srv_vram_txt(v=None):
    v = _srv_vram() if v is None else v
    return f"{v[0]} MiB" if v else "sin dato (nvidia-smi no respondió)"


def _srv_esperar_puerto_libre(puerto, segundos=15):
    t0 = time.time()
    while time.time() - t0 < segundos:
        if not _srv_oyente(puerto):
            return True
        time.sleep(0.5)
    return False


def _srv_puerto_antes_de_lanzar(eng):
    """Se llama con /health fallando, justo antes de lanzar otro servidor.
    -> (None, '') lanzar; (True, nota) el que habia ya contesta; (False, motivo)
    no se lanza (el puerto es de otro programa o no se libero)."""
    pr = srv_procesos(eng)
    for pid in pr["huerfanos"]:
        log(f"motores: huérfano de {Path(pr['exe']).name} (pid {pid}) sin router vivo: lo cierro con su árbol")
        _srv_matar(pid)
    oy = pr["oyente"]
    if not oy:
        return None, ""
    if not pr["nuestro"]:
        return False, (f"el puerto {pr['puerto']} lo ocupa otro programa ({pr['oyente_exe'] or 'pid ' + str(oy)}); "
                       f"no es el {Path(pr['exe']).name} del Bridge: no lanzo un segundo servidor ni lo cierro")
    espera = llama_cfg(eng)["espera_s"]
    edad = pr["edad_s"] if pr["edad_s"] is not None else espera
    if edad < espera:
        # Nuestro y recien lanzado (otro hilo o un arranque anterior): se espera.
        log(f"motores: {Path(pr['exe']).name} pid {oy} ya está en el {pr['puerto']} arrancando "
            f"({edad:.0f} s): espero a que conteste en vez de lanzar otro")
        t0 = time.time()
        while time.time() - t0 < espera - edad:
            if _health(eng, timeout=2)[0]:
                return True, ""
            if _RUN.get("stop"):
                return False, "parado por el usuario mientras esperaba al servidor local"
            time.sleep(1)
    log(f"motores: {Path(pr['exe']).name} pid {oy} ocupa el {pr['puerto']} y no contesta: lo cierro con su "
        "árbol antes de lanzar uno nuevo (mismo exe, mismo puerto)")
    _srv_matar(oy)
    if not _srv_esperar_puerto_libre(pr["puerto"]):
        return False, f"el puerto {pr['puerto']} no se liberó tras cerrar el pid {oy}"
    return None, ""


def srv_parar(eng, motivo="lo pidió el usuario"):
    """Para DE VERDAD el servidor: mata el proceso que escucha en su puerto
    (solo si es el exe del descriptor) con todo su arbol, y los huerfanos del
    mismo exe; espera a que el puerto quede libre. -> (ok, nota)."""
    got = _llama_lock.acquire(timeout=3)  # si una carga lo tiene, se para igual: lo pidio Leandro
    try:
        pr = srv_procesos(eng)
        exe = Path(pr["exe"])
        if pr["oyente"] and not pr["nuestro"]:
            return False, (f"el puerto {pr['puerto']} lo ocupa otro programa ({pr['oyente_exe'] or pr['oyente']}); "
                           f"no es el {exe.name} del Bridge y no lo toco")
        objetivo = ([pr["oyente"]] if pr["nuestro"] else []) + pr["huerfanos"]
        if not objetivo:
            _SRV.update(proc=None, modelos={}, rol=None, adoptado=None, hora=time.time())
            return True, f"{exe.stem} ya estaba parado (puerto {pr['puerto']} libre)"
        v0 = _srv_vram()
        for pid in objetivo:
            _srv_matar(pid)
        p = _SRV.get("proc")
        if p is not None:
            try:
                p.wait(timeout=10)
            except Exception:
                pass
        libre = _srv_esperar_puerto_libre(pr["puerto"])
        time.sleep(1)  # el driver tarda un instante en devolver la VRAM
        v1 = _srv_vram()
        _SRV.update(proc=None, modelos={}, rol=None, adoptado=None, hora=time.time())
        quedan = [q for q in srv_procesos(eng)["huerfanos"]]
        nota = (f"{exe.stem} parado ({motivo}): pid {', '.join(map(str, objetivo))} con su árbol "
                f"({len(pr['arbol'])} proceso(s) del router); puerto {pr['puerto']} "
                + ("libre" if libre else "TODAVÍA OCUPADO") + f"; VRAM {_srv_vram_txt(v0)} → {_srv_vram_txt(v1)}"
                + (f"; quedan huérfanos {quedan}" if quedan else ""))
        log(f"motores: {nota}")
        return libre and not quedan, nota
    finally:
        if got:
            _llama_lock.release()


def srv_liberar_vram(eng, motivo="lo pidió el usuario"):
    """Libera la VRAM del motor local: en modo router descarga TODOS los
    modelos (POST /models/unload; el router sigue vivo, ~0 MiB); un
    llama-server mono-modelo solo la suelta parandolo. -> (ok, nota)."""
    if not _health(eng, timeout=2)[0]:
        pr = srv_procesos(eng)
        if pr["nuestro"] or pr["huerfanos"]:
            return srv_parar(eng, motivo + "; no contestaba")
        return True, "el motor local no estaba encendido: no ocupaba VRAM"
    if not _srv_es_router(eng) or srv_rol(eng) == "mono":
        return srv_parar(eng, motivo + "; mono-modelo: solo suelta la VRAM al pararlo")
    v0 = _srv_vram()
    try:
        est = srv_modelos(eng)
    except LocalCallError as e:
        return srv_parar(eng, f"{motivo}; GET /models no contestó ({e})")
    cargados = [m for m, st in est.items() if st in ("loaded", "loading", "sleeping")]
    if not cargados:
        return True, f"no había ningún modelo cargado (VRAM {_srv_vram_txt(v0)})"
    for m in cargados:
        srv_descargar_modelo(eng, m)
    t0 = time.time()
    while time.time() - t0 < 30:
        try:
            if not any(st in ("loaded", "loading") for st in srv_modelos(eng).values()):
                break
        except LocalCallError:
            break
        time.sleep(0.5)
    time.sleep(1)
    v1 = _srv_vram()
    nota = (f"VRAM liberada ({motivo}): descargados {', '.join(cargados)} por POST /models/unload, el router "
            f"sigue encendido; VRAM {_srv_vram_txt(v0)} → {_srv_vram_txt(v1)}")
    log(f"motores: {nota}")
    return True, nota


def srv_cambiar_modelo(eng, model, aviso=None):
    """Cambio de modelo por endpoint, sin matar el proceso: descarga el que
    esta y carga el pedido. Si el router no esta encendido, lo arranca."""
    if _srv_es_router(eng) and not _srv_gguf(eng, model):
        return False, _srv_no_instalado(eng, model)
    if not _health(eng, timeout=2)[0]:
        return ensure_llama_server(eng, model)
    return srv_cargar_modelo(eng, model, aviso=aviso)


def srv_liberar_para_tarea(task, cuando):
    """La tarea pidio "liberar_vram" (p. ej. antes de Blender): todos los
    motores con servidor sueltan su VRAM. -> lista de notas."""
    notas = []
    paso0 = state.get("paso")
    state["paso"] = "Liberando VRAM del motor local…"
    try:
        for mid in motores_con_servidor():
            ok, n = srv_liberar_vram(get_engine(mid), f"la tarea {task.get('id')} lo pide (liberar_vram: {cuando})")
            notas.append(f"{mid}: {n}" if ok else f"{mid}: no se pudo: {n}")
    finally:
        state["paso"] = paso0
    return notas


def srv_arranque_limpio():
    """Al abrir la app: cierra huerfanos del mismo exe y, si ya hay un router
    del Bridge vivo en el puerto, lo adopta (no se lanza otro). Nunca toca un
    proceso de otro programa (Ollama trae su propio llama-server.exe)."""
    for mid in motores_con_servidor():
        eng = get_engine(mid)
        if not _srv_exe(eng).is_file():
            continue
        try:
            with _llama_lock:
                pr = srv_procesos(eng)
                for pid in pr["huerfanos"]:
                    ok = _srv_matar(pid)
                    log(f"motores: arranque: huérfano de {Path(pr['exe']).name} pid {pid} "
                        + ("cerrado con su árbol" if ok else "NO se pudo cerrar"))
                if pr["nuestro"]:
                    _SRV["adoptado"] = pr["oyente"]
                    log(f"motores: arranque: ya hay un {Path(pr['exe']).name} del Bridge vivo en el "
                        f"{pr['puerto']} (pid {pr['oyente']}): se usa ese, no se lanza otro")
                elif pr["oyente"]:
                    log(f"motores: arranque: el puerto {pr['puerto']} lo usa otro programa "
                        f"({pr['oyente_exe'] or pr['oyente']}); no lo toco")
        except Exception as e:
            log(f"motores: arranque limpio de {mid}: {type(e).__name__}: {e}")


def srv_al_salir():
    """Al salir de la app (Salir, no minimizar): si settings.json
    "motor_local_parar_al_salir" (por defecto true), para el servidor local
    del Bridge para que la VRAM no quede secuestrada."""
    if load_settings().get("motor_local_parar_al_salir", True) is False:
        log("motores: al salir: el motor local se queda encendido (motor_local_parar_al_salir: false)")
        return
    for mid in motores_con_servidor():
        try:
            ok, n = srv_parar(get_engine(mid), "al salir de la app")
            log(f"motores: al salir ({mid}): {n}")
        except Exception as e:
            log(f"motores: al salir ({mid}): {type(e).__name__}: {e}")


def srv_snapshot(eng):
    """Estado REAL para la pestaña Modelos: GET /models (nunca solo /health),
    nvidia-smi y quien esta en el puerto."""
    out = {"puerto": _srv_puerto(eng), "base": _srv_cfg(eng)["base"], "responde": False, "rol": None,
           "modelos": {}, "error": "", "cargando": _SRV.get("cargando"), "router": _srv_es_router(eng)}
    out["instalado"] = _llama_installed(eng)
    try:
        out["proc"] = srv_procesos(eng)
    except Exception as e:
        out["proc"] = {"oyente": None, "nuestro": False, "huerfanos": [], "arbol": [], "oyente_exe": None}
        out["error"] = f"no pude listar procesos ({type(e).__name__})"
    if out["proc"].get("oyente"):
        try:
            out["modelos"] = srv_modelos(eng, timeout=2)
            out["responde"] = True
            out["rol"] = srv_rol(eng) if out["router"] else "mono"
        except LocalCallError as e:
            out["error"] = str(e)[:200]
    out["vram"] = _srv_vram()
    try:
        out["instalados"] = sorted(g.stem for g in _srv_models_dir(eng).glob("*.gguf")
                                   if "mmproj" not in g.name.lower())
    except OSError:
        out["instalados"] = []
    return out


def _despertar(eng):
    """healthcheck.despertar del descriptor (p. ej. ['{binario}', 'list'],
    que despierta el servidor de fondo de Ollama). Sin shell."""
    cmd = (eng.get("healthcheck") or {}).get("despertar")
    req = ((eng.get("_v2") or {}).get("requisitos") or {}) if isinstance(eng.get("_v2"), dict) else {}
    if not isinstance(cmd, list) or not cmd:
        return
    exe = shutil.which(str(req.get("binario") or eng.get("binario") or ""))
    if "{binario}" in cmd and not exe:
        return
    try:
        _run_capture([exe if x == "{binario}" else str(x) for x in cmd], 60)
    except Exception:
        pass


def _req_binario(eng):
    """Binario de requisitos (motores HTTP que tambien tienen programa)."""
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else {}
    return ((d.get("requisitos") or {}).get("binario")) or None


# ---- interruptor por motor (t-interruptor-motor). Apagar NO borra ni toca el
# descriptor de engines.json: el motor se aparta (settings.json «motores_off»).
# Apagado: engine_status dice «desactivado», asi que no sale en el selector,
# ni en el router, ni en la cadena de jueces/fallback; una tarea que lo pida
# se rechaza. El principal no se apaga sin elegir antes quien lo sustituye.
def motores_apagados():
    try:
        return set(load_settings().get("motores_off") or [])
    except Exception:
        return set()


def _motor_de_modelo(model):
    m = str(model or "")
    if m in ("sonnet", "opus", "haiku"):
        return "claude"
    if m.startswith("motor:"):
        return m.split(":", 1)[1]
    if m.startswith("ollama:"):
        return "ollama"
    return None


def motor_activar(mid, on, sustituto=None):
    """(ok, mensaje en palabras normales)."""
    ids = [m for m in (load_engines()[0].get("motores") or {}) if not m.startswith("_")]
    if mid not in ids:
        return False, f"el motor «{mid}» no existe en engines.json"
    s = load_settings()
    off = set(s.get("motores_off") or [])
    avisos = []
    if not on:
        principal = default_motor()
        activos = [m for m in ids if m not in off and m != mid]
        if mid == principal:
            if not sustituto or sustituto == mid or sustituto not in activos:
                return False, (f"«{mid}» es el motor principal: antes de apagarlo elige cuál queda como principal "
                               f"({', '.join(activos) or 'no hay otro motor activo'}). Nunca dejo la app sin motor "
                               "principal.")
            s["motor_principal"] = sustituto
            avisos.append(f"ahora el principal es «{sustituto}»")
        off.add(mid)
        de = s.get("default_engine")
        if _motor_de_modelo(de) == mid:  # la superficie que lo usaba vuelve a algo sensato
            s["default_engine"] = "motor:auto"
            s["motor"] = AUTO
            avisos.append("el modelo por defecto de Preguntar usaba este motor: vuelve a «Automático»")
    else:
        off.discard(mid)
    s["motores_off"] = sorted(off)
    save_settings(s)
    if on:
        ok, why = engine_status(mid)
        msg = f"«{mid}» activado: " + ("disponible" if ok else f"no disponible ({why})")
    else:
        msg = f"«{mid}» desactivado: ya no sale en el selector, ni en el router, ni en los jueces"
    if avisos:
        msg += ". " + "; ".join(avisos)
    log(f"motores: {msg}")
    superficies_revisar()
    try:
        _refresh_engine_widgets()
    except Exception:
        pass
    return True, msg


def _mot_onoff_ui():
    W = _widgets
    mid = _MOT.get("sel")
    if not mid:
        return
    on = mid in motores_apagados()  # apagado -> se enciende
    sustituto = None
    if not on and mid == default_motor():
        from tkinter import simpledialog
        activos = [m for m in engine_ids() if m != mid]
        sustituto = simpledialog.askstring(
            "Motor principal", f"«{mid}» es el motor principal. ¿Cuál queda como principal? ({', '.join(activos)})",
            parent=_root)
        if not sustituto:
            return
        sustituto = sustituto.strip()
    ok, msg = motor_activar(mid, on, sustituto)
    if not ok:
        messagebox.showwarning("Motor", msg)
    _mot_pintar_onoff(msg if ok else None)
    _mot_render()


def _mot_pintar_onoff(msg=None):
    W, k = _widgets, _MOT.get("kit")
    mid = _MOT.get("sel")
    if k is None or W.get("mot_onoff") is None or not mid:
        return
    apagado = mid in motores_apagados()
    k.set_label(W["mot_onoff"], text=("Desactivado por ti (el descriptor sigue en engines.json, intacto). "
                                      if apagado else "Activo. ") + (msg or ""),
                color="orange_text" if apagado else "muted")
    try:
        W["mot_onoff_btn"].configure(text="Activar este motor" if apagado else "Desactivar este motor")
    except Exception:
        pass


# ---- modelo por superficie + niveles del modo Automatico
# (t-modelo-por-superficie-auto). Cada superficie guarda su modelo en
# settings.json («modelo_superficie»); cambiar una no toca las demas. Un modelo
# que deja de estar (motor apagado, desinstalado, sin credencial) nunca se queda
# en silencio: la superficie vuelve a «Automático» y la app lo dice.
SUPERFICIES = (("pregunta", "Pregunta rápida (paleta y cajita)"), ("chat", "Chat de Tareas"),
               ("comando", "Comandos de IA guardados"), ("revision", "Revisión del runner"))
AUTO_NIVELES = (("rapido", "Rápido"), ("equilibrado", "Equilibrado"), ("potente", "Potente"))
_AUTO_NIVEL_TXT = {"rapido": "local o barato primero", "equilibrado": "barato primero, caro si hace falta",
                   "potente": "el mejor disponible primero"}


def auto_nivel():
    n = load_settings().get("auto_nivel")
    return n if n in dict(AUTO_NIVELES) else "equilibrado"


def auto_nivel_poner(n):
    if n not in dict(AUTO_NIVELES):
        return
    s = load_settings()
    s["auto_nivel"] = n
    save_settings(s)
    log(f"router: modo Automático en «{dict(AUTO_NIVELES)[n]}» ({_AUTO_NIVEL_TXT[n]})")
    try:
        _update_tray_title()
    except Exception:
        pass


def auto_nivel_ciclar():
    orden = [k for k, _l in AUTO_NIVELES]
    auto_nivel_poner(orden[(orden.index(auto_nivel()) + 1) % len(orden)])
    toast(f"Auto: {dict(AUTO_NIVELES)[auto_nivel()]}")


def _modelo_disponible(model):
    """(ok, motivo) de un modelo del selector («sonnet», «motor:codex»,
    «ollama:…», «api:…», «motor:auto»)."""
    m = str(model or "")
    if m in ("", "motor:auto", AUTO):
        return True, ""
    mid = _motor_de_modelo(m) or ("api" if m.startswith("api:") else None)
    if mid == "api":
        return (True, "") if any(c[1] == m for c in engine_choices()) else (False, "su clave ya no está")
    if mid is None:
        return False, "no sé de qué motor es"
    if mid in motores_apagados():
        return False, f"el motor «{mid}» está desactivado"
    if not any(c[1] == m for c in engine_choices()):
        return False, "ya no está en la lista de modelos disponibles"
    return True, ""


def superficie_modelo(sup, avisar=True):
    """El modelo de la superficie, comprobado. Si ya no vale, vuelve a
    «Automático» (que elige uno que sí esté: Hermes local si no hay nube) y lo dice."""
    s = load_settings()
    tabla = dict(s.get("modelo_superficie") or {})
    m = tabla.get(sup) or ""
    if not m:
        return ""
    ok, why = _modelo_disponible(m)
    if ok:
        return m
    tabla[sup] = "motor:auto"
    s["modelo_superficie"] = tabla
    save_settings(s)
    nom = next((lab for lab, mm, _d in engine_choices() if mm == m), m)
    msg = f"el modelo {nom} ya no está ({why}): {dict(SUPERFICIES).get(sup, sup)} usa «Automático»"
    log(f"superficies: {msg}")
    _CAMBIOS_MOTOR.append({"at": _now_iso(), "de": str(m), "a": "Automático",
                           "motivo": f"{dict(SUPERFICIES).get(sup, sup)}: {why}"})
    if avisar:
        try:
            toast(f"{nom[:20]} ya no está: uso Automático")
        except Exception:
            pass
    return "motor:auto"


def superficie_poner(sup, model):
    s = load_settings()
    tabla = dict(s.get("modelo_superficie") or {})
    tabla[sup] = model
    s["modelo_superficie"] = tabla
    save_settings(s)
    log(f"superficies: {dict(SUPERFICIES).get(sup, sup)} → {model}")


def superficies_revisar():
    """Tras apagar/encender un motor: ninguna superficie se queda con un modelo roto."""
    return {sup: superficie_modelo(sup) for sup, _l in SUPERFICIES}


def _label_de_modelo(model):
    return next((lab for lab, mm, _d in engine_choices() if mm == model), None)


def engine_status(motor_id, autostart=False):
    """(disponible, motivo en palabras normales)."""
    if motor_id in motores_apagados():
        return False, "desactivado por ti (Modelos → Motores → Activar este motor)"
    eng = get_engine(motor_id)
    if eng is None:
        return False, f"el motor '{motor_id}' no existe en engines.json"
    return engine_status_rt(eng, autostart)


def engine_status_rt(eng, autostart=False):
    """Disponibilidad leyendo solo el descriptor: bien formado, credencial,
    binario y, si es HTTP, que responda (o que se pueda arrancar solo)."""
    tipo = eng.get("tipo")
    if tipo == "_mal_formado":
        return False, "descriptor mal formado: " + "; ".join(eng.get("_problemas") or [])[:400]
    if tipo == "cli_sincrono" and not _resolve_binary(eng):
        return False, f"no está instalado: no encuentro '{eng.get('binario')}' en el PATH"
    acc = acceso_motor(eng) if (eng.get("credencial_ref") or eng.get("autenticacion")) else None
    if acc is not None and not acc["ok"]:
        return False, acc["motivo"]
    if tipo == "cli_sincrono":
        b = _resolve_binary(eng)
        extra = f"; {acc['motivo']}" if acc and acc["modo"] == "sesion_cli" else ""
        return True, f"binario: {b[-1]}{extra}"
    if tipo == "api_sincrona":
        if eng.get("servidor"):
            if autostart:
                return ensure_llama_server(eng)
            ok, why = _health(eng)
            if ok and _srv_es_router(eng) and srv_rol(eng) == "router":
                # Salud del router NO es modelo listo: lo dice GET /models.
                m = _srv_modelo_defecto(eng)
                try:
                    st = srv_modelos(eng).get(m)
                except LocalCallError as e:
                    return True, f"router encendido, pero GET /models no contesta ({e}); se reintenta al usarlo"
                if st == "loaded":
                    return True, "responde"
                if st == "loading":
                    return True, f"router encendido; {SRV_AVISO_CARGA} {m} (aún no es {SRV_LOCAL_LISTO})"
                if st == "sleeping":
                    return True, f"router encendido; modelo {m} dormido (VRAM libre; despierta al usarlo)"
                if st is None:
                    return False, f"router encendido, pero no tiene el modelo {m} (¿falta en models\\?)"
                return True, (f"router encendido; modelo {m} sin cargar (se carga al usarlo): "
                              f"/health OK no es {SRV_LOCAL_LISTO}")
            if ok:
                return True, "responde"
            inst, msg = _llama_installed(eng)
            return (True, "apagado; se arranca solo al usarlo") if inst else (False, msg)
        ok, why = _health(eng)
        if not ok and autostart and (eng.get("healthcheck") or {}).get("despertar"):
            _despertar(eng)
            ok, why = _health(eng, timeout=5)
        if not ok and _req_binario(eng) and not shutil.which(_req_binario(eng)):
            return False, f"no está instalado: no encuentro '{_req_binario(eng)}' ({why})"
        return (True, "responde") if ok else (False, why)
    if tipo == "api_asincrona":
        if eng.get("credencial_ref"):
            return True, "clave guardada"
        if eng.get("clave_api"):  # forma v1
            return (True, "clave guardada") if _named_api_key(eng.get("clave_api")) else (
                False, f"falta la clave en APIs (ponle de nombre '{eng.get('clave_api')}')")
        return False, "falta credencial_ref en el descriptor"
    return False, f"tipo de motor desconocido en engines.json: {tipo}"


def engines_summary():
    out = {}
    for mid in engine_ids():
        ok, why = engine_status(mid)
        out[mid] = {"disponible": ok, "motivo": why}
    return out


# ---- modo Automatico: elige el motor con reglas de engines.json -> router
# Sin llamar a ningun modelo: cuesta $0 y no anade espera.
AUTO = "auto"
AUTO_LABEL = "Automático (recomendado)"


def _router_cfg():
    r = load_engines()[0].get("router")
    return r if isinstance(r, dict) else {}


def global_auto():
    """En Ajustes > Modelos esta elegido Automatico."""
    return load_settings().get("motor") == AUTO


def _num(v, default=0):
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def _kw_hit(norm_text, words):
    """Primera palabra clave que aparece (sin tildes ni mayusculas).
    'depur*' = cualquier palabra que empiece por depur."""
    for w in words or []:
        k = _norm(w).strip()
        pref = k.endswith("*")
        k = k.rstrip("*").strip()
        if not k:
            continue
        pat = ((r"(?<!\w)" if k[0].isalnum() else "") + re.escape(k)
               + ("" if pref or not k[-1].isalnum() else r"(?!\w)"))
        if re.search(pat, norm_text):
            return w
    return None


def _looks_like_code(prompt, cfg):
    for p in cfg.get("patrones_codigo") or []:
        try:
            if re.search(str(p), prompt, re.M):
                return True
        except re.error:
            continue
    return False


def _n_partes(prompt):
    items = len(re.findall(r"^\s*(?:[-*•]|\d+[.)])\s+\S", prompt, re.M))
    return max(items, prompt.count("?"))


def _router_conds(cond, ctx):
    """(encaja, por que). Todas las condiciones del bloque deben cumplirse."""
    why = []
    for k, v in (cond or {}).items():
        if str(k).startswith("_"):
            continue
        if k == "palabras":
            hit = _kw_hit(ctx["norm"], v)
            if not hit:
                return False, []
            why.append(f"«{hit}»")
        elif k == "sin_palabras":
            if _kw_hit(ctx["norm"], v):
                return False, []
        elif k == "min_chars":
            if ctx["chars"] < _num(v):
                return False, []
            why.append(f"{ctx['chars']} letras")
        elif k == "max_chars":
            if ctx["chars"] > _num(v):
                return False, []
            why.append(f"{ctx['chars']} letras")
        elif k == "codigo":
            if ctx["codigo"] != bool(v):
                return False, []
            why.append("parece código" if v else "sin código")
        elif k == "min_partes":
            if ctx["partes"] < _num(v):
                return False, []
            why.append(f"{ctx['partes']} partes")
        elif k == "min_criterios":
            if ctx["criterios"] < _num(v):
                return False, []
            why.append(f"{ctx['criterios']} criterios")
        else:
            log(f"router AVISO: condición desconocida '{k}' en engines.json; esa regla no encaja")
            return False, []
    return True, why


def _router_available(motor_id):
    """Disponible para elegirlo, sin esperar: un motor que se arranca solo
    (llama) cuenta si esta instalado; preguntarle a un puerto apagado tarda
    2 s en Windows y el runner lo enciende al usarlo."""
    if motor_id in motores_apagados():
        return False, "desactivado por ti"
    if motor_id in ("claude", "codex", "gemini"):  # nube: lo que diga el mapa (t-mapa-ampliado)
        ok, why = mapa_permite_nube(motor_id)
        if not ok:
            return False, why
    eng = get_engine(motor_id)
    if eng and eng.get("tipo") == "api_sincrona" and eng.get("servidor"):
        inst, msg = _llama_installed(eng)
        return (True, "instalado") if inst else (False, msg)
    return engine_status(motor_id)


def route_task(prompt, criterios=None):
    """Modo Automatico. ({elegido, motor, modelo, motivo, regla}, None) o
    (info_parcial, error). Primera regla que encaja gana; luego sube un
    escalon si la tarea es exigente; luego mira que el motor este disponible."""
    cfg = _router_cfg()
    targets = {k: v for k, v in (cfg.get("objetivos") or {}).items()
               if isinstance(v, dict) and not str(k).startswith("_")}
    if not targets:
        return None, ("Automático: engines.json no tiene la sección router.objetivos; "
                      "elige un motor a mano o añade el router")
    prompt = str(prompt or "")
    crits = [c for c in (criterios or []) if isinstance(c, str) and c.strip()]
    ctx = {"norm": _norm(prompt), "chars": len(prompt.strip()), "codigo": _looks_like_code(prompt, cfg),
           "partes": _n_partes(prompt), "criterios": len(crits)}
    pick = str(cfg.get("por_defecto") or "sonnet")
    motivo, regla, no_subir = "ninguna regla encaja: el de por defecto", None, False
    for r in cfg.get("reglas") or []:
        if not isinstance(r, dict) or r.get("objetivo") not in targets:
            continue
        ok, why = _router_conds(r.get("si"), ctx)
        if not ok:
            continue
        alts = r.get("y_alguno_de")
        if alts:
            for c in alts:
                ok2, why2 = _router_conds(c, ctx)
                if ok2:
                    why += why2
                    break
            else:
                continue
        pick, regla, no_subir = r["objetivo"], r.get("nombre"), bool(r.get("no_subir"))
        motivo = str(r.get("motivo") or regla or "regla") + (f" ({', '.join(why)})" if why else "")
        break
    up = cfg.get("subir_escalon") or {}
    escalera = [x for x in (up.get("escalera") or []) if x in targets]
    nv, pick_regla = auto_nivel(), pick  # rápido / equilibrado / potente (t-modelo-por-superficie-auto)
    if nv == "rapido":
        no_subir = True
    if not no_subir and pick in escalera and escalera.index(pick) + 1 < len(escalera):
        reason = None
        hit = _kw_hit(_norm(" ".join(crits)), up.get("palabras_en_criterios")) if crits else None
        if up.get("min_criterios") and len(crits) >= _num(up["min_criterios"], 99):
            reason = f"{len(crits)} criterios de aceptación"
        elif hit:
            reason = f"criterio exigente «{hit}»"
        elif up.get("min_chars") and ctx["chars"] >= _num(up["min_chars"], 10 ** 9):
            reason = f"encargo muy largo ({ctx['chars']} letras)"
        if reason:
            nxt = escalera[escalera.index(pick) + 1]
            motivo += f"; sube un escalón ({pick} → {nxt}) por {reason}"
            pick = nxt
    if nv == "rapido" and pick_regla in escalera and escalera.index(pick_regla) > 0:
        pick = escalera[escalera.index(pick_regla) - 1]
        motivo += f"; nivel Rápido: baja un escalón ({pick_regla} → {pick})"
    elif nv == "potente" and pick in escalera and escalera.index(pick) + 1 < len(escalera):
        nxt = escalera[escalera.index(pick) + 1]
        motivo += f"; nivel Potente: sube un escalón ({pick} → {nxt})"
        pick = nxt
    # El elegido tiene que estar disponible; si no, sus respaldos en orden.
    first, cola_, seen, faltan = pick, [pick], [], []
    while cola_:
        cur = cola_.pop(0)
        if cur in seen or cur not in targets:
            continue
        seen.append(cur)
        t = targets[cur]
        ok, why = _router_available(str(t.get("motor") or ""))
        if ok:
            txt = f"{cur}: {motivo}"
            if faltan:
                txt += " (" + "; ".join(faltan) + f"; respondió {cur})"
            return {"elegido": cur, "motor": str(t.get("motor")), "modelo": t.get("modelo"),
                    "motivo": txt[:400], "regla": regla}, None
        faltan.append(f"{cur} no está disponible: {why}")
        cola_ += [x for x in (t.get("respaldo") or []) if x not in seen]
    etq = targets[first].get("etiqueta") or first
    info = {"elegido": first, "motor": str(targets[first].get("motor")), "modelo": None,
            "motivo": f"{first}: {motivo}", "regla": regla}
    return info, f"Automático eligió {etq} ({motivo}), pero {'; '.join(faltan)}"


def auto_label(elegido):
    """'Sonnet', 'Hermes'... para la ventana."""
    t = (_router_cfg().get("objetivos") or {}).get(elegido)
    return (t.get("etiqueta") if isinstance(t, dict) else None) or str(elegido).capitalize()


def _auto_fields(enr):
    """Campos que llevan el resultado y la familia de una tarea en Automatico."""
    if not isinstance(enr, dict) or not enr.get("elegido"):
        return {}
    return {"modo_motor": "auto", "motor_elegido": enr["elegido"],
            "motivo_eleccion": enr.get("motivo") or ""}


# ---- sesiones locales (motores HTTP sin sesion propia)
def _session_load(sid):
    try:
        data = json.loads((SESSIONS_DIR / f"{sid}.json").read_text(encoding="utf-8"))
        return [m for m in data if isinstance(m, dict) and m.get("role") in ("user", "assistant")]
    except (OSError, ValueError, TypeError):
        return []


def _session_save(sid, msgs):
    try:
        SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
        (SESSIONS_DIR / f"{sid}.json").write_text(
            json.dumps(msgs[-40:], ensure_ascii=False, indent=1), encoding="utf-8")
    except OSError:
        pass


def _trim_messages(msgs, budget=14000):
    """Cabe en el contexto (8192 tokens en llama-server): se queda el primer
    mensaje (el encargo) y los mas recientes."""
    if sum(len(m["content"]) for m in msgs) <= budget:
        return msgs
    first = dict(msgs[0], content=msgs[0]["content"][:4000])
    rest, total = [], len(first["content"])
    for m in reversed(msgs[1:]):
        if total + len(m["content"]) > budget and rest:
            break
        rest.insert(0, m)
        total += len(m["content"])
    return [first] + rest


# ---- un resultado, el mismo para todos los motores
def _base_result(task, motor_id):
    return {
        "runner": f"growi-bridge/{VERSION}", "id": task["id"], "status": "error",
        "started_at": _now_iso(), "finished_at": None, "duration_s": None,
        "exit_code": None, "result": "", "cost_usd": None, "num_turns": None,
        "session_id": None, "stderr": "", "error": None,
        "motor": motor_id, "modelo": task.get("modelo"),
        "ronda": task.get("ronda", 0), "tarea_padre": task.get("tarea_padre"),
        "raiz": task.get("raiz") or task["id"], "fase": task.get("fase"),
        "proyecto": _proyecto_nombre(task.get("cwd"), task.get("proyecto")),  # t-gasto-pronostico
    }


def _kill_tree(proc):
    """Mata el proceso y todos sus hijos (claude/codex lanzan node). Con
    psutil, hijos primero y luego el padre; sin psutil, taskkill /T /F."""
    ps = _res_psutil()
    if ps is not None:
        try:
            parent = ps.Process(proc.pid)
            kids = parent.children(recursive=True)
            for k in kids:
                try:
                    k.kill()
                except ps.Error:
                    pass
            parent.kill()
            ps.wait_procs(kids + [parent], timeout=10)
        except ps.Error:
            pass
    else:
        try:
            subprocess.run(["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                           capture_output=True, timeout=15, **_oculto())
        except Exception:
            pass
    try:
        if proc.poll() is None:
            proc.kill()
    except Exception:
        pass


def stop_current_task():
    """Boton Parar: mata de verdad el proceso del motor (o corta la conexion
    con el motor local) y no deja que se creen mas rondas."""
    tid = state.get("current")
    if not tid:
        return False, "no hay ninguna tarea corriendo"
    _RUN["stop"] = True
    hecho = []
    proc = _RUN.get("proc")
    if proc is not None and proc.poll() is None:
        _kill_tree(proc)
        hecho.append(f"proceso {proc.pid} terminado")
    conn = _RUN.get("conn")
    if conn is not None:
        try:
            if conn.sock is not None:
                conn.sock.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        try:
            conn.close()
        except Exception:
            pass
        hecho.append("conexión con el motor local cortada")
    msg = f"Parar: {tid}: " + (", ".join(hecho) or "se para en cuanto termine el paso actual")
    log(msg)
    return True, msg


def _build_cli_cmd(task, motor_id, eng, prompt, abilities=True):
    base = _resolve_binary(eng)
    if not base:
        return None
    # Sin reanudar declarado, un session_id no se le pasa al motor.
    resume = bool(task.get("session_id")) and soporta_reanudar(eng)
    tpl = eng.get("comando_reanudar") if resume and eng.get("comando_reanudar") else eng.get("comando")
    tools = _cap(eng, "herramientas")
    allowed = task.get("allowed_tools") if tools else None
    off_tools = []
    if _cap(eng, "habilidades_growi") and abilities:
        off_tools = [k.split(":", 1)[1] for k in disabled_abilities() if k.startswith("tool:")]
        allowed = _filter_tools(allowed, off_tools)
    modelo = task.get("modelo") or (eng.get("modelo") or {}).get("por_defecto") or ""
    sid = (task.get("session_id") or "") if resume else ""
    vars_ = {
        "prompt": prompt, "cwd": task["cwd"],
        "modelo": modelo, "model": modelo, "session_id": sid, "session": sid,
        "allowed_tools": allowed or "", "disallowed_tools": ",".join(off_tools),
        "permission_mode": (task.get("permission_mode") or "") if tools else "",
    }
    opc = []
    tpl_huecos = _huecos(tpl or [])
    mflag = (eng.get("modelo") or {}).get("opcional")
    if vars_["modelo"] and mflag and not {"model", "modelo"} & tpl_huecos:
        opc += _fill(mflag, vars_)
    sflag = (eng.get("sesion") or {}).get("opcional")
    if resume and sflag and not eng.get("comando_reanudar") and not {"session", "session_id"} & tpl_huecos:
        opc += _fill(sflag, vars_)
    perms = eng.get("permisos") or {}
    for pair in perms.get("opcionales") or []:
        if all(vars_.get(p) for p in _PH_RE.findall(" ".join(pair))):
            opc += _fill(pair, vars_)
    perm_args = []
    if isinstance(perms.get("por_modo"), dict):
        perm_args = list(perms["por_modo"].get(vars_["permission_mode"], []))
    cmd, placed = [], False
    for part in tpl or []:
        if isinstance(part, list):
            # Sublista opcional: solo si todos sus huecos tienen valor.
            if all(vars_.get(h) for h in _huecos(part)):
                cmd += [str(_fill(x, vars_)) for x in part]
        elif part == "{binario}":
            cmd += base
        elif part == "{permisos}":
            cmd += perm_args
        elif part == "{opcionales}":
            cmd += opc
            placed = True
        else:
            cmd.append(str(_fill(part, vars_)))
    if not placed:
        cmd += opc
    pres = task.get("presupuesto_max_usd")
    if motor_id == "claude" and isinstance(pres, (int, float)) and pres > 0 and "-p" in cmd:
        # Tope nativo de Claude Code (solo con -p); los demas motores los corta el runner por acumulado.
        cmd += ["--max-budget-usd", f"{pres:.2f}"]
    return cmd


def _rutas(spec):
    """Las rutas de una regla de extraer: 'a.b', ['a', 'b'] o {"ruta": ...}."""
    if isinstance(spec, dict):
        spec = spec.get("ruta")
    if isinstance(spec, str):
        return [spec]
    return [x for x in spec if isinstance(x, str)] if isinstance(spec, list) else []


def extraer_valor(spec, data, numero=False):
    """(valor, dado). dado=False si el descriptor dice "no_lo_da" o si la
    ruta no aparece: entonces la ventana dice 'sin dato', nunca un numero
    inventado. {"fijo": x} es un valor declarado (p. ej. $0 en local)."""
    if spec is None or spec in ("no_lo_da", "historial_local"):
        return None, False
    if isinstance(spec, (int, float)) and not isinstance(spec, bool):
        return spec, True  # forma v1: costo 0.0 / turnos 1
    if isinstance(spec, dict) and "fijo" in spec:
        return spec["fijo"], True
    for r in _rutas(spec):
        v = _get_path(data, r) if data is not None else None
        if v is None or v == "":
            continue
        if numero and (not isinstance(v, (int, float)) or isinstance(v, bool)):
            continue
        return v, True
    return None, False


def _cumple(ev, cond):
    return all(str(_get_path(ev, k)) == str(v) for k, v in (cond or {}).items())


def _parse_jsonl(motor_id, sal, stdout, rc, result):
    """json_por_lineas generico: cada regla de extraer dice de que evento
    (campo 'type') y de que ruta sale cada cosa. Tambien entiende la forma
    v1 (campo / tipo_item)."""
    def regla(k):
        r = sal.get(k)
        if isinstance(r, dict) and "tipo_item" in r:  # forma v1
            r = {"evento": r.get("evento"), "ruta": f"item.{r.get('campo')}",
                 "si": {"item.type": r.get("tipo_item")}}
        elif isinstance(r, dict) and "campo" in r and "ruta" not in r:
            r = dict(r, ruta=r["campo"])
        elif isinstance(r, dict) and r.get("evento") and "ruta" not in r and k == "turnos":
            r = {"contar_evento": r["evento"]}  # forma v1 de turnos
        return r
    txt, ses, cos, tur = regla("texto"), regla("sesion"), regla("costo"), regla("turnos")
    errc = sal.get("error") or {}
    texts, errs, turns, sid, cost = [], [], 0, None, None
    for line in stdout.splitlines():
        try:
            ev = json.loads(line)
        except ValueError:
            continue
        if not isinstance(ev, dict):
            continue
        t = ev.get("type")
        for r, kind in ((txt, "texto"), (ses, "sesion"), (cos, "costo")):
            if isinstance(r, dict) and r.get("evento") == t and _cumple(ev, r.get("si")):
                v, ok = extraer_valor({"ruta": r.get("ruta")}, ev, numero=kind == "costo")
                if ok and kind == "texto":
                    texts.append(str(v))
                elif ok and kind == "sesion":
                    sid = v
                elif ok:
                    cost = v
        if isinstance(tur, dict) and tur.get("contar_evento") == t:
            turns += 1
        if t in (errc.get("eventos") or []):
            v, ok = extraer_valor({"ruta": errc.get("ruta") or ["error.message", "message"]}, ev)
            e = ev.get("error")
            errs.append(str(v) if ok and not isinstance(v, (dict, list)) else
                        str(e.get("message", e)) if isinstance(e, dict) else str(e or t))
    toma = (txt or {}).get("toma") if isinstance(txt, dict) else None
    result["result"] = ("\n".join(texts) if toma == "todos" else (texts[-1] if texts else ""))[:MAX_RESULT_CHARS]
    if isinstance(tur, dict) and "fijo" in tur:
        result["num_turns"] = tur["fijo"]
    else:
        result["num_turns"] = turns or None
    if isinstance(cos, dict) and "fijo" in cos:
        result["cost_usd"] = cos["fijo"]
    elif cost is not None:
        result["cost_usd"] = cost
    result["session_id"] = sid
    if rc == 0 and texts and not errs:
        result["status"] = "ok"
    else:
        result["error"] = (errs[-1] if errs else (f"{motor_id} salio con codigo {rc}" if rc
                           else f"{motor_id} no devolvió ningún mensaje"))[:300]


def _parse_cli_output(motor_id, eng, stdout, rc, result):
    sal = eng.get("salida") or {}
    fmt = sal.get("formato", "texto")
    if fmt == "json":
        try:
            data = json.loads(stdout)
        except ValueError:
            data = None
        if not isinstance(data, dict):
            result["result"] = stdout[:MAX_RESULT_CHARS]
            result["status"] = "ok" if rc == 0 else "error"
            if rc != 0:
                result["error"] = f"{motor_id} salio con codigo {rc} y salida no-JSON"
            return
        txt, _ok = extraer_valor(sal.get("texto") or "result", data)
        result["result"] = str(txt or "")[:MAX_RESULT_CHARS]
        cost, ok = extraer_valor(sal.get("costo"), data, numero=True)
        if ok:
            result["cost_usd"] = cost
        turns, ok = extraer_valor(sal.get("turnos"), data, numero=True)
        if ok:
            result["num_turns"] = turns
        sid, ok = extraer_valor(sal.get("sesion"), data)
        if ok:
            result["session_id"] = sid
        if isinstance(data.get("usage"), dict) or isinstance(data.get("modelUsage"), dict):
            uso = _uso_from_result_event(data)
            if uso:
                result["uso"] = uso
        # error_si: una ruta que vale true ("is_error") o {"ruta": "status",
        # "igual": "ERROR"} / {"ruta": ..., "distinto_de": "OK"}.
        flag = sal.get("error_si")
        if isinstance(flag, dict):
            v = _get_path(data, flag.get("ruta"))
            is_err = (("igual" in flag and str(v) == str(flag["igual"]))
                      or ("distinto_de" in flag and str(v) != str(flag["distinto_de"])))
            flag_txt = f"{flag.get('ruta')}={v}"
        else:
            is_err = bool(flag and _get_path(data, flag))
            flag_txt = f"{flag}=true"
        result["status"] = "error" if is_err or rc != 0 else "ok"
        msg, ok = extraer_valor((sal.get("error") or {}).get("ruta") if isinstance(sal.get("error"), dict)
                                else sal.get("error"), data)
        msg = str(msg)[:240] if ok and msg and not isinstance(msg, (dict, list)) else ""
        if is_err:
            result["error"] = f"{motor_id}: {msg}" if msg else f"{motor_id} reporto {flag_txt}"
        elif rc != 0:
            result["error"] = f"{motor_id} salio con codigo {rc}" + (f": {msg}" if msg else "")
        return
    if fmt == "jsonl":
        _parse_jsonl(motor_id, sal, stdout, rc, result)
        return
    result["result"] = stdout.replace("\r\n", "\n").strip()[:MAX_RESULT_CHARS]
    for k, field in (("costo", "cost_usd"), ("turnos", "num_turns")):
        v, ok = extraer_valor(sal.get(k), None)
        if ok:
            result[field] = v
    result["status"] = "ok" if rc == 0 and stdout.strip() else "error"
    if result["status"] != "ok":
        result["error"] = f"{motor_id} salio con codigo {rc}" if rc else f"{motor_id} no devolvió nada"


def _swap_args(cmd, old, new):
    """cmd con la secuencia old cambiada por new (None si old no esta)."""
    old, new = list(old or []), list(new or [])
    if not old:
        return None
    for i in range(len(cmd) - len(old) + 1):
        if cmd[i:i + len(old)] == old:
            return cmd[:i] + new + cmd[i + len(old):]
    return None


def _run_cli_engine(task, motor_id, eng, result, prompt, abilities=True, rol="tarea"):
    cmd = _build_cli_cmd(task, motor_id, eng, prompt, abilities=abilities)
    if cmd is None:
        result["error"] = (f"motor {motor_id} no disponible: no encuentro "
                           f"'{eng.get('binario')}' en el PATH de este usuario")
        return
    log(f"runner [{task['id']}]: corriendo {motor_id} en {task['cwd']} (timeout {task['timeout_min']} min)")
    vivo = eng.get("vivo") if isinstance(eng.get("vivo"), dict) and _cap(eng, "streaming") else {}
    live_cmd = (_swap_args(cmd, vivo.get("reemplaza"), vivo.get("argumentos"))
                if vivo.get("formato") == "stream-json" else None)
    if live_cmd:
        if _run_cli_stream(task, motor_id, eng, result, prompt, live_cmd, rol):
            return
        # stream-json no anduvo (no salio ni un evento): como siempre, con json.
        log(f"runner [{task['id']}]: {motor_id} no dio salida en vivo (stream-json); "
            "lo corro como antes (--output-format json), sin vivo")
        for k in ("status", "error", "result", "exit_code", "stderr"):
            result[k] = _base_result(task, motor_id)[k]
        live_set(rol, modo_vivo="sin vivo",
                 nota="el motor no dio salida en vivo; se corrió sin vivo")
    else:
        live_set(rol, modo_vivo="sin vivo")
    _run_cli_plain(task, motor_id, eng, result, prompt, cmd, rol)


def _live_event(ev, rol, st):
    """Un evento de stream-json de Claude Code -> vivo."""
    t = ev.get("type")
    if t == "stream_event":
        e = ev.get("event") or {}
        et = e.get("type")
        key = ev.get("api_message_id") or ((e.get("message") or {}).get("id"))
        if et == "message_start":
            m = e.get("message") or {}
            st["model_of"][key] = m.get("model")
            if isinstance(m.get("usage"), dict):
                st["uso"] = True
                live_msg(rol, key, m.get("model"), _usage_norm(m["usage"]))
        elif et == "message_delta" and isinstance(e.get("usage"), dict):
            st["uso"] = True
            live_msg(rol, key, st["model_of"].get(key), _usage_norm(e["usage"]))
    elif t == "assistant":
        m = ev.get("message") or {}
        if isinstance(m.get("usage"), dict):
            st["uso"] = True
            live_msg(rol, m.get("id"), m.get("model"), _usage_norm(m["usage"]))
        for b in m.get("content") or []:
            if isinstance(b, dict) and b.get("type") == "text" and b.get("text"):
                st["last_text"] = b["text"]
    elif t == "system" and ev.get("subtype") == "init":
        if ev.get("model"):
            live_set(rol, modelo_real=ev.get("model"))
        if rol == "tarea" and ev.get("session_id"):
            ck_en_vuelo(str(ev["session_id"]))  # checkpoint: la sesion, antes de que termine
    elif t == "result":
        st["final"] = ev


def _run_cli_stream(task, motor_id, eng, result, prompt, cmd, rol):
    """Corre el motor con salida en vivo (stream-json): un hilo lector va
    leyendo cada linea segun llega y suma el uso de cada mensaje. Devuelve
    False si no llego ni un evento (el motor no entiende stream-json): el
    que llama lo repite como siempre."""
    import tempfile
    stdin_mode = eng.get("prompt_por") == "stdin"
    timeout_s = task["timeout_min"] * 60
    st = {"final": None, "events": 0, "uso": False, "model_of": {}, "last_text": "",
          "raw": deque(maxlen=60)}
    with tempfile.TemporaryFile() as err:
        try:
            proc = subprocess.Popen(
                cmd, cwd=task["cwd"], stdout=subprocess.PIPE, stderr=err,
                stdin=subprocess.PIPE if stdin_mode else subprocess.DEVNULL,
                env=_engine_env(eng, task, rol), **_oculto())
        except FileNotFoundError:
            result["error"] = f"{motor_id} no esta en el PATH de este usuario"
            return True
        except OSError as e:
            result["error"] = f"no se pudo lanzar {motor_id} oculto ({OCULTO_TXT}): {e}"
            log(f"runner [{task['id']}]: {result['error']}; no se reintenta con ventana visible")
            return True
        _RUN["proc"] = proc
        _act_touch()  # el reloj de inactividad empieza al lanzar
        result["lanzamiento"] = _lanzamiento(proc)
        log(f"runner [{task['id']}]: {motor_id} lanzado oculto ({OCULTO_TXT}), pid {proc.pid}")
        _track_launch(proc, f"runner: tarea {task['id']}, motor {MOTOR_CORTO.get(motor_id, motor_id)}")

        def _reader():
            try:
                for raw in proc.stdout:
                    line = raw.decode("utf-8", "replace").strip()
                    if not line:
                        continue
                    _act_touch()  # cada evento stream-json es progreso
                    # Los trozos de texto (cientos) no traen uso: se saltan sin parsear.
                    if '"content_block_delta"' in line[:160]:
                        st["events"] += 1
                        continue
                    try:
                        ev = json.loads(line)
                    except ValueError:
                        st["raw"].append(line)
                        continue
                    if not isinstance(ev, dict):
                        continue
                    st["events"] += 1
                    try:
                        _live_event(ev, rol, st)
                    except Exception as e:  # el vivo nunca tumba la tarea
                        st["raw"].append(f"(vivo: {type(e).__name__}: {e})")
            except (OSError, ValueError):
                pass

        th = threading.Thread(target=_reader, daemon=True)
        th.start()
        rc = None
        sin_progreso = False
        try:
            if stdin_mode:
                try:
                    proc.stdin.write(prompt.encode("utf-8", "replace"))
                    proc.stdin.close()
                except OSError:
                    pass
            # Dos limites: el total de la tarea (timeout_min) y la inactividad
            # (no_progress_s sin un solo evento). Un motor que produce eventos
            # y tarda no se corta: solo el que se queda callado.
            deadline, limit = time.time() + timeout_s, no_progress_s()
            while True:
                try:
                    rc = proc.wait(timeout=1)
                    break
                except subprocess.TimeoutExpired:
                    pass
                idle = time.time() - _ACT["t"]
                if idle >= limit:
                    _kill_tree(proc)
                    sin_progreso = True
                    result["status"] = "error"
                    result["error"] = NO_PROGRESS_TXT
                    result["error_tipo"] = "definitivo"  # no se reintenta en bucle
                    log(f"runner [{task['id']}]: {NO_PROGRESS_TXT}: {motor_id} lleva {idle:.0f} s sin "
                        f"un evento (límite {limit} s); se mató el árbol de procesos del pid {proc.pid}")
                    break
                if time.time() >= deadline:
                    _kill_tree(proc)
                    result["status"] = "timeout"
                    result["error"] = f"timeout de {task['timeout_min']} min (se mató el proceso)"
                    break
        finally:
            _RUN["proc"] = None
        th.join(15)
        err.seek(0)
        stderr = err.read().decode("utf-8", "replace")
    result["exit_code"] = rc
    result["stderr"] = _ANSI_RE.sub("", stderr)[-MAX_STDERR_CHARS:]
    tail = st["last_text"] or "\n".join(st["raw"])
    if not st["uso"]:
        live_set(rol, modo_vivo="sin vivo",
                 nota="el motor no reportó uso mientras corría (sin vivo)")
    if _RUN.get("stop"):
        result["status"] = "error"
        result["error"] = "parado por el usuario (se mató el proceso)"
        result["result"] = tail[-MAX_RESULT_CHARS:]
        return True
    if result["status"] == "timeout" or sin_progreso:
        # Sin progreso no se repite con json: se colgaria igual otros 5 min.
        result["result"] = tail[-MAX_RESULT_CHARS:]
        return True
    final = st["final"]
    if final is None:
        if st["events"] == 0:
            return False
        result["result"] = tail[-MAX_RESULT_CHARS:]
        result["error"] = f"{motor_id} salio con codigo {rc} sin el mensaje final"
        return True
    # El mensaje final trae los mismos campos que --output-format json.
    _parse_cli_output(motor_id, eng, json.dumps(final), rc, result)
    if result.get("uso"):
        result["uso"]["fuente"] = "stream-json"
    live_final(rol, result.get("cost_usd"), result.get("uso"))
    return True


def _run_cli_plain(task, motor_id, eng, result, prompt, cmd, rol="tarea"):
    import tempfile
    stdin_mode = eng.get("prompt_por") == "stdin"
    timeout_s = task["timeout_min"] * 60
    with tempfile.TemporaryFile() as out, tempfile.TemporaryFile() as err:
        try:
            proc = subprocess.Popen(
                cmd, cwd=task["cwd"], stdout=out, stderr=err,
                stdin=subprocess.PIPE if stdin_mode else subprocess.DEVNULL,
                env=_engine_env(eng, task, rol), **_oculto())
        except FileNotFoundError:
            result["error"] = f"{motor_id} no esta en el PATH de este usuario"
            return
        except OSError as e:
            result["error"] = f"no se pudo lanzar {motor_id} oculto ({OCULTO_TXT}): {e}"
            log(f"runner [{task['id']}]: {result['error']}; no se reintenta con ventana visible")
            return
        _RUN["proc"] = proc
        result["lanzamiento"] = _lanzamiento(proc)
        log(f"runner [{task['id']}]: {motor_id} lanzado oculto ({OCULTO_TXT}), pid {proc.pid}")
        _track_launch(proc, f"runner: tarea {task['id']}, motor {MOTOR_CORTO.get(motor_id, motor_id)}")
        rc = None
        try:
            if stdin_mode:
                try:
                    proc.stdin.write(prompt.encode("utf-8", "replace"))
                    proc.stdin.close()
                except OSError:
                    pass
            try:
                rc = proc.wait(timeout=timeout_s)
            except subprocess.TimeoutExpired:
                _kill_tree(proc)
                result["status"] = "timeout"
                result["error"] = f"timeout de {task['timeout_min']} min (se mató el proceso)"
        finally:
            _RUN["proc"] = None
        out.seek(0)
        err.seek(0)
        stdout = out.read().decode("utf-8", "replace")
        stderr = err.read().decode("utf-8", "replace")
    result["exit_code"] = rc
    result["stderr"] = _ANSI_RE.sub("", stderr)[-MAX_STDERR_CHARS:]
    if _RUN.get("stop"):
        result["status"] = "error"
        result["error"] = "parado por el usuario (se mató el proceso)"
        result["result"] = stdout[-MAX_RESULT_CHARS:]
        return
    if result["status"] == "timeout":
        result["result"] = stdout[-MAX_RESULT_CHARS:]
        return
    _parse_cli_output(motor_id, eng, stdout, rc, result)
    if result.get("uso"):
        result["uso"]["fuente"] = "json (al terminar)"
    live_final(rol, result.get("cost_usd"), result.get("uso"))


def _local_model(eng, task):
    """Modelo de la tarea o el por_defecto del descriptor. '@ajuste:<clave>'
    lee esa clave de settings.json ('@ollama_por_defecto' es la forma vieja
    de '@ajuste:ollama_model')."""
    m = (task.get("modelo_local") if eng.get("servidor") else None) or task.get("modelo") or \
        (eng.get("modelo") or {}).get("por_defecto") or ""
    if m == "@ollama_por_defecto":
        m = default_ollama_model() or OLLAMA_MODEL
    elif isinstance(m, str) and m.startswith("@ajuste:"):
        key, _sep, resp = m[len("@ajuste:"):].partition("|")
        m = str(load_settings().get(key) or resp or "")
    return m


def _run_http_engine(task, motor_id, eng, result, prompt, for_review=False):
    """Motor HTTP local (llama-server, Ollama): un POST con stream:false. La
    sesion es un historial guardado en sesiones/<session_id>.json."""
    name = eng.get("nombre") or motor_id
    model = _local_model(eng, task)
    if eng.get("servidor") and not for_review:
        # Modo router: arranca el router si el puerto no responde, espera a
        # GET /models y carga el modelo de la tarea; solo entonces se ejecuta.
        ok, why = ensure_llama_server(eng, model)
        if ok and why:
            result.setdefault("avisos", []).append(why)
        # El resultado dice que modelo local se uso y como quedo listo.
        result["modelo_local"] = model or None
        result["modelo_local_carga"] = (why or f"{model} ya estaba cargado (GET /models: loaded): no se recargó") \
            if ok else f"no se pudo cargar: {why}"
    else:
        ok, why = engine_status_rt(eng, autostart=not for_review)
    if not ok:
        result["error"] = f"motor {motor_id} no disponible: {why}"
        return
    sid = None if for_review else task.get("session_id")
    messages = _trim_messages((_session_load(sid) if sid else [])
                              + [{"role": "user", "content": prompt}])
    body = _fill(eng.get("cuerpo") or {}, {"mensajes": messages, "modelo": model, "prompt": prompt})
    if for_review:
        body = _deep_merge(body, eng.get("cuerpo_revision") or {})
        if eng.get("esquema_rubrica_en"):
            # El servidor fuerza la salida al esquema de la rubrica (llama.cpp / Ollama).
            # Igual se valida al llegar: el esquema es la puerta, no la confianza.
            cur, ruta = body, str(eng["esquema_rubrica_en"]).split(".")
            for k in ruta[:-1]:
                cur = cur.setdefault(k, {}) if isinstance(cur.get(k, {}), dict) else cur
            cur[ruta[-1]] = RUBRICA_ESQUEMA
    if (eng.get("modelo") or {}).get("campo"):
        body[eng["modelo"]["campo"]] = model
    result["modelo"] = model or None
    rol = "revision" if for_review else "tarea"
    if not for_review:
        log(f"runner [{task['id']}]: corriendo {motor_id} ({name}) local, $0")
    sal = eng.get("salida") or {}
    vivo = eng.get("vivo") if isinstance(eng.get("vivo"), dict) and _cap(eng, "streaming") else {}
    timeout = task["timeout_min"] * 60
    data, text, tin, tout, fuente = None, None, None, None, None
    try:
        if vivo.get("stream") and not for_review:
            # En vivo: cada trozo que llega es un token de salida (el
            # servidor manda uno por trozo); al final, el uso que el
            # servidor reporta reemplaza la cuenta.
            sbody = _deep_merge(body, vivo.get("cuerpo") or {})
            try:
                text, tin, tout = _http_local_stream(
                    eng["url"], sbody, timeout, vivo,
                    lambda k: live_tokens(rol, model, 0, k, modo="en vivo (trozos)"),
                    idle=no_progress_s())
                fuente = "streaming"
            except _NoStream as e:
                log(f"runner [{task['id']}]: {name} no contestó en streaming ({e}); lo repito sin streaming")
                live_set(rol, nota="el motor no contestó en streaming; tokens al cerrar")
        if fuente is None:
            data = _http_local("POST", eng["url"], body, timeout=timeout, track=True)
            text = _get_path(data, sal.get("texto"))
            tin, tout = _first_num(data, sal.get("uso_in")), _first_num(data, sal.get("uso_out"))
            fuente = "al cerrar"
    except LocalCallError as e:
        if str(e) == NO_PROGRESS_TXT and not _RUN.get("stop"):
            result["error"] = NO_PROGRESS_TXT
            result["error_tipo"] = "definitivo"  # no se reintenta en bucle
            log(f"runner [{task['id']}]: {NO_PROGRESS_TXT}: {name} no mandó nada en "
                f"{no_progress_s()} s; se cortó la conexión")
            return
        result["error"] = (str(e) if "parado por el usuario" in str(e) or _RUN.get("stop")
                           else f"{name}: {e}")
        if _RUN.get("stop") and "parado" not in result["error"]:
            result["error"] = "parado por el usuario (se cortó la conexión con el motor)"
        return
    if tin is not None or tout is not None:
        result["uso"] = {"tokens_in": tin or 0, "tokens_out": tout or 0, "modelo_real": model or None,
                         "por_modelo": {model or motor_id: {"tokens_in": tin or 0, "tokens_out": tout or 0,
                                                            "cost_usd": 0.0}},
                         "fuente": fuente}
        live_tokens(rol, model, tin, tout, modo="en vivo" if fuente == "streaming" else "al cerrar")
    else:
        live_set(rol, modo_vivo="sin vivo", nota=f"{name} no reportó tokens")
    cost, cost_ok = extraer_valor(sal.get("costo"), data, numero=True)
    live_final(rol, float(cost) if cost_ok else None, result.get("uso"))
    if not isinstance(text, str) or not text.strip():
        result["error"] = f"{name} respondió sin texto"
        result["result"] = json.dumps(data, ensure_ascii=False)[:2000] if data is not None else ""
        return
    result.update(status="ok", exit_code=0, result=text[:MAX_RESULT_CHARS],
                  cost_usd=float(cost) if cost_ok else None)
    turns, turns_ok = extraer_valor(sal.get("turnos"), data, numero=True)
    result["num_turns"] = int(turns) if turns_ok else None
    if not for_review:
        sid = sid or ("s-" + secrets.token_hex(8))
        _session_save(sid, messages + [{"role": "assistant", "content": text}])
        result["session_id"] = sid
        result["num_turns"] = sum(1 for m in messages if m["role"] == "user")


def _http_inet(method, url, body, headers, timeout, key=""):
    req = urllib.request.Request(
        url, method=method, headers=headers,
        data=json.dumps(body, ensure_ascii=False).encode("utf-8") if body is not None else None)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        detail = ""
        try:
            detail = e.read().decode("utf-8", "replace")[:200]
        except Exception:
            pass
        raise LocalCallError(_scrub(f"{_http_reason(e.code)} {detail}", key))
    except urllib.error.URLError as e:
        raise LocalCallError(_scrub(f"sin conexión ({getattr(e, 'reason', e)})", key))


def _run_async_engine(task, motor_id, eng, result, prompt):
    """Motor asincrono (Meshy, 3D): crea la tarea, sondea el estado
    (PENDING / IN_PROGRESS / SUCCEEDED / FAILED) y descarga el archivo."""
    name = eng.get("nombre") or motor_id
    crear, est, desc = eng.get("crear") or {}, eng.get("estado") or {}, eng.get("descargar") or {}
    como = eng.get("credencial_como") if isinstance(eng.get("credencial_como"), dict) else {}
    if eng.get("credencial_ref"):
        # La clave de credencial_ref (proveedor + etiqueta), nunca otra.
        key, base, why = resolver_credencial(eng["credencial_ref"])
        if not key:
            result["error"] = f"motor {motor_id} no disponible: {why}"
            return
        if base:  # la credencial apunta a otra base_url
            old = str((eng.get("_v2") or {}).get("base_url") or "")
            crear = dict(crear, url=base.rstrip("/") + crear["url"][len(old.rstrip("/")):]) if old else crear
            est = dict(est, url=base.rstrip("/") + est["url"][len(old.rstrip("/")):]) if old else est
    else:  # forma v1
        key = _named_api_key(eng.get("clave_api"))
        if not key:
            result["error"] = (f"motor {motor_id} no disponible: falta la clave en APIs "
                               f"(ponle de nombre '{eng.get('clave_api')}')")
            return
    hdr = {"Content-Type": "application/json", "User-Agent": "GrowiBridge"}
    hdr[str(como.get("cabecera") or "Authorization")] = str(
        como.get("formato") or "Bearer {clave}").replace("{clave}", key)
    try:
        data = _http_inet(crear.get("metodo", "POST"), crear["url"],
                          _fill(crear.get("cuerpo") or {}, {"prompt": task["prompt"],
                                                            "modelo": task.get("modelo") or ""}),
                          hdr, 60, key)
        remote = _get_path(data, crear.get("campo_id", "result"))
        if not remote:
            result["error"] = f"{name} no devolvió el id de la tarea"
            return
        log(f"runner [{task['id']}]: {name} tarea creada ({remote})")
        deadline = time.time() + task["timeout_min"] * 60
        while True:
            if _RUN.get("stop"):
                result["error"] = f"parado por el usuario (la tarea {remote} de {name} puede seguir en su web)"
                return
            if time.time() > deadline:
                result["status"] = "timeout"
                result["error"] = f"timeout de {task['timeout_min']} min esperando a {name}"
                return
            d = _http_inet(est.get("metodo", "GET"), _fill(est["url"], {"tarea_id": remote}),
                           None, hdr, 60, key)
            st = str(d.get(est.get("campo", "status")) or "")
            state["paso"] = f"{name}: {st.lower() or 'esperando'} {d.get('progress', '')}%".strip()
            if st == est.get("exito", "SUCCEEDED"):
                break
            if st in (est.get("fallo") or ["FAILED"]):
                msg = _get_path(d, "task_error.message") or st
                result["error"] = f"{name} dijo {st}: {msg}"
                return
            for _ in range(int(est.get("cada_s") or 10)):
                if _RUN.get("stop"):
                    break
                time.sleep(1)
        url = _get_path(d, desc.get("campo_url", "model_urls.glb"))
        if not url:
            result["error"] = f"{name} terminó pero no dio la URL del archivo"
            return
        folder = SHARE / str(desc.get("carpeta") or "outbox/meshy")
        folder.mkdir(parents=True, exist_ok=True)
        dest = folder / f"{task['id']}{desc.get('extension', '.glb')}"
        with urllib.request.urlopen(url, timeout=300) as r, open(dest, "wb") as f:
            shutil.copyfileobj(r, f)
        size = dest.stat().st_size if dest.is_file() else 0
        if size <= 0:
            result["error"] = f"la descarga de {name} quedó vacía"
            return
        result.update(status="ok", exit_code=0, num_turns=1, session_id=str(remote),
                      result=f"Modelo 3D descargado en {dest} ({size // 1024} KB). Tarea {name}: {remote}.")
        result["archivos"] = [str(dest)]
    except LocalCallError as e:
        result["error"] = f"{name}: {e}"


# ---- herramientas del runner (t-blender-herramienta). Una herramienta NO es
# un motor: no conversa, no sale en el selector de modelos ni en la cadena de
# fallback. Es un ejecutor que el runner llama cuando la tarea lo pide.
HERRAMIENTAS_DEF = {
    "blender": {
        "nombre": "Blender",
        "operaciones": {"turntable": "template_turntable.py", "qc": "template_qc_views.py"},
        "no_hace": ["no genera modelos 3D (eso es Tripo o Meshy)", "no decide el diseño: ejecuta lo que se le pide",
                    "no sustituye a Tripo"],
        "timeout_s": 900,
    },
}
_HERR = {}
_MODELO_3D_RE = re.compile(r"""["']?((?:[A-Za-z]:[\\/]|\.{0,2}[\\/])?[^"'\s<>|]+?\.(?:glb|gltf|obj|fbx|blend))["']?""",
                           re.I)


def _blender_buscar():
    """Ruta real de blender.exe en ESTE PC (en vivo): PATH, y si no, la
    instalacion mas nueva en Program Files\\Blender Foundation\\."""
    exe = shutil.which("blender")
    if exe:
        return exe
    cands = []
    for base in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)"),
                 str(HOME_DIR / "AppData" / "Local" / "Programs")):
        if base:
            cands += list(Path(base, "Blender Foundation").glob("Blender*/blender.exe"))
    def _ver(p):
        return [int(x) for x in re.findall(r"\d+", p.parent.name)] or [0]
    cands.sort(key=_ver)
    return str(cands[-1]) if cands else None


def _blender_plantilla(nombre):
    for d in (SKILLS_DIR / "blender", INBOX / "skills-semilla" / "blender", APP_DIR / "skills" / "blender"):
        if (d / nombre).is_file():
            return d / nombre
    return None


def herramienta_ficha(hid="blender", fresca=False):
    """Lo que puede y lo que no, medido ahora (la version la dice el propio
    blender --version). Sin Blender: «no disponible» con el motivo."""
    if not fresca and hid in _HERR and time.time() - _HERR[hid]["t"] < 600:
        return _HERR[hid]["ficha"]
    d = HERRAMIENTAS_DEF[hid]
    f = {"id": hid, "nombre": d["nombre"], "es_motor": False, "disponible": False, "ruta": None, "version": None,
         "operaciones": {}, "no_hace": d["no_hace"], "motivo": None}
    exe = _blender_buscar()
    if not exe:
        f["motivo"] = "no encuentro blender.exe (ni en el PATH ni en Program Files\\Blender Foundation)"
    else:
        f["ruta"] = exe
        try:
            r = subprocess.run([exe, "--version"], capture_output=True, text=True, timeout=60,
                               encoding="utf-8", errors="replace", **_oculto())
            f["version"] = next((x.strip() for x in r.stdout.splitlines() if x.strip().startswith("Blender")), None)
            f["disponible"] = r.returncode == 0 and bool(f["version"])
            if not f["disponible"]:
                f["motivo"] = f"blender --version salió con {r.returncode}"
        except (OSError, subprocess.TimeoutExpired) as e:
            f["motivo"] = f"blender --version falló ({type(e).__name__})"
    for op, plantilla in d["operaciones"].items():
        p = _blender_plantilla(plantilla)
        f["operaciones"][op] = {"plantilla": str(p) if p else None,
                                "falta": None if p else f"falta {plantilla} en {SKILLS_DIR / 'blender'}"}
    _HERR[hid] = {"t": time.time(), "ficha": f}
    log(f"herramientas: {d['nombre']}: " + (f"{f['version']} en {f['ruta']}" if f["disponible"]
                                            else f"no disponible ({f['motivo']})"))
    return f


def herramienta_de_tarea(task):
    """{'herramienta','operacion','modelo'} si la tarea pide una tornamesa o un
    QC de un modelo 3D (campo «herramienta» o la frase del encargo), si no None."""
    h = task.get("herramienta") if isinstance(task.get("herramienta"), dict) else None
    texto = str(task.get("prompt") or "")
    if h:
        op, modelo = h.get("operacion"), h.get("modelo")
    else:
        if re.search(r"\b(tornamesa|turntable)\b", texto, re.I):
            op = "turntable"
        elif re.search(r"\b(qc|vistas de control|control de calidad)\b", texto, re.I):
            op = "qc"
        else:
            return None
        m = _MODELO_3D_RE.search(texto)
        modelo = m.group(1) if m else None
    if op not in HERRAMIENTAS_DEF["blender"]["operaciones"]:
        return None
    return {"herramienta": "blender", "operacion": op, "modelo": modelo, "salida": (h or {}).get("salida"),
            "frames": (h or {}).get("frames")}


def herramienta_correr(task, pedido):
    """Corre Blender en segundo plano con la plantilla; deja las imagenes en la
    carpeta del proyecto (junto al modelo). Resultado como el de un motor, $0."""
    result = _base_result(task, "blender (herramienta)")
    t0 = time.time()
    f = herramienta_ficha()
    op = pedido["operacion"]
    modelo = Path(pedido["modelo"] or "")
    if pedido["modelo"] and not modelo.is_absolute():
        modelo = Path(task.get("cwd") or INBOX) / modelo
    plantilla = (f["operaciones"].get(op) or {}).get("plantilla")
    if not f["disponible"]:
        result["error"] = f"Blender no disponible: {f['motivo']}"
    elif not plantilla:
        result["error"] = f["operaciones"][op]["falta"]
    elif not pedido["modelo"] or not modelo.is_file():
        result["error"] = f"no encuentro el modelo 3D ({modelo if pedido['modelo'] else 'el encargo no nombra un .glb/.gltf/.obj/.fbx/.blend'})"
    else:
        salida = Path(pedido.get("salida") or modelo.with_name(f"{modelo.stem}_{op}"))
        salida.mkdir(parents=True, exist_ok=True)
        args = [f["ruta"], "--background", "--python", plantilla, "--", f"MODEL_PATH={modelo}", f"OUT_DIR={salida}"]
        if op == "turntable":
            args.append(f"FRAMES={int(pedido.get('frames') or 24)}")
        log(f"runner [{task['id']}]: herramienta Blender: {op} de {modelo.name} -> {salida}")
        try:
            r = subprocess.run(args, capture_output=True, text=True, encoding="utf-8", errors="replace",
                               timeout=HERRAMIENTAS_DEF["blender"]["timeout_s"], **_oculto())
            pngs = sorted(str(p) for p in salida.glob("*.png"))
            result.update(exit_code=r.returncode, stderr=(r.stderr or "")[-2000:], archivos=pngs)
            if r.returncode == 0 and pngs:
                result.update(status="ok", result=f"Blender ({f['version']}) hizo {op} de {modelo.name}: "
                                                  f"{len(pngs)} imagen(es) en {salida}:\n" +
                                                  "\n".join(Path(p).name for p in pngs))
            else:
                result["error"] = f"Blender salió con {r.returncode} y {len(pngs)} imagen(es): " + \
                                  (r.stdout or "")[-600:]
        except subprocess.TimeoutExpired:
            result["status"], result["error"] = "timeout", f"Blender pasó de {HERRAMIENTAS_DEF['blender']['timeout_s']} s"
    result.update(cost_usd=0.0, herramienta={"id": "blender", "operacion": op, "version": f.get("version")},
                  finished_at=_now_iso(), duration_s=round(time.time() - t0, 1))
    return result


# ---- verificar Groq y Gemini (t-verificar-groq-gemini): llamada REAL, medida
# Tres caminos: Groq directo, Groq por el proxy y Gemini directo sin proxy.
# Primero se mira si el servidor contesta desde aqui SIN clave (un 401/403 de
# «falta la clave» dice que la IP llega; un error de region o de red, que no).
# Con la clave activa de Ajustes -> Claves se hace la prueba corta de siempre
# («Escribe tres frutas, una por linea»): latencia, tokens y costo. Sin clave
# es FALTA, nunca «no funciona». El informe (VERIFICACION-NUBES.json/.md, en la
# carpeta de Bridge) es lo que mira el router: un camino solo entra si su
# llamada real salio bien.
NUBES_FILE = APP_DIR / "VERIFICACION-NUBES.json"
NUBES_PRUEBA = "Escribe tres frutas, una por línea."
NUBES_PRECIOS = {  # $ por millón de tokens (entrada, salida), publicados (no medidos aquí)
    "groq": {"modelo": "llama-3.1-8b-instant", "entrada": 0.05, "salida": 0.08,
             "fuente": "precios publicados por Groq (oct-2026)"},
    "gemini": {"modelo": None, "entrada": 0.0, "salida": 0.0,
               "fuente": "capa gratis de Gemini: $0 (si la clave tiene facturación, cobra el precio del modelo)"},
}
_NUBES_SONDEO = {"groq": "https://api.groq.com/openai/v1/models",
                 "gemini": "https://generativelanguage.googleapis.com/v1beta/models"}


def _nubes_lectura(code, body, err):
    """Qué dice el sondeo sin clave. Un 401, o un 403 que habla de la clave, es
    «llega y pide clave»; un 403 pelado («Forbidden») es otra cosa: el servidor
    rechaza esta IP antes de mirar la clave (bloqueo por región, probablemente)."""
    low = (body or "").lower()
    if code == 401 or (code == 403 and any(x in low for x in ("api key", "api_key", "unregistered", "caller"))):
        return "llega: pide clave (lo esperado sin clave)"
    if code == 403:
        return "403 Forbidden sin hablar de la clave: rechaza esta IP (¿bloqueo por región?)"
    return f"contesta {code}" if code else f"no contesta: {err}"


def _nubes_llamar(prov, via_proxy, clave, c):
    """La prueba corta, de verdad. dict con lo medido."""
    info = CRED_PROVIDERS[prov]
    modelo = NUBES_PRECIOS[prov]["modelo"]
    if prov == "gemini":  # el modelo Flash-Lite (o Flash) que la API diga que hay, sin adivinar
        try:
            req = urllib.request.Request(_cred_url(c, info["test"]), headers=_cred_headers(prov, clave))
            op = urllib.request.build_opener(urllib.request.ProxyHandler(
                {"http": proxy_url(), "https": proxy_url()} if via_proxy else {}))
            with op.open(req, timeout=20) as r:
                nombres = [m.get("name", "").split("/")[-1] for m in json.loads(r.read().decode("utf-8")).get("models", [])]
            modelo = next((n for n in nombres if "flash-lite" in n), None) or next((n for n in nombres if "flash" in n), None)
        except Exception as e:
            return {"responde": False, "error": f"no pude leer la lista de modelos: {_net_reason(e)}"}
        if not modelo:
            return {"responde": False, "error": "la API no lista ningún modelo Flash"}
    cuerpo = json.dumps({"model": modelo, "messages": [{"role": "user", "content": NUBES_PRUEBA}],
                         "max_tokens": 60, "temperature": 0}).encode("utf-8")
    req = urllib.request.Request(_cred_url(c, info["chat"]), data=cuerpo, method="POST",
                                 headers=dict(_cred_headers(prov, clave), **{"Content-Type": "application/json"}))
    op = urllib.request.build_opener(urllib.request.ProxyHandler(
        {"http": proxy_url(), "https": proxy_url()} if via_proxy else {}))
    t0 = time.time()
    try:
        with op.open(req, timeout=60) as r:
            d = json.loads(r.read().decode("utf-8"))
            ms = int((time.time() - t0) * 1000)
            hdr = {k: v for k, v in r.headers.items() if "ratelimit" in k.lower() or "quota" in k.lower()}
    except urllib.error.HTTPError as e:
        try:
            det = e.read(600).decode("utf-8", "replace")
        except Exception:
            det = ""
        return {"responde": False, "http": e.code, "error": f"HTTP {e.code}: {det[:300]}",
                "ms": int((time.time() - t0) * 1000), "modelo": modelo}
    except Exception as e:
        return {"responde": False, "error": _net_reason(e), "ms": int((time.time() - t0) * 1000), "modelo": modelo}
    u = d.get("usage") or {}
    tin, tout = int(u.get("prompt_tokens") or 0), int(u.get("completion_tokens") or 0)
    p = NUBES_PRECIOS[prov]
    costo = round((tin * p["entrada"] + tout * p["salida"]) / 1e6, 8)
    tipica = round((2000 * p["entrada"] + 500 * p["salida"]) / 1e6, 6)
    txt = ((d.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
    return {"responde": True, "ms": ms, "modelo": d.get("model") or modelo, "salida": txt.strip()[:200],
            "tokens_entrada": tin, "tokens_salida": tout, "costo_usd": costo,
            "costo_tarea_tipica_usd": tipica, "precio_fuente": p["fuente"], "limites": hdr}


def verificar_nubes():
    """Los tres caminos, medidos ahora. Escribe el informe y lo devuelve."""
    caminos = [("groq", False, "Groq directo"), ("groq", True, "Groq por el proxy"), ("gemini", False, "Gemini directo")]
    filas = []
    for prov, via, nombre in caminos:
        f = {"camino": nombre, "proveedor": prov, "via_proxy": via, "at": _now_iso()}
        if via and not proxy_url():
            f.update(sondeo=None, llamada=None, entra_router=False, falta="no hay proxy guardado (Estado → Proxy)")
            filas.append(f)
            continue
        code, body, ms, err = _probe(_NUBES_SONDEO[prov], via_proxy=via, timeout=12)
        f["sondeo"] = {"http": code, "ms": ms, "error": err or None,
                       "lectura": _nubes_lectura(code, body, err),
                       "cuerpo": (body or "")[:200]}
        c = cred_activa(prov)
        clave = cred_clave(c["cuenta"]) if c else None
        if not c or not clave:
            f.update(llamada=None, entra_router=False,
                     falta=f"sin clave de {CRED_PROVIDERS[prov]['label']} en Ajustes → Claves: la llamada real no "
                           "se hizo (FALTA previa; no se inventa ni se pide prestada)")
        else:
            f["llamada"] = _nubes_llamar(prov, via, clave, c)
            f["entra_router"] = bool(f["llamada"].get("responde"))
            if not f["entra_router"]:
                f["falta"] = f"la llamada real falló: {f['llamada'].get('error')}"
        filas.append(f)
        log(f"verificar nubes: {nombre}: sondeo {f['sondeo']['http'] if f.get('sondeo') else '-'} "
            + (f"; llamada {'OK' if f['llamada'].get('responde') else 'falló'} en {f['llamada'].get('ms')} ms"
               if f.get("llamada") else f"; {f.get('falta')}"))
    entran = [f["camino"] for f in filas if f["entra_router"]]
    inf = {"actualizado": _now_iso(), "prueba": NUBES_PRUEBA, "caminos": filas, "entran_al_router": entran,
           "conclusion": (("Entran al router: " + ", ".join(entran) + ". ") if entran else
                          "Ninguno entra al router todavía: ") +
                         "; ".join(f"{f['camino']}: {f.get('falta')}" for f in filas if not f["entra_router"])}
    NUBES_FILE.write_text(json.dumps(inf, ensure_ascii=False, indent=2), encoding="utf-8")
    md = ["# Verificación de Groq y Gemini", "", f"Medido el {inf['actualizado'][:16].replace('T', ' a las ')}. "
          f"Prueba: «{NUBES_PRUEBA}».", "",
          "| Camino | Contesta sin clave | Llamada real | Latencia | Tokens | Costo (esta / típica 2.000+500) | Límites |",
          "|---|---|---|---|---|---|---|"]
    for f in filas:
        s, ll = f.get("sondeo") or {}, f.get("llamada") or {}
        md.append(f"| {f['camino']} | {s.get('lectura', '—')} ({s.get('ms', '—')} ms) | "
                  + ("sí: " + ll.get("salida", "").replace("\n", " / ")[:60] if ll.get("responde") else
                     (f.get("falta") or "—"))
                  + f" | {ll.get('ms', '—')} ms | {ll.get('tokens_entrada', '—')}+{ll.get('tokens_salida', '—')} | "
                  + (f"${ll['costo_usd']:.6f} / ${ll['costo_tarea_tipica_usd']:.6f}" if ll.get("responde") else "—")
                  + f" | {', '.join(f'{k}: {v}' for k, v in (ll.get('limites') or {}).items()) or '—'} |")
    md += ["", f"**Conclusión:** {inf['conclusion']}", "",
           "Regla: un camino entra al router automático solo si su llamada real salió bien aquí."]
    NUBES_FILE.with_suffix(".md").write_text("\n".join(md) + "\n", encoding="utf-8")
    log(f"verificar nubes: {inf['conclusion'][:300]}")
    return inf


def nube_verificada(camino):
    """Para el router: True solo si el último informe dice que ese camino respondió de verdad."""
    try:
        inf = json.loads(NUBES_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return camino in (inf.get("entran_al_router") or [])


def verificar_nubes_ui():
    def _bg():
        inf = verificar_nubes()
        _ui_call(lambda: messagebox.showinfo("Verificar Groq y Gemini", inf["conclusion"][:900]
                                             + f"\n\nInforme: {NUBES_FILE.with_suffix('.md')}"))
    threading.Thread(target=_bg, daemon=True).start()
    toast("Verificando Groq y Gemini…")


# ---- herramienta «transcribe» (t-transcribe-whisper): audio/video -> texto
# con faster-whisper en local ($0, offline una vez bajado el modelo). La receta
# es la probada en la VM: ffmpeg decodifica a f32le 16 kHz mono y se parchea
# faster_whisper.audio.decode_audio (faster-whisper 1.2.1 choca con av>=19).
# Corre en un proceso aparte (el Python que tenga faster-whisper), avisa del
# progreso real (segundo de audio por el que va) y se puede cancelar: lo que
# quede se marca PARCIAL, nunca como completo. Nada de nube ni de Descript.
TRANSCRIBE_EXT = (".mp4", ".mov", ".mkv", ".webm", ".avi", ".mp3", ".wav", ".m4a", ".ogg", ".opus", ".flac",
                  ".aac", ".wma")
_TRS_EXT_RE = "(?:" + "|".join(e[1:] for e in TRANSCRIBE_EXT) + ")"
# primero una ruta absoluta (puede llevar espacios), si no un nombre suelto sin espacios
TRANSCRIBE_MEDIA_ABS_RE = re.compile(r"[A-Za-z]:[\\/][^\"'<>|\r\n]*?\." + _TRS_EXT_RE + r"\b", re.I)
TRANSCRIBE_MEDIA_RE = re.compile(r"[^\s\"'<>|]+\." + _TRS_EXT_RE + r"\b", re.I)
TRANSCRIBE_COSTE = "$0, local, offline"
TRANSCRIBE_WORKER = r'''# Lo escribe Growi Bridge (herramienta transcribe). No editar: se reescribe.
import json, subprocess, sys
import numpy as np
import faster_whisper.audio as fwa
from faster_whisper import WhisperModel

archivo, salida, idioma, modelo, ffmpeg = sys.argv[1:6]


def decodificar(ruta, sampling_rate=16000, **_k):
    # receta de la VM: ffmpeg -> f32le mono (evita PyAV; faster-whisper 1.2.1 choca con av>=19)
    out = subprocess.run([ffmpeg, "-nostdin", "-v", "error", "-i", ruta, "-f", "f32le", "-ac", "1",
                          "-ar", str(sampling_rate), "-"], capture_output=True, check=True).stdout
    return np.frombuffer(out, np.float32)


fwa.decode_audio = decodificar
audio = decodificar(archivo)
dur = len(audio) / 16000.0
print(json.dumps({"evento": "audio", "duracion": dur}), flush=True)
m = WhisperModel(modelo, device="cpu", compute_type="int8", local_files_only=True)
segs, info = m.transcribe(audio, language=None if idioma == "auto" else idioma, vad_filter=True)
print(json.dumps({"evento": "idioma", "idioma": info.language,
                  "probabilidad": round(float(info.language_probability or 0), 3)}), flush=True)


def hms(t):
    t = int(t)
    return f"{t // 3600:02d}:{t % 3600 // 60:02d}:{t % 60:02d}"


with open(salida, "w", encoding="utf-8") as f:
    for s in segs:
        f.write(f"[{hms(s.start)} - {hms(s.end)}] {s.text.strip()}\n")
        f.flush()
        print(json.dumps({"evento": "progreso", "hasta": float(s.end), "duracion": dur}), flush=True)
print(json.dumps({"evento": "fin"}), flush=True)
'''
_TRS = {"ficha": None, "t": 0.0}


def _transcribe_python():
    """El Python con faster-whisper: settings «transcribe_python» o el de la app."""
    p = str(load_settings().get("transcribe_python") or "").strip()
    return p if p and Path(p).is_file() else sys.executable.replace("pythonw.exe", "python.exe")


def _transcribe_modelo_local(nombre="small"):
    """(ruta del model.bin, MB) del modelo CTranslate2 en la caché de Hugging Face, o (None, None)."""
    hub = Path(os.environ.get("HF_HOME") or HOME_DIR / ".cache" / "huggingface") / "hub"
    for snap in sorted((hub / f"models--Systran--faster-whisper-{nombre}" / "snapshots").glob("*")):
        mb = snap / "model.bin"
        try:
            real = mb.resolve()
            return str(real), round(real.stat().st_size / 1048576, 1)
        except OSError:
            continue
    return None, None


def transcribe_ficha(fresca=False):
    """Lo que hay de verdad en este PC (medido ahora): faster-whisper, ffmpeg y el modelo."""
    if not fresca and _TRS["ficha"] and time.time() - _TRS["t"] < 600:
        return _TRS["ficha"]
    nombre = str(load_settings().get("transcribe_modelo") or "small")
    py = _transcribe_python()
    f = {"id": "transcribe", "nombre": "Transcribir (faster-whisper)", "es_motor": False, "coste": TRANSCRIBE_COSTE,
         "python": py, "faster_whisper": None, "ffmpeg": shutil.which("ffmpeg"), "modelo": nombre,
         "modelo_ruta": None, "modelo_mb": None, "idioma": "es", "disponible": False, "motivo": None,
         "no_hace": ["no usa la nube ni Descript", "no traduce", "no separa quién habla"]}
    f["modelo_ruta"], f["modelo_mb"] = _transcribe_modelo_local(nombre)
    try:
        r = subprocess.run([py, "-c", "import faster_whisper;print(faster_whisper.__version__)"], capture_output=True,
                           text=True, timeout=60, encoding="utf-8", errors="replace", **_oculto())
        f["faster_whisper"] = r.stdout.strip() if r.returncode == 0 else None
    except (OSError, subprocess.TimeoutExpired):
        f["faster_whisper"] = None
    faltas = []
    if not f["faster_whisper"]:
        faltas.append(f"falta instalar faster-whisper en {py} (pip install faster-whisper==1.2.1; o pon en "
                      "settings.json «transcribe_python» el Python que ya lo tenga)")
    if not f["ffmpeg"]:
        faltas.append("falta ffmpeg en el PATH")
    if not f["modelo_ruta"]:
        faltas.append(f"falta el modelo Systran/faster-whisper-{nombre} en la caché de Hugging Face (se baja una vez)")
    f["disponible"] = not faltas
    f["motivo"] = "; ".join(faltas) or None
    _TRS.update(ficha=f, t=time.time())
    log("herramientas: transcribir: " + (f"lista ({TRANSCRIBE_COSTE}; modelo {nombre} {f['modelo_mb']} MB)"
                                          if f["disponible"] else f"no disponible: {f['motivo']}"))
    return f


def transcribe_de_tarea(task):
    """{'archivo','idioma'} si la tarea pide transcribir un audio o video."""
    h = task.get("herramienta") if isinstance(task.get("herramienta"), dict) else None
    if h and h.get("id") not in (None, "transcribe"):
        return None
    texto = str(task.get("prompt") or "")
    if not h and not re.search(r"\btranscrib\w*|\btranscripci[oó]n\b", texto, re.I):
        return None
    archivo = (h or {}).get("archivo")
    if not archivo:
        m = TRANSCRIBE_MEDIA_ABS_RE.search(texto) or TRANSCRIBE_MEDIA_RE.search(texto)
        archivo = m.group(0).strip() if m else None
    if not archivo and not h:
        return None
    return {"archivo": archivo, "idioma": str((h or {}).get("idioma") or "es")}


def transcribe_correr(task, pedido, ficha=None):
    """Corre la transcripción con progreso real; deja <archivo>.transcripcion.txt
    (o .PARCIAL.txt si se cancela o se corta). Resultado como el de un motor, $0."""
    result = _base_result(task, "transcribe (herramienta)")
    t0 = time.time()
    f = ficha or transcribe_ficha()
    archivo = Path(pedido.get("archivo") or "")
    if pedido.get("archivo") and not archivo.is_absolute():
        archivo = Path(task.get("cwd") or INBOX) / archivo
    result.update(cost_usd=0.0, herramienta={"id": "transcribe", "coste": TRANSCRIBE_COSTE, "modelo": f["modelo"]})
    if not pedido.get("archivo") or not archivo.is_file():
        result["error"] = f"no encuentro el audio o video ({archivo if pedido.get('archivo') else 'el encargo no nombra un archivo'})"
        result["error_tipo"] = "definitivo"
        return result
    if not f["disponible"]:
        result["error"] = f"no se puede transcribir aquí: {f['motivo']}"
        result["error_tipo"] = "definitivo"
        return result
    worker = APP_DIR / "herramientas" / "transcribe_worker.py"
    worker.parent.mkdir(parents=True, exist_ok=True)
    if not worker.exists() or worker.read_text(encoding="utf-8") != TRANSCRIBE_WORKER:
        worker.write_text(TRANSCRIBE_WORKER, encoding="utf-8")
    final = archivo.with_name(archivo.stem + ".transcripcion.txt")
    tmp = archivo.with_name(archivo.stem + ".transcripcion.tmp")
    cmd = [f["python"], str(worker), str(archivo), str(tmp), pedido["idioma"], f["modelo"], f["ffmpeg"]]
    log(f"runner [{task['id']}]: transcribir {archivo.name} ({pedido['idioma']}, modelo {f['modelo']}, {TRANSCRIBE_COSTE})")
    info = {"duracion": None, "idioma": None, "probabilidad": None, "hasta": 0.0}
    cancelada, err_lineas = False, []
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8",
                         errors="replace", **_oculto())
    _RUN["proc"] = p
    hilo_err = threading.Thread(target=lambda: err_lineas.extend(p.stderr.readlines()), daemon=True)
    hilo_err.start()
    ultimo_log = 0.0
    for linea in p.stdout:
        if _RUN.get("stop"):
            cancelada = True
            break
        try:
            ev = json.loads(linea)
        except ValueError:
            continue
        if ev.get("evento") == "audio":
            info["duracion"] = ev.get("duracion")
        elif ev.get("evento") == "idioma":
            info.update(idioma=ev.get("idioma"), probabilidad=ev.get("probabilidad"))
            log(f"runner [{task['id']}]: idioma detectado: {info['idioma']} ({info['probabilidad']})")
        elif ev.get("evento") == "progreso":
            info["hasta"] = ev.get("hasta") or info["hasta"]
            pct = (100 * info["hasta"] / info["duracion"]) if info["duracion"] else None
            state["paso"] = (f"Transcribiendo {archivo.name}: {_gw_hace(info['hasta'])} de "
                             f"{_gw_hace(info['duracion'] or 0)}" + (f" ({pct:.0f} %)" if pct is not None else ""))
            if time.time() - ultimo_log > 10:
                ultimo_log = time.time()
                log(f"runner [{task['id']}]: {state['paso']}")
    if cancelada or _RUN.get("stop"):
        cancelada = True
        _kill_tree(p)
    p.wait()
    hilo_err.join(timeout=2)
    cab = (f"# Transcripción de {archivo.name}\n# idioma: {info['idioma'] or 'sin dato'}"
           + (f" (detectado, {info['probabilidad']})" if pedido["idioma"] == "auto" else
              f" (pedido: {pedido['idioma']}; el modelo detectó {info['idioma']} con {info['probabilidad']})")
           + f" · modelo {f['modelo']} · {TRANSCRIBE_COSTE}\n")
    hecho = tmp.read_text(encoding="utf-8") if tmp.exists() else ""
    ok = (not cancelada) and p.returncode == 0
    if ok:
        final.write_text(cab + "\n" + hecho, encoding="utf-8")
        destino = final
    elif hecho.strip():  # lo que hay, marcado PARCIAL (nunca como completo)
        destino = archivo.with_name(archivo.stem + ".transcripcion.PARCIAL.txt")
        destino.write_text(cab + f"# PARCIAL: {'cancelada' if cancelada else 'se cortó'} a los "
                                 f"{_gw_hace(info['hasta'])} de {_gw_hace(info['duracion'] or 0)}. NO está completa.\n\n"
                           + hecho, encoding="utf-8")
    else:
        destino = None
    try:
        tmp.unlink()
    except OSError:
        pass
    result.update(finished_at=_now_iso(), duration_s=round(time.time() - t0, 1), exit_code=p.returncode,
                  archivos=[str(destino)] if destino else [], idioma_detectado=info["idioma"],
                  transcripcion={"duracion_audio_s": info["duracion"], "hasta_s": info["hasta"],
                                 "idioma": info["idioma"], "probabilidad": info["probabilidad"],
                                 "parcial": not ok, "cancelada": cancelada, "archivo": str(destino) if destino else None})
    if ok:
        result.update(status="ok", result=f"Transcripción lista ({info['idioma']}, {_gw_hace(info['duracion'] or 0)} de "
                                          f"audio, {TRANSCRIBE_COSTE}) en {destino}")
    elif cancelada:
        result.update(status="error", error=f"transcripción cancelada a los {_gw_hace(info['hasta'])}"
                                            + (f"; lo hecho quedó en {destino} marcado PARCIAL" if destino else
                                               "; no quedó nada a medias"), error_tipo="definitivo")
    else:
        result.update(status="error", error="la transcripción falló: " + "".join(err_lineas)[-600:],
                      error_tipo="definitivo")
    log(f"runner [{task['id']}]: transcribir: {result.get('result') or result.get('error')}")
    return result


def transcribe_ui():
    """Paleta: elegir un audio o video y encolar la transcripción (español)."""
    ruta = filedialog.askopenfilename(title="Transcribir un audio o video",
                                      filetypes=[("Audio o video", " ".join("*" + e for e in TRANSCRIBE_EXT))])
    if not ruta:
        return None
    tid = "t-transcribir-" + datetime.now().strftime("%Y%m%d-%H%M%S")
    TASKS.mkdir(parents=True, exist_ok=True)
    (TASKS / f"{tid}.task.json").write_text(json.dumps({
        "id": tid, "prompt": f"Transcribe {ruta}", "revisar": False,
        "herramienta": {"id": "transcribe", "archivo": ruta, "idioma": "es"}}, ensure_ascii=False), encoding="utf-8")
    log(f"transcribir: encolada {tid} ({Path(ruta).name}); {TRANSCRIBE_COSTE}")
    toast("Transcripción en la cola ($0, local)")
    return tid


# ---------------------------------------------------------------- MCP Streamable HTTP (t-mcp-streamable-http)
# PROPUESTA (la investigacion 0.3.0 no traia diseño; ver DISENO-MCP.md, con
# fuentes): servidor y cliente MCP segun la especificacion vigente leida en
# vivo (revision 2026-07-28: un solo endpoint POST, sin sesiones ni GET; los
# metadatos van en _meta y se reflejan en cabeceras que se validan).
# Servidor: SOLO 127.0.0.1, con el token del plano de control en cada
# peticion y Origin validado (ninguno permitido por defecto). Expone pocas
# herramientas descritas con datos (MCP_HERRAMIENTAS); nunca secretos,
# credenciales, cambios de permisos/politicas ni control de escritorio. Lo
# sensible (encolar una tarea) pasa por el runner: guardrail, politicas y
# aprobacion como cualquier tarea; por MCP un R3 se deniega (canal no-app).
# Cliente: llama a servidores MCP externos elegidos (por defecto DeepWiki,
# publico y de solo lectura), con interruptor por herramienta.
MCP_VERSION = "2026-07-28"
MCP_VERSION_LEGADO = "2025-06-18"
MCP_SERVIDOR_INFO = {"name": "growi-bridge", "version": VERSION}
MCP_HERRAMIENTAS = {  # descritas con datos (adenda §14): qué hace, su esquema y su nivel
    "bridge_estado": {"title": "Estado de Growi Bridge", "nivel": "R0",
                      "description": "Si el gateway, el runner y la cola están vivos (sin secretos ni rutas de token).",
                      "inputSchema": {"type": "object", "additionalProperties": False}},
    "bridge_cola": {"title": "Cola de tareas", "nivel": "R0",
                    "description": "Cuántas tareas hay en cola, en curso, esperando aprobación o fallidas.",
                    "inputSchema": {"type": "object", "additionalProperties": False}},
    "bridge_memoria_buscar": {"title": "Buscar en la memoria", "nivel": "R0",
                              "description": "Busca por palabras en la memoria del usuario (líneas con su origen).",
                              "inputSchema": {"type": "object", "properties": {"q": {"type": "string"}},
                                              "required": ["q"], "additionalProperties": False}},
    "bridge_encolar_tarea": {"title": "Encolar una tarea", "nivel": "según el encargo",
                             "description": "Deja un encargo en la cola del runner. Lo sensible espera la aprobación del "
                                            "usuario en la app (como cualquier tarea); un R3 por MCP se deniega.",
                             "inputSchema": {"type": "object", "properties": {
                                 "prompt": {"type": "string"},
                                 "cwd": {"type": "string", "description": "carpeta de trabajo (una de las permitidas)"}},
                                 "required": ["prompt"], "additionalProperties": False}},
}
MCP_NUNCA = ("secretos ni tokens", "credenciales ni claves de API", "cambiar permisos, guardrail o políticas",
             "control de escritorio por clics o capturas de pantalla", "acciones sensibles sin aprobación")
MCP_CLIENTES_DEF = [{"id": "deepwiki", "url": "https://mcp.deepwiki.com/mcp",
                     "para": "documentación pública de repos de GitHub (solo lectura, sin cuenta)"}]
_MCP: dict = {"server": None, "puerto": None, "legado": {}}


def mcp_puerto():
    return int(load_settings().get("mcp_puerto") or (BRIDGE_PORT + 20))


def _mcp_resp(h, code, obj=None):
    body = b"" if obj is None else json.dumps(obj, ensure_ascii=False).encode("utf-8")
    h.send_response(code)
    if obj is not None:
        h.send_header("Content-Type", "application/json")
    h.send_header("Content-Length", str(len(body)))
    h.end_headers()
    if body:
        h.wfile.write(body)


def _mcp_err(id_, code, msg):
    d = {"jsonrpc": "2.0", "error": {"code": code, "message": msg}}
    if id_ is not None:
        d["id"] = id_
    return d


def _mcp_texto(obj):
    t = json.dumps(obj, ensure_ascii=False, indent=1) if not isinstance(obj, str) else obj
    return {"resultType": "complete", "content": [{"type": "text", "text": t}],
            **({"structuredContent": obj} if not isinstance(obj, str) else {}), "isError": False}


def mcp_ejecutar_herramienta(nombre, args):
    """Lo que hace cada herramienta del servidor (nunca devuelve secretos)."""
    if nombre == "bridge_estado":
        d = gateway_estado()
        g = d.get("gateway") or {}
        return _mcp_texto({"vivo": g.get("vivo"), "desde": g.get("inicio"), "runner": (d.get("runner") or {}).get("estado"),
                           "tarea_en_curso": (d.get("runner") or {}).get("tarea"),
                           "motores": [{"id": m["id"], "disponible": m["disponible"]} for m in d.get("motores") or []]})
    if nombre == "bridge_cola":
        return _mcp_texto(cola_resumen()["cuenta"])
    if nombre == "bridge_memoria_buscar":
        hits, _m = mem_buscar_ordenado(str(args.get("q") or ""))
        return _mcp_texto([{"texto": h["texto"], "origen": h["origen"]} for h in hits[:10]])
    if nombre == "bridge_encolar_tarea":
        prompt = str(args.get("prompt") or "").strip()
        if not prompt:
            return {"resultType": "complete", "content": [{"type": "text", "text": "falta el encargo (prompt)"}],
                    "isError": True}
        tid = "t-mcp-" + datetime.now().strftime("%Y%m%d-%H%M%S-") + secrets.token_hex(2)
        TASKS.mkdir(parents=True, exist_ok=True)
        # la carpeta la valida el runner como en cualquier tarea; sin carpeta, la primera permitida
        cwd = str(args.get("cwd") or "").strip() or load_folders()[0]
        (TASKS / f"{tid}.task.json").write_text(json.dumps({"id": tid, "prompt": prompt, "canal": "mcp", "cwd": cwd},
                                                           ensure_ascii=False), encoding="utf-8")
        log(f"mcp: tarea {tid} encolada por MCP (canal mcp): pasa por el guardrail y las políticas como cualquiera")
        return _mcp_texto({"tarea": tid, "nota": "En cola. Si es sensible, espera la aprobación del usuario en la app; "
                                                 "un R3 pedido por MCP se deniega."})
    return None


class McpHandler(BaseHTTPRequestHandler):
    server_version = "GrowiBridgeMCP"

    def log_message(self, *a):
        pass

    def _rechazo(self, code, motivo, id_=None, rpc=-32600):
        log(f"mcp: rechazada una petición ({code}): {motivo}")
        _mcp_resp(self, code, _mcp_err(id_, rpc, motivo))

    def do_GET(self):
        _mcp_resp(self, 405, _mcp_err(None, -32600, "GET no existe en esta revisión (2026-07-28)"))

    def do_DELETE(self):
        self.do_GET()

    def do_POST(self):
        if self.client_address[0] != "127.0.0.1":
            return self._rechazo(403, "solo desde este PC (127.0.0.1)")
        origen = self.headers.get("Origin")
        if origen and origen not in gateway_origenes():
            return self._rechazo(403, f"Origin no permitido: {origen}")
        if not gateway_host_ok(self.headers.get("Host") or ""):
            return self._rechazo(403, "Host no es este PC (DNS rebinding)")
        tok, _o = gateway_token(crear=False)
        auth = self.headers.get("Authorization") or ""
        if not tok or not hmac.compare_digest(auth, f"Bearer {tok}"):
            return self._rechazo(401, "falta el token o no es el bueno")
        if self.path.split("?")[0] != "/mcp":
            return self._rechazo(404, "el endpoint MCP es /mcp")
        try:
            n = int(self.headers.get("Content-Length") or 0)
            msg = json.loads(self.rfile.read(min(n, 1048576)).decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            return self._rechazo(400, "JSON inválido", rpc=-32700)
        id_, metodo, params = msg.get("id"), msg.get("method"), msg.get("params") or {}
        if "id" not in msg:
            return _mcp_resp(self, 202)  # una notificación: aceptada, sin cuerpo
        ver_h = self.headers.get("MCP-Protocol-Version")
        ver_b = ((params.get("_meta") or {}).get("io.modelcontextprotocol/protocolVersion"))
        if not ver_h or ver_h != ver_b:
            return self._rechazo(400, "MCP-Protocol-Version falta o no coincide con _meta", id_, -32020)
        if ver_h != MCP_VERSION:
            return _mcp_resp(self, 400, {"jsonrpc": "2.0", "id": id_, "error": {
                "code": -32000, "message": "versión no soportada", "data": {"supported": [MCP_VERSION]}}})
        if self.headers.get("Mcp-Method") != metodo:
            return self._rechazo(400, "Mcp-Method no coincide con el cuerpo", id_, -32020)
        nombre = params.get("name") or params.get("uri")
        if metodo in ("tools/call", "resources/read", "prompts/get") and self.headers.get("Mcp-Name") != nombre:
            return self._rechazo(400, "Mcp-Name no coincide con el cuerpo", id_, -32020)
        if metodo == "tools/list":
            tools = [{"name": k, "title": v["title"], "description": v["description"] + f" (nivel {v['nivel']})",
                      "inputSchema": v["inputSchema"]} for k, v in MCP_HERRAMIENTAS.items()]
            return _mcp_resp(self, 200, {"jsonrpc": "2.0", "id": id_, "result": {"resultType": "complete",
                                                                                "tools": tools}})
        if metodo == "tools/call":
            if nombre not in MCP_HERRAMIENTAS:
                return _mcp_resp(self, 200, _mcp_err(id_, -32602, f"herramienta desconocida: {nombre}"))
            res = mcp_ejecutar_herramienta(nombre, params.get("arguments") or {})
            log(f"mcp: tools/call {nombre}")
            return _mcp_resp(self, 200, {"jsonrpc": "2.0", "id": id_, "result": res})
        if metodo == "server/discover":
            return _mcp_resp(self, 200, {"jsonrpc": "2.0", "id": id_, "result": {
                "resultType": "complete", "serverInfo": MCP_SERVIDOR_INFO, "capabilities": {"tools": {}},
                "supportedVersions": [MCP_VERSION]}})
        return _mcp_resp(self, 404, _mcp_err(id_, -32601, f"método no implementado: {metodo}"))


def mcp_servidor_arrancar():
    """Solo si está encendido en settings («mcp_servidor»). Siempre en 127.0.0.1."""
    if _MCP["server"] is not None or not load_settings().get("mcp_servidor"):
        return False
    gateway_token(crear=True)
    try:
        srv = ThreadingHTTPServer(("127.0.0.1", mcp_puerto()), McpHandler)
    except OSError as e:
        log(f"mcp: no se pudo abrir 127.0.0.1:{mcp_puerto()} ({e})")
        return False
    _MCP.update(server=srv, puerto=mcp_puerto())
    threading.Thread(target=srv.serve_forever, daemon=True, name="mcp").start()
    log(f"mcp: servidor Streamable HTTP ({MCP_VERSION}) en http://127.0.0.1:{mcp_puerto()}/mcp (con token y Origin)")
    return True


def mcp_servidor_parar():
    if _MCP["server"] is not None:
        _MCP["server"].shutdown()
        _MCP["server"].server_close()
        _MCP["server"] = None
        log("mcp: servidor parado")


# ---- cliente
def mcp_clientes():
    v = load_settings().get("mcp_clientes")
    return v if isinstance(v, list) and v else list(MCP_CLIENTES_DEF)


def _mcp_post(url, msg, cab, sesion=None):
    """(status, cabeceras, json_o_None, texto). Entiende application/json y SSE."""
    h = dict({"Content-Type": "application/json", "Accept": "application/json, text/event-stream",
              "User-Agent": "GrowiBridge"}, **cab)
    if sesion:
        h["Mcp-Session-Id"] = sesion
    req = urllib.request.Request(url, data=json.dumps(msg).encode("utf-8"), method="POST", headers=h)
    op = urllib.request.build_opener(urllib.request.ProxyHandler({}) if "127.0.0.1" in url else urllib.request.ProxyHandler())
    try:
        r = op.open(req, timeout=40)
        code, hdr, raw = r.status, dict(r.headers), r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        code, hdr, raw = e.code, dict(e.headers or {}), e.read().decode("utf-8", "replace")
    obj = None
    if "event-stream" in (hdr.get("Content-Type") or hdr.get("content-type") or ""):
        for linea in raw.splitlines():
            if linea.startswith("data:"):
                try:
                    d = json.loads(linea[5:].strip())
                except ValueError:
                    continue
                if isinstance(d, dict) and ("result" in d or "error" in d):
                    obj = d
    else:
        try:
            obj = json.loads(raw) if raw.strip() else None
        except ValueError:
            obj = None
    return code, hdr, obj, raw


def mcp_llamar(url, metodo, params=None, token=None):
    """Una llamada MCP: primero la revisión vigente; si el servidor es de la era
    anterior (initialize + sesión), cae a esa. (resultado, error, era)."""
    params = dict(params or {})
    auth = {"Authorization": f"Bearer {token}"} if token else {}
    meta = {"io.modelcontextprotocol/protocolVersion": MCP_VERSION,
            "io.modelcontextprotocol/clientInfo": {"name": "growi-bridge", "version": VERSION},
            "io.modelcontextprotocol/clientCapabilities": {}}
    if url not in _MCP["legado"]:
        msg = {"jsonrpc": "2.0", "id": 1, "method": metodo, "params": dict(params, _meta=meta)}
        cab = dict(auth, **{"MCP-Protocol-Version": MCP_VERSION, "Mcp-Method": metodo})
        if params.get("name"):
            cab["Mcp-Name"] = params["name"]
        code, _h, obj, raw = _mcp_post(url, msg, cab)
        moderno = isinstance(obj, dict) and isinstance(obj.get("error"), dict) and obj["error"].get("code") in (
            -32020, -32601, -32602, -32000)
        if code == 200 and isinstance(obj, dict) and "result" in obj:
            return obj["result"], None, MCP_VERSION
        if code in (400, 404, 405) and not moderno:
            _MCP["legado"][url] = None  # era anterior: initialize + sesión
        else:
            return None, (obj or {}).get("error") or f"HTTP {code}: {raw[:200]}", MCP_VERSION
    ses = _MCP["legado"].get(url)
    cab = dict(auth, **{"MCP-Protocol-Version": MCP_VERSION_LEGADO})
    if ses is None:
        code, hdr, obj, raw = _mcp_post(url, {"jsonrpc": "2.0", "id": 0, "method": "initialize", "params": {
            "protocolVersion": MCP_VERSION_LEGADO, "capabilities": {},
            "clientInfo": {"name": "growi-bridge", "version": VERSION}}}, auth)
        if code != 200 or not obj or "result" not in obj:
            return None, f"initialize falló: HTTP {code} {raw[:200]}", MCP_VERSION_LEGADO
        ses = next((v for k, v in hdr.items() if k.lower() == "mcp-session-id"), "")
        _MCP["legado"][url] = ses
        _mcp_post(url, {"jsonrpc": "2.0", "method": "notifications/initialized"}, cab, ses)
    code, _h, obj, raw = _mcp_post(url, {"jsonrpc": "2.0", "id": 2, "method": metodo, "params": params}, cab, ses)
    if obj and "result" in obj:
        return obj["result"], None, MCP_VERSION_LEGADO
    return None, (obj or {}).get("error") or f"HTTP {code}: {raw[:200]}", MCP_VERSION_LEGADO


def mcp_herramientas_cliente(cid):
    """[(nombre, descripcion, activa)] de un servidor externo, con su interruptor."""
    c = next((x for x in mcp_clientes() if x["id"] == cid), None)
    if c is None:
        return [], "no existe ese servidor"
    res, err, era = mcp_llamar(c["url"], "tools/list")
    if err:
        return [], f"{err} ({era})"
    st = load_settings()
    apagadas = set(st.get("mcp_herramientas_apagadas") or [])
    tools = [(t["name"], (t.get("description") or "")[:160]) for t in res.get("tools") or []]
    cache = dict(st.get("mcp_cache") or {})
    if cache.get(cid) != [list(t) for t in tools]:  # «Qué puede hacer» las pinta sin red
        cache[cid] = [list(t) for t in tools]
        st["mcp_cache"] = cache
        save_settings(st)
    return [(n, d, f"{cid}:{n}" not in apagadas) for n, d in tools], None


def mcp_herramientas_conocidas():
    """[(cid, nombre, descripcion, activa)] de la última lista vista de cada servidor (sin red)."""
    st = load_settings()
    apagadas = set(st.get("mcp_herramientas_apagadas") or [])
    return [(cid, n, d, f"{cid}:{n}" not in apagadas)
            for cid, tools in (st.get("mcp_cache") or {}).items() for n, d in tools]


def mcp_herramienta_interruptor(cid, nombre, activa):
    s = load_settings()
    ap = set(s.get("mcp_herramientas_apagadas") or [])
    (ap.discard if activa else ap.add)(f"{cid}:{nombre}")
    s["mcp_herramientas_apagadas"] = sorted(ap)
    save_settings(s)
    log(f"mcp: herramienta {cid}:{nombre} {'encendida' if activa else 'apagada'}")


def mcp_usar(cid, nombre, args):
    """Desde el runner: una herramienta de un servidor externo (si está encendida)."""
    if f"{cid}:{nombre}" in set(load_settings().get("mcp_herramientas_apagadas") or []):
        return None, f"la herramienta {cid}:{nombre} está apagada: no se usa"
    c = next((x for x in mcp_clientes() if x["id"] == cid), None)
    if c is None:
        return None, "no existe ese servidor MCP"
    res, err, _era = mcp_llamar(c["url"], "tools/call", {"name": nombre, "arguments": args or {}})
    if err:
        return None, str(err)[:300]
    txt = "\n".join(x.get("text", "") for x in res.get("content") or [] if x.get("type") == "text")
    return txt, None


def mcp_de_tarea(task):
    h = task.get("herramienta") if isinstance(task.get("herramienta"), dict) else None
    return h if h and h.get("id") == "mcp" else None


def mcp_correr(task, pedido):
    result = _base_result(task, f"mcp:{pedido.get('servidor')} (herramienta)")
    t0 = time.time()
    txt, err = mcp_usar(pedido.get("servidor"), pedido.get("tool"), pedido.get("args") or {})
    result.update(cost_usd=0.0, finished_at=_now_iso(), duration_s=round(time.time() - t0, 1),
                  herramienta={"id": "mcp", "servidor": pedido.get("servidor"), "tool": pedido.get("tool")})
    if err:
        result.update(status="error", error=err, error_tipo="definitivo")
    else:
        result.update(status="ok", result=txt[:20000])
    log(f"runner [{task['id']}]: MCP {pedido.get('servidor')}:{pedido.get('tool')}: {'ok' if not err else err}")
    return result


def mcp_ui():
    """El servidor MCP (encender/apagar) y las herramientas de los servidores externos, con interruptor."""
    top = tk.Toplevel(_root)
    top.title("MCP")
    top.configure(bg=THEME["bg"])
    top.geometry(f"{S(660)}x{S(560)}")
    page = _scrollable(top)
    k = _KitTk(page)
    c = k.section("Servidor MCP de Bridge", f"Streamable HTTP ({MCP_VERSION}), solo en 127.0.0.1, con token y Origin. "
                                            "Nunca expone: " + "; ".join(MCP_NUNCA) + ".")
    est = k.label(c, "", wrap=600)
    est.pack(anchor="w", padx=16)

    def pintar_srv():
        k.set_label(est, text=(f"Encendido en http://127.0.0.1:{_MCP['puerto']}/mcp" if _MCP["server"] else "Apagado."))

    def alternar():
        s_ = load_settings()
        s_["mcp_servidor"] = not bool(_MCP["server"])
        save_settings(s_)
        mcp_servidor_arrancar() if s_["mcp_servidor"] else mcp_servidor_parar()
        pintar_srv()
    k.button(c, "Encender / apagar", alternar).pack(anchor="w", padx=16, pady=(4, 12))
    pintar_srv()
    for cli in mcp_clientes():
        c2 = k.section(f"Servidor externo: {cli['id']}", f"{cli['url']} — {cli.get('para', '')}")
        box = k.frame(c2)
        box.pack(fill="x", padx=16, pady=(2, 12))
        tools, err = mcp_herramientas_cliente(cli["id"])
        if err:
            k.label(box, f"No responde: {err}", color="red").pack(anchor="w")
        for nombre, desc, activa in tools:
            v = tk.BooleanVar(value=activa)
            tk.Checkbutton(box, text=f"{nombre} — {desc[:70]}", variable=v, bg=THEME["card"], fg=THEME["text"],
                           justify="left",
                           anchor="w", command=lambda n=nombre, v=v, cid=cli["id"]: mcp_herramienta_interruptor(
                               cid, n, v.get())).pack(anchor="w", fill="x")
    return top


# ---- Puerta USB/serial para un gadget (t-gadget-esp32). SOLO la puerta en
# software: lista los puertos serie reales del PC (registro de Windows, sin
# inventar), abre SOLO el que el usuario eligió en la app (baudios y timeout
# visibles) y habla el protocolo de texto de PROTOCOLO-GADGET.md (propuesta).
# Sin pyserial: Win32 con ctypes. «tcp://127.0.0.1:<puerto>» es la línea serie
# del emulador (pruebas/emulador_gadget.py), solo en loopback. Lo que el gadget
# pide (PEDIR) es un encargo con canal «serie»: pasa por el guardrail (R2 espera
# aprobación, R3 se deniega). Nada de hardware aquí.
GADGET_LOG = APP_DIR / "gadget.log"
GADGET_PROTOCOLO = "1"
GADGET_BAUDIOS = ("9600", "57600", "115200", "230400")
_GADGET: dict = {"con": None, "hilo": None, "resp": None, "dispositivo": None}


def gadget_puertos():
    """[(nombre, dispositivo del sistema)] de HKLM\\HARDWARE\\DEVICEMAP\\SERIALCOMM: los reales, o []."""
    out = []
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"HARDWARE\DEVICEMAP\SERIALCOMM") as k:
            i = 0
            while True:
                try:
                    disp, com, _t = winreg.EnumValue(k, i)
                except OSError:
                    break
                out.append((str(com), str(disp)))
                i += 1
    except OSError:
        pass  # sin la clave: no hay ningún puerto serie
    return sorted(out, key=lambda x: int(re.sub(r"\D", "", x[0]) or 0))


def _gadget_log(direccion, linea):
    try:
        with GADGET_LOG.open("a", encoding="utf-8") as f:
            f.write(f"{_now_iso()} {_GADGET.get('dispositivo') or '-'} {direccion} {linea}\n")
    except OSError:
        pass


class _SerieWin:
    """Un COM real con Win32 (CreateFile / SetCommState / ReadFile / WriteFile)."""

    def __init__(self, com, baudios, timeout):
        import ctypes
        from ctypes import wintypes
        self.k = ctypes.WinDLL("kernel32", use_last_error=True)
        self.ct, self.wt = ctypes, wintypes
        self.k.CreateFileW.restype = ctypes.c_void_p
        h = self.k.CreateFileW("\\\\.\\" + com, 0xC0000000, 0, None, 3, 0, None)
        if h in (None, ctypes.c_void_p(-1).value):
            raise OSError(f"no se pudo abrir {com} (error {ctypes.get_last_error()})")
        self.h = h

        class DCB(ctypes.Structure):
            _fields_ = [("DCBlength", wintypes.DWORD), ("BaudRate", wintypes.DWORD), ("flags", wintypes.DWORD),
                        ("wReserved", wintypes.WORD), ("XonLim", wintypes.WORD), ("XoffLim", wintypes.WORD),
                        ("ByteSize", ctypes.c_ubyte), ("Parity", ctypes.c_ubyte), ("StopBits", ctypes.c_ubyte),
                        ("XonChar", ctypes.c_char), ("XoffChar", ctypes.c_char), ("ErrorChar", ctypes.c_char),
                        ("EofChar", ctypes.c_char), ("EvtChar", ctypes.c_char), ("wReserved1", wintypes.WORD)]
        dcb = DCB()
        dcb.DCBlength = ctypes.sizeof(DCB)
        hh = ctypes.c_void_p(h)
        if not (self.k.GetCommState(hh, ctypes.byref(dcb))
                and self.k.BuildCommDCBW(f"baud={int(baudios)} parity=N data=8 stop=1", ctypes.byref(dcb))
                and self.k.SetCommState(hh, ctypes.byref(dcb))):
            self.close()
            raise OSError(f"{com}: no acepta {baudios} baudios (error {ctypes.get_last_error()})")
        ms = int(float(timeout) * 1000)
        to = (wintypes.DWORD * 5)(50, 0, ms, 0, ms)
        self.k.SetCommTimeouts(hh, ctypes.byref(to))

    def write(self, b):
        n = self.wt.DWORD()
        self.k.WriteFile(self.ct.c_void_p(self.h), b, len(b), self.ct.byref(n), None)

    def read(self, n=256):
        buf = self.ct.create_string_buffer(n)
        got = self.wt.DWORD()
        if not self.k.ReadFile(self.ct.c_void_p(self.h), buf, n, self.ct.byref(got), None):
            raise OSError("lectura del puerto falló")
        return buf.raw[:got.value]

    def close(self):
        if getattr(self, "h", None):
            self.k.CloseHandle(self.ct.c_void_p(self.h))
            self.h = None


class _SerieTcp:
    """La línea serie del emulador: tcp://127.0.0.1:<puerto> (solo loopback)."""

    def __init__(self, dir_, timeout):
        host, _sep, puerto = dir_[len("tcp://"):].partition(":")
        if host not in ("127.0.0.1", "localhost"):
            raise OSError("el emulador solo se acepta en 127.0.0.1")
        self.s = socket.create_connection((host, int(puerto)), timeout=float(timeout))
        self.s.settimeout(float(timeout))

    def write(self, b):
        self.s.sendall(b)

    def read(self, n=256):
        try:
            d = self.s.recv(n)
        except socket.timeout:
            return b""
        if not d:
            raise OSError("el emulador cerró la línea")
        return d

    def close(self):
        try:
            self.s.close()
        except OSError:
            pass


def gadget_elegir(dispositivo):
    """El usuario elige el puerto en la app: queda registrado. Solo este se puede abrir."""
    s = load_settings()
    s["gadget_puerto"] = str(dispositivo).strip()
    save_settings(s)
    log(f"gadget: puerto elegido por el usuario: {s['gadget_puerto']}")
    _gadget_log("**", f"puerto elegido por el usuario: {s['gadget_puerto']}")


def gadget_abrir(dispositivo, baudios=115200, timeout=2.0):
    """Abre el puerto ELEGIDO (nunca otro) y saluda. (ok, mensaje)."""
    dispositivo = str(dispositivo).strip()
    if dispositivo != str(load_settings().get("gadget_puerto") or ""):
        return False, f"{dispositivo} no es el puerto elegido en la app: no se abre"
    gadget_cerrar()
    try:
        con = _SerieTcp(dispositivo, timeout) if dispositivo.startswith("tcp://") else _SerieWin(dispositivo, baudios,
                                                                                              timeout)
    except (OSError, ValueError) as e:
        log(f"gadget: no se abrió {dispositivo}: {e}")
        return False, str(e)
    _GADGET.update(con=con, resp=queue.Queue(), dispositivo=dispositivo, timeout=float(timeout))
    _gadget_log("**", f"abierto a {baudios} baudios, timeout {timeout} s")
    h = threading.Thread(target=_gadget_leer, args=(con,), daemon=True, name="gadget")
    _GADGET["hilo"] = h
    h.start()
    r = gadget_enviar(f"HOLA {GADGET_PROTOCOLO}")
    log(f"gadget: abierto {dispositivo} ({baudios} baudios): {r}")
    return (r or "").startswith("OK"), r or "el gadget no contestó al HOLA"


def gadget_cerrar():
    con = _GADGET.get("con")
    _GADGET["con"] = None
    if con:
        con.close()
        _gadget_log("**", "cerrado")


def gadget_enviar(linea):
    """Manda una línea (comando del protocolo) y espera su OK/ERR. Devuelve la respuesta o None."""
    con = _GADGET.get("con")
    if not con:
        return None
    linea = str(linea).replace("\r", " ").replace("\n", " ").strip()[:240]
    if not linea:
        return None  # una línea vacía no se manda
    while not _GADGET["resp"].empty():
        _GADGET["resp"].get_nowait()
    _gadget_log(">>", linea)
    try:
        con.write((linea + "\n").encode("utf-8"))
        return _GADGET["resp"].get(timeout=_GADGET.get("timeout", 2.0) + 1)
    except (OSError, queue.Empty):
        return None


def _gadget_leer(con):
    buf = b""
    while _GADGET.get("con") is con:
        try:
            d = con.read(256)
        except OSError as e:
            if _GADGET.get("con") is con:
                log(f"gadget: lectura cortada: {e}")
                _gadget_log("**", f"lectura cortada: {e}")
            return
        buf += d
        while b"\n" in buf:
            raw, buf = buf.split(b"\n", 1)
            linea = raw.decode("utf-8", errors="replace").strip()
            if linea:
                _gadget_linea(con, linea)


def _gadget_linea(con, linea):
    _gadget_log("<<", linea)
    cmd = linea.split(" ", 1)
    if cmd[0] in ("OK", "ERR"):
        _GADGET["resp"].put(linea)
    elif cmd[0] == "PEDIR":  # el gadget pide algo: es un encargo como cualquiera (guardrail)
        encargo = cmd[1].strip() if len(cmd) > 1 else ""
        if not encargo:
            resp = "ERR VACIO"
        else:
            tid = "t-serie-" + datetime.now().strftime("%Y%m%d-%H%M%S-") + secrets.token_hex(2)
            TASKS.mkdir(parents=True, exist_ok=True)
            (TASKS / f"{tid}.task.json").write_text(json.dumps({
                "id": tid, "prompt": encargo, "canal": "serie", "cwd": load_folders()[0]}, ensure_ascii=False),
                encoding="utf-8")
            log(f"gadget: encargo {tid} pedido por serie (canal serie): pasa por el guardrail")
            resp = f"OK ENCOLADO {tid}"
        _gadget_log(">>", resp)
        try:
            con.write((resp + "\n").encode("utf-8"))
        except OSError:
            pass
    else:  # EVENTO u otra cosa: solo se registra, no se ejecuta nada
        log(f"gadget: {linea[:200]}")


def gadget_ui():
    """Elegir el puerto (los reales del PC), abrirlo con baudios y timeout, y conversar."""
    top = tk.Toplevel(_root)
    top.title("Gadget (USB/serie)")
    top.configure(bg=THEME["bg"])
    top.geometry(f"{S(660)}x{S(600)}")
    page = _scrollable(top)
    k = None
    if _ctk_wanted():
        try:
            k = _KitCtk(page)
        except Exception as e:
            log(f"gadget: CustomTkinter no disponible ({type(e).__name__}: {e}); ventana clásica")
    k = k or _KitTk(page)
    puertos = gadget_puertos()
    c = k.section("Puerto", "Los puertos serie que Windows ve ahora. Solo se abre el que elijas aquí. Para el "
                            "emulador, escribe tcp://127.0.0.1:<puerto>.")
    k.label(c, "\n".join(f"{com} — {disp}" for com, disp in puertos) or "Ningún dispositivo.",
            muted=True).pack(anchor="w", padx=16, pady=(2, 6))
    r = k.row(c)
    elegido = load_settings().get("gadget_puerto") or (puertos[0][0] if puertos else "")
    cb = k.option(r, [p[0] for p in puertos], width=26, editable=True)
    cb.set(elegido)
    cb.pack(side="left")
    bd = k.option(r, list(GADGET_BAUDIOS), width=10)
    bd.set("115200")
    bd.pack(side="left", padx=8)
    to = k.entry(r, width=6)
    to.insert(0, "2")
    to.pack(side="left")
    k.label(r, "s de timeout", muted=True).pack(side="left", padx=(4, 0))
    est = k.label(c, "Cerrado.", wrap=600)
    est.pack(anchor="w", padx=16, pady=(4, 4))
    hist = None

    def pintar():
        try:
            lineas = GADGET_LOG.read_text(encoding="utf-8", errors="replace").splitlines()[-14:]
        except OSError:
            lineas = []
        k.set_label(hist, text="\n".join(lineas) or "Sin conversación todavía.")

    def abrir():
        dispo = cb.get().strip()
        if not dispo:
            k.set_label(est, text="Ningún dispositivo que abrir.")
            return
        gadget_elegir(dispo)
        ok, msg = gadget_abrir(dispo, bd.get(), to.get() or "2")
        k.set_label(est, text=(f"Abierto {dispo}: {msg}" if ok else f"No se abrió {dispo}: {msg}"),
                    color=None if ok else "red")
        pintar()

    def cerrar():
        gadget_cerrar()
        k.set_label(est, text="Cerrado.")
        pintar()
    r2 = k.row(c, pady=(0, 12))
    k.button(r2, "Elegir y abrir", abrir, accent=True).pack(side="left")
    k.button(r2, "Cerrar", cerrar).pack(side="left", padx=8)
    c2 = k.section("Conversación", "Comandos del protocolo (PROTOCOLO-GADGET.md): PING, ESTADO, MOSTRAR <texto>, "
                                   "LED ON|OFF. Lo que el gadget pide (PEDIR) pasa por el guardrail.")
    r3 = k.row(c2)
    ent = k.entry(r3, width=40)
    ent.pack(side="left")

    def enviar():
        resp = gadget_enviar(ent.get())
        k.set_label(est, text=f"Respuesta: {resp}" if resp else "Sin respuesta (¿puerto cerrado?)")
        pintar()
    k.button(r3, "Enviar", enviar).pack(side="left", padx=8)
    hist = k.label(c2, "", muted=True, wrap=600)
    hist.pack(anchor="w", padx=16, pady=(4, 12))
    pintar()
    _GADGET["ui"] = {"top": top, "cb": cb, "bd": bd, "to": to, "ent": ent, "est": est, "hist": hist,
                     "abrir": abrir, "enviar": enviar}
    return top


def run_engine(task, prompt=None, eng=None):
    """Corre una tarea con su motor, leyendo SOLO su descriptor (eng: un
    descriptor ya traducido que aun no esta en engines.json, para la prueba
    de «Nuevo motor»)."""
    pedido_m = mcp_de_tarea(task) if eng is None else None
    if pedido_m:  # una herramienta de un servidor MCP externo (t-mcp-streamable-http)
        return mcp_correr(task, pedido_m)
    pedido_t = transcribe_de_tarea(task) if eng is None else None
    if pedido_t:  # transcribir audio/video: faster-whisper local (herramienta), no un motor
        return transcribe_correr(task, pedido_t)
    pedido = herramienta_de_tarea(task) if eng is None else None
    if pedido:  # tornamesa / QC: lo hace Blender (herramienta), no un motor
        return herramienta_correr(task, pedido)
    motor_id = task.get("motor") or default_motor()
    result = _base_result(task, motor_id)
    result.update(_auto_fields(task.get("enrutado")))
    t0 = time.time()
    eng = eng if eng is not None else get_engine(motor_id)
    if eng is None:
        result["error"] = (f"el motor '{motor_id}' no existe en engines.json "
                           f"(hay: {', '.join(engine_ids())})")
    elif eng.get("tipo") == "_mal_formado":
        result["error"] = (f"motor {motor_id} no disponible: descriptor mal formado: "
                           + "; ".join(eng.get("_problemas") or [])[:400])
        result["error_tipo"] = "definitivo"
    else:
        prompt = prompt if prompt is not None else prompt_de_tarea(task)
        tipo = eng.get("tipo")
        try:
            if (eng.get("credencial_ref") or eng.get("autenticacion")) and tipo != "api_asincrona":
                acc = acceso_motor(eng)
                if not acc["ok"]:
                    raise _SinCredencial(acc["motivo"])
                result["acceso"] = acc["modo"]
            if tipo == "cli_sincrono":
                _run_cli_engine(task, motor_id, eng, result, prompt)
            elif tipo == "api_sincrona":
                _run_http_engine(task, motor_id, eng, result, prompt)
            elif tipo == "api_asincrona":
                live_set("tarea", modo_vivo="sin vivo", nota=f"{eng.get('nombre') or motor_id} no reporta tokens")
                _run_async_engine(task, motor_id, eng, result, prompt)
            else:
                result["error"] = f"tipo de motor desconocido en engines.json: {tipo}"
        except _SinCredencial as e:
            result["error"] = f"motor {motor_id} no disponible: {e}"
        except Exception as e:
            result["error"] = f"{type(e).__name__}: {e}"[:300]
    result["finished_at"] = _now_iso()
    result["duration_s"] = round(time.time() - t0, 1)
    if eng is not None and eng.get("credencial_ref") and result.get("acceso") == "clave":
        # La clave solo vive en el entorno del proceso: si el motor la repite
        # en su salida, aqui se tapa (quedan los 4 ultimos).
        try:
            key = resolver_credencial(eng["credencial_ref"])[0]
        except Exception:
            key = None
        for k in ("result", "stderr", "error"):
            if isinstance(result.get(k), str) and result[k]:
                result[k] = _scrub(result[k], key)
    auth = ((eng or {}).get("errores") or {}).get("auth") if isinstance((eng or {}).get("errores"), dict) else None
    if auth and result.get("status") != "ok" and result.get("acceso"):  # solo si el motor llegó a correr
        visto = f"{result.get('error') or ''}\n{result.get('stderr') or ''}"
        if any(re.search(str(p), visto, re.I) for p in auth):
            # 401 / sesion caducada: definitivo, sin reintentos en bucle.
            result["error"] = ("clave inválida o sesión caducada: "
                               + str(result.get("error") or "el motor rechazó la autenticación"))[:300]
            result["error_tipo"] = "definitivo"
            sesion_cli_caducada(eng, "clave inválida o sesión caducada (lo vio la última tarea)")
    if eng is not None and result.get("status") == "ok" and result.get("cost_usd") is None:
        # El motor no da costo: se dice, nunca se inventa un numero.
        result["costo_dato"] = "sin dato (el motor no lo da)"
    if eng is not None and result.get("status") != "ok" and not result.get("error_tipo"):
        kind = "transitorio" if result.get("status") == "timeout" else clasificar_error(eng, result.get("error"))
        if kind:
            result["error_tipo"] = kind
    return result


class _SinCredencial(Exception):
    """El motor necesita la clave de su credencial_ref y no esta guardada."""


# ---- «Nuevo motor»: prueba corta real antes de guardar
PRUEBA_PROMPT = "Escribe tres frutas, una por linea"
PRUEBA_PROMPT_2 = ("¿Cuál fue la segunda fruta que escribiste antes? Responde solo con esa "
                   "palabra.")
MOTORES_SALUD_FILE = APP_DIR / "motores-salud.json"


def probar_descriptor(motor_id, desc, timeout_min=3):
    """Corre la tarea corta de verdad con ese descriptor (sin guardarlo) y
    dice si pasa: salida, costo/turnos (o 'no los da') y si reanuda. Se usa
    en un proceso aparte (--probar-motor), asi no pisa la tarea en curso."""
    import tempfile
    out = {"motor": motor_id, "paso": False, "hora": _now_iso(), "salida": "", "costo": None,
           "turnos": None, "reanuda": None, "motivo": "", "problemas": []}
    probs = validar_descriptor(motor_id, desc)
    if probs:
        out["problemas"] = probs
        out["motivo"] = "descriptor mal formado: " + "; ".join(probs)
        return out
    eng = runtime_engine(motor_id, desc)
    ok, why = engine_status_rt(eng, autostart=True)
    if not ok:
        out["motivo"] = f"no disponible: {why}"
        return out
    cwd = Path(tempfile.gettempdir()) / "growi-prueba-motor"
    cwd.mkdir(parents=True, exist_ok=True)
    task = {"id": f"prueba-motor-{motor_id}"[:60], "motor": motor_id, "prompt": PRUEBA_PROMPT,
            "cwd": str(cwd), "timeout_min": timeout_min, "session_id": None, "modelo": None,
            "allowed_tools": None, "permission_mode": None, "ronda": 0}
    r1 = run_engine(task, prompt=PRUEBA_PROMPT, eng=eng)
    out["salida"] = (r1.get("result") or "")[:1500]
    out["error"] = r1.get("error")
    out["stderr"] = (r1.get("stderr") or "")[-500:]
    out["duracion_s"] = r1.get("duration_s")
    if r1.get("status") != "ok" or not out["salida"].strip():
        out["motivo"] = f"la prueba falló: {r1.get('error') or 'no devolvió texto'}"
        return out
    ext = desc.get("extraer") or {}
    for k, field in (("costo", "cost_usd"), ("turnos", "num_turns")):
        if ext.get(k) == "no_lo_da":
            out[k] = "no los da"
        elif r1.get(field) is None:
            out["motivo"] = (f"el descriptor dice que el motor da {k}, pero en la salida no "
                             f"salió (revisa la ruta o pon «no lo da»)")
            return out
        else:
            out[k] = r1.get(field)
    lineas = [x for x in out["salida"].splitlines() if x.strip()]
    out["lineas"] = len(lineas)
    if soporta_reanudar(eng):
        sid = r1.get("session_id")
        if not sid:
            out["reanuda"] = "no: dice que reanuda pero no devolvió ninguna sesión"
            out["motivo"] = "el descriptor dice que reanuda y no devolvió sesión (o pon «no soporta»)"
            return out
        r2 = run_engine(dict(task, id=task["id"] + "-2", session_id=sid), prompt=PRUEBA_PROMPT_2, eng=eng)
        txt2 = (r2.get("result") or "").strip()
        if r2.get("status") != "ok" or not txt2:
            out["reanuda"] = f"no: la segunda vuelta falló ({r2.get('error') or 'sin texto'})"
            out["motivo"] = "el descriptor dice que reanuda y la segunda vuelta falló"
            return out
        segunda = re.sub(r"^[\s\-*•\d.)]+", "", lineas[1]).strip().lower() if len(lineas) > 1 else ""
        recuerda = bool(segunda) and segunda.split()[0] in txt2.lower()
        out["reanuda"] = (f"sí: misma sesión, recordó «{txt2[:40]}»" if recuerda else
                          f"respondió en la misma sesión («{txt2[:40]}»), sin comprobar que recordara")
    else:
        out["reanuda"] = "no soporta (las rondas van como sesión nueva con resumen)"
    out["paso"] = True
    out["motivo"] = "pasó la prueba corta"
    return out


def _cli_probar_motor(desc_path, out_path=None):
    """python growi-bridge.py --probar-motor <descriptor.json> [salida.json].
    Proceso aparte: no toca la cola, ni la tarea en curso, ni runner-live.json."""
    global LIVE_FILE
    import tempfile
    LIVE_FILE = Path(tempfile.gettempdir()) / "growi-prueba-motor-live.json"
    try:
        d = json.loads(Path(desc_path).read_text(encoding="utf-8"))
        mid = str(d.get("id") or "")
        res = probar_descriptor(mid, d.get("descriptor") or d, int(d.get("_timeout_min") or 3)) \
            if _safe_id(mid) else {"paso": False, "motivo": f"id de motor inválido: {mid!r}"}
    except Exception as e:
        res = {"paso": False, "motivo": f"no se pudo probar ({type(e).__name__}: {e})"}
    text = json.dumps(res, ensure_ascii=False, indent=2)
    if out_path:
        Path(out_path).write_text(text, encoding="utf-8")
    else:
        print(text)
    return 0 if res.get("paso") else 1


# ---- Tripo en subproceso (t-saldo-tripo): la clave solo existe en el entorno
# de este proceso (TRIPO_API_KEY); lo que escribe en la salida nunca la lleva.
class _TripoHttpError(Exception):
    def __init__(self, msg, http=None, codigo=None):
        super().__init__(msg)
        self.http, self.codigo = http, codigo


def _tripo_http(method, url, key, body=None, archivo=None, timeout=60):
    """Una llamada a la API de Tripo. Los GET solo van a rutas de lectura
    (saldo, estado de una tarea): un GET nunca crea ni gasta nada."""
    ruta = urllib.parse.urlsplit(url).path
    if method == "GET" and not any(p in ruta for p in TRIPO_GET_SOLO_LECTURA):
        raise _TripoHttpError(f"ruta GET no permitida: {ruta}")
    hdr = {"Authorization": f"Bearer {key}", "User-Agent": "GrowiBridge"}
    data = None
    if archivo is not None:
        bnd = "----GrowiBridge" + os.urandom(8).hex()
        tipo = "image/png" if archivo.suffix.lower() == ".png" else "image/jpeg"
        data = (f"--{bnd}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"{archivo.name}\"\r\n"
                f"Content-Type: {tipo}\r\n\r\n").encode("utf-8") + archivo.read_bytes() + f"\r\n--{bnd}--\r\n".encode()
        hdr["Content-Type"] = f"multipart/form-data; boundary={bnd}"
    elif body is not None:
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        hdr["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, method=method, headers=hdr)
    try:
        with _cred_open(req, timeout) as r:
            d = json.loads(r.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as e:
        codigo, msg = None, ""
        try:
            err = json.loads(e.read(4000).decode("utf-8", "replace"))
            codigo, msg = err.get("code"), str(err.get("message") or err.get("suggestion") or "")
        except Exception:
            pass
        raise _TripoHttpError(_scrub(f"{_http_reason(e.code)}" + (f": «{msg[:160]}»" if msg else ""), key),
                              e.code, codigo)
    except urllib.error.URLError as e:
        raise _TripoHttpError(_scrub(f"sin conexión ({getattr(e, 'reason', e)})", key))
    if not isinstance(d, dict) or d.get("code") not in (0, None):
        raise _TripoHttpError(_scrub(f"Tripo respondió code {d.get('code') if isinstance(d, dict) else '?'}: "
                                     f"{(d or {}).get('message') or ''}"[:200], key), 200,
                              d.get("code") if isinstance(d, dict) else None)
    return d.get("data") if isinstance(d.get("data"), (dict, list)) else d


def _tripo_salida(out_path, res):
    tmp = Path(str(out_path) + ".tmp")
    tmp.write_text(json.dumps(res, ensure_ascii=False), encoding="utf-8")
    os.replace(tmp, out_path)


def _cli_tripo_saldo(base_url, out_path):
    """--tripo-saldo <base_url> <salida.json>: GET /v3/account/balance."""
    key = os.environ.get("TRIPO_API_KEY") or ""
    res = {"ok": False}
    if not key:
        res["error"] = "falta TRIPO_API_KEY en el entorno del subproceso"
    else:
        try:
            d = _tripo_http("GET", str(base_url).rstrip("/") + "/v3/account/balance", key, timeout=30)
            res.update(ok=True, http=200, creditos=float(d["balance"]), congelados=float(d.get("frozen") or 0))
        except _TripoHttpError as e:
            res.update(error=str(e), http=e.http, codigo=e.codigo)
        except (KeyError, TypeError, ValueError) as e:
            res.update(error=f"respuesta sin «balance» ({type(e).__name__})")
    _tripo_salida(out_path, res)
    return 0 if res["ok"] else 1


def _cli_tripo_generar(spec_path, out_path):
    """--tripo-generar <spec.json> <salida.json>: sube las fotos, crea la tarea,
    la sondea y baja el modelo. Escribe el progreso en la salida (task_id en
    cuanto existe) para que la app lo registre aunque algo se corte."""
    key = os.environ.get("TRIPO_API_KEY") or ""
    res = {"estado": "fallida", "task_id": None, "creditos_reales": None, "error": None, "http": None,
           "paso": "empezando", "progreso": 0}

    def w(**kw):
        res.update(kw)
        _tripo_salida(out_path, res)
    try:
        sp = json.loads(Path(spec_path).read_text(encoding="utf-8"))
        base = str(sp["base_url"]).rstrip("/")
        if not key:
            w(error="falta TRIPO_API_KEY en el entorno del subproceso", creditos_reales=0.0,
              creditos_fuente="no se creó la tarea: no gastó")
            return 1
        tipo, q = sp["tipo"], {"estandar": "standard", "alta": "detailed"}[sp["calidad"]]
        body = {"model": TRIPO_MODELO, "texture": True, "pbr": True, "texture_quality": q, "geometry_quality": q}

        def token(v):
            if re.match(r"https?://", str(v)):
                return v
            w(paso=f"subiendo {Path(v).name}")
            return _tripo_http("POST", base + "/v3/files", key, archivo=Path(v), timeout=120)["file_token"]
        fotos = sp.get("fotos") or {}
        if tipo == "texto":
            body["prompt"] = sp["prompt"]
        elif tipo == "imagen":
            body["input"] = token(fotos["front"])
        else:
            body["inputs"] = [{v: token(fotos[v])} for v in TRIPO_VISTAS if fotos.get(v)]
        w(paso="creando la tarea")
        tid = _tripo_http("POST", base + TRIPO_RUTAS[tipo], key, body=body).get("task_id")
        if not tid:
            w(error="Tripo no devolvió el id de la tarea", creditos_reales=None)
            return 1
        w(estado="en_curso", task_id=tid, paso="en cola")
        deadline = time.time() + float(sp.get("timeout_min") or 30) * 60
        while True:
            t = _tripo_http("GET", f"{base}/v3/tasks/{tid}", key)
            stt = str(t.get("status") or "")
            if isinstance(t.get("credits_consumed"), (int, float)):
                res["creditos_reales"] = float(t["credits_consumed"])
            w(paso=stt or "esperando", progreso=int(t.get("progress") or 0))
            if stt == "success":
                break
            if stt in ("failed", "cancelled", "banned", "expired", "unknown"):
                cobro = res["creditos_reales"]
                w(estado="cancelada" if stt == "cancelled" else "fallida",
                  error=f"Tripo dijo {stt}" + (f": {t.get('error_message') or t.get('error_code')}"
                                               if t.get("error_message") or t.get("error_code") else ""),
                  creditos_reales=cobro if cobro is not None else 0.0,
                  creditos_fuente=("credits_consumed de la tarea" if cobro is not None else
                                   "0: la tarea no dio credits_consumed y Tripo devuelve lo congelado "
                                   "si falla o se cancela"))
                return 1
            if time.time() > deadline:
                w(estado="fallida", error=f"timeout de {sp.get('timeout_min') or 30} min: la tarea {tid} puede "
                                          "seguir en Tripo y cobrar; mira su estado en la web")
                return 1
            time.sleep(float(sp.get("cada_s") or 5))
        out = t.get("output") or {}
        url = next((out.get(k) for k in ("model_url", "pbr_model", "model", "base_model") if out.get(k)), None)
        if res["creditos_reales"] is not None:
            res["creditos_fuente"] = "credits_consumed de la tarea"
        if not url:
            w(estado="ok", error="la tarea terminó pero no dio la URL del modelo")
            return 1
        ext = Path(urllib.parse.urlsplit(url).path).suffix.lower() or ".glb"
        dest = Path(sp["destino"]).with_suffix(ext)
        dest.parent.mkdir(parents=True, exist_ok=True)
        w(paso="bajando el modelo")
        # La descarga va al CDN SIN la clave (es una URL firmada).
        with _cred_open(urllib.request.Request(url, headers={"User-Agent": "GrowiBridge"}), 300) as r, \
                open(dest, "wb") as f:
            shutil.copyfileobj(r, f)
        size = dest.stat().st_size
        nota = ""
        if ext == ".glb":
            head = dest.read_bytes()[:12]
            if len(head) < 12 or head[:4] != b"glTF" or int.from_bytes(head[8:12], "little") != size:
                nota = " (ojo: la cabecera GLB no cuadra con el tamaño: descarga truncada o no es GLB)"
        w(estado="ok", archivo=str(dest), bytes=size, paso="listo", progreso=100,
          error=("descarga dudosa" + nota) if nota else None)
        return 0
    except _TripoHttpError as e:
        if res.get("task_id"):
            w(estado="fallida", error=str(e), http=e.http, codigo=e.codigo)
        else:  # no llego a crearse la tarea: no congelo ni gasto nada
            w(estado="fallida", error=str(e), http=e.http, codigo=e.codigo, creditos_reales=0.0,
              creditos_fuente="no se creó la tarea: no gastó")
        return 1
    except Exception as e:
        w(estado="fallida", error=_scrub(f"{type(e).__name__}: {e}", key)[:300])
        return 1


def tripo_generar(tipo, calidad, prompt="", fotos=None, timeout_min=30, cada_s=5):
    """Lanza UNA generacion con la credencial Tripo activa y la registra en
    tripo-gasto.jsonl (al lanzar y al terminar). Solo se llama DESPUES de
    que Leandro vio el costo y pulso «Generar» en el dialogo de confirmacion."""
    c = cred_activa("tripo")
    if c is None:
        return {"estado": "no_lanzada", "error": "falta guardar la clave en Ajustes → APIs"}
    antes = tripo_leer_saldo()
    if antes.get("motivo") in ("invalida", "sin_clave"):
        return {"estado": "no_lanzada", "error": antes.get("texto")}
    st = tripo_estado()
    est = tripo_costo_estimado(calidad, tipo)
    host = urllib.parse.urlsplit(c["base_url"]).netloc
    rid = "tripo-" + datetime.now().strftime("%Y%m%d-%H%M%S")
    entry = {"id": rid, "fecha": _now_iso(), "tipo": tipo, "calidad": calidad,
             "creditos_estimados": est["creditos"], "fuente_estimacion": est["fuente"],
             "creditos_reales": None, "saldo_antes": st["creditos"], "saldo_antes_en_vivo": st["en_vivo"],
             # La etiqueta en texto, la misma que se ve en la app («en vivo» / «… no en vivo …»).
             "saldo_antes_estado": "en vivo" if st["en_vivo"] else st["fuente"],
             "saldo_despues_estado": None,
             "saldo_despues": None, "saldo_despues_en_vivo": None, "clave_etiqueta": c["etiqueta"],
             "clave_cuenta": c["cuenta"], "clave": tripo_mask(c["ultimos4"]), "base_host": host,
             "task_id": None, "estado": "en_curso", "simulada": _tripo_es_local(c["base_url"]),
             "lanzada_desde": "app: Modelos → Generar con Tripo"}
    tripo_gasto_registrar(entry)
    _TRIPO["gen"] = {"id": rid, "paso": "empezando", "progreso": 0, "task_id": None, "fin": None}
    log(f"tripo: lanzo {rid}: {TRIPO_TIPO_TXT[tipo]} en {TRIPO_CALIDAD_TXT[calidad]} con «{c['etiqueta']}» "
        f"({tripo_mask(c['ultimos4'])}) en {host}; costo estimado ~{_tripo_num(est['creditos'])} créditos; "
        f"saldo antes {_tripo_num(st['creditos'])}" + ("" if st["en_vivo"] else " (no en vivo)"))
    import tempfile
    tmp = Path(tempfile.mkdtemp(prefix="growi-tripo-gen-"))
    spec, dst = tmp / "spec.json", tmp / "salida.json"
    spec.write_text(json.dumps({"base_url": c["base_url"], "tipo": tipo, "calidad": calidad, "prompt": prompt,
                                "fotos": fotos or {}, "timeout_min": timeout_min, "cada_s": cada_s,
                                "destino": str(TRIPO_MODELOS_DIR / rid)}, ensure_ascii=False), encoding="utf-8")
    env = dict(os.environ)
    env["TRIPO_API_KEY"] = cred_clave(c["cuenta"]) or ""
    res = {}
    try:
        p = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "--tripo-generar", str(spec), str(dst)],
                             cwd=str(APP_DIR), env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
                             **_oculto())
        env.pop("TRIPO_API_KEY", None)
        while True:
            fin = p.poll()
            try:
                res = json.loads(dst.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                pass
            if res.get("task_id") and not entry["task_id"]:
                entry["task_id"] = res["task_id"]
                tripo_gasto_registrar(entry)  # ya hay tarea en Tripo: queda anotada aunque se corte algo
                log(f"tripo: {rid} creó la tarea {res['task_id']}")
            _TRIPO["gen"].update(paso=res.get("paso") or "empezando", progreso=res.get("progreso") or 0,
                                 task_id=res.get("task_id"))
            if fin is not None:
                break
            time.sleep(1)
        if not res:
            err = (p.stderr.read() if p.stderr else b"").decode("utf-8", "replace")[-300:]
            res = {"estado": "fallida", "error": f"el subproceso no devolvió datos ({err.strip() or p.returncode})"}
    finally:
        for f in (spec, dst):
            try:
                f.unlink()
            except OSError:
                pass
        try:
            tmp.rmdir()
        except OSError:
            pass
    despues = tripo_leer_saldo()
    entry.update(estado=res.get("estado") or "fallida", task_id=res.get("task_id") or entry["task_id"],
                 creditos_reales=res.get("creditos_reales"), creditos_fuente=res.get("creditos_fuente"),
                 error=res.get("error"), archivo=res.get("archivo"), terminada=_now_iso(),
                 saldo_despues=despues.get("creditos") if despues.get("ok") else None,
                 saldo_despues_en_vivo=bool(despues.get("ok")),
                 saldo_despues_estado=("en vivo" if despues.get("ok") else
                                       f"no en vivo: no se pudo leer ({despues.get('texto') or 'sin respuesta'})"))
    if despues.get("ok") and st["en_vivo"]:
        entry["diferencia_saldo"] = round(st["creditos"] - despues["creditos"], 2)
    if entry["creditos_reales"] is None and entry["estado"] == "fallida" and not entry["task_id"]:
        entry["creditos_reales"] = 0.0
    tripo_gasto_registrar(entry)
    _TRIPO["gen"].update(fin=entry)
    real = entry["creditos_reales"]
    log(f"tripo: {rid} terminó «{entry['estado']}»: "
        + (f"{_tripo_num(real)} créditos reales" if isinstance(real, (int, float)) else "costo real sin dato")
        + f" (estimado ~{_tripo_num(est['creditos'])}); saldo después "
        + (_tripo_num(entry["saldo_despues"]) if entry["saldo_despues"] is not None else "sin leer")
        + (f"; {entry['error']}" if entry.get("error") else "") + f" -> {TRIPO_GASTO_FILE.name}")
    return entry


def probar_motor_aparte(motor_id, desc, timeout_min=3):
    """Lanza la prueba en otro proceso (el mismo Python y el mismo programa)
    y devuelve su resultado."""
    import tempfile
    tmp = Path(tempfile.mkdtemp(prefix="growi-nuevo-motor-"))
    src, dst = tmp / "descriptor.json", tmp / "resultado.json"
    src.write_text(json.dumps(dict(desc, id=motor_id, _timeout_min=timeout_min), ensure_ascii=False),
                   encoding="utf-8")
    try:
        subprocess.run([sys.executable, str(Path(__file__).resolve()), "--probar-motor", str(src), str(dst)],
                       capture_output=True, timeout=timeout_min * 60 * 2 + 60, cwd=str(APP_DIR),
                       **_oculto())
        return json.loads(dst.read_text(encoding="utf-8"))
    except subprocess.TimeoutExpired:
        return {"paso": False, "motivo": "la prueba tardó demasiado y se cortó"}
    except (OSError, ValueError) as e:
        return {"paso": False, "motivo": f"no se pudo leer el resultado de la prueba ({e})"}
    finally:
        for f in (src, dst):
            try:
                f.unlink()
            except OSError:
                pass
        try:
            tmp.rmdir()
        except OSError:
            pass


def guardar_motor(motor_id, desc, prueba):
    """Anade el motor a engines.json SOLO si la prueba paso. Copia antes el
    archivo a engines.json.bak (la de la ultima vez que se guardo un motor)."""
    if not prueba or not prueba.get("paso"):
        return False, "no se guarda: no pasó la prueba"
    if not _safe_id(motor_id):
        return False, f"id inválido: {motor_id!r}"
    try:
        raw = json.loads(ENGINES_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return False, f"no se pudo leer engines.json ({e})"
    if not isinstance(raw.get("motores"), dict):
        return False, "engines.json no tiene la sección 'motores'"
    if motor_id in raw["motores"]:
        return False, f"ya hay un motor '{motor_id}': ponle otro nombre"
    probs = validar_descriptor(motor_id, desc)
    if probs:
        return False, "descriptor mal formado: " + "; ".join(probs)
    d = dict(desc, id=motor_id)
    d["verificado_en_vivo"] = True
    d["nota_verificacion"] = ("Pasó la prueba corta de «Nuevo motor» el "
                             f"{str(prueba.get('hora') or _now_iso())[:16].replace('T', ' a las ')}.")
    d["prueba"] = {k: prueba.get(k) for k in ("hora", "salida", "costo", "turnos", "reanuda", "duracion_s")}
    d["prueba"]["salida"] = str(d["prueba"]["salida"] or "")[:300]
    raw["motores"][motor_id] = d
    try:
        shutil.copy2(ENGINES_FILE, ENGINES_FILE.with_name(ENGINES_FILE.name + ".bak"))
        tmpf = ENGINES_FILE.with_name(ENGINES_FILE.name + ".tmp")
        tmpf.write_text(json.dumps(raw, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmpf, ENGINES_FILE)
    except OSError as e:
        return False, f"no se pudo escribir engines.json ({e})"
    log(f"motores: nuevo motor '{motor_id}' guardado en engines.json (pasó la prueba corta)")
    return True, f"guardado en engines.json como '{motor_id}'"


# ---- ficha honesta de cada motor
def _salud():
    try:
        d = json.loads(MOTORES_SALUD_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _version_motor(eng):
    """(binario_encontrado, version) leyendo requisitos del descriptor."""
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else {}
    req = d.get("requisitos") if isinstance(d.get("requisitos"), dict) else {}
    exe = None
    if req.get("binario"):
        b = _resolve_binary(dict(eng, binario=req["binario"])) if eng.get("tipo") == "cli_sincrono" \
            else ([shutil.which(req["binario"])] if shutil.which(req["binario"]) else None)
        exe = b[-1] if b else None
    elif req.get("archivos"):
        files = [_app_path(f) for f in req["archivos"]]
        exe = str(files[0]) if all(f.is_file() for f in files) else None
    vc = req.get("version_comando")
    if not exe or not isinstance(vc, list) or not vc:
        return exe, None
    if vc[0] == "{binario}":
        base = _resolve_binary(dict(eng, binario=req.get("binario"))) or [exe]
        cmd = base + [str(x) for x in vc[1:]]
    else:
        cmd = [str(_app_path(vc[0]))] + [str(x) for x in vc[1:]]
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=20, stdin=subprocess.DEVNULL,
                           **_oculto())
        txt = (r.stdout or b"").decode("utf-8", "replace") + (r.stderr or b"").decode("utf-8", "replace")
        line = next((x.strip() for x in txt.splitlines() if x.strip()), "")
        return exe, line[:80] or None
    except (OSError, subprocess.SubprocessError):
        return exe, None


def version_cumple(texto, minima):
    """True/False si la version de 'texto' (p. ej. '1.4.5' o 'agy 1.4.5')
    llega a 'minima'; None si no se puede leer."""
    def nums(s):
        m = re.search(r"\d+(?:\.\d+)*", str(s or ""))
        return [int(x) for x in m.group(0).split(".")] if m else None
    a, b = nums(texto), nums(minima)
    if not a or not b:
        return None
    n = max(len(a), len(b))
    return a + [0] * (n - len(a)) >= b + [0] * (n - len(b))


def comprobar_motor(motor_id):
    """Healthcheck de un motor: disponible, binario, version. Se guarda en
    motores-salud.json (la ficha muestra el ultimo)."""
    eng = get_engine(motor_id)
    if eng is None:
        return None
    if eng.get("autenticacion"):
        _sesion_cli(eng, fresca=True)  # «Comprobar ahora»: la sesion del CLI, de nuevo
    ok, why = engine_status_rt(eng)
    exe, ver = (None, None) if eng.get("tipo") == "_mal_formado" else _version_motor(eng)
    rec = {"hora": _now_iso(), "disponible": ok, "motivo": why, "binario": exe, "version": ver}
    with _STATUS_LOCK:
        d = _salud()
        d[motor_id] = rec
        try:
            MOTORES_SALUD_FILE.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
        except OSError:
            pass
    return rec


INVOCACION_TXT = {"cli_sincrono": "programa de línea de comandos",
                  "api_sincrona": "servidor que responde al momento (HTTP)",
                  "api_asincrona": "servicio por internet que trabaja por encargo (crear, esperar, descargar)"}


def ficha_motor(motor_id, vivo=False):
    """La ficha honesta: lo que el motor hace y, sobre todo, lo que NO puede.
    Lista de (etiqueta, texto, color: ok | aviso | mal | None)."""
    raw, eng = engine_raw(motor_id), get_engine(motor_id)
    if eng is None:
        return [("Motor", f"'{motor_id}' no existe en engines.json", "mal")]
    d = raw if isinstance(raw, dict) else {}
    rows = []
    sal = _salud().get(motor_id) or {}
    fresco = sal and (time.time() - _iso_ts(sal.get("hora")) < 600)
    if fresco and eng.get("tipo") == "api_sincrona" and not vivo and not (
            _srv_es_router(eng) and sal.get("disponible")):
        # Un servidor apagado tarda ~2 s en decir que no: la ficha usa el
        # ultimo healthcheck (de hace menos de 10 min) y no congela la ventana.
        # Un router encendido contesta al momento: su estado (modelo cargado
        # o no) se pregunta siempre, que el «responde» de antes no vale.
        ok, why = bool(sal.get("disponible")), str(sal.get("motivo") or "")
    else:
        ok, why = engine_status_rt(eng)
    rows.append(("Estado", ("disponible" if ok else "no disponible") + f": {why}", "ok" if ok else "mal"))
    if eng.get("tipo") == "_mal_formado":
        return rows
    if _srv_es_router(eng):
        # Salud del router no es modelo listo: el estado de cada modelo sale
        # de GET /models (loaded / unloaded / loading). Si el router no
        # contesto hace poco, no se le pregunta (no congela la ventana).
        apagado = fresco and not vivo and not sal.get("disponible")
        est, txt = (None, "router apagado: ningún modelo cargado (se arranca solo al usarlo)") \
            if apagado else srv_estado_texto(eng)
        listo = bool(est) and "loaded" in est.values()
        col = "ok" if listo else ("aviso" if est is not None else None)
        txt = (f"{SRV_LOCAL_LISTO}: " if listo else f"todavía no es {SRV_LOCAL_LISTO}: ") + txt
        rows.append(("Modelos del router", txt, col))
        if state.get("paso") and str(state["paso"]).startswith(SRV_AVISO_CARGA):
            rows.append(("Ahora", state["paso"], "aviso"))
    rows.append(("Qué es", INVOCACION_TXT.get(eng.get("tipo"), str(eng.get("tipo"))), None))
    if isinstance(d.get("puede"), list) and d["puede"]:
        rows.append(("Qué sí puede", "; ".join(str(x) for x in d["puede"]), None))
    if d.get("verificado_en_vivo") is False or eng.get("_v1"):
        nota = re.sub(r"^\s*sin verificar en vivo[.:]?\s*", "", str(d.get("nota_verificacion") or ""), flags=re.I)
        rows.append(("En vivo", "sin verificar en vivo" + (f": {nota}" if nota else ""), "aviso"))
    else:
        rows.append(("En vivo", "verificado. " + str(d.get("nota_verificacion") or ""), "ok"))
    req = d.get("requisitos") if isinstance(d.get("requisitos"), dict) else {}
    if req.get("binario") or req.get("archivos"):
        if sal:
            rows.append(("Programa", f"encontrado: {sal['binario']}" if sal.get("binario")
                         else "no encontrado en este PC", "ok" if sal.get("binario") else "mal"))
            vmin = req.get("version_min")
            vtxt = sal.get("version") or "no la dice"
            col = None
            if vmin and sal.get("version"):
                cumple = version_cumple(sal["version"], vmin)
                vtxt += (f" (mínimo {vmin}: " + ("cumple)" if cumple else "NO cumple: actualízalo)")
                         if cumple is not None else f" (mínimo {vmin}: no sé leerla)")
                col = "ok" if cumple else ("mal" if cumple is False else "aviso")
            rows.append(("Versión", vtxt, col))
        else:
            rows.append(("Programa", "sin comprobar (pulsa Comprobar ahora)", None))
    rows.append(("Último healthcheck", (f"{sal['hora'][:19].replace('T', ' ')}: "
                 + ("respondió" if sal.get("disponible") else f"falló ({sal.get('motivo')})"))
                 if sal else "nunca (pulsa Comprobar ahora)", None if not sal else
                 ("ok" if sal.get("disponible") else "mal")))
    rows.append(("Dirección (base_url)", str(d.get("base_url") or "no tiene"), None))
    cr = d.get("credencial_ref")
    au = d.get("autenticacion") if isinstance(d.get("autenticacion"), dict) else {}
    if au.get("sesion_cli"):
        sc = au["sesion_cli"]
        acc = acceso_motor(eng, fresca=vivo)
        s_ok, s_why = _sesion_cli(eng)
        rows.append(("Acceso", ("por " + (sc.get("nombre") or "la sesión del programa") + ", sin clave"
                                if acc["modo"] == "sesion_cli" else
                                f"por clave {cred_texto(cr)} (Ajustes → Claves)" if acc["modo"] == "clave"
                                else "ninguno: sin sesión del programa ni clave guardada"),
                     "ok" if acc["ok"] else "mal"))
        det = sesion_cli_detalle(eng)
        rows.append(("Sesión del programa", s_why + (f" ({det})" if det and not s_ok else "") + (
                     "" if s_ok or not sc.get("como_iniciar") else f". Para entrar: {sc['como_iniciar']}"),
                     "ok" if s_ok else "aviso"))
        if cr:
            key, _b, cwhy = resolver_credencial(cr)
            rows.append(("Clave (alternativa)", f"{cred_texto(cr)}: " + (
                "guardada (la activa de Ajustes → Claves)" if key else "sin clave guardada (no hace falta "
                "si la sesión del programa está iniciada)"), "ok" if key else None))
    elif cr:
        key, _b, cwhy = resolver_credencial(cr)
        rows.append(("Credencial", f"{cred_texto(cr)}: " + ("guardada" if key else "sin credencial"),
                     "ok" if key else "mal"))
    else:
        susc = req.get("suscripcion")
        rows.append(("Credencial", "sin credencial: no usa clave" + (f" ({susc})" if susc else ""), None))
    # Lo que NO puede (nunca se finge).
    no = []
    if not _cap(eng, "streaming"):
        no.append("sin streaming: no hay consumo en vivo mientras trabaja")
    if not soporta_reanudar(eng):
        no.append("no reanuda sesión: las rondas van como sesión nueva con resumen")
    cs = (d.get("extraer") or {}).get("costo") if not eng.get("_v1") else None
    if cs == "no_lo_da" or (not eng.get("_v1") and not _cap(eng, "costo")):
        no.append("no da costo: cada tarea dice «sin dato», nunca un número inventado")
    if isinstance(cs, dict) and "fijo" in cs:
        rows.append(("Costo", f"${cs['fijo']} declarado ({cs.get('por_que') or 'fijo'})", None))
    elif isinstance(cs, dict) or isinstance(cs, (str, list)) and cs != "no_lo_da":
        rows.append(("Costo", "lo dice el motor al terminar cada tarea", None))
    else:
        rows.append(("Costo", "sin dato: el motor no lo da", "aviso"))
    if not _cap(eng, "herramientas"):
        no.append("sin herramientas fiables: no se le piden (ni leer ni tocar archivos)")
    no += [str(x) for x in d.get("no_puede") or [] if str(x) not in no]
    rows.append(("Lo que no puede", "; ".join(no) if no else "nada que declarar", "aviso" if no else None))
    if d.get("convive"):
        rows.append(("Convive con", str(d["convive"]), None))
    fb = d.get("fallback")
    rows.append(("Respaldo", (", ".join(fb) + ": declarado, sin usar todavía (t-router-fallbacks)")
                 if fb else "ninguno declarado", None))
    return rows


def _filter_tools(allowed, off_tools):
    """Quita de allowed_tools las herramientas que el usuario apago."""
    if not allowed or not off_tools:
        return allowed
    # Separadas por comas (o por espacios si no hay comas): "Bash(git *)"
    # lleva un espacio dentro y no se debe partir.
    parts = allowed.split(",") if "," in allowed else allowed.split()
    keep = [t.strip() for t in parts
            if t.strip() and t.strip().split("(", 1)[0] not in off_tools]
    return ",".join(keep) or None


def run_task(task):
    if task.get("ollama_action"):
        return run_model_task(task)
    # "liberar_vram": la tarea pide soltar la VRAM del motor local antes de
    # empezar (p. ej. para Blender) o al terminar. Solo cuando lo pide.
    lv = task.get("liberar_vram")
    antes = srv_liberar_para_tarea(task, "antes") if lv == "antes" else []
    _pol_conocer()
    try:
        res = _run_task_motor(task)
    finally:
        try:
            if _pol_vigilar(task) and isinstance(locals().get("res"), dict):
                res["politicas_revertidas"] = True
        except Exception as e:
            log(f"políticas [{task.get('id')}]: no se pudo comprobar {POL_FILE.name} ({type(e).__name__}: {e})")
    if lv and isinstance(res, dict):
        despues = srv_liberar_para_tarea(task, "despues") if lv == "despues" else []
        res["vram_liberada"] = {"cuando": lv, "notas": antes + despues}
    return res


def _run_task_motor(task):
    if task.get("motor") == "api":
        res = _run_api(task)
        res.update(motor="api", modelo=task.get("model"), ronda=task.get("ronda", 0),
                   tarea_padre=task.get("tarea_padre"), raiz=task.get("raiz") or task["id"],
                   fase=task.get("fase"))
        return res
    return run_engine(task)


def _write_result(result):
    RESULTS.mkdir(parents=True, exist_ok=True)
    _ultima_ejecucion_set(result)
    if isinstance(result, dict):
        result.setdefault("run_id", result.get("raiz") or result.get("id"))
        if _CTX.get(str(result.get("id"))):
            result.setdefault("contexto_recibido", _CTX[str(result.get("id"))])
    snap = _cfg_snap()
    if snap is not None and isinstance(result, dict):
        # Evidencia de la recarga en caliente: con que config corrio esta tarea.
        result.setdefault("config_al_empezar", dict(snap["huella"]))
        if snap.get("cred_usada"):
            result.setdefault("credencial_usada", dict(snap["cred_usada"]))
    if isinstance(result, dict) and "gasto_clave" not in result:
        # Gasto POR CLAVE (Ajustes -> Claves): queda en el result con la etiqueta.
        try:
            g = gasto_de_resultado(result)
            if g:
                result["gasto_clave"] = g
                log(f"claves: gasto de la tarea {result.get('id')} con la clave «{g['etiqueta']}» "
                    f"({g['cuenta']}): " + (f"${g['usd']:.6f} ({g['fuente']})" if g["usd"] is not None
                                            else g["fuente"]))
        except Exception as e:
            log(f"claves: no se pudo anotar el gasto ({type(e).__name__})")
    if isinstance(result, dict):
        # Skills nativas: que se activo (o que no se activo ninguna) y, si el
        # motor dijo que le falto una, el borrador propuesto (nunca activo).
        reg = _SKILLS_ACT.get(str(result.get("id")))
        if reg is not None:
            result.setdefault("skills_activadas", [a["nombre"] for a in reg["activadas"]])
            result.setdefault("skills", reg)
        try:
            skills_workshop_de_resultado(result)
        except Exception as e:
            log(f"skills: workshop: {type(e).__name__}: {e}")
        # Memoria: que archivos se inyectaron y cuantos caracteres (t-memoria-pc).
        mc = _MEM_CARGA.get(str(result.get("id")))
        if mc is not None:
            result.setdefault("memoria_cargada", mc["registro"])
        asis_en_resultado(result)  # el asistente (perfil) con el que corrio
    path = RESULTS / f"{result['id']}.result.json"
    with open(path, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    return path


def _error_result(task_id, error):
    return {
        "runner": f"growi-bridge/{VERSION}", "id": task_id, "status": "error",
        "started_at": _now_iso(), "finished_at": _now_iso(), "duration_s": 0,
        "exit_code": None, "result": "", "cost_usd": None, "num_turns": None,
        "session_id": None, "stderr": "", "error": error,
    }


# ---------------------------------------------------------------- orquestacion
# Bucle cerrado: corre -> revisa -> (si falta algo) ronda de correccion,
# maximo 3 -> aprobada / necesita decision. Cada tarea original es una
# "familia" (su raiz) con su estado en <raiz>.orquestacion.json.
ESTADOS = {
    "pendiente": "pendiente", "esperando_aprobacion": "esperando aprobación",
    "en_curso": "en curso", "revisando": "revisando", "aprobada": "aprobada",
    "necesita_decision": "necesita decisión", "fallida": "fallida",
    "sin_revision": "sin revisión", "rechazada": "rechazada",
    "esperando_reintento": "esperando reintento", "en_cuarentena": "en cuarentena",
}
FINAL_STATES = ("aprobada", "necesita_decision", "fallida", "sin_revision", "rechazada", "en_cuarentena")
NO_CONFIRMADO = "Lo intenté pero no pude confirmar que funcionara."


def _family_path(raiz):
    return RESULTS / f"{raiz}.orquestacion.json"


def load_family(raiz):
    try:
        d = json.loads(_family_path(raiz).read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None


def _family_update(raiz, **kw):
    with _FAM_LOCK:
        fam = load_family(raiz) or {"raiz": raiz, "tareas": [], "costo_usd": 0.0,
                                    "creada": _now_iso(), "ronda": 0, "max_rondas": MAX_ROUNDS}
        add = kw.pop("sumar_costo", None)
        if isinstance(add, (int, float)):
            fam["costo_usd"] = round((fam.get("costo_usd") or 0) + add, 4)
        tid = kw.pop("tarea", None)
        if tid and tid not in fam["tareas"]:
            fam["tareas"].append(tid)
        for k, v in kw.items():
            if k.startswith("solo_si_falta_"):
                fam.setdefault(k[len("solo_si_falta_"):], v)
            else:
                fam[k] = v
        fam.setdefault("run_id", raiz)  # t-idempotencia-cuarentena-030: un run_id por encargo
        fam["actualizado"] = _now_iso()
        fam["final"] = fam.get("estado") in FINAL_STATES
        RESULTS.mkdir(parents=True, exist_ok=True)
        tmp = _family_path(raiz).with_suffix(".tmp")
        tmp.write_text(json.dumps(fam, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmp, _family_path(raiz))
        return fam


# ---- aprobacion humana en lo sensible
GUARDRAIL_LEVELS = (("siempre", "Preguntarme siempre",
                     "Antes de borrar, publicar, gastar o enviar algo, te enseño el plan y espero tu sí."),
                    ("delicado", "Preguntarme solo lo delicado",
                     "Solo pregunto si es grave: gastar dinero, publicar, borrar en masa o escribir a otras personas."),
                    ("nunca", "Hazlo sin preguntar",
                     "Growi lo hace todo sin enseñarte el plan. Pide doble confirmación."))
# categoria -> (palabras leves, palabras fuertes). "Preguntarme siempre" pregunta
# por cualquiera; "solo lo delicado" solo por las fuertes.
SENSITIVE = {
    "borrar": ([r"\bborr", r"\belimin", r"\bdelete\b", r"\bremove\b", r"\brm\s", r"\bdel\s",
                r"\bquit\w* (?:el|la|los|las) (?:archivo|carpeta)"],
               [r"\bborr\w* (?:todo|toda|todos|todas|la carpeta|el disco)", r"\brm\s+-\w*r",
                r"\bformate", r"\bdel\s+/s", r"\belimin\w* (?:todo|todos|permanente|la carpeta)",
                r"\bvac[ií]a\w* (?:la|el) (?:carpeta|disco|papelera)"]),
    "publicar": ([r"\bpublic", r"\bsub[ei]r? (?:a|al) ", r"\bupload", r"\bgit push\b", r"\bdeploy",
                  r"\bdespl[ei]eg"],
                 [r"\bpublic", r"\bdeploy", r"\bdespl[ei]eg", r"\bgit push\b", r"\bproducci[oó]n\b",
                  r"\bredes sociales\b", r"\btweet", r"\binstagram\b", r"\byoutube\b"]),
    "gastar": ([r"\bgast", r"\bcompr[aeo]", r"\bpag(?:a|ar|o|ue|ues)\b", r"\bsuscri", r"\bcr[eé]ditos?\b"],
               [r"\bgast\w* (?:dinero|\$|\d)", r"\bcompr[aeo]", r"\bpag(?:a|ar|o|ue|ues)\b", r"\bsuscri",
                r"\btarjeta\b", r"\$\s?\d", r"\bfactur"]),
    "enviar": ([r"\benv[ií]", r"\bmand[ae]r?\b", r"\bsend\b", r"\bcorreo\b", r"\bemail\b"],
               [r"\bcorreo\b", r"\be-?mail\b", r"\bwhatsapp\b", r"\bsms\b", r"\btelegram\b",
                r"\benv[ií]\w* (?:a|al|un mensaje|un correo)\b", r"\bmand\w* un (?:mensaje|correo)\b"]),
}
# Aprobaciones: solo en memoria. Ni el puente ni una tarea pueden escribir
# aqui, asi que nadie se puede autoaprobar; solo el clic del usuario. Se
# guardan por familia (raiz): los tipos R1 aprobados (valen para toda la
# tarea) y los «pases» R2/R3 (cada uno vale UNA vez, para la accion exacta
# que se aprobo). Nada de esto va a disco: solo las politicas de riesgos.json.
_APPROVED = {}  # raiz -> {"tipos": set(tipos R1), "hashes": {hash del paso: approval_id}, "por_tipo": {...}}


def guardrail_level():
    v = load_settings().get("guardrail")
    return v if v in ("siempre", "delicado", "nunca") else "siempre"


def detect_sensitive(task):
    """{categoria: {"nivel": "fuerte"|"leve", "palabras": [...]}} de la tarea.
    (Detector viejo por palabras; desde t-vencimiento-aprobacion-030 manda
    clasificar_riesgo(). Se deja por compatibilidad.)"""
    text = " ".join(str(x) for x in (task.get("prompt") or "",
                                     " ".join(task.get("criterios") or []))).lower()
    found = {}
    for cat, (leves, fuertes) in SENSITIVE.items():
        hits_f = [m.group(0).strip() for r in fuertes for m in [re.search(r, text)] if m]
        hits_l = [m.group(0).strip() for r in leves for m in [re.search(r, text)] if m]
        if hits_f or hits_l:
            found[cat] = {"nivel": "fuerte" if hits_f else "leve",
                          "palabras": sorted(set(hits_f + hits_l))[:6]}
    for cat in task.get("sensible") or []:
        found[cat] = {"nivel": "fuerte", "palabras": ["la tarea lo marca como sensible"]}
    eng = get_engine(task.get("motor") or "") or {}
    for cat in eng.get("sensible") or []:
        found[cat] = {"nivel": "fuerte", "palabras": [f"el motor {task.get('motor')} {cat}"]}
    if task.get("permission_mode") == "bypassPermissions":
        found["permisos totales"] = {"nivel": "fuerte", "palabras": ["bypassPermissions"]}
    return found


# ---- niveles de riesgo R0-R3 y vencimiento de los pedidos (t-vencimiento-aprobacion-030)
# El silencio nunca es consentimiento. Cada pedido de aprobacion nace con su
# nivel, su motivo y su vencimiento (hora de Caracas, segun el nivel). El
# runner revisa los pendientes en cada vuelta de la cola, cada 10 s mientras
# un motor trabaja y al arrancar; al vencer, la tarea pasa a necesita_decision
# y NO se ejecuta. Una aprobacion que llega despues no vale: se apunta como
# «tardia, descartada». La clasificacion vive en riesgos.json (editable).
RIESGOS_FILE = APP_DIR / "riesgos.json"
NIVELES_R = ("R0", "R1", "R2", "R3")
APR_LOG = OUTBOX / "aprobaciones-registro.jsonl"  # auditoria: una linea por evento, nunca se borra
APR_PEDIDOS = OUTBOX / "aprobaciones"             # el pedido tal cual (Growi lo reenvia por WhatsApp)
APR_CADA_S = 10                                   # mientras un motor trabaja, el pulso revisa cada 10 s
_APR_LOCK = threading.RLock()                     # vencer y aprobar nunca a la vez
_APR = {"t": 0.0, "arranque": time.time()}
_riesgos_cache = {"key": None, "d": None, "err": None}
_DIAS = ("lun", "mar", "mié", "jue", "vie", "sáb", "dom")
_VENCE_DEF_H = {"R1": 24, "R2": 2, "R3": 2}       # solo si riesgos.json no trae vence_h
_RESET_NEG = re.compile(r"(?:,\s*|\s)(?:pero|solo|sino|luego|despues|ademas|y luego|y despues)\b|,\s*y\b")
_RUTA_ABS = re.compile(r"(?<![\w])([a-z]:\\[^\s\"'«»<>|*?,;()]+)", re.I)
_VERBO_ESCRIBIR = re.compile(r"\b(?:escrib|guard|cre[ae]|copi|mueve|mover|modific|edit|actualiz|"
                             r"sobrescrib|reemplaz|instal|pon|deja|write|save|copy|move)\w*")
_VERBO_BORRAR = re.compile(r"\b(?:borr|elimin|delete|remove|rm\b|del\b)\w*")


def _tz_caracas():
    try:
        from zoneinfo import ZoneInfo
        return ZoneInfo("America/Caracas")
    except Exception:  # Windows sin tzdata: Venezuela es UTC-4 fijo (sin horario de verano) desde 2016
        return timezone(timedelta(hours=-4), "VET")


TZ_CARACAS = _tz_caracas()


def hora_caracas(ts):
    return datetime.fromtimestamp(ts, TZ_CARACAS).isoformat(timespec="seconds")


def hora_caracas_txt(ts):
    d = datetime.fromtimestamp(ts, TZ_CARACAS)
    return f"{_DIAS[d.weekday()]} {d:%d/%m} a las {d:%H:%M}"


def falta_txt(seg):
    if seg <= 0:
        return "ya venció"
    if seg < 60:
        return f"quedan {int(seg)} s"
    h, m = divmod(int(seg // 60), 60)
    return f"quedan {h} h {m:02d} min" if h else f"quedan {m} min"


def _dur_txt(seg):
    seg = int(round(seg))
    if seg % 3600 == 0:
        return f"{seg // 3600} h"
    if seg % 60 == 0:
        return f"{seg // 60} min"
    return f"{seg} s"


def _rango(nivel):
    return NIVELES_R.index(nivel) if nivel in NIVELES_R else 3


def cargar_riesgos():
    """(tabla, error). Se relee si el archivo cambia (sin reiniciar). Sin
    tabla legible, error: el que llama trata la tarea como R3 (fail-closed)."""
    try:
        st = RIESGOS_FILE.stat()
        key = (st.st_mtime_ns, st.st_size)
    except OSError as e:
        key, err = None, f"no encuentro {RIESGOS_FILE.name} ({e.strerror or e})"
        if _riesgos_cache["err"] != err:
            log(f"riesgos: {err}; TODA tarea se trata como R3 hasta que vuelva")
        _riesgos_cache.update(key=None, d=None, err=err)
        return None, err
    if key == _riesgos_cache["key"]:
        return _riesgos_cache["d"], _riesgos_cache["err"]
    d, err = None, None
    try:
        d = json.loads(RIESGOS_FILE.read_text(encoding="utf-8"))
        if not isinstance(d, dict) or not isinstance(d.get("tipos"), dict) or not d["tipos"]:
            raise ValueError("falta la lista «tipos»")
        for tid, t in d["tipos"].items():
            if not isinstance(t, dict) or t.get("nivel") not in NIVELES_R:
                raise ValueError(f"el tipo «{tid}» no tiene un nivel R0-R3")
            for s in t.get("senales") or []:
                re.compile(s)
    except (OSError, ValueError, re.error) as e:
        d, err = None, f"{RIESGOS_FILE.name} mal formado: {e}"
        log(f"riesgos: {err}; TODA tarea se trata como R3 hasta que se arregle")
    _riesgos_cache.update(key=key, d=d, err=err)
    return d, err


def _sin_acentos(text):
    import unicodedata
    t = unicodedata.normalize("NFKD", str(text or "").lower())
    return "".join(c for c in t if not unicodedata.combining(c))


def _frases(text):
    return [f for f in re.split(r"(?<=[.!?;])\s+|\n+", text) if f.strip()]


def _negada(frase, ini, negs):
    """True si antes del verbo, en la misma frase, hay una negacion que no se
    corta con «pero / solo / luego / , y». «No borres nada» no cuenta;
    «No toques nada, y borra viejo.txt» si."""
    antes = frase[:ini]
    ult = None
    for m in re.finditer(r"\b(?:" + "|".join(re.escape(n) for n in negs) + r")\b", antes):
        ult = m
    return bool(ult) and not _RESET_NEG.search(antes[ult.end():])


def _accion(tabla, tipo, origen, evidencia, nivel=None, ruta=None, usd=None, frase=None):
    t = (tabla.get("tipos") or {}).get(tipo) or {}
    return {"tipo": tipo, "nivel": nivel or t.get("nivel") or "R2",
            "nombre": t.get("nombre") or tipo.replace("_", " "), "origen": origen,
            "palabras": [str(evidencia)[:80]], "rutas": [str(ruta)] if ruta else [],
            "usd": usd if isinstance(usd, (int, float)) else None,
            "frases": [str(frase)[:400]] if frase else []}


def _ruta_r3(ruta, tabla):
    partes = re.split(r"[\\/]+", _sin_acentos(ruta))
    return any(str(r).lower() in partes or str(r).lower() in partes[-1:] for r in tabla.get("rutas_r3") or [])


def _dentro(ruta, cwd):
    try:
        r = os.path.normcase(os.path.abspath(ruta))
        c = os.path.normcase(os.path.abspath(cwd))
    except (TypeError, ValueError):
        return False
    return r == c or r.startswith(c.rstrip("\\/") + os.sep)


def _monto(frase):
    m = (re.search(r"\$\s?(\d+(?:[.,]\d+)?)", frase)
         or re.search(r"(\d+(?:[.,]\d+)?)\s*(?:usd|dolares|\$)", frase))
    if not m:
        return None
    try:
        return float(m.group(1).replace(",", "."))
    except ValueError:
        return None


def _de_declaradas(task, tabla):
    """Las acciones que la tarea declara: [{"tipo", "ruta"?, "usd"?, "recursivo"?}]."""
    out = []
    umbral = float(tabla.get("umbral_gasto_usd") or 0.5)
    for a in task.get("acciones") or []:
        tipo = str(a.get("tipo") or "").strip()
        ruta, usd = a.get("ruta"), a.get("usd")
        ev = "declarada por la tarea" + (f": {ruta}" if ruta else "") + (f": ${usd}" if usd is not None else "")
        fr = json.dumps(a, sort_keys=True, ensure_ascii=False)
        if ruta and tipo != "leer" and _ruta_r3(str(ruta), tabla):
            out.append(_accion(tabla, "tocar_credenciales", "declarada", ev, ruta=ruta, frase=fr))
            continue
        if tipo in ("escribir", "escribir_trabajo", "escribir_fuera") and ruta:
            tipo = "escribir_trabajo" if _dentro(str(ruta), task["cwd"]) else "escribir_fuera"
        elif tipo == "escribir":
            tipo = "escribir_fuera"  # sin ruta no se puede saber que es dentro
        if tipo == "borrar" and a.get("recursivo"):
            tipo = "borrar_recursivo"
        if tipo in ("gastar", "gastar_poco"):
            tipo = ("gastar_poco" if isinstance(usd, (int, float)) and 0 <= usd <= umbral else "gastar")
        if tipo not in (tabla.get("tipos") or {}):
            out.append(_accion(tabla, tipo or "desconocido", "declarada",
                               f"tipo «{tipo}» que no está en {RIESGOS_FILE.name}", nivel="R2", ruta=ruta, usd=usd,
                               frase=fr))
            continue
        out.append(_accion(tabla, tipo, "declarada", ev, ruta=ruta, usd=usd, frase=fr))
    return out


def _de_encargo(task, tabla):
    """Lo que se deduce del encargo, frase por frase: tipo por sus senales
    (verbo + objeto) y alcance por las rutas y cifras de esa misma frase."""
    out = []
    negs = tabla.get("negaciones") or ["no", "nunca", "sin"]
    umbral = float(tabla.get("umbral_gasto_usd") or 0.5)
    texto = _sin_acentos(" \n".join([task.get("prompt") or ""] + list(task.get("criterios") or [])))
    for frase in _frases(texto):
        for tipo, t in (tabla.get("tipos") or {}).items():
            for s in t.get("senales") or []:
                m = re.search(s, frase)
                if not m or _negada(frase, m.start(), negs):
                    continue
                tp = tipo
                n = _monto(frase) if tipo == "gastar" else None
                if n is not None and n <= umbral:
                    tp = "gastar_poco"
                rr = [r.rstrip(".:") for r in _RUTA_ABS.findall(frase)]
                out.append(_accion(tabla, tp, "encargo", m.group(0).strip(), ruta=rr[0] if rr else None, usd=n,
                                   frase=frase))
                break
        # Alcance: una ruta absoluta en la misma frase que un verbo de escribir o borrar.
        rutas = [r.rstrip(".:") for r in _RUTA_ABS.findall(frase)]
        if not rutas:
            continue
        vw, vb = _VERBO_ESCRIBIR.search(frase), _VERBO_BORRAR.search(frase)
        vw = vw if vw and not _negada(frase, vw.start(), negs) else None
        vb = vb if vb and not _negada(frase, vb.start(), negs) else None
        for r in rutas:
            if (vw or vb) and _ruta_r3(r, tabla):
                out.append(_accion(tabla, "tocar_credenciales", "encargo", r, ruta=r, frase=frase))
            elif vw and not _dentro(r, task["cwd"]):
                out.append(_accion(tabla, "escribir_fuera", "encargo", r, ruta=r, frase=frase))
    return out


def clasificar_riesgo(task):
    """{"nivel", "acciones": [...], "motivo", "tabla"}: el nivel R0-R3 del
    pedido (el mayor de sus acciones) y por que. Union de lo declarado, lo
    marcado como sensible y lo deducido del encargo: nunca menos que lo declarado."""
    tabla, err = cargar_riesgos()
    if tabla is None:
        a = {"tipo": "tabla_ilegible", "nivel": "R3", "nombre": "no pude leer la tabla de riesgos",
             "origen": "runner", "palabras": [err]}
        return {"nivel": "R3", "acciones": [a], "motivo": f"no pude leer la tabla de riesgos ({err}): "
                "por seguridad se trata como R3", "tabla": "ilegible"}
    acc = _de_declaradas(task, tabla)
    mapa = tabla.get("mapa_sensible") or {}
    for cat in task.get("sensible") or []:
        acc.append(_accion(tabla, mapa.get(cat, cat), "sensible", "la tarea lo marca como sensible"))
    eng = get_engine(task.get("motor") or "") or {}
    for cat in eng.get("sensible") or []:
        acc.append(_accion(tabla, mapa.get(cat, cat), "motor", f"el motor {task.get('motor')} {cat}"))
    if task.get("permission_mode") == "bypassPermissions":
        acc.append(_accion(tabla, "permisos_totales", "permisos", "bypassPermissions"))
    acc += _de_encargo(task, tabla)
    # Una por tipo (la primera evidencia de cada origen se suma)
    junto = {}
    for a in acc:
        j = junto.setdefault(a["tipo"], dict(a, palabras=[], rutas=[], frases=[], usd=None))
        if _rango(a["nivel"]) > _rango(j["nivel"]):
            j["nivel"] = a["nivel"]
        for p in a["palabras"]:
            if p not in j["palabras"] and len(j["palabras"]) < 4:
                j["palabras"].append(p)
        for campo in ("rutas", "frases"):
            for x in a.get(campo) or []:
                if x not in j[campo]:
                    j[campo].append(x)
        if isinstance(a.get("usd"), (int, float)):
            j["usd"] = max(j["usd"] or 0, a["usd"])
        if a["origen"] == "declarada":
            j["origen"] = "declarada"
    lista = sorted(junto.values(), key=lambda a: -_rango(a["nivel"]))
    nivel = lista[0]["nivel"] if lista else "R0"
    return {"nivel": nivel, "acciones": lista, "motivo": motivo_riesgo(lista), "tabla": RIESGOS_FILE.name}


def motivo_riesgo(acciones):
    if not acciones:
        return "nada que pida aprobación (R0: reversible y local)"
    de = {"declarada": "lo declara la tarea", "encargo": "deducido del encargo", "sensible": "la tarea lo marca",
          "motor": "lo marca el motor", "permisos": "permisos pedidos", "runner": "runner"}
    return "; ".join(f"{a['nombre']} ({a['nivel']}, {de.get(a['origen'], a['origen'])}: "
                     f"«{'», «'.join(a['palabras'][:2])}»)" for a in acciones)


def _desde(tabla, level):
    d = (tabla or {}).get("pregunta_desde") or {}
    v = d.get(level) or {"siempre": "R1", "delicado": "R2", "nunca": "R3"}[level]
    return v if v in NIVELES_R[1:] else "R1"


def _vence_prueba_s(nivel):
    """Temporizador de prueba: GROWI_BRIDGE_VENCE_PRUEBA="R2=60,R3=60" SOLO en
    una instancia aislada: share propia (GROWI_BRIDGE_SHARE) + mutex propio
    (GROWI_BRIDGE_MUTEX), que la app instalada nunca pone, y una share que no
    es la de la instalacion (%USERPROFILE%\\growi-bridge\\share). En la cola
    real se ignora siempre."""
    raw = os.environ.get("GROWI_BRIDGE_VENCE_PRUEBA")
    if not raw:
        return None
    try:
        instalada = (HOME_DIR / "growi-bridge" / "share").resolve()
        aislada = (bool(os.environ.get("GROWI_BRIDGE_SHARE")) and bool(os.environ.get("GROWI_BRIDGE_MUTEX"))
                   and SHARE.resolve() != instalada)
    except OSError:
        aislada = False
    if not aislada:
        if not _APR.get("aviso_prueba"):
            _APR["aviso_prueba"] = True
            log("aprobaciones: GROWI_BRIDGE_VENCE_PRUEBA ignorado: solo vale en una instancia de prueba aislada")
        return None
    for parte in raw.split(","):
        k, _s, v = parte.partition("=")
        if k.strip().upper() == nivel:
            try:
                return max(5, int(float(v)))
            except ValueError:
                return None
    return None


def vence_segundos(nivel, tabla=None):
    """Cuanto espera un pedido de ese nivel. Nunca infinito: entre 1 min y 7 dias."""
    p = _vence_prueba_s(nivel)
    if p:
        return p, True
    h = (((tabla or {}).get("niveles") or {}).get(nivel) or {}).get("vence_h")
    try:
        h = float(h)
    except (TypeError, ValueError):
        h = _VENCE_DEF_H.get(nivel, 2)
    return int(max(60, min(7 * 86400, h * 3600))), False


# ---- estimado de gasto ANTES de ejecutar (t-estimado-gasto-030). Los tres
# dineros nunca se mezclan: $ real (API) / $ equivalente Max (sesion de
# suscripcion: no es dinero real) / $0 local. La cuota restante de Max no
# tiene API publica: el estimado NO sabe si la tarea cabe en tu ventana y lo
# dice; nunca hay cuenta atras inventada.
UMBRAL_TAREA_DEF, UMBRAL_PLAN_DEF = 1.0, 5.0
RESERVA_SALIDA = {"respuesta corta": 800, "código": 6000, "documento largo": 12000}
LLAMADAS_POR_TAREA = 6  # un agente hace 5-10 llamadas; las siguientes leen de caché
REVISION_TOKENS = 3000
BREAKER_FALLOS, BREAKER_PAUSA_S = 3, 600
_BREAKER = {"seguidos": 0, "pausado": False, "desde": None, "motivo": None}
_ETIQUETA_EQUIV = "$ equivalente Max, no dinero real"


def umbrales_gasto():
    s = load_settings()
    def _f(k, d):
        try:
            v = float(s.get(k))
            return v if v > 0 else d
        except (TypeError, ValueError):
            return d
    return _f("umbral_tarea_usd", UMBRAL_TAREA_DEF), _f("umbral_plan_usd", UMBRAL_PLAN_DEF)


def _tipo_tarea(task):
    p = str(task.get("prompt") or "")
    if es_tarea_de_codigo(task):
        return "código"
    if len(p) > 1500 or re.search(r"\b(informe|documento|manual|art[ií]culo|propuesta|reporte)\b", p, re.I):
        return "documento largo"
    return "respuesta corta"


def _precio(modelo):
    pm = ((load_engines()[0].get("precios") or {}).get("por_millon") or {})
    m = str(modelo or "").lower()
    for k, v in pm.items():
        if m and (m == k.lower() or m in k.lower()):
            return k, v
    return None, None


def _dinero(task):
    motor = task.get("motor") or default_motor()
    modelo = str(task.get("modelo") or "")
    if motor in ("llama", "ollama") or modelo.startswith("ollama:"):
        return "local"
    if motor == "api" or modelo.startswith("api:"):
        return "real"
    if motor == "claude":
        return "real" if _claude_plan() == "api" else "equiv"
    return "equiv" if motor == "codex" else "otro"


def _historico_costes(motor, tipo=None, n_max=300):
    """Costos reales (cost_usd) de los .result.json de ese motor (y tipo, si
    el .task.json archivado deja saberlo). Nunca una tabla inventada."""
    out = []
    for f in sorted(RESULTS.glob("*.result.json"), key=lambda p: p.stat().st_mtime, reverse=True)[:n_max]:
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        c = d.get("cost_usd")
        if not isinstance(c, (int, float)) or c <= 0 or (d.get("motor") or "") != motor:
            continue
        if tipo:
            tf = DONE / f"{d.get('id')}.task.json"
            try:
                if tf.exists() and _tipo_tarea(json.loads(tf.read_text(encoding="utf-8"))) != tipo:
                    continue
            except (OSError, ValueError):
                pass
        out.append(float(c))
    return out


def estimar_gasto(task):
    """Antes de ejecutar: entrada contada del prompt real, reserva de salida
    por tipo, revision y peor caso (3 rondas), en los tres dineros."""
    motor = task.get("motor") or default_motor()
    eng = get_engine(motor) or {}
    try:
        prompt = prompt_de_tarea(task)
    except Exception:
        prompt = str(task.get("prompt") or "")
    n_in, como = _contar_tokens(eng, prompt) if eng else (len(prompt) // 3 + 1, "estimado (3 caracteres por token)")
    tipo = _tipo_tarea(task)
    salida = RESERVA_SALIDA[tipo]
    modelo = task.get("modelo") or (eng.get("modelo") or {}).get("por_defecto") or ("sonnet" if motor == "claude" else "")
    clave, p = _precio(modelo)
    dinero = _dinero(task)
    e = {"tokens_entrada": n_in, "como_se_conto": como, "tipo": tipo, "reserva_salida": salida, "motor": motor,
         "modelo": clave or modelo or None, "dinero": dinero, "llamadas_supuestas": LLAMADAS_POR_TAREA}
    if dinero == "local":
        una = rev = 0.0
    elif p:
        una = (n_in * p["entrada"] + n_in * (LLAMADAS_POR_TAREA - 1) * p.get("cache_lectura", p["entrada"])
               + salida * p["salida"]) / 1e6
        _kh, ph = _precio("haiku")
        rev = ((n_in + salida + REVISION_TOKENS) * ph["entrada"] + 800 * ph["salida"]) / 1e6 if ph else 0.0
    else:
        una = rev = None
    e.update(una_ronda=una, revision=rev, revision_nota="1 ronda con Hermes local ($0) y, si hace falta, Haiku",
             peor_caso=None if una is None else round(3 * (una + (rev or 0)), 4))
    hist = _historico_costes(motor, tipo) or _historico_costes(motor)
    if len(hist) >= 5:
        s = sorted(hist)
        e["historico"] = {"n": len(s), "medio": round(sum(s) / len(s), 4), "p10": round(s[len(s) // 10], 4),
                          "p90": round(s[min(len(s) - 1, len(s) * 9 // 10)], 4)}
        e["calibrado"] = True
    else:
        e["historico"] = {"n": len(hist)}
        e["calibrado"] = False
    e["rango"] = (None if una is None else
                  [round(e["historico"]["p10"], 2), round(max(e["historico"]["p90"], e["peor_caso"]), 2)]
                  if e["calibrado"] else [round(una * 0.5, 2), round(e["peor_caso"], 2)])
    def _tres(v):
        if v is None:
            return "sin precio para este modelo (no se inventa)"
        real = v if dinero == "real" else 0.0
        eq = v if dinero in ("equiv", "otro") else 0.0
        return f"${real:.2f} real, ${eq:.2f} equivalente Max, $0 local"
    e["texto"] = (f"Estimado ({tipo}, {motor}{' ' + str(e['modelo']) if e['modelo'] else ''}): entrada {n_in} tokens "
                  f"({como}), reserva de salida {salida} tokens. Una ronda: {_tres(una)}. Revisión: {_tres(rev)} "
                  f"({e['revision_nota']}). Peor caso, 3 rondas: {_tres(e['peor_caso'])}."
                  + (f" Rango real de tus tareas parecidas: ${e['rango'][0]:.2f}–${e['rango'][1]:.2f} "
                     f"({e['historico']['n']} resultados)." if e["calibrado"] and e["rango"] else
                     f" Sin histórico: estimado grueso, rango ${e['rango'][0]:.2f}–${e['rango'][1]:.2f}."
                     if e["rango"] else "")
                  + (f" ({_ETIQUETA_EQUIV}.)" if dinero == "equiv" else "")
                  + (" No sé si cabe en lo que te queda de Max: Anthropic no publica la cuota."
                     if dinero == "equiv" and motor == "claude" else ""))
    return e


def _gasto_pide_aprobacion(task, level):
    """Si el peor caso pasa del umbral, la tarea pide aprobación aunque el
    nivel sea «solo lo delicado» (con «Hazlo sin preguntar», no)."""
    if level == "nunca" or task.get("ollama_action"):
        return None, None
    est = estimar_gasto(task)
    tarea, _plan = umbrales_gasto()
    pc = est.get("peor_caso")
    if pc is not None and pc > tarea:
        return {"nivel": "R2", "tipo": "gasto_estimado", "nombre": f"gasto estimado alto (peor caso ${pc:.2f} > "
                                                                    f"umbral ${tarea:.2f})",
                "origen": "runner", "palabras": [f"${pc:.2f}", f"umbral ${tarea:.2f}"]}, est
    return None, est


def _tope_superado(task, result):
    """(gastado, tope) si la familia (con reintentos y rondas) pasó del
    presupuesto_max_usd de la tarea, o si Claude cortó por --max-budget-usd."""
    tope = task.get("presupuesto_max_usd")
    if not isinstance(tope, (int, float)) or tope <= 0:
        return None
    fam = load_family(task["raiz"]) or {}
    gastado = float(fam.get("costo_usd") or 0)
    corte = re.search(r"budget|presupuesto", f"{result.get('error') or ''} {result.get('result') or ''}", re.I)
    return (gastado, float(tope)) if gastado >= tope or (corte and result.get("status") != "ok") else None


def breaker_apuntar(result, transitorio):
    """3 fallos transitorios seguidos -> pausa (minimo 10 min) y aviso. Solo
    se reanuda a mano (breaker_reset)."""
    if result.get("status") == "ok":
        _BREAKER["seguidos"] = 0
        return
    if not transitorio:
        return
    _BREAKER["seguidos"] += 1
    if _BREAKER["seguidos"] >= BREAKER_FALLOS and not _BREAKER["pausado"]:
        _BREAKER.update(pausado=True, desde=time.time(),
                        motivo=f"{BREAKER_FALLOS} fallos transitorios seguidos (el último: "
                               f"{str(result.get('error') or result.get('status'))[:120]})")
        log(f"runner: circuit breaker: {_BREAKER['motivo']}; la cola se pausa (reanudar a mano)")
        _ui_call(lambda: toast("Cola en pausa: 3 fallos seguidos", ("tareas",)))


def breaker_reset(origen="a mano"):
    if not _BREAKER["pausado"]:
        return False, "La cola no estaba en pausa."
    falta = BREAKER_PAUSA_S - (time.time() - (_BREAKER["desde"] or 0))
    if falta > 0 and origen != "prueba":
        return False, f"La pausa mínima es de 10 min: faltan {int(falta // 60) + 1} min."
    _BREAKER.update(pausado=False, seguidos=0, desde=None, motivo=None)
    log(f"runner: circuit breaker reiniciado ({origen}); la cola sigue")
    return True, "La cola sigue."


def breaker_reset_ui():
    ok, msg = breaker_reset()
    messagebox.showinfo("Reanudar la cola", msg)


def costo_por_tarea_completada():
    """Por motor: todo lo gastado (con reintentos, rondas fallidas y
    revisiones, que suman en la tarea padre) / tareas que terminaron bien."""
    por = {}
    for f in RESULTS.glob("*.orquestacion.json"):
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(d, dict) or not d.get("raiz"):
            continue
        m = str(d.get("motor") or "?")
        x = por.setdefault(m, {"gastado": 0.0, "completadas": 0, "familias": 0})
        x["gastado"] += float(d.get("costo_usd") or 0)
        x["familias"] += 1
        x["completadas"] += 1 if d.get("estado") in ("aprobada", "sin_revision") else 0
    for x in por.values():
        x["por_completada"] = round(x["gastado"] / x["completadas"], 4) if x["completadas"] else None
        x["gastado"] = round(x["gastado"], 4)
    return por


# ---- politicas persistentes (t-politicas-persistentes-030)
# politicas.json (carpeta de Bridge, legible a mano): reglas por tipo de
# accion y carpeta, con su decision. Orden de Claude Code: deny > ask > allow
# > modo global (el guardrail). Solo persisten las POLITICAS; cada aprobacion
# concreta vale para un paso, su hash y su vencimiento. Un «permitir siempre»
# solo vale para R0-R1: R2 y R3 se preguntan siempre, por accion exacta.
# NINGUNA politica la crea una tarea ni el asistente: solo el usuario en la
# app. Una tarea que pide escribir politicas.json se rechaza, y si un motor
# lo cambia durante la tarea, la app lo devuelve a como estaba (y lo apunta).
POL_FILE = APP_DIR / "politicas.json"
POL_DECISIONES = (("allow", "Permitir siempre"), ("ask", "Preguntar siempre"), ("deny", "No permitir nunca"))
_POL = {"firma": None, "contenido": None, "cargado": False}
_POL_LOCK = threading.RLock()


def _pol_sha(b):
    return hashlib.sha256(b).hexdigest() if b is not None else None


def _pol_leer_bytes():
    try:
        return POL_FILE.read_bytes()
    except OSError:
        return None


def _pol_conocer():
    """La primera vez: lo que hay en disco es lo bueno (lo dejó el usuario)."""
    with _POL_LOCK:
        if not _POL["cargado"]:
            b = _pol_leer_bytes()
            _POL.update(firma=_pol_sha(b), contenido=b, cargado=True)


def politicas_leer():
    """(reglas, error). Sin archivo: [] (no hay reglas)."""
    _pol_conocer()
    b = _pol_leer_bytes()
    if b is None:
        return [], None
    try:
        d = json.loads(b.decode("utf-8"))
        reglas = d.get("reglas") if isinstance(d, dict) else None
        if not isinstance(reglas, list):
            raise ValueError("falta la lista «reglas»")
        ok = []
        for r in reglas:
            if isinstance(r, dict) and r.get("decision") in dict(POL_DECISIONES) and r.get("accion"):
                ok.append(r)
        return ok, None
    except (ValueError, UnicodeDecodeError) as e:
        return [], f"{POL_FILE.name} mal formado ({e})"


def politicas_guardar(reglas, quien):
    """SOLO desde la app (el usuario). Escribe y recuerda la firma buena."""
    d = {"_que_es": "Reglas permanentes de Growi Bridge (Ajustes → Permisos → Reglas permanentes). Las crea solo "
                    "el usuario en la app; una tarea o el asistente NUNCA. Orden: no permitir > preguntar > "
                    "permitir > el nivel de permisos. «Permitir siempre» solo vale para R0-R1.",
         "version": 1, "reglas": reglas}
    b = json.dumps(d, ensure_ascii=False, indent=1).encode("utf-8")
    with _POL_LOCK:
        tmp = POL_FILE.with_suffix(".tmp")
        tmp.write_bytes(b)
        os.replace(tmp, POL_FILE)
        _POL.update(firma=_pol_sha(b), contenido=b, cargado=True)
    log(f"políticas: guardadas {len(reglas)} regla(s) ({quien})")


def _pol_nivel(tipo):
    tabla, _e = cargar_riesgos()
    return ((tabla or {}).get("tipos") or {}).get(tipo, {}).get("nivel") or ("R0" if tipo == "*" else "R2")


def _pol_nombre(tipo):
    if tipo == "*":
        return "cualquier acción"
    tabla, _e = cargar_riesgos()
    return ((tabla or {}).get("tipos") or {}).get(tipo, {}).get("nombre") or tipo.replace("_", " ")


def politica_frase(r):
    dec = dict(POL_DECISIONES).get(r.get("decision"), r.get("decision"))
    lim = r.get("limite_usd")
    que = _pol_nombre(r.get("accion"))
    if isinstance(lim, (int, float)):
        que += (f" hasta ${lim:g}" if r.get("decision") == "allow" else f" de más de ${lim:g}")
    donde = f"en {r['carpeta']}" if r.get("carpeta") else "en cualquier carpeta"
    return f"{dec}: {que} {donde} ({_pol_nivel(r.get('accion'))})"


def politica_validar(r):
    """Motivo por el que una regla no se puede guardar, o None."""
    if r.get("decision") not in dict(POL_DECISIONES):
        return "elige qué hacer: permitir, preguntar o no permitir"
    tabla, _e = cargar_riesgos()
    if r.get("accion") != "*" and r.get("accion") not in ((tabla or {}).get("tipos") or {}):
        return "elige un tipo de acción de la lista"
    if r["decision"] == "allow" and (r.get("accion") == "*" or _rango(_pol_nivel(r["accion"])) >= 2):
        return ("«Permitir siempre» solo vale para lo reversible (R0-R1). Lo irreversible o externo (R2) y lo "
                "que nunca se hace sin ti (R3) se pregunta siempre, por acción exacta")
    lim = r.get("limite_usd")
    if lim is not None and (not isinstance(lim, (int, float)) or lim < 0):
        return "el límite es un monto en $ (p. ej. 0.5)"
    return None


def _pol_coincide(r, accion, task):
    if r.get("accion") not in ("*", accion["tipo"]):
        return False
    lim = r.get("limite_usd")
    if isinstance(lim, (int, float)):
        usd = accion.get("usd")
        if not isinstance(usd, (int, float)):
            return False
        if (r["decision"] == "allow" and usd > lim) or (r["decision"] != "allow" and usd <= lim):
            return False
    carp = str(r.get("carpeta") or "").strip()
    if not carp:
        return True
    import fnmatch
    rutas = accion.get("rutas") or [task.get("cwd") or ""]
    for ruta in rutas:
        if any(ch in carp for ch in "*?["):
            if fnmatch.fnmatch(os.path.normcase(os.path.abspath(ruta)), os.path.normcase(carp)):
                return True
        elif _dentro(ruta, carp):
            return True
    return False


def politica_decidir(accion, task):
    """(decision, regla) para UNA accion: deny > ask > allow; (None, None) = modo global."""
    reglas, _e = politicas_leer()
    hits = [r for r in reglas if _pol_coincide(r, accion, task)]
    for dec in ("deny", "ask", "allow"):
        for r in hits:
            if r["decision"] != dec:
                continue
            if dec == "allow" and _rango(accion["nivel"]) >= 2:
                log(f"políticas: «{politica_frase(r)}» no vale para {accion['nombre']} ({accion['nivel']}): "
                    "R2/R3 se preguntan siempre")
                continue
            return dec, r
    return None, None


def accion_hash(task, a):
    """La huella de la accion EXACTA (tipo, rutas, monto, frases donde sale,
    carpeta y motor): si cambia entre la aprobacion y la ejecucion, la
    aprobacion no vale (patron TrustLoop)."""
    base = {"tipo": a.get("tipo"), "rutas": sorted(os.path.normcase(str(x)) for x in a.get("rutas") or []),
            "usd": a.get("usd"), "frases": sorted(a.get("frases") or [])
            or [_sin_acentos(task.get("prompt") or "")[:4000]],
            "cwd": os.path.normcase(str(task.get("cwd") or "")), "motor": task.get("motor")}
    return hashlib.sha256(json.dumps(base, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:16]


def _quien(canal):
    nombre = str(load_settings().get("user_name") or "").strip() or "el usuario"
    return f"{nombre} en la app" if str(canal or "app") in ("app", "") else f"{nombre} por {canal}"


def _pol_evento(evento, **kw):
    """Una línea más en el registro de auditoría (el mismo de las aprobaciones)."""
    d = {"at": hora_caracas(time.time()), "evento": evento, **kw}
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        with open(APR_LOG, "a", encoding="utf-8") as f:
            f.write(json.dumps(d, ensure_ascii=False) + "\n")
    except OSError as e:
        log(f"políticas: no se pudo escribir el registro ({e})")


_POL_INTENTO_RE = re.compile(r"politicas\.json")


def _pol_intento(task):
    """True si la tarea pide escribir/borrar politicas.json (o lo declara)."""
    for a in task.get("acciones") or []:
        if "politicas.json" in _sin_acentos(str(a.get("ruta") or "")) and a.get("tipo") != "leer":
            return True
    texto = _sin_acentos(" \n".join([task.get("prompt") or ""] + [str(c) for c in task.get("criterios") or []]))
    for frase in _frases(texto):
        if _POL_INTENTO_RE.search(frase) and (_VERBO_ESCRIBIR.search(frase) or _VERBO_BORRAR.search(frase)
                                              or re.search(r"\b(?:anad|agreg|cambi|quit|permit|regla)\w*", frase)):
            return True
    return False


def _pol_vigilar(task):
    """Tras correr un motor: si politicas.json cambió sin pasar por la app, se
    devuelve a como estaba y se apunta (una tarea nunca crea políticas)."""
    _pol_conocer()
    with _POL_LOCK:
        b = _pol_leer_bytes()
        if _pol_sha(b) == _POL["firma"]:
            return False
        try:
            if _POL["contenido"] is None:
                POL_FILE.unlink()
            else:
                tmp = POL_FILE.with_suffix(".tmp")
                tmp.write_bytes(_POL["contenido"])
                os.replace(tmp, POL_FILE)
            hecho = "devuelto a como estaba"
        except OSError as e:
            hecho = f"NO se pudo devolver ({e})"
    log(f"políticas [{task.get('id')}]: la tarea cambió {POL_FILE.name} sin pasar por la app: {hecho}. Una tarea "
        "nunca crea políticas")
    _pol_evento("politicas_cambio_rechazado", tarea=task.get("id"), raiz=task.get("raiz"), motor=task.get("motor"),
                quien=f"la tarea {task.get('id')} ({task.get('motor')})", desde="motor", resultado=hecho)
    return True


def politicas_auditoria(n=40):
    """Las últimas decisiones del registro, en palabras."""
    try:
        lineas = APR_LOG.read_text(encoding="utf-8").splitlines()[-400:]
    except OSError:
        return []
    out = []
    for x in reversed(lineas):
        try:
            d = json.loads(x)
        except ValueError:
            continue
        ev = d.get("evento")
        cuando = str(d.get("at") or "")[5:16].replace("T", " ")
        if ev in ("politica_allow", "politica_deny", "politica_ask"):
            txt = (f"{cuando}, {d.get('tarea')}: {d.get('accion')} → {d.get('decision_txt')} por la regla "
                   f"«{d.get('regla_frase')}» (puesta por {d.get('regla_quien')})")
        elif ev in ("aprobada", "rechazada"):
            txt = (f"{cuando}, {d.get('quien') or d.get('canal')} {'aprobó' if ev == 'aprobada' else 'rechazó'} "
                   f"{d.get('approval_id')} ({d.get('nivel')}) desde {d.get('canal') or 'app'}; vio: "
                   f"«{str(d.get('motivo') or '')[:140]}»; política: {d.get('politica') or 'ninguna (nivel de permisos)'}")
        elif ev == "pedido":
            txt = (f"{cuando}, pedido {d.get('approval_id')} ({d.get('nivel')}) para {d.get('tarea')}: "
                   f"{str(d.get('motivo') or '')[:160]}")
        elif ev == "aprobacion_invalidada":
            txt = (f"{cuando}, {d.get('tarea')}: la aprobación {d.get('approval_id')} ya no vale — la acción cambió "
                   f"({d.get('hash_aprobado')} → {d.get('hash_ahora')}); se vuelve a pedir")
        elif ev in ("politicas_intento", "politicas_cambio_rechazado"):
            txt = f"{cuando}, {d.get('quien')}: intentó cambiar las políticas → {d.get('resultado')}"
        elif ev in ("regla_creada", "regla_editada", "regla_revocada"):
            verbo = {"regla_creada": "creó", "regla_editada": "editó", "regla_revocada": "revocó"}[ev]
            txt = f"{cuando}, {d.get('quien')} {verbo} la regla «{d.get('regla_frase')}»"
        else:
            txt = f"{cuando}, {ev}: {d.get('tarea') or ''} {str(d.get('resultado') or d.get('motivo') or '')[:120]}"
        out.append((ev, txt))
        if len(out) >= n:
            break
    return out


# ---- editor (Ajustes → Permisos y seguridad → «Reglas permanentes»)
_POLUI = {"top": None}


def politica_guardar_ui(regla, rid=None):
    """Crea (rid None) o edita una regla, como el usuario en la app. (ok, mensaje)."""
    regla = dict(regla)
    if regla.get("limite_usd") in ("", None):
        regla["limite_usd"] = None
    else:
        try:
            regla["limite_usd"] = float(str(regla["limite_usd"]).replace(",", ".").replace("$", ""))
        except ValueError:
            return False, "el límite es un monto en $ (p. ej. 0.5)"
    regla["carpeta"] = str(regla.get("carpeta") or "").strip()
    why = politica_validar(regla)
    if why:
        return False, why
    reglas, _e = politicas_leer()
    quien = _quien("app")
    regla["nivel"] = _pol_nivel(regla["accion"])
    if rid:
        vieja = next((r for r in reglas if r.get("id") == rid), None)
        if vieja is None:
            return False, "esa regla ya no está"
        vieja.update(regla, editada_por=quien, editada_en=_now_iso())
        r = vieja
        ev = "regla_editada"
    else:
        r = dict(regla, id="r-" + secrets.token_hex(3), creada_por=quien, creada_en=_now_iso())
        reglas.append(r)
        ev = "regla_creada"
    politicas_guardar(reglas, quien)
    _pol_evento(ev, quien=quien, desde="app", regla_id=r["id"], regla_frase=politica_frase(r))
    return True, politica_frase(r)


def politica_revocar_ui(rid, confirmar=True):
    reglas, _e = politicas_leer()
    r = next((x for x in reglas if x.get("id") == rid), None)
    if r is None:
        return False
    if confirmar and not messagebox.askyesno("Revocar regla", f"¿Quito esta regla?\n\n{politica_frase(r)}"):
        return False
    quien = _quien("app")
    politicas_guardar([x for x in reglas if x.get("id") != rid], quien)
    _pol_evento("regla_revocada", quien=quien, desde="app", regla_id=rid, regla_frase=politica_frase(r))
    return True


def politicas_ui():
    """La ventana del editor (CTk con respaldo clásico)."""
    top = _POLUI.get("top")
    if top is not None:
        try:
            top.deiconify()
            top.lift()
            _politicas_render()
            return top
        except tk.TclError:
            pass
    top = tk.Toplevel(_root)
    top.title("Reglas permanentes")
    top.configure(bg=THEME["bg"])
    top.geometry(f"{S(720)}x{S(640)}")
    page = _scrollable(top)
    k = None
    if _ctk_wanted():
        try:
            k = _KitCtk(page)
        except Exception as e:
            log(f"políticas: CustomTkinter no disponible ({type(e).__name__}: {e}); editor clásico")
    k = k or _KitTk(page)
    _POLUI.update(top=top, kit=k, editando=None)
    card = k.section("Reglas permanentes", "Qué hacer siempre con un tipo de acción en una carpeta. Manda «No "
                                           "permitir» sobre «Preguntar», y «Preguntar» sobre «Permitir»; lo que no "
                                           "cubre ninguna regla sigue tu nivel de permisos. Las crea solo tú, aquí.")
    tabla, _e = cargar_riesgos()
    tipos = [("*", "cualquier acción")] + [(t, f"{v.get('nombre')} ({v.get('nivel')})")
                                            for t, v in ((tabla or {}).get("tipos") or {}).items()]
    _POLUI["tipos"] = tipos
    f = k.frame(card)
    f.pack(fill="x", padx=16, pady=(4, 2))
    k.label(f, "Qué", muted=True, wrap=0).pack(side="left", padx=(0, 8))
    cb = ttk.Combobox(f, values=[lab for _t, lab in tipos], state="readonly", width=44, font=(FONT, 10))
    cb.current(0)
    cb.pack(side="left")
    _POLUI["accion"] = cb
    f = k.frame(card)
    f.pack(fill="x", padx=16, pady=2)
    k.label(f, "Dónde", muted=True, wrap=0).pack(side="left", padx=(0, 8))
    _POLUI["carpeta"] = k.entry(f, width=46)
    _POLUI["carpeta"].pack(side="left")
    k.button(f, "Elegir…", lambda: _pol_elegir_carpeta()).pack(side="left", padx=(6, 0))
    f = k.frame(card)
    f.pack(fill="x", padx=16, pady=2)
    k.label(f, "Límite $ (solo gastar)", muted=True, wrap=0).pack(side="left", padx=(0, 8))
    _POLUI["limite"] = k.entry(f, width=8)
    _POLUI["limite"].pack(side="left")
    f = k.frame(card)
    f.pack(fill="x", padx=16, pady=2)
    _POLUI["decision"] = k.segmented(f, list(POL_DECISIONES), lambda _v: None)
    _POLUI["decision"].pack(side="left")
    f = k.frame(card)
    f.pack(fill="x", padx=16, pady=(6, 2))
    _POLUI["guardar"] = k.button(f, "Añadir regla", _pol_guardar_click, accent=True)
    _POLUI["guardar"].pack(side="left")
    k.button(f, "Limpiar", _pol_limpiar).pack(side="left", padx=(8, 0))
    _POLUI["msg"] = k.label(card, "", wrap=600)
    _POLUI["msg"].pack(fill="x", padx=16, pady=(4, 2))
    _POLUI["lista"] = k.frame(card)
    _POLUI["lista"].pack(fill="x", padx=16, pady=(4, 12))
    aud = k.section("Registro de decisiones", f"Quién aprobó qué, cuándo, desde dónde, qué vio y qué regla aplicó "
                                              f"(se guarda en {APR_LOG.name}, nunca se borra).")
    _POLUI["audit"] = k.frame(aud)
    _POLUI["audit"].pack(fill="x", padx=16, pady=(4, 12))
    _politicas_render()
    return top


def _pol_elegir_carpeta():
    d = filedialog.askdirectory(title="Carpeta de la regla")
    if d:
        _POLUI["carpeta"].delete(0, "end")
        _POLUI["carpeta"].insert(0, os.path.normpath(d))


def _pol_limpiar():
    _POLUI["editando"] = None
    _POLUI["accion"].current(0)
    _POLUI["carpeta"].delete(0, "end")
    _POLUI["limite"].delete(0, "end")
    try:
        _POLUI["guardar"].configure(text="Añadir regla")
    except Exception:
        pass


def _pol_guardar_click():
    k = _POLUI["kit"]
    i = _POLUI["accion"].current()
    regla = {"accion": _POLUI["tipos"][max(i, 0)][0], "carpeta": _POLUI["carpeta"].get(),
             "limite_usd": _POLUI["limite"].get().strip() or None, "decision": k.seg_get(_POLUI["decision"])}
    ok, msg = politica_guardar_ui(regla, _POLUI.get("editando"))
    k.set_label(_POLUI["msg"], text=("Guardada: " + msg) if ok else f"No se guardó: {msg}.",
                color="green_text" if ok else "red")
    if ok:
        _pol_limpiar()
    _politicas_render()


def _pol_editar(rid):
    reglas, _e = politicas_leer()
    r = next((x for x in reglas if x.get("id") == rid), None)
    if r is None:
        return
    _POLUI["editando"] = rid
    ids = [t for t, _l in _POLUI["tipos"]]
    _POLUI["accion"].current(ids.index(r["accion"]) if r["accion"] in ids else 0)
    _POLUI["carpeta"].delete(0, "end")
    _POLUI["carpeta"].insert(0, r.get("carpeta") or "")
    _POLUI["limite"].delete(0, "end")
    if r.get("limite_usd") is not None:
        _POLUI["limite"].insert(0, f"{r['limite_usd']:g}")
    seg = _POLUI["decision"]
    if hasattr(seg, "_keys"):  # CTkSegmentedButton: se pone por su texto
        seg.set(dict(POL_DECISIONES)[r["decision"]])
    else:
        seg.var.set(r["decision"])
    try:
        _POLUI["guardar"].configure(text="Guardar cambios")
    except Exception:
        pass
    _POLUI["kit"].set_label(_POLUI["msg"], text=f"Editando: {politica_frase(r)}", color="blue")


def _politicas_render():
    k = _POLUI.get("kit")
    if k is None:
        return
    box = _POLUI["lista"]
    for ch in box.winfo_children():
        ch.destroy()
    reglas, err = politicas_leer()
    if err:
        k.label(box, f"No pude leer las reglas: {err}. Mientras, no se aplica ninguna.", color="red").pack(anchor="w")
    if not reglas and not err:
        k.label(box, "Sin reglas: todo sigue tu nivel de permisos.", muted=True).pack(anchor="w")
    for r in reglas:
        fila = k.frame(box)
        fila.pack(fill="x", pady=2)
        k.label(fila, politica_frase(r), wrap=430,
                color={"allow": "green_text", "deny": "red", "ask": "orange_text"}.get(r["decision"])).pack(
            side="left", anchor="w")
        k.button(fila, "Revocar", lambda i=r["id"]: (politica_revocar_ui(i), _politicas_render())).pack(
            side="right", padx=(6, 0))
        k.button(fila, "Editar", lambda i=r["id"]: _pol_editar(i)).pack(side="right")
    ab = _POLUI["audit"]
    for ch in ab.winfo_children():
        ch.destroy()
    filas = politicas_auditoria(25)
    if not filas:
        k.label(ab, "Todavía no hay decisiones apuntadas.", muted=True).pack(anchor="w")
    for ev, txt in filas:
        k.label(ab, txt, wrap=640, muted=ev not in ("politica_deny", "politicas_intento",
                                                    "politicas_cambio_rechazado", "aprobacion_invalidada"),
                color="red" if ev in ("politica_deny", "politicas_intento", "politicas_cambio_rechazado",
                                      "aprobacion_invalidada") else None).pack(anchor="w", pady=1)


def _approval_needed(task):
    """None si puede correr; si no, {"nivel", "acciones", "motivo", ...} con UN
    paso (cada paso sensible se aprueba aparte, con su approval_id), o
    {"denegada": True, ...} si una política (o la regla dura) lo prohíbe."""
    tabla, _err = cargar_riesgos()
    cls = clasificar_riesgo(task)
    level = guardrail_level()
    desde = _rango(_desde(tabla, level))
    pol = (tabla or {}).get("politicas") or {}
    if _pol_intento(task):  # regla dura: una tarea nunca escribe politicas.json
        a = {"tipo": "cambiar_politicas", "nivel": "R3", "nombre": f"cambiar {POL_FILE.name}", "origen": "encargo",
             "palabras": [POL_FILE.name], "rutas": [str(POL_FILE)], "frases": [], "usd": None}
        motivo = (f"una tarea no puede crear ni cambiar políticas ({POL_FILE.name}): solo tú, en la app "
                  "(Ajustes → Permisos → Reglas permanentes)")
        _pol_evento("politicas_intento", tarea=task.get("id"), raiz=task.get("raiz"),
                    quien=f"la tarea {task.get('id')} (canal {task.get('canal') or 'app'})", desde="tarea",
                    resultado="rechazada antes de empezar", vio=str(task.get("prompt") or "")[:300])
        log(f"políticas [{task.get('id')}]: RECHAZADA: pide cambiar {POL_FILE.name}; solo el usuario crea políticas")
        return {"denegada": True, "nivel": "R3", "acciones": [a], "motivo": motivo, "regla": None}
    need = []
    for a in cls["acciones"]:
        a["hash"] = accion_hash(task, a)
        dec, regla = politica_decidir(a, task)
        if dec:
            _pol_evento(f"politica_{dec}", tarea=task.get("id"), raiz=task.get("raiz"), accion=a["nombre"],
                        nivel=a["nivel"], hash=a["hash"], decision_txt=dict(POL_DECISIONES)[dec],
                        regla_id=regla.get("id"), regla_frase=politica_frase(regla),
                        regla_quien=regla.get("editada_por") or regla.get("creada_por"))
        if dec == "deny":
            log(f"políticas [{task.get('id')}]: {a['nombre']} lo prohíbe «{politica_frase(regla)}»: no se ejecuta")
            return {"denegada": True, "nivel": a["nivel"], "acciones": [a], "regla": regla,
                    "motivo": f"{a['nombre']}: lo prohíbe tu regla «{politica_frase(regla)}»"}
        if dec == "allow":
            log(f"políticas [{task.get('id')}]: {a['nombre']} permitido por «{politica_frase(regla)}»")
            continue
        if dec == "ask":
            need.append(dict(a, politica=politica_frase(regla)))
            continue
        if (a["nivel"] != "R0" and _rango(a["nivel"]) >= desde
                and not (a["nivel"] == "R1" and pol.get(a["tipo"]) == "permitir")):
            need.append(a)
    gasto, est = _gasto_pide_aprobacion(task, level)  # t-estimado-gasto-030
    if est is not None:
        task["_estimado"] = est
    if gasto:
        gasto.setdefault("hash", accion_hash(task, gasto))
        need.append(gasto)
    if not need:
        return None
    ap = _APPROVED.setdefault(task["raiz"], {"tipos": set(), "hashes": {}, "por_tipo": {}})
    pend, cubiertos = [], []
    for a in need:
        if a["nivel"] == "R1" and a["tipo"] in ap["tipos"] and not a.get("politica"):
            continue  # R1: una vez por tipo y por tarea
        aid = ap["hashes"].get(a["hash"])
        if aid:  # la aprobación de ESTE paso exacto (se gasta solo si la tarea arranca)
            cubiertos.append((a, aid))
            continue
        viejo = ap["por_tipo"].pop(a["tipo"], None)
        if viejo and viejo["hash"] != a["hash"]:
            ap["hashes"].pop(viejo["hash"], None)
            log(f"runner [{task['id']}]: la aprobación {viejo['aid']} ya no vale: «{a['nombre']}» cambió desde que "
                f"la aprobaste (hash {viejo['hash']} → {a['hash']}); se vuelve a pedir")
            _pol_evento("aprobacion_invalidada", tarea=task.get("id"), raiz=task.get("raiz"),
                        approval_id=viejo["aid"], accion=a["nombre"], hash_aprobado=viejo["hash"],
                        hash_ahora=a["hash"], resultado="se vuelve a pedir")
        pend.append(a)
    if not pend:
        for a, aid in cubiertos:  # todos los pasos aprobados: cada aprobación vale una vez
            ap["hashes"].pop(a["hash"], None)
            ap["por_tipo"].pop(a["tipo"], None)
            log(f"runner [{task['id']}]: usa tu aprobación {aid} para «{a['nombre']}» (hash {a['hash']}); vale una vez")
        return None
    pend.sort(key=lambda a: -_rango(a["nivel"]))
    paso = pend[0]
    resto = (f" (paso 1 de {len(pend)}: cada paso sensible se aprueba aparte; luego vienen "
             f"{', '.join(a['nombre'] for a in pend[1:])})" if len(pend) > 1 else "")
    return {"nivel": paso["nivel"], "acciones": [paso], "motivo": motivo_riesgo([paso]) + (
                f"; regla «{paso['politica']}»" if paso.get("politica") else "") + resto + (
                f". {est['texto']}" if est and paso is gasto else ""),
            "nivel_tarea": cls["nivel"], "tabla": cls["tabla"], "permisos": level,
            "estimado": est, "pasos_pendientes": len(pend)}


def _apr_evento(ev, row, **kw):
    """Una linea en el registro auditable (nunca se reescribe ni se borra)."""
    d = {"at": hora_caracas(time.time()), "evento": ev, "run_id": row.get("raiz"),
         **{k: row.get(k) for k in ("approval_id", "tarea", "raiz", "nivel", "motivo", "pedido",
                                    "creado_en", "vence_en", "estado", "resultado")}, **kw}
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        with open(APR_LOG, "a", encoding="utf-8") as f:
            f.write(json.dumps(d, ensure_ascii=False) + "\n")
    except OSError as e:
        log(f"aprobaciones: no se pudo escribir el registro ({e})")


def aprobaciones_init():
    _cola("""CREATE TABLE IF NOT EXISTS aprobaciones (
        approval_id TEXT PRIMARY KEY, tarea TEXT, raiz TEXT, archivo TEXT, nivel TEXT,
        acciones TEXT, motivo TEXT, pedido TEXT, canal TEXT, creado_en TEXT, creado_ts REAL,
        vence_en TEXT, vence_ts REAL, prueba INTEGER DEFAULT 0, estado TEXT NOT NULL,
        resultado TEXT, resuelto_en TEXT, resuelto_por TEXT, tardias TEXT)""")
    _cola("CREATE INDEX IF NOT EXISTS aprobaciones_estado ON aprobaciones(estado)")


def apr_get(approval_id):
    r = _cola("SELECT * FROM aprobaciones WHERE approval_id=?", (approval_id,), fetch=True)
    return r[0] if r else None


def apr_de_raiz(raiz):
    r = _cola("SELECT * FROM aprobaciones WHERE raiz=? ORDER BY creado_ts DESC LIMIT 1", (raiz,), fetch=True)
    return r[0] if r else None


def apr_pendientes():
    return _cola("SELECT * FROM aprobaciones WHERE estado='pendiente' ORDER BY vence_ts", fetch=True)


def _apr_set(approval_id, **kw):
    cols = ", ".join(f"{k}=?" for k in kw)
    _cola(f"UPDATE aprobaciones SET {cols} WHERE approval_id=?", (*kw.values(), approval_id))


def _apr_info(row):
    """Lo que la familia y la tarjeta necesitan saber del pedido."""
    return {k: row.get(k) for k in ("approval_id", "nivel", "motivo", "creado_en", "vence_en",
                                    "vence_ts", "estado", "resultado", "canal")} | {
        "vence_txt": hora_caracas_txt(row["vence_ts"]) if row.get("vence_ts") else None,
        "espera_txt": _dur_txt((row.get("vence_ts") or 0) - (row.get("creado_ts") or 0)),
        "prueba": bool(row.get("prueba"))}


def texto_pedido(row, nivel_nombre=""):
    """El pedido tal como lo leeria Leandro (WhatsApp o la app)."""
    r3 = row.get("nivel") == "R3"
    return (f"Growi necesita tu sí para «{row.get('raiz')}» ({row.get('nivel')}"
            + (f": {nivel_nombre}" if nivel_nombre else "") + ").\n"
            f"Quiere: {row.get('motivo')}.\n"
            f"Vence el {hora_caracas_txt(row['vence_ts'])} (hora de Caracas). Si no respondes, NO se hace.\n"
            + ("Esto solo se aprueba en la app, con el PC delante: por aquí no se puede."
               if r3 else f"Código del pedido: {row.get('approval_id')}"))


def _apr_pedido_archivo(row, nivel_nombre=""):
    try:
        APR_PEDIDOS.mkdir(parents=True, exist_ok=True)
        d = dict(_apr_info(row), tarea=row.get("tarea"), raiz=row.get("raiz"), pedido=row.get("pedido"),
                 acciones=json.loads(row.get("acciones") or "[]"), nivel_nombre=nivel_nombre,
                 se_puede_por_whatsapp=row.get("nivel") != "R3", texto_whatsapp=texto_pedido(row, nivel_nombre),
                 actualizado=hora_caracas(time.time()))
        p = APR_PEDIDOS / f"{row['approval_id']}.pedido.json"
        tmp = p.with_suffix(".tmp")
        tmp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmp, p)
    except (OSError, ValueError) as e:
        log(f"aprobaciones: no se pudo escribir el pedido de {row.get('approval_id')} ({e})")


def _nivel_nombre(nivel):
    tabla, _e = cargar_riesgos()
    return (((tabla or {}).get("niveles") or {}).get(nivel) or {}).get("nombre") or ""


def _apr_nuevo(task, need, archivo, creado_ts=None, nota=None):
    """Crea el pedido (nuevo approval_id y nuevo vencimiento, siempre)."""
    tabla, _e = cargar_riesgos()
    ahora = time.time()
    creado_ts = creado_ts or ahora
    secs, prueba = vence_segundos(need["nivel"], tabla)
    aid = f"apr-{_safe_id_part(task['raiz'])[:40]}-{datetime.fromtimestamp(ahora):%Y%m%d%H%M%S}-{random.randint(0, 0xffff):04x}"
    row = {"approval_id": aid, "tarea": task["id"], "raiz": task["raiz"], "archivo": str(archivo),
           "nivel": need["nivel"], "acciones": json.dumps(need["acciones"], ensure_ascii=False),
           "motivo": need["motivo"][:600], "pedido": re.sub(r"\s+", " ", task.get("prompt") or "")[:300],
           "canal": str(task.get("canal") or "app"), "creado_en": hora_caracas(creado_ts),
           "creado_ts": creado_ts, "vence_en": hora_caracas(creado_ts + secs), "vence_ts": creado_ts + secs,
           "prueba": 1 if prueba else 0, "estado": "pendiente", "resultado": None, "tardias": "[]"}
    _cola(f"INSERT INTO aprobaciones ({', '.join(row)}) VALUES ({', '.join('?' * len(row))})",
          tuple(row.values()))
    _apr_pedido_archivo(row, _nivel_nombre(row["nivel"]))
    _apr_evento("pedido", row, espera=_dur_txt(secs), prueba=bool(prueba), nota=nota)
    return row


def _safe_id_part(s):
    return re.sub(r"[^\w.-]", "-", str(s or "tarea"))


def _plan_de(task, need, row=None):
    acc = {a["nombre"]: {"nivel": "fuerte", "palabras": a["palabras"], "riesgo": a["nivel"],
                         "tipo": a["tipo"], "origen": a["origen"]} for a in need["acciones"]}
    plan = {"motor": task["motor"], "modelo": task.get("modelo"), "cwd": task["cwd"],
            "permisos": {"permission_mode": task.get("permission_mode"),
                         "allowed_tools": task.get("allowed_tools")},
            "prompt": task["prompt"][:3000], "criterios": criterios_txt(task),
            "acciones": acc, "nivel": guardrail_level(), "tarea": task["id"],
            "riesgo": {"nivel": need["nivel"], "nombre": _nivel_nombre(need["nivel"]), "motivo": need["motivo"]},
            **_auto_fields(task.get("enrutado"))}
    if row:
        plan["aprobacion"] = _apr_info(row)
    return plan


def _park_for_approval(task_file, task, need):
    """Aparca la tarea con su pedido. Devuelve (estado de cola, archivo).
    R3 pedida por un canal remoto: denegada al instante (no se aparca)."""
    with _APR_LOCK:
        canal = str(task.get("canal") or "app").lower()
        if need["nivel"] == "R3" and canal not in ("app", ""):
            return _denegar_remota_nueva(task_file, task, need, canal)
        WAITING.mkdir(parents=True, exist_ok=True)
        dest = WAITING / task_file.name
        shutil.move(str(task_file), str(dest))
        row = _apr_nuevo(task, need, dest)
        ck_aprobacion(task, row["approval_id"])
        plan = _plan_de(task, need, row)
        _family_update(task["raiz"], estado="esperando_aprobacion", plan=plan,
                       archivo_espera=dest.name, motor=task["motor"], tarea=task["id"],
                       ronda=task.get("ronda", 0), solo_si_falta_encargo=task["prompt"][:2000],
                       solo_si_falta_criterios=criterios_txt(task), fase=task.get("fase"),
                       aprobacion=_apr_info(row), motivo_decision=None,
                       **_auto_fields(task.get("enrutado")))
        log(f"runner [{task['id']}]: espera tu aprobación ({need['nivel']}: {need['motivo'][:160]}); "
            f"pedido {row['approval_id']}, vence el {hora_caracas_txt(row['vence_ts'])} (Caracas); "
            "no se ejecuta sola")
        return "esperando_aprobacion", dest


def _pol_denegar(task_file, task, cid, need):
    """Una política (o la regla dura) lo prohíbe: no se ejecuta, sin reintentos."""
    DONE.mkdir(parents=True, exist_ok=True)
    dest = DONE / task_file.name
    shutil.move(str(task_file), str(dest))
    motivo = need["motivo"]
    rep = f"{NO_CONFIRMADO} No se ejecutó: {motivo}."
    res = _error_result(task["id"], motivo)
    res.update(raiz=task["raiz"], estado="fallida", reporte=rep, reintentos=0, motor=task.get("motor"),
               no_ejecutado=True, politica=(need.get("regla") or {}).get("id"))
    _write_result(res)
    _family_update(task["raiz"], estado="fallida", reporte=rep, error=motivo, motor=task.get("motor"),
                   tarea=task["id"], solo_si_falta_encargo=str(task.get("prompt") or "")[:2000])
    cola_set(cid, estado="fallida", archivo=str(dest), motivo=f"definitivo, sin reintentos: {motivo}"[:300])
    log(f"runner [{task['id']}]: no se ejecuta: {motivo}")


def _cerrar_sin_ejecutar(raiz, tarea, src, motivo, reporte, info, estado_apr):
    """La tarea pasa a necesita_decision SIN ejecutarse: su encargo va a done/."""
    DONE.mkdir(parents=True, exist_ok=True)
    dest = DONE / Path(src).name
    if Path(src).exists():
        os.replace(src, dest)
    res = _error_result(tarea, motivo)
    res.update(raiz=raiz, estado="necesita_decision", reporte=reporte, reintentos=0,
               no_ejecutado=True, aprobacion=dict(info, estado=estado_apr))
    _write_result(res)
    ck_cerrar_espera(tarea, "necesita_decision", f"aprobación {estado_apr}: no se ejecutó nada")
    cola_set(tarea, estado="necesita_decision", archivo=str(dest), motivo=motivo, proximo_intento=None)
    _family_update(raiz, estado="necesita_decision", archivo_espera=None, reporte=reporte,
                   motivo_decision=motivo, en_curso=None, aprobacion=dict(info, estado=estado_apr))
    return dest


def _denegar_remota_nueva(task_file, task, need, canal):
    row = _apr_nuevo(task, need, task_file, nota=f"pedido por canal remoto ({canal})")
    motivo = f"R3 pedida por canal remoto ({canal}): denegada al instante; R3 solo se aprueba en la app"
    rep = (f"{NO_CONFIRMADO} Se pidió por {canal} algo de nivel R3 ({need['motivo'][:300]}). R3 nunca se "
           "hace sin ti delante: solo se aprueba en la app. Se denegó al instante y no se ejecutó nada.")
    _apr_set(row["approval_id"], estado="denegada", resultado="R3 por canal remoto: denegada, no se ejecutó nada",
             resuelto_en=hora_caracas(time.time()), resuelto_por=canal)
    row = apr_get(row["approval_id"]) or row
    dest = _cerrar_sin_ejecutar(task["raiz"], task["id"], task_file, motivo, rep, _apr_info(row), "denegada")
    _family_update(task["raiz"], plan=_plan_de(task, need, row), motor=task["motor"], tarea=task["id"],
                   solo_si_falta_encargo=task["prompt"][:2000])
    _apr_pedido_archivo(row, _nivel_nombre("R3"))
    _apr_evento("denegada_remota", row, canal=canal)
    log(f"runner [{task['id']}]: {motivo}")
    return "necesita_decision", dest


def _vencer(row, ahora):
    """Vencimiento = denegar. Nada se ejecuta; queda en el registro."""
    nivel, raiz, tarea = row["nivel"], row["raiz"], row["tarea"]
    espera = _dur_txt(row["vence_ts"] - row["creado_ts"])
    motivo = f"aprobacion vencida ({nivel}, {espera} sin respuesta)"
    apagon = row["vence_ts"] < _APR["arranque"]
    src = Path(row["archivo"] or "")
    if not src.is_file():
        src = WAITING / src.name
    por_que = (row.get("motivo") or "")[:300]
    rep = (f"{NO_CONFIRMADO} Se intentó «{(row.get('pedido') or '')[:200]}», pero faltó tu aprobación: el "
           f"pedido {row['approval_id']} ({nivel}: {por_que}) se hizo el {hora_caracas_txt(row['creado_ts'])} "
           f"y venció el {hora_caracas_txt(row['vence_ts'])} "
           "(hora de Caracas) sin respuesta. No se ejecutó nada: el encargo nunca llegó al motor."
           + (" Venció mientras el runner estaba apagado; se aplicó al arrancar." if apagon else "")
           + " Para hacerla, vuelve a encolarla (Tareas → Volver a la cola): saldrá un pedido nuevo con su "
           "propio vencimiento; esta aprobación ya no vale.")
    resultado = "vencida: no se ejecutó nada" + (" (aplicado al arrancar, tras un apagado)" if apagon else "")
    _apr_set(row["approval_id"], estado="vencida", resultado=resultado, resuelto_en=hora_caracas(ahora),
             resuelto_por="runner (vencimiento)")
    row = apr_get(row["approval_id"]) or dict(row, estado="vencida", resultado=resultado)
    _cerrar_sin_ejecutar(raiz, tarea, src, motivo, rep, _apr_info(row), "vencida")
    _apr_pedido_archivo(row, _nivel_nombre(nivel))
    _apr_evento("vencida", row, al_arrancar=apagon, archivo_intacto_en="done/")
    log(f"aprobaciones: {row['approval_id']} ({tarea}) {motivo}; pasa a necesita decisión sin ejecutarse"
        + (" (venció con el runner apagado)" if apagon else ""))


def aprobaciones_vencer(ahora=None):
    """Aplica los vencimientos que ya cayeron. Lo llama el runner en cada
    vuelta, el pulso cada 10 s y el arranque. Devuelve cuantos vencio."""
    ahora = time.time() if ahora is None else ahora
    n = 0
    with _APR_LOCK:
        _APR["t"] = time.time()
        for r in _cola("SELECT * FROM aprobaciones WHERE estado='pendiente' AND vence_ts <= ?",
                       (ahora,), fetch=True):
            try:
                _vencer(r, ahora)
                n += 1
            except Exception as e:
                log(f"aprobaciones: no se pudo vencer {r.get('approval_id')}: {type(e).__name__}: {e}")
    return n


def aprobaciones_adoptar():
    """Al arrancar: toda tarea en esperando/ tiene que tener un pedido con
    vencimiento. Las que esperaban de antes de esta version reciben uno que
    cuenta desde que llegaron (la hora del archivo): ninguna espera es infinita."""
    vivos = {Path(r["archivo"] or "").name for r in apr_pendientes()}
    n = 0
    for p in sorted(WAITING.glob("*.task.json")):
        if p.name in vivos:
            continue
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
            task, err = validate_task(data)
        except Exception as e:
            task, err = None, str(e)
        if task is None:
            tid = _cola_id(p, {})
            task = {"id": tid, "raiz": tid, "prompt": "", "cwd": str(INBOX), "motor": None}
        need = _approval_needed(dict(task)) or {"nivel": "R2", "acciones": [], "motivo":
                                                "esperaba de antes del vencimiento; sin clasificar"}
        row = _apr_nuevo(task, need, p, creado_ts=p.stat().st_mtime,
                         nota="adoptada al arrancar: ya esperaba sin vencimiento")
        fam = load_family(task["raiz"]) or {}
        plan = dict(fam.get("plan") or _plan_de(task, need), aprobacion=_apr_info(row),
                    riesgo={"nivel": need["nivel"], "nombre": _nivel_nombre(need["nivel"]),
                            "motivo": need["motivo"]})
        _family_update(task["raiz"], estado="esperando_aprobacion", plan=plan, archivo_espera=p.name,
                       aprobacion=_apr_info(row), tarea=task["id"])
        cola_set(task["id"], estado="esperando_aprobacion", archivo=str(p))
        n += 1
    if n:
        log(f"aprobaciones: {n} tarea(s) que ya esperaban reciben su pedido con vencimiento")
    return n


def _apr_tardia(row, decision, canal):
    tard = []
    try:
        tard = json.loads(row.get("tardias") or "[]")
    except ValueError:
        pass
    tard.append({"at": hora_caracas(time.time()), "decision": decision, "canal": canal})
    _apr_set(row["approval_id"], tardias=json.dumps(tard, ensure_ascii=False))
    _apr_evento("tardia_descartada", dict(row, resultado="tardía, descartada: no se ejecutó nada"),
                decision=decision, canal=canal)
    _family_update(row["raiz"], aprobacion_tardia={"at": hora_caracas(time.time()), "decision": decision,
                                                    "canal": canal, "approval_id": row["approval_id"]})
    log(f"aprobaciones: {decision} de {row['approval_id']} llegó tarde ({row['estado']}): "
        "tardía, descartada; no se ejecuta nada")


def decidir_aprobacion(approval_id=None, decision="aprobar", canal="app", raiz=None):
    """La UNICA entrada para aprobar o rechazar un pedido (app o, mas adelante,
    un canal remoto). (hecho, mensaje). Comprueba el vencimiento ANTES de
    nada: lo que llega tarde se apunta y se descarta."""
    canal = str(canal or "app").lower()
    with _APR_LOCK:
        row = apr_get(approval_id) if approval_id else apr_de_raiz(raiz) if raiz else None
        if row is None:
            return False, "no encuentro ese pedido de aprobación"
        ahora = time.time()
        if row["estado"] == "pendiente" and ahora >= row["vence_ts"]:
            _vencer(row, ahora)
            row = apr_get(row["approval_id"]) or row
        if row["estado"] != "pendiente":
            _apr_tardia(row, decision, canal)
            if row["estado"] == "vencida":
                return False, (f"Llegó tarde: ese pedido venció el {hora_caracas_txt(row['vence_ts'])} "
                               "(hora de Caracas). Se apuntó como «tardía, descartada» y no se ejecutó nada. "
                               "Para hacerla, vuelve a encolarla: saldrá un pedido nuevo.")
            return False, f"ese pedido ya está resuelto ({row['estado']}); no se hizo nada más"
        if row["nivel"] == "R3" and canal != "app":
            return _denegar_remota(row, canal)
        name = Path(row["archivo"] or "").name
        src = WAITING / name
        if not name or not src.is_file():
            return False, "esa tarea ya no está esperando"
        if decision == "aprobar":
            try:
                acc = json.loads(row.get("acciones") or "[]")
            except ValueError:
                acc = []
            ap = _APPROVED.setdefault(row["raiz"], {"tipos": set(), "hashes": {}, "por_tipo": {}})
            ap["tipos"].update(a["tipo"] for a in acc if a.get("nivel") == "R1" and not a.get("politica"))
            for a in acc:
                if a.get("hash"):
                    ap["hashes"][a["hash"]] = row["approval_id"]
                    ap["por_tipo"][a["tipo"]] = {"hash": a["hash"], "aid": row["approval_id"]}
            dest = TASKS / src.name
            shutil.move(str(src), str(dest))
            t = time.time() - 5
            os.utime(dest, (t, t))
            cola_registrar(dest)
            _apr_set(row["approval_id"], estado="aprobada", resultado="aprobada: vuelve a la cola",
                     resuelto_en=hora_caracas(ahora), resuelto_por=canal)
            row = apr_get(row["approval_id"]) or row
            _family_update(row["raiz"], estado="pendiente", archivo_espera=None, aprobada_por_usuario=_now_iso(),
                           aprobacion=_apr_info(row))
            _apr_pedido_archivo(row, _nivel_nombre(row["nivel"]))
            _apr_evento("aprobada", row, canal=canal, quien=_quien(canal), desde=canal,
                        hashes=[a.get("hash") for a in acc],
                        politica="; ".join(a["politica"] for a in acc if a.get("politica")) or None)
            log(f"tareas: aprobaste {row['raiz']} ({row['approval_id']}, {row['nivel']}); vuelve a la cola")
            return True, "aprobada; vuelve a la cola"
        DONE.mkdir(parents=True, exist_ok=True)
        shutil.move(str(src), str(DONE / src.name))
        res = _error_result(row["tarea"], "rechazada por el usuario antes de empezar")
        res.update(raiz=row["raiz"], estado="rechazada", reporte="No se hizo nada: la rechazaste antes de empezar.",
                   reintentos=0)
        _write_result(res)
        cola_set(row["tarea"], estado="fallida", archivo=str(DONE / src.name),
                 motivo="rechazada por el usuario (definitivo, sin reintentos)")
        ck_cerrar_espera(row["tarea"], "fallida", "rechazada por ti antes de empezar")
        _apr_set(row["approval_id"], estado="rechazada", resultado="rechazada: no se hizo nada",
                 resuelto_en=hora_caracas(ahora), resuelto_por=canal)
        row = apr_get(row["approval_id"]) or row
        _family_update(row["raiz"], estado="rechazada", archivo_espera=None,
                       reporte="No se hizo nada: la rechazaste antes de empezar.", aprobacion=_apr_info(row))
        _apr_pedido_archivo(row, _nivel_nombre(row["nivel"]))
        _apr_evento("rechazada", row, canal=canal, quien=_quien(canal), desde=canal)
        log(f"tareas: rechazaste {row['raiz']}")
        return True, "rechazada"


def _denegar_remota(row, canal):
    motivo = f"R3 pedida por canal remoto ({canal}): denegada al instante; R3 solo se aprueba en la app"
    rep = (f"{NO_CONFIRMADO} Llegó por {canal} una respuesta a un pedido R3 ({(row.get('motivo') or '')[:300]}). "
           "R3 nunca se hace sin ti delante: solo se aprueba en la app. Se denegó al instante y no se ejecutó nada.")
    _apr_set(row["approval_id"], estado="denegada", resultado="R3 por canal remoto: denegada, no se ejecutó nada",
             resuelto_en=hora_caracas(time.time()), resuelto_por=canal)
    row = apr_get(row["approval_id"]) or row
    src = WAITING / Path(row["archivo"] or "").name
    _cerrar_sin_ejecutar(row["raiz"], row["tarea"], src, motivo, rep, _apr_info(row), "denegada")
    _apr_pedido_archivo(row, _nivel_nombre("R3"))
    _apr_evento("denegada_remota", row, canal=canal)
    log(f"aprobaciones: {row['approval_id']}: {motivo}")
    return False, motivo


def _apr_de_familia(raiz):
    fam = load_family(raiz) or {}
    return ((fam.get("plan") or {}).get("aprobacion") or fam.get("aprobacion") or {}).get("approval_id")


def approve_waiting(raiz, approval_id=None, canal="app"):
    """Clic en Aprobar: la tarea vuelve a la cola (si el pedido no vencio)."""
    return decidir_aprobacion(approval_id or _apr_de_familia(raiz), "aprobar", canal, raiz=raiz)


def reject_waiting(raiz, approval_id=None, canal="app"):
    return decidir_aprobacion(approval_id or _apr_de_familia(raiz), "rechazar", canal, raiz=raiz)


# ---- revision automatica
_FILE_RE = re.compile(r"(?<![\w.-])((?:[A-Za-z]:[\\/])?[\w.\\/-]*\w\.[A-Za-z][A-Za-z0-9]{0,7})(?![\w])")
_MARK_RE = re.compile(r"\"([^\"\n]{1,120})\"|“([^”\n]{1,120})”|«([^»\n]{1,120})»|`([^`\n]{1,120})`|'([^'\n]{2,120})'")
_SKIP_DIRS = {".git", "node_modules", "__pycache__", ".venv", "venv", "processing", "done", "esperando"}


def _iso_ts(iso):
    try:
        return datetime.fromisoformat(iso).timestamp()
    except (TypeError, ValueError):
        return time.time()


def _touched_files(cwd, since_ts, limit=40, max_entries=20000, max_s=3.0):
    """Archivos modificados dentro de cwd mientras corria la tarea."""
    skip = {str(p).lower() for p in (TASKS, RESULTS, SESSIONS_DIR)}
    out, n, t0, stack = [], 0, time.time(), [str(cwd)]
    while stack and n < max_entries and time.time() - t0 < max_s:
        d = stack.pop()
        try:
            it = os.scandir(d)
        except OSError:
            continue
        with it:
            for e in it:
                n += 1
                try:
                    if e.is_dir(follow_symlinks=False):
                        if (e.name not in _SKIP_DIRS and not e.name.startswith(".")
                                and str(Path(e.path)).lower() not in skip):
                            stack.append(e.path)
                    elif e.is_file(follow_symlinks=False) and e.stat().st_mtime >= since_ts:
                        out.append(e.path)
                except OSError:
                    continue
    out.sort(key=lambda p: os.path.getmtime(p) if os.path.exists(p) else 0, reverse=True)
    return out[:limit]


def _file_facts(path):
    p = Path(path)
    if not p.is_file():
        return {"existe": False}
    size = p.stat().st_size
    facts = {"existe": True, "bytes": size, "lineas": None}
    if size <= 5_000_000:
        try:
            data = p.read_bytes()
            facts["lineas"] = data.count(b"\n") + (1 if data and not data.endswith(b"\n") else 0)
        except OSError:
            pass
    return facts


def _read_text(path, limit=2_000_000):
    try:
        p = Path(path)
        if p.stat().st_size > limit:
            return ""
        return p.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def _resolve_mentioned(tok, cwd, touched):
    p = Path(tok.replace("\\", "/"))
    cand = p if p.is_absolute() else Path(cwd) / p
    try:
        cand = cand.resolve()
    except OSError:
        pass
    if not cand.exists():
        same = [t for t in touched if Path(t).name.lower() == p.name.lower()]
        if same:
            cand = Path(same[0])
    if not _inside_any(cand, load_folders()):
        return None
    return cand


def _check_criterion(crit, cwd, touched, text):
    """Comprueba un criterio contra los archivos reales cuando se puede
    (existe, numero de lineas, marcadores entre comillas). None si no hay
    nada que comprobar a maquina (lo decide la revision del modelo)."""
    low = crit.lower()
    toks = list(dict.fromkeys(m.group(1).rstrip(".") for m in _FILE_RE.finditer(crit)))
    marks = [next(g for g in m.groups() if g) for m in _MARK_RE.finditer(crit)]
    marks = [m for m in marks if m not in toks and not _FILE_RE.fullmatch(m)]
    textual = (re.search(r"\b(respuesta|responde|menciona|dice|nombra|explica|resumen|texto)\b", low)
               and not re.search(r"\b(archivo|fichero|carpeta|existe|l[ií]neas)\b", low))
    if textual:
        toks = []
    if not toks and not marks:
        return None
    oks, fails = [], []
    negate = re.search(r"\bno\s+(?:debe\s+)?(?:existe|existir|est[aá]|quede)|\b(?:borrad|eliminad)[oa]s?\b", low)
    mlines = re.search(r"(m[aá]s\s+de|mayor\s+(?:a|que)|al\s+menos|como\s+m[ií]nimo|m[ií]nimo|>=|>)\s*(\d+)\s*l[ií]neas", low)
    pool = []
    for tok in toks:
        p = _resolve_mentioned(tok, cwd, touched)
        if p is None:
            fails.append(f"{tok}: está fuera de las carpetas permitidas, no lo puedo comprobar")
            continue
        f = _file_facts(p)
        if negate:
            (fails if f["existe"] else oks).append(
                f"{p} todavía existe" if f["existe"] else f"{p} no existe (comprobado)")
            continue
        if not f["existe"]:
            fails.append(f"el archivo {tok} no existe (busqué en {p})")
            continue
        pool.append(p)
        oks.append(f"{p} existe ({f['lineas']} líneas, {f['bytes']} bytes)")
        if mlines and f["lineas"] is not None:
            n = int(mlines.group(2))
            strict = not re.search(r"al\s+menos|m[ií]nimo|>=", mlines.group(1))
            good = f["lineas"] > n if strict else f["lineas"] >= n
            (oks if good else fails).append(
                f"{p} tiene {f['lineas']} líneas ({'más de' if strict else 'al menos'} {n}: "
                f"{'sí' if good else 'no'})")
    if marks:
        if textual:
            sources = [("el resultado", text)]
        else:
            files = pool or [Path(t) for t in touched if Path(t).is_file()][:20]
            sources = [(str(f), _read_text(f)) for f in files]
        for mk in marks:
            where = [name for name, body in sources if mk.lower() in body.lower()]
            (oks if where else fails).append(
                f"marcador '{mk}' presente en {where[0]}" if where
                else f"falta el marcador '{mk}'" + (" en el resultado" if textual else " en los archivos"))
    return {"criterio": crit, "resultado": "no cumple" if fails else "cumple",
            "detalle": oks + fails, "falla": fails}


# ---- criterios tipados + rubrica + doble juez (t-criterios-tipados-030)
# Los criterios de un task pueden ser frases (las juzga el juez) u objetos
# tipados (los comprueba el codigo, $0). EL JUEZ OPINA; LOS HECHOS MANDAN: si
# un check tipado falla no hay aprobacion, diga lo que diga el juez.
CRIT_TIPOS = ("existe", "lineas", "contiene", "compila", "comando")
_CRIT_CAMPOS = {
    "existe": {"tipo", "archivo", "descripcion"},
    "lineas": {"tipo", "archivo", "min", "max", "descripcion"},
    "contiene": {"tipo", "archivo", "texto", "descripcion"},
    "compila": {"tipo", "archivo", "comando", "timeout_s", "descripcion"},
    "comando": {"tipo", "comando", "texto", "exit", "timeout_s", "descripcion"},
}
_COMPILA_EXT = {".py": "python", ".pyw": "python", ".js": "node", ".mjs": "node", ".cjs": "node"}
CMD_PERMITIDOS_DEF = ("python", "py", "node", "npm", "npx", "pnpm", "yarn", "pytest", "git",
                      "dotnet", "cargo", "go", "tsc")
_GIT_LECTURA = ("status", "diff", "log", "show", "rev-parse", "ls-files", "grep")
_SHELL_META = re.compile(r"[&|<>^;`\r\n]|\$\(|%[A-Za-z_][\w]*%")
CHECK_TIMEOUT_DEF_S, CHECK_TIMEOUT_MAX_S = 60, 600
_PYC_SNIPPET = "import py_compile,sys;py_compile.compile(sys.argv[1],cfile=sys.argv[2],doraise=True)"
RUBRICA_DIMS = ("completitud", "correccion", "no_regresion", "evidencia")
RUBRICA_ESQUEMA = {
    "type": "object",
    "properties": {
        "puntuacion": {"type": "object", "properties": {
            k: {"type": "integer", "minimum": 1, "maximum": 5} for k in RUBRICA_DIMS},
            "required": list(RUBRICA_DIMS), "additionalProperties": False},
        "aprobado": {"type": "string", "enum": ["si", "no"]},
        "que_falta": {"type": "array", "items": {"type": "object", "properties": {
            "falta": {"type": "string"}, "arreglo": {"type": "string"}},
            "required": ["falta", "arreglo"], "additionalProperties": False}},
        "evidencia": {"type": "array", "items": {"type": "string"}}},
    "required": ["puntuacion", "aprobado", "que_falta", "evidencia"],
    "additionalProperties": False}
CALIB_BLOQUE = 30
CALIB_FILE = OUTBOX / "calibracion-revisor.json"
REV_LOG = OUTBOX / "revisiones-registro.jsonl"


def _rev_cfg():
    d = load_engines()[0]
    return (d.get("revision") or {}) if isinstance(d, dict) else {}


def _cmd_permitidos():
    v = _rev_cfg().get("comandos_permitidos")
    return tuple(str(x).lower() for x in v) if isinstance(v, list) and v else CMD_PERMITIDOS_DEF


def _partir_comando_check(cmd):
    """Un solo programa con sus argumentos, SIN shell. (args, None) o (None, motivo)."""
    if not isinstance(cmd, str) or not cmd.strip():
        return None, "comando vacío"
    if len(cmd) > 400:
        return None, "comando demasiado largo (máximo 400 caracteres)"
    if _SHELL_META.search(cmd):
        return None, ("sin shell: no se aceptan & | < > ^ ; ` $( ni %VARIABLES% "
                      "(un solo programa con sus argumentos)")
    try:
        import shlex
        args = shlex.split(cmd, posix=False)
    except ValueError as e:
        return None, f"comando mal escrito ({e})"
    args = [a[1:-1] if len(a) >= 2 and a[0] == a[-1] == '"' else a for a in args]
    if not args:
        return None, "comando vacío"
    prog = re.sub(r"\.(exe|cmd|bat)$", "", Path(args[0]).name.lower())
    if prog not in _cmd_permitidos():
        return None, (f"el programa '{args[0]}' no está entre los comandos permitidos "
                      f"({', '.join(_cmd_permitidos())}; se cambian en engines.json → revision)")
    if prog == "git" and (len(args) < 2 or args[1].lower() not in _GIT_LECTURA):
        return None, f"git solo para leer ({', '.join(_GIT_LECTURA)})"
    return args, None


def _ruta_criterio(archivo, cwd):
    p = Path(str(archivo).replace("/", os.sep)).expanduser()
    p = p if p.is_absolute() else Path(cwd) / p
    try:
        return p.resolve()
    except OSError:
        return p


def validar_criterio_tipado(c, cwd):
    """(criterio normalizado, None) o (None, motivo claro). Nada se interpreta a ojo."""
    if not isinstance(c, dict):
        return None, "no es un objeto"
    tipo = c.get("tipo")
    if tipo not in CRIT_TIPOS:
        return None, f"tipo desconocido {tipo!r} (usa: {', '.join(CRIT_TIPOS)})"
    extra = sorted(set(c) - _CRIT_CAMPOS[tipo])
    if extra:
        return None, (f"{tipo}: campo desconocido {', '.join(map(repr, extra))} "
                      f"(admite: {', '.join(sorted(_CRIT_CAMPOS[tipo] - {'tipo'}))})")
    out = {"tipo": tipo}
    if "descripcion" in c:
        if not isinstance(c["descripcion"], str) or len(c["descripcion"]) > 300:
            return None, f"{tipo}: descripcion debe ser un texto corto"
        out["descripcion"] = c["descripcion"].strip()
    arch = c.get("archivo")
    if (tipo in ("existe", "lineas", "contiene") or (tipo == "compila" and "comando" not in c)) \
            and (not isinstance(arch, str) or not arch.strip()):
        return None, f'{tipo}: falta la ruta del archivo ("archivo": "...")'
    if arch is not None:
        if not isinstance(arch, str) or not arch.strip() or len(arch) > 400:
            return None, f"{tipo}: archivo debe ser una ruta (texto de hasta 400 caracteres)"
        p = _ruta_criterio(arch.strip(), cwd)
        if not _inside_any(p, load_folders()):
            return None, f"{tipo}: {arch} queda fuera de las carpetas permitidas ({p})"
        out["archivo"] = arch.strip()
    if tipo == "lineas":
        for k in ("min", "max"):
            if k in c and (not isinstance(c[k], int) or isinstance(c[k], bool) or c[k] < 0):
                return None, f"lineas: {k} debe ser un número entero mayor o igual que 0"
        if "min" not in c and "max" not in c:
            return None, "lineas: falta min o max"
        if "min" in c and "max" in c and c["min"] > c["max"]:
            return None, "lineas: min es mayor que max"
        out.update({k: c[k] for k in ("min", "max") if k in c})
    if tipo == "contiene" or (tipo == "comando" and "texto" in c):
        t = c.get("texto")
        if not isinstance(t, str) or not t or len(t) > 500:
            return None, f"{tipo}: texto debe ser el marcador exacto (de 1 a 500 caracteres)"
        out["texto"] = t
    if "comando" in c:
        _args, err = _partir_comando_check(c["comando"])
        if err:
            return None, f"{tipo}: {err}"
        out["comando"] = c["comando"].strip()
    if tipo == "compila" and "comando" not in out:
        ext = Path(out["archivo"]).suffix.lower()
        if ext not in _COMPILA_EXT:
            return None, (f"compila: no sé compilar '{ext or out['archivo']}' sin un comando "
                          '(añade "comando": "...", p. ej. "npm run build")')
    if tipo == "comando":
        ex = c.get("exit", 0)
        if ex is not None and (not isinstance(ex, int) or isinstance(ex, bool)):
            return None, "comando: exit debe ser un número entero o null"
        if ex is None and "texto" not in out:
            return None, 'comando: con "exit": null hace falta "texto" (lo que debe salir)'
        out["exit"] = ex
    if "timeout_s" in c:
        v = c["timeout_s"]
        if not isinstance(v, int) or isinstance(v, bool) or not 1 <= v <= CHECK_TIMEOUT_MAX_S:
            return None, f"{tipo}: timeout_s debe ser un entero de 1 a {CHECK_TIMEOUT_MAX_S}"
        out["timeout_s"] = v
    return out, None


def separar_criterios(raw, cwd):
    """criterios del task -> (frases, tipados, None) o (.., .., error claro)."""
    if isinstance(raw, (str, dict)):
        raw = [raw]
    if raw is None:
        raw = []
    if not isinstance(raw, list) or not all(isinstance(c, (str, dict)) for c in raw):
        return [], [], ("criterios debe ser una lista de frases u objetos tipados "
                        f'{{"tipo": {"|".join(CRIT_TIPOS)}, ...}}')
    frases, tipados = [], []
    for i, c in enumerate(raw):
        if isinstance(c, str):
            if c.strip():
                frases.append(c.strip()[:500])
            continue
        n, err = validar_criterio_tipado(c, cwd)
        if err:
            return [], [], f"criterios[{i}] (tipado) mal formado: {err}"
        tipados.append(n)
    if len(tipados) > 20:
        return [], [], "demasiados criterios tipados (máximo 20)"
    return frases[:20], tipados, None


def criterio_txt(c):
    """Un criterio (frase o tipado) en palabras, para la ventana y el juez."""
    if isinstance(c, str):
        return c
    t, a = c.get("tipo"), c.get("archivo")
    if t == "existe":
        s = f"{a} existe"
    elif t == "lineas":
        if "min" in c and "max" in c:
            s = f"{a} tiene entre {c['min']} y {c['max']} líneas"
        elif "min" in c:
            s = f"{a} tiene al menos {c['min']} líneas"
        else:
            s = f"{a} tiene como mucho {c['max']} líneas"
    elif t == "contiene":
        s = f"{a} contiene «{c.get('texto', '')[:80]}»"
    elif t == "compila":
        s = f"{a} compila" + (f" ({c['comando']})" if c.get("comando") else "") if a else \
            f"«{c.get('comando')}» compila (sale con exit 0)"
    else:
        ex = c.get("exit", 0)
        s = f"«{c.get('comando')}»" + (f" sale con exit {ex}" if ex is not None else "") + (
            (" y" if ex is not None else "") + f" su salida contiene «{c['texto'][:60]}»" if c.get("texto") else "")
    return f"[{t}] {s}" + (f" — {c['descripcion']}" if c.get("descripcion") else "")


def criterios_txt(task):
    return list(task.get("criterios") or []) + [criterio_txt(c) for c in task.get("criterios_tipados") or []]


def _python_exe():
    exe = Path(sys.executable)
    if exe.name.lower() == "pythonw.exe" and exe.with_name("python.exe").exists():
        return str(exe.with_name("python.exe"))
    return str(exe)


def _correr_check(args, cwd, timeout_s):
    """(exit, salida, segundos, error): sin shell, oculto y con tope de tiempo.
    El boton Parar lo corta (queda en _RUN['proc'] mientras corre)."""
    t0 = time.time()
    exe = shutil.which(args[0]) or args[0]
    env = dict(os.environ, NO_PROXY="127.0.0.1,localhost", no_proxy="127.0.0.1,localhost",
               PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
    try:
        p = subprocess.Popen([exe] + list(args[1:]), cwd=str(cwd), stdout=subprocess.PIPE,
                             stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, env=env, **_oculto())
    except OSError as e:
        return None, "", round(time.time() - t0, 2), f"no se pudo lanzar {args[0]} ({e})"
    prev = _RUN.get("proc")
    _RUN["proc"] = p
    try:
        try:
            out, _e = p.communicate(timeout=timeout_s)
        except subprocess.TimeoutExpired:
            _kill_tree(p)
            try:
                out, _e = p.communicate(timeout=5)
            except Exception:
                out = b""
            return None, (out or b"").decode("utf-8", "replace"), round(time.time() - t0, 2), \
                f"no terminó en {timeout_s} s (se cortó)"
    finally:
        _RUN["proc"] = prev
    if _RUN.get("stop"):
        return None, (out or b"").decode("utf-8", "replace"), round(time.time() - t0, 2), "parado por el usuario"
    return p.returncode, (out or b"").decode("utf-8", "replace"), round(time.time() - t0, 2), None


def _check_tipado(c, cwd):
    """Comprueba un criterio tipado con codigo contra los archivos reales ($0)."""
    tipo, ok, oks, fails = c["tipo"], True, [], []
    ev = {"tipo": tipo}
    p = f = None
    if c.get("archivo"):
        p = _ruta_criterio(c["archivo"], cwd)
        ev["archivo"] = str(p)
        if not _inside_any(p, load_folders()):
            fails.append(f"{p}: fuera de las carpetas permitidas, no lo compruebo")
        else:
            f = _file_facts(p)
            ev["existe"] = f["existe"]
            if not f["existe"]:
                fails.append(f"el archivo {p} no existe (comprobado)")
            else:
                ev.update(bytes=f["bytes"], lineas_reales=f["lineas"])
    if not fails and tipo == "existe":
        oks.append(f"{p} existe ({f['lineas']} líneas, {f['bytes']} bytes)")
    elif not fails and tipo == "lineas":
        n = f["lineas"]
        if n is None:
            fails.append(f"{p}: no pude contar sus líneas (más de 5 MB)")
        else:
            lo, hi = c.get("min"), c.get("max")
            good = (lo is None or n >= lo) and (hi is None or n <= hi)
            pedido = (f"entre {lo} y {hi}" if lo is not None and hi is not None
                      else f"al menos {lo}" if lo is not None else f"como mucho {hi}")
            (oks if good else fails).append(f"{p} tiene {n} líneas reales (pedido: {pedido}): "
                                            f"{'sí' if good else 'no'}")
            ev.update(min=lo, max=hi)
    elif not fails and tipo == "contiene":
        body = _read_text(p, limit=5_000_000)
        if not body and (f or {}).get("bytes"):
            fails.append(f"{p}: no lo pude leer como texto (o pasa de 5 MB)")
        else:
            i = body.find(c["texto"])
            ev.update(texto=c["texto"], encontrado=i >= 0)
            if i >= 0:
                ln = body.count("\n", 0, i) + 1
                linea = body.split("\n")[ln - 1].rstrip("\r")
                ev.update(linea=ln, texto_linea=linea.strip()[:200])
                oks.append(f"marcador «{c['texto'][:80]}» encontrado en {p}, línea {ln}: {linea.strip()[:120]}")
            else:
                fails.append(f"falta el marcador «{c['texto'][:80]}» en {p} (no está en ninguna de sus "
                             f"{f['lineas']} líneas)")
    elif not fails and tipo in ("compila", "comando"):
        to = int(c.get("timeout_s") or _rev_cfg().get("timeout_check_s") or CHECK_TIMEOUT_DEF_S)
        to = max(1, min(CHECK_TIMEOUT_MAX_S, to))
        if c.get("comando"):
            args, err = _partir_comando_check(c["comando"])
            como = c["comando"]
        elif _COMPILA_EXT.get(p.suffix.lower()) == "python":
            tmpd = Path(os.environ.get("TEMP") or os.environ.get("TMP") or str(APP_DIR)) / "growi-bridge-checks"
            tmpd.mkdir(parents=True, exist_ok=True)
            # El .pyc va a %TEMP% (siempre el mismo por proceso): no deja __pycache__ en el proyecto.
            args, err = [_python_exe(), "-c", _PYC_SNIPPET, str(p), str(tmpd / f"compila-{os.getpid()}.pyc")], None
            como = f"python -m py_compile {p.name} (el .pyc va a %TEMP%)"
        else:
            args, err, como = ["node", "--check", str(p)], None, f"node --check {p.name}"
        ev["comando"] = como
        if err:
            fails.append(f"{como}: {err}")
        else:
            code, salida, secs, err = _correr_check(args, cwd, to)
            esperado = 0 if tipo == "compila" else c.get("exit", 0)
            ev.update(cwd=str(cwd), exit=code, exit_esperado=esperado, segundos=secs,
                      salida_final=salida.strip()[-800:])
            if err:
                fails.append(f"{como}: {err}")
            else:
                if esperado is not None:
                    (oks if code == esperado else fails).append(
                        f"{como}: salió con exit {code} (se pedía {esperado}) en {secs} s"
                        + ("" if code == esperado or not salida.strip() else
                           f"; última línea: {salida.strip().splitlines()[-1][:160]}"))
                if tipo == "comando" and c.get("texto"):
                    hay = c["texto"] in salida
                    ev["texto_encontrado"] = hay
                    (oks if hay else fails).append(
                        f"{como}: su salida {'contiene' if hay else 'NO contiene'} «{c['texto'][:60]}»")
    ok = not fails
    return {"criterio": criterio_txt(c), "tipo": tipo, "tipado": True, "resultado": "pasa" if ok else "falla",
            "evidencia": ev, "detalle": oks + fails, "falla": fails}


def checks_deterministas(task, touched, text):
    """Los criterios tipados (codigo) + lo comprobable de las frases (como 0.2.0)."""
    out = []
    for c in task.get("criterios_tipados") or []:
        if _RUN.get("stop"):
            break
        try:
            out.append(_check_tipado(c, task["cwd"]))
        except Exception as e:  # un check roto es un check que no pasa, nunca un aprobado
            out.append({"criterio": criterio_txt(c), "tipo": c.get("tipo"), "tipado": True,
                        "resultado": "falla", "evidencia": {"error": f"{type(e).__name__}: {e}"},
                        "detalle": [f"{criterio_txt(c)}: el check falló al correr ({type(e).__name__}: {e})"],
                        "falla": [f"{criterio_txt(c)}: el check falló al correr ({type(e).__name__}: {e})"]})
    for frase in task.get("criterios") or []:
        ch = _check_criterion(frase, task["cwd"], touched, text)
        if ch:
            ch["tipado"] = False
            ch["resultado"] = "pasa" if not ch["falla"] else "falla"
            out.append(ch)
    return out


# -- el juez: rubrica fija 1-5 con JSON validado por esquema
def _umbral_rubrica():
    try:
        return max(1, min(5, int((_rev_cfg().get("rubrica") or {}).get("umbral_min", 3))))
    except (TypeError, ValueError):
        return 3


def validar_veredicto(d):
    """(veredicto, []) si el JSON cumple el esquema; (None, errores) si no.
    Un JSON que no valida NO es una aprobacion: es «sin revision»."""
    if not isinstance(d, dict):
        return None, ["no es un objeto JSON"]
    errs = []
    extra = sorted(set(d) - {"puntuacion", "aprobado", "que_falta", "evidencia"})
    if extra:
        errs.append(f"campos que el esquema no admite: {', '.join(extra)}")
    pu = d.get("puntuacion")
    if not isinstance(pu, dict):
        errs.append("falta puntuacion {completitud, correccion, no_regresion, evidencia}")
    else:
        for k in RUBRICA_DIMS:
            v = pu.get(k)
            if not (isinstance(v, int) and not isinstance(v, bool) and 1 <= v <= 5):
                errs.append(f"puntuacion.{k} debe ser un entero de 1 a 5 (llegó {v!r})")
        if set(pu) - set(RUBRICA_DIMS):
            errs.append(f"puntuacion trae dimensiones de más: {', '.join(sorted(set(pu) - set(RUBRICA_DIMS)))}")
    ap = d.get("aprobado")
    if ap not in ("si", "sí", "no"):
        errs.append(f'aprobado debe ser "si" o "no" (llegó {ap!r})')
    items = []
    qf = d.get("que_falta")
    if not isinstance(qf, list):
        errs.append("que_falta debe ser una lista")
    else:
        for i, it in enumerate(qf):
            if (not isinstance(it, dict) or set(it) - {"falta", "arreglo"}
                    or not isinstance(it.get("falta"), str) or not it["falta"].strip()
                    or not isinstance(it.get("arreglo"), str) or not it["arreglo"].strip()):
                errs.append(f'que_falta[{i}] debe ser {{"falta": "...", "arreglo": "..."}} con los dos textos')
            else:
                items.append({"falta": it["falta"].strip()[:400], "arreglo": it["arreglo"].strip()[:400]})
    ev = d.get("evidencia")
    if not isinstance(ev, list) or not all(isinstance(x, str) for x in ev):
        errs.append("evidencia debe ser una lista de textos")
    if not errs:
        if ap == "no" and not items:
            errs.append('aprobado "no" sin que_falta: no dice qué hay que arreglar')
        if ap in ("si", "sí") and items:
            errs.append('aprobado "si" con que_falta lleno: el veredicto se contradice')
    if errs:
        return None, errs
    v = {"aprobado": ap != "no", "aprobado_juez": ap != "no", "puntuacion": {k: pu[k] for k in RUBRICA_DIMS},
         "que_falta_items": items, "evidencia": [x.strip()[:400] for x in ev if x.strip()][:20]}
    u = _umbral_rubrica()
    bajas = [k for k in RUBRICA_DIMS if pu[k] < u]
    if v["aprobado"] and bajas:
        # El juez dice «si» pero su propia rubrica no llega al umbral: cuenta como «no».
        v.update(aprobado=False, ajustado_por_umbral=u, que_falta_items=[
            {"falta": f"el juez puntuó {k.replace('_', '-')} con {pu[k]}/5 (el umbral es {u})",
             "arreglo": f"revisa {k.replace('_', '-')}: el propio juez no la ve cumplida"} for k in bajas])
    v["que_falta"] = [f"{x['falta'].rstrip('. ')}. Arreglo: {x['arreglo']}" for x in v["que_falta_items"]]
    return v, []


def parse_veredicto(text):
    text = text or ""
    a, b = text.find("{"), text.rfind("}")
    if a < 0 or b <= a:
        return None, ["la respuesta no trae ningún JSON"]
    try:
        d = json.loads(text[a:b + 1])
    except ValueError as e:
        return None, [f"JSON roto ({e})"]
    return validar_veredicto(d)


def _parse_review_json(text):
    """Compatibilidad (0.2.0): lo de antes, ahora por el esquema de la rubrica."""
    v, _errs = parse_veredicto(text)
    return v


def _es_texto(path, sniff=4096):
    try:
        with open(path, "rb") as fh:
            return b"\x00" not in fh.read(sniff)
    except OSError:
        return False


def _obra(task, touched, checks, lim_archivo, max_archivos):
    """Lo que el juez ve de la obra: los archivos de los criterios tipados y los
    tocados, con su contenido relevante (cabecera + las lineas de cada marcador)."""
    rutas = []
    for c in task.get("criterios_tipados") or []:
        if c.get("archivo"):
            rutas.append(str(_ruta_criterio(c["archivo"], task["cwd"])))
    rutas += [str(t) for t in touched]
    marcas = {}
    for ch in checks:
        evd = ch.get("evidencia") or {}
        if evd.get("linea") and evd.get("archivo"):
            marcas.setdefault(evd["archivo"].lower(), []).append(evd["linea"])
    partes, vistos = [], set()
    for r in rutas:
        if len(vistos) >= max_archivos:
            break
        if r.lower() in vistos or not Path(r).is_file() or not _es_texto(r):
            continue
        vistos.add(r.lower())
        body = _read_text(r)
        lines = body.splitlines()
        trozo = body[:lim_archivo]
        for ln in marcas.get(r.lower(), []):
            ctx = "\n".join(lines[max(0, ln - 3):ln + 2])
            if ctx and ctx not in trozo:
                trozo += f"\n[... líneas {max(1, ln - 2)}-{min(len(lines), ln + 2)} ...]\n{ctx[:600]}"
        if len(body) > lim_archivo:
            trozo += f"\n[... recortado: {len(body)} caracteres en total ...]"
        partes.append(f"--- {r} ({len(lines)} líneas)\n{trozo}")
    return partes, len(set(x.lower() for x in rutas if Path(x).is_file()))


def _review_prompt(task, result, checks, touched, can_read, nivel=None):
    return _armar_prompt_juez(task, result, checks, touched, can_read, (5000, 2500, 6), None)


def _gate_para_revision(task, tope=1500):
    """Lineas del gate de calidad local (gate-calidad.py, Stop hook de Claude
    Code) para el prompt del juez: su log gate-calidad-<id>.log en la carpeta
    gate-calidad/ de la tarea (o de una carpeta de arriba, la raiz del repo).
    El gate es un filtro previo: la revision por criterios sigue igual, pero
    no repite a mano lo que el gate ya comprobo. [] si ahi no hay gate."""
    try:
        cwd = Path(task.get("cwd") or "")
    except TypeError:
        return []
    nombre = f"gate-calidad-{task.get('id')}.log"
    if (SHARE / "outbox" / nombre).is_file():  # la copia que deja el gate en share/outbox/
        f = SHARE / "outbox" / nombre
    else:
        for d in [cwd, *cwd.parents][:6]:
            g = d / "gate-calidad"
            if (d / "gate-calidad.py").is_file() or g.is_dir():
                break
        else:
            return []
        f = g / nombre
    try:
        txt = f.read_text(encoding="utf-8", errors="replace").strip()
    except OSError:
        return ["", "GATE DE CALIDAD LOCAL: no hay log para esta tarea "
                f"({f}); el gate no corrió. Compruébalo tú si hace falta."]
    primera = txt.splitlines()[0] if txt else ""
    out = ["", f"GATE DE CALIDAD LOCAL (comprobado por código, $0; log completo en {f}). Ya comprobó "
               "sintaxis (py_compile), lint (ruff), tipos (mypy), tests (pytest) y arranque (smoke): NO lo "
               "vuelvas a comprobar a mano; céntrate en los criterios del encargo."]
    if "FALLA" in primera:
        out.append("El gate FALLÓ y el agente no lo corrigió: es un HECHO que FALLA, la tarea NO se aprueba.")
    out.append(txt[:tope] + (f"\n[... log recortado: {len(txt)} caracteres ...]" if len(txt) > tope else ""))
    return out


def _armar_prompt_juez(task, result, checks, touched, can_read, lim, nota_recorte):
    lim_res, lim_arch, max_arch = lim
    fam = load_family(task["raiz"]) or {}
    encargo = fam.get("encargo") or task["prompt"]
    parts = ["Eres un juez estricto. NO hagas el trabajo: solo compruebas si está hecho y lo puntúas.",
             "", "ENCARGO:", encargo[:3000 if lim_res >= 800 else 1200]]
    frases = task.get("criterios") or []
    if frases:
        parts += ["", "CRITERIOS EN FRASES (estos los juzgas tú):"] + [f"{i}. {c}" for i, c in enumerate(frases, 1)]
    if checks:
        parts += ["", "HECHOS COMPROBADOS POR CÓDIGO EN LOS ARCHIVOS REALES (mandan sobre tu opinión: si "
                      "alguno dice FALLA, la tarea NO se aprueba):"]
        for ch in checks:
            parts.append(f"- [{'PASA' if not ch['falla'] else 'FALLA'}] {ch['criterio']}: "
                         + "; ".join(ch["detalle"])[:500])
    parts += _gate_para_revision(task, 1500 if lim_res >= 800 else 600)
    res_txt = (result.get("result") or "").strip()
    parts += ["", "PARTE DEL MOTOR (lo que él dice que hizo; puede exagerar):",
              (res_txt[:lim_res] + (f"\n[... recortado: {len(res_txt)} caracteres en total ...]"
                                    if len(res_txt) > lim_res else "")) if res_txt else "(vacío)"]
    obra, n_total = _obra(task, touched, checks, lim_arch, max_arch)
    parts += ["", "LA OBRA (archivos tocados y su contenido; esto es lo que cuenta, no el parte):"]
    parts += obra or ["(no hay archivos tocados que se puedan leer)"]
    if n_total > len(obra):
        parts.append(f"(hay {n_total} archivos; se muestran {len(obra)})")
    if nota_recorte:
        parts += ["", f"NOTA: {nota_recorte}"]
    if can_read:
        parts.append("Puedes leer archivos de la carpeta para comprobarlo (solo leer).")
    u = _umbral_rubrica()
    parts += ["", "RÚBRICA (puntúa de 1 a 5 cada dimensión):",
              "- completitud: ¿está hecho TODO lo que pide el encargo y cada criterio? (5 = todo, 1 = casi nada)",
              "- correccion: ¿lo hecho es correcto, sin errores, y hace lo que dice?",
              "- no_regresion: ¿no rompió nada que ya estaba ni tocó lo que no debía?",
              "- evidencia: ¿hay pruebas en los hechos o en la obra (no solo en el parte del motor)?",
              f'Reglas: "aprobado" es "si" solo si todas valen {u} o más, ningún hecho dice FALLA y no falta nada. '
              'Si apruebas, que_falta va vacío. Si no apruebas, cada cosa de que_falta lleva su arreglo concreto '
              '("falta" y "arreglo"). evidencia: archivos o líneas que lo demuestran. No inventes archivos ni líneas.',
              "Responde SOLO con un JSON así, sin nada más:",
              '{"puntuacion": {"completitud": 1-5, "correccion": 1-5, "no_regresion": 1-5, "evidencia": 1-5}, '
              '"aprobado": "si" o "no", "que_falta": [{"falta": "qué falta", "arreglo": "qué hacer"}], '
              '"evidencia": ["archivo o línea"]}']
    return "\n".join(parts)


def _contexto_juez(eng):
    """(tokens, fuente) del contexto REAL del juez: se le pregunta al servidor si
    el descriptor dice donde (llama-server: /props); si no, lo declarado; si no, None."""
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else eng
    cx = d.get("contexto") if isinstance(d.get("contexto"), dict) else None
    if not cx:
        return None, "sin dato"
    base = d.get("base_url")
    if cx.get("props") and base:
        url = _url_join(base, cx["props"])
        if _srv_es_router(eng):
            # El router sin ?model= da n_ctx 0: se pregunta por el modelo.
            url += ("&" if "?" in url else "?") + "model=" + _srv_modelo_defecto(eng)
        try:
            p = _http_local("GET", url, timeout=3)
            n = _get_path(p, cx.get("campo") or "default_generation_settings.n_ctx")
            if isinstance(n, int) and n > 0:
                return n, f"lo dice el servidor ({cx['props']}: n_ctx={n})"
        except LocalCallError:
            pass
    if isinstance(cx.get("tokens"), int):
        return cx["tokens"], cx.get("fuente") or "declarado en engines.json"
    return None, "sin dato"


def _contar_tokens(eng, text):
    """(n, como): exacto con el tokenizador del servidor si lo hay; si no, estimado."""
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else eng
    cx = d.get("contexto") if isinstance(d.get("contexto"), dict) else {}
    if cx.get("tokenizar") and d.get("base_url"):
        body = {"content": text}
        if _srv_es_router(eng):
            body["model"] = _srv_modelo_defecto(eng)  # el router exige "model" (sin el: 400)
        try:
            r = _http_local("POST", _url_join(d["base_url"], cx["tokenizar"]), body, timeout=15)
            if isinstance(r, dict) and isinstance(r.get("tokens"), list):
                return len(r["tokens"]), "exacto (tokenizador del servidor)"
        except LocalCallError:
            pass
    return len(text) // 3 + 1, "estimado (3 caracteres por token)"


_NIVELES_RECORTE = ((5000, 2500, 6), (800, 2500, 6), (300, 1500, 5), (300, 800, 4), (200, 400, 3), (120, 200, 2))


def prompt_juez_que_quepa(task, result, checks, touched, eng):
    """(prompt, recorte): si no cabe en el contexto del juez se recorta el parte
    del motor y luego la obra (lo relevante: hechos + archivos tocados) y se dice.
    (None, recorte) si ni recortado cabe: ese juez no se usa (nunca falla en silencio)."""
    can_read = _cap(eng, "herramientas")
    ctx, fuente = _contexto_juez(eng)
    d = eng.get("_v2") if isinstance(eng.get("_v2"), dict) else eng
    reserva = int(((d.get("contexto") or {}) if isinstance(d.get("contexto"), dict) else {}).get("reserva_salida") or 800)
    rec = {"contexto_tokens": ctx, "fuente_contexto": fuente, "reserva_salida": reserva, "recortado": False}
    prompt = _armar_prompt_juez(task, result, checks, touched, can_read, _NIVELES_RECORTE[0], None)
    if ctx is None:
        rec.update(tokens_prompt=None, conteo="no se contó (el contexto de este juez no tiene dato; no se recorta)")
        return prompt, rec
    n, como = _contar_tokens(eng, prompt)
    rec.update(tokens_prompt=n, conteo=como, tokens_original=n)
    if n + reserva <= ctx:
        return prompt, rec
    res_len = len((result.get("result") or "").strip())
    for i, lim in enumerate(_NIVELES_RECORTE[1:], 1):
        nota = (f"para que quepa en tu contexto ({ctx} tokens) se recortó el parte del motor "
                f"(de {res_len} a {min(res_len, lim[0])} caracteres) y la obra (hasta {lim[2]} archivos, "
                f"{lim[1]} caracteres cada uno). Juzga con lo que ves; los HECHOS no se recortaron.")
        prompt = _armar_prompt_juez(task, result, checks, touched, can_read, lim, nota)
        n, como = _contar_tokens(eng, prompt)
        if n + reserva <= ctx:
            rec.update(recortado=True, nivel=i, tokens_prompt=n, conteo=como, que=nota)
            return prompt, rec
    rec.update(recortado=True, nivel=len(_NIVELES_RECORTE) - 1, tokens_prompt=n, conteo=como,
               no_cabe=f"ni recortado cabe: {n} tokens + {reserva} de respuesta > {ctx}")
    return None, rec


def _llamar_juez(spec, task, result, checks, touched, rol="juez 1"):
    """Un juez del descriptor. estado: valido | invalido | no_disponible | error |
    no_cabe | parado | omitido. Mide el tiempo y el costo reales."""
    mid = spec.get("motor")
    eng = get_engine(mid)
    j = {"rol": rol, "motor": mid, "modelo": spec.get("modelo"), "spec": {"motor": mid, "modelo": spec.get("modelo")},
         "estado": None, "veredicto": None,
         "errores": [], "costo_usd": None, "segundos": None, "tokens": None, "recorte": None, "crudo": None}
    if LANE == "b" and not (eng or {}).get("carril_b"):
        return dict(j, estado="no_disponible", errores=["el carril B no usa motores locales"])
    if eng is None:
        return dict(j, estado="no_disponible", errores=["no existe en engines.json"])
    j["nombre"] = eng.get("nombre") or mid
    ok, why = engine_status(mid)
    if not ok or (eng.get("servidor") and why != "responde"):
        return dict(j, estado="no_disponible", errores=[str(why)])
    if eng.get("tipo") not in ("cli_sincrono", "api_sincrona"):
        return dict(j, estado="no_disponible", errores=["no sirve para revisar texto"])
    if _RUN.get("stop"):
        return dict(j, estado="parado", errores=["parado por el usuario"])
    prompt, rec = prompt_juez_que_quepa(task, result, checks, touched, eng)
    j["recorte"] = rec
    if prompt is None:
        log(f"runner [{task['id']}]: revisión: {mid} no se usa: {rec.get('no_cabe')}")
        return dict(j, estado="no_cabe", errores=[rec.get("no_cabe")])
    if rec.get("recortado"):
        log(f"runner [{task['id']}]: revisión: recorté el contexto para {mid} ({rec.get('que')})")
    state["paso"] = f"Revisando {task['raiz']} con {j['nombre']}" + (" (segundo juez)" if rol == "juez 2" else "")
    rtask = {"id": task["id"] + ("-revision" if rol == "juez 1" else "-revision-2"), "cwd": task["cwd"],
             "timeout_min": 10, "modelo": spec.get("modelo"), "session_id": None, "prompt": "",
             "allowed_tools": spec.get("allowed_tools"), "permission_mode": None}
    r = _base_result(rtask, mid)
    _RUN["rev_prompt"], _RUN["rev_raw"] = prompt, None  # transcript de la ronda (checkpoint)
    if eng.get("tipo") in ("cli_sincrono", "api_sincrona"):
        live_review_start(mid, spec.get("modelo") or _local_model(eng, {}) or None)
    t0 = time.time()
    if eng.get("tipo") == "cli_sincrono":
        _run_cli_engine(rtask, mid, eng, r, prompt, abilities=False, rol="revision")
    else:
        _run_http_engine(rtask, mid, eng, r, prompt, for_review=True)
    j["segundos"] = round(time.time() - t0, 2)
    j["costo_usd"] = r.get("cost_usd") if isinstance(r.get("cost_usd"), (int, float)) else None
    j["modelo"] = r.get("modelo") or j["modelo"]
    j["tokens"] = r.get("uso")
    j["crudo"] = (r.get("result") or r.get("error") or "")[:4000]
    _RUN["rev_raw"] = j["crudo"]
    if _RUN.get("stop"):
        return dict(j, estado="parado", errores=["parado por el usuario"])
    if r["status"] != "ok":
        return dict(j, estado="error", errores=[str(r.get("error") or "falló")])
    v, errs = parse_veredicto(r["result"])
    if v is None:
        log(f"runner [{task['id']}]: revisión: {mid} devolvió un JSON que no cumple el esquema: {'; '.join(errs)[:200]}")
        return dict(j, estado="invalido", errores=errs)
    return dict(j, estado="valido", veredicto=v)


def _llm_review(task, result, checks, touched, nivel="R0"):
    """Primer juez: la cadena del descriptor (revision.orden), el primero que
    responda. Uno que responde con JSON invalido NO se salta: es «sin revision».
    (juez, intentos)"""
    intentos = []
    orden_rev = list(_rev_cfg().get("orden") or [])
    mrev = superficie_modelo("revision", avisar=False)  # t-modelo-por-superficie-auto
    if mrev and mrev != "motor:auto" and _motor_de_modelo(mrev):
        mid_rev = _motor_de_modelo(mrev)
        mod_rev = mrev if mrev in ("sonnet", "opus", "haiku") else (mrev.split(":", 1)[1] if mrev.startswith("ollama:")
                                                                     else None)
        orden_rev = [{"motor": mid_rev, "modelo": mod_rev}] + [x for x in orden_rev if not (
            x.get("motor") == mid_rev and (x.get("modelo") or None) == mod_rev)]
    for spec in asis_orden_revision(task, orden_rev):  # la del asistente primero
        desde = spec.get("solo_desde")
        if desde in NIVELES_R and _rango(nivel) < _rango(desde):
            intentos.append({"rol": "juez 1", "motor": spec.get("motor"), "modelo": spec.get("modelo"),
                             "estado": "omitido", "errores": [f"no se gasta en tareas {nivel} (solo desde {desde})"]})
            continue
        j = _llamar_juez(spec, task, result, checks, touched, "juez 1")
        if j["estado"] in ("valido", "invalido", "parado"):
            return j, intentos
        intentos.append(j)
    return None, intentos


def _nivel_de_tarea(task):
    """Nivel R0-R3 de la tarea original (las rondas heredan el de su encargo)."""
    fam = load_family(task["raiz"]) or {}
    try:
        a = clasificar_riesgo(task)["nivel"]
        b = clasificar_riesgo(dict(task, prompt=fam.get("encargo") or task["prompt"]))["nivel"]
        return max(a, b, key=_rango)
    except Exception as e:
        log(f"runner [{task['id']}]: revisión: no pude clasificar el riesgo ({e}); se trata como R3")
        return "R3"


def _motivo_segundo_juez(nivel, det_fail):
    """(motivo para llamar a Haiku, o None) y por que no. Nunca en R0."""
    if nivel == "R0":
        return None, "tarea R0: nunca se gasta el segundo juez"
    if det_fail:
        return "un check determinista falló", None
    if nivel in ("R2", "R3"):
        return f"tarea {nivel} (riesgo alto)", None
    return None, f"tarea {nivel} con todos los checks en verde: basta con el primer juez"


def _resumen_juez(j):
    if not j:
        return None
    v = j.get("veredicto") or {}
    return {"rol": j.get("rol"), "motor": j.get("motor"), "nombre": j.get("nombre"), "modelo": j.get("modelo"),
            "estado": j.get("estado"), "aprobado": v.get("aprobado") if v else None,
            "aprobado_juez": v.get("aprobado_juez") if v else None, "puntuacion": v.get("puntuacion"),
            "ajustado_por_umbral": v.get("ajustado_por_umbral"), "que_falta": v.get("que_falta") or [],
            "que_falta_items": v.get("que_falta_items") or [], "evidencia": v.get("evidencia") or [],
            "errores": j.get("errores") or [], "costo_usd": j.get("costo_usd"), "segundos": j.get("segundos"),
            "tokens": j.get("tokens"), "recorte": j.get("recorte")}


def _evidencia_no_existe(tok, cwd, touched):
    """Una ruta citada por un juez que no existe NO cuenta. Una ruta absoluta se
    mira tal cual (no vale que otro archivo se llame igual); una relativa, como
    en 0.2.0 (carpeta de la tarea o un archivo tocado con ese nombre)."""
    p = Path(str(tok).replace("\\", "/"))
    if p.is_absolute():
        try:
            return not p.exists()
        except OSError:
            return True
    r = _resolve_mentioned(tok, cwd, touched)
    return r is not None and not r.exists()


def review_task(task, result):
    """Revision al terminar (t-criterios-tipados-030). Sin criterios: solo que el
    resultado no este vacio ni traiga error. Con criterios: (1) checks
    deterministas ($0) como puerta dura; (2) juez con rubrica 1-5 y JSON validado
    por esquema; (3) segundo juez (Haiku, del descriptor) solo si un check fallo
    o la tarea es R2/R3, nunca en R0; si los jueces no coinciden: necesita decision."""
    eng = get_engine(task.get("motor") or "") or {}
    frases = task.get("criterios") or []
    tipados = task.get("criterios_tipados") or []
    text = (result.get("result") or "").strip()
    solo = task.get("revisar") == "solo_checks"
    can_touch = eng.get("tipo") in ("cli_sincrono", "api_asincrona") or task.get("motor") == "api"
    touched = _touched_files(task["cwd"], _iso_ts(result.get("started_at")) - 2) if can_touch else []
    touched = list(dict.fromkeys((result.get("archivos") or []) + touched))
    rev = {"id": task["id"], "raiz": task["raiz"], "ronda": task.get("ronda", 0),
           "aprobado": None, "decision": None, "necesita_decision": False, "que_falta": [], "evidencia": [],
           "motor_revision": None, "verificacion_automatica": [], "checks_deterministas": [],
           "opinion_modelo": None, "veredictos": [], "segundo_juez": None, "archivos_tocados": touched,
           "criterios": frases, "criterios_tipados": tipados, "cost_usd": 0.0, "revisado_at": None,
           "error": None, "esquema": "rubrica-1-5 (t-criterios-tipados-030)",
           "modo_revision": "solo_checks" if solo else "completa"}
    if not frases and not tipados and not solo:
        ok = bool(text) and not result.get("error")
        rev.update(aprobado=ok, decision="aprobado" if ok else "no_aprobado",
                   motor_revision="reglas (la tarea no trae criterios)",
                   evidencia=[f"el resultado tiene {len(text)} caracteres y no trae error"] if ok else [],
                   que_falta=[] if ok else ["el resultado llegó vacío"], revisado_at=_now_iso())
        return rev
    nivel = _nivel_de_tarea(task)
    rev["nivel"] = nivel
    # 1. Los hechos, con codigo y antes de cualquier juez ($0).
    state["paso"] = f"Revisando {task['raiz']}: checks deterministas"
    checks = checks_deterministas(task, touched, text)
    rev["verificacion_automatica"] = checks
    rev["checks_deterministas"] = [{"criterio": c["criterio"], "tipo": c.get("tipo"), "tipado": c.get("tipado"),
                                    "resultado": c["resultado"], "evidencia": c.get("evidencia"),
                                    "detalle": c["detalle"]} for c in checks]
    det_fail = [f for c in checks for f in c["falla"]]
    verified = [d for c in checks for d in c["detalle"] if d not in c["falla"]]
    if _RUN.get("stop"):
        rev.update(error="parado por el usuario durante la revisión", revisado_at=_now_iso())
        return rev
    if solo:
        return _decision_solo_checks(task, rev, checks, det_fail, verified)
    # 2. El juez (cadena del descriptor).
    j1, intentos = _llm_review(task, result, checks, touched, nivel)
    rev["jueces_intentados"] = [_resumen_juez(x) for x in intentos]
    rev.update(_ruta_revisor(j1, intentos))  # t-router-fallbacks: «llama: sin respuesta -> ollama: valido»
    if intentos or j1:
        log(f"runner [{task['id']}]: revisión por la cadena: {rev['cadena_revisor']}")
    cost = sum(x.get("costo_usd") or 0 for x in intentos) + ((j1 or {}).get("costo_usd") or 0)
    v1 = (j1 or {}).get("veredicto")
    if j1:
        rev["veredictos"].append(_resumen_juez(j1))
        rev["motor_revision"] = j1["motor"]
        if (j1.get("recorte") or {}).get("recortado"):
            rev["recorte"] = j1["recorte"]
    # 3. Segundo juez: solo si hace falta y nunca en R0.
    j2 = None
    motivo2, por_que_no = _motivo_segundo_juez(nivel, det_fail)
    spec2 = _rev_cfg().get("segundo_juez") if isinstance(_rev_cfg().get("segundo_juez"), dict) else None
    sj = {"llamado": False, "motivo": motivo2, "por_que_no": por_que_no}
    if motivo2 and not v1:
        sj["por_que_no"] = "el primer juez no dio un veredicto válido: no se paga un segundo para desempatar nada"
    elif motivo2 and not spec2:
        sj["por_que_no"] = "engines.json no declara revision.segundo_juez"
    elif motivo2 and j1 and spec2.get("motor") == j1["spec"]["motor"] and \
            (spec2.get("modelo") or None) == (j1["spec"]["modelo"] or None):
        sj["por_que_no"] = "el segundo juez sería el mismo motor que el primero: no se repite"
    elif motivo2 and not _RUN.get("stop"):
        j2 = _llamar_juez(spec2, task, result, checks, touched, "juez 2")
        cost += j2.get("costo_usd") or 0
        sj.update(llamado=True, motor=j2["motor"], modelo=j2.get("modelo"), estado=j2["estado"],
                  costo_usd=j2.get("costo_usd"), segundos=j2.get("segundos"), tokens=j2.get("tokens"),
                  errores=j2.get("errores"))
        rev["veredictos"].append(_resumen_juez(j2))
        log(f"runner [{task['id']}]: segundo juez {j2['motor']} ({j2.get('modelo')}): {j2['estado']}, "
            f"{j2.get('segundos')} s, costo {j2.get('costo_usd')}")
    rev["segundo_juez"] = sj
    v2 = (j2 or {}).get("veredicto")
    rev["cost_usd"] = round(cost, 6)
    rev["opinion_modelo"] = ({"aprobado": v1["aprobado"], "que_falta": v1["que_falta"],
                              "evidencia": v1["evidencia"], "motor": j1["motor"], "modelo": j1.get("modelo")}
                             if v1 else None)
    # 4. Decision: los hechos mandan; dos jueces que no coinciden -> decide Leandro.
    falta_jueces = [x for v in (v1, v2) if v and not v["aprobado"] for x in v["que_falta"]]
    if v1 is None:
        estado1 = (j1 or {}).get("estado")
        why = ("el juez respondió con un JSON que no cumple el esquema: " + "; ".join((j1 or {}).get("errores") or [])[:300]
               if estado1 == "invalido" else
               "parado por el usuario durante la revisión" if estado1 == "parado" else
               "no hay juez disponible: " + "; ".join(f"{x['motor']}: {'; '.join(x.get('errores') or [])}"
                                                    for x in intentos)[:400])
        if estado1 == "parado":
            rev["error"] = why
        elif det_fail:
            rev.update(decision="no_aprobado", aprobado=False, que_falta=det_fail,
                       motor_revision=f"checks deterministas (sin juez válido: {why[:160]})")
        else:
            rev.update(decision="sin_revision", aprobado=None, error=why)
    elif v2 is not None and v1["aprobado"] != v2["aprobado"]:
        rev.update(decision="necesita_decision", necesita_decision=True, aprobado=False,
                   motivo_decision="los dos jueces no coinciden",
                   que_falta=det_fail + [x for x in falta_jueces if x not in det_fail])
    elif v2 is not None and det_fail and v1["aprobado"]:
        rev.update(decision="necesita_decision", necesita_decision=True, aprobado=False,
                   motivo_decision="los dos jueces aprueban pero un check determinista falla",
                   que_falta=det_fail)
    elif det_fail:
        rev.update(decision="no_aprobado", aprobado=False,
                   que_falta=det_fail + [x for x in falta_jueces if x not in det_fail])
        if v1["aprobado"]:
            rev["juez_contra_hechos"] = (f"{j1['motor']} aprobó, pero un check determinista falla: "
                                         "no se aprueba (los hechos mandan)")
    elif v1["aprobado"]:
        rev.update(decision="aprobado", aprobado=True)
    else:
        rev.update(decision="no_aprobado", aprobado=False, que_falta=falta_jueces)
    if rev["aprobado"] is False and not rev["que_falta"]:
        rev["que_falta"] = ["la revisión no aprobó pero no dijo qué falta: revisa el resultado"]
    for v, j in ((v1, j1), (v2, j2)):
        for e in (v or {}).get("evidencia") or []:
            bad = [t for t in (m.group(1) for m in _FILE_RE.finditer(e))
                   if _evidencia_no_existe(t, task["cwd"], touched)]
            rev["evidencia"].append(f"según {j['motor']}: {e}" + (
                f" (pero {', '.join(bad)} no existe: no cuenta)" if bad else ""))
    rev["evidencia"] = verified + rev["evidencia"]
    rev["revisado_at"] = _now_iso()
    # el veredicto en tres palabras (t-rubrica-revisor-030): aprobado / rechazado / necesita_decision
    rev["veredicto"] = {"aprobado": "aprobado", "no_aprobado": "rechazado"}.get(rev.get("decision"),
                                                                              rev.get("decision"))
    rev["run_id"] = task.get("run_id") or task.get("raiz")
    try:
        rev["calibracion_id"] = calib_registrar(task, rev)
    except Exception as e:
        log(f"runner [{task['id']}]: calibración: no se pudo apuntar la revisión ({type(e).__name__}: {e})")
    return rev


def _decision_solo_checks(task, rev, checks, det_fail, verified):
    """«revisar»: «solo_checks»: decide SOLO con los checks deterministas,
    sin ningun juez ($0). Aprueba solo si hay criterios tipados y todos los
    checks pasan; un check en rojo o ningun tipado -> necesita decision
    (nunca aprobado contra un hecho, ni en silencio sin hechos)."""
    tipados_ok = [c for c in checks if c.get("tipado")]
    rev.update(motor_revision="checks deterministas (revisar: solo_checks, sin juez, $0)",
               jueces_intentados=[], cost_usd=0.0, evidencia=verified,
               segundo_juez={"llamado": False, "motivo": None,
                             "por_que_no": "revisar: solo_checks: no se llama a ningún juez"})
    if det_fail:
        rev.update(decision="necesita_decision", necesita_decision=True, aprobado=False, que_falta=det_fail,
                   motivo_decision="solo_checks: un check determinista falla (los hechos mandan; "
                                   "sin juez no se abre otra ronda)")
    elif not tipados_ok:
        rev.update(decision="necesita_decision", necesita_decision=True, aprobado=False,
                   motivo_decision="solo_checks sin criterios tipados: no hay hechos que comprobar con código; "
                                   "no se aprueba en silencio",
                   que_falta=["la tarea no trae criterios_tipados: añádelos o usa \"revisar\": true (con juez)"])
    else:
        rev.update(decision="aprobado", aprobado=True)
    rev["revisado_at"] = _now_iso()
    log(f"runner [{task['id']}]: revisión solo_checks (sin juez, $0): {len(checks)} check(s), "
        f"{len(tipados_ok)} tipado(s), {len(det_fail)} en rojo -> {rev['decision']}")
    return rev


# -- auto-critica barata antes de entregar (tareas de codigo)
_CODIGO_RE = re.compile(r"\.(?:py|pyw|js|mjs|cjs|ts|tsx|jsx|cs|go|rs|java|c|cpp|h|ps1|bat|sh)\b|"
                        r"\bc[oó]digo\b|\bscript\b|\bfunci[oó]n\b|\bprograma\b|\bcompil|\bpy_compile\b|"
                        r"\brefactor|\bbug\b|\bclase\b", re.I)


def es_tarea_de_codigo(task):
    tip = task.get("criterios_tipados") or []
    if any(c.get("tipo") in ("compila", "comando") for c in tip):
        return True
    if any(Path(str(c.get("archivo") or "")).suffix.lower() in _COMPILA_EXT for c in tip):
        return True
    fam = load_family(task.get("raiz") or task["id"]) or {}
    texto = " ".join([fam.get("encargo") or "", task.get("prompt") or ""] + list(task.get("criterios") or []))
    return bool(_CODIGO_RE.search(texto))


def autocritica_txt(task):
    """Lo que se anade al prompt de cada tarea de codigo: reflexion barata
    grounded en ejecucion (el runner lo va a comprobar con codigo igual)."""
    if not es_tarea_de_codigo(task):
        return ""
    tip = task.get("criterios_tipados") or []
    lineas = ["", "", "Antes de darlo por hecho, comprueba tú mismo (el runner lo va a verificar con código, "
                      "y si algo falla no se aprueba):"]
    comp = [criterio_txt(c) for c in tip if c["tipo"] in ("compila", "comando")]
    lineas.append("- que compila: " + ("; ".join(comp) if comp else
                                        "python -m py_compile en cada .py que tocaste (o el build del proyecto)"))
    marc = [f"«{c['texto'][:80]}» en {c['archivo']}" for c in tip if c["tipo"] == "contiene"]
    lineas.append("- que los marcadores están: " + ("; ".join(marc) if marc else "los que pide el encargo"))
    for c in tip:
        if c["tipo"] in ("lineas", "existe"):
            lineas.append(f"- {criterio_txt(c)[len(c['tipo']) + 3:]}")
    arch = list(dict.fromkeys(c["archivo"] for c in tip if c.get("archivo")))
    lineas.append("- que no tocaste archivos fuera de la lista: " + (", ".join(arch) if arch else
                                                                     "solo los que el encargo pide"))
    lineas.append("Si algo falla, arréglalo antes de responder, y di en tu respuesta qué comprobaste y con qué resultado.")
    return "\n".join(lineas)


def prompt_de_tarea(task):
    """El prompt que de verdad recibe el motor: reglas + skills activadas por
    descripcion (maximo 3) + encargo + auto-critica."""
    try:
        skills_txt, _reg = skills_bloque_prompt(task)
    except Exception as e:  # una skill rota nunca para una tarea
        log(f"skills [{task.get('id')}]: no se pudieron adjuntar ({type(e).__name__}: {e})")
        skills_txt = ""
    try:
        mem_txt = mem_bloque_prompt(task)
    except Exception as e:  # la memoria rota nunca para una tarea
        log(f"memoria [{task.get('id')}]: no se pudo cargar ({type(e).__name__}: {e})")
        mem_txt = ""
    try:
        asis_txt = asis_bloque_prompt(task)
    except Exception as e:  # un perfil roto nunca para una tarea
        log(f"asistentes [{task.get('id')}]: no se pudo adjuntar el perfil ({type(e).__name__}: {e})")
        asis_txt = ""
    try:
        perfil_txt = perfil_bloque_prompt(task)
    except Exception as e:  # «Sobre mí» roto nunca para una tarea
        log(f"perfil [{task.get('id')}]: no se pudo adjuntar ({type(e).__name__}: {e})")
        perfil_txt = ""
    # el perfil justo antes del encargo: los modelos pequeños hacen más caso a lo último que leen
    try:
        perfil_ojo = perfil_recordatorio(task) if perfil_txt else ""
    except Exception:
        perfil_ojo = ""
    if SLOT2_MODO["activo"]:  # agente del 2.º hueco: encargo + archivos + perfil, sin la memoria larga
        mem_txt = ""
    try:
        proy_txt = proyecto_bloque_prompt(task)  # t-proyectos: el de la tarea, no el activo ahora
    except Exception as e:
        log(f"proyectos [{task.get('id')}]: no se pudo adjuntar ({type(e).__name__}: {e})")
        proy_txt = ""
    contexto_apuntar(task, {"reglas": rules_prefix(), "proyecto": proy_txt, "asistente": asis_txt, "memoria": mem_txt,
                            "skills": skills_txt, "perfil": perfil_txt, "encargo": task["prompt"]})
    return (rules_prefix() + proy_txt + asis_txt + mem_txt + skills_txt + perfil_txt + task["prompt"] + perfil_ojo
            + autocritica_txt(task))


# ---------------------------------------------------------------- memoria en el PC
# t-memoria-pc: la memoria vive en Markdown en memory\ junto al programa
# (MEMORY.md curada + memory\AAAA-MM-DD.md, registro del dia, solo anadir).
# Se lee y se edita abriendo el archivo; nada de base de datos. Se escribe
# solo por flush (antes de compactar / al terminar una fase), por el
# snapshot de /nuevo o porque Leandro dice «recuerda esto», y cada escritura
# se ve (registro, aviso). Al empezar una tarea se inyectan MEMORY.md + hoy +
# ayer, nunca el historial. Con la VM se sincroniza POR DIFERENCIA (secciones
# «## ...»): lo nuevo de cada lado se anade, lo que existe no se pisa, y un
# conflicto guarda las dos versiones y avisa. Diseno estudiado (no copiado)
# de la memoria en Markdown de OpenClaw; OpenClaw no se usa.
MEMORY_DIR = Path(os.environ.get("GROWI_BRIDGE_MEMORIA") or (APP_DIR / "memory"))
_MEM_LOCK = threading.RLock()
_MEM_CARGA = {}   # id de la tarea -> {"texto", "registro"} (una sola carga por tarea)
_MEM_DEF = {
    "activa": True,
    # Cuanto texto de memoria va al prompt como mucho (se adapta al contexto
    # que declara el descriptor del motor: nunca mas de un 25 %).
    "max_caracteres": 12000,
    # Flush: mismo patron que OpenClaw (reserva 20.000 tokens, flush suave a
    # 4.000 del limite) para una ventana de referencia de 200.000; con una
    # ventana menor (la que declara el descriptor) se escala en proporcion.
    "reserva_tokens": 20000, "flush_suave_tokens": 4000, "contexto_referencia_tokens": 200000,
    "contexto_tokens": None,      # forzar la ventana (si el descriptor no la da)
    "flush_fin_de_fase": True,    # flush al terminar cada fase de un plan
    "flush_motor": "mismo",       # "mismo" = el motor de la tarea (con su sesion si reanuda) o un id
    "motor_resumen": None,        # para el snapshot de /nuevo; None = el primero de revision.orden
    "vm_carpeta": "memoria-vm",   # share\inbox\<esto>: lo que deja la VM para la sync
}
_MEM_NOTA_RE = re.compile(r"^\d{4}-\d{2}-\d{2}\.md$")
_MEM_SYNC_RE = re.compile(r"^(MEMORY\.md|\d{4}-\d{2}-\d{2}\.md|snapshot-[\w.-]+\.md)$", re.I)
_MEM_DIAS = ("lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo")


def mem_cfg():
    c = dict(_MEM_DEF)
    s = load_settings().get("memoria")
    if isinstance(s, dict):
        c.update({k: v for k, v in s.items() if k in _MEM_DEF})
    return c


def mem_activa(task=None):
    if LANE == "b":  # el carril B es una copia de fondo: una sola memoria, la del carril A
        return False
    if task is not None and task.get("memoria") is False:
        return False
    return bool(mem_cfg().get("activa", True))


def mem_hoy():
    """La fecha de hoy (hora de Caracas). GROWI_BRIDGE_MEMORIA_HOY solo vale
    en una instancia aislada (para probar «sin nota de ayer»)."""
    o = os.environ.get("GROWI_BRIDGE_MEMORIA_HOY")
    if o and _instancia_aislada():
        try:
            return datetime.strptime(o, "%Y-%m-%d").date()
        except ValueError:
            pass
    return datetime.now(TZ_CARACAS).date()


def _mem_hora():
    return datetime.now(TZ_CARACAS).strftime("%H:%M")


def mem_nota(d):
    return MEMORY_DIR / f"{d.isoformat()}.md"


def _mem_rel(p):
    try:
        return str(Path(p).relative_to(MEMORY_DIR.parent))
    except ValueError:
        return str(p)


def _mem_registro(evento, **kw):
    """share\\outbox\\memoria-registro.jsonl: una linea por carga, escritura,
    flush, snapshot y sync (el puente lo sincroniza a la VM)."""
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        with open(OUTBOX / "memoria-registro.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps(dict(at=_now_iso(), evento=evento, **kw), ensure_ascii=False) + "\n")
    except OSError:
        pass


def _mem_escribir(path, text):
    """Escritura entera (solo MEMORY.md curada y archivos nuevos): a un .tmp y
    os.replace, para que un corte nunca deje el archivo a medias."""
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    os.replace(tmp, path)


def _mem_cabecera_nota(d):
    return (f"# Nota del {d.isoformat()} ({_MEM_DIAS[d.weekday()]})\n\n"
            "Registro del día: solo se añade, nunca se reescribe. Lo escriben Bridge (flush antes de "
            "compactar, snapshot de /nuevo, «recuerda esto») y tú cuando quieras.\n")


def mem_anadir_nota(titulo, lineas, d=None):
    """Escritor de solo-anadir de la nota del dia: abre en modo «a», nunca
    reescribe lo que ya estaba. Devuelve la ruta."""
    d = d or mem_hoy()
    p = mem_nota(d)
    with _MEM_LOCK:
        MEMORY_DIR.mkdir(parents=True, exist_ok=True)
        nuevo = not p.exists()
        sep = ""
        if not nuevo:
            with open(p, "rb") as f:
                f.seek(0, 2)
                if f.tell():
                    f.seek(-1, 2)
                    sep = "" if f.read(1) == b"\n" else "\n"
        with open(p, "a", encoding="utf-8") as f:
            if nuevo:
                f.write(_mem_cabecera_nota(d))
            f.write(f"{sep}\n## {_mem_hora()} · PC · {titulo}\n" + "\n".join(lineas) + "\n")
    return p


def _mem_memory_minima():
    """MEMORY.md minima cuando la VM no dejo semilla: solo lo que la app sabe
    de verdad (reglas activas, puerto del puente, motores locales del
    descriptor). Nada inventado sobre Leandro."""
    hoy = mem_hoy().isoformat()
    reglas = [r["text"] for r in load_rules() if r.get("on")]
    pc = [f"- El puente escucha en el puerto {BRIDGE_PORT} (127.0.0.1 y la IP de Tailscale de este PC)."]
    for mid in engine_ids():
        e = get_engine(mid) or {}
        if e.get("servidor") and e.get("url"):
            sv = e["servidor"]
            pc.append(f"- Motor local «{e.get('nombre') or mid}»: {sv.get('exe')} con {sv.get('gguf')} "
                      f"en {e['url'].split('/v1')[0]} (de engines.json).")
    pc.append("- Las llamadas HTTP a 127.0.0.1 van con NO_PROXY=127.0.0.1 y JSON en UTF-8 "
              "(un proxy en 127.0.0.1 intercepta localhost; está en el «entorno» de los descriptores).")
    return "\n".join([
        "# MEMORY.md — memoria curada de Bridge", "",
        "Hechos curados, decisiones y preferencias. Bridge la inyecta al empezar cada tarea, junto con "
        "la nota de hoy y la de ayer (nunca el historial entero). Edítala a mano cuando quieras: cada "
        "sección va con fecha («## AAAA-MM-DD — tema») para que la sync con la VM sea por diferencia.", "",
        f"## {hoy} — Origen de esta memoria",
        "- Creada en el PC por Bridge sin la copia de la VM (no llegó share\\inbox\\memoria-semilla\\): "
        "solo lleva lo que la app ya sabía. Lo de la VM entra con la primera sync.", "",
        f"## {hoy} — Reglas del usuario (de rules.json)",
        *([f"- {t}" for t in reglas] or ["- (no hay reglas activas)"]), "",
        f"## {hoy} — Datos del PC (de la configuración de Bridge)", *pc, "",
        f"## {hoy} — Decisiones",
        "- OpenClaw no se usa; su memoria en Markdown solo se estudió como referencia de diseño.",
        "- La memoria vive en Markdown en memory\\ (MEMORY.md + una nota por día), legible y editable; "
        "sin base de datos, sin búsqueda vectorial y sin captura automática.", ""])


def mem_iniciar(origen="arranque"):
    """Crea memory\\ si falta. MEMORY.md: si la VM dejo share\\inbox\\memoria-semilla\\,
    la primera sync la trae; si no, una minima. Siempre la nota de hoy y la
    sesion actual. Nunca pisa nada que ya exista."""
    info = {"carpeta": str(MEMORY_DIR), "creados": [], "semilla": None}
    with _MEM_LOCK:
        MEMORY_DIR.mkdir(parents=True, exist_ok=True)
        m = MEMORY_DIR / "MEMORY.md"
        semilla = INBOX / "memoria-semilla"
        if not m.exists() and (semilla / "MEMORY.md").is_file():
            info["semilla"] = mem_sync(semilla, origen="primera sync (semilla de la VM)")
        if not m.exists():
            _mem_escribir(m, _mem_memory_minima())
            info["creados"].append("MEMORY.md (mínima: no llegó la semilla de la VM)")
            info["falta_semilla"] = str(semilla / "MEMORY.md")
        p = mem_nota(mem_hoy())
        if not p.exists():
            _mem_escribir(p, _mem_cabecera_nota(mem_hoy()))
            info["creados"].append(p.name)
        s = MEMORY_DIR / "sesion-actual.md"
        if not s.exists():
            _mem_escribir(s, _mem_cabecera_sesion(None))
            info["creados"].append(s.name)
    if info["creados"]:
        log(f"memoria: {origen}: creados en {MEMORY_DIR}: {', '.join(info['creados'])}")
        _mem_registro("iniciar", origen=origen, creados=info["creados"], carpeta=str(MEMORY_DIR))
    return info


def _mem_recortar(texto, n, del_final):
    """Recorta a n caracteres: MEMORY.md se queda el principio; una nota del
    dia, el final (lo mas reciente). Dice cuanto quedo fuera."""
    if len(texto) <= n:
        return texto, False
    fuera = len(texto) - n
    aviso = f"[… recortado para que quepa: {fuera} caracteres más en el archivo …]"
    return ((aviso + "\n" + texto[-n:]) if del_final else (texto[:n] + "\n" + aviso)), True


def mem_bloque_prompt(task):
    """Texto de memoria que va al prompt: MEMORY.md + la nota de hoy + la de
    ayer, NUNCA notas mas viejas. Una sola carga por tarea (queda en el
    resultado como memoria_cargada y en el registro)."""
    tid = str(task.get("id"))
    if tid in _MEM_CARGA:
        return _MEM_CARGA[tid]["texto"]
    if not mem_activa(task):
        _MEM_CARGA[tid] = {"texto": "", "registro": {"cargada": False, "motivo": "memoria apagada (task o ajustes)"
                                                     if LANE != "b" else "carril B: sin memoria"}}
        return ""
    if not (MEMORY_DIR / "MEMORY.md").exists() or not mem_nota(mem_hoy()).exists():
        mem_iniciar("primera tarea del día")
    cfg = mem_cfg()
    eng = get_engine(task.get("motor") or default_motor()) or {}
    presupuesto, fuente = int(cfg.get("max_caracteres") or 12000), "settings.json → memoria.max_caracteres"
    try:
        ctx, _f = _contexto_juez(eng) if eng else (None, "sin dato")
    except Exception:
        ctx = None
    if isinstance(ctx, int) and ctx > 0 and ctx * 3 // 4 < presupuesto:
        presupuesto = ctx * 3 // 4  # 25 % de la ventana (3 caracteres por token)
        fuente = f"25 % del contexto del motor ({ctx} tokens, descriptor de engines.json)"
    hoy = mem_hoy()
    ayer = hoy - timedelta(days=1)
    piezas = [("MEMORY.md", MEMORY_DIR / "MEMORY.md", False, 0.5),
              (f"Nota de hoy ({hoy.isoformat()}.md)", mem_nota(hoy), True, 0.3),
              (f"Nota de ayer ({ayer.isoformat()}.md)", mem_nota(ayer), True, 0.2)]
    if _tarea_de_grupo(task):  # la memoria larga nunca entra en un contexto de grupo (fugas)
        piezas = piezas[1:]
        log(f"memoria [{tid}]: contexto de grupo: MEMORY.md no se carga")
    textos = []
    for titulo, p, fin, cuota in piezas:
        try:
            textos.append((titulo, p, fin, cuota, p.read_text(encoding="utf-8").strip()))
        except OSError:
            textos.append((titulo, p, fin, cuota, None))
    # Reparto: cada archivo su cuota; lo que sobra de uno pasa a los demas.
    libres = presupuesto - sum(min(len(t or ""), int(presupuesto * c)) for _a, _b, _c, c, t in textos)
    reg = {"cargada": True, "carpeta": str(MEMORY_DIR), "archivos": [], "presupuesto_caracteres": presupuesto,
           "fuente_presupuesto": fuente}
    partes = []
    for titulo, p, fin, cuota, t in textos:
        if t is None:
            reg["archivos"].append({"archivo": p.name, "inyectado": False, "motivo": "no existe"})
            if p.name.startswith(ayer.isoformat()):
                reg["ayer"] = f"no existe {p.name}: se carga solo la de hoy"
                partes.append(f"--- Nota de ayer ({p.name}): no existe; solo se carga la de hoy ---")
            continue
        n = min(len(t), int(presupuesto * cuota))
        if n < len(t) and libres > 0:
            extra = min(libres, len(t) - n)
            n, libres = n + extra, libres - extra
        cuerpo, rec = _mem_recortar(t, n, fin)
        partes.append(f"--- {titulo} ---\n{cuerpo}")
        reg["archivos"].append({"archivo": p.name, "inyectado": True, "caracteres": len(cuerpo),
                                "caracteres_archivo": len(t), "recortado": rec})
    try:
        viejas = sorted(x.name for x in MEMORY_DIR.iterdir() if _MEM_NOTA_RE.match(x.name)
                        and x.name < ayer.isoformat())
    except OSError:
        viejas = []
    reg["no_cargadas"] = {"notas_mas_viejas": len(viejas), "ejemplo": viejas[-3:]}
    who = str(load_settings().get("user_name") or "").strip()
    texto = ("MEMORIA" + (f" DE {who.upper()}" if who else "") + f" (archivos Markdown en {MEMORY_DIR}; "
             "solo se cargan MEMORY.md, la nota de hoy y la de ayer, nunca el historial entero; "
             "si algo choca con el encargo, manda el encargo):\n" + "\n\n".join(partes)
             + "\n--- Fin de la memoria ---\n\n")
    reg["total_caracteres"] = len(texto)
    _MEM_CARGA[tid] = {"texto": texto, "registro": reg}
    if len(_MEM_CARGA) > 300:
        for k in list(_MEM_CARGA)[:100]:
            _MEM_CARGA.pop(k, None)
    iny = [f"{a['archivo']} ({a['caracteres']} car.{', recortado' if a['recortado'] else ''})"
           for a in reg["archivos"] if a.get("inyectado")]
    log(f"memoria [{tid}]: inyectados {', '.join(iny) or 'ninguno'}"
        + (f"; {reg['ayer']}" if reg.get("ayer") else "")
        + f"; total {len(texto)} car.; {len(viejas)} notas más viejas no se cargan")
    _mem_registro("carga", tarea=tid, archivos=reg["archivos"], ayer=reg.get("ayer"),
                  total_caracteres=len(texto), notas_mas_viejas_no_cargadas=len(viejas))
    return texto


# ---- «recuerda esto»
_MEM_DURADERO = re.compile(r"\b(siempre|nunca|jamas|prefier\w*|preferencia|me gusta\w*|no me gusta\w*|"
                           r"a partir de|de ahora en adelante|regla|decid\w*|decision|mi \w+ es|"
                           r"mis \w+ son|odio|quiero que)\b")
_MEM_EPISODICO = re.compile(
    r"\b(hoy|ayer|anoche|manana|pasado manana|esta (?:manana|tarde|noche|semana)|ahora|ahorita|"
    r"acabo de|hace (?:un rato|\d+)|este (?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)|"
    r"a las \d{1,2}|\d{1,2} ?(?:de )?(?:ene|feb|mar|abr|may|jun|jul|ago|sep|set|oct|nov|dic)\w*|"
    r"\d{4}-\d{2}-\d{2}|\d{1,2}/\d{1,2}(?:/\d{2,4})?)\b")
_MEM_RECUERDA_RE = re.compile(r"^\s*recuerda\s+esto\b\s*(\((?P<q>[^)]{0,30})\))?\s*(?P<q2>para siempre|hoy)?"
                              r"\s*[:,.\-–—]?\s*(?P<hecho>.*)$", re.I | re.S)


def mem_clasificar(hecho, forzar=None):
    """('memory'|'nota', porque). Duradero (preferencia, decision, regla) ->
    MEMORY.md; de un dia concreto (fecha, «hoy», «ayer»…) -> nota del dia."""
    n = _norm(hecho)
    if forzar in ("para siempre", "siempre", "duradero", "memory"):
        return "memory", "lo pediste «para siempre»"
    if forzar in ("hoy", "dia", "nota"):
        return "nota", "lo pediste para hoy"
    m = _MEM_DURADERO.search(n)
    if m:
        return "memory", f"es duradero («{m.group(0)}»)"
    m = _MEM_EPISODICO.search(n)
    if m:
        return "nota", f"es de un día concreto («{m.group(0)}»)"
    return "memory", "no lleva fecha ni «hoy/ayer»: se guarda como hecho duradero"


def _mem_anadir_memory(hecho):
    """Anade una vinieta a «## <hoy> — Recordado por el usuario» de MEMORY.md
    (la crea al final si no esta). No toca ninguna otra seccion."""
    m = MEMORY_DIR / "MEMORY.md"
    titulo = f"## {mem_hoy().isoformat()} — Recordado por el usuario"
    with _MEM_LOCK:
        if not m.exists():
            mem_iniciar("recuerda esto")
        t = m.read_text(encoding="utf-8")
        lineas = t.split("\n")
        try:
            i = next(k for k, x in enumerate(lineas) if x.strip() == titulo)
        except StopIteration:
            t = t.rstrip("\n") + f"\n\n{titulo}\n- {hecho}\n"
        else:
            j = next((k for k in range(i + 1, len(lineas)) if lineas[k].startswith("## ")), len(lineas))
            while j > i + 1 and not lineas[j - 1].strip():
                j -= 1
            lineas.insert(j, f"- {hecho}")
            t = "\n".join(lineas)
            if not t.endswith("\n"):
                t += "\n"
        _mem_escribir(m, t)
    return m


def mem_recuerda(texto, origen="app"):
    """«recuerda esto: <hecho>». Escribe donde toca y devuelve dónde (nunca
    en silencio: el mensaje lo dice y el archivo se puede abrir)."""
    mm = _MEM_RECUERDA_RE.match(texto or "")
    hecho = re.sub(r"\s+", " ", (mm.group("hecho") if mm else texto) or "").strip().strip("«»\"'")
    if not hecho:
        return {"ok": False, "mensaje": "Dime qué recordar: «recuerda esto: …». No guardé nada."}
    hecho = hecho[:600]
    forzar = _norm((mm.group("q") or mm.group("q2") or "").strip()) if mm else None
    destino, porque = mem_clasificar(hecho, forzar or None)
    try:
        if destino == "memory":
            p = _mem_anadir_memory(hecho)
            donde = f"MEMORY.md (hechos duraderos), sección «{mem_hoy().isoformat()} — Recordado por el usuario»"
        else:
            # El pedido tal cual tambien queda: se sabe de donde salio el hecho.
            pedido = re.sub(r"\s+", " ", texto or "").strip()[:700]
            p = mem_anadir_nota(f"recuerda esto ({origen})", [f"- {hecho}", f"  - Pedido tal cual: «{pedido}»"])
            donde = f"la nota de hoy ({p.name})"
    except OSError as e:
        log(f"memoria: «recuerda esto» NO se pudo guardar ({e})")
        return {"ok": False, "mensaje": f"No se pudo guardar en la memoria: {e}. No quedó nada escrito."}
    # Comprobado contra el archivo real: si no esta, no se dice que se guardo.
    ok = hecho in p.read_text(encoding="utf-8")
    msg = (f"Guardado en {donde}: «{hecho}». Porque {porque}. Archivo: {p}" if ok else
           f"Lo intenté pero no lo encuentro en {p}: no se guardó.")
    log(f"memoria: recuerda esto ({origen}) -> {p} [{destino}; {porque}]: {hecho[:120]}")
    _mem_registro("recuerda", origen=origen, archivo=str(p), destino=destino, porque=porque, hecho=hecho,
                  comprobado=ok)
    return {"ok": ok, "mensaje": msg, "ruta": str(p), "destino": destino, "porque": porque, "hecho": hecho}


# ---- sesion actual y snapshot de /nuevo
def _mem_cabecera_sesion(snapshot_anterior):
    ahora = datetime.now(TZ_CARACAS).strftime("%Y-%m-%d %H:%M")
    return (f"# Sesión actual (empezó el {ahora})\n\n"
            "Lo que se hizo en esta sesión (una entrada por tarea). Con /nuevo se resume en un "
            "snapshot-AAAA-MM-DD-<tema>.md y se empieza otra; esta sesión no se inyecta en las tareas."
            + (f"\nLa sesión anterior quedó en {snapshot_anterior}." if snapshot_anterior else "") + "\n")


def mem_sesion_anotar(task, result):
    """Una entrada por tarea en memory\\sesion-actual.md (lo que /nuevo resume)."""
    if not mem_activa(task) or result.get("status") is None:
        return
    enc = re.sub(r"\s+", " ", task.get("prompt") or "").strip()[:400]
    res = re.sub(r"\s+", " ", (result.get("result") or result.get("error") or "")).strip()[:600]
    s = MEMORY_DIR / "sesion-actual.md"
    try:
        with _MEM_LOCK:
            if not s.exists():
                _mem_escribir(s, _mem_cabecera_sesion(None))
            with open(s, "a", encoding="utf-8") as f:
                f.write(f"\n## {_mem_hora()} · tarea {task['id']} ({task.get('motor')})\n"
                        f"- Encargo: {enc}\n- Resultado ({result.get('status')}): {res or '(sin texto)'}\n")
    except OSError as e:
        log(f"memoria: no se pudo anotar la sesión ({e})")


_MEM_VACIAS = set("para como pero esta este esto unas unos sobre desde hasta cada todo toda todos todas "
                  "tarea tareas haz hacer escribe solo sola entre donde cuando porque tiene tienen".split())


def _mem_slug(t, n=40):
    s = re.sub(r"[^a-z0-9]+", "-", _norm(t)).strip("-")
    return (s[:n].rstrip("-") or "sesion")


def _mem_tema_extractivo(texto):
    pal = [w for w in re.findall(r"[a-záéíóúñü]{4,}", _norm(texto)) if w not in _MEM_VACIAS]
    cuenta = {}
    for w in pal:
        cuenta[w] = cuenta.get(w, 0) + 1
    top = sorted(cuenta, key=lambda w: (-cuenta[w], pal.index(w)))[:3]
    return " ".join(top) or "sesion"


def _mem_gratis(eng):
    """True si el descriptor declara costo $0 (0.0 o {"fijo": 0}) en salida o
    extraer. Un costo que «dice el motor al terminar» no cuenta como gratis."""
    for sec in ("salida", "extraer"):
        c = (eng.get(sec) or {}).get("costo")
        if isinstance(c, dict):
            c = c.get("fijo")
        if isinstance(c, (int, float)) and not isinstance(c, bool):
            return c == 0
    return False


def _mem_motor_resumen():
    """El motor del snapshot: memoria.motor_resumen o el primero de
    revision.orden (engines.json) que responda. None = resumen sin modelo.
    Sin motor_resumen puesto a mano, solo motores de $0 (salida.costo = 0 en
    el descriptor): la memoria nunca gasta dinero sin que Leandro lo pida."""
    cfg = mem_cfg()
    cands = [cfg["motor_resumen"]] if cfg.get("motor_resumen") else \
        [s.get("motor") for s in (_rev_cfg().get("orden") or []) if isinstance(s, dict)]
    for mid in cands:
        eng = get_engine(mid or "")
        if not eng or eng.get("tipo") not in ("cli_sincrono", "api_sincrona"):
            continue
        if not cfg.get("motor_resumen") and not _mem_gratis(eng):
            continue
        ok, why = engine_status(mid)
        if ok and (not eng.get("servidor") or why == "responde"):
            return mid
    return None


def _mem_llamar(motor_id, prompt, cwd, session_id=None, timeout_min=5):
    """Un turno aparte (silencioso) con el motor, leyendo SOLO su descriptor.
    No toca el vivo de la tarea ni guarda historial nuevo. -> dict."""
    eng = get_engine(motor_id) or {}
    out = {"motor": motor_id, "ok": False, "texto": "", "error": None, "segundos": None, "cost_usd": None,
           "reanudo_sesion": bool(session_id)}
    t0 = time.time()
    try:
        if eng.get("tipo") == "cli_sincrono":
            rt = {"id": f"memoria-{int(t0)}", "cwd": cwd or str(INBOX), "timeout_min": timeout_min,
                  "modelo": None, "session_id": session_id, "prompt": "", "allowed_tools": None,
                  "permission_mode": None}
            r = _base_result(rt, motor_id)
            _run_cli_engine(rt, motor_id, eng, r, prompt, abilities=False, rol="revision")
            out.update(ok=r.get("status") == "ok", texto=r.get("result") or "", error=r.get("error"),
                       cost_usd=r.get("cost_usd"))
        elif eng.get("tipo") == "api_sincrona":
            # _local_model resuelve '@ollama_por_defecto' / '@ajuste:...': sin
            # eso Ollama recibia el alias tal cual (400: invalid model name).
            model = _local_model(eng, {}) or None
            ok, why = (ensure_llama_server(eng, model) if eng.get("servidor")
                       else engine_status_rt(eng, autostart=True))
            if not ok:
                raise LocalCallError(f"no disponible: {why}")
            body = _fill(eng.get("cuerpo") or {}, {"mensajes": [{"role": "user", "content": prompt}],
                                                    "modelo": model, "prompt": prompt})
            if (eng.get("modelo") or {}).get("campo"):
                body[eng["modelo"]["campo"]] = model
            data = _http_local("POST", eng["url"], body, timeout=timeout_min * 60)
            txt = _get_path(data, (eng.get("salida") or {}).get("texto"))
            out.update(ok=isinstance(txt, str) and bool(txt.strip()), texto=txt or "", cost_usd=0.0,
                       error=None if txt else "respondió sin texto")
        else:
            out["error"] = f"el motor {motor_id} ({eng.get('tipo')}) no sirve para un turno de texto"
    except Exception as e:
        out["error"] = f"{type(e).__name__}: {e}"[:300]
    out["segundos"] = round(time.time() - t0, 2)
    return out


def mem_nuevo(origen="app"):
    """/nuevo: resume la sesion actual en memory\\snapshot-AAAA-MM-DD-<tema>.md
    (nunca pisa otro), archiva la sesion en memory\\sesiones\\ y empieza una
    nueva. Las tareas siguientes arrancan solo con MEMORY.md + hoy + ayer."""
    s = MEMORY_DIR / "sesion-actual.md"
    with _MEM_LOCK:
        if not MEMORY_DIR.exists():
            mem_iniciar("/nuevo")
        try:
            txt = s.read_text(encoding="utf-8")
        except OSError:
            txt = ""
    entradas = [u for k, u in _mem_unidades(txt) if k != "(inicio)"]
    if not entradas:
        with _MEM_LOCK:
            _mem_escribir(s, _mem_cabecera_sesion(None))
        log(f"memoria: /nuevo ({origen}): la sesión estaba vacía; no hay snapshot que guardar")
        return {"ok": True, "snapshot": None, "mensaje": "La sesión estaba vacía (ninguna tarea): no hay nada "
                                                          "que resumir. Empieza una sesión nueva."}
    cuerpo = "\n\n".join(entradas)
    motor = _mem_motor_resumen()
    resumen, como, tema = None, "sin modelo (resumen extractivo: los encargos tal cual)", None
    if motor:
        r = _mem_llamar(motor, "Resume esta sesión de trabajo para guardarla como snapshot en la memoria.\n"
                        "Primera línea, exactamente: TEMA: <de 2 a 5 palabras>\nDespués, de 3 a 8 viñetas "
                        "«- » con lo que se hizo, lo que se decidió y lo que quedó pendiente. Solo lo que "
                        "está en el texto; nada inventado.\n\nSESIÓN:\n" + cuerpo[-6000:], None)
        if r["ok"]:
            lin = [x.strip() for x in r["texto"].strip().splitlines() if x.strip()]
            mt = re.match(r"^\**\s*tema\s*:\s*\**\s*(.+)$", lin[0], re.I) if lin else None
            tema = mt.group(1).strip(" *.") if mt else None
            vin = [("- " + re.sub(r"^[-*•]\s*", "", x)) for x in lin[1 if mt else 0:]
                   if re.match(r"^[-*•]\s+", x)][:8]
            if vin:
                resumen, como = "\n".join(vin), f"lo resumió {get_engine(motor).get('nombre') or motor} ({r['segundos']} s)"
        if resumen is None:
            como += f" — el modelo {motor} no dio un resumen válido ({r.get('error') or 'sin viñetas'})"
    if resumen is None:
        encs = re.findall(r"^- Encargo: (.*)$", cuerpo, re.M)
        resumen = "\n".join(f"- {e[:200]}" for e in encs[:8]) or "- (sin encargos)"
    tema = tema or _mem_tema_extractivo(" ".join(re.findall(r"^- Encargo: (.*)$", cuerpo, re.M)))
    hoy = mem_hoy().isoformat()
    base = f"snapshot-{hoy}-{_mem_slug(tema)}"
    ahora = datetime.now(TZ_CARACAS).strftime("%Y-%m-%d %H:%M")
    texto = (f"# Snapshot de sesión — {ahora} — {tema}\n\n"
             f"Guardado por /nuevo ({origen}) antes de empezar una sesión nueva. {len(entradas)} tareas.\n\n"
             f"## Resumen\n{resumen}\n\n(Resumen: {como}.)\n\n## Tareas de la sesión\n\n{cuerpo}\n")
    with _MEM_LOCK:
        k = 1
        while True:
            p = MEMORY_DIR / (f"{base}.md" if k == 1 else f"{base}-{k}.md")
            try:
                with open(p, "x", encoding="utf-8") as f:  # «x»: nunca pisa un snapshot anterior
                    f.write(texto)
                break
            except FileExistsError:
                k += 1
        arch = MEMORY_DIR / "sesiones" / f"sesion-{datetime.now(TZ_CARACAS).strftime('%Y%m%d-%H%M%S')}.md"
        arch.parent.mkdir(parents=True, exist_ok=True)
        try:
            os.replace(s, arch)  # la sesion se archiva, no se borra
        except OSError as e:
            log(f"memoria: /nuevo: no se pudo archivar la sesión ({e}); se deja donde estaba")
            arch = None
        _mem_escribir(s, _mem_cabecera_sesion(p.name))
    mem_anadir_nota("/nuevo", [f"- Snapshot de la sesión anterior ({len(entradas)} tareas): {p.name}"
                               + (f" (sesión archivada en sesiones\\{arch.name})" if arch else "")])
    log(f"memoria: /nuevo ({origen}): snapshot {p} ({len(entradas)} tareas; {como})")
    _mem_registro("snapshot", origen=origen, archivo=str(p), tareas=len(entradas), resumen_como=como,
                  sesion_archivada=str(arch) if arch else None)
    return {"ok": True, "snapshot": str(p), "tareas": len(entradas), "resumen_como": como,
            "mensaje": f"Sesión nueva. La anterior ({len(entradas)} tareas) quedó resumida en {p}."}


def mem_comando(texto, origen="app"):
    """None si no es un comando de memoria; si lo es, lo hace y devuelve
    {"ok", "mensaje", "ruta"?} para confirmarlo en pantalla."""
    t = (texto or "").strip()
    if re.match(r"^/nuevo\b", t, re.I):
        return mem_nuevo(origen)
    if _MEM_RECUERDA_RE.match(t):
        return mem_recuerda(t, origen)
    return None


# ---- flush antes de compactar / al terminar una fase
def _mem_umbrales(ctx, cfg):
    """(reserva, suave) escalados a la ventana del motor: 20.000 + 4.000 para
    200.000 tokens (OpenClaw); con 8.192 quedan 819 + 163."""
    ref = int(cfg.get("contexto_referencia_tokens") or 200000)
    f = min(1.0, ctx / ref) if ref > 0 else 1.0
    return int(int(cfg.get("reserva_tokens") or 20000) * f), int(int(cfg.get("flush_suave_tokens") or 4000) * f)


def _mem_flush_motivo(task, result, eng, cfg):
    """(motivo | None, datos): fin de fase, contexto cerca del limite, o la
    proxima vuelta compactaria el historial local."""
    datos = {}
    if cfg.get("contexto_tokens"):
        ctx, fuente = int(cfg["contexto_tokens"]), "settings.json → memoria.contexto_tokens"
    else:
        ctx, fuente = _contexto_juez(eng)
    uso = result.get("uso") if isinstance(result.get("uso"), dict) else {}
    # El mayor de lo que reporta el motor y lo estimado por caracteres: un
    # servidor con cache (llama-server: timings.prompt_n) solo cuenta lo no cacheado.
    rep = int(uso.get("tokens_in") or 0) + int(uso.get("tokens_out") or 0)
    est = (len(prompt_de_tarea(task)) + len(result.get("result") or "")) // 3
    usados, como = (rep, "lo reportó el motor") if rep >= est else \
        (est, "estimado (3 caracteres por token)" + (f"; el motor reportó {rep}" if rep else ""))
    datos.update(contexto_tokens=ctx, fuente_contexto=fuente, tokens_usados=usados, conteo=como)
    if isinstance(ctx, int) and ctx > 0:
        reserva, suave = _mem_umbrales(ctx, cfg)
        umbral = ctx - reserva - suave
        datos.update(reserva_tokens=reserva, flush_suave_tokens=suave, umbral_tokens=umbral)
        if usados >= umbral:
            datos["motivo_corto"] = f"cerca del límite de contexto ({usados}/{ctx} tokens)"
            return (f"la tarea se acerca al límite de contexto ({usados} de {ctx} tokens; el flush salta a "
                    f"partir de {umbral} = {ctx} − reserva {reserva} − umbral suave {suave})"), datos
    sid = result.get("session_id")
    if (eng.get("sesion") or {}).get("tipo") == "historial_local" and sid and task.get("siguiente_fase") is None:
        try:
            hist = sum(len(m.get("content") or "") for m in _session_load(sid))
        except Exception:
            hist = 0
        datos["historial_caracteres"] = hist
        if hist >= 14000 * 0.85:  # _trim_messages compacta a partir de 14.000
            datos["motivo_corto"] = f"antes de compactar el historial ({hist} caracteres)"
            return (f"la próxima vuelta compactaría el historial de la sesión ({hist} caracteres; se "
                    "recorta a partir de 14.000)"), datos
    if cfg.get("flush_fin_de_fase") and (task.get("fase") or task.get("siguiente_fase")):
        datos["motivo_corto"] = f"fin de la {task.get('fase') or 'fase 1'}"
        return f"terminó la fase «{task.get('fase') or 'fase 1'}» de {task.get('fase_base') or task['raiz']}", datos
    return None, datos


def mem_flush_tal_vez(task, result):
    """Despues del motor y ANTES de la ronda / fase siguiente: si hace falta,
    un turno silencioso le pide al modelo los hechos duraderos y se anaden a la
    nota de hoy (solo anadir). Devuelve lo que paso (va al resultado)."""
    if not mem_activa(task) or result.get("status") != "ok" or task.get("motor") == "api":
        return None
    cfg = mem_cfg()
    eng = get_engine(task.get("motor") or "") or {}
    motivo, datos = _mem_flush_motivo(task, result, eng, cfg)
    if not motivo:
        return dict(datos, hecho=False, motivo="no hizo falta (ni fin de fase ni cerca del límite)")
    fm = cfg.get("flush_motor") or "mismo"
    motor = task.get("motor") if fm == "mismo" else fm
    meng = get_engine(motor or "") or {}
    gratis = _mem_gratis(meng)
    # «mismo» solo si ese motor es de $0; uno de pago solo si se nombra a mano
    # en memoria.flush_motor (regla: preguntar antes de gastar dinero).
    if meng.get("tipo") not in ("cli_sincrono", "api_sincrona") or (fm == "mismo" and not gratis):
        motor = _mem_motor_resumen()
        meng = get_engine(motor or "") or {}
    if not motor:
        log(f"memoria [{task['id']}]: flush NO hecho ({motivo}): ningún motor de texto disponible")
        _mem_registro("flush", tarea=task["id"], hecho=False, motivo=motivo, error="sin motor")
        return dict(datos, hecho=False, motivo=motivo, error="ningún motor de texto disponible")
    sid = result.get("session_id")
    reanuda = (motor == task.get("motor") and sid and soporta_reanudar(meng)
               and (meng.get("sesion") or {}).get("tipo") != "historial_local")
    intro = ("Turno silencioso de memoria (no es parte de la tarea; tu respuesta no se le enseña a nadie, "
             f"solo se guarda en la nota del día). Antes de seguir ({motivo}), ")
    # Las instrucciones van DESPUES del material: con un encargo largo, un
    # modelo pequeno olvida lo que se le pidio arriba (medido con Hermes 8B).
    instr = ("destila los HECHOS DURADEROS que valga la pena recordar mañana: decisiones tomadas, datos "
             "comprobados (rutas, puertos, versiones, resultados medidos), preferencias del usuario y "
             "pendientes concretos. Nada de relleno, nada que no esté en el encargo o en el resultado, nada "
             "inventado. Responde SOLO con viñetas que empiecen por «- » (máximo 8, una línea cada una). "
             "Si no hay nada duradero, responde exactamente: NADA_QUE_GUARDAR")
    pedido = intro + instr
    if not reanuda:
        pedido = intro + "lee el ENCARGO y el RESULTADO de abajo."
        # Sin la sesion, el motor ve el encargo y el resultado: tanto como quepa
        # en SU contexto (descriptor), 60 % encargo / 40 % resultado; si no cabe,
        # principio + final (y se dice).
        try:
            fctx, _f = _contexto_juez(meng)
        except Exception:
            fctx = None
        lim = max(4000, int(((fctx or 4000) - 1200) * 3 * 0.8))

        def _cabe(t, n):
            if len(t) <= n:
                return t
            return t[:n // 2] + f"\n[… {len(t) - n} caracteres del medio no caben en el contexto …]\n" + t[-n // 2:]
        entero = (pedido + "\n\nENCARGO:\n" + (task.get("prompt") or "")
                  + "\n\nRESULTADO:\n" + (result.get("result") or ""))
        n_ent, _como = _contar_tokens(meng, entero) if fctx else (len(entero) // 3, "")
        if fctx and n_ent + 800 <= fctx:
            pedido = entero  # cabe entero (contado con el tokenizador del motor si lo tiene)
        else:
            pedido += ("\n\nENCARGO:\n" + _cabe(task.get("prompt") or "", int(lim * 0.6))
                       + "\n\nRESULTADO:\n" + _cabe(result.get("result") or "", int(lim * 0.4)))
        pedido += "\n\nAHORA, con lo de arriba: " + instr
    state["paso"] = f"Guardando memoria de {task['raiz']} (flush antes de seguir)"
    log(f"memoria [{task['id']}]: flush: {motivo}; turno silencioso con {motor}"
        + (" (misma sesión)" if reanuda else " (encargo + resultado en el prompt)"))
    r = _mem_llamar(motor, pedido, task.get("cwd"), sid if reanuda else None)
    info = dict(datos, motivo=motivo, motor=motor, reanudo_sesion=bool(reanuda), segundos=r["segundos"],
                cost_usd=r.get("cost_usd"), at=_now_iso())
    if not r["ok"]:
        info.update(hecho=False, error=r.get("error"))
        log(f"memoria [{task['id']}]: flush falló ({r.get('error')}); no se escribió nada")
    else:
        txt = r["texto"].strip()
        vin = [("- " + re.sub(r"^[-*•]\s*", "", x.strip()))[:300] for x in txt.splitlines()
               if re.match(r"^\s*[-*•]\s+\S", x)][:8]
        if not vin:
            info.update(hecho=False, nada_que_guardar="NADA_QUE_GUARDAR" in txt,
                        error=None if "NADA_QUE_GUARDAR" in txt else "respuesta sin viñetas: no se guardó")
        else:
            # Lo destila el modelo: se dice quien y que no esta verificado.
            p = mem_anadir_nota(f"flush ({task['id']}): {datos.get('motivo_corto') or motivo[:60]} — lo destiló "
                                f"{motor}, sin verificar", vin)
            info.update(hecho=True, escrito_en=str(p), hechos=len(vin))
            log(f"memoria [{task['id']}]: flush: {len(vin)} hechos añadidos a {p}")
    state["paso"] = None
    _mem_registro("flush", tarea=task["id"], **{k: v for k, v in info.items() if k != "at"})
    return info


# ---- sync por diferencia con la VM
def _mem_unidades(text):
    """[(clave, bloque)]: un bloque por encabezado «## ». Lo de antes del
    primero es «(inicio)». Encabezados repetidos: «clave #2»."""
    out, key, cur, seen = [], "(inicio)", [], {}
    for line in (text or "").replace("\r\n", "\n").split("\n"):
        if line.startswith("## "):
            out.append((key, cur))
            k = re.sub(r"\s+", " ", line[3:]).strip()
            seen[k] = seen.get(k, 0) + 1
            key, cur = (k if seen[k] == 1 else f"{k} #{seen[k]}"), [line]
        else:
            cur.append(line)
    out.append((key, cur))
    return [(k, "\n".join(b).strip("\n")) for k, b in out if k != "(inicio)" or "\n".join(b).strip()]


def _mem_h(bloque):
    norm = "\n".join(x.rstrip() for x in (bloque or "").strip().split("\n"))
    return hashlib.sha256(norm.encode("utf-8")).hexdigest()[:16]


def _mem_sync_estado():
    try:
        d = json.loads((MEMORY_DIR / "sync" / "estado.json").read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _mem_aviso_conflicto(archivo, clave, pc, vm, ts):
    """Las dos versiones se guardan: la del PC sigue en su archivo; la de la VM
    (y una copia de la del PC) va a memory\\conflictos\\. Se avisa."""
    d = MEMORY_DIR / "conflictos"
    d.mkdir(parents=True, exist_ok=True)
    p = d / f"{Path(archivo).stem}--{_mem_slug(clave, 30)}--vm-{ts}.md"
    _mem_escribir(p, f"# Conflicto de sync: {archivo} → «{clave}»\n\n"
                     "La VM y el PC editaron la misma sección. La versión del PC sigue en su archivo; aquí "
                     "están las dos. Elige la que vale (o júntalas) en el archivo y luego borra este cuando "
                     "quieras (Bridge no lo borra).\n\n"
                     f"## Versión de la VM\n\n{vm}\n\n## Versión del PC (copia al {ts})\n\n{pc}\n")
    with open(MEMORY_DIR / "CONFLICTOS.md", "a", encoding="utf-8") as f:
        f.write(f"- {ts}: {archivo} → «{clave}»: las dos versiones en conflictos\\{p.name}\n")
    return p


def _mem_cabecera_defecto(nombre):
    """La cabecera (lo de antes del primer «## ») que Bridge pone al crear el
    archivo. Si el PC la tiene tal cual, una cabecera distinta en la VM no es
    un conflicto: solo cambio la VM (la del PC queda en sync\\anteriores\\)."""
    try:
        if nombre == "MEMORY.md":
            return dict(_mem_unidades(_mem_memory_minima())).get("(inicio)", "")
        if _MEM_NOTA_RE.match(nombre):
            return _mem_cabecera_nota(datetime.strptime(nombre[:10], "%Y-%m-%d").date()).strip("\n")
    except Exception:
        pass
    return ""


def mem_sync(origen_dir=None, origen="sync"):
    """Sync por DIFERENCIA (por secciones «## »), VM -> PC. Lo nuevo de la VM se
    anade; lo que ya existe no se pisa; solo cambio la VM (el PC sigue igual
    que en la ultima sync) -> se toma el de la VM y el anterior queda en
    memory\\sync\\anteriores\\; los dos cambiaron -> conflicto: se guardan las
    dos y se avisa. Despues, la diferencia PC -> VM va a
    share\\outbox\\memoria-pc\\diferencia.json. Devuelve el informe."""
    src = Path(origen_dir) if origen_dir else INBOX / (mem_cfg().get("vm_carpeta") or "memoria-vm")
    ts = datetime.now(TZ_CARACAS).strftime("%Y%m%d-%H%M%S")
    inf = {"origen": str(src), "destino": str(MEMORY_DIR), "at": _now_iso(), "archivos": [],
           "anadidas": 0, "actualizadas": 0, "conflictos": [], "iguales": 0, "solo_pc": 0}
    if not src.is_dir():
        inf["falta"] = f"no existe {src}: la VM no dejó nada para sincronizar"
        _mem_registro("sync", origen_txt=origen, **{k: v for k, v in inf.items() if k != "at"})
        return inf
    with _MEM_LOCK:
        MEMORY_DIR.mkdir(parents=True, exist_ok=True)
        est = _mem_sync_estado()
        base, visto = est.setdefault("base", {}), est.setdefault("vm_conflicto_visto", {})
        for vf in sorted(src.iterdir()):
            if not vf.is_file() or not _MEM_SYNC_RE.match(vf.name):
                continue
            try:
                vtxt = vf.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError) as e:
                inf["archivos"].append({"archivo": vf.name, "error": str(e)})
                continue
            fila = {"archivo": vf.name, "anadidas": [], "actualizadas": [], "conflictos": [], "iguales": 0}
            b, v = base.setdefault(vf.name, {}), visto.setdefault(vf.name, {})
            pf = MEMORY_DIR / vf.name
            vun = _mem_unidades(vtxt)
            if not pf.exists():
                _mem_escribir(pf, vtxt if vtxt.endswith("\n") else vtxt + "\n")
                fila["anadidas"] = [k for k, _u in vun]
                fila["archivo_nuevo"] = True
                for k, u in vun:
                    b[k] = _mem_h(u)
            else:
                ptxt = pf.read_text(encoding="utf-8")
                pun = _mem_unidades(ptxt)
                pmap = dict(pun)
                nuevas, cambios = [], {}
                for k, u in vun:
                    vh = _mem_h(u)
                    if k not in pmap:
                        nuevas.append((k, u))
                        b[k] = vh
                        continue
                    ph = _mem_h(pmap[k])
                    if k == "(inicio)" and k not in b and ph == _mem_h(_mem_cabecera_defecto(vf.name)):
                        b[k] = ph  # cabecera que puso Bridge y nadie toco: no es un conflicto
                    if ph == vh:
                        b[k] = vh
                        fila["iguales"] += 1
                    elif b.get(k) == vh or v.get(k) == vh:
                        continue  # la VM no cambio (o ese conflicto ya se guardo): manda lo del PC
                    elif b.get(k) == ph:
                        cambios[k] = u  # solo cambio la VM
                        b[k] = vh
                    else:
                        cp = _mem_aviso_conflicto(vf.name, k, pmap[k], u, ts)
                        v[k] = vh
                        fila["conflictos"].append({"clave": k, "versiones_en": str(cp)})
                if cambios:
                    ant = MEMORY_DIR / "sync" / "anteriores" / f"{pf.stem}-{ts}.md"
                    _mem_escribir(ant, ptxt)
                    _mem_escribir(pf, "\n\n".join(cambios.get(k, u) for k, u in pun) + "\n")
                    fila["actualizadas"] = [{"clave": k, "anterior_en": str(ant)} for k in cambios]
                if nuevas:
                    ini = [u for k, u in nuevas if k == "(inicio)"]
                    resto = [u for k, u in nuevas if k != "(inicio)"]
                    if ini:  # el PC no tenia cabecera: va al principio (archivo entero de nuevo)
                        _mem_escribir(pf, ini[0] + "\n\n" + pf.read_text(encoding="utf-8"))
                    if resto:  # lo demas, solo anadir al final
                        cur = pf.read_text(encoding="utf-8")
                        with open(pf, "a", encoding="utf-8") as f:
                            f.write(("" if cur.endswith("\n") else "\n") + "\n" + "\n\n".join(resto) + "\n")
                    fila["anadidas"] = [k for k, _u in nuevas]
                fila["solo_pc"] = len([k for k, _u in pun if k not in dict(vun)])
            inf["archivos"].append(fila)
            inf["anadidas"] += len(fila["anadidas"])
            inf["actualizadas"] += len(fila["actualizadas"])
            inf["iguales"] += fila["iguales"]
            inf["solo_pc"] += fila.get("solo_pc", 0)
            inf["conflictos"] += [dict(c, archivo=vf.name) for c in fila["conflictos"]]
        est["ultima_sync"] = {"at": inf["at"], "origen": str(src)}
        _mem_escribir(MEMORY_DIR / "sync" / "estado.json", json.dumps(est, ensure_ascii=False, indent=2))
    inf["exportado"] = mem_exportar(src)
    log(f"memoria: sync ({origen}) desde {src}: {inf['anadidas']} secciones nuevas añadidas, "
        f"{inf['actualizadas']} actualizadas desde la VM, {inf['iguales']} iguales, "
        f"{len(inf['conflictos'])} conflictos")
    if inf["conflictos"]:
        txt = (f"Memoria: {len(inf['conflictos'])} conflicto(s) con la VM; están las dos versiones en "
               f"{MEMORY_DIR / 'conflictos'}")
        log("memoria: AVISO " + txt + ": " + "; ".join(f"{c['archivo']} «{c['clave']}»" for c in inf["conflictos"]))
        try:
            with open(OUTBOX / "memoria-conflictos.jsonl", "a", encoding="utf-8") as f:
                for c in inf["conflictos"]:
                    f.write(json.dumps(dict(c, at=inf["at"]), ensure_ascii=False) + "\n")
        except OSError:
            pass
        toast(f"Memoria: {len(inf['conflictos'])} conflicto(s) con la VM", ("page", "registro"))
        state["memoria_aviso"] = txt
    _mem_registro("sync", origen_txt=origen, **{k: v for k, v in inf.items() if k not in ("exportado", "at")})
    # En cada sync, el historial de Claude Code tambien va a la VM (en un hilo:
    # la primera copia puede tardar; las siguientes solo llevan lo nuevo).
    claude_copia_async(f"sync de memoria ({origen})")
    return inf


def mem_exportar(vm_dir=None):
    """Diferencia PC -> VM: solo las secciones que la VM no tiene (o tiene
    distintas), en share\\outbox\\memoria-pc\\diferencia.json. Nunca el archivo entero."""
    vm_dir = Path(vm_dir) if vm_dir else INBOX / (mem_cfg().get("vm_carpeta") or "memoria-vm")
    uni = []
    with _MEM_LOCK:
        if not MEMORY_DIR.is_dir():
            return None
        for pf in sorted(MEMORY_DIR.iterdir()):
            if not pf.is_file() or not _MEM_SYNC_RE.match(pf.name):
                continue
            try:
                pun = _mem_unidades(pf.read_text(encoding="utf-8"))
                vmap = dict(_mem_unidades((vm_dir / pf.name).read_text(encoding="utf-8"))) \
                    if (vm_dir / pf.name).is_file() else {}
            except (OSError, UnicodeDecodeError):
                continue
            for k, u in pun:
                if k not in vmap or _mem_h(vmap[k]) != _mem_h(u):
                    uni.append({"archivo": pf.name, "clave": k, "hash": _mem_h(u), "contenido": u,
                                "tipo": "nueva" if k not in vmap else "distinta"})
    d = {"_que_es": "Diferencia de memoria PC -> VM (por secciones «## »). La VM añade las «nueva»; una "
                    "«distinta» que la VM también cambió es un conflicto: se guardan las dos versiones.",
         "generado": _now_iso(), "comparado_con": str(vm_dir), "unidades": uni}
    try:
        (OUTBOX / "memoria-pc").mkdir(parents=True, exist_ok=True)
        _mem_escribir(OUTBOX / "memoria-pc" / "diferencia.json", json.dumps(d, ensure_ascii=False, indent=2))
    except OSError:
        return None
    return {"archivo": str(OUTBOX / "memoria-pc" / "diferencia.json"), "unidades": len(uni)}


def _mem_huella(d):
    try:
        return tuple(sorted((x.name, x.stat().st_size, int(x.stat().st_mtime)) for x in Path(d).iterdir()
                            if x.is_file()))
    except OSError:
        return None


def _mem_sync_loop(stop=None):
    """Hilo: cada 20 s, si cambio lo que dejo la VM en share\\inbox\\memoria-vm\\
    (o la semilla share\\inbox\\memoria-semilla\\, que puede llegar despues de
    crear la MEMORY.md minima), sync por diferencia; si cambio la memoria del
    PC, rehace la exportacion."""
    ult, ult_pc = {}, None
    while not (stop and stop.is_set()):
        try:
            if mem_activa():
                vm = INBOX / (mem_cfg().get("vm_carpeta") or "memoria-vm")
                for d, nombre in ((INBOX / "memoria-semilla", "semilla de la VM"), (vm, vm.name)):
                    h = _mem_huella(d)
                    if h is not None and h != ult.get(nombre):
                        mem_sync(d, origen=f"automática (cambió share\\inbox\\{d.name}: {nombre})")
                        ult[nombre] = _mem_huella(d)
                hp = _mem_huella(MEMORY_DIR)
                if hp is not None and hp != ult_pc:
                    mem_exportar(vm)
                    ult_pc = hp
        except Exception as e:
            log(f"memoria: sync automática: {type(e).__name__}: {e}")
        time.sleep(20)


# ---- memoria buscable (t-memoria-buscable): por palabras + fecha, sin
# vectores ni IA generativa. Lee los Markdown POR DEMANDA en cada busqueda
# (nunca carga la memoria entera de antemano). El decaimiento solo ORDENA:
# lo reciente y lo reforzado arriba, lo viejo abajo pero presente. Nada se
# borra por viejo.
_MEM_QUE_SE_RE = re.compile(r"^\s*(?:qu[eé]\s+s[eé]\s+de|que\s+se\s+de|memoria\s*:)\s*(?P<q>.+)$", re.I)
_MEM_FECHA_RE = re.compile(r"(\d{4}-\d{2}-\d{2})")
MEM_MEDIA_VIDA_DIAS = 30


def mem_buscar_ordenado(q, mostrar=30):
    """(resultados, medidas). Cada resultado: texto, archivo, linea, fecha
    (o None = «sin origen registrado»), origen en palabras, refuerzo, puntos."""
    t0 = time.perf_counter()
    toks = [t for t in _norm(q).split() if t]
    hits, leidos, bytes_ = [], 0, 0
    if not toks or not MEMORY_DIR.is_dir():
        return [], {"ms": 0, "archivos": 0, "bytes": 0, "total": 0}
    hoy = mem_hoy()
    for p in MEMORY_DIR.rglob("*.md"):
        try:
            txt = p.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        leidos += 1
        bytes_ += len(txt)
        m = _MEM_FECHA_RE.match(p.stem)
        fecha_archivo = m.group(1) if m else None
        fecha_seccion = None
        for i, line in enumerate(txt.splitlines(), 1):
            if line.lstrip().startswith("#"):
                ms = _MEM_FECHA_RE.search(line)
                fecha_seccion = ms.group(1) if ms else None
            n = _norm(line)
            if all(t in n for t in toks):
                fecha = fecha_archivo or fecha_seccion
                origen = (f"nota diaria del {fecha_archivo}" if fecha_archivo else
                          f"{p.name} (sección del {fecha_seccion})" if fecha_seccion else p.name)
                h_ = {"texto": line.strip()[:240], "archivo": _mem_rel(p), "ruta": str(p), "linea": i,
                      "fecha": fecha, "origen": origen if fecha else f"{p.name}: sin origen registrado"}
                try:  # t-proyectos: lo de otro proyecto sale marcado, nunca como si fuera de este
                    partes = p.relative_to(MEMORY_DIR).parts
                except ValueError:
                    partes = ()
                if len(partes) > 2 and partes[0] == "proyectos":
                    h_["proyecto"] = partes[1]
                    pa = proyecto_activo()
                    if not pa or pa["id"] != partes[1]:
                        h_["origen"] += f" — de OTRO proyecto ({(proyecto_get(partes[1]) or {}).get('nombre', partes[1])})"
                hits.append(h_)
    # refuerzo: el mismo hecho mencionado en varios sitios sube
    claves = [" ".join(sorted(set(_norm(h["texto"]).split()))[:8]) for h in hits]
    for h, k in zip(hits, claves):
        h["refuerzo"] = claves.count(k)
        try:
            dias = (hoy - datetime.fromisoformat(h["fecha"]).date()).days if h["fecha"] else 365
        except ValueError:
            dias = 365
        h["dias"] = max(dias, 0)
        h["puntos"] = round(0.5 ** (h["dias"] / MEM_MEDIA_VIDA_DIAS) + 0.25 * (h["refuerzo"] - 1), 4)
    hits.sort(key=lambda h: -h["puntos"])
    med = {"ms": round((time.perf_counter() - t0) * 1000, 1), "archivos": leidos, "bytes": bytes_,
           "total": len(hits)}
    log(f"memoria: buscar «{q}»: {len(hits)} resultado(s) en {leidos} archivo(s), {bytes_} bytes leídos al momento, "
        f"{med['ms']} ms")
    return hits, med


def _mem_paleta_items(q):
    hits, med = mem_buscar_ordenado(q)
    items = []
    for h in hits[:12]:
        cuando = h["fecha"] or "sin fecha"
        items.append({"id": "_mem_hit", "label": f"{h['texto'][:70]}, {h['origen']} ({cuando})",
                      "fn": lambda r=h["ruta"]: os.startfile(r)})
    if len(hits) > 12:
        items.append({"id": "_mem_mas", "label": f"… y {len(hits) - 12} más (lo viejo sigue abajo, no se borra)",
                      "fn": lambda: os.startfile(str(MEMORY_DIR))})
    if not hits:
        items.append({"id": "_mem_nada", "label": f"No sé nada de «{q}» en la memoria ({med['archivos']} archivos)",
                      "fn": lambda: os.startfile(str(MEMORY_DIR))})
    return items


def _tarea_de_grupo(task):
    """Contexto de grupo (canal de grupo o marcada): ahí NO entra MEMORY.md."""
    c = str(task.get("canal") or "").lower()
    return bool(task.get("grupo")) or "grupo" in c or "group" in c


# ---- notas locales estilo Obsidian, sin su curva (t-notas-obsidian-030).
# Un .md por nota en notas\ (frontmatter: titulo, fecha, etiquetas, proyecto),
# legible y editable a mano: nada de base opaca. [[wikilinks]] + backlinks;
# un enlace a una nota que no existe queda «pendiente» (no se crea vacia).
# La nube es un ESPEJO opcional (carpeta sincronizada), nunca el original.
NOTAS_DIR = Path(os.environ.get("GROWI_BRIDGE_NOTAS") or (APP_DIR / "notas"))
_WIKI_RE = re.compile(r"\[\[([^\[\]|#]{1,120})(?:[|#][^\]]*)?\]\]")
NOTAS_PLANTILLAS = {
    "reunion": ("Reunión", "## Asistentes\n- \n\n## Temas\n- \n\n## Acuerdos\n- \n\n## Siguiente paso\n- \n"),
    "proyecto": ("Proyecto", "## Objetivo\n\n\n## Pendientes\n- [ ] \n\n## Enlaces\n- \n"),
    "idea": ("Idea", "## Chispa\n\n\n## Siguiente paso\n- \n"),
}


def _nota_slug(titulo):
    s = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "", str(titulo)).strip().rstrip(".")
    return (s or "sin título")[:100]


def nota_ruta(titulo):
    return NOTAS_DIR / f"{_nota_slug(titulo)}.md"


def nota_leer(path):
    """{titulo, fecha, etiquetas, proyecto, cuerpo, ruta, enlaces}. Frontmatter simple (clave: valor)."""
    txt = Path(path).read_text(encoding="utf-8")
    meta, cuerpo = {}, txt
    if txt.startswith("---"):
        fin = txt.find("\n---", 3)
        if fin > 0:
            for ln in txt[3:fin].splitlines():
                if ":" in ln:
                    k, v = ln.split(":", 1)
                    meta[k.strip().lower()] = v.strip()
            cuerpo = txt[fin + 4:].lstrip("\n")
    etq = [e.strip().lstrip("#") for e in re.split(r"[,\s]+", meta.get("etiquetas", "").strip("[]")) if e.strip()]
    return {"titulo": meta.get("titulo") or Path(path).stem, "fecha": meta.get("fecha") or None, "etiquetas": etq,
            "proyecto": meta.get("proyecto") or None, "cuerpo": cuerpo, "ruta": str(path),
            "enlaces": sorted({m.group(1).strip() for m in _WIKI_RE.finditer(cuerpo)})}


def nota_escribir(titulo, cuerpo, etiquetas=(), proyecto=None, fecha=None, sobrescribir=False):
    NOTAS_DIR.mkdir(parents=True, exist_ok=True)
    p = nota_ruta(titulo)
    if p.exists() and not sobrescribir:
        raise FileExistsError(str(p))
    fm = ["---", f"titulo: {titulo}", f"fecha: {fecha or mem_hoy().isoformat()}",
          f"etiquetas: {', '.join(etiquetas)}", f"proyecto: {proyecto or ''}", "---", ""]
    p.write_text("\n".join(fm) + cuerpo.rstrip() + "\n", encoding="utf-8")
    return p


def notas_todas():
    if not NOTAS_DIR.is_dir():
        return []
    out = []
    for p in sorted(NOTAS_DIR.glob("*.md")):
        try:
            out.append(nota_leer(p))
        except (OSError, UnicodeDecodeError):
            continue
    return out


def notas_indice():
    """Titulos, backlinks y enlaces pendientes (leido al momento, sin caché opaca)."""
    notas = notas_todas()
    por = {_norm(n["titulo"]): n for n in notas}
    back = {n["titulo"]: [] for n in notas}
    pendientes = {}
    for n in notas:
        for e in n["enlaces"]:
            dest = por.get(_norm(e))
            if dest:
                back[dest["titulo"]].append(n["titulo"])
            else:
                pendientes.setdefault(e, []).append(n["titulo"])
    return {"notas": notas, "backlinks": back, "pendientes": pendientes}


def nota_diaria(fecha=None):
    """Una por día, automática (se crea la primera vez que se pide)."""
    f = (fecha or mem_hoy()).isoformat()
    p = nota_ruta(f)
    if not p.exists():
        nota_escribir(f, f"# {f}\n\n- \n", etiquetas=("diaria",), fecha=f)
        log(f"notas: nota diaria {p.name} creada")
    return p


def notas_parecidas(titulo, umbral=0.75):
    """Duplicados probables por titulo (difflib). Solo avisa: nunca fusiona."""
    import difflib
    t = _norm(titulo)
    return [n["titulo"] for n in notas_todas()
            if difflib.SequenceMatcher(None, t, _norm(n["titulo"])).ratio() >= umbral]


def nota_crear(titulo, plantilla=None, etiquetas=(), proyecto=None, cuerpo=None):
    """(ok, ruta o motivo, parecidas). Con plantilla: su estructura."""
    titulo = str(titulo).strip()
    if not titulo:
        return False, "falta el título", []
    parecidas = [x for x in notas_parecidas(titulo) if _norm(x) != _norm(titulo)]
    if nota_ruta(titulo).exists():
        return False, f"ya existe la nota «{titulo}»", parecidas
    if plantilla in NOTAS_PLANTILLAS:
        nom, est = NOTAS_PLANTILLAS[plantilla]
        cuerpo = (cuerpo or "") + f"# {titulo}\n\n" + est
        etiquetas = tuple(etiquetas) + (plantilla,)
    p = nota_escribir(titulo, cuerpo or f"# {titulo}\n\n", etiquetas, proyecto)
    log(f"notas: creada «{titulo}»" + (f" con la plantilla {plantilla}" if plantilla else "")
        + (f"; ojo, ya hay notas parecidas: {', '.join(parecidas)}" if parecidas else ""))
    return True, str(p), parecidas


def nota_enlazar(origen, destino):
    """Añade [[destino]] al final de la nota origen (si no estaba)."""
    p = nota_ruta(origen)
    if not p.exists():
        return False, f"no existe la nota «{origen}»"
    n = nota_leer(p)
    if _norm(destino) in {_norm(e) for e in n["enlaces"]}:
        return True, f"«{origen}» ya enlazaba a «{destino}»"
    with open(p, "a", encoding="utf-8") as fh:
        fh.write(f"\n- Enlace: [[{destino}]]\n")
    pend = "" if nota_ruta(destino).exists() else " (todavía no existe: queda como enlace pendiente)"
    log(f"notas: «{origen}» → [[{destino}]]{pend}")
    return True, f"enlazado «{origen}» → [[{destino}]]{pend}"


def nota_resumir(titulo, n_frases=3):
    """Resumen EXTRACTIVO y local (sin modelo): títulos de sección y las
    primeras frases con contenido. Se dice que es extractivo."""
    p = nota_ruta(titulo)
    if not p.exists():
        return None
    c = nota_leer(p)["cuerpo"]
    secc = [ln.lstrip("# ").strip() for ln in c.splitlines() if ln.startswith("#")]
    frases = [ln.strip("-* ").strip() for ln in c.splitlines() if ln.strip() and not ln.startswith("#")
              and len(ln.strip("-* [] ")) > 3][:n_frases]
    return f"Resumen extractivo (sin IA) de «{titulo}»: secciones {', '.join(secc) or '—'}; " + (
        "; ".join(frases) if frases else "sin contenido todavía") + "."


def notas_buscar(q):
    """Títulos, etiquetas y contenido; leído al momento. Orden: título > etiqueta > contenido."""
    toks = [t for t in _norm(q).split() if t]
    out = []
    for n in notas_todas():
        donde = ("título" if all(t in _norm(n["titulo"]) for t in toks) else
                 "etiqueta" if all(any(t in _norm(e) for e in n["etiquetas"]) for t in toks) else
                 "contenido" if all(t in _norm(n["cuerpo"]) for t in toks) else None)
        if donde:
            out.append({"titulo": n["titulo"], "donde": donde, "ruta": n["ruta"], "fecha": n["fecha"]})
    out.sort(key=lambda x: {"título": 0, "etiqueta": 1, "contenido": 2}[x["donde"]])
    return out


def nota_capturar(texto, origen="tarea"):
    """Captura en un clic: el texto va a la nota diaria con su origen."""
    p = nota_diaria()
    with open(p, "a", encoding="utf-8") as fh:
        fh.write(f"\n- ({origen}, {datetime.now().strftime('%H:%M')}) {str(texto).strip()[:2000]}\n")
    log(f"notas: capturado desde {origen} en {p.name}")
    return p


def notas_grafo(etiqueta=None, proyecto=None):
    """{nodos, aristas, pendientes} filtrado. Nodos = notas; aristas = enlaces."""
    idx = notas_indice()
    sel = [n for n in idx["notas"] if (not etiqueta or etiqueta in n["etiquetas"])
           and (not proyecto or (n["proyecto"] or "") == proyecto)]
    tit = {_norm(n["titulo"]): n["titulo"] for n in sel}
    aristas = [(n["titulo"], tit[_norm(e)]) for n in sel for e in n["enlaces"] if _norm(e) in tit]
    return {"nodos": [{"titulo": n["titulo"], "proyecto": n["proyecto"], "etiquetas": n["etiquetas"]} for n in sel],
            "aristas": aristas, "pendientes": {k: v for k, v in idx["pendientes"].items()
                                               if any(x in tit.values() for x in v)}}


def notas_espejo_sync(destino):
    """Espejo bidireccional con una carpeta (OneDrive / Google Drive). Copia
    lo nuevo en cada lado; si una nota cambió en los DOS lados desde la última
    sync, es un CONFLICTO: no se sobrescribe, se lista para que elijas. El
    original sigue siendo notas\\ (si el espejo se cae, todo sigue en local)."""
    import hashlib
    dst = Path(destino)
    dst.mkdir(parents=True, exist_ok=True)
    NOTAS_DIR.mkdir(parents=True, exist_ok=True)
    est_f = NOTAS_DIR / ".espejo.json"
    try:
        est = json.loads(est_f.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        est = {}

    def h(p):
        return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
    res = {"a_espejo": [], "desde_espejo": [], "conflictos": [], "iguales": 0}
    for nombre in sorted({p.name for p in NOTAS_DIR.glob("*.md")} | {p.name for p in dst.glob("*.md")}):
        a, b = NOTAS_DIR / nombre, dst / nombre
        ha, hb, base = h(a), h(b), est.get(nombre)
        if ha == hb:
            res["iguales"] += 1
            est[nombre] = ha
        elif hb is None or (ha and hb == base):
            shutil.copy2(a, b)
            res["a_espejo"].append(nombre)
            est[nombre] = ha
        elif ha is None or (hb and ha == base):
            shutil.copy2(b, a)
            res["desde_espejo"].append(nombre)
            est[nombre] = hb
        else:
            res["conflictos"].append(nombre)  # cambió en los dos lados: decide Leandro
    est_f.write_text(json.dumps(est, indent=1), encoding="utf-8")
    log(f"notas: espejo {dst}: {len(res['a_espejo'])} subidas, {len(res['desde_espejo'])} bajadas, "
        f"{len(res['conflictos'])} conflicto(s) sin tocar")
    return res


def _nota_capturar_tarea_ui():
    tree = _widgets.get("tasks_tree")
    sel = tree.selection() if tree is not None else ()
    if not sel:
        toast("Elige una tarea en Tareas primero")
        return None
    fam = load_family(sel[0]) or {}
    p = nota_capturar(f"Tarea {sel[0]} ({fam.get('estado') or '—'}): {(fam.get('reporte') or '')[:600]}",
                      origen=f"tarea {sel[0]}")
    toast(f"Capturada en {p.name}")
    return p


def _nota_capturar_chat_ui():
    box = _widgets.get("ask_text")
    txt = box.get("1.0", "end").strip() if box is not None else ""
    if not txt:
        toast("El chat está vacío")
        return None
    p = nota_capturar(txt, origen="chat de Tareas")
    toast(f"Capturado en {p.name}")
    return p


def notas_ui():
    """Ventana «Notas»: lista + búsqueda, editor del archivo, backlinks y
    pendientes, plantillas, grafo filtrable y espejo."""
    top = tk.Toplevel(_root)
    top.title("Notas")
    top.configure(bg=THEME["bg"])
    top.geometry(f"{S(980)}x{S(640)}")
    izq = tk.Frame(top, bg=THEME["sidebar"], width=S(260))
    izq.pack(side="left", fill="y")
    izq.pack_propagate(False)
    der = tk.Frame(top, bg=THEME["bg"])
    der.pack(side="right", fill="both", expand=True)
    q = ttk.Entry(izq, font=(FONT, 10))
    q.pack(fill="x", padx=8, pady=8)
    lb = tk.Listbox(izq, font=(FONT, 10), activestyle="none", bd=0, highlightthickness=0)
    lb.pack(fill="both", expand=True, padx=8)
    barra = tk.Frame(izq, bg=THEME["sidebar"])
    barra.pack(fill="x", padx=8, pady=8)
    titulo = tk.Label(der, text="", font=(FONT, 15, "bold"), bg=THEME["bg"], fg=THEME["text"], anchor="w")
    titulo.pack(fill="x", padx=16, pady=(12, 0))
    meta = tk.Label(der, text="", font=(FONT, 9), bg=THEME["bg"], fg=THEME["muted"], anchor="w", justify="left")
    meta.pack(fill="x", padx=16)
    ed = tk.Text(der, font=(FONT, 10), wrap="word", height=18, undo=True)
    ed.pack(fill="both", expand=True, padx=16, pady=8)
    back = tk.Label(der, text="", font=(FONT, 9), bg=THEME["bg"], fg=THEME["text"], anchor="w", justify="left",
                    wraplength=S(640))
    back.pack(fill="x", padx=16, pady=(0, 10))
    st = {"actual": None, "lista": []}

    def pintar_lista(_e=None):
        texto = q.get().strip()
        lista = [x["titulo"] for x in notas_buscar(texto)] if texto else [n["titulo"] for n in notas_todas()]
        st["lista"] = lista
        lb.delete(0, "end")
        for t in lista:
            lb.insert("end", t)

    def abrir(t):
        p = nota_ruta(t)
        if not p.exists():
            return
        n = nota_leer(p)
        idx = notas_indice()
        st["actual"] = n["titulo"]
        titulo.config(text=n["titulo"])
        meta.config(text=f"{n['fecha'] or 'sin fecha'}, etiquetas: {', '.join(n['etiquetas']) or '—'}, proyecto: "
                         f"{n['proyecto'] or '—'}, {p}")
        ed.delete("1.0", "end")
        ed.insert("1.0", p.read_text(encoding="utf-8"))
        bl = idx["backlinks"].get(n["titulo"]) or []
        pend = [e for e in n["enlaces"] if e in idx["pendientes"]]
        back.config(text=("Qué enlaza aquí: " + (", ".join(bl) or "nada")) +
                         (f"\nEnlaces pendientes (la nota aún no existe): {', '.join(pend)}" if pend else ""))

    def guardar(_e=None):
        if st["actual"]:
            nota_ruta(st["actual"]).write_text(ed.get("1.0", "end-1c"), encoding="utf-8")
            log(f"notas: guardada «{st['actual']}»")
            abrir(st["actual"])

    def nueva(plantilla=None):
        from tkinter import simpledialog
        t = simpledialog.askstring("Nueva nota", "Título:", parent=top)
        if not t:
            return
        ok, out, parecidas = nota_crear(t, plantilla)
        if parecidas:
            messagebox.showinfo("Notas", "Ya tienes notas parecidas: " + ", ".join(parecidas) +
                                ". No fusiono ni borro nada: decide tú.")
        if not ok:
            messagebox.showwarning("Notas", out)
        pintar_lista()
        abrir(t)

    lb.bind("<<ListboxSelect>>", lambda _e: lb.curselection() and abrir(st["lista"][lb.curselection()[0]]))
    q.bind("<KeyRelease>", pintar_lista)
    ed.bind("<Control-s>", guardar)
    for txt, fn in (("Nueva", lambda: nueva()), ("Reunión", lambda: nueva("reunion")),
                    ("Proyecto", lambda: nueva("proyecto")), ("Idea", lambda: nueva("idea")),
                    ("Hoy", lambda: (nota_diaria(), pintar_lista(), abrir(mem_hoy().isoformat()))),
                    ("Grafo", lambda: notas_grafo_ui()), ("Guardar", guardar)):
        ttk.Button(barra, text=txt, command=fn).pack(fill="x", pady=1)
    pintar_lista()
    _widgets["notas_ui"] = {"top": top, "abrir": abrir, "lista": st, "back": back, "editor": ed}
    return top


def notas_grafo_ui(etiqueta=None, proyecto=None):
    """Grafo simple: notas en círculo agrupadas por proyecto, aristas por enlace,
    pendientes en gris. Sin física ni 3D. Filtro por etiqueta o proyecto."""
    import math
    top = tk.Toplevel(_root)
    top.title("Grafo de notas")
    top.configure(bg=THEME["bg"])
    fila = tk.Frame(top, bg=THEME["bg"])
    fila.pack(fill="x", padx=10, pady=6)
    todas = notas_todas()
    etqs = sorted({e for n in todas for e in n["etiquetas"]})
    proys = sorted({n["proyecto"] for n in todas if n["proyecto"]})
    ve, vp = tk.StringVar(value=etiqueta or "(todas)"), tk.StringVar(value=proyecto or "(todos)")
    tk.Label(fila, text="Etiqueta", bg=THEME["bg"], fg=THEME["muted"]).pack(side="left")
    ce = ttk.Combobox(fila, textvariable=ve, values=["(todas)"] + etqs, state="readonly", width=16)
    ce.pack(side="left", padx=(4, 12))
    tk.Label(fila, text="Proyecto", bg=THEME["bg"], fg=THEME["muted"]).pack(side="left")
    cp = ttk.Combobox(fila, textvariable=vp, values=["(todos)"] + proys, state="readonly", width=18)
    cp.pack(side="left", padx=4)
    cv = tk.Canvas(top, width=S(760), height=S(520), bg=THEME["bg"], highlightthickness=0)
    cv.pack(padx=10, pady=(0, 10))

    def dibujar(_e=None):
        cv.delete("all")
        g = notas_grafo(None if ve.get() == "(todas)" else ve.get(), None if vp.get() == "(todos)" else vp.get())
        nod = sorted(g["nodos"], key=lambda n: (n["proyecto"] or "~", n["titulo"]))
        pend = sorted(g["pendientes"])
        W_, H_ = S(760), S(520)
        cx, cy, R = W_ / 2, H_ / 2, min(W_, H_) / 2 - S(70)
        todos = [n["titulo"] for n in nod] + pend
        pos = {t: (cx + R * math.cos(2 * math.pi * i / max(1, len(todos))),
                   cy + R * math.sin(2 * math.pi * i / max(1, len(todos)))) for i, t in enumerate(todos)}
        for a, b in g["aristas"]:
            cv.create_line(*pos[a], *pos[b], fill=THEME["muted"], width=1)
        for t, orig in g["pendientes"].items():
            for o in orig:
                if o in pos:
                    cv.create_line(*pos[o], *pos[t], fill=THEME["line"], dash=(3, 3))
        for n in nod:
            x, y = pos[n["titulo"]]
            cv.create_oval(x - 6, y - 6, x + 6, y + 6, fill=THEME["blue"], outline="")
            cv.create_text(x, y - 14, text=n["titulo"][:28], fill=THEME["text"], font=(FONT, 9))
            if n["proyecto"]:
                cv.create_text(x, y + 14, text=n["proyecto"][:24], fill=THEME["muted"], font=(FONT, 8))
        for t in pend:
            x, y = pos[t]
            cv.create_oval(x - 5, y - 5, x + 5, y + 5, outline=THEME["muted"], dash=(2, 2))
            cv.create_text(x, y - 14, text=f"{t[:24]} (pendiente)", fill=THEME["muted"], font=(FONT, 8))
        _widgets["notas_grafo_dato"] = g
    ce.bind("<<ComboboxSelected>>", dibujar)
    cp.bind("<<ComboboxSelected>>", dibujar)
    dibujar()
    _widgets["notas_grafo"] = (top, cv, ve, vp, dibujar)
    return top


_NOTA_CMD_RE = re.compile(r"^\s*(?:nota(?:\s+de\s+(?P<pl>reuni[oó]n|proyecto|idea))?\s*:\s*(?P<t>.+)|"
                          r"enlaza\s+(?P<a>.+?)\s+con\s+(?P<b>.+)|resume\s+la\s+nota\s+(?P<r>.+))\s*$", re.I)


def notas_paleta_items(q):
    """Comandos de notas en palabras normales desde la paleta."""
    m = _NOTA_CMD_RE.match(q or "")
    if not m:
        return None
    if m.group("t"):
        pl = {"reunion": "reunion", "reunión": "reunion", "proyecto": "proyecto", "idea": "idea"}.get(
            (m.group("pl") or "").lower())
        t = m.group("t").strip()
        par = [x for x in notas_parecidas(t) if _norm(x) != _norm(t)]
        return [{"id": "_nota_crear", "label": f"Crear la nota «{t}»" + (f" (plantilla {pl})" if pl else "")
                 + (f" — ojo: ya tienes «{par[0]}»" if par else ""),
                 "fn": lambda t=t, pl=pl: (nota_crear(t, pl), notas_ui())}]
    if m.group("a"):
        a, b = m.group("a").strip(), m.group("b").strip()
        return [{"id": "_nota_enlazar", "label": f"Enlazar «{a}» → [[{b}]]",
                 "fn": lambda a=a, b=b: toast(nota_enlazar(a, b)[1][:49])}]
    t = m.group("r").strip()
    return [{"id": "_nota_resumir", "label": f"Resumir la nota «{t}» (extractivo, sin IA)",
             "fn": lambda t=t: messagebox.showinfo("Notas", nota_resumir(t) or f"No existe la nota «{t}»")}]


def mem_buscar(q, maximo=40):
    """Busqueda por texto (sin vectores) en los Markdown de memory\\."""
    toks = [t for t in _norm(q).split() if t]
    hits = []
    if not toks or not MEMORY_DIR.is_dir():
        return hits
    for p in sorted(MEMORY_DIR.rglob("*.md"), reverse=True):
        try:
            for i, line in enumerate(p.read_text(encoding="utf-8").splitlines(), 1):
                n = _norm(line)
                if all(t in n for t in toks):
                    hits.append((_mem_rel(p), i, line.strip()[:200]))
                    if len(hits) >= maximo:
                        return hits
        except (OSError, UnicodeDecodeError):
            continue
    return hits


def _cli_memoria(args):
    """--memoria-iniciar | --memoria-carga "encargo" [motor] | --recuerda "texto" |
    --nuevo | --sync-memoria [carpeta] | --buscar-memoria "texto" (sin ventana)."""
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    op, resto = args[0], args[1:]
    if op == "--memoria-iniciar":
        print(json.dumps(mem_iniciar("consola"), ensure_ascii=False, indent=2))
        return 0
    if op == "--memoria-carga":
        t = {"id": "consola-" + datetime.now().strftime("%H%M%S"), "prompt": resto[0] if resto else "",
             "motor": resto[1] if len(resto) > 1 else default_motor()}
        txt = mem_bloque_prompt(t)
        print(txt)
        print(json.dumps(_MEM_CARGA[t["id"]]["registro"], ensure_ascii=False, indent=2))
        return 0
    if op in ("--recuerda", "--nuevo"):
        r = mem_comando(("/nuevo" if op == "--nuevo" else " ".join(resto)), "consola")
        if r is None:
            r = mem_recuerda(" ".join(resto), "consola")
        print(r["mensaje"])
        return 0 if r.get("ok") else 1
    if op == "--sync-memoria":
        inf = mem_sync(resto[0] if resto else None, origen="consola")
        print(json.dumps(inf, ensure_ascii=False, indent=2))
        return 0 if not inf.get("falta") else 1
    if op == "--buscar-memoria":
        for rel, i, line in mem_buscar(" ".join(resto)):
            print(f"{rel}:{i}: {line}")
        return 0
    return 2


def _mem_confirmar_ui(r):
    """Confirmacion visible de una escritura de memoria (nunca en silencio):
    ventanita con el mensaje y «Abrir el archivo»."""
    if _root is None or not r:
        return
    try:
        win = tk.Toplevel(_root)
        win.title("Memoria")
        win.configure(bg=THEME["bg"])
        win.attributes("-topmost", True)
        win.resizable(False, False)
        tk.Label(win, text="Guardado en la memoria" if r.get("ok") else "Memoria",
                 font=(FONT, 12, "bold"), bg=THEME["bg"], fg=THEME["text"]).pack(anchor="w", padx=18,
                                                                                  pady=(16, 4))
        tk.Label(win, text=r.get("mensaje") or "", font=(FONT, 10), bg=THEME["bg"],
                 fg=THEME["text"] if r.get("ok") else THEME["red"], wraplength=S(420),
                 justify="left").pack(anchor="w", padx=18)
        row = tk.Frame(win, bg=THEME["bg"])
        row.pack(anchor="e", padx=18, pady=(12, 14))
        ruta = r.get("ruta") or r.get("snapshot")
        if ruta:
            ttk.Button(row, text="Abrir el archivo", style="Accent.TButton",
                       command=lambda: (os.startfile(ruta), win.destroy())).pack(side="left", padx=4)
        ttk.Button(row, text="Cerrar", command=win.destroy).pack(side="left", padx=4)
        win.bind("<Escape>", lambda _e: win.destroy())
        win.update_idletasks()
        x = _root.winfo_rootx() + max(0, (_root.winfo_width() - win.winfo_width()) // 2)
        y = _root.winfo_rooty() + S(80)
        win.geometry(f"+{x}+{y}")
    except Exception as e:
        log(f"memoria: no se pudo mostrar la confirmación ({e})")


def _mem_sync_ui():
    """Paleta → «Sincronizar la memoria con la VM»: en un hilo, y lo confirma."""
    def _bg():
        try:
            r = mem_sync(origen="paleta")
            m = {"ok": not r.get("falta"), "mensaje": r.get("falta") or (
                f"Sync por diferencia hecha desde {r['origen']}: {r['anadidas']} secciones nuevas añadidas, "
                f"{r['actualizadas']} actualizadas, {len(r['conflictos'])} conflictos"
                + (f" (las dos versiones en {MEMORY_DIR / 'conflictos'})" if r["conflictos"] else "") + ".")}
        except Exception as e:
            m = {"ok": False, "mensaje": f"No se pudo sincronizar: {type(e).__name__}: {e}"}
        if _root is not None:
            _root.after(0, lambda: _mem_confirmar_ui(m))
    threading.Thread(target=_bg, daemon=True).start()


def mem_comando_ui(texto, origen):
    """Para el chat (Tareas, mascota) y la paleta: si es «/nuevo» o
    «recuerda esto», lo hace en un hilo y lo confirma. True si lo era."""
    if not (re.match(r"^\s*/nuevo\b", texto or "", re.I) or _MEM_RECUERDA_RE.match(texto or "")):
        return False

    def _bg():
        try:
            r = mem_comando(texto, origen)
        except Exception as e:
            r = {"ok": False, "mensaje": f"No se pudo: {type(e).__name__}: {e}"}
        st = _widgets.get("ask_status")
        if _root is not None:
            _root.after(0, lambda: (_mem_confirmar_ui(r),
                                    st.config(text=("✓ " if r.get("ok") else "") + (r.get("mensaje") or "")[:140])
                                    if st is not None and origen == "chat de Tareas" else None))
    threading.Thread(target=_bg, daemon=True).start()
    return True


# ---------------------------------------------------------------- exportar chats + copia de .claude\projects
# Defensa contra el baneo (ver share\outbox\ESTADO-EXPORTAR-CHATS.md). Bridge NO
# exporta por su cuenta: la exportacion oficial la pide Leandro en Claude
# (Ajustes -> Privacidad -> Exportar datos); Bridge guia, apunta la fecha
# (settings.json: ultima_exportacion), recuerda como mucho 1 vez por semana
# (ultimo_recordatorio_exportacion) y LEE el ZIP que se deja en la carpeta
# vigilada. Aparte, en cada sync copia el historial de Claude Code
# (.claude\projects, JSONL) a share\outbox\claude-projects-backup\: el original
# solo se lee; un archivo solo cuenta como copiado tras comprobar su sha256, y
# una copia cortada queda en «.parcial» y la siguiente sigue desde ahi.
EXPORT_AVISO_PROXY = ("El proxy te conecta; tu cuenta puede ser suspendida si el proveedor detecta la región. "
                      "La vía sin ese riesgo es la API con key propia o un modelo local. "
                      "Exporta tus chats cada semana.")
EXPORT_RUTA = "Ajustes → Privacidad → Exportar datos"
EXPORT_RECORDATORIO = "¿Exportaste tus chats esta semana?"
EXPORT_ZIP_MALO = "El archivo exportado no se pudo leer: vuelve a pedir la exportación"
CLAUDE_PROJECTS_DIR = (Path(os.environ["GROWI_BRIDGE_CLAUDE_PROJECTS"])
                       if os.environ.get("GROWI_BRIDGE_CLAUDE_PROJECTS") else HOME_DIR / ".claude" / "projects")
CLAUDE_BACKUP_DIR = OUTBOX / "claude-projects-backup"
EXPORT_DIR = INBOX / "export-claude"          # carpeta vigilada por defecto
EXPORT_VM_DIR = OUTBOX / "export-claude"      # copia del ZIP bueno, para la VM
EXPORT_ESTADO_FILE = OUTBOX / "exportar-chats-estado.json"
_EXP = {"lock": threading.Lock(), "estado_lock": threading.Lock(), "copiando": False, "linea": None, "kit": None, "kit_linea": None,
        "zips": {}, "ult_check": None}


def _exp_ahora():
    return datetime.now(TZ_CARACAS)


def _exp_fecha(v):
    try:
        d = datetime.fromisoformat(str(v))
    except (TypeError, ValueError):
        return None
    return d if d.tzinfo else d.replace(tzinfo=TZ_CARACAS)


def _exp_estado():
    try:
        d = json.loads(EXPORT_ESTADO_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _exp_json_atomico(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(tmp, path)


def _exp_estado_poner(**kw):
    with _EXP["estado_lock"]:
        d = _exp_estado()
        d.update(kw)
        try:
            _exp_json_atomico(EXPORT_ESTADO_FILE, d)
        except OSError as e:
            log(f"exportar: no se pudo guardar {EXPORT_ESTADO_FILE.name} ({e})")
    return d


def _exp_dias(d, ahora=None):
    return None if d is None else ((ahora or _exp_ahora()) - d).total_seconds() / 86400


def _exp_fecha_txt(d):
    if d is None:
        return "nunca"
    meses = "ene feb mar abr may jun jul ago sep oct nov dic".split()
    d = d.astimezone(TZ_CARACAS)
    return f"{d.day} {meses[d.month - 1]} {d.year}, {d.strftime('%H:%M')}"


# ---- 1) registro de la exportacion + 2) recordatorio semanal
def export_registrar(fuente="botón"):
    """Apunta en settings.json la fecha de la exportacion (la pidio Leandro en
    Claude o se verifico un ZIP bueno). Quita la linea del recordatorio."""
    ahora = _exp_ahora()
    s = load_settings()
    s["ultima_exportacion"] = ahora.isoformat(timespec="seconds")
    save_settings(s)
    _EXP["linea"] = None
    log(f"exportar: exportación registrada ({fuente}): ultima_exportacion = {s['ultima_exportacion']}")
    _ui_call(_exp_pintar)
    return s["ultima_exportacion"]


def export_recordatorio(motivo="domingo", ahora=None):
    """La linea «¿Exportaste tus chats esta semana?» si toca; si no, None.
    Toca si pasaron MAS de 7 dias desde ultima_exportacion (o nunca se
    exporto) y: es domingo (motivo «domingo») o se acaba de cerrar un
    proyecto grande (motivo «proyecto»). Tope: 1 aviso por semana (si
    ultimo_recordatorio_exportacion es de hace menos de 7 dias de calendario,
    no se repite aunque se abra la app diez veces). Al mostrarla, apunta la
    fecha. Nunca un pop-up: es una linea en Estado."""
    ahora = ahora or _exp_ahora()
    s = load_settings()
    ult = _exp_fecha(s.get("ultima_exportacion"))
    rec = _exp_fecha(s.get("ultimo_recordatorio_exportacion"))
    if ult is not None and _exp_dias(ult, ahora) <= 7:
        return None, f"exportaste hace {_exp_dias(ult, ahora):.1f} días (no pasaron más de 7)"
    if motivo == "domingo" and ahora.weekday() != 6:
        return None, "hoy no es domingo"
    if rec is not None and (ahora.date() - rec.astimezone(TZ_CARACAS).date()).days < 7:
        return None, f"ya se avisó esta semana ({_exp_fecha_txt(rec)}): máximo 1 aviso por semana"
    s["ultimo_recordatorio_exportacion"] = ahora.isoformat(timespec="seconds")
    save_settings(s)
    linea = EXPORT_RECORDATORIO + (" Acabas de cerrar un proyecto grande." if motivo == "proyecto" else "")
    _EXP["linea"] = linea
    log(f"exportar: recordatorio mostrado ({motivo}; última exportación: {_exp_fecha_txt(ult)}): {linea}")
    _ui_call(_exp_pintar)
    return linea, "mostrado"


def export_recordatorio_proyecto(task, result):
    """Al cerrar un proyecto grande (la ultima fase de una tarea con fases,
    la ronda 2+ o mas de 30 min) tambien vale el recordatorio, sin romper el
    tope de 1 por semana."""
    try:
        if (result.get("status") == "ok" and task.get("siguiente_fase") is None
                and (task.get("fase") or (task.get("ronda") or 0) >= 2
                     or (result.get("duration_s") or 0) >= 1800)):
            linea, por = export_recordatorio("proyecto")
            if not linea:
                log(f"exportar: proyecto {task.get('raiz') or task.get('id')} cerrado; sin recordatorio ({por})")
    except Exception as e:
        log(f"exportar: recordatorio de fin de proyecto: {type(e).__name__}: {e}")


# ---- 3) copia de .claude\projects a la VM (outbox)
def _exp_sha_prefijo(path, n):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        falta = n
        while falta > 0:
            b = f.read(min(1 << 20, falta))
            if not b:
                break
            h.update(b)
            falta -= len(b)
    return h


def _exp_hasta_ultima_linea(f, tam):
    """Posicion tras el ultimo «\\n» (una linea a medio escribir no se copia)."""
    pos, paso = tam, 1 << 16
    while pos > 0:
        ini = max(0, pos - paso)
        f.seek(ini)
        b = f.read(pos - ini)
        i = b.rfind(b"\n")
        if i >= 0:
            return ini + i + 1
        pos = ini
    return tam  # sin ningun salto: el archivo entero (una sola linea)


_EXP_CORTE = {"n": 0}


def _exp_copiar_uno(src, dst, st):
    """Copia src -> dst pasando por «dst.parcial». Si hay un .parcial (copia
    cortada) o una copia anterior que es el principio del original, sigue
    desde ahi (solo se transfiere lo que falta, como rsync --partial). Solo se
    renombra a dst tras comprobar el sha256 de lo escrito."""
    es_jsonl = src.suffix.lower() == ".jsonl"
    tmp = dst.with_name(dst.name + ".parcial")
    dst.parent.mkdir(parents=True, exist_ok=True)
    corte = int(os.environ.get("GROWI_BRIDGE_PRUEBA_CORTE_BYTES") or 0)  # solo pruebas: simula un apagon
    with open(src, "rb") as fi:
        lim = _exp_hasta_ultima_linea(fi, st.st_size) if es_jsonl and st.st_size else st.st_size
        base, modo, h = 0, "nuevo", hashlib.sha256()
        for cand, como in ((tmp, "reanudado desde el .parcial"), (dst, "añadido lo nuevo al final")):
            if not cand.is_file():
                continue
            n = cand.stat().st_size
            if n == 0 or n > lim:
                continue
            hs = _exp_sha_prefijo(src, n)
            if hs.hexdigest() == _exp_sha_prefijo(cand, n).hexdigest():
                if cand == dst:
                    shutil.copyfile(dst, tmp)
                base, modo, h = n, como, hs
                break
        if base == 0 and dst.is_file():
            modo = "entero de nuevo (el original cambió)"
        fi.seek(base)
        with open(tmp, "ab" if base else "wb") as fo:
            fo.truncate(base)
            falta = lim - base
            while falta > 0:
                b = fi.read(min(1 << 20, falta))
                if not b:
                    break
                fo.write(b)
                h.update(b)
                falta -= len(b)
                _EXP_CORTE["n"] += len(b)
                if corte and _EXP_CORTE["n"] >= corte:
                    fo.flush()
                    os._exit(9)  # prueba: el proceso muere a mitad, sin limpiar nada
            fo.flush()
            os.fsync(fo.fileno())
    escrito = tmp.stat().st_size
    sha = h.hexdigest()
    if escrito != lim or _exp_sha_prefijo(tmp, escrito).hexdigest() != sha:
        raise OSError(f"la copia no coincide con el original ({escrito} de {lim} bytes); queda como .parcial")
    anterior = None
    if base == 0 and dst.is_file():
        # El original ya no empieza como la copia (se reescribio): la copia
        # vieja NO se pisa, se aparta al lado.
        anterior = dst.with_name(f"{dst.name}.anterior-{datetime.now(TZ_CARACAS).strftime('%Y%m%d-%H%M%S')}")
        os.replace(dst, anterior)
    os.replace(tmp, dst)
    os.utime(dst, ns=(st.st_atime_ns, st.st_mtime_ns))
    return {**({"copia_anterior_en": anterior.name} if anterior else {}), "tam": lim, "tam_origen": st.st_size, "mtime_ns": st.st_mtime_ns, "sha256": sha,
            "completo": lim == st.st_size, "copiado_at": _now_iso(), "modo": modo,
            "bytes_transferidos": lim - base,
            **({"pendiente": f"{st.st_size - lim} bytes de una línea a medio escribir (archivo en uso): "
                             "van en la próxima sync"} if lim != st.st_size else {})}


def _exp_jsonl_revisar(path):
    """Parsea un JSONL linea por linea: lineas, mensajes (user/assistant) y
    las lineas que NO parsean (numero de linea)."""
    lineas = mensajes = 0
    malas = []
    with open(path, "rb") as f:
        for i, raw in enumerate(f, 1):
            if not raw.strip():
                continue
            try:
                o = json.loads(raw)
            except ValueError:
                malas.append(i)
                continue
            lineas += 1
            if isinstance(o, dict) and o.get("type") in ("user", "assistant"):
                mensajes += 1
    return {"lineas": lineas, "mensajes": mensajes, "malas": malas}


def claude_verificar_copia(dst=None, man=None, completa=False):
    """Tras cada sync: los JSONL de la COPIA parsean linea por linea. Cuenta
    archivos, conversaciones (un .jsonl por sesion en la carpeta de cada
    proyecto), subagentes y mensajes; lista por nombre los corruptos. Un
    archivo ya verificado con el mismo sha256 no se vuelve a leer (salvo
    completa=True), pero su tamaño en disco si se comprueba."""
    dst = Path(dst or CLAUDE_BACKUP_DIR)
    raiz = dst / "projects"
    mpath = dst / "manifiesto.json"
    if man is None:
        try:
            man = json.loads(mpath.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            man = {"archivos": {}}
    arch = man.setdefault("archivos", {})
    v = {"at": _now_iso(), "archivos": 0, "jsonl": 0, "conversaciones": 0, "subagentes": 0, "mensajes": 0,
         "lineas": 0, "corruptos": [], "releidos": 0, "faltan_en_copia": []}
    for rel, e in sorted(arch.items()):
        p = raiz / rel
        if not p.is_file() or p.stat().st_size != e.get("tam"):
            v["faltan_en_copia"].append(rel)
            continue
        v["archivos"] += 1
        if not rel.lower().endswith(".jsonl"):
            continue
        v["jsonl"] += 1
        r = e.get("lectura")
        if completa or not r or r.get("sha256") != e.get("sha256"):
            try:
                r = dict(_exp_jsonl_revisar(p), sha256=e.get("sha256"), at=_now_iso())
            except OSError as ex:
                r = {"lineas": 0, "mensajes": 0, "malas": [], "error": str(ex), "sha256": None}
            e["lectura"] = r
            v["releidos"] += 1
        if rel.count("/") == 1:
            v["conversaciones"] += 1
        else:
            v["subagentes"] += 1
        v["mensajes"] += r.get("mensajes", 0)
        v["lineas"] += r.get("lineas", 0)
        if r.get("malas") or r.get("error"):
            v["corruptos"].append({"archivo": rel, "lineas_malas": r.get("malas", [])[:10],
                                   "n_malas": len(r.get("malas", [])), "error": r.get("error")})
    return v


def claude_copia(origen="sync", src=None, dst=None, completa=False):
    """Copia (solo lectura del original) .claude\\projects ->
    share\\outbox\\claude-projects-backup\\projects\\ + manifiesto.json (tamaño,
    fecha, sha256 de cada archivo) + sincronizaciones.jsonl (una linea con la
    fecha por sync). Luego verifica los JSONL. Devuelve el informe."""
    src, dst = Path(src or CLAUDE_PROJECTS_DIR), Path(dst or CLAUDE_BACKUP_DIR)
    if not _EXP["lock"].acquire(blocking=False):
        return {"omitida": "ya hay una copia en curso"}
    _EXP["copiando"] = True
    _ui_call(_exp_pintar)
    t0 = time.time()
    inf = {"at": _now_iso(), "origen": origen, "fuente": str(src), "destino": str(dst), "archivos_pc": 0,
           "copiados": 0, "reanudados": 0, "iguales": 0, "en_uso": 0, "bytes_transferidos": 0, "errores": [],
           "ya_no_estan_en_pc": 0}
    try:
        archivos = sorted(p for p in src.rglob("*") if p.is_file()) if src.is_dir() else []
        if not src.is_dir() or not archivos:
            inf["falta"] = (f"no existe {src}: no hay historial de Claude Code que copiar" if not src.is_dir()
                            else f"{src} está vacía: no hay historial de Claude Code que copiar")
            log(f"exportar: copia de Claude Code NO hecha: {inf['falta']}")
            _exp_estado_poner(ultima_copia=inf)
            return inf
        mpath = dst / "manifiesto.json"
        try:
            man = json.loads(mpath.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            man = {}
        man.setdefault("_que_es", "Copia del historial de Claude Code del PC (.claude\\projects). Un archivo "
                                  "está aquí SOLO si se comprobó su sha256; los «.parcial» son copias cortadas "
                                  "que la siguiente sync termina. Bridge nunca toca los originales del PC.")
        arch = man.setdefault("archivos", {})
        vistos, ult_guardado = set(), time.time()
        for p in archivos:
            rel = p.relative_to(src).as_posix()
            vistos.add(rel)
            inf["archivos_pc"] += 1
            try:
                st = p.stat()
                e, d = arch.get(rel), dst / "projects" / rel
                if (e and e.get("completo") and e.get("tam_origen") == st.st_size
                        and e.get("mtime_ns") == st.st_mtime_ns and d.is_file() and d.stat().st_size == e["tam"]):
                    inf["iguales"] += 1
                    continue
                n = _exp_copiar_uno(p, d, st)
                if e and e.get("lectura"):
                    n["lectura"] = e["lectura"]  # se rehace en la verificacion si cambio el sha256
                arch[rel] = n
                inf["copiados"] += 1
                inf["bytes_transferidos"] += n["bytes_transferidos"]
                inf["reanudados"] += 1 if n["modo"].startswith(("reanudado", "añadido")) else 0
                inf["en_uso"] += 0 if n["completo"] else 1
            except OSError as ex:
                inf["errores"].append(f"{rel}: {ex}")
            if time.time() - ult_guardado > 5:
                _exp_json_atomico(mpath, man)  # solo con lo ya comprobado
                ult_guardado = time.time()
        for rel, e in arch.items():
            if rel not in vistos:
                e["ya_no_esta_en_pc"] = True  # la copia se queda: es el respaldo
                inf["ya_no_estan_en_pc"] += 1
            else:
                e.pop("ya_no_esta_en_pc", None)
        ver = claude_verificar_copia(dst, man, completa=completa)
        inf["verificacion"] = ver
        man["ultima_sync"] = inf["at"]
        _exp_json_atomico(mpath, man)
        inf["segundos"] = round(time.time() - t0, 1)
        with open(dst / "sincronizaciones.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps({k: v for k, v in inf.items() if k != "verificacion"} | {
                "conversaciones": ver["conversaciones"], "mensajes": ver["mensajes"],
                "corruptos": [c["archivo"] for c in ver["corruptos"]]}, ensure_ascii=False) + "\n")
        leeme = dst / "LEEME.txt"
        if not leeme.is_file():
            leeme.write_text("Copia del historial de Claude Code del PC de Leandro (C:\\Users\\forte\\.claude\\"
                             "projects), hecha por Growi Bridge en cada sync.\r\nprojects\\ = los archivos tal cual; "
                             "manifiesto.json = tamaño, fecha y sha256 de cada uno; sincronizaciones.jsonl = una "
                             "línea por sync con la fecha.\r\nSi el PC muere, el historial sigue aquí.\r\n",
                             encoding="utf-8")
        log(f"exportar: copia de Claude Code ({origen}) a {dst}: {inf['archivos_pc']} archivos en el PC, "
            f"{inf['copiados']} copiados ({inf['reanudados']} siguiendo una copia anterior, "
            f"{inf['bytes_transferidos'] // 1024} KB transferidos), {inf['iguales']} iguales, "
            f"{inf['en_uso']} con una línea a medio escribir, {len(inf['errores'])} errores, "
            f"{inf['segundos']} s")
        log(f"exportar: verificación de la copia: {ver['archivos']} archivos, {ver['jsonl']} JSONL leídos "
            f"línea por línea ({ver['releidos']} releídos ahora), {ver['conversaciones']} conversaciones + "
            f"{ver['subagentes']} de subagentes, {ver['mensajes']} mensajes, {len(ver['corruptos'])} corruptos"
            + (": " + ", ".join(f"{c['archivo']} (líneas {c['lineas_malas']})" for c in ver["corruptos"])
               if ver["corruptos"] else "")
            + (f"; FALTAN en la copia: {', '.join(ver['faltan_en_copia'][:10])}" if ver["faltan_en_copia"] else ""))
        for err in inf["errores"][:10]:
            log(f"exportar: copia: error: {err}")
        _exp_estado_poner(ultima_copia=inf)
        return inf
    except Exception as e:
        inf["errores"].append(f"{type(e).__name__}: {e}")
        log(f"exportar: la copia de Claude Code falló: {type(e).__name__}: {e}")
        _exp_estado_poner(ultima_copia=inf)
        return inf
    finally:
        _EXP["copiando"] = False
        _EXP["lock"].release()
        _ui_call(_exp_pintar)


def claude_copia_async(origen):
    if load_settings().get("copia_claude", True) is False:
        return
    threading.Thread(target=lambda: claude_copia(origen), daemon=True).start()


# ---- 4) verificar el ZIP de la exportacion oficial
def _exp_carpetas():
    out = [EXPORT_DIR]
    extra = (load_settings().get("export_carpeta_vigilada") or "").strip()
    if extra and Path(extra) != EXPORT_DIR:
        out.append(Path(extra))
    return out


def _exp_es_candidato(p, carpeta):
    """En share\\inbox\\export-claude\\ cuenta todo .zip; en otra carpeta
    (Descargas) solo los que parecen de Claude («data-…» o «claude»)."""
    if p.suffix.lower() != ".zip":
        return False
    return carpeta == EXPORT_DIR or p.name.lower().startswith("data-") or "claude" in p.name.lower()


def export_verificar_zip(path):
    """Abre el ZIP, comprueba el CRC de todos los miembros, lee
    conversations.json ENTERO y cuenta conversaciones y mensajes. Nunca dice
    que esta bien sin haberlo leido."""
    import zipfile
    p = Path(path)
    r = {"archivo": str(p), "at": _now_iso(), "ok": False, "miembros": [], "conversaciones": 0, "mensajes": 0}
    try:
        r["tam"] = p.stat().st_size
        for sufijo in (".crdownload", ".part", ".partial", ".download"):
            if p.with_name(p.name + sufijo).exists():
                raise ValueError(f"la descarga sigue a medias ({p.name}{sufijo})")
        with zipfile.ZipFile(p) as z:
            infos = z.infolist()
            r["miembros"] = [i.filename for i in infos][:200]
            r["n_miembros"] = len(infos)
            malo = z.testzip()
            if malo:
                raise ValueError(f"el miembro {malo} está dañado (CRC)")
            conv = [i for i in infos if i.filename.replace("\\", "/").split("/")[-1].lower() == "conversations.json"]
            if not conv:
                raise ValueError("no trae conversations.json (¿es la exportación de Claude?)")
            data = json.loads(z.read(conv[0]).decode("utf-8"))
            if not isinstance(data, list):
                raise ValueError("conversations.json no es una lista de conversaciones")
            r["conversaciones"] = len(data)
            r["mensajes"] = sum(len(c.get("chat_messages") or []) for c in data if isinstance(c, dict))
            r["sin_mensajes"] = sum(1 for c in data if isinstance(c, dict) and not c.get("chat_messages"))
            r["otros_json"] = []
            for i in infos:
                if i.filename.lower().endswith(".json") and i is not conv[0]:
                    json.loads(z.read(i).decode("utf-8"))  # tambien tienen que parsear enteros
                    r["otros_json"].append(i.filename)
        r["ok"] = True
        r["texto"] = (f"✓ {p.name} se leyó entero: {r['conversaciones']} conversaciones, {r['mensajes']} mensajes "
                      f"({r['n_miembros']} archivos en el ZIP). Guárdalo también en la VM y en Drive.")
    except Exception as e:  # BadZipFile, CRC/zlib, JSON, E/S...: nunca se da por bueno
        r["error"] = f"{type(e).__name__}: {e}"
        r["texto"] = f"✗ {EXPORT_ZIP_MALO}. ({p.name}: {e})"
    return r


def export_revisar_carpetas(forzar=False):
    """Mira la(s) carpeta(s) vigilada(s); cada ZIP nuevo o cambiado (tamaño +
    fecha) se verifica una vez. Bueno -> copia a share\\outbox\\export-claude\\
    (para la VM, con sha256 comprobado) y apunta ultima_exportacion."""
    est = _exp_estado()
    vistos = est.get("zips") or {}
    hechos = []
    for carpeta in _exp_carpetas():
        try:
            lista = sorted(x for x in carpeta.iterdir() if x.is_file() and _exp_es_candidato(x, carpeta))
        except OSError:
            continue
        for p in lista:
            try:
                st = p.stat()
            except OSError:
                continue
            if time.time() - st.st_mtime < 10:
                continue  # todavia se esta escribiendo
            huella = f"{st.st_size}:{st.st_mtime_ns}"
            if not forzar and (vistos.get(str(p)) or {}).get("huella") == huella:
                continue
            r = export_verificar_zip(p)
            r["huella"] = huella
            if r["ok"]:
                try:
                    EXPORT_VM_DIR.mkdir(parents=True, exist_ok=True)
                    dst = EXPORT_VM_DIR / p.name
                    tmp = dst.with_name(dst.name + ".parcial")
                    shutil.copyfile(p, tmp)
                    if _exp_sha_prefijo(tmp, st.st_size).hexdigest() != _exp_sha_prefijo(p, st.st_size).hexdigest():
                        raise OSError("el sha256 de la copia no coincide")
                    os.replace(tmp, dst)
                    r["copia_vm"] = str(dst)
                except OSError as e:
                    r["copia_vm_error"] = str(e)
                ult = _exp_fecha(load_settings().get("ultima_exportacion"))
                if ult is None or ult.timestamp() < st.st_mtime:
                    export_registrar(f"ZIP verificado: {p.name}")
            log(f"exportar: ZIP {p}: " + (r["texto"] + (f" Copiado a {r['copia_vm']}." if r.get("copia_vm") else "")
                                         if r["ok"] else f"{EXPORT_ZIP_MALO} ({r['error']})"))
            vistos[str(p)] = r
            hechos.append(r)
    if hechos:
        _exp_estado_poner(zips=vistos, ultimo_zip=hechos[-1])
        _ui_call(_exp_pintar)
    return hechos


def _exp_loop(stop=None):
    """Hilo: cada 30 s mira la carpeta vigilada; cada 30 min (y al arrancar)
    el recordatorio del domingo y la copia de .claude\\projects (copia_claude_cada_min)."""
    try:
        EXPORT_DIR.mkdir(parents=True, exist_ok=True)  # para que Leandro la vea (vacia)
    except OSError:
        pass
    time.sleep(8)
    ult_copia, ult_rec, primera = 0.0, 0.0, True
    while not (stop and stop.is_set()):
        try:
            export_revisar_carpetas()
            if time.time() - ult_rec > 1800:
                linea, por = export_recordatorio("domingo")
                if primera and not linea:
                    log(f"exportar: sin recordatorio al arrancar ({por})")
                ult_rec = time.time()
            cada = float(load_settings().get("copia_claude_cada_min") or 30) * 60
            if time.time() - ult_copia > cada:
                ult_copia = time.time()
                if load_settings().get("copia_claude", True) is not False:
                    claude_copia("al arrancar" if primera else "periódica")
            primera = False
        except Exception as e:
            log(f"exportar: {type(e).__name__}: {e}")
        time.sleep(30)


def _cli_exportar(args):
    """--copia-claude [completa] | --verificar-export <zip> | --recordatorio-export [proyecto]
    (sin ventana; para pruebas y para Leandro)."""
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    op, resto = args[0], args[1:]
    if op == "--copia-claude":
        inf = claude_copia("consola", completa="completa" in resto)
        print(json.dumps(inf, ensure_ascii=False, indent=2))
        return 0 if not inf.get("falta") and not inf.get("errores") else 1
    if op == "--verificar-export":
        r = export_verificar_zip(resto[0]) if resto else {"ok": False, "texto": "falta la ruta del ZIP"}
        print(json.dumps(r, ensure_ascii=False, indent=2))
        return 0 if r["ok"] else 1
    if op == "--recordatorio-export":
        linea, por = export_recordatorio(resto[0] if resto else "domingo")
        print(json.dumps({"linea": linea, "por": por}, ensure_ascii=False))
        return 0
    return 2


# ---- interfaz: boton + linea del recordatorio (CTk con respaldo clasico)
def _exp_kit(holder):
    """_KitCtk si se puede (regla del piloto), si no _KitTk."""
    if _ctk_wanted():
        try:
            return _KitCtk(holder, global_setup=not isinstance(_GW.get("kit"), _KitCtk))
        except Exception as e:
            log(f"exportar: CustomTkinter no disponible ({type(e).__name__}: {e}); se usa tkinter clásico")
    return _KitTk(holder)


def _build_export_ui(linea_holder, card_holder):
    for holder, fn, key in ((linea_holder, _build_export_linea, "kit_linea"), (card_holder, _build_export_card, "kit")):
        t0 = time.perf_counter()
        kit = _exp_kit(holder)
        try:
            fn(kit, holder)
        except Exception as e:
            if not isinstance(kit, _KitCtk):
                raise
            log(f"exportar: CTk falló al dibujar ({type(e).__name__}: {e}); se usa tkinter clásico")
            for ch in holder.winfo_children():
                ch.destroy()
            kit = _KitTk(holder)
            fn(kit, holder)
        _EXP[key] = kit
        log(f"exportar: {'línea del recordatorio' if key == 'kit_linea' else 'tarjeta Tus conversaciones'} "
            f"con {kit.nombre} ({(time.perf_counter() - t0) * 1000:.0f} ms)")
    _exp_pintar()


def _build_export_linea(k, holder):
    W = _widgets
    card = k.card(holder)
    W["exp_linea_card"] = card  # se muestra solo cuando hay recordatorio
    r = k.row(card, pady=(8, 8))
    W["exp_linea"] = k.label(r, "", bold=True, wrap=380, color="orange_text")
    W["exp_linea"].pack(side="left", fill="x", expand=True)
    k.button(r, "Ocultar", _exp_ocultar_linea).pack(side="right")
    k.button(r, "Exportar ahora", export_guia_ui, accent=True).pack(side="right", padx=(0, 8))


def _build_export_card(k, holder):
    W = _widgets
    card = k.section("Tus conversaciones",
                     "Si la cuenta de Claude cae, lo exportado es lo único que se salva (y no se puede "
                     "importar a otra cuenta: es un archivo de consulta). Bridge no exporta por ti: te guía, "
                     "apunta la fecha y comprueba que el ZIP se puede leer.")
    r = k.row(card, pady=(6, 6))
    W["exp_btn"] = k.button(r, "Exportar mis conversaciones", export_guia_ui)
    W["exp_btn"].pack(side="left")
    W["exp_ult"] = k.label(r, "", wrap=360)
    W["exp_ult"].pack(side="left", padx=(12, 0), fill="x", expand=True)
    W["exp_zip"] = k.label(card, "", muted=True, wrap=600)
    W["exp_zip"].pack(anchor="w", fill="x", padx=16, pady=(0, 4))
    W["exp_copia"] = k.label(card, "", muted=True, wrap=600)
    W["exp_copia"].pack(anchor="w", fill="x", padx=16, pady=(0, 6))
    r2 = k.row(card, pady=(0, 14))
    W["exp_copiar_btn"] = k.button(r2, "Copiar el historial a la VM ahora", lambda: threading.Thread(
        target=lambda: claude_copia("botón"), daemon=True).start())
    W["exp_copiar_btn"].pack(side="left")
    k.button(r2, "Verificar un ZIP…", _exp_elegir_zip).pack(side="left", padx=(8, 0))
    k.button(r2, "Carpeta vigilada…", _exp_elegir_carpeta).pack(side="left", padx=(8, 0))


def _exp_ocultar_linea():
    _EXP["linea"] = None
    _exp_pintar()


def _exp_pintar():
    W = _widgets
    if "exp_ult" not in W:
        return
    try:
        k, kl = _EXP["kit"], _EXP["kit_linea"]
        card = W.get("exp_linea_card")
        if card is not None and kl is not None:
            if _EXP["linea"]:
                kl.set_label(W["exp_linea"], _EXP["linea"])
                if not card.winfo_ismapped():
                    card.pack(fill="x", padx=20, pady=(0, 6))
            elif card.winfo_ismapped():
                card.pack_forget()
        s = load_settings()
        ult = _exp_fecha(s.get("ultima_exportacion"))
        if ult is None:
            k.set_label(W["exp_ult"], "Todavía no registraste ninguna exportación.", color="orange_text")
        else:
            dias = _exp_dias(ult)
            k.set_label(W["exp_ult"], f"Última exportación: {_exp_fecha_txt(ult)} (hace {int(dias)} días)",
                        color="orange_text" if dias > 7 else "green_text")
        est = _exp_estado()
        z = est.get("ultimo_zip")
        if z:
            k.set_label(W["exp_zip"], z.get("texto") or "", color="green_text" if z.get("ok") else "red")
        else:
            k.set_label(W["exp_zip"], "Deja el ZIP que te llega por correo en "
                        + " o ".join(str(c) for c in _exp_carpetas()) + ": Bridge lo abre y lo cuenta.",
                        color="muted")
        c = est.get("ultima_copia")
        if _EXP["copiando"]:
            txt, col = "⠋ Copiando el historial de Claude Code a la VM…", "muted"
        elif not c:
            txt, col = "Copia del historial de Claude Code a la VM: todavía no se hizo.", "muted"
        elif c.get("falta"):
            txt, col = "Copia a la VM no hecha: " + c["falta"], "orange_text"
        else:
            v = c.get("verificacion") or {}
            mal = v.get("corruptos") or []
            txt = (f"Historial de Claude Code en la VM: {v.get('archivos', 0)} archivos, "
                   f"{v.get('conversaciones', 0)} conversaciones, {v.get('mensajes', 0)} mensajes; "
                   + (("1 archivo corrupto: " if len(mal) == 1 else f"{len(mal)} archivos corruptos: ")
                      + ", ".join(x["archivo"] for x in mal[:5])
                      if mal else "ninguno corrupto") + f" (última copia: {_exp_fecha_txt(_exp_fecha(c['at']))})"
                   + (f"; {len(c['errores'])} errores, mira el Registro" if c.get("errores") else ""))
            col = "red" if mal or c.get("errores") else "green_text"
        k.set_label(W["exp_copia"], txt, color=col)
        k.set_enabled(W["exp_copiar_btn"], not _EXP["copiando"])
    except Exception as e:
        log(f"exportar: no se pudo pintar la tarjeta ({type(e).__name__}: {e})")


def _exp_elegir_zip():
    p = filedialog.askopenfilename(title="Verificar la exportación de Claude", filetypes=[("Archivo zip", "*.zip")])
    if not p:
        return

    def _bg():
        r = export_verificar_zip(p)
        log(f"exportar: ZIP elegido a mano {p}: " + (r["texto"] if r["ok"] else f"{EXPORT_ZIP_MALO} ({r['error']})"))
        if r["ok"]:
            ult = _exp_fecha(load_settings().get("ultima_exportacion"))
            if ult is None or ult.timestamp() < Path(p).stat().st_mtime:
                export_registrar(f"ZIP verificado: {Path(p).name}")
        _exp_estado_poner(ultimo_zip=r)
        _ui_call(_exp_pintar)
    threading.Thread(target=_bg, daemon=True).start()


def _exp_elegir_carpeta():
    p = filedialog.askdirectory(title="Carpeta donde dejas el ZIP de la exportación (p. ej. Descargas)",
                                initialdir=str(HOME_DIR / "Downloads"))
    if not p:
        return
    s = load_settings()
    s["export_carpeta_vigilada"] = p
    save_settings(s)
    log(f"exportar: carpeta vigilada: {EXPORT_DIR} y {p}")
    _exp_pintar()


def export_guia_ui():
    """El boton «Exportar mis conversaciones»: explica la ruta oficial y los
    avisos, y apunta la fecha cuando Leandro dice que ya la pidio. No promete
    exportar nada por su cuenta."""
    if _root is None:
        return
    old = _EXP.get("dlg")
    try:
        if old is not None and old.winfo_exists():
            old.lift()
            return
    except Exception:
        pass
    top = tk.Toplevel(_root)
    top.title("Exportar mis conversaciones")
    top.configure(bg=THEME["bg"])
    top.transient(_root)
    top.resizable(False, False)
    _EXP["dlg"] = top
    kit = None
    if isinstance(_EXP.get("kit"), _KitCtk):
        try:
            kit = _KitCtk(top, global_setup=False)
            _exp_guia_con(kit, top)
        except Exception as e:
            log(f"exportar: guía sin CustomTkinter ({type(e).__name__}: {e}); se usa la clásica")
            for ch in top.winfo_children():
                ch.destroy()
            kit = None
    if kit is None:
        kit = _KitTk(top)
        _exp_guia_con(kit, top)
    top.bind("<Escape>", lambda _e: top.destroy())
    top.update_idletasks()
    x = _root.winfo_rootx() + max(0, (_root.winfo_width() - top.winfo_width()) // 2)
    top.geometry(f"+{x}+{_root.winfo_rooty() + S(60)}")
    log("exportar: guía abierta (ruta oficial y avisos)")


EXPORT_GUIA_PASOS = (
    f"1. Abre Claude en la web (claude.ai) o en Claude Desktop. En el móvil (iOS/Android) no está.\n"
    f"2. Ve a {EXPORT_RUTA}.\n"
    "3. Anthropic te manda un enlace por correo. El enlace caduca a las 24 horas: descárgalo ese mismo día.\n"
    "4. Llega un ZIP con tus conversaciones en JSON. Déjalo en la carpeta vigilada y Bridge lo abre, lo "
    "cuenta y te dice si se puede leer.")
EXPORT_GUIA_AVISOS = (
    "Ojo: el ZIP NO se puede importar a otra cuenta (es un archivo de consulta, no una migración) y no trae "
    "la memoria ni los archivos que subiste. Guárdalo en la VM y en Drive. No abras una cuenta nueva para "
    "saltarte un bloqueo: la apelación oficial es claude.ai/restricted.")


def _exp_guia_con(k, top):
    card = k.card(top)
    card.pack(fill="both", expand=True, padx=12, pady=12)
    top._titulo = k.title(card, "Exportar mis conversaciones")
    top._titulo.pack(anchor="w", padx=18, pady=(16, 6))
    top._pasos = k.label(card, EXPORT_GUIA_PASOS, wrap=480)
    top._pasos.pack(anchor="w", fill="x", padx=18)
    top._avisos = k.label(card, EXPORT_GUIA_AVISOS, bold=True, wrap=480, color="orange_text")
    top._avisos.pack(anchor="w", fill="x", padx=18, pady=(10, 0))
    top._carpeta = k.label(card, "Carpeta vigilada: " + " y ".join(str(c) for c in _exp_carpetas()),
                           muted=True, wrap=480)
    top._carpeta.pack(anchor="w", fill="x", padx=18, pady=(8, 0))
    b = k.frame(card)
    b.pack(anchor="e", padx=18, pady=(14, 16))

    def _ya():
        export_registrar("botón «Ya la pedí»")
        top.destroy()

    def _abrir():
        import webbrowser
        webbrowser.open("https://claude.ai")
        log("exportar: abierto claude.ai en el navegador")
    top._ya = k.button(b, "Ya la pedí: apuntar la fecha", _ya, accent=True)
    top._ya.pack(side="right")
    k.button(b, "Abrir claude.ai", _abrir).pack(side="right", padx=(0, 8))
    k.button(b, "Copia local (.zip)", lambda: (top.destroy(), export_conversations())).pack(side="right",
                                                                                           padx=(0, 8))
    top._cerrar = k.button(b, "Cerrar", top.destroy)
    top._cerrar.pack(side="right", padx=(0, 8))


# -- calibracion contra Leandro: un registro y una revision manual, nada automatico
def calibracion_init():
    _cola("""CREATE TABLE IF NOT EXISTS revisiones (
        rev_id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, task_id TEXT, raiz TEXT,
        ronda INTEGER, nivel TEXT, decision TEXT, aprobado INTEGER,
        juez1_motor TEXT, juez1_modelo TEXT, juez1_estado TEXT, juez1_aprobado INTEGER, juez1_puntuacion TEXT,
        juez2_motor TEXT, juez2_modelo TEXT, juez2_estado TEXT, juez2_aprobado INTEGER, juez2_puntuacion TEXT,
        juez2_costo REAL, juez2_segundos REAL, checks_total INTEGER, checks_fallados INTEGER,
        archivo_revision TEXT, umbral INTEGER,
        etiqueta_leandro TEXT, etiqueta_at TEXT, etiqueta_nota TEXT)""")
    _cola("CREATE INDEX IF NOT EXISTS revisiones_raiz ON revisiones(raiz)")


def _b(v):
    return None if v is None else (1 if v else 0)


def _rev_evento(d):
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        with open(REV_LOG, "a", encoding="utf-8") as f:
            f.write(json.dumps(d, ensure_ascii=False) + "\n")
    except OSError as e:
        log(f"calibración: no se pudo escribir {REV_LOG.name} ({e})")


def calib_registrar(task, rev):
    """Cada revision con su veredicto (cola.db -> revisiones + revisiones-registro.jsonl)."""
    vs = {v["rol"]: v for v in rev.get("veredictos") or [] if v}
    j1, j2 = vs.get("juez 1") or {}, vs.get("juez 2") or {}
    row = {"at": _now_iso(), "task_id": task["id"], "raiz": task["raiz"], "ronda": task.get("ronda", 0),
           "nivel": rev.get("nivel"), "decision": rev.get("decision"), "aprobado": _b(rev.get("aprobado")),
           "juez1_motor": j1.get("motor"), "juez1_modelo": j1.get("modelo"), "juez1_estado": j1.get("estado"),
           "juez1_aprobado": _b(j1.get("aprobado")),
           "juez1_puntuacion": json.dumps(j1.get("puntuacion")) if j1.get("puntuacion") else None,
           "juez2_motor": j2.get("motor"), "juez2_modelo": j2.get("modelo"), "juez2_estado": j2.get("estado"),
           "juez2_aprobado": _b(j2.get("aprobado")),
           "juez2_puntuacion": json.dumps(j2.get("puntuacion")) if j2.get("puntuacion") else None,
           "juez2_costo": j2.get("costo_usd"), "juez2_segundos": j2.get("segundos"),
           "checks_total": len(rev.get("checks_deterministas") or []),
           "checks_fallados": sum(1 for c in rev.get("checks_deterministas") or [] if c["resultado"] == "falla"),
           "archivo_revision": f"{task['id']}.revision.json", "umbral": _umbral_rubrica()}
    _cola(f"INSERT INTO revisiones ({', '.join(row)}) VALUES ({', '.join('?' * len(row))})", tuple(row.values()))
    r = _cola("SELECT max(rev_id) AS m FROM revisiones WHERE task_id=?", (task["id"],), fetch=True)
    rid = r[0]["m"] if r else None
    _rev_evento(dict(row, evento="revision", rev_id=rid))
    return rid


def calib_etiquetar(raiz, veredicto, nota=""):
    """Leandro corrige (o confirma) la revision de una tarea: queda como etiqueta.
    No cambia el estado de la tarea ni el umbral: solo se apunta."""
    if veredicto not in ("aprobado", "rechazado"):
        return False, "la etiqueta debe ser aprobado o rechazado"
    r = _cola("SELECT * FROM revisiones WHERE raiz=? ORDER BY rev_id DESC LIMIT 1", (raiz,), fetch=True)
    if not r:
        return False, "esa tarea no tiene ninguna revisión registrada"
    row = r[0]
    _cola("UPDATE revisiones SET etiqueta_leandro=?, etiqueta_at=?, etiqueta_nota=? WHERE rev_id=?",
          (veredicto, _now_iso(), str(nota or "")[:300], row["rev_id"]))
    dec_ok = row["decision"] == "aprobado"
    corrige = dec_ok != (veredicto == "aprobado") or row["decision"] in ("necesita_decision", "sin_revision")
    _rev_evento({"at": _now_iso(), "evento": "etiqueta", "rev_id": row["rev_id"], "raiz": raiz,
                 "task_id": row["task_id"], "decision_revisor": row["decision"], "etiqueta_leandro": veredicto,
                 "corrige": corrige, "nota": nota})
    _family_update(raiz, etiqueta_leandro={"veredicto": veredicto, "at": _now_iso(), "rev_id": row["rev_id"],
                                           "decision_revisor": row["decision"], "corrige": corrige})
    res = calib_resumen()
    msg = (f"Apuntado: tú dices «{veredicto}»; la revisión había dicho «{row['decision']}»"
           + (" (corrección)." if corrige else " (estás de acuerdo).")
           + (f" Casos: {res['casos']}: toca revisar a mano la rúbrica y el umbral ({CALIB_FILE.name})."
              if res["toca_revisar"] else
              f" Casos: {res['casos']}; la próxima revisión de la rúbrica toca en {res['proxima_revision_en']} casos."))
    return True, msg


def calib_resumen(escribir=True):
    """Tasa de acuerdo juez-vs-Leandro por bloques de ~30 casos (la ultima
    revision de cada tarea). Es para revisarla a mano: no cambia ningun umbral."""
    rows = _cola("SELECT * FROM revisiones ORDER BY rev_id", fetch=True)
    ult = {}
    for r in rows:
        ult[r["raiz"]] = r
    casos = sorted(ult.values(), key=lambda r: r["rev_id"])
    casos = [r for r in casos if r["decision"] in ("aprobado", "no_aprobado", "necesita_decision")]

    def tasa(lista, campo):
        ok = [r for r in lista if r["etiqueta_leandro"] and r[campo] is not None]
        if not ok:
            return {"n": 0, "acuerdo": None}
        hit = sum(1 for r in ok if bool(r[campo]) == (r["etiqueta_leandro"] == "aprobado"))
        return {"n": len(ok), "acuerdo": round(hit / len(ok), 3)}

    def bloque(lista):
        et = [r for r in lista if r["etiqueta_leandro"]]
        corr = [r for r in et if (r["decision"] == "aprobado") != (r["etiqueta_leandro"] == "aprobado")
                or r["decision"] == "necesita_decision"]
        return {"casos": len(lista), "etiquetados_por_leandro": len(et), "correcciones": len(corr),
                "acuerdo_implicito": (round(1 - len(corr) / len(lista), 3) if lista else None),
                "acuerdo_juez1_vs_leandro": tasa(lista, "juez1_aprobado"),
                "acuerdo_juez2_vs_leandro": tasa(lista, "juez2_aprobado"),
                "acuerdo_decision_vs_leandro": tasa([dict(r, dec=1 if r["decision"] == "aprobado" else 0)
                                                     for r in lista], "dec"),
                "desde_rev_id": lista[0]["rev_id"] if lista else None,
                "hasta_rev_id": lista[-1]["rev_id"] if lista else None}
    bloques = [bloque(casos[i:i + CALIB_BLOQUE]) for i in range(0, len(casos), CALIB_BLOQUE)]
    res = {"actualizado": _now_iso(), "casos": len(casos), "bloque": CALIB_BLOQUE, "umbral_actual": _umbral_rubrica(),
           "proxima_revision_en": CALIB_BLOQUE - (len(casos) % CALIB_BLOQUE),
           "toca_revisar": bool(casos) and len(casos) % CALIB_BLOQUE == 0,
           "total": bloque(casos), "bloques": bloques,
           "como_leerlo": ("casos = la última revisión de cada tarea. acuerdo_implicito cuenta como de acuerdo "
                           "lo que no corregiste; los acuerdos «vs_leandro» solo usan lo que etiquetaste. Cada "
                           f"{CALIB_BLOQUE} casos mira la tasa y, si hace falta, ajusta a mano la rúbrica o "
                           "revision.rubrica.umbral_min en engines.json: nada cambia solo."),
           "desacuerdos": [{"rev_id": r["rev_id"], "raiz": r["raiz"], "decision": r["decision"],
                            "juez1": r["juez1_motor"], "juez1_aprobado": r["juez1_aprobado"],
                            "leandro": r["etiqueta_leandro"]} for r in casos if r["etiqueta_leandro"]
                           and (r["decision"] == "aprobado") != (r["etiqueta_leandro"] == "aprobado")][-30:]}
    if escribir:
        try:
            OUTBOX.mkdir(parents=True, exist_ok=True)
            tmp = CALIB_FILE.with_suffix(".tmp")
            tmp.write_text(json.dumps(res, ensure_ascii=False, indent=2), encoding="utf-8")
            os.replace(tmp, CALIB_FILE)
        except OSError as e:
            log(f"calibración: no se pudo escribir {CALIB_FILE.name} ({e})")
        if res["toca_revisar"]:
            log(f"calibración: {res['casos']} casos: toca revisar la rúbrica/umbral a mano "
                f"(acuerdo implícito {res['total']['acuerdo_implicito']}); ver {CALIB_FILE.name}")
    return res

_DIM_TXT = {"completitud": "completitud", "correccion": "corrección", "no_regresion": "no-regresión",
            "evidencia": "evidencia"}


def veredicto_txt(v):
    """Un veredicto en palabras (la ventana y el reporte)."""
    if not v:
        return ""
    quien = v.get("nombre") or v.get("motor") or "?"
    if v.get("modelo") and str(v["modelo"]).lower() not in quien.lower():
        quien += f" ({v['modelo']})"
    if v.get("estado") != "valido":
        return (f"{quien}: sin veredicto válido ({v.get('estado')}: "
                + "; ".join(v.get("errores") or [])[:160] + ")")
    pu = v.get("puntuacion") or {}
    s = (f"{quien} dijo {'aprobado' if v.get('aprobado') else 'no aprobado'} ("
         + ", ".join(f"{_DIM_TXT[k]} {pu.get(k)}" for k in RUBRICA_DIMS) + ")")
    if v.get("ajustado_por_umbral"):
        s += f"; dijo «sí» pero su rúbrica no llega al umbral {v['ajustado_por_umbral']}"
    if not v.get("aprobado") and v.get("que_falta"):
        s += ": " + "; ".join(v["que_falta"][:3])[:300]
    return s



# ---- idempotencia, cuarentena y compensación (t-idempotencia-cuarentena-030)
# run_id = el id del encargo original (la raiz): va en cada task, ronda,
# revision, aprobacion y resultado. Cada efecto externo que hace Bridge se
# apunta en cola.db (tabla efectos) con su idempotencia_key = run_id:paso ANTES
# de ejecutarse; si al reintentar ya consta «hecho», no se repite, y si consta
# solo «registrado» (se murio entre hacer y apuntar) se COMPRUEBA si se hizo
# antes de repetir nada; si no se puede comprobar, cuarentena. Un fallo que no
# encaja en nada conocido no se reintenta ni se da por fallido: queda
# «en_cuarentena» con el error y la entrada a la vista hasta que decidas tu.
# Patron: reintento -> cuarentena -> escalada (tu) -> rollback (compensacion).
EFECTOS_COMPENSACION = {
    "enviar_correo": "sin compensación: revisión manual (un correo enviado no se puede retirar)",
    "crear_ticket": "cerrar el ticket que lleva el run_id como marcador (se busca por el marcador antes de crear)",
    "borrar": "soft-delete primero (a la papelera de Bridge, restaurable); el borrado definitivo, solo después",
    "mover_dinero": "reembolso usando el fingerprint del pago (la clave lleva el fingerprint del payload)",
    "escribir_archivos": "el worktree de la tarea (t-paralelo-seguro-030) o la copia previa (.bak)",
    "pedido_vm": "retirar outbox\\cosecha\\<id>.json si la VM aún no lo leyó; si ya corrió: sin compensación, "
                 "revisión manual (créditos gastados)",
}


def efectos_init():
    _cola("""CREATE TABLE IF NOT EXISTS efectos (
        clave TEXT PRIMARY KEY, run_id TEXT, paso TEXT, tipo TEXT, payload_sha TEXT, estado TEXT,
        resultado TEXT, compensacion TEXT, registrado_en TEXT, hecho_en TEXT, intentos INTEGER DEFAULT 0)""")


def efecto_clave(run_id, paso, payload=None, tipo=None):
    """run_id:paso; para mover dinero, con el fingerprint del payload (otra cantidad = otro efecto)."""
    clave = f"{run_id}:{paso}"
    if tipo == "mover_dinero" and payload is not None:
        clave += ":" + hashlib.sha256(json.dumps(payload, sort_keys=True).encode("utf-8")).hexdigest()[:12]
    return clave


def efecto_get(clave):
    r = _cola("SELECT * FROM efectos WHERE clave=?", (clave,), fetch=True)
    return dict(r[0]) if r else None


def efecto_ejecutar(run_id, paso, tipo, payload, fn, comprobar=None):
    """Hace el efecto UNA vez. (estado, resultado): «hecho» (ahora), «ya_hecho» (no se repite),
    «cuarentena» (consta empezado y no se puede comprobar si se hizo)."""
    efectos_init()
    clave = efecto_clave(run_id, paso, payload, tipo)
    sha = hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:16]
    fila = efecto_get(clave)
    if fila and fila["estado"] == "hecho":
        log(f"efectos: {clave} ({tipo}) ya está hecho ({fila['hecho_en']}): no se repite")
        return "ya_hecho", fila["resultado"]
    if fila and fila["estado"] == "registrado":
        # se murió entre «hacer» y «apuntar»: se comprueba ANTES de repetir
        hecho = None
        if comprobar is not None:
            try:
                hecho = comprobar()
            except Exception as e:
                log(f"efectos: {clave}: no se pudo comprobar ({type(e).__name__}: {e})")
        if hecho:
            _cola("UPDATE efectos SET estado='hecho', resultado=?, hecho_en=? WHERE clave=?",
                  (f"comprobado tras un corte: {hecho}", _now_iso(), clave))
            log(f"efectos: {clave} constaba empezado; comprobado que SÍ se hizo ({hecho}): no se repite")
            return "ya_hecho", str(hecho)
        if comprobar is None or hecho is None:
            _cola("UPDATE efectos SET estado='cuarentena' WHERE clave=?", (clave,))
            log(f"efectos: {clave} constaba empezado y no se puede comprobar si se hizo: cuarentena (no se repite)")
            return "cuarentena", "consta empezado y no se puede comprobar si se hizo"
    if fila and fila["estado"] == "cuarentena":
        return "cuarentena", "en cuarentena: decide tú antes de repetirlo"
    _cola("INSERT OR REPLACE INTO efectos (clave, run_id, paso, tipo, payload_sha, estado, compensacion, "
          "registrado_en, intentos) VALUES (?, ?, ?, ?, ?, 'registrado', ?, ?, ?)",
          (clave, run_id, paso, tipo, sha, EFECTOS_COMPENSACION.get(tipo, "sin compensación: revisión manual"),
           _now_iso(), ((fila or {}).get("intentos") or 0) + 1))
    res = fn()  # el efecto de verdad (si el proceso muere aquí, queda «registrado»)
    _cola("UPDATE efectos SET estado='hecho', resultado=?, hecho_en=? WHERE clave=?",
          (str(res)[:500], _now_iso(), clave))
    log(f"efectos: {clave} ({tipo}) hecho: {str(res)[:160]}")
    return "hecho", res


def efectos_de(run_id):
    efectos_init()
    return [dict(r) for r in _cola("SELECT * FROM efectos WHERE run_id=? ORDER BY registrado_en", (run_id,),
                                   fetch=True)]


def efecto_compensar(clave):
    """La acción inversa, si la hay. (hecho, texto)."""
    f = efecto_get(clave)
    if f is None:
        return False, "no existe ese efecto"
    if f["tipo"] == "pedido_vm":
        p = COSECHA_OUT / f"{f['run_id']}.json"
        if p.exists():
            p.unlink()
            _cola("UPDATE efectos SET estado='compensado', resultado=? WHERE clave=?",
                  (f"retirado {p.name} del outbox", clave))
            log(f"efectos: {clave}: compensado (retirado {p.name} antes de que la VM lo leyera)")
            return True, f"retirado {p.name}"
        return False, "la VM ya lo recogió: sin compensación, revisión manual"
    return False, f["compensacion"] or "sin compensación: revisión manual"


def _es_ambiguo(result):
    """Un fallo que no encaja en ninguna respuesta conocida (ni pasajero ni definitivo)."""
    if result.get("status") in ("ok", "timeout") or result.get("error_tipo") in ("transitorio", "definitivo"):
        return False
    err = str(result.get("error") or "")
    if not err or _DEFINITIVO_RE.search(err):
        return False
    txt = " ".join((err, str(result.get("stderr") or "")[-1500:]))
    return not _TRANSITORIO_RE.search(txt)


def _reporte_fallo(task, result, fam, motivo, cuarentena=False):
    """Qué se intentó, qué quedó hecho (comprobado), qué no se pudo confirmar,
    cuánto costó y el siguiente paso."""
    encargo = re.sub(r"\s+", " ", (fam or {}).get("encargo") or task.get("prompt") or "")[:180]
    hecho = []
    try:
        desde = _iso_ts(result.get("started_at")) - 2
        hecho = [p for p in _touched_files(task["cwd"], desde) if Path(p).exists()][:8]
    except Exception:
        hecho = []
    efs = efectos_de(task.get("run_id") or task.get("raiz") or task["id"])
    costo_i = result.get("cost_usd") if isinstance(result.get("cost_usd"), (int, float)) else None
    costo_f = (fam or {}).get("costo_usd")
    if cuarentena:
        sig = ("decide tú: «Volver a la cola» si fue algo puntual, corrige el encargo, o «Abandonar» "
               "(y deshaz lo hecho con su compensación)")
    elif re.search(r"clave|credencial|401|403|config|no existe|no est[aá] instalado", motivo, re.I):
        sig = "corrige la configuración o el encargo y vuelve a encolarla"
    else:
        sig = "reintentar más tarde, o abandonar"
    return (f"{NO_CONFIRMADO} Se intentó: «{encargo}». "
            + ("Quedó hecho (comprobado en archivos): " + "; ".join(hecho) + ". " if hecho else
               "No hay nada comprobado en archivos. ")
            + ("Efectos registrados: " + "; ".join(f"{e['paso']} ({e['tipo']}): {e['estado']}" for e in efs) + ". "
               if efs else "")
            + f"No se pudo confirmar: {motivo[:300]}. "
            + "Costó: " + (f"${costo_i:.4f} este intento" if costo_i is not None else "sin dato este intento")
            + (f" (${costo_f:.4f} en total)" if isinstance(costo_f, (int, float)) and costo_f else "") + ". "
            + f"Siguiente paso: {sig}.")


def cuarentena_snapshot(task, result):
    snap = {"run_id": task.get("run_id") or task.get("raiz"), "tarea": task["id"], "at": _now_iso(),
            "error": result.get("error"), "stderr_final": str(result.get("stderr") or "")[-1500:],
            "entrada": {k: task.get(k) for k in ("prompt", "motor", "modelo", "cwd", "criterios", "ronda",
                                                 "permission_mode", "allowed_tools")},
            "efectos": efectos_de(task.get("run_id") or task.get("raiz") or task["id"]),
            "que_hacer": "Volver a la cola (Tareas) o Abandonar (Ctrl+K). No se reintenta solo."}
    p = RESULTS / f"{task['id']}.cuarentena.json"
    p.write_text(json.dumps(snap, ensure_ascii=False, indent=2, default=str), encoding="utf-8")
    return p


def cuarentena_abandonar(raiz):
    fam = load_family(raiz) or {}
    if fam.get("estado") != "en_cuarentena":
        return False, "esa tarea no está en cuarentena"
    _family_update(raiz, estado="fallida", reporte=(fam.get("reporte") or "") + " Abandonada por ti desde la cuarentena.")
    cola_set(fam.get("ultimo_resultado") or raiz, estado="fallida", motivo="abandonada desde la cuarentena")
    log(f"cuarentena: {raiz} abandonada por el usuario")
    return True, "abandonada"


def _honest_report(estado, task, rev, fam, error=None):
    """Regla anti-exito-inventado: solo se dice que algo funciono si esta
    comprobado contra archivos reales (o, sin criterios, si hay respuesta)."""
    rondas = fam.get("ronda", 0) if fam else task.get("ronda", 0)
    motor = task.get("motor")
    checks = (rev or {}).get("verificacion_automatica") or []
    verified = [d for c in checks for d in c["detalle"] if d not in c["falla"]]
    if estado == "aprobada":
        base = f"Aprobada por la revisión ({(rev or {}).get('motor_revision')})"
        base += f" tras {rondas} ronda(s) de corrección." if rondas else "."
        if verified:
            return base + " Comprobado en archivos: " + "; ".join(verified[:6]) + "."
        if task.get("criterios") or task.get("criterios_tipados"):
            return base + (" La aprobación se basa en el texto del resultado: no hay archivos "
                           "que lo confirmen.")
        return base + " Solo se comprobó que hay respuesta y no hay error."
    if estado == "necesita_decision" and (rev or {}).get("necesita_decision"):
        ambos = " / ".join(veredicto_txt(v) for v in rev.get("veredictos") or [] if v)
        motivo = rev.get("motivo_decision") or "los jueces no coinciden"
        txt = (f"{NO_CONFIRMADO} {motivo[:1].upper() + motivo[1:]}: {ambos}. "
               "No se aprueba sola ni se hace otra ronda: decide tú (Tareas → DETALLE).")
        if verified:
            txt += " Lo que sí está comprobado en archivos: " + "; ".join(verified[:6]) + "."
        fallos = [f for c in checks for f in c["falla"]]
        if fallos:
            txt += " Checks que fallan: " + "; ".join(fallos[:4]) + "."
        return txt
    if estado == "necesita_decision":
        faltas = "; ".join((rev or {}).get("que_falta") or []) or "no se sabe"
        txt = (f"Se intentó el encargo con {motor} en {rondas} ronda(s) de corrección (máximo "
               f"{MAX_ROUNDS}). No se pudo confirmar: {faltas}.")
        if verified:
            return txt + " Lo que sí está comprobado en archivos: " + "; ".join(verified[:6]) + "."
        return NO_CONFIRMADO + " " + txt
    if estado == "sin_revision":
        return (f"Terminó, pero no se pudo revisar ({error or (rev or {}).get('error')}). "
                "Nadie ha comprobado que esté bien.")
    return f"{NO_CONFIRMADO} {error or 'falló'}."


def _new_task_file(data):
    TASKS.mkdir(parents=True, exist_ok=True)
    base, i = data["id"], 1
    while any((d / f"{data['id']}.task.json").exists() for d in (TASKS, PROCESSING, DONE, WAITING)):
        data["id"] = f"{base}-{i}"
        i += 1
    path = TASKS / f"{data['id']}.task.json"
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    t = time.time() - 5
    os.utime(path, (t, t))
    cola_registrar(path, data)
    return data["id"]


def _task_core(task):
    """Lo que hereda una ronda o una fase de su tarea."""
    d = {"cwd": task["cwd"], "motor": task["motor"], "timeout_min": task["timeout_min"],
         "allowed_tools": task.get("allowed_tools"), "permission_mode": task.get("permission_mode"),
         "sensible": task.get("sensible") or None, "enrutado": task.get("enrutado"),
         "acciones": task.get("acciones") or None, "canal": task.get("canal"),
         "lane": task.get("lane"), "archivos": task.get("archivos"), "lee": task.get("lee"),
         "lee_carril_a": task.get("lee_carril_a") or None,
         "memoria": False if task.get("memoria") is False else None,
         "asistente": task.get("asistente")}  # la ronda o la fase sigue con el mismo asistente
    if task.get("model") is not None:  # api:... y motores con modelo.permitidos
        d["model"] = task.get("model")
    else:
        d["modelo"] = task.get("modelo")
    return {k: v for k, v in d.items() if v is not None}


def _enqueue_round(task, result, rev):
    n = task.get("ronda", 0) + 1
    raiz = task["raiz"]
    # Sin reanudar en su descriptor, la ronda es una sesion nueva con resumen.
    sin_sesion = not soporta_reanudar(get_engine(task.get("motor") or ""))
    sid = None if sin_sesion else (result.get("session_id") or task.get("session_id"))
    prompt = ("Revisé tu trabajo y faltan estas cosas. Corrígelas (solo esto):\n"
              + "\n".join(f"- {x}" for x in rev["que_falta"]))
    if not sid:
        fam = load_family(raiz) or {}
        if sin_sesion:
            resumen = re.sub(r"\s+", " ", (result.get("result") or "")).strip()[:1500]
            prompt += ("\n\n(Este motor no puede continuar una sesión: es una sesión nueva. "
                       "Resumen de tu respuesta anterior:)\n" + (resumen or "(sin texto)"))
        prompt += ("\n\n(No hay sesión que continuar; este era el encargo:)\n"
                   + (fam.get("encargo") or task["prompt"])[:4000])
    data = dict(_task_core(task), id=f"{raiz[:70]}-r{n}", prompt=prompt, session_id=sid,
                criterios=(task.get("criterios") or []) + (task.get("criterios_tipados") or []),
                ronda=n, tarea_padre=raiz, raiz=raiz, run_id=task.get("run_id") or raiz,
                fase=task.get("fase"), siguiente_fase=task.get("siguiente_fase"),
                fase_base=task.get("fase_base"), creada_por="runner: ronda de corrección")
    return _new_task_file({k: v for k, v in data.items() if v is not None})


def _next_fase_label(fase):
    m = re.search(r"(\d+)(\s*(?:de|/)\s*\d+)?", str(fase or ""))
    if not m:
        return None
    return fase[:m.start(1)] + str(int(m.group(1)) + 1) + fase[m.end(1):]


def _enqueue_next_phase(task, result):
    nxt = task.get("siguiente_fase")
    if isinstance(nxt, dict):
        prompt, crits = nxt.get("prompt"), nxt.get("criterios")
        after, label = nxt.get("siguiente_fase"), nxt.get("fase")
    else:
        prompt, crits, after, label = nxt, None, None, None
    label = label or _next_fase_label(task.get("fase"))
    base = (task.get("fase_base") or task["raiz"])[:68]
    m = re.search(r"(\d+)", str(label or ""))
    k = int(m.group(1)) if m else 2
    resumen = re.sub(r"\s+", " ", (result.get("result") or "")).strip()[:700]
    sid = (result.get("session_id") or task.get("session_id")) \
        if soporta_reanudar(get_engine(task.get("motor") or "")) else None
    full = (f"{prompt}\n\nContexto de lo ya hecho en la fase anterior ({task.get('fase') or task['raiz']}), "
            f"resumen corto:\n{resumen or '(sin texto)'}")
    data = dict(_task_core(task), id=f"{base}-f{k}", prompt=full, session_id=sid,
                criterios=crits or [], fase=label, siguiente_fase=after, fase_base=base,
                fase_anterior=task["raiz"], creada_por="runner: siguiente fase")
    data = {k2: v for k2, v in data.items() if v is not None}
    new_id = _new_task_file(data)
    _family_update(new_id, estado="pendiente", motor=task["motor"], fase=label,
                   fase_anterior=task["raiz"], encargo=full[:2000], criterios=crits or [])
    return new_id


def _after_run(task, result):
    """Despues de correr: revisar y decidir (aprobada / otra ronda /
    necesita decision / fallida / sin revision)."""
    raiz, n = task["raiz"], task.get("ronda", 0)
    ya_sumado = result.pop("_costo_ya_sumado", False)  # se corto revisando: el motor ya conto
    _family_update(raiz, sumar_costo=None if ya_sumado else result.get("cost_usd"), ultimo_resultado=task["id"],
                   session_id=result.get("session_id"), en_curso=None, solo_si_falta_proyecto=task.get("proyecto"))
    rev = None
    tope = _tope_superado(task, result)
    if tope:  # tope de gasto (con reintentos y rondas): se para y decides tu
        estado, reporte = "necesita_decision", (
            f"Parada por el tope de gasto: lleva ${tope[0]:.2f} de ${tope[1]:.2f} (con reintentos, rondas y "
            "revisiones). No sigue gastando: decide tú si subes el tope o la cierras.")
        log(f"runner [{task['id']}]: tope de gasto: ${tope[0]:.2f} de ${tope[1]:.2f}; queda en necesita_decision")
    elif result["status"] != "ok" and result.get("estado") == "necesita_decision":
        estado, reporte = "necesita_decision", (
            f"{NO_CONFIRMADO} {result.get('motivo_decision')}. Lo hecho hasta aquí está guardado (checkpoint y "
            "rondas anteriores): nada se borró. Decide tú: reintentar más tarde, cambiar de motor o cerrarla.")
    elif result["status"] != "ok" and _es_ambiguo(result):
        # ni pasajero ni definitivo conocido: ni reintento ni fallida; decide Leandro (t-idempotencia-cuarentena-030)
        snap = cuarentena_snapshot(task, result)
        estado = "en_cuarentena"
        reporte = (_reporte_fallo(task, result, load_family(raiz), str(result.get("error")), cuarentena=True)
                   + f" El error y la entrada están en {snap.name}.")
        log(f"runner [{task['id']}]: EN CUARENTENA (fallo que no encaja en nada conocido): {str(result.get('error'))[:200]}")
    elif result["status"] != "ok":
        motivo = result.get("error") or result["status"]
        estado, reporte = "fallida", _reporte_fallo(task, result, load_family(raiz), str(motivo))
    elif not task.get("revisar", True):
        estado, reporte = "sin_revision", _honest_report("sin_revision", task, None, None,
                                                         "la tarea pidió no revisarla")
    else:
        state["paso"] = f"Revisando {raiz}" + (f" (ronda {n}/{MAX_ROUNDS})" if n else "")
        _family_update(raiz, estado="revisando")
        ck_revision_inicio(task)
        rev = review_task(task, result)
        try:
            with open(RESULTS / f"{task['id']}.revision.json", "w", encoding="utf-8") as f:
                json.dump(rev, f, ensure_ascii=False, indent=2)
        except OSError as e:
            log(f"runner [{task['id']}]: no se pudo guardar la revisión: {e}")
        result["revision"] = f"{task['id']}.revision.json"
        fam = _family_update(raiz, sumar_costo=rev.get("cost_usd"), ultima_revision={
            "id": task["id"], "aprobado": rev["aprobado"], "que_falta": rev["que_falta"],
            "motor": rev["motor_revision"], "evidencia": rev["evidencia"][:8],
            "decision": rev.get("decision"), "necesita_decision": rev.get("necesita_decision"),
            "motivo_decision": rev.get("motivo_decision"), "nivel": rev.get("nivel"),
            "juez_contra_hechos": rev.get("juez_contra_hechos"), "recorte": rev.get("recorte"),
            "checks": [{"criterio": c["criterio"], "resultado": c["resultado"], "tipado": c.get("tipado"),
                        "detalle": c["detalle"][:2]} for c in rev.get("checks_deterministas") or []][:12],
            "veredictos": [{k: v.get(k) for k in ("rol", "motor", "nombre", "modelo", "estado", "aprobado",
                                                  "puntuacion", "ajustado_por_umbral", "costo_usd", "segundos")}
                           | {"que_falta": (v.get("que_falta") or [])[:4], "errores": (v.get("errores") or [])[:3]}
                           for v in rev.get("veredictos") or [] if v],
            "segundo_juez": {k: (rev.get("segundo_juez") or {}).get(k) for k in
                             ("llamado", "motivo", "por_que_no", "motor", "modelo", "estado", "costo_usd",
                              "segundos")} if rev.get("segundo_juez") else None,
            "calibracion_id": rev.get("calibracion_id")})
        log(f"runner [{task['id']}]: revisión ({rev['motor_revision'] or 'ninguna'}): "
            f"{'aprobada' if rev['aprobado'] else 'no aprobada' if rev['aprobado'] is False else 'sin revisión'}")
        if rev.get("error") and "parado" in rev["error"]:
            estado, reporte = "fallida", _honest_report("fallida", task, rev, fam, rev["error"])
        elif rev["aprobado"] is None:
            estado, reporte = "sin_revision", _honest_report("sin_revision", task, rev, fam)
        elif rev.get("necesita_decision"):
            # Los jueces no coinciden (o aprueban contra un hecho): decide Leandro, sin otra ronda.
            estado, reporte = "necesita_decision", _honest_report("necesita_decision", task, rev, fam)
        elif rev["aprobado"]:
            estado, reporte = "aprobada", _honest_report("aprobada", task, rev, fam)
            if task.get("siguiente_fase"):
                # Checkpoint ANTES de encolar: si se corta en medio, al volver se
                # ve que falta la fase y se repite solo la revision (nunca dos fases).
                ck_revision_fin(task, rev, "terminada", "fase siguiente")
                nid = _enqueue_next_phase(task, result)
                reporte += f" Siguiente fase encolada: {nid}."
                _family_update(raiz, siguiente=nid)
                plan_tocar(task, "terminada", None, sig_task=nid)
                log(f"runner [{task['id']}]: aprobada; encolo la siguiente fase {nid}")
        elif n < MAX_ROUNDS and not _RUN.get("stop"):
            ck_revision_fin(task, rev, "revisada", f"ronda {n + 1}")
            nid = _enqueue_round(task, result, rev)
            _family_update(raiz, estado="en_curso", ronda=n + 1, ultima_ronda=nid)
            plan_tocar(task, "en_curso", f"ronda {n + 1}")
            log(f"runner [{task['id']}]: no aprobada; ronda de corrección {n + 1}/{MAX_ROUNDS}: {nid}")
            result["estado"] = "en_curso"
            _write_result(result)
            return
        else:
            estado, reporte = "necesita_decision", _honest_report("necesita_decision", task, rev, fam)
    reporte += _cola_nota(result)
    result["estado"], result["reporte"] = estado, reporte
    if not (estado == "aprobada" and task.get("siguiente_fase")):
        # El checkpoint primero: cuando la familia diga «terminada», el
        # checkpoint ya tiene el costo de la ultima revision.
        ck_revision_fin(task, rev, {"aprobada": "terminada"}.get(estado, estado), "terminada")
        plan_tocar(task, {"aprobada": "terminada", "sin_revision": "terminada", "rechazada": "fallida"}.get(
            estado, estado), None)
    _write_result(result)
    _family_update(raiz, estado=estado, reporte=reporte)
    log(f"runner [{raiz}]: {ESTADOS[estado]}: {reporte[:160]}")
    if estado == "fallida":
        mascota_evento("fallo", raiz)  # baja la cabeza una vez; el reporte vive en la fila
    dag_fase_terminada(task, estado)  # si es fase de un plan con grafo: avanza el plan


# ---------------------------------------------------------------- cola persistente
# cola.db (SQLite en modo WAL con synchronous=FULL, para que un apagon no la
# corrompa) es el registro de estado de cada tarea que entra a runner-tasks/.
# El .task.json sigue siendo el encargo; la base es lo que sobrevive. Al
# arrancar, lo que quedo en_curso por un corte vuelve a en_cola (intentos+1)
# y su resultado dira «recuperada tras corte». Nada se pierde en silencio.
COLA_DB = (Path(os.environ["GROWI_BRIDGE_COLA"]) if os.environ.get("GROWI_BRIDGE_COLA")
           else SHARE.parent / "cola.db" if os.environ.get("GROWI_BRIDGE_SHARE")
           else APP_DIR / "cola.db")
COLA_FINALES = ("terminada", "fallida", "necesita_decision", "archivada")
RETRY_BACKOFF_S = (30, 120, 480)  # 30 s, 2 min, 8 min, con +-20 % de azar (jitter)
MAX_RETRIES = len(RETRY_BACKOFF_S)
MAX_CORTES = 3                    # cortada 3 veces mientras corria: no se repite mas sola
ARCHIVE_DAYS = 30
CORTE = "recuperada tras corte"
_COLA_LOCK = threading.Lock()
_cola_err = [None]
_cola_vistos = set()
_cola_corriendo = set()  # ids que este mismo proceso esta corriendo ahora
# Errores pasajeros (se reintentan) y definitivos (nunca). Se mira primero lo
# definitivo: un "falta la clave" no se arregla esperando.
_DEFINITIVO_RE = re.compile(
    r"no existe en engines\.json|falta la clave|parado por el usuario|rechazad|"
    r"no est[aá] en el PATH|no encuentro '|tipo de motor desconocido|no est[aá] instalado|"
    r"CODIFICACI[OÓ]N|clave rechazada|sin permiso \(403\)|no encontrado \(404\)|"
    r"petici[oó]n rechazada \(400\)|JSON invalido|no es una direcci[oó]n local|"
    r"descriptor mal formado|sin credencial|\b40[13]\b|unauthori[sz]ed|forbidden|invalid.{0,4}api.?key", re.I)
_TRANSITORIO_RE = re.compile(
    r"no responde|servidor apagado|sin respuesta de|conexi[oó]n cortada|PROXY:|sin conexi[oó]n|"
    r"todav[ií]a est[aá] cargando|no respondi[oó] en|se cerr[oó] al arrancar|timed? ?out|timeout|"
    r"ECONNRE|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket hang up|fetch failed|network|overloaded|"
    r"\b5(?:00|02|03|04|29)\b|el servicio fall[oó]|l[ií]mite de uso|rate.?limit|\b429\b|"
    r"Connection(?:Reset|Aborted|Refused)Error|RemoteDisconnected|temporarily|temporalmente|\b408\b|cuota", re.I)


def _cola_conn():
    con = sqlite3.connect(str(COLA_DB), timeout=15, isolation_level=None)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA journal_mode=WAL")
    con.execute("PRAGMA synchronous=FULL")
    return con


def _cola(sql, args=(), fetch=False):
    """Una sentencia en cola.db (cada una se confirma sola). Si la base
    falla, el runner sigue como antes y lo dice en el registro."""
    try:
        with _COLA_LOCK:
            con = _cola_conn()
            try:
                cur = con.execute(sql, args)
                out = [dict(r) for r in cur.fetchall()] if fetch else cur.rowcount
            finally:
                con.close()
        _cola_err[0] = None
        return out
    except sqlite3.Error as e:
        if str(e) != _cola_err[0]:
            log(f"cola: ERROR en {COLA_DB.name} ({e}); el runner sigue, pero sin registro")
        _cola_err[0] = str(e)
        return [] if fetch else 0


def cola_init():
    _cola("""CREATE TABLE IF NOT EXISTS tareas (
        id TEXT PRIMARY KEY, archivo TEXT, estado TEXT NOT NULL,
        intentos INTEGER NOT NULL DEFAULT 0, reintentos INTEGER NOT NULL DEFAULT 0,
        cortes INTEGER NOT NULL DEFAULT 0, motor TEXT, ronda INTEGER,
        tarea_padre TEXT, raiz TEXT, fase TEXT, creado_en TEXT NOT NULL,
        actualizado_en TEXT NOT NULL, actualizado_ts REAL NOT NULL,
        proximo_intento REAL, motivo TEXT, historial TEXT)""")
    _cola("CREATE INDEX IF NOT EXISTS tareas_estado ON tareas(estado)")
    aprobaciones_init()
    checkpoint_init()
    calibracion_init()
    automations_init()
    dag_init()


def cola_get(tid):
    rows = _cola("SELECT * FROM tareas WHERE id=?", (tid,), fetch=True)
    return rows[0] if rows else None


def cola_set(tid, **kw):
    kw.update(actualizado_en=_now_iso(), actualizado_ts=time.time())
    if isinstance(kw.get("historial"), list):
        kw["historial"] = json.dumps(kw["historial"], ensure_ascii=False)
    cols = ", ".join(f"{k}=?" for k in kw)
    return _cola(f"UPDATE tareas SET {cols} WHERE id=?", (*kw.values(), tid))


def _cola_hist(row):
    try:
        h = json.loads((row or {}).get("historial") or "[]")
        return h if isinstance(h, list) else []
    except ValueError:
        return []


def _cola_id(task_file, data):
    tid = data.get("id") if isinstance(data, dict) else None
    return tid if _safe_id(tid) else Path(task_file).name.split(".task.json")[0]


def cola_registrar(task_file, data=None):
    """Apunta en cola.db una tarea de runner-tasks/ ANTES de recogerla. Si
    ya estaba terminada y vuelve a llegar con el mismo id, cuenta como nueva."""
    task_file = Path(task_file)
    if data is None:
        try:
            data = json.loads(task_file.read_text(encoding="utf-8"))
        except Exception:
            data = {}
    if not isinstance(data, dict):
        data = {}
    tid = _cola_id(task_file, data)
    row = cola_get(tid)
    if row is not None and row["estado"] == "en_cola" and row["archivo"] == str(task_file):
        return tid
    now = _now_iso()
    try:
        ronda = int(data.get("ronda") or 0)
    except (TypeError, ValueError):
        ronda = 0
    info = dict(motor=data.get("motor") or ("modelos" if "ollama_action" in data else None),
                ronda=ronda, tarea_padre=data.get("tarea_padre"),
                raiz=data.get("raiz") or tid, fase=data.get("fase"))
    if row is None:
        _cola("INSERT OR IGNORE INTO tareas (id, archivo, estado, motor, ronda, tarea_padre, raiz,"
              " fase, creado_en, actualizado_en, actualizado_ts) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
              (tid, str(task_file), "en_cola", *info.values(), now, now, time.time()))
    elif row["estado"] in COLA_FINALES:
        cola_set(tid, archivo=str(task_file), estado="en_cola", intentos=0, reintentos=0, cortes=0,
                 proximo_intento=None, motivo="llegó otra vez con el mismo id", historial=None,
                 creado_en=now, **info)
    else:  # aprobada (venia de esperando) o devuelta a la cola
        cola_set(tid, archivo=str(task_file), estado="en_cola")
    return tid


def _cola_ver(p):
    """Registra el archivo si es nuevo (o cambio) desde la ultima vuelta."""
    key = (p.name, p.stat().st_mtime_ns)
    if key not in _cola_vistos:
        if len(_cola_vistos) > 5000:
            _cola_vistos.clear()
        cola_registrar(p)
        _cola_vistos.add(key)


def cola_en_espera():
    """{nombre de archivo: hora} de las que esperan su reintento."""
    rows = _cola("SELECT archivo, proximo_intento FROM tareas WHERE estado='en_cola' "
                 "AND proximo_intento > ?", (time.time(),), fetch=True)
    return {Path(r["archivo"] or "").name: r["proximo_intento"] for r in rows}


def _hora(ts):
    return datetime.fromtimestamp(ts).astimezone().isoformat(timespec="seconds")


def cola_resumen():
    rows = _cola("SELECT estado, COUNT(*) AS n, MIN(CASE WHEN proximo_intento > ? THEN "
                 "proximo_intento END) AS prox FROM tareas GROUP BY estado",
                 (time.time(),), fetch=True)
    cuenta = {r["estado"]: r["n"] for r in rows}
    prox = min((r["prox"] for r in rows if r["prox"]), default=None)
    return {"cuenta": cuenta, "pendiente": cuenta.get("en_cola", 0) + cuenta.get("en_curso", 0),
            "proximo_reintento": _hora(prox) if prox else None}


def _es_transitorio(result):
    """Red, timeout del motor, llama-server/Ollama caido, proxy caido: se
    reintenta. Motor inexistente, falta de clave, parado/rechazado: no."""
    if result.get("status") == "timeout":
        return True
    # Lo que dice el descriptor del motor (errores.transitorio/definitivo)
    # manda; si no encaja ningun patron suyo, las reglas de siempre.
    if result.get("error_tipo") in ("transitorio", "definitivo"):
        return result["error_tipo"] == "transitorio"
    err = str(result.get("error") or "")
    if not err or _DEFINITIVO_RE.search(err):
        return False
    txt = " ".join((err, str(result.get("stderr") or "")[-1500:], str(result.get("result") or "")[:500]))
    return bool(_TRANSITORIO_RE.search(txt))


def _veces(n):
    return "1 vez" if n == 1 else f"{n} veces"


def _cola_nota(result):
    """Lo que se añade al reporte si hubo cortes o reintentos."""
    nota = ""
    if result.get("recuperada_tras_corte"):
        desde = result.get("reanudado_desde")
        nota += (f" Recuperada tras corte: se cortó {_veces(result.get('cortes') or 1)} mientras corría y "
                 + (f"se reanudó desde el checkpoint ({desde}), no desde cero." if desde
                    else "se repitió desde el principio."))
    if (result.get("reanudacion") or {}).get("sin_sesion_original"):
        nota += (f" Se reanudó sin la sesión original ({result['reanudacion'].get('motivo')}): sesión nueva "
                 "con el resumen del checkpoint.")
    if result.get("reintentos"):
        ult = (result.get("historial_reintentos") or [{}])[-1].get("error") or "?"
        nota += (f" Hicieron falta {result['reintentos']} reintento(s) por errores pasajeros "
                 f"(último: {str(ult)[:120]}).")
    return nota


# ---- cadena de respaldo del ejecutor (t-router-fallbacks)
# engines.json -> «fallback» (editable, nada fijo en el codigo). Reglas de
# OpenClaw (isFailoverWorthyBackendError): solo se cambia de motor ante un
# error TRANSITORIO (429, 408, 5xx, red, cuota, timeout, sin respuesta) y tras
# agotar los reintentos con backoff; un error definitivo (400/401/403,
# configuracion) nunca cambia de motor ni se reintenta. El cambio es ENTRE
# intentos o rondas (frontera limpia): el motor nuevo sigue con la sesion si
# puede; si no, con el resumen del checkpoint. Cambiar de motor es degradar
# el alcance: solo si la tarea lo declara («degradacion») o la seccion lo
# permite por defecto; sin regla, la decision no la toma el error: la tarea
# queda «necesita decision» con el trabajo parcial guardado.
_FB_DEF = {"ejecutor": {"cadena": ["claude", "gemini", "llama"]},
           "breaker": {"fallos": 3, "minutos": 5}, "cuota_aviso_pct": 90,
           "degradacion_sin_regla": "necesita_decision", "utilidad": "llama", "heartbeat": "llama"}
_MOTOR_BRK = {}  # motor -> {"seguidos", "abierto_hasta", "ultimo"}


def fallback_cfg():
    data, _e = load_engines()
    fb = data.get("fallback") if isinstance(data.get("fallback"), dict) else {}
    out = json.loads(json.dumps(_FB_DEF))
    for k, v in fb.items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k].update(v)
        elif not str(k).startswith("_"):
            out[k] = v
    return out


def cadena_ejecutor():
    """La cadena del ejecutor, solo con motores de la allowlist (los descritos
    en engines.json); uno de fuera se rechaza y se dice."""
    cad = [str(m) for m in (fallback_cfg().get("ejecutor") or {}).get("cadena") or []]
    ok = [m for m in cad if m in engine_ids()]
    fuera = [m for m in cad if m not in ok]
    if fuera and _FB_AVISO.get("fuera") != fuera:
        _FB_AVISO["fuera"] = fuera
        log(f"respaldo: {', '.join(fuera)} no está en la lista de motores (engines.json → motores): se rechaza "
            "en la cadena")
    return list(dict.fromkeys(ok))


_FB_AVISO = {}


def _nombre_motor(mid):
    return ((get_engine(mid) or {}).get("nombre") or mid) if mid else "?"


def degradacion_permitida(task):
    """(si/no, por qué). La tarea manda; si no dice nada, la sección fallback."""
    d = task.get("degradacion")
    if d in (True, "seguir") or (isinstance(d, dict) and d.get("permitida")):
        return True, "la tarea lo declara («si Claude no responde, sigue con el siguiente y avísame»)"
    if d in (False, "no", "preguntar") or (isinstance(d, dict) and d.get("permitida") is False):
        return False, "la tarea pide no cambiar de motor"
    if fallback_cfg().get("degradacion_sin_regla") == "seguir":
        return True, "engines.json → fallback.degradacion_sin_regla = seguir"
    return False, "ni la tarea ni engines.json declaran que se pueda seguir con otro motor"


def motor_breaker_abierto(mid):
    b = _MOTOR_BRK.get(mid) or {}
    return bool(b.get("abierto_hasta") and time.time() < b["abierto_hasta"])


def motor_fallo_apuntar(mid, result, transitorio):
    """Breaker por motor: 3 fallos transitorios seguidos -> 5 min al
    respaldo; despues se sondea el primario con la siguiente tarea."""
    if not mid:
        return
    b = _MOTOR_BRK.setdefault(mid, {"seguidos": 0, "abierto_hasta": None, "ultimo": None})
    if result.get("status") == "ok":
        if b["seguidos"] or b["abierto_hasta"]:
            log(f"respaldo: {_nombre_motor(mid)} vuelve a responder: se cierra su breaker")
        b.update(seguidos=0, abierto_hasta=None)
        return
    if not transitorio:
        return
    b["seguidos"] += 1
    b["ultimo"] = str(result.get("error") or result.get("status"))[:160]
    cfg = fallback_cfg().get("breaker") or {}
    n, mins = int(cfg.get("fallos") or 3), float(cfg.get("minutos") or 5)
    if b["seguidos"] >= n and not motor_breaker_abierto(mid):
        b["abierto_hasta"] = time.time() + mins * 60
        sig = _siguiente_motor(mid, None)
        log(f"respaldo: {_nombre_motor(mid)} no responde ({n} fallos seguidos; el último: {b['ultimo']}): "
            f"{mins:g} min trabajando con {_nombre_motor(sig) if sig else 'nadie (cadena agotada)'}; luego se "
            f"vuelve a probar {_nombre_motor(mid)}")
        try:
            _ui_call(lambda: toast(f"{_nombre_motor(mid)} no responde: {mins:g} min con "
                                   f"{_nombre_motor(sig) if sig else 'nadie'}", ("tareas",)))
        except Exception:
            pass


def _siguiente_motor(actual, task, probados=()):
    """El siguiente de la cadena que esté encendido, disponible y sin breaker."""
    cad = cadena_ejecutor()
    i = cad.index(actual) if actual in cad else -1
    for m in cad[i + 1:]:
        if m in probados or m == actual or motor_breaker_abierto(m) or m in motores_apagados():
            continue
        try:
            ok, _why = engine_status(m)
        except Exception:
            ok = False
        if ok:
            return m
    return None


def _ruta_motor(task, de, a, motivo):
    r = dict(task.get("ruta_motor") or {})
    pasos = list(r.get("pasos") or [])
    pasos.append(f"{de}: {motivo} -> {a}")
    r.update(motor_elegido=a, motivo_eleccion=f"respaldo de {de}", escalon_previo=de, motivo_escalado=motivo,
             pasos=pasos, probados=list(dict.fromkeys(list(r.get("probados") or []) + [de])))
    return r


def router_antes(task, task_file, cid):
    """Antes de lanzar: si el motor tiene el breaker abierto (o la cuota está
    a punto de acabarse), la tarea va al respaldo si puede degradarse; si no,
    espera a que pase el breaker. (task, 'seguir'|'pospuesta')."""
    mid = task.get("motor")
    cad = cadena_ejecutor()
    if mid not in cad:
        return task, "seguir"
    motivo = None
    if motor_breaker_abierto(mid):
        b = _MOTOR_BRK[mid]
        motivo = f"breaker abierto ({b['seguidos']} fallos seguidos; el último: {b['ultimo']})"
    elif mid == "claude":
        pct = None
        try:
            pct = _quota_pct()
        except Exception:
            pct = None
        umbral = fallback_cfg().get("cuota_aviso_pct") or 90
        if isinstance(pct, (int, float)) and pct >= umbral:
            motivo = f"cuota de Claude al {pct:.0f} % (aviso desde el {umbral:g} %): mejor cambiar antes del corte"
    if not motivo:
        return task, "seguir"
    ok, por_que = degradacion_permitida(task)
    sig = _siguiente_motor(mid, task, (task.get("ruta_motor") or {}).get("probados") or ())
    if ok and sig:
        motor_cambio(mid, sig, f"{_nombre_motor(mid)}: {motivo}; la tarea {task['id']} sigue con {_nombre_motor(sig)}")
        task = dict(task, motor=sig, ruta_motor=_ruta_motor(task, mid, sig, motivo))
        task.pop("model", None)
        task.pop("modelo", None)
        _fb_reescribir(task_file, task)
        return task, "seguir"
    if motor_breaker_abierto(mid):
        hasta = _MOTOR_BRK[mid]["abierto_hasta"]
        cola_set(cid, estado="en_cola", proximo_intento=hasta,
                 motivo=f"esperando a {_nombre_motor(mid)} ({motivo}); no cambia de motor: {por_que}")
        log(f"runner [{task['id']}]: {_nombre_motor(mid)} {motivo}: espera hasta las {_hora(hasta)[11:19]} "
            f"(no cambia de motor: {por_que})")
        return task, "pospuesta"
    log(f"runner [{task['id']}]: {motivo}; sigue con {_nombre_motor(mid)} (no cambia de motor: {por_que})")
    return task, "seguir"


def _fb_reescribir(task_file, task):
    try:
        d = json.loads(Path(task_file).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return
    d["motor"] = task["motor"]
    d.pop("model", None)
    d.pop("modelo", None)
    d["ruta_motor"] = task.get("ruta_motor")
    Path(task_file).write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")


def fallback_tras_fallo(cid, task, task_file, processing_path, result, row):
    """Reintentos agotados con un error transitorio: siguiente de la cadena
    (si se puede degradar) o necesita_decision. True si ya se encargó."""
    mid = task.get("motor")
    if mid not in cadena_ejecutor():
        return False
    err = str(result.get("error") or result.get("status"))[:200]
    ok, por_que = degradacion_permitida(task)
    probados = list((task.get("ruta_motor") or {}).get("probados") or []) + [mid]
    sig = _siguiente_motor(mid, task, probados) if ok else None
    if sig:
        nuevo = dict(task, motor=sig, ruta_motor=_ruta_motor(task, mid, sig, err))
        motor_cambio(mid, sig, f"{_nombre_motor(mid)} no responde ({err[:120]}): la tarea {task['id']} sigue con "
                               f"{_nombre_motor(sig)}")
        dest = TASKS / task_file.name
        try:
            os.replace(processing_path, dest)
        except OSError as e:
            log(f"runner [{task['id']}]: respaldo: no se pudo devolver a la cola ({e})")
            return False
        _fb_reescribir(dest, nuevo)
        hist = _cola_hist(row) + [{"respaldo": f"{mid} -> {sig}", "error": err, "at": _now_iso()}]
        cola_set(cid, estado="en_cola", archivo=str(dest), intentos=(row.get("intentos") or 0) + 1,
                 reintentos=0, proximo_intento=None, motivo=f"respaldo: {mid} -> {sig} ({err[:120]})",
                 historial=hist, motor=sig)
        _family_update(task["raiz"], estado="pendiente", en_curso=None, motor=sig,
                       ruta_motor=nuevo["ruta_motor"], sumar_costo=result.get("cost_usd"))
        return True
    motivo = (f"{_nombre_motor(mid)} falló con un error pasajero ({err}) tras {MAX_RETRIES} reintentos y "
              + (f"no queda nadie en la cadena ({' -> '.join(cadena_ejecutor())}) que responda"
                 if ok else f"no se cambia de motor: {por_que}"))
    result.update(estado="necesita_decision", motivo_decision=motivo,
                  ruta_motor=_ruta_motor(task, mid, "nadie", err) if ok else task.get("ruta_motor"))
    result.setdefault("avisos", []).append(motivo + ". Lo hecho hasta aquí está guardado (checkpoint y "
                                                    "resultados de las rondas anteriores): nada se borró.")
    log(f"runner [{task['id']}]: necesita tu decisión: {motivo}")
    return False


def _ruta_revisor(j1, intentos):
    """motor_elegido / motivo_eleccion / escalon_previo / motivo_escalado de la revisión."""
    pasos = []
    for i in intentos:
        err = "; ".join(i.get("errores") or [])[:90]
        pasos.append(f"{i.get('motor')}{(':' + i['modelo']) if i.get('modelo') else ''}: {i.get('estado')}"
                     + (f" ({err})" if err else ""))
    if j1:
        pasos.append(f"{j1.get('motor')}{(':' + j1['modelo']) if j1.get('modelo') else ''}: {j1.get('estado')}")
    previo = intentos[-1] if intentos else None
    return {"motor_elegido": (f"{j1['motor']}" + (f":{j1['modelo']}" if j1.get("modelo") else "")) if j1 else None,
            "motivo_eleccion": ("el primero de la cadena del revisor que respondió" if j1 and not intentos else
                                "respaldo: los anteriores de la cadena no respondieron" if j1 else
                                "ningún juez de la cadena respondió"),
            "escalon_previo": previo.get("motor") if previo else None,
            "motivo_escalado": "; ".join(previo.get("errores") or [])[:200] if previo else None,
            "cadena_revisor": " -> ".join(pasos)}


# ---- Modelos -> «Cadena de respaldo» (t-router-fallbacks): la cadena y el
# modelo activo, con ↑/↓ para reordenar. Se guarda en engines.json (con .bak)
# y vale para la siguiente tarea sin reiniciar (la recarga en caliente la ve;
# la que esté en curso termina con el motor con el que empezó).
_CAD = {"kit": None}


def fallback_guardar(ejecutor=None, revisor=None):
    """Reordena la cadena del ejecutor y/o la del revisor (revision.orden). (ok, msg)."""
    try:
        raw = json.loads(ENGINES_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        return False, f"no se pudo leer engines.json ({e})"
    if ejecutor is not None:
        fuera = [m for m in ejecutor if m not in (raw.get("motores") or {})]
        if fuera:
            return False, f"{', '.join(fuera)} no está en la lista de motores: no puede ir en la cadena"
        fb = raw.setdefault("fallback", {})
        fb.setdefault("ejecutor", {})["cadena"] = list(ejecutor)
    if revisor is not None:
        orden = (raw.get("revision") or {}).get("orden") or []
        por = {(x.get("motor"), x.get("modelo")): x for x in orden if isinstance(x, dict)}
        raw["revision"]["orden"] = [por[k] for k in revisor if k in por]
        raw.setdefault("fallback", {}).setdefault("revisor", {})["cadena"] = [
            m + (f":{mod}" if mod else "") for m, mod in revisor]
    try:
        shutil.copy2(ENGINES_FILE, ENGINES_FILE.with_name(ENGINES_FILE.name + ".bak"))
        tmpf = ENGINES_FILE.with_name(ENGINES_FILE.name + ".tmp")
        tmpf.write_text(json.dumps(raw, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmpf, ENGINES_FILE)
    except OSError as e:
        return False, f"no se pudo escribir engines.json ({e})"
    if ejecutor is not None:
        log(f"respaldo: cadena del ejecutor ahora: {' -> '.join(ejecutor)} (desde Modelos; vale para la "
            "siguiente tarea, sin reiniciar)")
    if revisor is not None:
        log(f"respaldo: cadena del revisor ahora: {' -> '.join(m + (':' + d if d else '') for m, d in revisor)}")
    return True, "guardado"


def _build_cadena_card(tab):
    holder = tk.Frame(tab, bg=THEME["bg"])
    holder.pack(fill="x")
    k = None
    if _ctk_wanted():
        try:
            k = _KitCtk(holder)
        except Exception as e:
            log(f"respaldo: CustomTkinter no disponible ({type(e).__name__}: {e}); tarjeta clásica")
    k = k or _KitTk(holder)
    _CAD["kit"] = k
    card = k.section("Cadena de respaldo", "Si el motor de una tarea no responde (429, 5xx, red, cuota, timeout) tras "
                                           "los reintentos, sigue el siguiente; solo si la tarea lo permite. Un "
                                           "401/403 nunca cambia de motor. Se guarda en engines.json y vale para la "
                                           "siguiente tarea, sin reiniciar.")
    _CAD["activo"] = k.label(card, "", wrap=560)
    _CAD["activo"].pack(anchor="w", padx=16, pady=(2, 4))
    k.label(card, "Quien hace la tarea", bold=True, wrap=0).pack(anchor="w", padx=16, pady=(4, 0))
    _CAD["ejec"] = k.frame(card)
    _CAD["ejec"].pack(fill="x", padx=16)
    k.label(card, "Quien la revisa", bold=True, wrap=0).pack(anchor="w", padx=16, pady=(8, 0))
    _CAD["rev"] = k.frame(card)
    _CAD["rev"].pack(fill="x", padx=16)
    _CAD["pie"] = k.label(card, "", muted=True, wrap=560)
    _CAD["pie"].pack(anchor="w", padx=16, pady=(6, 12))
    _cadena_render()


def _cadena_estado(mid):
    if motor_breaker_abierto(mid):
        b = _MOTOR_BRK[mid]
        return f"en pausa hasta las {_hora(b['abierto_hasta'])[11:16]} ({b['seguidos']} fallos seguidos)", "red"
    if mid in motores_apagados():
        return "apagado", "muted"
    m = next((x for x in (_GW_ESTADO_CACHE.get("motores") or []) if x["id"] == mid), None)
    if m is None:
        return "sin comprobar", "muted"
    return ("disponible", "green_text") if m["disponible"] else ("no disponible", "orange_text")


def _cadena_render():
    k = _CAD.get("kit")
    if k is None:
        return
    for box in (_CAD["ejec"], _CAD["rev"]):
        for ch in box.winfo_children():
            ch.destroy()
    cfg = fallback_cfg()
    info = cfg.get("motores") or {}
    cad = cadena_ejecutor()
    for i, mid in enumerate(cad):
        r = k.frame(_CAD["ejec"])
        r.pack(fill="x", pady=1)
        est, col = _cadena_estado(mid)
        d = info.get(mid) or {}
        k.label(r, f"{i + 1}. {_nombre_motor(mid)}", wrap=0).pack(side="left")
        k.label(r, f"  {d.get('rol') or ('principal' if i == 0 else 'respaldo')}, {d.get('coste') or 'sin dato'}: ",
                muted=True, wrap=0).pack(side="left")
        k.label(r, est, wrap=0, color=col).pack(side="left")
        if i < len(cad) - 1:
            k.button(r, "↓", lambda i=i: _cadena_mover("ejec", i, 1)).pack(side="right", padx=(4, 0))
        if i:
            k.button(r, "↑", lambda i=i: _cadena_mover("ejec", i, -1)).pack(side="right", padx=(4, 0))
    orden = [(x.get("motor"), x.get("modelo")) for x in (_rev_cfg().get("orden") or []) if isinstance(x, dict)]
    for i, (mid, mod) in enumerate(orden):
        r = k.frame(_CAD["rev"])
        r.pack(fill="x", pady=1)
        k.label(r, f"{i + 1}. {_nombre_motor(mid)}" + (f" ({mod})" if mod else ""), wrap=0).pack(side="left")
        if i < len(orden) - 1:
            k.button(r, "↓", lambda i=i: _cadena_mover("rev", i, 1)).pack(side="right", padx=(4, 0))
        if i:
            k.button(r, "↑", lambda i=i: _cadena_mover("rev", i, -1)).pack(side="right", padx=(4, 0))
    cur = state.get("current_motor")
    k.set_label(_CAD["activo"], text=(f"Activo ahora: {_nombre_motor(cur)} (en la tarea {state.get('current')}; "
                                      "termina con este motor aunque cambies la cadena)" if cur else
                                      f"Activo ahora: ninguna tarea en curso; la siguiente empieza con "
                                      f"{_nombre_motor(cad[0]) if cad else default_motor()}."))
    brk = cfg.get("breaker") or {}
    k.set_label(_CAD["pie"], text=(
        f"Si un motor falla {brk.get('fallos', 3)} veces seguidas, {brk.get('minutos', 5)} min al siguiente y luego "
        f"se vuelve a probar. Revisión, latidos y resúmenes: {_nombre_motor(cfg.get('utilidad'))} (local, $0). "
        "Sin permiso para cambiar de motor (la tarea no lo declara), la tarea queda esperando tu decisión."))


def _cadena_mover(cual, i, delta):
    if cual == "ejec":
        cad = cadena_ejecutor()
        j = i + delta
        if 0 <= j < len(cad):
            cad[i], cad[j] = cad[j], cad[i]
            fallback_guardar(ejecutor=cad)
    else:
        orden = [(x.get("motor"), x.get("modelo")) for x in (_rev_cfg().get("orden") or []) if isinstance(x, dict)]
        j = i + delta
        if 0 <= j < len(orden):
            orden[i], orden[j] = orden[j], orden[i]
            fallback_guardar(revisor=orden)
    _cadena_render()


def _programar_reintento(cid, task, task_file, processing_path, result, row):
    """Error pasajero: la tarea vuelve a runner-tasks/ y espera su turno
    (30 s, 2 min, 8 min, con jitter). Queda en cola.db, no en memoria."""
    n = (row.get("reintentos") or 0) + 1
    espera = RETRY_BACKOFF_S[n - 1] * random.uniform(0.8, 1.2)
    cuando = time.time() + espera
    err = str(result.get("error") or result.get("status"))[:300]
    hist = _cola_hist(row) + [{"reintento": n, "error": err, "at": _now_iso(),
                               "proximo": _hora(cuando), "cost_usd": result.get("cost_usd")}]
    dest = TASKS / task_file.name
    cola_set(cid, estado="en_cola", archivo=str(dest), intentos=(row.get("intentos") or 0) + 1,
             reintentos=n, proximo_intento=cuando, motivo=err, historial=hist)
    try:
        os.replace(processing_path, dest)
    except OSError as e:
        log(f"runner [{task['id']}]: no se pudo devolver a la cola para reintentar: {e}")
    _family_update(task["raiz"], estado="esperando_reintento", en_curso=None, reintentos=n,
                   proximo_reintento=_hora(cuando), motivo_reintento=err,
                   sumar_costo=result.get("cost_usd"))
    log(f"runner [{task['id']}]: error pasajero ({err[:140]}); reintento {n}/{MAX_RETRIES} "
        f"en {espera:.0f} s (a las {_hora(cuando)[11:19]})")


def _cola_resultado(path):
    try:
        d = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return d if isinstance(d, dict) else None


def cola_recuperar():
    """Al arrancar: lo que un corte dejo a medias vuelve a la cola (o, si ya
    se corto MAX_CORTES veces, queda fallida con el motivo). Nunca en silencio."""
    for d in (TASKS, PROCESSING, DONE, RESULTS, WAITING):
        d.mkdir(parents=True, exist_ok=True)
    cola_init()
    recuperadas, avisos = [], []
    for r in _cola("SELECT * FROM tareas WHERE estado IN ('en_cola', 'en_curso')", fetch=True):
        tid, name = r["id"], Path(r["archivo"] or f"{r['id']}.task.json").name
        if tid in _cola_corriendo:  # runner apagado y encendido con la tarea aun corriendo
            continue
        en_t, en_p, en_d, en_w = TASKS / name, PROCESSING / name, DONE / name, WAITING / name
        if r["estado"] == "en_cola":
            if en_t.exists():
                continue
            if en_p.exists():  # cortada entre apuntar y mover: vuelve a su sitio
                os.replace(en_p, en_t)
                cola_set(tid, archivo=str(en_t))
            elif en_w.exists():
                cola_set(tid, estado="esperando_aprobacion", archivo=str(en_w))
            else:
                motivo = "su archivo .task.json ya no está en runner-tasks/ (¿se movió a mano?)"
                cola_set(tid, estado="fallida", motivo=motivo)
                avisos.append(f"{tid}: {motivo}")
            continue
        # en_curso: se corto (luz, reinicio, cuelgue) mientras corria
        res = _cola_resultado(RESULTS / f"{tid}.result.json")
        if (not en_p.exists() and not en_t.exists() and en_d.exists() and res
                and res.get("estado") in FINAL_STATES + ("en_curso",)):
            # habia terminado; solo faltaba apuntarlo
            est = res.get("estado")
            cola_set(tid, archivo=str(en_d), estado=(
                "necesita_decision" if est == "necesita_decision" else
                "terminada" if res.get("status") == "ok" and est != "fallida" else "fallida"))
            continue
        src = next((p for p in (en_p, en_t, en_d) if p.exists()), None)
        cortes, intentos = r["cortes"] + 1, r["intentos"] + 1
        hist = _cola_hist(r) + [{"corte": _now_iso(), "intento": intentos}]
        raiz = r["raiz"] or tid
        es_modelo = r["motor"] == "modelos"
        if src is None or cortes > MAX_CORTES:
            motivo = (f"{CORTE}, pero su archivo .task.json no está en ninguna carpeta"
                      if src is None else
                      f"se cortó {cortes} veces mientras corría; no la repito sola para no "
                      "entrar en bucle (mándala otra vez si la quieres)")
            if src is not None and src != en_d:
                os.replace(src, en_d)
            cola_set(tid, estado="fallida", intentos=intentos, cortes=cortes, motivo=motivo,
                     historial=hist, proximo_intento=None,
                     archivo=str(en_d) if src is not None else r["archivo"])
            res = _error_result(tid, motivo)
            res.update(raiz=raiz, estado="fallida", recuperada_tras_corte=True, cortes=cortes,
                       intentos=intentos, reintentos=r["reintentos"],
                       reporte=f"{NO_CONFIRMADO} {motivo}.")
            _write_result(res)
            if not es_modelo:
                _family_update(raiz, estado="fallida", reporte=res["reporte"], en_curso=None,
                               recuperada_tras_corte=True)
            avisos.append(f"{tid}: {motivo}")
            continue
        if src != en_t:
            os.replace(src, en_t)
        cola_set(tid, estado="en_cola", archivo=str(en_t), intentos=intentos, cortes=cortes,
                 proximo_intento=None, motivo=f"{CORTE} ({_now_iso()})", historial=hist)
        if not es_modelo:
            _family_update(raiz, estado="pendiente", en_curso=None, recuperada_tras_corte=True,
                           nota_cola=f"{CORTE}: se cortó mientras corría (intento {intentos}); "
                                     "vuelve a la cola")
        recuperadas.append(tid)
    # Huerfanas en processing/ sin registro (de antes de la cola): no se
    # repiten solas (podrian ser instalaciones viejas), pero se ven.
    for p in PROCESSING.glob("*.task.json"):
        try:
            data = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            data = {}
        tid = _cola_id(p, data)
        if cola_get(tid) is not None:
            continue
        cola_registrar(p, data)
        motivo = (f"{CORTE}: quedó a medias en processing/ (archivo del "
                  f"{datetime.fromtimestamp(p.stat().st_mtime):%d/%m %H:%M}) antes de existir la "
                  "cola; no la repito sola. Para repetirla: Tareas → elígela → «Volver a la cola»")
        cola_set(tid, estado="necesita_decision", archivo=str(p), motivo=motivo)
        if isinstance(data, dict) and "ollama_action" not in data:
            _family_update(tid, estado="necesita_decision", reporte=motivo, tarea=tid,
                           motor=data.get("motor") or default_motor(), recuperada_tras_corte=True,
                           solo_si_falta_encargo=str(data.get("prompt") or "")[:2000])
        avisos.append(f"{tid}: huérfana sin registro en processing/, necesita tu decisión")
    if recuperadas:
        log(f"cola: {len(recuperadas)} tarea(s) {CORTE}, vuelven a la cola: {', '.join(recuperadas)}")
    for a in avisos:
        log(f"cola AVISO: {a}")
    return recuperadas, avisos


def cola_reencolar(tid):
    """Devuelve a la cola una tarea fallida, huerfana o que necesita decision."""
    r = cola_get(tid)
    if r is None:
        return False, "esa tarea no está en la cola"
    if r["estado"] in ("en_cola", "en_curso", "esperando_aprobacion"):
        return False, "ya está en la cola"
    name = Path(r["archivo"] or f"{tid}.task.json").name
    src = next((d / name for d in (PROCESSING, DONE, TASKS) if (d / name).exists()), None)
    if src is None:
        return False, "su archivo .task.json ya no está"
    dest = TASKS / name
    t = time.time() - 5
    cola_set(tid, estado="en_cola", archivo=str(dest), proximo_intento=None,
             motivo="la volviste a encolar")
    if src != dest:
        os.replace(src, dest)
    os.utime(dest, (t, t))
    _cola_vistos.add((dest.name, dest.stat().st_mtime_ns))
    log(f"cola: {tid} vuelve a la cola (a mano)")
    return True, "vuelve a la cola"


def cola_archivar(days=ARCHIVE_DAYS):
    """Terminadas/fallidas de hace mas de 30 dias -> archivada. No se borra
    nada: .task.json, .result.json y .revision.json quedan intactos."""
    n = _cola("UPDATE tareas SET estado='archivada', actualizado_en=? WHERE estado IN "
              "('terminada', 'fallida') AND actualizado_ts < ?",
              (_now_iso(), time.time() - days * 86400))
    if n:
        log(f"cola: {n} tarea(s) de hace más de {days} días pasan a archivada (no se borra nada)")
    return n


def cola_archivadas():
    return {r["id"] for r in _cola("SELECT id FROM tareas WHERE estado='archivada'", fetch=True)}


# ---------------------------------------------------------------- checkpoint por ronda
# t-checkpoint-ronda-030. La cola sabe QUE tarea estaba corriendo; el
# checkpoint sabe EN QUE PASO iba: una fila por ronda/intento en la misma
# cola.db (WAL + FULL), escrita ANTES de lanzar cada paso y DESPUES de cada
# resultado. Al arrancar, el supervisor recompone lo que quedo a medias y el
# runner reanuda desde siguiente_paso: si murio revisando, solo se repite la
# revision; si murio con el motor corriendo, la misma ronda con la misma
# sesion y la misma carpeta. Si la sesion ya no sirve (compactada, perdida,
# otro motor), nueva sesion con el resumen del checkpoint, sin fallar.
# No es un DAG ni un motor de flujos: solo el registro minimo para reanudar.
CK_FINALES = ("terminada", "fallida", "necesita_decision", "sin_revision")
CK_TRAS_MOTOR = ("resultado_guardado", "revisando")  # el motor ya termino: falta (o faltaba) revisar
CK_PASO_TXT = {"lanzando": "lanzando el motor", "corriendo": "con el motor corriendo",
               "resultado_guardado": "con el motor ya terminado, antes de revisar",
               "revisando": "revisando", "esperando_aprobacion": "esperando tu aprobación",
               "reintento": "esperando un reintento", "revisada": "entre rondas (revisión hecha)"}
CK_SUPERVISOR_FILE = OUTBOX / "supervisor-arranque.json"
CK_AVISO_MISMA_SESION = ("(Aviso del runner: se cortó mientras trabajabas en esto. Sigues en la misma sesión: "
                         "continúa desde donde quedaste y no repitas lo ya hecho.)\n\n")
# --resume que ya no encuentra la sesion (Claude: «No conversation found with
# session ID: ...», comprobado el 26/10 con un id inexistente; sale con codigo 1).
_SESION_PERDIDA_RE = re.compile(
    r"no conversation found|session(?:\s+id)?\s*(?:\S+\s+)?(?:not found|no encontrad|expired|expirad|invalid)|"
    r"no such session|could not (?:resume|find session)|unable to resume|sesi[oó]n (?:no existe|perdida|expirada)",
    re.I)


def checkpoint_init():
    _cola("""CREATE TABLE IF NOT EXISTS checkpoints (
        ck_id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT NOT NULL, run_id TEXT NOT NULL,
        ronda INTEGER NOT NULL, intento INTEGER NOT NULL, motor_usado TEXT, modelo TEXT,
        session_id TEXT, session_id_entrada TEXT, cwd TEXT, criterios_pendientes TEXT,
        costo_paso REAL, costo_revision REAL, costo_acumulado REAL, costo_corte_estimado REAL,
        estado TEXT NOT NULL, paso TEXT, siguiente_paso TEXT, plan_id TEXT, fase TEXT,
        approval_id TEXT, degradado INTEGER NOT NULL DEFAULT 0, degradacion TEXT, resumen TEXT,
        archivos_tocados TEXT, transcript TEXT, reanudado_desde TEXT, creado_en TEXT NOT NULL,
        actualizado_en TEXT NOT NULL, actualizado_ts REAL NOT NULL, historial TEXT,
        UNIQUE(task_id, ronda, intento))""")
    _cola("CREATE INDEX IF NOT EXISTS checkpoints_run ON checkpoints(run_id)")
    _cola("CREATE INDEX IF NOT EXISTS checkpoints_task ON checkpoints(task_id)")
    _cola("""CREATE TABLE IF NOT EXISTS planes (
        plan_id TEXT PRIMARY KEY, origen TEXT, estado TEXT NOT NULL, n_fases INTEGER,
        creado_en TEXT NOT NULL, actualizado_en TEXT NOT NULL)""")
    _cola("""CREATE TABLE IF NOT EXISTS plan_fases (
        plan_id TEXT NOT NULL, n INTEGER NOT NULL, etiqueta TEXT, task_id TEXT, depende_de INTEGER,
        estado TEXT NOT NULL, siguiente_paso TEXT, actualizado_en TEXT NOT NULL,
        PRIMARY KEY (plan_id, n))""")


def _jl(v, default=None):
    try:
        x = json.loads(v) if isinstance(v, str) else v
    except ValueError:
        return default
    return default if x is None else x


def ck_get(ck_id):
    r = _cola("SELECT * FROM checkpoints WHERE ck_id=?", (ck_id,), fetch=True) if ck_id else []
    return r[0] if r else None


def ck_ultimo(task_id):
    r = _cola("SELECT * FROM checkpoints WHERE task_id=? ORDER BY ck_id DESC LIMIT 1", (task_id,), fetch=True)
    return r[0] if r else None


def ck_de_run(run_id):
    return _cola("SELECT * FROM checkpoints WHERE run_id=? ORDER BY ck_id", (run_id,), fetch=True)


def _ck_costo_run(run_id, sin=None):
    """Lo gastado por toda la familia: cada intento (reintentos incluidos) + cada revision."""
    r = _cola("SELECT COALESCE(SUM(COALESCE(costo_paso, 0) + COALESCE(costo_revision, 0)), 0) AS c "
              "FROM checkpoints WHERE run_id=?" + (" AND ck_id<>?" if sin else ""),
              (run_id, sin) if sin else (run_id,), fetch=True)
    return round(float((r[0] if r else {}).get("c") or 0), 6)


def ck_set(ck_id, paso_log=None, **kw):
    """Actualiza la fila (cada sentencia se confirma sola: WAL + FULL) y
    apunta el paso en su historial. Recalcula el costo acumulado."""
    row = ck_get(ck_id)
    if row is None:
        return None
    for k in ("criterios_pendientes", "archivos_tocados", "resumen", "degradacion"):
        if isinstance(kw.get(k), (list, dict)):
            kw[k] = json.dumps(kw[k], ensure_ascii=False)
    hist = _jl(row.get("historial"), [])
    if paso_log:
        hist.append({"at": _now_iso(), "estado": kw.get("estado") or row["estado"], "nota": paso_log})
    kw.update(historial=json.dumps(hist[-40:], ensure_ascii=False), actualizado_en=_now_iso(),
              actualizado_ts=time.time())
    cols = ", ".join(f"{k}=?" for k in kw)
    _cola(f"UPDATE checkpoints SET {cols} WHERE ck_id=?", (*kw.values(), ck_id))
    acum = round(_ck_costo_run(row["run_id"]), 6)
    _cola("UPDATE checkpoints SET costo_acumulado=? WHERE ck_id=?", (acum, ck_id))
    row = ck_get(ck_id)
    _ck_a_familia(row)
    return row


def _ck_a_familia(row):
    """La ventana lee la familia (.orquestacion.json): ahi va un resumen del checkpoint."""
    if not row:
        return
    try:
        _family_update(row["run_id"], checkpoint={
            "task_id": row["task_id"], "ronda": row["ronda"], "intento": row["intento"],
            "estado": row["estado"], "paso": row["paso"], "siguiente_paso": row["siguiente_paso"],
            "motor": row["motor_usado"], "costo_acumulado": row["costo_acumulado"],
            "degradado": bool(row["degradado"]), "reanudado_desde": row["reanudado_desde"],
            "actualizado": row["actualizado_en"]})
    except Exception as e:
        log(f"checkpoint: no se pudo copiar a la familia de {row.get('run_id')}: {type(e).__name__}: {e}")


def _ck_siguiente_tras_motor(task):
    return "revisar" if task.get("revisar", True) else "terminada"


def _ck_pendientes_previos(task):
    """Criterios pendientes al empezar: los que dejo la revision anterior (o todos)."""
    for r in reversed(ck_de_run(task["raiz"])):
        if r["ronda"] < task.get("ronda", 0) and r["criterios_pendientes"] is not None:
            return _jl(r["criterios_pendientes"], [])
    return criterios_txt(task)


def _ck_fila(task, intento, estado, paso, siguiente, **extra):
    """Crea (o reutiliza) la fila de esta ronda/intento. Devuelve ck_id."""
    key = (task["id"], int(task.get("ronda", 0)), int(intento))
    r = _cola("SELECT ck_id FROM checkpoints WHERE task_id=? AND ronda=? AND intento=?", key, fetch=True)
    pid = _plan_id(task)
    base = dict(motor_usado=task.get("motor"), modelo=task.get("modelo") or task.get("model"),
                session_id_entrada=task.get("session_id"), cwd=task.get("cwd"),
                criterios_pendientes=_ck_pendientes_previos(task), estado=estado, paso=paso,
                siguiente_paso=siguiente, plan_id=pid, fase=task.get("fase"),
                transcript=f"{task['raiz']}.ronda-{task.get('ronda', 0)}.json", **extra)
    if r:
        return ck_set(r[0]["ck_id"], paso_log=f"{estado}: {siguiente}", **base)["ck_id"]
    now = _now_iso()
    base["criterios_pendientes"] = json.dumps(base["criterios_pendientes"], ensure_ascii=False)
    row = dict(task_id=key[0], run_id=task["raiz"], ronda=key[1], intento=key[2], costo_paso=None,
               costo_revision=None, costo_acumulado=_ck_costo_run(task["raiz"]), creado_en=now,
               actualizado_en=now, actualizado_ts=time.time(),
               historial=json.dumps([{"at": now, "estado": estado, "nota": siguiente}], ensure_ascii=False),
               **base)
    _cola(f"INSERT INTO checkpoints ({', '.join(row)}) VALUES ({', '.join('?' * len(row))})", tuple(row.values()))
    got = _cola("SELECT * FROM checkpoints WHERE task_id=? AND ronda=? AND intento=?", key, fetch=True)
    if not got:
        return None
    _ck_a_familia(got[0])
    return got[0]["ck_id"]


def _ck_transcript(task, intento, **campos):
    """runner-results/<run_id>.ronda-N.json: lo enviado y lo recibido en cada
    intento de esa ronda (prompt, resultado, revision). Se reescribe entero
    (tmp + replace) antes de lanzar y despues de cada resultado."""
    p = RESULTS / f"{task['raiz']}.ronda-{task.get('ronda', 0)}.json"
    try:
        d = json.loads(p.read_text(encoding="utf-8")) if p.is_file() else {}
    except (OSError, ValueError):
        d = {}
    d.setdefault("run_id", task["raiz"])
    d.setdefault("ronda", task.get("ronda", 0))
    ints = d.setdefault("intentos", [])
    ent = next((x for x in ints if x.get("intento") == intento and x.get("task_id") == task["id"]), None)
    if ent is None:
        ent = {"intento": intento, "task_id": task["id"]}
        ints.append(ent)
    ent.update(campos)
    d["actualizado"] = _now_iso()
    try:
        RESULTS.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(".tmp")
        tmp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmp, p)
    except OSError as e:
        log(f"checkpoint: no se pudo guardar el transcript {p.name} ({e})")


def ck_resumen_txt(task, motivo):
    """Resumen corto del checkpoint para una sesion nueva: lo hecho, los
    criterios pendientes y los archivos tocados. Sale de la base (y del
    transcript), no de la memoria del motor."""
    filas = [r for r in ck_de_run(task["raiz"]) if r["ck_id"] != _RUN.get("ck")]
    fam = load_family(task["raiz"]) or {}
    hecho, archivos, pend = [], [], None
    for r in filas:
        res = _jl(r["resumen"], {}) or {}
        if res.get("hecho"):
            hecho.append(f"ronda {r['ronda']} ({r['motor_usado']}): {res['hecho']}")
        for a in _jl(r["archivos_tocados"], []) or []:
            if a not in archivos:
                archivos.append(a)
        if r["criterios_pendientes"] is not None and r["estado"] in ("revisada",) + CK_FINALES:
            pend = _jl(r["criterios_pendientes"], [])
    if pend is None:
        pend = _ck_pendientes_previos(task)
    out = [f"(Aviso del runner: se reanuda SIN la sesión original ({motivo}). Es una sesión nueva; "
           "esto es el resumen del checkpoint de lo ya hecho. No repitas lo que ya esté hecho.)",
           "Encargo original: " + re.sub(r"\s+", " ", str(fam.get("encargo") or task["prompt"]))[:1500]]
    out.append("Lo hecho hasta ahora: " + (" | ".join(hecho[-3:]) if hecho else "nada registrado todavía"))
    out.append("Criterios pendientes:" + ("".join(f"\n- {c}" for c in pend) if pend else " ninguno registrado"))
    out.append("Archivos tocados:" + ("".join(f"\n- {a}" for a in archivos[:20]) if archivos else " ninguno registrado"))
    return "\n".join(out)


def _sesion_perdida(result):
    if result.get("status") == "ok" or _RUN.get("stop"):
        return False
    txt = " ".join(str(result.get(k) or "") for k in ("error", "stderr", "result"))
    return bool(_SESION_PERDIDA_RE.search(txt))


def _ck_degradar(task, plan, motivo):
    """Nueva sesion con el resumen del checkpoint (en vez de fallar la tarea)."""
    plan["degradar"] = motivo
    plan["session_id_original"] = task.get("session_id") or plan.get("session_id_original")
    task["session_id"] = None
    task["prompt"] = task["prompt"].replace(CK_AVISO_MISMA_SESION, "") + "\n\n" + ck_resumen_txt(task, motivo)
    log(f"runner [{task['id']}]: se reanuda sin la sesión original ({motivo}): nueva sesión con el "
        "resumen del checkpoint")


def _ck_siguiente_existe(task, ck):
    """True si el siguiente paso apuntado ya esta hecho o encolado."""
    sig = str(ck.get("siguiente_paso") or "")
    if sig.startswith("ronda "):
        name = f"{task['raiz'][:70]}-r{_fase_n(sig)}.task.json"
        return any((d / name).exists() for d in (TASKS, PROCESSING, DONE, WAITING))
    if sig == "fase siguiente":
        return bool((load_family(task["raiz"]) or {}).get("siguiente"))
    return True


def ck_preparar(task, row_cola):
    """Lee el checkpoint ANTES de lanzar y decide desde donde se sigue:
    {"modo": "motor" | "revisar", ...}. Puede cambiar en task la carpeta, la
    sesion y el prompt (reanudacion o degradacion). Nunca inventa un paso:
    sin checkpoint previo se corre como siempre."""
    plan = {"modo": "motor", "resultado": None, "degradar": None, "reanuda": None,
            "costo_ya_sumado": False, "session_id_original": None}
    prev = ck_ultimo(task["id"])
    eng = get_engine(task.get("motor") or "") or {}
    puede = soporta_reanudar(eng)
    if prev:
        tras_motor = prev["estado"] in CK_TRAS_MOTOR or (prev["estado"] == "cortada" and prev["paso"] == "revision")
        if tras_motor:
            res = _cola_resultado(RESULTS / f"{task['id']}.result.json")
            if res and res.get("status") == "ok" and res.get("id") == task["id"]:
                # El motor ya habia terminado: solo se repite la revision (barata).
                plan.update(modo="revisar", resultado=res, reanuda="revisar",
                            costo_ya_sumado=prev["estado"] == "revisando" or prev["paso"] == "revision")
                log(f"runner [{task['id']}]: checkpoint: el motor ya había terminado la ronda "
                    f"{task.get('ronda', 0)}; solo se repite la revisión")
                return plan
        tras_corte = str((row_cola or {}).get("motivo") or "").startswith(CORTE)
        if tras_corte and prev["estado"] in ("revisada",) + CK_FINALES:
            # Se corto DESPUES de revisar y decidir: si el siguiente paso ya
            # existe (ronda o fase encolada), no hay nada que repetir; si no
            # llego a encolarse, se repite solo la revision (que lo encola).
            res = _cola_resultado(RESULTS / f"{task['id']}.result.json")
            if res and res.get("id") == task["id"]:
                if res.get("estado") and _ck_siguiente_existe(task, prev):
                    plan.update(modo="hecho", resultado=res, reanuda="nada: el paso ya estaba hecho")
                    log(f"runner [{task['id']}]: checkpoint: el corte llegó con este paso ya revisado "
                        f"({prev['siguiente_paso']}); no se repite nada")
                    return plan
                if res.get("status") == "ok":
                    plan.update(modo="revisar", resultado=res, reanuda="revisar", costo_ya_sumado=True)
                    log(f"runner [{task['id']}]: checkpoint: revisado pero sin «{prev['siguiente_paso']}» "
                        "encolado; se repite solo la revisión")
                    return plan
        if prev["estado"] in ("lanzando", "corriendo", "cortada"):
            # Murio con el motor corriendo: la MISMA ronda, en la misma carpeta y con la misma sesion.
            if prev["cwd"] and Path(prev["cwd"]).is_dir():
                task["cwd"] = prev["cwd"]
            sid = prev["session_id"] or prev["session_id_entrada"]
            plan["reanuda"] = f"ronda {task.get('ronda', 0)}"
            if sid and puede:
                task["session_id"] = sid
                task["prompt"] = CK_AVISO_MISMA_SESION + task["prompt"]
                log(f"runner [{task['id']}]: checkpoint: reanudo la ronda {task.get('ronda', 0)} con la "
                    f"sesión {sid} en {task['cwd']}")
            elif sid and not puede:
                _ck_degradar(task, plan, f"el motor {task.get('motor')} no puede continuar una sesión")
            elif task.get("session_id") or task.get("ronda", 0) > 0:
                # La ronda necesitaba continuar una sesion y el checkpoint ya no la tiene.
                plan["session_id_original"] = task.get("session_id")
                _ck_degradar(task, plan, "session_id perdido: el checkpoint ya no lo tiene")
            else:
                log(f"runner [{task['id']}]: checkpoint: la ronda 0 se cortó antes de tener sesión; "
                    "se repite desde el principio de esa ronda")
            return plan
    # Frontera entre rondas: si cambio el motor (o no reanuda), no se le pasa
    # la sesion del otro: recibe el resumen del checkpoint.
    if task.get("session_id"):
        antes = [r for r in ck_de_run(task["raiz"]) if r["ronda"] < task.get("ronda", 0)]
        m_antes = antes[-1]["motor_usado"] if antes else None
        if not puede:
            _ck_degradar(task, plan, f"el motor {task.get('motor')} no puede continuar una sesión")
        elif m_antes and m_antes != task.get("motor"):
            motor_cambio(m_antes, task.get("motor"), f"la tarea {task.get('id')} cambió de motor entre rondas")
            _ck_degradar(task, plan, f"cambio de motor entre rondas ({m_antes} → {task.get('motor')}): "
                                     "el motor nuevo no puede continuar la sesión del anterior")
        elif antes and antes[-1]["cwd"] and Path(antes[-1]["cwd"]).is_dir():
            task["cwd"] = antes[-1]["cwd"]  # la sesion esta ligada a la carpeta en que nacio
    return plan


def ck_inicio(task, row_cola, plan):
    """Fila ANTES de lanzar el paso (motor o, si se reanuda, solo revision)."""
    intento = int((row_cola or {}).get("intentos") or 0) + 1
    if plan["modo"] == "revisar":
        ck = _ck_fila(task, intento, "revisando", "revision", "revisar", reanudado_desde="revisar")
    else:
        ck = _ck_fila(task, intento, "lanzando", "motor", _ck_siguiente_tras_motor(task),
                      reanudado_desde=plan.get("reanuda"),
                      degradado=1 if plan.get("degradar") else 0,
                      degradacion=json.dumps({"motivo": plan["degradar"],
                                              "session_id_original": plan.get("session_id_original")},
                                             ensure_ascii=False) if plan.get("degradar") else None)
    _RUN["ck"] = ck
    task["_ck"], task["_intento"] = ck, intento
    _ck_transcript(task, intento, ck_id=ck, motor=task.get("motor"), modelo=task.get("modelo"),
                   cwd=task["cwd"], session_id_entrada=task.get("session_id"),
                   lanzado_en=_now_iso(), modo=plan["modo"], reanudado_desde=plan.get("reanuda"),
                   degradacion=plan.get("degradar"),
                   prompt_enviado=None if plan["modo"] == "revisar" else prompt_de_tarea(task))
    plan_tocar(task, "en_curso", "revisar" if plan["modo"] == "revisar" else "motor")
    return ck


def ck_en_vuelo(session_id):
    """La sesion que el motor anuncia al arrancar (stream-json, evento init):
    se guarda ya, para poder continuarla si se corta a mitad."""
    ck = _RUN.get("ck")
    row = ck_get(ck) if ck else None
    if row and row["estado"] in ("lanzando", "corriendo") and row["session_id"] != session_id:
        ck_set(ck, paso_log=f"sesión en vuelo {session_id}", estado="corriendo", session_id=session_id)


def ck_resultado(task, result, plan):
    """Fila DESPUES del resultado del motor (antes de revisar)."""
    ck = task.get("_ck")
    if not ck:
        return
    ok = result.get("status") == "ok"
    texto = re.sub(r"\s+", " ", str(result.get("result") or "")).strip()
    deg = None
    if plan.get("degradar"):
        deg = {"motivo": plan["degradar"], "session_id_original": plan.get("session_id_original"),
               "modo": "nueva sesión con resumen del checkpoint"}
    est = "resultado_guardado" if ok else "reintento" if result.get("_reintento") else "fallida"
    sig = (_ck_siguiente_tras_motor(task) if ok else
           f"ronda {task.get('ronda', 0)} (reintento)" if est == "reintento" else "terminada")
    kw = dict(estado=est, siguiente_paso=sig, session_id=result.get("session_id") or (ck_get(ck) or {}).get("session_id"),
              resumen={"hecho": texto[:600], "status": result.get("status"), "error": result.get("error")})
    if plan["modo"] != "revisar":
        kw["costo_paso"] = result.get("cost_usd") if isinstance(result.get("cost_usd"), (int, float)) else 0.0
    if deg:
        kw.update(degradado=1, degradacion=deg)
    row = ck_set(ck, paso_log=f"resultado del motor: {result.get('status')}", **kw)
    if plan["modo"] != "revisar":
        _ck_transcript(task, task.get("_intento"), terminado_en=_now_iso(), resultado={
            k: result.get(k) for k in ("status", "error", "result", "cost_usd", "num_turns", "session_id",
                                       "exit_code", "duration_s", "lanzamiento")}
            | {"stderr_final": str(result.get("stderr") or "")[-1500:]}, reanudacion=deg)
    return row


def ck_revision_inicio(task):
    ck = task.get("_ck")
    if ck:
        ck_set(ck, paso_log="empieza la revisión", estado="revisando", paso="revision", siguiente_paso="revisar")


def ck_revision_fin(task, rev, estado, siguiente):
    ck = task.get("_ck")
    if not ck:
        return
    kw = dict(estado=estado, siguiente_paso=siguiente)
    if rev is not None:
        kw.update(criterios_pendientes=list(rev.get("que_falta") or []) if rev.get("aprobado") is False else [],
                  archivos_tocados=list(rev.get("archivos_tocados") or [])[:40],
                  costo_revision=rev.get("cost_usd") if isinstance(rev.get("cost_usd"), (int, float)) else 0.0)
        _ck_transcript(task, task.get("_intento"), revision={
            "motor": rev.get("motor_revision"), "aprobado": rev.get("aprobado"), "que_falta": rev.get("que_falta"),
            "evidencia": (rev.get("evidencia") or [])[:8], "cost_usd": rev.get("cost_usd"),
            "prompt_enviado": _RUN.get("rev_prompt"), "respuesta_cruda": _RUN.get("rev_raw"),
            "revisado_at": rev.get("revisado_at"), "decision": rev.get("decision"),
            "checks_deterministas": rev.get("checks_deterministas"), "veredictos": rev.get("veredictos"),
            "segundo_juez": rev.get("segundo_juez")})
    ck_set(ck, paso_log=f"{estado}: {siguiente}", **kw)


def ck_aprobacion(task, approval_id):
    """La tarea queda aparcada: su siguiente paso es esperar tu aprobacion."""
    try:
        row = cola_get(task["id"]) or {}
        _ck_fila(task, int(row.get("intentos") or 0) + 1, "esperando_aprobacion", "aprobacion",
                 f"esperar_aprobacion:{approval_id}", approval_id=approval_id)
    except Exception as e:
        log(f"checkpoint: no se pudo apuntar la espera de {task.get('id')}: {type(e).__name__}: {e}")


def ck_cerrar_espera(task_id, estado, nota):
    """La espera de aprobacion termino sin ejecutar (vencida, denegada o rechazada)."""
    try:
        ck = ck_ultimo(task_id)
        if ck and ck["estado"] == "esperando_aprobacion":
            ck_set(ck["ck_id"], paso_log=nota, estado=estado, siguiente_paso="terminada")
    except Exception as e:
        log(f"checkpoint: no se pudo cerrar la espera de {task_id}: {type(e).__name__}: {e}")


# ---- registro minimo del plan (fases encadenadas). El DAG completo es t-dag-fases-030.
def _plan_id(task):
    if not (task.get("fase") or task.get("siguiente_fase") or task.get("fase_base")):
        return None
    return str(task.get("fase_base") or task["raiz"])[:68]


def _fase_n(label, default=1):
    m = re.search(r"(\d+)", str(label or ""))
    return int(m.group(1)) if m else default


def _plan_cadena(task):
    """[(n, etiqueta)] de las fases que vienen detras (siguiente_fase anidado)."""
    out, k, nxt, label = [], _fase_n(task.get("fase")), task.get("siguiente_fase"), task.get("fase")
    while nxt and len(out) < 20:
        k += 1
        if isinstance(nxt, dict):
            label = nxt.get("fase") or _next_fase_label(label) or f"fase {k}"
            nxt = nxt.get("siguiente_fase")
        else:
            label, nxt = _next_fase_label(label) or f"fase {k}", None
        out.append((k, label))
    m = re.search(r"(?:de|/)\s*(\d+)", str(task.get("fase") or ""))
    total = int(m.group(1)) if m else 0
    while k < total:
        k += 1
        out.append((k, f"fase {k} de {total}"))
    return out


def plan_fases(plan_id):
    return _cola("SELECT * FROM plan_fases WHERE plan_id=? ORDER BY n", (plan_id,), fetch=True)


def _plan_recalcular(plan_id):
    est = [f["estado"] for f in plan_fases(plan_id)]
    e = ("terminado" if est and all(x == "terminada" for x in est) else
         "detenido" if any(x in ("fallida", "necesita_decision") for x in est) else
         "a_medias" if "a_medias" in est else
         "en_curso" if "en_curso" in est or "terminada" in est else "pendiente")
    _cola("UPDATE planes SET estado=?, n_fases=?, actualizado_en=? WHERE plan_id=?",
          (e, len(est), _now_iso(), plan_id))
    return e


def plan_txt(plan_id):
    fs = plan_fases(plan_id)
    if not fs:
        return ""
    nom = {"a_medias": "a medias", "en_curso": "en curso", "necesita_decision": "necesita decisión"}
    return f"Plan {plan_id}: " + ", ".join(
        f"fase {f['n']} {nom.get(f['estado'], f['estado'])}"
        + (f" (siguiente: {f['siguiente_paso']})" if f["estado"] in ("a_medias", "en_curso") and f["siguiente_paso"]
           else "") for f in fs)


def plan_tocar(task, estado, siguiente=None, sig_task=None):
    """Registra la fase de esta tarea y su estado; las de detras quedan pendientes."""
    pid = _plan_id(task)
    if not pid:
        return
    try:
        now, k = _now_iso(), _fase_n(task.get("fase"))
        _cola("INSERT OR IGNORE INTO planes (plan_id, origen, estado, n_fases, creado_en, actualizado_en) "
              "VALUES (?,?,?,?,?,?)", (pid, task["raiz"], "en_curso", 0, now, now))
        _cola("INSERT OR IGNORE INTO plan_fases (plan_id, n, etiqueta, task_id, depende_de, estado, "
              "siguiente_paso, actualizado_en) VALUES (?,?,?,?,?,?,?,?)",
              (pid, k, task.get("fase") or f"fase {k}", task["raiz"], k - 1 if k > 1 else None,
               "pendiente", None, now))
        for n, label in _plan_cadena(task):
            _cola("INSERT OR IGNORE INTO plan_fases (plan_id, n, etiqueta, task_id, depende_de, estado, "
                  "siguiente_paso, actualizado_en) VALUES (?,?,?,?,?,?,?,?)",
                  (pid, n, label, None, n - 1, "pendiente", None, now))
        _cola("UPDATE plan_fases SET task_id=?, estado=?, siguiente_paso=?, actualizado_en=? "
              "WHERE plan_id=? AND n=?", (task["raiz"], estado, siguiente, now, pid, k))
        if sig_task:
            _cola("UPDATE plan_fases SET task_id=?, siguiente_paso=?, actualizado_en=? WHERE plan_id=? AND n=?",
                  (sig_task, "en cola", now, pid, k + 1))
        _plan_recalcular(pid)
        _family_update(task["raiz"], plan_id=pid, plan_fases=[
            {"n": f["n"], "etiqueta": f["etiqueta"], "estado": f["estado"], "task_id": f["task_id"]}
            for f in plan_fases(pid)])
    except Exception as e:
        log(f"plan: no se pudo registrar {pid}: {type(e).__name__}: {e}")


# ---- supervisor al arrancar
CK_A_MEDIAS = ("lanzando", "corriendo", "resultado_guardado", "revisando", "cortada")


def _ck_paso_efectivo(ck):
    """'motor' si murio con el motor corriendo; 'revision' si ya habia resultado."""
    if ck["estado"] == "cortada":
        return ck["paso"] or "motor"
    return "revision" if ck["estado"] in CK_TRAS_MOTOR else "motor"


def _ultimo_estado_txt(ck):
    motor = MOTOR_CORTO.get(ck["motor_usado"], ck["motor_usado"])
    if ck["estado"] in CK_A_MEDIAS and _ck_paso_efectivo(ck) == "motor":
        como = (f"murió con {motor} corriendo; se reanuda la ronda {ck['ronda']} con la "
                "misma sesión y la misma carpeta")
    elif ck["estado"] in CK_A_MEDIAS:
        como = "murió revisando; el motor ya había terminado: se repite solo la revisión"
    else:
        como = "se quedó " + CK_PASO_TXT.get(ck["estado"], ck["estado"])
    return f"ronda {ck['ronda']}, siguiente_paso {ck['siguiente_paso']} ({como})"


def supervisor_arranque():
    """Al arrancar, ANTES de reponer la cola: recompone desde cola.db lo que
    quedo a medias (que fase, que ronda, que paso y cual es el siguiente) y
    deja el «ultimo estado conocido» en cada tarea para verlo en Tareas. Una
    tarea sin checkpoint (de antes de esto) queda «sin estado previo» y se
    repone como antes, sin inventarle un siguiente paso."""
    checkpoint_init()
    lv = {}
    try:
        lv = json.loads(LIVE_FILE.read_text(encoding="utf-8")) if LIVE_FILE.is_file() else {}
    except (OSError, ValueError):
        lv = {}
    informe = {"at": _now_iso(), "tareas": [], "planes": []}
    vivas = _cola("SELECT * FROM tareas WHERE estado IN ('en_curso', 'en_cola')", fetch=True)
    for r in vivas:
        if r["id"] in _cola_corriendo or r["motor"] == "modelos":
            continue
        run_id = r["raiz"] or r["id"]
        ck = ck_ultimo(r["id"])
        if r["estado"] == "en_cola" and (ck is None or ck["estado"] not in CK_A_MEDIAS):
            continue  # esperando su turno (o su reintento): nada se corto a mitad
        if ck is None:
            ue = {"task_id": r["id"], "sin_estado_previo": True, "at": _now_iso(),
                  "texto": "sin estado previo (tarea de antes del checkpoint): se repone como antes, "
                           "desde el principio; no hay siguiente_paso guardado"}
        else:
            if ck["estado"] in CK_FINALES:
                continue
            ue = {"task_id": r["id"], "run_id": run_id, "ronda": ck["ronda"], "intento": ck["intento"],
                  "estado": ck["estado"], "paso": ck["paso"], "siguiente_paso": ck["siguiente_paso"],
                  "motor": ck["motor_usado"], "session_id": ck["session_id"] or ck["session_id_entrada"],
                  "cwd": ck["cwd"], "costo_acumulado": ck["costo_acumulado"],
                  "criterios_pendientes": _jl(ck["criterios_pendientes"], []), "at": _now_iso(),
                  "texto": _ultimo_estado_txt(ck), "cortada_a_mitad": ck["estado"] in CK_A_MEDIAS}
            if ue["cortada_a_mitad"]:
                est_lv = None
                if lv.get("task_id") == r["id"] and lv.get("estado") != "terminado" and \
                        isinstance(lv.get("cost_usd_estimado"), (int, float)):
                    est_lv = lv["cost_usd_estimado"]
                    ue["costo_corte_estimado"] = est_lv
                ck_set(ck["ck_id"], paso_log="cortada: el runner arrancó y esta fila seguía a medias",
                       estado="cortada", paso=_ck_paso_efectivo(ck),
                       costo_corte_estimado=est_lv if est_lv is not None else ck["costo_corte_estimado"])
        try:
            _family_update(run_id, ultimo_estado=ue)
        except Exception as e:
            log(f"supervisor: no se pudo anotar {run_id}: {type(e).__name__}: {e}")
        informe["tareas"].append(ue)
        log(f"supervisor: {r['id']}: último estado conocido: {ue['texto']}")
    for p in _cola("SELECT * FROM planes WHERE estado IN ('en_curso', 'a_medias')", fetch=True):
        for f in plan_fases(p["plan_id"]):
            if f["estado"] != "en_curso":
                continue
            ult = ck_de_run(f["task_id"]) if f["task_id"] else []
            sig = None
            if ult:
                c = ult[-1]
                sig = (f"ronda {c['ronda']}: {c['siguiente_paso']}" if c["estado"] not in CK_FINALES
                       else c["siguiente_paso"])
            _cola("UPDATE plan_fases SET estado='a_medias', siguiente_paso=?, actualizado_en=? "
                  "WHERE plan_id=? AND n=?", (sig, _now_iso(), p["plan_id"], f["n"]))
        _plan_recalcular(p["plan_id"])
        fs = plan_fases(p["plan_id"])
        txt = plan_txt(p["plan_id"])
        informe["planes"].append({"plan_id": p["plan_id"], "texto": txt, "fases": fs})
        for f in fs:
            if f["task_id"] and f["estado"] == "a_medias":
                fam = load_family(f["task_id"]) or {}
                ue = dict(fam.get("ultimo_estado") or {"at": _now_iso(), "texto": "fase a medias"}, plan=txt)
                _family_update(f["task_id"], ultimo_estado=ue, plan_id=p["plan_id"], plan_fases=[
                    {"n": x["n"], "etiqueta": x["etiqueta"], "estado": x["estado"], "task_id": x["task_id"]}
                    for x in fs])
        log(f"supervisor: {txt}")
    try:
        OUTBOX.mkdir(parents=True, exist_ok=True)
        tmp = CK_SUPERVISOR_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(informe, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(tmp, CK_SUPERVISOR_FILE)
    except OSError as e:
        log(f"supervisor: no se pudo escribir {CK_SUPERVISOR_FILE.name} ({e})")
    log(f"supervisor: al arrancar {len(informe['tareas'])} tarea(s) a medias, "
        f"{len(informe['planes'])} plan(es) a medias")
    return informe


def process_one(task_file):
    """Una tarea, de principio a fin, con la configuracion con la que empezo
    (recarga en caliente: settings.json y engines.json pueden cambiar
    mientras corre; esta tarea no se entera, la siguiente si)."""
    if _cfg_snap() is not None:
        return _process_one_impl(task_file)
    _CFG_LOCAL.snap = _cfg_tomar()
    try:
        return _process_one_impl(task_file)
    finally:
        _CFG_LOCAL.snap = None


# ---- planes con grafo de fases (t-dag-fases-030): DAG MINIMO, sin motor de
# grafos. El grafo es un campo del plan y la verdad es una tabla (cola.db):
# dag_planes + dag_fases. Las fases corren de una en una por la cola de
# siempre (sin paralelo: eso es t-paralelo-seguro-030). La cadena lineal de
# antes (siguiente_fase) sigue igual.
DAG_AL_FALLAR = ("reintentar_una_vez", "saltar_con_aviso", "abortar_plan", "pedir_decision")
DAG_OK = ("terminada", "saltada")
DAG_MAL = ("fallida", "necesita_decision", "cancelada", "bloqueada")
_DAG_NOM = {"pendiente": "sin arrancar", "en_cola": "en cola", "terminada": "terminada", "saltada": "saltada",
            "fallida": "fallida", "necesita_decision": "necesita decisión", "cancelada": "cancelada",
            "bloqueada": "bloqueada"}


def dag_init():
    _cola("""CREATE TABLE IF NOT EXISTS dag_planes (
        plan_id TEXT PRIMARY KEY, estado TEXT NOT NULL, orden TEXT, cwd TEXT, motor TEXT,
        creado_en TEXT NOT NULL, actualizado_en TEXT NOT NULL, motivo TEXT, revisar TEXT)""")
    _cola("""CREATE TABLE IF NOT EXISTS dag_fases (
        plan_id TEXT NOT NULL, fase_id TEXT NOT NULL, n INTEGER NOT NULL, prompt TEXT, depende_de TEXT,
        al_fallar TEXT NOT NULL, criterios TEXT, estado TEXT NOT NULL, task_id TEXT, reintentos INTEGER DEFAULT 0,
        motivo TEXT, actualizado_en TEXT NOT NULL, PRIMARY KEY (plan_id, fase_id))""")


def dag_validar(data):
    """(orden, None) u (None, motivo en palabras normales). Antes de ejecutar:
    ids, dependencias que existen, al_fallar valido y SIN ciclos."""
    fases = data.get("fases")
    if not isinstance(fases, list) or not fases:
        return None, "el plan no trae fases"
    ids = [str((f or {}).get("id") or "") for f in fases]
    for f, fid in zip(fases, ids):
        if not isinstance(f, dict) or not _safe_id(fid):
            return None, f"cada fase necesita un id corto sin espacios raros (tengo «{fid}»)"
        if not str(f.get("prompt") or "").strip():
            return None, f"la fase «{fid}» no dice qué hacer (falta prompt)"
        if (f.get("al_fallar") or "pedir_decision") not in DAG_AL_FALLAR:
            return None, f"la fase «{fid}»: al_fallar debe ser {', '.join(DAG_AL_FALLAR)}"
    if len(set(ids)) != len(ids):
        return None, "hay dos fases con el mismo id"
    deps = {fid: [str(d) for d in (f.get("depende_de") or [])] for f, fid in zip(fases, ids)}
    for fid, ds in deps.items():
        for d in ds:
            if d not in deps:
                return None, f"la fase «{fid}» depende de «{d}», que no existe en el plan"
            if d == fid:
                return None, f"la fase «{fid}» depende de sí misma"
    orden, grado = [], {fid: len(ds) for fid, ds in deps.items()}
    listas = [fid for fid in ids if grado[fid] == 0]
    while listas:
        x = listas.pop(0)
        orden.append(x)
        for fid in ids:
            if x in deps[fid]:
                grado[fid] -= 1
                if grado[fid] == 0:
                    listas.append(fid)
    if len(orden) != len(ids):
        ciclo = [fid for fid in ids if grado[fid] > 0]
        return None, ("el plan tiene un ciclo: " + " ↔ ".join(ciclo) + " dependen unas de otras y ninguna "
                      "podría empezar nunca. Rompe el ciclo y vuelve a mandarlo.")
    return orden, None


def _dag_fases(pid):
    return [dict(r) for r in _cola("SELECT * FROM dag_fases WHERE plan_id=? ORDER BY n", (pid,), fetch=True) or []]


def _dag_plan(pid):
    r = _cola("SELECT * FROM dag_planes WHERE plan_id=?", (pid,), fetch=True)
    return dict(r[0]) if r else None


def _dag_set(pid, fid, **kw):
    kw["actualizado_en"] = _now_iso()
    _cola(f"UPDATE dag_fases SET {', '.join(k + '=?' for k in kw)} WHERE plan_id=? AND fase_id=?",
          tuple(kw.values()) + (pid, fid))


def _dag_plan_set(pid, **kw):
    kw["actualizado_en"] = _now_iso()
    _cola(f"UPDATE dag_planes SET {', '.join(k + '=?' for k in kw)} WHERE plan_id=?", tuple(kw.values()) + (pid,))


def dag_ingestar(task_file, data):
    """Un .task.json con «fases»: se valida el grafo, se registra en SQLite
    (antes de ejecutar nada) y se encolan las fases que ya pueden empezar."""
    pid = str(data.get("id") or task_file.stem)
    DONE.mkdir(parents=True, exist_ok=True)
    orden, motivo = (None, f"id de plan inválido: {pid}") if not _safe_id(pid) else dag_validar(data)
    if motivo:
        log(f"plan [{pid}]: rechazado antes de ejecutar: {motivo}")
        shutil.move(str(task_file), str(DONE / task_file.name))
        res = _error_result(pid, f"plan rechazado: {motivo}")
        res.update(raiz=pid, estado="fallida", reporte=f"El plan no se ejecutó: {motivo}")
        _write_result(res)
        _family_update(pid, estado="fallida", reporte=res["reporte"], error=motivo)
        return True
    now = _now_iso()
    _cola("INSERT OR REPLACE INTO dag_planes (plan_id, estado, orden, cwd, motor, creado_en, actualizado_en, revisar) "
          "VALUES (?,?,?,?,?,?,?,?)", (pid, "en_curso", json.dumps(orden), data.get("cwd"), data.get("motor"), now,
                                       now, json.dumps(data["revisar"]) if "revisar" in data else None))
    por_id = {str(f["id"]): f for f in data["fases"]}
    for n, fid in enumerate(orden, 1):
        f = por_id[fid]
        _cola("INSERT OR REPLACE INTO dag_fases (plan_id, fase_id, n, prompt, depende_de, al_fallar, criterios, estado, "
              "task_id, reintentos, actualizado_en) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
              (pid, fid, n, f["prompt"], json.dumps([str(d) for d in f.get("depende_de") or []]),
               f.get("al_fallar") or "pedir_decision", json.dumps(f.get("criterios") or []), "pendiente",
               f"{pid}-{fid}"[:80], 0, now))
    shutil.move(str(task_file), str(DONE / task_file.name))
    log(f"plan [{pid}]: registrado con {len(orden)} fase(s) en orden {' → '.join(orden)}")
    dag_avanzar(pid)
    return True


def _dag_validacion_deps(pid, fase, por_id):
    """Fan-in: las dependencias en ok Y sus criterios tipados en verde ($0)."""
    plan = _dag_plan(pid) or {}
    fallos = []
    for d in json.loads(fase["depende_de"] or "[]"):
        dep = por_id[d]
        if dep["estado"] == "saltada":
            continue
        _f, tip, _err = separar_criterios(json.loads(dep["criterios"] or "[]"), plan.get("cwd") or str(INBOX))
        for c in tip or []:
            ch = _check_tipado(c, plan.get("cwd") or str(INBOX))
            if ch.get("falla"):
                fallos.append(f"«{d}»: {'; '.join(ch['falla'])[:200]}")
    return fallos


def _dag_encolar(pid, fase):
    plan = _dag_plan(pid) or {}
    t = {"id": fase["task_id"], "prompt": fase["prompt"], "fase": f"fase {fase['n']} ({fase['fase_id']})",
         "dag": {"plan": pid, "fase": fase["fase_id"]}, "criterios": json.loads(fase["criterios"] or "[]")}
    for k in ("cwd", "motor"):
        if plan.get(k):
            t[k] = plan[k]
    if plan.get("revisar") is not None:
        t["revisar"] = json.loads(plan["revisar"])  # el plan dice como se revisan sus fases
    TASKS.mkdir(parents=True, exist_ok=True)
    (TASKS / f"{fase['task_id']}.task.json").write_text(json.dumps(t, ensure_ascii=False), encoding="utf-8")
    _dag_set(pid, fase["fase_id"], estado="en_cola")
    log(f"plan [{pid}]: fase {fase['fase_id']} en cola")


def dag_avanzar(pid):
    """Encola lo que ya puede empezar; bloquea lo que depende de algo roto; cierra el plan."""
    plan = _dag_plan(pid)
    if not plan or plan["estado"] != "en_curso":
        dag_reflejar(pid)
        return
    fases = _dag_fases(pid)
    por_id = {f["fase_id"]: f for f in fases}
    for f in fases:
        if f["estado"] != "pendiente":
            continue
        deps = json.loads(f["depende_de"] or "[]")
        est = [por_id[d]["estado"] for d in deps]
        if any(e in DAG_MAL for e in est):
            rotas = [d for d in deps if por_id[d]["estado"] in DAG_MAL]
            _dag_set(pid, f["fase_id"], estado="bloqueada", motivo=f"depende de {', '.join(rotas)}, que no terminó bien")
            f["estado"] = "bloqueada"
            continue
        if not all(e in DAG_OK for e in est):
            continue  # espera a sus dependencias
        fallos = _dag_validacion_deps(pid, f, por_id) if deps else []
        if fallos:
            _dag_set(pid, f["fase_id"], motivo="validación de sus dependencias: " + " | ".join(fallos))
            log(f"plan [{pid}]: fase {f['fase_id']} no arranca: la validación de sus dependencias falla: {fallos[0]}")
            dag_fallo(pid, f["fase_id"], "sus dependencias no pasan la validación: " + " | ".join(fallos), encolar=False)
            return
        _dag_encolar(pid, f)
        f["estado"] = "en_cola"
    fases = _dag_fases(pid)
    if all(f["estado"] in DAG_OK for f in fases):
        _dag_plan_set(pid, estado="terminado")
        log(f"plan [{pid}]: terminado")
    elif not any(f["estado"] in ("pendiente", "en_cola") for f in fases):
        _dag_plan_set(pid, estado="detenido", motivo="ninguna fase puede seguir")
    dag_reflejar(pid)


def dag_fallo(pid, fid, motivo, encolar=True):
    """Lo que dice al_fallar de la fase."""
    f = next(x for x in _dag_fases(pid) if x["fase_id"] == fid)
    accion = f["al_fallar"]
    if accion == "reintentar_una_vez" and not f["reintentos"] and encolar:
        _dag_set(pid, fid, reintentos=1, motivo=f"reintento: {motivo}"[:300])
        _dag_encolar(pid, dict(f, reintentos=1))
        log(f"plan [{pid}]: fase {fid} falló ({motivo[:120]}); se reintenta una vez")
        return
    if accion == "reintentar_una_vez":
        accion = "pedir_decision"  # el reintento ya se gasto: decide Leandro
    if accion == "saltar_con_aviso":
        _dag_set(pid, fid, estado="saltada", motivo=motivo[:300])
        toast(f"Plan {pid}: se saltó la fase {fid}")
        log(f"plan [{pid}]: fase {fid} falló y se salta con aviso ({motivo[:120]})")
    elif accion == "abortar_plan":
        _dag_set(pid, fid, estado="fallida", motivo=motivo[:300])
        for x in _dag_fases(pid):
            if x["estado"] in ("pendiente", "en_cola"):
                _dag_set(pid, x["fase_id"], estado="cancelada", motivo=f"plan abortado por la fase {fid}")
                tf = TASKS / f"{x['task_id']}.task.json"
                if tf.exists():
                    shutil.move(str(tf), str(DONE / tf.name))
        _dag_plan_set(pid, estado="abortado", motivo=f"fase {fid}: {motivo}"[:300])
        log(f"plan [{pid}]: abortado por la fase {fid} ({motivo[:120]})")
    else:
        _dag_set(pid, fid, estado="necesita_decision", motivo=motivo[:300])
        _dag_plan_set(pid, estado="necesita_decision", motivo=f"fase {fid}: {motivo}"[:300])
        log(f"plan [{pid}]: fase {fid} falló: necesita tu decisión; el resto del plan queda como estaba")
    dag_avanzar(pid)


def dag_fase_terminada(task, estado):
    """Lo llama _after_run cuando una fase de un plan termina (estado final)."""
    d = task.get("dag") if isinstance(task.get("dag"), dict) else None
    if not d or estado not in ("aprobada", "sin_revision", "fallida", "rechazada", "necesita_decision"):
        return
    pid, fid = d.get("plan"), d.get("fase")
    try:
        if estado in ("aprobada", "sin_revision"):
            _dag_set(pid, fid, estado="terminada", motivo=None)
            log(f"plan [{pid}]: fase {fid} terminada")
            dag_avanzar(pid)
        else:
            dag_fallo(pid, fid, f"la tarea terminó {ESTADOS.get(estado, estado)}")
    except Exception as e:
        log(f"plan [{pid}]: no se pudo apuntar la fase {fid} ({type(e).__name__}: {e})")


def dag_supervisor():
    """Al arrancar: recompone los planes a medias desde cola.db. Las fases
    hechas no se repiten; las que estaban en cola o a medias siguen con su
    checkpoint (la cola las repone); las que nunca arrancaron se encolan
    cuando les toca. Si una fase ya tenia resultado final pero el plan no lo
    apunto (corte justo despues), se apunta ahora."""
    out = []
    for p in _cola("SELECT plan_id FROM dag_planes WHERE estado='en_curso'", fetch=True) or []:
        pid = p["plan_id"]
        hechas, a_medias, sin = [], [], []
        for f in _dag_fases(pid):
            if f["estado"] in DAG_OK:
                hechas.append(f["fase_id"])
            elif f["estado"] == "en_cola":
                rf = RESULTS / f"{f['task_id']}.result.json"
                fam = load_family(f["task_id"]) or {}
                if rf.exists() and fam.get("estado") in ("aprobada", "sin_revision", "fallida", "rechazada",
                                                         "necesita_decision"):
                    dag_fase_terminada({"dag": {"plan": pid, "fase": f["fase_id"]}}, fam["estado"])
                    hechas.append(f["fase_id"] + " (apuntada ahora)")
                elif not (TASKS / f"{f['task_id']}.task.json").exists() and not any(
                        r["estado"] in ("en_cola", "en_curso") for r in _cola(
                            "SELECT estado FROM tareas WHERE id=?", (f["task_id"],), fetch=True) or []):
                    _dag_encolar(pid, f)
                    a_medias.append(f["fase_id"] + " (vuelta a la cola)")
                else:
                    a_medias.append(f["fase_id"] + " (sigue con su checkpoint)")
            elif f["estado"] == "pendiente":
                sin.append(f["fase_id"])
        dag_avanzar(pid)
        txt = (f"plan {pid}: hechas {', '.join(hechas) or '—'}; a medias {', '.join(a_medias) or '—'}; "
               f"sin arrancar {', '.join(sin) or '—'}")
        log(f"supervisor: {txt}")
        out.append(txt)
    return out


def dag_txt(pid):
    """El plan en palabras: cada fase con su estado y de quién depende, y qué lo bloquea."""
    plan = _dag_plan(pid)
    if not plan:
        return ""
    fases = _dag_fases(pid)
    por_id = {f["fase_id"]: f for f in fases}
    partes = []
    for f in fases:
        deps = json.loads(f["depende_de"] or "[]")
        s = f"Fase {f['n']} ({f['fase_id']}): {_DAG_NOM.get(f['estado'], f['estado'])}"
        esperando = [d for d in deps if por_id[d]["estado"] not in DAG_OK]
        if f["estado"] == "pendiente" and esperando:
            s += " — espera a " + " y ".join(f"Fase {por_id[d]['n']}" for d in esperando)
        if f.get("motivo") and f["estado"] not in ("terminada",):
            s += f" ({f['motivo'][:120]})"
        partes.append(s)
    bloquea = [f for f in fases if f["estado"] in ("fallida", "necesita_decision")]
    cab = {"en_curso": "en curso", "terminado": "terminado", "necesita_decision": "necesita tu decisión",
           "abortado": "abortado", "detenido": "detenido"}.get(plan["estado"], plan["estado"])
    return (f"Plan {pid} ({cab})" + (f". Lo bloquea la Fase {bloquea[0]['n']} ({bloquea[0]['fase_id']})" if bloquea
                                     else "") + ". " + "; ".join(partes) + ".")


def dag_reflejar(pid):
    """La fila del plan en Tareas: estado y reporte con las fases."""
    plan = _dag_plan(pid)
    if not plan:
        return
    est = {"en_curso": "en_curso", "terminado": "aprobada", "necesita_decision": "necesita_decision",
           "abortado": "fallida", "detenido": "fallida"}.get(plan["estado"], "en_curso")
    txt = dag_txt(pid)
    res = {"runner": f"growi-bridge/{VERSION}", "id": pid, "raiz": pid, "status": "ok", "estado": est,
           "reporte": txt, "result": txt, "motor": "plan (fases)", "cost_usd": None,
           "started_at": plan["creado_en"], "finished_at": _now_iso() if est != "en_curso" else None}
    _write_result(res)
    _family_update(pid, estado=est, reporte=txt, solo_si_falta_encargo=f"Plan con {len(_dag_fases(pid))} fases")


def _process_one_impl(task_file):
    try:
        data = json.loads(task_file.read_text(encoding="utf-8"))
    except Exception as e:
        log(f"runner [{task_file.name}]: JSON invalido ({e}); se archiva sin correr")
        DONE.mkdir(parents=True, exist_ok=True)
        cid = cola_registrar(task_file, {})
        shutil.move(str(task_file), str(DONE / task_file.name))
        cola_set(cid, estado="fallida", archivo=str(DONE / task_file.name), motivo=f"JSON invalido: {e}")
        _write_result(_error_result(task_file.stem, f"JSON invalido: {e}"))
        return True
    if isinstance(data, dict) and isinstance(data.get("fases"), list):
        return dag_ingestar(task_file, data)  # un plan con grafo de fases (t-dag-fases-030)
    cid = cola_registrar(task_file, data)
    task, error = validate_task(data)
    task_id = data.get("id") if isinstance(data.get("id"), str) else task_file.stem
    if not error:
        error = _lane_b_espera_a(task)
    if error:
        log(f"runner [{task_id}]: rechazado: {error}")
        DONE.mkdir(parents=True, exist_ok=True)
        shutil.move(str(task_file), str(DONE / task_file.name))
        res = _error_result(task_id, error)
        res["reintentos"] = 0
        if _safe_id(task_id) and isinstance(data, dict) and "ollama_action" not in data:
            rep = f"{NO_CONFIRMADO} La tarea se rechazó antes de empezar: {error}."
            res.update(raiz=task_id, estado="fallida", reporte=rep, motor=data.get("motor"),
                       **_auto_fields(data.get("_enrutado")))
            _family_update(task_id, estado="fallida", reporte=rep, error=error,
                           **_auto_fields(data.get("_enrutado")),
                           motor=data.get("motor") or default_motor(), tarea=task_id,
                           solo_si_falta_encargo=str(data.get("prompt") or "")[:2000])
        cola_set(cid, estado="fallida", archivo=str(DONE / task_file.name),
                 motivo=f"definitivo, sin reintentos: {error}"[:300])
        _write_result(res)
        return True
    is_model = bool(task.get("ollama_action"))
    if not is_model and isinstance(data, dict) and not data.get("run_id") and task.get("run_id"):
        # el run_id queda también en el encargo original (t-idempotencia-cuarentena-030)
        try:
            data["run_id"] = task["run_id"]
            task_file.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        except OSError as e:
            log(f"runner [{task['id']}]: no pude apuntar el run_id en el encargo ({e})")
    if not is_model:
        need = _approval_needed(task)
        if task.get("_estimado"):  # el estimado queda a la vista ANTES de ejecutar
            _family_update(task["raiz"], estimado=task["_estimado"]["texto"])
            log(f"runner [{task['id']}]: {task['_estimado']['texto'][:300]}")
        if need and need.get("denegada"):
            _pol_denegar(task_file, task, cid, need)
            return True
        if need:
            est, dest = _park_for_approval(task_file, task, need)
            cola_set(cid, estado=est, archivo=str(dest))
            return True
        try:
            task, _ruta = router_antes(task, task_file, cid)  # t-router-fallbacks
        except Exception as e:
            log(f"runner [{task['id']}]: respaldo: {type(e).__name__}: {e}; sigue con su motor")
            _ruta = "seguir"
        if _ruta == "pospuesta":
            return True
    PROCESSING.mkdir(parents=True, exist_ok=True)
    DONE.mkdir(parents=True, exist_ok=True)
    processing_path = PROCESSING / task_file.name
    row = cola_get(cid) or {}
    # Primero se apunta en_curso y despues se mueve: si se va la luz entre
    # medias, al volver cola_recuperar() la encuentra igual.
    cola_set(cid, estado="en_curso", archivo=str(processing_path), proximo_intento=None)
    try:
        shutil.move(str(task_file), str(processing_path))
    except OSError as e:
        log(f"runner [{task['id']}]: no se pudo mover a processing: {e}")
        cola_set(cid, estado="en_cola", archivo=str(task_file))
        return False
    _cola_corriendo.add(cid)
    if is_model:
        # Acciones de modelos: carril propio, no cuentan como "Claude
        # trabajando" (ni la mascota teclea ni el PC se queda despierto).
        result = run_task(task)
    else:
        _RUN.update(stop=False, id=task["id"], proc=None, conn=None)
        _ACT["started_at"] = _now_iso()
        _act_touch()
        state["current"] = task["id"]
        n = task.get("ronda", 0)
        eng = get_engine(task["motor"]) or {}
        _mod = (task.get("model") if task["motor"] == "api" else task.get("modelo")) or \
            (eng.get("modelo") or {}).get("por_defecto")
        if isinstance(_mod, str) and _mod.startswith("@"):
            _mod = _local_model(eng, task) or None
        state["current_motor"], state["current_modelo"] = task["motor"], _mod
        live_start(task, task["motor"], _mod)
        runner_heartbeat()  # 'current' ya trae la tarea desde el primer segundo
        # Checkpoint: desde donde se sigue (no desde cero) y la fila ANTES de lanzar.
        try:
            ckp = ck_preparar(task, row)
        except Exception as e:
            log(f"runner [{task['id']}]: checkpoint: no se pudo leer ({type(e).__name__}: {e}); "
                "se corre como siempre")
            ckp = {"modo": "motor", "resultado": None, "degradar": None, "reanuda": None,
                   "costo_ya_sumado": False, "session_id_original": None}
        if ckp["modo"] == "hecho":
            result = ckp["resultado"]
            _cola_corriendo.discard(cid)
            live_finish("el paso ya estaba hecho antes del corte")
            state["current"] = state["paso"] = None
            state["current_motor"] = state["current_modelo"] = None
            _RUN.update(proc=None, conn=None, id=None, ck=None)
            try:
                shutil.move(str(processing_path), str(DONE / task_file.name))
            except OSError as e:
                log(f"runner [{task['id']}]: no se pudo archivar el task: {e}")
            est = result.get("estado")
            cola_set(cid, archivo=str(DONE / task_file.name), estado=(
                "necesita_decision" if est == "necesita_decision" else
                "terminada" if result.get("status") == "ok" and est not in ("fallida",) else "fallida"))
            return True
        try:
            ck_inicio(task, row, ckp)
        except Exception as e:
            log(f"runner [{task['id']}]: checkpoint: no se pudo apuntar el inicio ({type(e).__name__}: {e})")
        state["paso"] = (f"{eng.get('nombre') or task['motor']} trabaja en {task['raiz']}"
                         + (f" (ronda {n}/{MAX_ROUNDS})" if n else "")
                         + (f" (reintento {row['reintentos']}/{MAX_RETRIES})" if row.get("reintentos") else "")
                         + (" (reanuda tras corte)" if ckp.get("reanuda") else ""))
        _family_update(task["raiz"], estado="en_curso", motor=task["motor"],
                       modelo=task.get("modelo"), ronda=n, tarea=task["id"], en_curso=task["id"],
                       proximo_reintento=None,
                       solo_si_falta_encargo=task["prompt"][:2000],
                       solo_si_falta_criterios=criterios_txt(task),
                       fase=task.get("fase"), siguiente_fase=bool(task.get("siguiente_fase")),
                       **_auto_fields(task.get("enrutado")))
        snap = _lane_snapshot() if LANE == "b" else None
        if ckp["modo"] == "revisar":
            # El motor ya habia terminado antes del corte: su resultado esta
            # guardado; solo se repite la revision (barata), no la ronda.
            result = dict(ckp["resultado"], reanudado_desde="revisar")
            state["paso"] = f"Revisando {task['raiz']} (reanuda tras corte: solo la revisión)"
            live_set("tarea", nota="tras el corte se repite solo la revisión: el motor ya había terminado")
        else:
            result = run_task(task)
            if task.get("session_id") and _sesion_perdida(result):
                # --resume fallo (sesion compactada, perdida o expirada): nueva
                # sesion con el resumen del checkpoint, en vez de fallar la tarea.
                lineas = [x.strip() for k in ("stderr", "error", "result")
                          for x in str(result.get(k) or "").splitlines() if x.strip()]
                motivo = "--resume falló: " + next((x for x in lineas if _SESION_PERDIDA_RE.search(x)),
                                                   str(result.get("error") or "?"))[:200]
                c0 = result.get("cost_usd") if isinstance(result.get("cost_usd"), (int, float)) else 0.0
                _ck_transcript(task, task.get("_intento"), intento_con_sesion={
                    "session_id": task["session_id"], "error": result.get("error"),
                    "stderr_final": str(result.get("stderr") or "")[-800:], "cost_usd": c0})
                _ck_degradar(task, ckp, motivo)
                if task.get("_ck"):
                    ck_set(task["_ck"], paso_log=motivo, degradado=1, session_id_entrada=None,
                           degradacion={"motivo": motivo, "session_id_original": ckp.get("session_id_original"),
                                        "modo": "nueva sesión con resumen del checkpoint"})
                    _ck_transcript(task, task["_intento"], prompt_enviado=prompt_de_tarea(task),
                                   degradacion=motivo)
                live_set("tarea", nota="la sesión anterior no se pudo continuar; sigue en una sesión nueva "
                                       "con el resumen del checkpoint")
                result = run_task(task)
                if isinstance(result.get("cost_usd"), (int, float)) and c0:
                    result["cost_usd"] = round(result["cost_usd"] + c0, 6)
            if ckp.get("degradar"):
                result["reanudacion"] = {"modo": "nueva sesión con resumen del checkpoint",
                                         "motivo": ckp["degradar"],
                                         "session_id_original": ckp.get("session_id_original"),
                                         "sin_sesion_original": True}
                result.setdefault("avisos", []).append(
                    f"Se reanudó SIN la sesión original ({ckp['degradar']}): nueva sesión con el resumen del "
                    "checkpoint (lo hecho, los criterios pendientes y los archivos tocados).")
                _family_update(task["raiz"], reanudacion=dict(result["reanudacion"], at=_now_iso(),
                                                              ronda=n, task_id=task["id"]))
            if ckp.get("reanuda"):
                result["reanudado_desde"] = ckp["reanuda"]
        result["checkpoint"] = {"ck_id": task.get("_ck"), "intento": task.get("_intento"),
                                "transcript": f"{task['raiz']}.ronda-{n}.json"}
        if snap is not None:
            result["carril"] = "b"
            cambios = [f for f, v in _lane_snapshot().items() if snap.get(f) != v]
            if cambios:
                result["carril_b_alerta"] = cambios
                result.setdefault("avisos", []).append(
                    "carril B: durante esta tarea cambiaron archivos prohibidos (puede haber "
                    "sido el carril A, revísalo): " + ", ".join(cambios[:8]))
                log(f"runner [{task['id']}]: AVISO carril B: cambiaron {cambios[:8]}")
        try:
            # El costo final es el que reporto el motor al terminar (el
            # mismo que va al .result.json); el estimado se queda al lado.
            live_final("tarea", result.get("cost_usd"), result.get("uso"))
            if result.get("status") != "ok" and not (_LIVE["d"] or {}).get("tokens_in"):
                live_set("tarea", nota=f"terminó con error: {str(result.get('error') or '')[:160]}")
        except Exception as e:
            log(f"runner [{task['id']}]: vivo: {type(e).__name__}: {e}")
        state["tasks_done"] += 1
        state["last_result"] = f"{task['id']}: {result['status']} ({result['duration_s']}s)"
        reintentos = row.get("reintentos") or 0
        breaker_apuntar(result, result.get("status") != "ok" and _es_transitorio(result))
        motor_fallo_apuntar(task.get("motor"), result, result.get("status") != "ok" and _es_transitorio(result))
        if (result.get("status") != "ok" and not _RUN.get("stop") and reintentos < MAX_RETRIES
                and _es_transitorio(result)):
            try:
                try:
                    ck_resultado(task, dict(result, _reintento=True), ckp)
                except Exception as e:
                    log(f"runner [{task['id']}]: checkpoint: {type(e).__name__}: {e}")
                _programar_reintento(cid, task, task_file, processing_path, result, row)
            finally:
                live_finish("reintento programado")
                state["current"] = None
                state["paso"] = None
                state["current_motor"] = state["current_modelo"] = None
                _RUN.update(proc=None, conn=None, id=None, ck=None)
                _cola_corriendo.discard(cid)
            return True
        if result.get("status") != "ok" and not _RUN.get("stop") and _es_transitorio(result):
            try:
                hecho = fallback_tras_fallo(cid, task, task_file, processing_path, result, row)
            except Exception as e:
                log(f"runner [{task['id']}]: respaldo: {type(e).__name__}: {e}")
                hecho = False
            if hecho:
                live_finish("sigue con el siguiente motor de la cadena")
                state["current"] = state["paso"] = None
                state["current_motor"] = state["current_modelo"] = None
                _RUN.update(proc=None, conn=None, id=None, ck=None)
                _cola_corriendo.discard(cid)
                return True
        if task.get("ruta_motor"):  # motor por intento: motor_elegido, motivo_eleccion, escalon_previo...
            result.setdefault("ruta_motor", task["ruta_motor"])
            for _k in ("motor_elegido", "motivo_eleccion", "escalon_previo", "motivo_escalado"):
                result.setdefault(_k, task["ruta_motor"].get(_k))
    hist = _cola_hist(row)
    result["intentos"] = (row.get("intentos") or 0) + 1
    result["reintentos"] = row.get("reintentos") or 0
    if [h for h in hist if "reintento" in h]:
        result["historial_reintentos"] = [h for h in hist if "reintento" in h]
    if row.get("cortes"):
        result.update(recuperada_tras_corte=True, cortes=row["cortes"])
        result.setdefault("avisos", []).append(
            f"{CORTE}: se cortó {_veces(row['cortes'])} mientras corría; "
            + (f"se reanudó desde el checkpoint ({result['reanudado_desde']})" if result.get("reanudado_desde")
               else "se repitió entera"))
    try:
        _write_result(result)
        log(f"runner [{task['id']}]: terminado: {result['status']} duracion={result['duration_s']}s costo={result['cost_usd']}"
            + (f" reintentos={result['reintentos']}" if result["reintentos"] else "")
            + (f" ({CORTE})" if row.get("cortes") else ""))
    except OSError as e:
        log(f"runner [{task['id']}]: no se pudo escribir el resultado: {e}")
    if not is_model:
        export_recordatorio_proyecto(task, result)  # tope 1 por semana; nunca un pop-up
        try:
            # DESPUES del resultado (ya en disco): si se corta revisando, al
            # volver solo se repite la revision.
            ck_resultado(task, result, ckp)
        except Exception as e:
            log(f"runner [{task['id']}]: checkpoint: no se pudo apuntar el resultado ({type(e).__name__}: {e})")
        if ckp.get("costo_ya_sumado"):
            result["_costo_ya_sumado"] = True
        # Memoria: flush ANTES de la ronda / fase siguiente (las encola
        # _after_run) y la entrada de la sesion actual (lo que resume /nuevo).
        try:
            mf = mem_flush_tal_vez(task, result)
            if mf is not None:
                result["memoria_flush"] = mf
                with open(RESULTS / f"{result['id']}.result.json", "w", encoding="utf-8") as f:
                    json.dump({k: v for k, v in result.items() if not k.startswith("_")}, f,
                              ensure_ascii=False, indent=2)
        except Exception as e:
            log(f"runner [{task['id']}]: memoria: flush: {type(e).__name__}: {e}")
        try:
            mem_sesion_anotar(task, result)
        except Exception as e:
            log(f"runner [{task['id']}]: memoria: sesión: {type(e).__name__}: {e}")
        try:
            if result.get("status") == "ok" and task.get("revisar", True):
                live_set("tarea", estado="revisando")
            _after_run(task, result)
        except Exception as e:
            log(f"runner [{task['id']}]: ERROR en la revisión/orquestación: {type(e).__name__}: {e}")
            _family_update(task["raiz"], estado="sin_revision",
                           reporte=_honest_report("sin_revision", task, None, None, f"{type(e).__name__}: {e}"))
        finally:
            live_finish()
            state["current"] = None
            state["paso"] = None
            state["current_motor"] = state["current_modelo"] = None
            _RUN.update(proc=None, conn=None, id=None, ck=None)
    # Se archiva el task DESPUES de revisar: si se corta durante la revision,
    # sigue en processing/ y al volver solo se repite la revision (checkpoint).
    try:
        shutil.move(str(processing_path), str(DONE / task_file.name))
    except OSError as e:
        log(f"runner [{task['id']}]: no se pudo archivar el task: {e}")
    est = result.get("estado")
    cola_set(cid, archivo=str(DONE / task_file.name), intentos=result["intentos"],
             estado=("necesita_decision" if est == "necesita_decision" else
                     "en_cuarentena" if est == "en_cuarentena" else
                     "terminada" if result.get("status") == "ok" and est != "fallida" else "fallida"),
             motivo=(str(result.get("error") or "")[:300] or None))
    _cola_corriendo.discard(cid)
    return True


# ---- banner de la nube fiel al runner (t-estado-banner-nube-045). El banner
# «Sin conexión con la nube» lo decidía conn_state(), que solo mira el sondeo
# del mapa (fila «claude»: estado + ruta directa o por proxy). Un sondeo lento
# o una ruta por proxy sin «proxy_on» bastaban para alarmar aunque el runner
# siguiera en Opus. Ahora el banner lee runner-status.json (la tarea en curso o
# la última ejecución: motor y modelo reales) y solo alarma si el runner NO
# alcanza la nube de verdad: su última ejecución en la nube falló por red, o el
# sondeo falló dos veces seguidas (la segunda es una comprobación a los 20 s).
_ULTIMA: dict = {"d": None, "leida": False}
NUBE_ERROR_RED = re.compile(r"(?i)connect|conexi[oó]n|timed? ?out|tiempo de espera|getaddrinfo|network|"
                            r"unreachable|ECONN|proxy|SSL|\b50[234]\b|overloaded|no se pudo alcanzar")
PROBE_VIEJO_S = 180  # runner-status.json sin latido en 3 min: no se puede leer el estado


def _motor_es_local(motor, modelo=""):
    return str(motor or "") in ("llama", "ollama") or str(modelo or "").startswith("ollama:")


def _ultima_ejecucion_set(result):
    if not isinstance(result, dict) or not result.get("motor") or "(herramienta)" in str(result.get("motor")):
        return
    uso = result.get("uso") if isinstance(result.get("uso"), dict) else {}
    _ULTIMA["d"] = {"tarea": result.get("id"), "motor": result.get("motor"),
                    "modelo": uso.get("modelo_real") or result.get("modelo_real") or result.get("modelo"),
                    "status": result.get("status"), "error": str(result.get("error") or "")[:200],
                    "at": result.get("finished_at") or _now_iso()}


def _ultima_ejecucion():
    """La última ejecución del runner (al arrancar, la del result.json más reciente: una sola vez)."""
    if _ULTIMA["d"] is None and not _ULTIMA["leida"]:
        _ULTIMA["leida"] = True
        try:
            fs = sorted(RESULTS.glob("*.result.json"), key=lambda f: f.stat().st_mtime)
            for f in reversed(fs[-20:]):
                d = json.loads(f.read_text(encoding="utf-8"))
                if isinstance(d, dict) and d.get("motor") and "(herramienta)" not in str(d.get("motor")):
                    _ultima_ejecucion_set(d)
                    break
        except (OSError, ValueError):
            pass
    return _ULTIMA["d"]


def runner_modelo_probe():
    """Qué modelo usa el runner AHORA, leído de runner-status.json (la misma fuente que el panel):
    {estado: nube | local | sin_ejecuciones | ilegible, motor, modelo, fuente, fallo_red, motivo}."""
    path = OUTBOX / _STATUS_NOMBRE["principal"]
    try:
        st = json.loads(path.read_text(encoding="utf-8"))
        lp = datetime.fromisoformat(str(st.get("last_poll")))
    except (OSError, ValueError, TypeError) as e:
        return {"estado": "ilegible", "motivo": f"{path.name}: {type(e).__name__}"}
    edad = time.time() - lp.timestamp()
    if edad > PROBE_VIEJO_S:
        return {"estado": "ilegible", "motivo": f"el runner no da señales desde hace {int(edad // 60)} min"}
    cur = st.get("current") if isinstance(st.get("current"), dict) else {}
    ult = st.get("ultima_ejecucion") if isinstance(st.get("ultima_ejecucion"), dict) else {}
    if cur.get("motor"):
        motor, modelo, fuente = cur["motor"], cur.get("modelo_real") or cur.get("modelo"), f"tarea en curso {cur.get('id')}"
    elif ult.get("motor"):
        motor, modelo, fuente = ult["motor"], ult.get("modelo"), f"última ejecución {ult.get('tarea')}"
    else:
        return {"estado": "sin_ejecuciones", "motivo": "el runner aún no ha ejecutado nada"}
    d = {"estado": "local" if _motor_es_local(motor, modelo) else "nube", "motor": motor,
         "modelo": modelo or motor, "fuente": fuente, "fallo_red": False}
    if d["estado"] == "nube" and ult.get("motor") == motor and ult.get("status") not in ("ok", None):
        d["fallo_red"] = bool(NUBE_ERROR_RED.search(str(ult.get("error") or "")))
    return d


def cloud_banner_decidir(probe, fallos_confirmados):
    """(mostrar, texto, tipo) con tipo alarma | info | neutro."""
    e = probe.get("estado")
    if e == "ilegible":
        return True, f"No se pudo leer el estado del runner ({probe.get('motivo')}).", "neutro"
    if e == "local":
        return True, f"Trabajando con el modelo local {probe.get('modelo')} ({probe.get('fuente')}).", "info"
    if probe.get("fallo_red") or fallos_confirmados >= 2:
        que = f" {probe.get('modelo')}" if e == "nube" else ""
        porque = ("su última ejecución falló por red" if probe.get("fallo_red")
                  else "el sondeo de la nube falló dos veces seguidas")
        return True, f"Sin conexión con la nube: el runner no alcanza{que} ({porque}).", "alarma"
    return False, "", ""


def runner_heartbeat():
    """runner-status.json. Lo escribe el bucle cuando esta libre y el hilo de
    pulso cada 60 s mientras una tarea corre: un last_poll viejo ya no
    significa 'Claude trabajando', significa problema."""
    with _STATUS_LOCK:
        _HB["t"] = time.time()
        try:
            RESULTS.mkdir(parents=True, exist_ok=True)
            cola = cola_resumen()
            cur = None
            if state.get("current"):
                lv = _LIVE["d"] or {}
                cur = {"id": state["current"], "motor": state.get("current_motor"),
                       "modelo": state.get("current_modelo"),
                       "modelo_real": lv.get("modelo_real") if lv.get("task_id") == state["current"] else None,
                       "estado": lv.get("estado") if lv.get("task_id") == state["current"] else None}
                act = _ACT["t"] or time.time()
                cur.update(started_at=_ACT["started_at"], last_activity=_ts_iso(act),
                           idle_s=round(time.time() - act))
            status = {
                "runner": f"growi-bridge/{VERSION}", "alive": True, "last_poll": _now_iso(),
                "tasks_done": state["tasks_done"], "current": cur,
                "paso": state.get("paso"), "claude": shutil.which("claude"), "pid": os.getpid(),
                "motores": engines_summary(), "guardrail": guardrail_level(),
                "esperando_aprobacion": sorted(p.name for p in WAITING.glob("*.task.json")),
                "aprobaciones_pendientes": [
                    {"approval_id": r["approval_id"], "tarea": r["tarea"], "nivel": r["nivel"],
                     "vence_en": r["vence_en"], "solo_en_app": r["nivel"] == "R3"}
                    for r in apr_pendientes()],
                "cola_pendiente": cola["pendiente"], "proximo_reintento": cola["proximo_reintento"],
                "cola": cola["cuenta"], "cola_db": str(COLA_DB),
                "vivo": LIVE_FILE.name, "supervisor": CK_SUPERVISOR_FILE.name,
                "ultima_ejecucion": _ultima_ejecucion(),
            }
            path = OUTBOX / _STATUS_NOMBRE["principal"]  # el 2.º hueco escribe el suyo (t-agentes-paralelos-030)
            tmp = path.with_suffix(".tmp")
            tmp.write_text(json.dumps(status, ensure_ascii=False, indent=2), encoding="utf-8")
            for i in range(5):
                try:
                    os.replace(tmp, path)
                    break
                except PermissionError:
                    time.sleep(0.1 * (i + 1))
        except OSError:
            pass
        except Exception as e:  # nunca tumbar al que llama
            log(f"runner: latido con error ({type(e).__name__}: {e})")


def _runner_pulse_loop(stop_event):
    """Hilo de pulso: mientras una tarea corre, el bucle principal espera al
    motor; este hilo sigue escribiendo el vivo (cada ~5 s) y el latido
    (cada 60 s), para que nada se congele."""
    while not stop_event.is_set():
        try:
            d = _LIVE["d"]
            if d is not None and d.get("estado") != "terminado":
                live_write()
            if state.get("current") and time.time() - _HB["t"] >= HEARTBEAT_SECONDS:
                runner_heartbeat()
            # Con un motor trabajando el bucle no da vueltas: el pulso vence por el.
            if state.get("current") and time.time() - _APR["t"] >= APR_CADA_S:
                aprobaciones_vencer()
            # ...y apunta en cola.db lo que llega mientras tanto (gateway): si
            # se va la luz ahora, esas tareas ya estan en SQLite, no solo como
            # archivo. Solo se apuntan; las recoge el bucle cuando le toca.
            if state.get("current"):
                now = time.time()
                for p in TASKS.glob("*.task.json"):
                    try:
                        if now - p.stat().st_mtime >= 2 and not _is_model_task(p):
                            _cola_ver(p)
                    except OSError:
                        continue
        except Exception as e:
            log(f"runner (pulso) ERROR (se sigue): {type(e).__name__}: {e}")
        stop_event.wait(1)


# ---- paralelo seguro (t-paralelo-seguro-030): un 2.º hueco, con reglas
# Máximo 2 tareas a la vez (settings «paralelo_max», 1 = en serie). La 2.ª
# corre en un PROCESO APARTE (growi-bridge.py --slot2 <tarea>) para no mezclar
# el estado de la que ya corre. Solo si: no son del mismo tipo de motor (nunca
# dos Claudes: sesión Max única; nunca dos locales: VRAM) y sus carpetas o
# archivos objetivo no se solapan (si se solapan, en serie). Si son del mismo
# repo git, la 2.ª trabaja en su worktree «agent/<id>» y NADA se fusiona solo:
# al terminar se corre la suite de tests en el worktree; con exit 0 queda la
# nota de merge para que Leandro decida; si falla, el agente recibe el fallo y
# reintenta. Una tarea que espera aprobación se aparca y libera el hueco.
PARALELO_WT_REG = APP_DIR / "worktrees-agentes.json"
SLOT_DIR = TASKS.parent / "runner-slot"
_SLOT = {"proc": None, "task": None, "file": None, "t0": None, "wt": None, "main": None}


def paralelo_max():
    try:
        return max(1, min(2, int(load_settings().get("paralelo_max") or 2)))
    except (TypeError, ValueError):
        return 2


def _motor_clase(task):
    m = str(task.get("motor") or default_motor())
    mod = str(task.get("model") or task.get("modelo") or "")
    return "local" if m in ("llama", "ollama") or mod.startswith("ollama:") else m


def _objetivos(task):
    decl = [str(x) for x in (task.get("archivos") or []) if x]
    decl += [str(a.get("ruta")) for a in task.get("acciones") or [] if a.get("ruta")]
    base = Path(task.get("cwd") or INBOX)
    out = [Path(x) if Path(x).is_absolute() else base / x for x in decl]
    return out or [base]


def _repo_de(path):
    try:
        r = subprocess.run(["git", "-C", str(path), "rev-parse", "--show-toplevel"], capture_output=True, text=True,
                           timeout=15, encoding="utf-8", errors="replace", **_oculto())
        return os.path.normcase(os.path.abspath(r.stdout.strip())) if r.returncode == 0 and r.stdout.strip() else None
    except (OSError, subprocess.TimeoutExpired):
        return None


def paralelo_decidir(a, b):
    """(en_paralelo, motivo, usar_worktree) para la tarea b junto a la a, que ya corre."""
    if paralelo_max() < 2:
        return False, "el tope es 1 (settings «paralelo_max»): en serie", False
    ca, cb = _motor_clase(a), _motor_clase(b)
    if ca == cb:
        return False, ("nunca dos Claudes a la vez (sesión Max única)" if ca == "claude" else
                       "nunca dos modelos locales a la vez (VRAM)" if ca == "local" else
                       f"el motor {ca} ya está ocupado"), False
    for x in _objetivos(a):
        for y in _objetivos(b):
            if _dentro(x, y) or _dentro(y, x):
                return False, f"se solapan ({y} y {x}): en serie", False
    ra, rb = _repo_de(a.get("cwd") or INBOX), _repo_de(b.get("cwd") or INBOX)
    return True, "no se solapan", bool(ra and ra == rb)


def _wt_reg():
    try:
        d = json.loads(PARALELO_WT_REG.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _wt_guardar(reg):
    PARALELO_WT_REG.write_text(json.dumps(reg, ensure_ascii=False, indent=2), encoding="utf-8")


def es_worktree_agente(cwd):
    """True si cwd está dentro de un worktree que creó Bridge para una tarea (su repo sí está permitido)."""
    for w in _wt_reg().values():
        if w.get("estado") in ("activo", "tests_ok", "tests_fallan") and _dentro(cwd, w["ruta"]):
            return True
    return False


def _git(args, cwd, timeout=120):
    r = subprocess.run(["git", "-C", str(cwd)] + list(args), capture_output=True, text=True, timeout=timeout,
                       encoding="utf-8", errors="replace", **_oculto())
    return r.returncode, (r.stdout or "") + (r.stderr or "")


def worktree_crear(task):
    """git worktree add ../<repo>-<id> -b agent/<id>. Devuelve el registro o None."""
    repo = _repo_de(task.get("cwd") or INBOX)
    if not repo:
        return None
    tid = _safe_id_part(task["id"])
    ruta = Path(repo).parent / f"{Path(repo).name}-{tid}"
    rama = f"agent/{tid}"
    base_rc, base = _git(["rev-parse", "--abbrev-ref", "HEAD"], repo)
    rc, out = _git(["worktree", "add", str(ruta), "-b", rama], repo)
    if rc != 0:
        log(f"paralelo: no se pudo crear el worktree de {task['id']}: {out.strip()[:300]}")
        return None
    rel = os.path.relpath(os.path.abspath(task.get("cwd") or repo), repo)
    w = {"tarea": task["id"], "repo": repo, "ruta": str(ruta), "rama": rama, "base": base.strip() if base_rc == 0 else None,
         "cwd": str(ruta / rel) if rel != "." else str(ruta), "creado": _now_iso(), "estado": "activo", "tests": [],
         "reintentos_test": 0}
    reg = _wt_reg()
    reg[task["id"]] = w
    _wt_guardar(reg)
    log(f"paralelo: worktree {ruta} en la rama {rama} para {task['id']} (sale de {w['base']})")
    return w


def _tests_comando(ruta):
    cmd = str(load_settings().get("paralelo_tests") or "").strip()
    if cmd:
        return cmd.split()
    if (Path(ruta) / "tests").is_dir() or list(Path(ruta).glob("test_*.py")):
        return [sys.executable.replace("pythonw.exe", "python.exe"), "-m", "pytest", "-q"]
    return None


def worktree_test_gate(tid):
    """Corre la suite en el worktree. (exit, salida). Sin suite: (None, motivo)."""
    reg = _wt_reg()
    w = reg.get(tid)
    if not w:
        return None, "no hay worktree para esa tarea"
    cmd = _tests_comando(w["ruta"])
    if not cmd:
        w["tests"].append({"at": _now_iso(), "comando": None, "exit": None, "salida": "sin suite de tests"})
        _wt_guardar(reg)
        return None, "el repo no tiene suite de tests (settings «paralelo_tests»): sin test gate no se fusiona"
    try:
        r = subprocess.run(cmd, cwd=w["ruta"], capture_output=True, text=True, timeout=900, encoding="utf-8",
                           errors="replace", **_oculto())
        rc, out = r.returncode, ((r.stdout or "") + (r.stderr or ""))[-3000:]
    except (OSError, subprocess.TimeoutExpired) as e:
        rc, out = 1, f"no se pudo correr: {type(e).__name__}: {e}"
    w["tests"].append({"at": _now_iso(), "comando": " ".join(cmd), "exit": rc, "salida": out[-1500:]})
    w["estado"] = "tests_ok" if rc == 0 else "tests_fallan"
    _wt_guardar(reg)
    log(f"paralelo: tests en el worktree de {tid}: exit {rc}")
    return rc, out


def worktree_nota_merge(tid, main_id=None):
    w = _wt_reg().get(tid) or {}
    ult = (w.get("tests") or [{}])[-1]
    nota = [f"# Nota de merge: {w.get('rama')}", "",
            f"- Repo: {w.get('repo')} (rama base: {w.get('base')})",
            f"- Worktree: {w.get('ruta')}",
            f"- Orden: primero lo que ya está en {w.get('base')}"
            + (f" (incluida la tarea {main_id}, que corrió en el checkout principal)" if main_id else "")
            + f"; después {w.get('rama')}.",
            f"- Tests en el worktree: `{ult.get('comando')}` → exit {ult.get('exit')}",
            "- Nada se fusiona solo: «Fusionar» vuelve a correr los tests y solo fusiona con exit 0.", "",
            "```", str(ult.get("salida") or "")[-1200:], "```"]
    p = RESULTS / f"{tid}.merge.md"
    p.write_text("\n".join(nota) + "\n", encoding="utf-8")
    return p


def paralelo_fusionar(tid):
    """Merge explícito (lo pide Leandro): tests otra vez; con exit 0, merge --no-ff y se quita el worktree."""
    w = _wt_reg().get(tid)
    if not w:
        return False, "no hay worktree para esa tarea"
    rc, out = worktree_test_gate(tid)
    if rc != 0:
        return False, ("no se fusiona: " + (out if rc is None else f"los tests fallan (exit {rc})"))[:400]
    mrc, mout = _git(["merge", "--no-ff", w["rama"], "-m", f"Merge {w['rama']} (tarea {tid}, tests en verde)"], w["repo"])
    if mrc != 0:
        _git(["merge", "--abort"], w["repo"])
        return False, f"conflicto al fusionar: {mout.strip()[:300]} (merge abortado; nada cambió)"
    _git(["worktree", "remove", w["ruta"]], w["repo"])
    _git(["branch", "-d", w["rama"]], w["repo"])
    reg = _wt_reg()
    reg[tid]["estado"] = "fusionado"
    reg[tid]["fusionado"] = _now_iso()
    _wt_guardar(reg)
    log(f"paralelo: {w['rama']} fusionada en {w['base']} y worktree quitado")
    return True, f"fusionada {w['rama']} en {w['base']}"


def _slot_lanzar(main_task, cand_file, cand_task, usar_wt):
    data = json.loads(Path(cand_file).read_text(encoding="utf-8"))
    if usar_wt:
        w = worktree_crear(cand_task)
        if w is None:
            log(f"paralelo: {cand_task['id']} es del mismo repo y no hay worktree: va en serie")
            return False
        data["cwd"], data["worktree"] = w["cwd"], {"ruta": w["ruta"], "rama": w["rama"]}
    SLOT_DIR.mkdir(parents=True, exist_ok=True)
    dest = SLOT_DIR / Path(cand_file).name
    os.replace(cand_file, dest)  # primero fuera de la cola (atómico): el bucle principal ya no la ve
    dest.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    py = sys.executable.replace("pythonw.exe", "python.exe")
    p = subprocess.Popen([py, str(Path(__file__).resolve()), "--slot2", str(dest)], cwd=str(APP_DIR),
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **_oculto())
    _SLOT.update(proc=p, task=cand_task, file=dest, t0=time.time(), wt=usar_wt, main=main_task.get("id"))
    log(f"paralelo: {cand_task['id']} ({_motor_clase(cand_task)}) en el 2.º hueco junto a {main_task['id']} "
        f"({_motor_clase(main_task)})" + (" en su worktree" if usar_wt else "") + f"; proceso {p.pid}")
    return True


def _wt_de_cwd(cwd):
    """La tarea dueña del worktree donde está cwd (para los reintentos del agente en su worktree)."""
    for tid, w in _wt_reg().items():
        if w.get("estado") in ("activo", "tests_ok", "tests_fallan") and _dentro(cwd, w["ruta"]):
            return tid
    return None


def _slot_terminar():
    p, t = _SLOT["proc"], _SLOT["task"]
    rc = p.poll()
    log(f"paralelo: el 2.º hueco terminó {t['id']} (salida {rc})")
    if rc != 0 and _agente_reasignar(t, rc):  # murió a medias: a la cola, desde su checkpoint
        _SLOT.update(proc=None, task=None, file=None, t0=None, wt=None, main=None)
        return
    dueno = t["id"] if _SLOT["wt"] else _wt_de_cwd(t.get("cwd") or "")
    if dueno:
        rc_t, out = worktree_test_gate(dueno)
        nota = worktree_nota_merge(dueno, _SLOT["main"])
        if rc_t == 0:
            _family_update(t.get("raiz") or t["id"], merge={"estado": "tests en verde: espera tu decisión de fusionar",
                                                            "nota": str(nota)})
        else:
            reg = _wt_reg()
            w = reg.get(dueno) or {}
            if rc_t is not None and w.get("reintentos_test", 0) < 2:  # el agente recibe el fallo y reintenta
                w["reintentos_test"] = w.get("reintentos_test", 0) + 1
                _wt_guardar(reg)
                nid = _new_task_file({"id": f"{dueno[:60]}-test{w['reintentos_test']}", "motor": t.get("motor"),
                                      "cwd": w["cwd"], "worktree": {"ruta": w["ruta"], "rama": w["rama"]},
                                      "raiz": t.get("raiz") or t["id"], "run_id": t.get("run_id") or t["id"],
                                      "tarea_padre": t["id"], "revisar": False,
                                      "prompt": "Los tests fallan en tu worktree después de tu cambio. Corrígelo "
                                                f"(solo esto). Salida de `{(w.get('tests') or [{}])[-1].get('comando')}`:\n"
                                                + out[-2000:]})
                log(f"paralelo: tests en rojo en el worktree de {dueno}: el agente recibe el fallo y reintenta ({nid})")
            elif rc_t is not None:
                log(f"paralelo: tests en rojo en el worktree de {dueno} tras {w.get('reintentos_test')} reintento(s): "
                    "se para; la rama queda sin fusionar para que decidas tú")
            _family_update(t.get("raiz") or t["id"], merge={"estado": "tests en rojo: no se fusiona", "nota": str(nota)})
    _SLOT.update(proc=None, task=None, file=None, t0=None, wt=None, main=None)


def _main_actual():
    tid = state.get("current")
    if not tid:
        return None
    for p in PROCESSING.glob("*.task.json"):
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if d.get("id") == tid:
            t, err = validate_task(d)
            return t if not err else None
    return None


def slot_vigia(stop_event):
    """Cada 3 s: si corre una tarea y el 2.º hueco está libre, busca otra compatible."""
    while not stop_event.is_set():
        try:
            if _SLOT["proc"] is not None:
                if _SLOT["proc"].poll() is not None:
                    _slot_terminar()
                else:  # los 2 huecos ocupados: lo que espera lo dice (cola visible)
                    for f in list(TASKS.glob("*.task.json"))[:6]:
                        try:
                            tid = json.loads(f.read_text(encoding="utf-8")).get("id")
                            if tid in (state.get("current"), (_SLOT.get("task") or {}).get("id")):
                                continue  # un duplicado de lo que ya corre: no se toca su fila (deduplicación)
                            _cola_ver(f)  # que conste en la cola (y en la vista) aunque el bucle aún no la haya visto
                            fila = cola_get(tid) if tid else None
                            if fila and fila.get("estado") == "en_cola" and not fila.get("motivo"):
                                cola_set(tid, motivo=f"espera hueco: los {paralelo_max()} huecos están ocupados")
                        except (OSError, ValueError):
                            continue
            elif paralelo_max() >= 2 and not _BREAKER["pausado"]:
                main = _main_actual()
                if main is not None:
                    espera = cola_en_espera()
                    now = time.time()
                    for f in sorted(TASKS.glob("*.task.json"), key=lambda q: q.stat().st_mtime):
                        if now - f.stat().st_mtime < 2 or _is_model_task(f) or f.name in espera:
                            continue
                        try:
                            t, err = validate_task(json.loads(f.read_text(encoding="utf-8")))
                        except (OSError, ValueError):
                            continue
                        if err:
                            continue
                        if t["id"] == main["id"] or (cola_get(t["id"]) or {}).get("estado") == "en_curso":
                            if _SLOT.get("ultimo_dup") != t["id"]:
                                log(f"agentes: {t['id']} ya tiene un agente activo: no se asigna otro (deduplicación)")
                                _SLOT["ultimo_dup"] = t["id"]
                            continue
                        ok, motivo, wt = paralelo_decidir(main, t)
                        if ok:
                            _slot_lanzar(main, f, t, wt)
                            break
                        log(f"paralelo: {t['id']} no va junto a {main['id']}: {motivo}") if _SLOT.get(
                            "ultimo_no") != (t["id"], main["id"]) else None
                        try:
                            _cola_ver(f)
                            cola_set(t["id"], motivo=f"espera hueco: {motivo}")
                        except Exception:
                            pass
                        _SLOT["ultimo_no"] = (t["id"], main["id"])
        except Exception as e:
            log(f"paralelo: {type(e).__name__}: {e}")
        stop_event.wait(3)


def _cli_slot2(ruta):
    """El 2.º hueco: procesa UNA tarea en este proceso y sale."""
    global LIVE_FILE
    SLOT2_MODO["activo"] = True  # contexto mínimo y sus propios archivos de estado
    _STATUS_NOMBRE["principal"] = "runner-status-slot2.json"
    LIVE_FILE = OUTBOX / "runner-live-slot2.json"
    cola_init()
    hook = os.environ.get("GROWI_BRIDGE_PRUEBA_HOOK")
    if hook and os.environ.get("GROWI_BRIDGE_SHARE") and os.environ.get("GROWI_BRIDGE_MUTEX"):
        import runpy  # solo en una instancia aislada de prueba (share y mutex propios)
        runpy.run_path(hook, init_globals={"gb": sys.modules[__name__]})
    p = Path(ruta)
    try:
        process_one(p)
    except Exception as e:
        log(f"paralelo: el 2.º hueco falló con {p.name}: {type(e).__name__}: {e}")
        return 1
    return 0


# ---- agentes en paralelo (t-agentes-paralelos-030): el orquestador encima
# del 2.º hueco. Cada agente = un motor + su tarea (+ su worktree si es código
# del mismo repo). Tope total paralelo_max (2). Lo que no cabe queda en la cola
# con el motivo a la vista («espera hueco: …»). Nunca dos agentes con el mismo
# task_id. Si el agente del 2.º hueco muere, su tarea vuelve a la cola y sigue
# desde su checkpoint; el otro agente no se entera. Cada agente del 2.º hueco
# recibe solo encargo + archivos de su tarea + perfil (sin la memoria larga), y
# queda apuntado qué contexto recibió.
SLOT2_MODO = {"activo": False}
_STATUS_NOMBRE = {"principal": "runner-status.json"}
_CTX = {}


def contexto_apuntar(task, partes):
    """Lo que de verdad recibió el motor de esa tarea (caracteres por pieza)."""
    _CTX[str(task.get("id"))] = dict({k: len(v or "") for k, v in partes.items()},
                                     modo="agente del 2.º hueco (contexto mínimo)" if SLOT2_MODO["activo"]
                                     else "principal")
    if len(_CTX) > 300:
        for k in list(_CTX)[:100]:
            _CTX.pop(k, None)


def agentes_vista():
    """[{hueco, tarea, motor, estado, costo, progreso, worktree}] + [(en cola, motivo)]."""
    out = []
    if state.get("current"):
        lv = _LIVE.get("d") or {}
        ini = _ACT.get("started_at")
        try:
            seg = time.time() - datetime.fromisoformat(ini).timestamp() if ini else None
        except ValueError:
            seg = None
        out.append({"hueco": 1, "tarea": state["current"], "motor": state.get("current_motor"),
                    "estado": "en curso", "costo": lv.get("cost_usd_estimado"),
                    "tokens": (lv.get("tokens_in") or 0) + (lv.get("tokens_out") or 0),
                    "progreso": state.get("paso") or (f"{_gw_hace(seg)} trabajando" if seg else "empezando"),
                    "worktree": None})
    if _SLOT.get("proc") is not None and _SLOT.get("task"):
        t = _SLOT["task"]
        try:
            st = json.loads((OUTBOX / "runner-status-slot2.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            st = {}
        try:
            lv2 = json.loads((OUTBOX / "runner-live-slot2.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            lv2 = {}
        w = _wt_reg().get(t["id"]) or {}
        out.append({"hueco": 2, "tarea": t["id"], "motor": t.get("motor"), "estado": "en curso",
                    "costo": lv2.get("cost_usd_estimado"),
                    "tokens": (lv2.get("tokens_in") or 0) + (lv2.get("tokens_out") or 0),
                    "progreso": st.get("paso") or f"{_gw_hace(time.time() - (_SLOT.get('t0') or time.time()))} trabajando",
                    "worktree": w.get("rama")})
    cola = []
    try:
        for r in _cola("SELECT id, motivo FROM tareas WHERE estado='en_cola' AND motivo LIKE 'espera hueco:%' "
                       "ORDER BY actualizado_ts", fetch=True):
            cola.append((r["id"], r["motivo"]))
    except Exception:
        pass
    return out, cola


def _agente_reasignar(t, rc):
    """El agente del 2.º hueco murió con su tarea a medias: vuelve a la cola y
    sigue desde su checkpoint (el otro agente sigue como si nada)."""
    fila = cola_get(t["id"]) or {}
    if fila.get("estado") != "en_curso":
        return False
    name = Path(fila.get("archivo") or f"{t['id']}.task.json").name
    src = PROCESSING / name
    if not src.exists():
        return False
    os.replace(src, TASKS / name)
    cortes = (fila.get("cortes") or 0) + 1
    cola_set(t["id"], estado="en_cola", archivo=str(TASKS / name), cortes=cortes, proximo_intento=None,
             motivo=f"el agente del 2.º hueco murió (salida {rc}): se reasigna y sigue desde su checkpoint")
    _family_update(t.get("raiz") or t["id"], estado="pendiente", en_curso=None, recuperada_tras_corte=True)
    log(f"agentes: el agente de {t['id']} murió (salida {rc}) a mitad: vuelve a la cola (corte {cortes}) y sigue "
        "desde su checkpoint; el resto sigue")
    return True


_AGUI = {"kit": None}


def _agentes_build(page):
    holder = tk.Frame(page, bg=THEME["bg"])
    holder.pack(fill="x")
    k = None
    if _ctk_wanted():
        try:
            k = _KitCtk(holder)
        except Exception as e:
            log(f"agentes: CustomTkinter no disponible ({type(e).__name__}: {e}); tarjeta clásica")
    k = k or _KitTk(holder)
    _AGUI["kit"] = k
    c = k.section("Agentes", f"Hasta {paralelo_max()} a la vez: nunca dos Claudes ni dos locales; lo que no cabe "
                             "espera en la cola con el motivo.")
    _AGUI["box"] = k.frame(c)
    _AGUI["box"].pack(fill="x", padx=16, pady=(2, 12))
    _AGUI["fp"] = None
    _agentes_refrescar()


def _agentes_refrescar():
    k = _AGUI.get("kit")
    if k is None:
        return
    try:
        filas, cola = agentes_vista()
        txt = []
        for f in filas:
            txt.append((f"Hueco {f['hueco']}: {f['tarea']}, {MOTOR_CORTO.get(str(f['motor']), f['motor'])}"
                        + (f", rama {f['worktree']}" if f.get("worktree") else "")
                        + f", {f['estado']}, " + (f"${f['costo']:.4f}" if isinstance(f.get("costo"), (int, float))
                                                     else "costo sin dato")
                        + (f", {f['tokens']} tokens" if f.get("tokens") else "") + f", {f['progreso']}"[:160], "text"))
        if not filas:
            txt.append(("Ningún agente trabajando ahora.", "muted"))
        for tid, motivo in cola[:4]:
            txt.append((f"En cola: {tid} — {motivo}"[:180], "orange_text"))
        if txt != _AGUI["fp"]:
            _AGUI["fp"] = txt
            for ch in _AGUI["box"].winfo_children():
                ch.destroy()
            for t, col in txt:
                k.label(_AGUI["box"], t, wrap=600, color=col).pack(anchor="w", pady=1)
    except Exception as e:
        log(f"agentes: vista ({type(e).__name__}: {e})")
    try:
        _AGUI["box"].after(3000, _agentes_refrescar)
    except Exception:
        pass


def runner_loop(stop_event):
    for d in (TASKS, PROCESSING, DONE, RESULTS, WAITING):
        d.mkdir(parents=True, exist_ok=True)
    claude = shutil.which("claude")
    log(f"runner: arrancado (claude={claude or 'NO ENCONTRADO'})")
    try:
        # Supervisor: ANTES de reponer la cola, recompone desde el checkpoint
        # en que ronda/paso se quedo cada tarea y cada plan.
        cola_init()
        supervisor_arranque()
    except Exception as e:
        log(f"supervisor ERROR al arrancar (el runner sigue): {type(e).__name__}: {e}")
    try:
        dag_supervisor()  # planes con grafo a medias (t-dag-fases-030)
    except Exception as e:
        log(f"supervisor: planes con fases: {type(e).__name__}: {e}")
    try:
        rec, _av = cola_recuperar()
        cola_archivar()
        log(f"cola: {COLA_DB} lista ({len(rec)} recuperada(s) tras corte)")
        # Aviso visible (no solo en el registro): bandeja + panel de Estado.
        GATEWAY.update(recuperadas=list(rec), avisos_cola=list(_av), arranque_at=_now_iso())
        if rec:
            n = len(rec)
            log(f"gateway AVISO: al arrancar se re-encolaron {n} tarea(s) que quedaron en curso: "
                + ", ".join(rec))
            _ui_call(lambda n=n: toast(f"{n} tarea{'s' if n != 1 else ''} vuelve{'n' if n != 1 else ''} "
                                       "a la cola tras el corte", ctx=("tareas",)))
    except Exception as e:
        log(f"cola ERROR al recuperar (el runner sigue): {type(e).__name__}: {e}")
    try:
        # Lo que vencio con el runner apagado se aplica ya: no resucita como pendiente.
        _APR["arranque"] = time.time()
        aprobaciones_adoptar()
        nv = aprobaciones_vencer()
        pend = apr_pendientes()
        log(f"aprobaciones: al arrancar {nv} vencida(s) aplicada(s), {len(pend)} pendiente(s)"
            + (f"; la próxima vence el {hora_caracas_txt(pend[0]['vence_ts'])} (Caracas)" if pend else ""))
    except Exception as e:
        log(f"aprobaciones ERROR al arrancar (el runner sigue): {type(e).__name__}: {e}")
    _eng, _err = load_engines()
    log("motores: " + ", ".join(f"{k} {'sí' if v['disponible'] else 'no'}"
                                for k, v in engines_summary().items())
        + (f" (AVISO: {_err})" if _err else ""))
    if not claude:
        log("runner AVISO: `claude` no esta en el PATH; las tareas fallaran con error.")
    threading.Thread(target=_runner_pulse_loop, args=(stop_event,), daemon=True).start()
    threading.Thread(target=slot_vigia, args=(stop_event,), daemon=True).start()  # 2.º hueco (t-paralelo-seguro-030)
    last_heartbeat = 0.0
    last_archive = time.time()
    while not stop_event.is_set():
        try:
            now = time.time()
            if now - max(last_heartbeat, _HB["t"]) >= HEARTBEAT_SECONDS:
                runner_heartbeat()
                last_heartbeat = now
            if now - last_archive >= 3600:
                cola_archivar()
                last_archive = now
            if aprobaciones_vencer():  # cada vuelta de la cola: ninguna espera es infinita
                runner_heartbeat()
            if _BREAKER["pausado"]:  # circuit breaker: la cola espera a que la reanudes
                stop_event.wait(5)
                continue
            espera = cola_en_espera()
            candidates = []
            for p in TASKS.glob("*.task.json"):
                try:
                    if now - p.stat().st_mtime >= 2 and not _is_model_task(p):
                        _cola_ver(p)  # se apunta en cola.db antes de recogerla
                        if p.name not in espera:
                            candidates.append(p)
                except OSError:
                    continue
            # Las rondas de correccion van primero (son la misma tarea).
            candidates.sort(key=lambda p: (0 if _is_round_task(p) else 1, p.stat().st_mtime))
            if candidates:
                if process_one(candidates[0]):
                    runner_heartbeat()
                    last_heartbeat = time.time()
        except Exception as e:
            log(f"runner ERROR en el loop (se sigue): {type(e).__name__}: {e}")
        stop_event.wait(POLL_SECONDS)
    log("runner: parado")


def _is_round_task(path):
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        return isinstance(data, dict) and bool(data.get("ronda"))
    except Exception:
        return False


def _is_model_task(path):
    """True si el task es una accion de modelos (ollama_action). Esos van
    por su propio carril para no esperar detras de una tarea larga de Claude."""
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        return isinstance(data, dict) and "ollama_action" in data
    except Exception:
        return False


def model_lane_loop(stop_event):
    """Carril de modelos: instala / borra / lista modelos de uno en uno,
    aunque Claude este ocupado con otra tarea."""
    while not stop_event.is_set():
        try:
            now = time.time()
            candidates = []
            for p in TASKS.glob("*.task.json"):
                try:
                    if now - p.stat().st_mtime >= 1 and _is_model_task(p):
                        _cola_ver(p)
                        candidates.append(p)
                except OSError:
                    continue
            if candidates:
                candidates.sort(key=lambda p: p.stat().st_mtime)
                process_one(candidates[0])
                continue
        except Exception as e:
            log(f"runner (modelos) ERROR en el loop (se sigue): {type(e).__name__}: {e}")
        stop_event.wait(2)


# ---------------------------------------------------------------- gateway unificado
# t-gateway-unificado-030. Growi Bridge es UN proceso coordinador: la ventana,
# el puente (plano de control), el runner y la cola viven aqui dentro como
# hilos. Lo que este bloque anade:
#   - instancia unica: mutex con nombre + gateway.lock (pid) de respaldo; una
#     segunda copia avisa «ya está corriendo» y sale sin tocar nada;
#   - plano de control solo en 127.0.0.1 (y en la IP de Tailscale de este PC
#     si hay tunel; nunca 0.0.0.0), con bind exclusivo (sin SO_REUSEADDR, que
#     en Windows deja a dos procesos escuchar el mismo puerto), token guardado
#     fuera de la carpeta (DPAPI en %LOCALAPPDATA%\GrowiBridge) y Origin/Host
#     validados en cada peticion;
#   - estado en vivo para la pestana Estado (/gateway/estado);
#   - recarga en caliente de settings.json, engines.json, reglas, carpetas y
#     skills, por secciones; las tareas en curso siguen con su config.
# Referencia de diseno (no dependencia): openclaw/openclaw 2026.10.7
# src/gateway/server-start.ts y zod-schema.gateway.ts. De ahi NO se copia la
# confianza en 127.0.0.1 (CVE-2026-25253), ni el hot-reload que pierde
# sesiones, ni sus subsistemas con nombre propio.
GATEWAY = {"inicio": time.time(), "lock": None, "mutex": None, "recuperadas": [], "avisos_cola": [],
           "arranque_at": None, "tunel": {"estado": "sin comprobar"}, "escucha": [],
           "token_origen": None, "rechazos": deque(maxlen=50), "_rech_log": {}}
LOCK_FILE = APP_DIR / "gateway.lock"
_CFG_LOCAL = threading.local()
_RECARGA = {"huellas": {}, "propio": {}, "hist": deque(maxlen=30), "settings": None, "skills": None,
            "motores": None}
_GW_ESTADO_CACHE = {"t": 0.0, "motores": None}


def _instancia_aislada():
    """Copia de prueba: share propia + mutex propio y no es la share instalada."""
    try:
        instalada = (HOME_DIR / "growi-bridge" / "share").resolve()
        return (bool(os.environ.get("GROWI_BRIDGE_SHARE")) and bool(os.environ.get("GROWI_BRIDGE_MUTEX"))
                and SHARE.resolve() != instalada)
    except OSError:
        return False


# ---- instancia unica
def _pid_vivo(pid):
    """True si el pid es un proceso vivo de Python (contra pids reciclados)."""
    try:
        import ctypes
        from ctypes import wintypes
        k32 = ctypes.windll.kernel32
        k32.OpenProcess.restype = wintypes.HANDLE
        h = k32.OpenProcess(0x1000, False, int(pid))  # PROCESS_QUERY_LIMITED_INFORMATION
        if not h:
            return False
        try:
            code = wintypes.DWORD()
            if not k32.GetExitCodeProcess(h, ctypes.byref(code)) or code.value != 259:  # STILL_ACTIVE
                return False
            buf = ctypes.create_unicode_buffer(1024)
            n = wintypes.DWORD(1024)
            if k32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(n)):
                return "python" in Path(buf.value).name.lower()
            return True
        finally:
            k32.CloseHandle(h)
    except Exception:
        return False


def _lock_leer():
    try:
        d = json.loads(LOCK_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None


def _lock_escribir():
    d = {"pid": os.getpid(), "inicio": _now_iso(), "puerto": BRIDGE_PORT, "carril": LANE,
         "programa": str(APP_DIR / "growi-bridge.py"), "python": sys.executable}
    try:
        tmp = LOCK_FILE.with_suffix(".lock.tmp")
        tmp.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
        os.replace(tmp, LOCK_FILE)
        GATEWAY["lock"] = d
    except OSError as e:
        log(f"gateway: no se pudo escribir {LOCK_FILE.name} ({e}); queda solo el mutex")


def _lock_soltar():
    """Al salir: solo si el lockfile es el nuestro."""
    try:
        d = _lock_leer()
        if d and d.get("pid") == os.getpid():
            LOCK_FILE.unlink()
    except OSError:
        pass


def instancia_unica():
    """(True, None) si somos la unica instancia; si no (False, motivo). Mutex
    con nombre (CreateMutexW) + gateway.lock de respaldo. OJO: la app corre
    elevada (tarea GrowiBridgeApp, HighestAvailable); una copia sin elevar no
    puede abrir ese mutex y Windows contesta ERROR_ACCESS_DENIED (5), no
    ERROR_ALREADY_EXISTS (183). Antes se tomaba como «no hay nadie» y la copia
    seguia: dos iconos y dos puentes. Ahora 5 tambien es «ya hay otra»."""
    name = os.environ.get("GROWI_BRIDGE_MUTEX") or (
        "Local\\GrowiBridgeInstanciaUnica" + ("-carrilB" if LANE == "b" else ""))
    GATEWAY["mutex"] = name
    try:
        import ctypes
        k32 = ctypes.windll.kernel32
        k32.CreateMutexW.restype = ctypes.c_void_p
        k32.GetLastError.restype = ctypes.c_ulong
        h = k32.CreateMutexW(None, False, name)
        err = k32.GetLastError()
        if err == 183:
            return False, f"el mutex {name} ya existe"
        if not h and err == 5:
            return False, f"el mutex {name} ya existe (lo creó una copia con más privilegios)"
        if h:
            global _instance_mutex
            _instance_mutex = h
        else:
            log(f"instancia unica: CreateMutexW fallo (error {err}); se mira el lockfile")
    except Exception as e:
        log(f"instancia unica: no se pudo comprobar el mutex ({e}); se mira el lockfile")
    d = _lock_leer()
    if d and d.get("pid") != os.getpid() and _pid_vivo(d.get("pid") or 0):
        return False, f"{LOCK_FILE.name} dice que el pid {d.get('pid')} está vivo"
    _lock_escribir()
    return True, None


# ---- traer al frente la instancia que ya corre
# Evento con nombre (auto-reset), uno por carril: lo crea la instancia unica
# al arrancar y su bucle de Tk lo mira cada 300 ms; la segunda copia lo
# abre, lo marca y sale. Se deriva del nombre del mutex, asi que lleva el
# mismo sufijo de carril (y el de una copia de prueba con GROWI_BRIDGE_MUTEX).
_mostrar_evento = None


def _nombre_mostrar():
    m = GATEWAY.get("mutex") or "Local\\GrowiBridgeInstanciaUnica"
    return (m.replace("GrowiBridgeInstanciaUnica", "GrowiBridgeMostrar")
            if "GrowiBridgeInstanciaUnica" in m else m + "-Mostrar")


def _mostrar_crear():
    """La instancia unica crea el evento. Con DACL explicita: la app corre
    elevada y, si la DACL por defecto no dejara entrar a una copia sin
    elevar (el caso del error 5 del mutex), esa copia no podria marcarlo.
    Usuarios autenticados solo pueden marcarlo (EVENT_MODIFY_STATE |
    SYNCHRONIZE); etiqueta de integridad media."""
    global _mostrar_evento
    name = _nombre_mostrar()
    try:
        import ctypes
        from ctypes import wintypes
        k32, adv = ctypes.windll.kernel32, ctypes.windll.advapi32

        class SA(ctypes.Structure):
            _fields_ = [("nLength", wintypes.DWORD), ("lpSecurityDescriptor", ctypes.c_void_p),
                        ("bInheritHandle", wintypes.BOOL)]
        sd = ctypes.c_void_p()
        sa = None
        if adv.ConvertStringSecurityDescriptorToSecurityDescriptorW(
                "D:(A;;0x1F0003;;;SY)(A;;0x1F0003;;;BA)(A;;0x1F0003;;;OW)(A;;0x100002;;;AU)S:(ML;;NW;;;ME)",
                1, ctypes.byref(sd), None):
            sa = SA(ctypes.sizeof(SA), sd, False)
        k32.CreateEventW.restype = ctypes.c_void_p
        h = k32.CreateEventW(ctypes.byref(sa) if sa else None, False, False, name)
        if not h:
            h = k32.CreateEventW(None, False, False, name)
        if sd:
            k32.LocalFree(sd)
        _mostrar_evento = h or None
        if not h:
            log(f"instancia unica: no se pudo crear el evento {name} (error {k32.GetLastError()}); "
                "una segunda copia no podrá traer la ventana al frente")
    except Exception as e:
        log(f"instancia unica: evento {name} no disponible ({type(e).__name__}: {e})")


def _mostrar_poll():
    """Bucle de Tk: si una segunda copia marcó el evento, show_window() (el
    mismo camino que el doble clic en la bandeja: sirve con withdraw e iconify)."""
    if _mostrar_evento is None or _root is None:
        return
    try:
        import ctypes
        if ctypes.windll.kernel32.WaitForSingleObject(ctypes.c_void_p(_mostrar_evento), 0) == 0:
            log("instancia unica: otra copia pidió la ventana; se trae al frente")
            show_window()
            _root.after(500, _mostrar_comprobar)
    except Exception:
        pass
    try:
        _root.after(300, _mostrar_poll)
    except Exception:
        pass


def _mostrar_comprobar():
    """Si la ventana quedo visible pero sin el foco (la copia que lo pidio no
    tenia derecho a cederlo, p. ej. la lanzo un proceso de fondo), se toma
    con AttachThreadInput al hilo que tiene el foco. Lo deja en el registro."""
    try:
        import ctypes
        u32, k32 = ctypes.windll.user32, ctypes.windll.kernel32
        u32.GetForegroundWindow.restype = ctypes.c_void_p
        hw = int(_root.wm_frame(), 16)
        como = "en primer plano"
        fg = u32.GetForegroundWindow()
        if fg != hw:
            otro = u32.GetWindowThreadProcessId(ctypes.c_void_p(fg), None) if fg else 0
            mio = k32.GetCurrentThreadId()
            unido = bool(otro) and otro != mio and u32.AttachThreadInput(mio, otro, True)
            try:
                u32.BringWindowToTop(ctypes.c_void_p(hw))
                u32.SetForegroundWindow(ctypes.c_void_p(hw))
            finally:
                if unido:
                    u32.AttachThreadInput(mio, otro, False)
            como = ("en primer plano (tomado con AttachThreadInput)" if u32.GetForegroundWindow() == hw
                    else "visible y encima, pero sin el foco del teclado")
        log(f"instancia unica: ventana {_root.state()}, {como}")
    except Exception:
        pass


def _mostrar_senalar():
    """Segunda copia: marca el evento de la primera. True si se pudo."""
    name = _nombre_mostrar()
    try:
        import ctypes
        k32, u32 = ctypes.windll.kernel32, ctypes.windll.user32
        k32.OpenEventW.restype = ctypes.c_void_p
        k32.GetLastError.restype = ctypes.c_ulong
        h = k32.OpenEventW(0x0002, False, name)  # EVENT_MODIFY_STATE
        if not h:
            log(f"instancia unica: no se pudo abrir {name} (error {k32.GetLastError()})")
            return False
        try:
            # Esta copia la acaba de lanzar el usuario: puede ceder el primer
            # plano a la otra (sin esto Windows solo haría parpadear el botón).
            u32.AllowSetForegroundWindow(-1)  # ASFW_ANY
            return bool(k32.SetEvent(ctypes.c_void_p(h)))
        finally:
            k32.CloseHandle(ctypes.c_void_p(h))
    except Exception as e:
        log(f"instancia unica: no se pudo marcar {name} ({type(e).__name__}: {e})")
        return False


def _aviso_ya_corre(motivo):
    """La segunda copia: pide a la primera que se traiga al frente y sale sin
    ventana. Solo si no lo consigue (la primera aún arranca, evento sin
    acceso) muestra un aviso corto (3 s; antes 15 s). No toca puerto, cola,
    runner ni watchdog."""
    d = _lock_leer() or {}
    pid = d.get("pid")
    traida = _mostrar_senalar()
    log(f"Growi Bridge ya esta corriendo{f' (pid {pid})' if pid else ''}: esta copia (pid {os.getpid()}) "
        f"se cierra sin tocar nada ({motivo}); "
        + ("se pidió a la instancia que ya corre que se traiga al frente" if traida
           else "no se pudo avisar a la instancia que ya corre"))
    if traida:
        return
    txt = ("Growi Bridge ya está corriendo" + (f" (proceso {pid})" if pid else "") + ".\n\n"
           "Esta copia se cierra sin tocar nada. Busca el icono de Growi en la bandeja.")
    try:
        import ctypes
        u32 = ctypes.windll.user32
        fn = getattr(u32, "MessageBoxTimeoutW", None)
        if fn is not None:
            fn(0, txt, "Growi Bridge", 0x40 | 0x40000, 0, 3000)  # info + siempre encima
        else:
            u32.MessageBoxW(0, txt, "Growi Bridge", 0x40 | 0x40000)
    except Exception:
        pass


# ---- token del plano de control (fuera de la carpeta, cifrado con DPAPI)
def _dpapi(data, proteger):
    import ctypes
    from ctypes import wintypes

    class BLOB(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_char))]
    buf = ctypes.create_string_buffer(data, len(data))
    src, dst = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_char))), BLOB()
    c32 = ctypes.windll.crypt32
    fn = c32.CryptProtectData if proteger else c32.CryptUnprotectData
    if not fn(ctypes.byref(src), "growi-bridge" if proteger else None, None, None, None, 0x1,
              ctypes.byref(dst)):  # CRYPTPROTECT_UI_FORBIDDEN
        raise OSError(f"DPAPI fallo (error {ctypes.GetLastError()})")
    try:
        return ctypes.string_at(dst.pbData, dst.cbData)
    finally:
        ctypes.windll.kernel32.LocalFree(dst.pbData)


def _token_dir():
    if os.environ.get("GROWI_BRIDGE_TOKEN_DIR") and _instancia_aislada():
        return Path(os.environ["GROWI_BRIDGE_TOKEN_DIR"])
    return Path(os.environ.get("LOCALAPPDATA") or (HOME_DIR / "AppData" / "Local")) / "GrowiBridge"


def token_file():
    return _token_dir() / f"plano-control-{LANE}.dpapi"


def gateway_token(crear=True):
    """(token, origen). Vive en %LOCALAPPDATA%\\GrowiBridge\\plano-control-<carril>.dpapi,
    cifrado con DPAPI (solo este usuario de Windows lo descifra), fuera de la
    carpeta del programa y de settings.json. La primera vez, si hay un
    secret.txt viejo, se usa ese MISMO valor (la VM ya lo tiene y no se corta
    el puente); si no, se genera uno nuevo (instalador: --generar-token).
    secret.txt no se borra solo: browser\\browser-server.py todavia lo lee."""
    f = token_file()
    try:
        tok = _dpapi(f.read_bytes(), False).decode("utf-8").strip()
        if tok:
            return tok, "dpapi"
    except FileNotFoundError:
        pass
    except Exception as e:
        log(f"gateway: no se pudo leer el token protegido ({type(e).__name__}: {e})")
        if f.exists():
            return "", f"el token de {f} no se pudo descifrar"
    if not crear:
        return "", "no hay token"
    viejo = ""
    try:
        viejo = (APP_DIR / "secret.txt").read_text(encoding="utf-8").strip()
    except OSError:
        pass
    tok, origen = (viejo, "migrado de secret.txt") if viejo else (secrets.token_urlsafe(32), "generado")
    try:
        f.parent.mkdir(parents=True, exist_ok=True)
        tmp = f.with_suffix(".tmp")
        tmp.write_bytes(_dpapi(tok.encode("utf-8"), True))
        os.replace(tmp, f)
        log(f"gateway: token del plano de control {origen} y guardado cifrado en {f}"
            + (" (secret.txt sigue en la carpeta: la app ya no lo lee, pero el servidor del navegador "
               "sí; no lo borres hasta que ese también lea el token)" if viejo else ""))
    except Exception as e:
        log(f"gateway: no se pudo guardar el token protegido ({type(e).__name__}: {e})")
        return (tok, f"{origen}, sin guardar") if viejo else ("", f"no se pudo guardar ({e})")
    return tok, origen


# ---- quien puede hablar con el plano de control
def gateway_origenes():
    """Origins permitidos (por defecto ninguno: ninguna web habla con el gateway)."""
    v = load_settings().get("gateway_origenes_permitidos")
    return {str(x).strip() for x in v} if isinstance(v, list) else set()


def gateway_host_ok(host):
    """Defensa contra DNS rebinding: Host tiene que ser este PC, nunca un
    dominio ajeno que resuelva a 127.0.0.1."""
    h = host.rsplit(":", 1)[0].strip("[]") if not host.startswith("[") else host[1:].split("]")[0]
    ok = {"127.0.0.1", "localhost", "::1", socket.gethostname().lower()}
    ip = (GATEWAY.get("tunel") or {}).get("ip")
    if ip:
        ok.add(ip)
    return h in ok or h.endswith(".ts.net")


def gateway_rechazo(ip, metodo, ruta, motivo):
    GATEWAY["rechazos"].append({"at": _now_iso(), "ip": ip, "metodo": metodo,
                                "ruta": str(ruta)[:80], "motivo": motivo})
    k = (ip, motivo)
    if time.time() - GATEWAY["_rech_log"].get(k, 0) > 60:  # una linea por minuto y motivo
        GATEWAY["_rech_log"][k] = time.time()
        log(f"plano de control: rechazada {metodo} {str(ruta)[:60]} desde {ip}: {motivo}")


class _GatewayServer(ThreadingHTTPServer):
    """Bind EXCLUSIVO: sin SO_REUSEADDR (en Windows deja a otro proceso
    escuchar el mismo puerto: «dos instancias peleando por el 8787») y con
    SO_EXCLUSIVEADDRUSE, para que nadie mas pueda colgarse de el."""
    allow_reuse_address = False
    daemon_threads = True

    def server_bind(self):
        if hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
        super().server_bind()


# ---- tunel (Tailscale): acceso remoto solo por el tunel que ya existe
def _es_ip_tailscale(ip):
    try:
        a, b = (int(x) for x in ip.split(".")[:2])
        return a == 100 and 64 <= b <= 127  # 100.64.0.0/10 (CGNAT de Tailscale)
    except (ValueError, AttributeError):
        return False


def tunel_ip():
    """IPv4 de Tailscale de ESTE PC (o None). Primero las interfaces; si no,
    `tailscale ip -4` oculto. Solo esa IP: nunca la de la red local."""
    try:
        import psutil
        for _n, addrs in psutil.net_if_addrs().items():
            for a in addrs:
                if a.family == socket.AF_INET and _es_ip_tailscale(a.address):
                    return a.address
    except Exception:
        pass
    exe = shutil.which("tailscale") or str(Path(os.environ.get("ProgramFiles", r"C:\Program Files"))
                                           / "Tailscale" / "tailscale.exe")
    if Path(exe).is_file():
        try:
            rc, out, _e = _run_capture([exe, "ip", "-4"], 8)
            for line in out.split():
                if _es_ip_tailscale(line.strip()):
                    return line.strip()
        except Exception:
            pass
    return None


def _tunel_modo():
    m = str(load_settings().get("tunel_remoto") or "tailscale").strip().lower()
    return m if m in ("tailscale", "ninguno") else "tailscale"


def _tunel_arrancar():
    """Segundo oyente, SOLO en la IP de Tailscale (no en la LAN ni en
    0.0.0.0), con el mismo manejador: token + Origin + Host igual que en
    loopback. Sin tunel, la VM no llega, y el panel lo dice."""
    global _tunel_server
    if _tunel_server is not None:
        return
    if _tunel_modo() == "ninguno":
        GATEWAY["tunel"] = {"estado": "apagado", "motivo": "tunel_remoto = ninguno en settings.json"}
        return
    ip = tunel_ip()
    if not ip:
        GATEWAY["tunel"] = {"estado": "sin túnel", "motivo": "no encuentro la IP de Tailscale de este PC "
                                                               "(¿Tailscale apagado?); se reintenta cada 30 s"}
        return
    try:
        srv = _GatewayServer((ip, BRIDGE_PORT), BridgeHandler)
    except OSError as e:
        GATEWAY["tunel"] = {"estado": "error", "ip": ip, "motivo": f"no pude escuchar en {ip}:{BRIDGE_PORT} ({e})"}
        log(f"gateway: túnel ERROR en {ip}:{BRIDGE_PORT} ({e})")
        return
    _tunel_server = srv
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    GATEWAY["tunel"] = {"estado": "activo", "ip": ip, "puerto": BRIDGE_PORT, "via": "Tailscale"}
    log(f"gateway: túnel Tailscale escuchando en {ip}:{BRIDGE_PORT} (solo esa IP; token y Origin igual)")


def _tunel_parar():
    global _tunel_server
    if _tunel_server is not None:
        try:
            _tunel_server.shutdown()
            _tunel_server.server_close()
        except Exception:
            pass
        _tunel_server = None
    GATEWAY["tunel"] = {"estado": "apagado", "motivo": "el puente está apagado"}


def _tunel_vigia():
    while True:
        time.sleep(30)
        try:
            if _bridge_server is not None and _tunel_server is None and _tunel_modo() != "ninguno":
                _tunel_arrancar()
        except Exception as e:
            log(f"gateway: vigía del túnel ({type(e).__name__}: {e})")


def _escucha():
    out = [f"127.0.0.1:{BRIDGE_PORT}"] if _bridge_server is not None else []
    t = GATEWAY.get("tunel") or {}
    if _tunel_server is not None and t.get("ip"):
        out.append(f"{t['ip']}:{BRIDGE_PORT}")
    return out


# ---- estado en vivo (lo que lee la pestana Estado por el plano de control)
def _motores_estado(esperar=True):
    """Cada motor con su estado, base_url y credencial (proveedor + etiqueta
    + 4 ultimos), leidos de su descriptor. Comprobar un motor HTTP cuesta
    hasta 2 s: se sirve lo ultimo leido (de hace <= 10 s) y se vuelve a leer
    en segundo plano; tras una recarga de config se lee en el momento (o,
    con esperar=False, se lanza la lectura y se devuelve None = «comprobando»)."""
    c = _GW_ESTADO_CACHE
    if c["motores"] is None and esperar:
        return _motores_estado_leer()
    if (c["motores"] is None or time.time() - c["t"] >= 10) and not c.get("leyendo"):
        c["leyendo"] = True

        def _bg():
            try:
                _motores_estado_leer()
            except Exception as e:
                log(f"gateway: no se pudieron comprobar los motores ({type(e).__name__}: {e})")
            finally:
                c["leyendo"] = False
        threading.Thread(target=_bg, daemon=True).start()
    return c["motores"]


def _motores_estado_leer():
    c = _GW_ESTADO_CACHE
    out = []
    data, _err = load_engines()
    for mid in engine_ids():
        raw = engine_raw(mid) or {}
        ok, why = engine_status(mid)
        cred = credencial_info(raw.get("credencial_ref"))
        base = (cred or {}).get("base_url_credencial") or raw.get("base_url")
        if cred and not cred["guardada"]:
            ok, why = False, (f"sin credencial: la clave «{cred['activa']}» de {cred['proveedor']} "
                              f"no está guardada")
        out.append({"id": mid, "nombre": raw.get("nombre") or mid, "disponible": bool(ok), "motivo": why,
                    "base_url": base, "credencial": cred,
                    "fallback": raw.get("fallback") if isinstance(raw.get("fallback"), list) else [],
                    "por_defecto": mid == default_motor()})
    c.update(t=time.time(), motores=out)
    return out


def _cadena_respaldo():
    data, _e = load_engines()
    rev = data.get("revision") if isinstance(data.get("revision"), dict) else {}
    jueces = [str((x or {}).get("motor")) for x in (rev.get("orden") or []) if isinstance(x, dict)]
    declarados = {m["id"]: m["fallback"] for m in (_GW_ESTADO_CACHE["motores"] or []) if m["fallback"]}
    return {"por_defecto": default_motor(), "jueces": jueces,
            "nube_a_local": "si la nube cae, lo que pides desde la app pasa al modelo local "
                            f"({default_ollama_model() or 'el de Modelos'})",
            "declarados": declarados}


def gateway_estado():
    """La foto en vivo del gateway (JSON). Todo leido ahora, nada fijo."""
    cola = {"pendientes": 0, "en_curso": 0, "fallidas": 0, "esperando_aprobacion": 0,
            "necesita_decision": 0, "terminadas": 0, "proximo_reintento": None, "error": None}
    try:
        r = cola_resumen()
        cu = r["cuenta"]
        cola.update(pendientes=cu.get("en_cola", 0), en_curso=cu.get("en_curso", 0),
                    fallidas=cu.get("fallida", 0), esperando_aprobacion=cu.get("esperando_aprobacion", 0),
                    necesita_decision=cu.get("necesita_decision", 0), terminadas=cu.get("terminada", 0),
                    proximo_reintento=r.get("proximo_reintento"))
        esp = _cola("SELECT id FROM tareas WHERE estado IN ('esperando_aprobacion', 'necesita_decision') "
                    "ORDER BY actualizado_ts LIMIT 1", fetch=True)
        cola["primera_esperando"] = esp[0]["id"] if esp else None
    except Exception as e:
        cola["error"] = f"{type(e).__name__}: {e}"
    if _cola_err[0]:
        cola["error"] = f"cola.db: {_cola_err[0]}"
    dis = set(load_settings().get("disabled_abilities") or [])
    skills = [{"nombre": name, "activa": f"skill:{Path(folder).name}" not in dis}
              for name, _desc, folder in list_skills()]
    canales = []
    for key, name, _d in CHANNELS:
        on = bool(state.get("mascot")) if key == "mascota" else state.get("bridge") == "corriendo"
        canales.append({"id": key, "nombre": name, "conectado": on})
    lk = GATEWAY.get("lock") or {}
    mot = _motores_estado(esperar=False)
    lv = read_live() or {}
    vivo = ({k: lv.get(k) for k in ("motor", "modelo", "tokens_in", "tokens_out", "elapsed_s", "actualizado")}
            if lv and lv.get("estado") != "terminado" and state.get("current") else None)
    return {
        "gateway": {"vivo": True, "pid": os.getpid(), "carril": LANE, "puerto": BRIDGE_PORT,
                    "escucha": _escucha(), "tunel": GATEWAY.get("tunel"),
                    "inicio": datetime.fromtimestamp(GATEWAY["inicio"]).astimezone().isoformat(timespec="seconds"),
                    "uptime_s": round(time.time() - GATEWAY["inicio"]),
                    "instancia_unica": {"mutex": GATEWAY.get("mutex"), "lockfile": str(LOCK_FILE),
                                        "lock_pid": lk.get("pid")},
                    "token": {"origen": GATEWAY.get("token_origen"), "donde": str(token_file())},
                    "rechazos_recientes": list(GATEWAY["rechazos"])[-5:]},
        "runner": {"estado": state.get("runner"), "tarea": state.get("current"),
                   "motor": state.get("current_motor"), "paso": state.get("paso")},
        "cola": cola,
        "arranque": {"recuperadas": GATEWAY.get("recuperadas") or [], "avisos": GATEWAY.get("avisos_cola") or [],
                     "at": GATEWAY.get("arranque_at")},
        "skills": skills,
        "skills_bridge": skills_resumen(),
        "motores": mot or [],
        "comprobando": ["motores"] if mot is None else [],
        "respaldo": _cadena_respaldo(),
        "cambios_motor": list(_CAMBIOS_MOTOR)[-5:],
        "vivo": vivo,
        "modelos_locales": [m.get("name") for m in (_mdl.get("installed") or [])],
        "canales": canales,
        "recarga": list(_RECARGA["hist"])[-5:],
        "config": {"settings": _huella_archivo(SETTINGS_FILE), "engines": _huella_archivo(ENGINES_FILE)},
        "leido_en": _now_iso(),
    }


# ---- configuracion por tarea + recarga en caliente
def _huella_archivo(p):
    try:
        return hashlib.sha1(Path(p).read_bytes()).hexdigest()[:12]
    except OSError:
        return None


def _cfg_snap():
    return getattr(_CFG_LOCAL, "snap", None)


def _cfg_tomar():
    """La config con la que empieza una tarea (se queda con ella hasta el final)."""
    eng, err = load_engines()
    return {"eng": eng, "eng_err": err, "rt": {}, "settings": load_settings(),
            "huella": {"settings": _huella_archivo(SETTINGS_FILE), "engines": _huella_archivo(ENGINES_FILE),
                       "tomada": _now_iso()}}


def _skills_firma():
    base = HOME_DIR / ".claude" / "skills"
    try:
        return tuple(sorted((d.name, (d / "SKILL.md").stat().st_mtime if (d / "SKILL.md").exists() else 0)
                            for d in base.iterdir() if d.is_dir()))
    except OSError:
        return ()


def _recarga_settings(viejo, nuevo):
    """Aplica en vivo lo que cambio en settings.json, seccion por seccion."""
    cambios = sorted(k for k in set(viejo) | set(nuevo) if viejo.get(k) != nuevo.get(k))
    aplicado, al_reabrir = [], []
    for k in cambios:
        v = nuevo.get(k)
        if k == "mascot" and LANE == "a":
            on = bool(v)
            if on != bool(state.get("mascot")):
                state["mascot"] = on
                _ui_call(lambda on=on: (show_mascot() if on else hide_mascot()))
            aplicado.append(k)
        elif k == "keep_awake":
            state["keep_awake"] = bool(v)
            aplicado.append(k)
        elif k == "auto_update":
            state["auto_update"] = bool(v)
            aplicado.append(k)
        elif k == "guardrail":
            _ui_call(lambda: _espera_refrescar())
            aplicado.append(k)
        elif k == "atajos":
            # Editado a mano: se valida igual que desde Ajustes -> Atajos; lo
            # que no valga se queda como estaba y lo dice en su fila.
            _ui_call(atajos_desde_settings)
            aplicado.append(k)
        elif k in ("default_engine", "motor", "ollama_model", "disabled_abilities", "ability_names"):
            _ui_call(lambda: (_refresh_engine_widgets(), _render_abilities()))
            aplicado.append(k)
        elif k in ("credenciales_activas", "credenciales", "credenciales_topes"):
            # Ajustes -> Claves editado a mano en settings.json: el siguiente uso
            # ya va por la clave activa nueva (resolver_credencial lee en cada uso).
            _GW_ESTADO_CACHE["motores"] = None
            _ui_call(_claves_render)
            aplicado.append(k)
        elif k in ("tunel_remoto",):
            if _bridge_server is not None:
                _tunel_parar()
                _tunel_arrancar()
            aplicado.append(k)
        elif k in ("bridge_port", "lane", "apariencia", "piloto_ctk"):
            al_reabrir.append(k)
        else:
            aplicado.append(k)  # se lee de settings.json cada vez que se usa
    return cambios, aplicado, al_reabrir


def _recarga_una(nombre, path, viejo_txt=None):
    """Una seccion cambio en disco: aplicarla sin reiniciar."""
    ev = {"archivo": nombre, "at": _now_iso(), "cambios": [], "aplicado": [], "al_reabrir": [], "error": None}
    corriendo = state.get("current")
    if nombre == "settings.json":
        try:
            nuevo = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(nuevo, dict):
                raise ValueError("no es un objeto JSON")
        except (OSError, ValueError) as e:
            ev["error"] = f"no se pudo leer ({e}); sigue la config anterior"
            _RECARGA["hist"].append(ev)
            _ui_call(atajos_desde_settings)  # Ajustes -> Atajos lo dice arriba
            return ev
        if _ATAJOS.get("settings_error"):  # ya se puede leer otra vez: quitar el aviso
            _ui_call(atajos_desde_settings)
        viejo = _RECARGA["settings"] or {}
        _RECARGA["settings"] = nuevo
        ev["cambios"], ev["aplicado"], ev["al_reabrir"] = _recarga_settings(viejo, nuevo)
    elif nombre == "engines.json":
        antes = set(_RECARGA["motores"] or [])
        data, err = load_engines()
        if err and "última versión buena" in err:
            ev["error"] = err
        ahora = set(engine_ids())
        _RECARGA["motores"] = sorted(ahora)
        ev["cambios"] = ([f"+{m}" for m in sorted(ahora - antes)] + [f"-{m}" for m in sorted(antes - ahora)]
                         or ["descriptores"])
        _GW_ESTADO_CACHE["motores"] = None
        _ui_call(lambda: (_mot_refresh_list(), _refresh_engine_widgets(), _claves_render()))
        ev["aplicado"] = ["motores"]
    elif nombre == "skills":
        ev["cambios"] = [f"{len(_skills_firma())} skills"]
        _ui_call(lambda: (refresh_skills_ui(), _render_abilities()))
        ev["aplicado"] = ["skills"]
    elif nombre == "skills de Bridge":
        idx = skills_indexar("cambio en skills\\")
        ev["cambios"] = [f"{len(idx['skills'])} cargadas, {len(idx['rechazadas'])} no se cargaron, "
                         f"{len(idx['borradores'])} borradores"]
        _ui_call(_skb_refrescar)
        ev["aplicado"] = ["índice de skills de Bridge"]
    elif nombre == "rules.json":
        _ui_call(_render_rules)
        ev["aplicado"] = ["reglas"]
    elif nombre == "folders.json":
        _ui_call(refresh_folders_ui)
        ev["aplicado"] = ["carpetas"]
    if corriendo:
        ev["tarea_en_curso"] = f"{corriendo} sigue con la config con la que empezó"
    _RECARGA["hist"].append(ev)
    log(f"recarga en caliente: {nombre}"
        + (f" (cambió: {', '.join(ev['cambios'])[:200]})" if ev["cambios"] else "")
        + (f"; aplicado sin reiniciar: {', '.join(ev['aplicado'])[:160]}" if ev["aplicado"] else "")
        + (f"; se aplica al volver a abrir: {', '.join(ev['al_reabrir'])}" if ev["al_reabrir"] else "")
        + (f"; AVISO: {ev['error']}" if ev["error"] else "")
        + (f"; {ev['tarea_en_curso']}" if corriendo else ""))
    return ev


def _recarga_loop(stop_event):
    """Observador de archivos de config (cada 1,5 s, por huella del contenido)."""
    vigilados = {"settings.json": SETTINGS_FILE, "engines.json": ENGINES_FILE,
                 "rules.json": RULES_FILE, "folders.json": FOLDERS_FILE}
    h = _RECARGA["huellas"]
    for n, p in vigilados.items():
        h[n] = _huella_archivo(p)
    h["skills"] = _skills_firma()
    h["skills_bridge"] = _skills_bridge_firma()
    _RECARGA["settings"] = load_settings()
    _RECARGA["motores"] = sorted(engine_ids())
    while not stop_event.wait(1.5):
        try:
            for n, p in vigilados.items():
                nueva = _huella_archivo(p)
                if nueva != h.get(n):
                    h[n] = nueva
                    if _RECARGA["propio"].get(n) == nueva:  # lo acaba de guardar la propia app
                        if n == "settings.json":
                            _RECARGA["settings"] = load_settings()
                        continue
                    _recarga_una(n, p)
            sk = _skills_firma()
            if sk != h.get("skills"):
                h["skills"] = sk
                _recarga_una("skills", None)
            skb = _skills_bridge_firma()
            if skb != h.get("skills_bridge"):
                h["skills_bridge"] = skb
                _recarga_una("skills de Bridge", None)
        except Exception as e:
            log(f"recarga en caliente: ERROR (se sigue con la config anterior): {type(e).__name__}: {e}")


# ---------------------------------------------------------------- servicios
_bridge_server = None
_bridge_thread = None
_tunel_server = None
_runner_stop = None
_runner_thread = None
_share_stop = None
_share_thread = None


def start_bridge():
    global _bridge_server, _bridge_thread
    if _bridge_thread and _bridge_thread.is_alive():
        return True, "el puente ya estaba corriendo"
    secret, origen = gateway_token()
    GATEWAY["token_origen"] = origen
    if not secret:
        state["bridge"] = "error"
        state["bridge_err"] = f"falta el token del plano de control ({origen})"
        log(f"puente ERROR: falta el token del plano de control ({origen})")
        return False, state["bridge_err"]
    BridgeHandler.SECRET = secret
    try:
        # Solo loopback: nunca 0.0.0.0 (la VM entra por el tunel, abajo).
        server = _GatewayServer(("127.0.0.1", BRIDGE_PORT), BridgeHandler)
    except OSError as e:
        state["bridge"] = "error"
        state["bridge_err"] = f"puerto {BRIDGE_PORT} ocupado ({e}) — ¿sigue corriendo pc-server.py?"
        log(f"puente ERROR: puerto {BRIDGE_PORT} ocupado ({e})")
        return False, state["bridge_err"]
    _bridge_server = server
    _bridge_thread = threading.Thread(target=server.serve_forever, daemon=True)
    _bridge_thread.start()
    state["bridge"] = "corriendo"
    state["bridge_err"] = ""
    log(f"puente: escuchando en puerto {BRIDGE_PORT} (plano de control solo en 127.0.0.1, con token)")
    try:
        _tunel_arrancar()
    except Exception as e:
        log(f"gateway: túnel no arrancó ({type(e).__name__}: {e})")
    return True, f"puente corriendo en puerto {BRIDGE_PORT}"


def stop_bridge():
    global _bridge_server, _bridge_thread
    _tunel_parar()
    if _bridge_server is not None:
        try:
            _bridge_server.shutdown()
            _bridge_server.server_close()
        except Exception:
            pass
        _bridge_server = None
    if _bridge_thread is not None:
        _bridge_thread.join(timeout=5)
        _bridge_thread = None
    state["bridge"] = "parado"
    log("puente: parado")


def start_runner():
    global _runner_stop, _runner_thread
    if _runner_thread and _runner_thread.is_alive():
        return True, "el runner ya estaba corriendo"
    _runner_stop = threading.Event()
    _runner_thread = threading.Thread(target=runner_loop, args=(_runner_stop,), daemon=True)
    _runner_thread.start()
    threading.Thread(target=model_lane_loop, args=(_runner_stop,), daemon=True).start()
    state["runner"] = "corriendo"
    log("runner: arrancado")
    return True, "runner corriendo"


def stop_runner():
    global _runner_stop, _runner_thread
    if _runner_stop is not None:
        _runner_stop.set()
    if _runner_thread is not None:
        _runner_thread.join(timeout=10)
        _runner_thread = None
    _runner_stop = None
    state["runner"] = "parado"
    state["current"] = None
    log("runner: parado")


def set_power(on):
    """El boton grande: enciende/apaga puente + runner juntos."""
    if on:
        ok_b, _ = start_bridge()
        ok_r, _ = start_runner()
        state["power"] = state["bridge"] == "corriendo" or state["runner"] == "corriendo"
        if not (ok_b and ok_r):
            log("boton: algo no arranco; revisa el registro")
    else:
        stop_runner()
        stop_bridge()
        state["power"] = False
    return state["power"]


# ---------------------------------------------------------------- pantalla
def _cleanup_old_sessions(days=7):
    """Borra las carpetas de sesiones de pantalla de mas de `days` dias."""
    try:
        now = time.time()
        for d in SCREENS.iterdir():
            if d.is_dir() and len(d.name) >= 15 and d.name[:8].isdigit() \
                    and "-" in d.name:
                if now - d.stat().st_mtime > days * 86400:
                    shutil.rmtree(d, ignore_errors=True)
                    log(f"pantalla: sesion vieja borrada ({d.name})")
    except Exception:
        pass


def _capture_frame():
    """Un fotograma comprimido: se guarda en la carpeta de la sesion actual
    (outbox/screens/AAAAMMDD-HHMMSS/frame-NNNN.jpg) y como latest.jpg."""
    try:
        from PIL import ImageGrab
    except ImportError:
        return None
    folder = state.get("share_folder")
    if not folder:
        return None
    SCREENS.mkdir(parents=True, exist_ok=True)
    try:
        img = ImageGrab.grab()
    except Exception as e:
        log(f"pantalla: no se pudo capturar ({e})")
        return None
    if img.width > 1280:
        img = img.resize((1280, int(img.height * 1280 / img.width)))
    img = img.convert("RGB")
    frame = state.get("share_frame", 0) + 1
    state["share_frame"] = frame
    path = Path(folder) / ("frame-%04d.jpg" % frame)
    img.save(path, "JPEG", quality=45)
    img.save(SCREENS / "latest.jpg", "JPEG", quality=45)
    info = {"at": _now_iso(), "session": Path(folder).name, "frame": frame,
            "size": path.stat().st_size, "w": img.width, "h": img.height}
    (SCREENS / "status.json").write_text(json.dumps(info), encoding="utf-8")
    state["last_frame"] = info["at"]
    return info


def screen_loop(stop_event, interval_s):
    log(f"pantalla: compartiendo en {state.get('share_folder')} "
        f"(fotograma cada {interval_s}s, JPEG 45, max 1280px)")
    count = 0
    while not stop_event.is_set():
        info = _capture_frame()
        if info:
            count += 1
            if count % 10 == 1:
                log(f"pantalla: fotograma {count} ({info['size'] // 1024} KB)")
        stop_event.wait(interval_s)
    log("pantalla: compartiendo detenido")


def start_sharing(interval_s=10):
    global _share_stop, _share_thread
    if _share_thread and _share_thread.is_alive():
        return False
    _cleanup_old_sessions()
    folder = SCREENS / datetime.now().strftime("%Y%m%d-%H%M%S")
    folder.mkdir(parents=True, exist_ok=True)
    state["share_folder"] = str(folder)
    state["share_frame"] = 0
    _share_stop = threading.Event()
    _share_thread = threading.Thread(target=screen_loop,
                                     args=(_share_stop, float(interval_s)),
                                     daemon=True)
    _share_thread.start()
    state["sharing"] = True
    log(f"pantalla: nueva sesion {folder.name} (fotogramas en {folder})")
    return True


def stop_sharing():
    global _share_stop, _share_thread
    if _share_stop is not None:
        _share_stop.set()
    if _share_thread is not None:
        _share_thread.join(timeout=5)
        _share_thread = None
    _share_stop = None
    state["sharing"] = False
    try:
        (SCREENS / "status.json").write_text(
            json.dumps({"on": False, "at": _now_iso()}), encoding="utf-8")
    except OSError:
        pass
    log("pantalla: compartiendo detenido")

