# ---- estados de carga (t-carga-300ms): la regla de los 300 ms en UN sitio.
# Menos de 300 ms: nada (un spinner que parpadea es peor que nada). Más de
# 300 ms: estado de carga (esqueleto en listas, spinner en botones). Más de
# 1 s: el estado dice qué está pasando. Todo lo que espera pasa por Carga.
CARGA_MS, CARGA_DETALLE_MS = 300, 1000
_CARGA_REG = deque(maxlen=200)  # (nombre, ms, patron): para medir y para las pruebas


class Carga:
    def __init__(self, nombre, mostrar=None, detalle=None, ocultar=None, texto=None, widget=None):
        self.nombre, self.t0, self.patron = nombre, time.perf_counter(), "nada"
        self._mostrar, self._detalle, self._ocultar, self.texto = mostrar, detalle, ocultar, texto
        self._w = widget or _root
        self._jobs = []
        self.hecha = False
        try:
            if mostrar:
                self._jobs.append(self._w.after(CARGA_MS, self._paso_mostrar))
            if detalle:
                self._jobs.append(self._w.after(CARGA_DETALLE_MS, self._paso_detalle))
        except Exception:
            pass

    def _paso_mostrar(self):
        if not self.hecha:
            self.patron = "carga"
            try:
                self._mostrar()
            except Exception as e:
                log(f"carga: {self.nombre}: no se pudo mostrar ({type(e).__name__}: {e})")

    def _paso_detalle(self):
        if not self.hecha:
            self.patron = "carga+detalle"
            try:
                self._detalle(self.texto)
            except Exception as e:
                log(f"carga: {self.nombre}: no se pudo detallar ({type(e).__name__}: {e})")

    def fin(self):
        if self.hecha:
            return
        self.hecha = True
        for j in self._jobs:
            try:
                self._w.after_cancel(j)
            except Exception:
                pass
        if self.patron != "nada" and self._ocultar:
            try:
                self._ocultar()
            except Exception:
                pass
        ms = round((time.perf_counter() - self.t0) * 1000)
        _CARGA_REG.append((self.nombre, ms, self.patron))
        if ms >= CARGA_MS:
            log(f"carga: {self.nombre}: {ms} ms -> {self.patron}")


def con_carga(nombre, trabajo, al_terminar, **kw):
    """Corre trabajo() en un hilo con su Carga; al_terminar(resultado) en la ventana."""
    c = Carga(nombre, **kw)

    def _hilo():
        try:
            r = trabajo()
        except Exception as e:
            r = e
        _ui_call(lambda: (c.fin(), al_terminar(r)))
    threading.Thread(target=_hilo, daemon=True).start()
    return c


def boton_largo(btn, nombre, trabajo, al_terminar, texto="Trabajando"):
    """Spinner en el boton: se desactiva AL MOMENTO (feedback < 200 ms y no se
    puede pulsar dos veces); a los 300 ms gira; a 1 s dice que hace."""
    if getattr(btn, "_ocupado", False):
        return None
    btn._ocupado = True
    original = btn.cget("text")
    btn.configure(state="disabled")
    giro = {"i": 0, "job": None, "txt": texto}

    def _girar():
        try:
            btn.configure(text=f"{_SPIN[giro['i'] % len(_SPIN)]} {giro['txt']}…")
            giro["i"] += 1
            giro["job"] = btn.after(100, _girar)
        except Exception:
            pass

    def _ocultar():
        if giro["job"]:
            btn.after_cancel(giro["job"])

    def _fin(r):
        btn._ocupado = False
        try:
            btn.configure(text=original, state="normal")
        except Exception:
            pass
        al_terminar(r)
    return con_carga(nombre, trabajo, _fin, mostrar=_girar, ocultar=_ocultar, widget=btn,
                     detalle=lambda t: giro.__setitem__("txt", t), texto=texto)


def esqueleto(parent, filas=4, alto=34, bg=None):
    """Filas grises con la geometria de una lista (no un spinner a pantalla
    completa). Devuelve el marco: quien carga lo quita al llegar los datos."""
    gris = _tema_fijo("seg_bg") or "#E8E8ED"
    f = tk.Frame(parent, bg=bg or THEME["card"])
    for i in range(filas):
        r = tk.Frame(f, bg=bg or THEME["card"], height=S(alto))
        r.pack(fill="x", padx=16, pady=(6, 0))
        r.pack_propagate(False)
        tk.Frame(r, bg=gris, height=S(12), width=S(220 - 30 * (i % 3))).pack(anchor="w", pady=(2, 4))
        tk.Frame(r, bg=gris, height=S(9), width=S(340 - 40 * (i % 2))).pack(anchor="w")
    f._esqueleto = True
    return f


def check_updates_boton(btn):
    """«Buscar actualizaciones» con spinner y sin doble clic."""
    def _fin(remote):
        if isinstance(remote, Exception):
            log(f"actualizaciones: no se pudo comprobar ({type(remote).__name__})")
            return
        state["update_checked"] = True
        if remote:
            state["update_available"] = remote
            log(f"actualizaciones: hay una nueva version v{remote}")
        else:
            log("actualizaciones: estás en la última versión")
    return boton_largo(btn, "buscar actualizaciones", check_update_available, _fin, texto="Buscando")


def check_updates_ui():
    def _run():
        remote = check_update_available()
        state["update_checked"] = True
        if remote:
            state["update_available"] = remote
            log(f"actualizaciones: hay una nueva version v{remote}")
        else:
            log("actualizaciones: estás en la última versión")
    threading.Thread(target=_run, daemon=True).start()


def do_update_ui():
    version = state["update_available"]
    if not version:
        return
    if not messagebox.askyesno(
            "Actualizar Growi Bridge",
            f"Se descargará la versión v{version} y la app se reiniciará. ¿Seguir?"):
        return
    if not download_update(version):
        messagebox.showerror("Actualizar", "No se pudo descargar la actualización.")
        return
    log(f"actualizaciones: v{version} descargada, reiniciando...")
    try:
        subprocess.Popen(["cmd", "/c", "actualizar.bat"], cwd=str(APP_DIR))
    except Exception as e:
        messagebox.showerror("Actualizar", f"No se pudo lanzar el actualizador: {e}")
        return
    quit_app()


def open_folder(path):
    try:
        os.startfile(str(path))
    except Exception as e:
        log(f"no se pudo abrir {path}: {e}")


# ---------------------------------------------------------------- mascota
_mascot = {"win": None, "label": None, "sets": {}, "animating": False,
           "drag": None, "frame_idx": 0, "last_tasks": 0, "idle_next": 0}


def _mascot_sets():
    """Carga los tres juegos de animacion (idle / working / wave) de
    mascot/*.png. Cada juego son 16 fotogramas de 256x256, con fondo
    magenta puro (la ventana lo hace transparente)."""
    if _mascot["sets"]:
        return _mascot["sets"]
    sets = {}
    for name in ("idle", "working", "wave"):
        frames = []
        try:
            for p in sorted(MASCOT_DIR.glob(f"{name}-*.png")):
                frames.append(ImageTk.PhotoImage(
                    Image.open(p).resize((MASCOT_SIZE, MASCOT_SIZE), Image.LANCZOS)))
        except Exception:
            frames = []
        sets[name] = frames
    _mascot["sets"] = sets
    return sets


# ---- mascota: 4 estados + reglas anti-molestia + memoria minima
# (t-lote-mascota-040 = t-mascota-estados + t-mascota-memoria-minima).
# Cada estado es UN fotograma de postura que se queda hasta que el estado
# cambia (nada de animaciones largas ni sonido). Las posturas se derivan de
# los fotogramas reales (idle-01) con PIL: el arte definitivo es otra tarea.
# Las 6 reglas (numeradas): (1) max. una intervencion por evento; (2) nunca
# un pop-up no pedido: reacciona, no interrumpe; (3) nunca dos veces seguidas
# lo mismo (memoria); (4) lo malo no se celebra ni se dramatiza; (5) todo
# estado tiene salida («Descansar») y toda animacion termina sola; (6) la
# mascota no es el sistema de notificaciones: los botones viven en la pagina.
MASCOTA_MEM = APP_DIR / "mascota-memoria.json"
MASCOTA_VALIDACION = APP_DIR / "mascota-validacion.jsonl"
_MASC = {"posturas": None, "fallo_hasta": 0.0, "eventos": {}, "estado_visto": None, "saludo_at": 0.0}


def _masc_mem():
    try:
        d = json.loads(MASCOTA_MEM.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _masc_mem_set(**kw):
    d = _masc_mem()
    d.update(kw)
    try:
        MASCOTA_MEM.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    except OSError as e:
        log(f"mascota: no se pudo guardar su memoria ({e})")
    return d


def mascota_posturas_pil():
    """{estado: PIL.Image} derivadas de idle-01 (256 px, fondo magenta)."""
    from PIL import Image, ImageDraw
    base = Image.open(MASCOT_DIR / "idle-01.png").convert("RGB")
    W_, H_ = base.size
    mag = (255, 0, 255)

    def lienzo():
        return Image.new("RGB", (W_, H_), mag)

    def sin_fondo(im):
        a = Image.new("L", im.size, 0)
        px, pa = im.load(), a.load()
        for y in range(im.size[1]):
            for x in range(im.size[0]):
                r, g, b = px[x, y][:3]
                pa[x, y] = 0 if (r > 200 and b > 200 and g < 80) else 255
        return a

    out = {}
    # proxy caido: impermeable amarillo (el jersey negro se vuelve amarillo) y algo encogida
    imp = base.copy()
    px = imp.load()
    for y in range(int(H_ * 0.33), int(H_ * 0.80)):
        for x in range(W_):
            r, g, b = px[x, y]
            if r < 70 and g < 70 and b < 70:
                k = (r + g + b) / 210
                px[x, y] = (int(235 * (0.75 + k)), int(190 * (0.75 + k)), int(40 * (0.75 + k)))
    peq = imp.resize((int(W_ * 0.88), int(H_ * 0.88)))
    c = lienzo()
    c.paste(peq, ((W_ - peq.size[0]) // 2, H_ - peq.size[1]), sin_fondo(peq))
    out["proxy_caido"] = c
    # sin internet: dormida de lado, con una manta
    lado = base.rotate(90, expand=True, fillcolor=mag).resize((int(W_ * 0.78), int(H_ * 0.78)))
    c = lienzo()
    c.paste(lado, ((W_ - lado.size[0]) // 2, H_ - lado.size[1] - 4), sin_fondo(lado))
    d = ImageDraw.Draw(c)
    # la manta tapa el cuerpo (a la derecha); la cabeza (a la izquierda) queda fuera
    d.rounded_rectangle((int(W_ * 0.40), int(H_ * 0.50), int(W_ * 0.94), int(H_ * 0.97)), radius=22,
                        fill=(70, 110, 170))
    d.rectangle((int(W_ * 0.40), int(H_ * 0.50), int(W_ * 0.94), int(H_ * 0.56)), fill=(95, 135, 195))
    try:
        from PIL import ImageFont
        fuentes = [ImageFont.truetype("segoeuib.ttf", t) for t in (26, 34, 42)]
    except Exception:
        fuentes = [None, None, None]
    for (x, y), f in zip(((0.30, 0.34), (0.40, 0.22), (0.52, 0.08)), fuentes):
        d.text((int(W_ * x), int(H_ * y)), "z", fill=(110, 110, 150), font=f)
    out["sin_internet"] = c
    # esperando aprobacion: «te toca a ti», una mano levantada (distintivo) y sin palabras
    c = base.copy()
    d = ImageDraw.Draw(c)
    cx, cy, rr = int(W_ * 0.82), int(H_ * 0.18), int(W_ * 0.12)
    d.ellipse((cx - rr, cy - rr, cx + rr, cy + rr), fill=(255, 255, 255), outline=(0, 122, 255), width=4)
    d.rectangle((cx - 10, cy - 4, cx + 10, cy + 16), fill=(240, 205, 170))  # palma
    for i, dx in enumerate((-9, -3, 3, 9)):
        d.rectangle((cx + dx - 2, cy - 18 + abs(dx) // 2, cx + dx + 2, cy - 2), fill=(240, 205, 170))
    out["esperando"] = c
    # tarea fallida: baja la cabeza (se inclina hacia delante), una vez
    baja = base.resize((W_, int(H_ * 0.93))).rotate(-7, center=(W_ // 2, int(H_ * 0.93)), fillcolor=mag)
    c = lienzo()
    c.paste(baja, (0, H_ - baja.size[1]), sin_fondo(baja))
    out["fallo"] = c
    return out


def _masc_postura(nombre):
    """PhotoImage de la postura (en caché)."""
    if _MASC["posturas"] is None:
        try:
            from PIL import ImageTk
            _MASC["posturas"] = {k: ImageTk.PhotoImage(v.resize((MASCOT_SIZE, MASCOT_SIZE)))
                                 for k, v in mascota_posturas_pil().items()}
        except Exception as e:
            log(f"mascota: no se pudieron preparar las posturas ({type(e).__name__}: {e})")
            _MASC["posturas"] = {}
    return _MASC["posturas"].get(nombre)


def mascota_estado():
    """El estado que manda ahora (o None = reposo normal). Prioridad: el
    fallo (un momento), sin internet, proxy caido, esperando aprobacion."""
    if _masc_mem().get("descansar_hasta", 0) > time.time():
        return None  # regla 5: «Descansar» apaga los estados
    if time.time() < _MASC["fallo_hasta"]:
        return "fallo"
    rows = _AV.get("rows") or {}
    if (rows.get("internet") or {}).get("estado") == "falla":
        return "sin_internet"
    if (rows.get("proxy") or {}).get("estado") == "falla" or _IPX.get("proxy_caido"):
        return "proxy_caido"
    if ((_ESP.get("dato") or {}).get("n") or 0) > 0:  # tareas retenidas esperando tu aprobación
        return "esperando"
    return None


def mascota_evento(tipo, clave=None):
    """Un evento -> como mucho UNA intervencion (regla 1). tipo: 'fallo'."""
    k = f"{tipo}:{clave}"
    if k in _MASC["eventos"]:
        return False
    _MASC["eventos"][k] = time.time()
    if tipo == "fallo":
        _MASC["fallo_hasta"] = time.time() + 2.5  # baja la cabeza una vez y vuelve al reposo
        log(f"mascota: baja la cabeza una vez ({clave}); el reporte vive en la fila de la tarea")
    return True


def mascota_decir(texto, variante=None):
    """Regla 3: nunca dos veces seguidas lo mismo. Si lo ultimo dicho es
    igual, usa la variante corta o se calla. Lo dicho queda en disco."""
    mem = _masc_mem()
    if mem.get("ultimo_dicho") == texto:
        if not variante or mem.get("ultimo_dicho_variante") == variante:
            log(f"mascota: se calla (ya dijo «{texto[:40]}»)")
            return None
        texto_final = variante
        _masc_mem_set(ultimo_dicho_variante=variante, ultimo_dicho_at=_now_iso())
    else:
        texto_final = texto
        _masc_mem_set(ultimo_dicho=texto, ultimo_dicho_variante=None, ultimo_dicho_at=_now_iso())
    toast(texto_final)
    return texto_final


def mascota_tarea_aprobada():
    """Solo la primera tarea del dia se celebra; los hitos reales (7 dias
    seguidos, 100 tareas) una vez, pequeños, en el aviso de la tarea."""
    mem = _masc_mem()
    hoy = datetime.now().strftime("%Y-%m-%d")
    n = int(load_settings().get("aprobadas_total") or 0)
    dias = sorted(set(mem.get("dias_con_tarea") or []) | {hoy})[-30:]
    racha, d0 = 1, datetime.now().date()
    while (d0 - timedelta(days=racha)).isoformat() in dias:
        racha += 1
    hitos = set(mem.get("hitos") or [])
    nuevo = None
    if racha >= 7 and "racha7" not in hitos:
        nuevo = ("racha7", "7 días seguidos usando Bridge")
    elif n >= 100 and n % 100 == 0 and f"tareas{n}" not in hitos:
        nuevo = (f"tareas{n}", f"{n} tareas aprobadas")
    _masc_mem_set(dias_con_tarea=dias)
    if mem.get("ultimo_celebrado") == f"primera:{hoy}" and not nuevo:
        log("mascota: tarea aprobada; no es la primera del día: no se celebra")
        return None
    if nuevo:
        _masc_mem_set(hitos=sorted(hitos | {nuevo[0]}), ultimo_celebrado=f"hito:{nuevo[0]}")
        motivo = nuevo[1]
    else:
        _masc_mem_set(ultimo_celebrado=f"primera:{hoy}")
        motivo = "primera tarea del día"
    try:
        _mascot_play("wave")
    except Exception:
        pass
    log(f"mascota: celebra ({motivo})")
    return motivo


def mascota_descansar(horas=1):
    _masc_mem_set(descansar_hasta=time.time() + horas * 3600)
    log(f"mascota: descansa {horas} h (sin estados ni celebraciones)")


def mascota_validacion_ui():
    """«¿Te molestó alguna vez?»: la respuesta queda en mascota-validacion.jsonl."""
    r = messagebox.askyesnocancel("La mascota", "Esta semana, ¿la mascota te molestó alguna vez?\n\n"
                                                "Sí = se recortan sus estados. No = se quedan.")
    if r is None:
        return
    try:
        with open(MASCOTA_VALIDACION, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"at": _now_iso(), "molesto": bool(r),
                                 "inicio_prueba": _masc_mem().get("validacion_desde")}, ensure_ascii=False) + "\n")
    except OSError as e:
        log(f"mascota: no se pudo guardar la respuesta ({e})")
    log(f"mascota: validación: {'SÍ molestó: recortar estados' if r else 'no molestó'}")


def _mascot_play(name):
    """Reproduce un juego de animacion una vez (saludo, celebracion)."""
    frames = _mascot_sets().get(name) or []
    label = _mascot["label"]
    if not frames or label is None or not movimiento_permitido():  # sin movimiento: fotograma fijo
        return
    _mascot["animating"] = True
    idx = [0]

    def _step():
        if idx[0] >= len(frames) * 2:
            _mascot["animating"] = False
            return
        try:
            label.config(image=frames[idx[0] % len(frames)])
        except Exception:
            pass
        idx[0] += 1
        try:
            _root.after(90, _step)
        except Exception:
            _mascot["animating"] = False

    _step()


def _mascot_micro():
    """Un respiro corto: 6 fotogramas del juego idle, una sola vez. Es lo
    unico que se mueve cuando nadie toca a la mascota."""
    frames = _mascot_sets().get("idle") or []
    label = _mascot["label"]
    if not frames or label is None or _mascot["animating"] or not movimiento_permitido():
        return
    _mascot["animating"] = True
    idx = [0]

    def _step():
        if idx[0] >= 6:
            _mascot["animating"] = False
            try:
                label.config(image=frames[0])
            except Exception:
                pass
            return
        try:
            label.config(image=frames[idx[0] % len(frames)])
        except Exception:
            pass
        idx[0] += 1
        try:
            _root.after(120, _step)
        except Exception:
            _mascot["animating"] = False

    _step()


def _mascot_loop():
    """La mascota descansa QUIETA casi todo el tiempo: solo se mueve un
    poco cada cierto rato (un respiro corto), y anima de verdad cuando algo
    pasa (clic, arrastre, tarea terminada) o mientras Claude trabaja."""
    win = _mascot["win"]
    if win is None:
        return
    est = None if _mascot["animating"] else mascota_estado()
    if est != _MASC["estado_visto"]:
        _MASC["estado_visto"] = est
        log(f"mascota: postura {est or 'reposo'}")
    if est and _masc_postura(est) is not None:
        try:  # un fotograma de postura que se queda hasta que el estado cambia
            _mascot["label"].config(image=_masc_postura(est))
        except Exception:
            pass
    elif not _mascot["animating"]:
        # Ya no saluda por cada tarea: solo celebra los hitos (ver
        # _celebrate_milestone, que lo llama al aprobarse una tarea).
        _mascot["last_tasks"] = state["tasks_done"]
        if state.get("current"):
            # Trabajando: el loop de tecleo, continuo (tiene sentido).
            frames = _mascot_sets().get("working") or []
            if frames and movimiento_permitido():
                _mascot["frame_idx"] = (_mascot["frame_idx"] + 1) % len(frames)
                try:
                    _mascot["label"].config(image=frames[_mascot["frame_idx"]])
                except Exception:
                    pass
        else:
            # Descansando: quieto, con un respiro corto cada 8-15 s.
            now = time.time()
            if now >= _mascot.get("idle_next", 0):
                _mascot["idle_next"] = now + random.uniform(8, 15)
                _mascot_micro()
            else:
                try:
                    frames = _mascot_sets().get("idle") or []
                    if frames:
                        _mascot["label"].config(image=frames[0])
                except Exception:
                    pass
    try:
        _root.after(120, _mascot_loop)
    except Exception:
        pass


def _mascot_pos():
    sw = _root.winfo_screenwidth()
    sh = _root.winfo_screenheight()
    return sw - (MASCOT_SIZE + S(20)), sh - (MASCOT_SIZE + S(20))



def show_mascot():
    if _root is None or _mascot["win"] is not None:
        return
    if not TRAY_OK or not PHOTO.is_file():
        log("mascota: falta la foto (growi.png)")
        return
    win = tk.Toplevel(_root)
    win.overrideredirect(True)
    win.configure(bg=MASCOT_MAGIC)  # todo pixel fuera de la imagen es magenta = transparente
    win.attributes("-topmost", True)
    try:
        win.attributes("-transparentcolor", MASCOT_MAGIC)
    except Exception:
        pass
    x, y = _mascot_pos()
    win.geometry(f"{MASCOT_SIZE}x{MASCOT_SIZE}+{x}+{y}")
    try:
        first = MASCOT_DIR / "idle-01.png"
        img_path = first if first.is_file() else PHOTO
        img = Image.open(img_path).resize((MASCOT_SIZE, MASCOT_SIZE), Image.LANCZOS)
        photo = ImageTk.PhotoImage(img)
    except Exception:
        win.destroy()
        return
    label = tk.Label(win, image=photo, bg=MASCOT_MAGIC, bd=0, highlightthickness=0)
    label.image = photo
    label.pack(fill="both", expand=True)
    win._photo = photo
    _mascot["win"] = win
    _mascot["label"] = label
    _mascot["idle_next"] = time.time() + 5
    # Arrastrar archivos sobre la mascota: los copia al Inbox (tkinterdnd2).
    if DND_OK:
        try:
            label.drop_target_register(DND_FILES)
            label.dnd_bind("<<DropEnter>>", _mascot_drag_enter)
            label.dnd_bind("<<DropPosition>>", _mascot_drag_position)
            label.dnd_bind("<<DropLeave>>", _mascot_drag_leave)
            label.dnd_bind("<<Drop>>", _mascot_drop)
        except Exception as e:
            log(f"mascota: no se pudo activar el arrastre ({e})")

    def _press(e):
        _mascot["drag"] = (e.x_root, e.y_root, win.winfo_x(), win.winfo_y(), False)

    def _move(e):
        d = _mascot["drag"]
        if not d:
            return
        dx = e.x_root - d[0]
        dy = e.y_root - d[1]
        if abs(dx) + abs(dy) > 5:
            _mascot["drag"] = (d[0], d[1], d[2], d[3], True)
            win.geometry(f"{MASCOT_SIZE}x{MASCOT_SIZE}+{d[2] + dx}+{d[3] + dy}")

    def _release(e):
        d = _mascot["drag"]
        _mascot["drag"] = None
        if d and d[4]:
            # al soltar, la ventana vuelve al tamano de la imagen en el sitio soltado
            try:
                win.geometry(f"{MASCOT_SIZE}x{MASCOT_SIZE}+{win.winfo_x()}+{win.winfo_y()}")
            except Exception:
                pass
        if d and not d[4]:
            on_mascot_click()

    label.bind("<ButtonPress-1>", _press)
    label.bind("<B1-Motion>", _move)
    label.bind("<ButtonRelease-1>", _release)
    label.bind("<Button-3>", _mascot_menu)
    log("mascota: Growi está en la esquina inferior derecha")
    if not _masc_mem().get("validacion_desde"):  # la semana de prueba de los estados empieza hoy
        _masc_mem_set(validacion_desde=_now_iso())
    _mascot["last_tasks"] = state["tasks_done"]
    _root.after(120, _mascot_loop)
    _root.after(700, lambda: _mascot_play("wave"))  # saludo al arrancar


def _mascot_menu(event):
    """Clic derecho en la mascota: lo que se le puede pedir sin abrir la
    ventana."""
    menu = tk.Menu(_root, tearoff=0, font=(FONT, 10))
    menu.add_command(label="Escribirle a Growi", command=open_prompt_box)
    menu.add_command(label="Abrir Growi Bridge", command=show_window)
    menu.add_command(label="Buscar acciones",
                     accelerator=_atajo_compacto(atajo_actual("abrir_paleta", "paleta")),
                     command=lambda: (show_window(), _open_palette()))
    menu.add_separator()
    menu.add_command(label="Descansar 1 hora", command=mascota_descansar)
    menu.add_command(label="¿Te molestó la mascota?", command=mascota_validacion_ui)
    menu.add_command(label="Ocultar la mascota", command=toggle_mascot)
    try:
        menu.tk_popup(event.x_root, event.y_root)
    finally:
        menu.grab_release()


def on_mascot_click():
    win = _mascot["win"]
    label = _mascot["label"]
    if win is None or label is None or _mascot["animating"]:
        return
    # Clic = saludo corto, no la cajita (regla 2: reacciona, no interrumpe).
    # Si acaba de saludar, nada. La cajita: clic derecho → «Escribirle a Growi».
    if time.time() - _MASC["saludo_at"] < 30:
        log("mascota: clic; acaba de saludar: nada")
        return
    _MASC["saludo_at"] = time.time()
    _mascot_play("wave")
    log("mascota: clic → saludo (sin abrir la cajita)")

def _big_file_dialog(name, size_mb):
    """Pregunta si de verdad se quiere copiar un archivo grande (>200 MB).
    Devuelve True si se copia, False si se cancela. El boton "No mostrar
    durante 30 min" silencia el aviso media hora (se guarda en settings)."""
    result = {"ok": False}
    box = tk.Toplevel(_root)
    box.title("Archivo grande")
    box.attributes("-topmost", True)
    box.configure(bg=THEME["bg"])
    x = max(0, _root.winfo_x() + S(100))
    y = max(0, _root.winfo_y() + S(100))
    box.geometry(f"{S(360)}x{S(190)}+{x}+{y}")
    tk.Label(box, text=f"'{name}' pesa {size_mb:.0f} MB.",
             font=(FONT, 11, "bold"), bg=THEME["bg"], fg=THEME["text"],
             wraplength=S(320), justify="left").pack(padx=16, pady=(14, 2))
    tk.Label(box, text="Copiarlo a Growi Bridge puede tardar un rato en "
             "sincronizarse. ¿Seguro que quieres copiarlo?",
             font=(FONT, 10), bg=THEME["bg"], fg=THEME["muted"],
             wraplength=S(320), justify="left").pack(padx=16, pady=(0, 10))
    row = tk.Frame(box, bg=THEME["bg"])
    row.pack(pady=4)
    tk.Button(row, text="Sí, copiar", bg=THEME["blue"], fg="white",
              borderwidth=0, font=(FONT, 10, "bold"),
              command=lambda: (result.__setitem__("ok", True), box.destroy())
              ).pack(side="left", padx=4)
    tk.Button(row, text="Cancelar", bg="#E8E8ED", fg=THEME["text"],
              borderwidth=0, font=(FONT, 10),
              command=box.destroy).pack(side="left", padx=4)
    tk.Button(box, text="No mostrar durante 30 min", bg=THEME["bg"],
              fg=THEME["muted"], borderwidth=0, font=(FONT, 9),
              command=lambda: (_snooze_big_file_warn(), box.destroy())
              ).pack(pady=4)
    box.grab_set()
    _root.wait_window(box)
    return result["ok"]


def _snooze_big_file_warn():
    s = load_settings()
    s["big_file_warn_snooze_until"] = time.time() + 30 * 60
    save_settings(s)
    log("mascota: aviso de archivo grande silenciado 30 min")


def _big_file_warn_snoozed():
    try:
        return time.time() < float(load_settings().get(
            "big_file_warn_snooze_until", 0))
    except (TypeError, ValueError):
        return False


def _copy_dropped_file(path):
    """Copia un archivo soltado sobre la mascota al Inbox del puente
    (llega a Growi por la sincronizacion). En un hilo para no congelar
    la ventana."""
    def _run():
        try:
            size = os.path.getsize(path)
            name = os.path.basename(path)
            dest = INBOX / name
            i = 1
            while dest.exists():
                stem, ext = os.path.splitext(name)
                dest = INBOX / f"{stem} ({i}){ext}"
                i += 1
            shutil.copy2(path, dest)
            log(f"mascota: '{dest.name}' copiado al Inbox "
                f"({size // (1024 * 1024)} MB) — llega a Growi por el puente")
            try:
                _root.after(0, lambda: _mascot_play("wave"))
            except Exception:
                pass
        except Exception as e:
            log(f"mascota: no se pudo copiar '{path}' ({e})")

    threading.Thread(target=_run, daemon=True).start()


def _mascot_drop(event):
    """Archivo(s) soltados sobre la mascota: Growi levanta la mano para
    recibirlos y se copian al Inbox. Mas de 200 MB: aviso con opcion de
    silenciarlo 30 min."""
    try:
        _mascot_play("wave")
    except Exception:
        pass
    data = (event.data or "").strip()
    if not data:
        return
    # tkinterdnd2 entrega las rutas entre llaves cuando tienen espacios.
    paths = []
    for part in re.findall(r"\{([^}]+)\}|(\S+)", data):
        p = part[0] or part[1]
        if p:
            paths.append(p)
    for p in paths:
        try:
            if not os.path.isfile(p):
                continue
            size = os.path.getsize(p)
            name = os.path.basename(p)
            if size > 200 * 1024 * 1024 and not _big_file_warn_snoozed():
                if not _big_file_dialog(name, size / (1024 * 1024)):
                    log(f"mascota: copia de '{name}' cancelada por el usuario")
                    continue
            _copy_dropped_file(p)
        except Exception as e:
            log(f"mascota: no se pudo procesar '{p}' ({e})")


def _mascot_drag_enter(event):
    """Un archivo entra sobre la mascota: Growi levanta la mano."""
    try:
        _mascot_play("wave")
    except Exception:
        pass


def _mascot_drag_position(event):
    """Mientras el archivo se mueve sobre la mascota, Growi se inclina un
    poco hacia el cursor, como buscandolo."""
    win = _mascot["win"]
    if win is None:
        return
    try:
        cx = win.winfo_x() + win.winfo_width() // 2
        cy = win.winfo_y() + win.winfo_height() // 2
        dx = max(-8, min(8, (event.x_root - cx) // 12))
        dy = max(-8, min(8, (event.y_root - cy) // 12))
        base_x, base_y = _mascot_pos()
        win.geometry(f"{MASCOT_SIZE}x{MASCOT_SIZE}+{base_x + dx}+{base_y + dy}")
    except Exception:
        pass


def _mascot_drag_leave(event):
    """El archivo se aleja: Growi vuelve a su sitio."""
    win = _mascot["win"]
    if win is None:
        return
    try:
        x, y = _mascot_pos()
        win.geometry(f"{MASCOT_SIZE}x{MASCOT_SIZE}+{x}+{y}")
    except Exception:
        pass



def open_prompt_box():
    """Cajita para escribirle a Growi (estilo Mac: avatar, campo con borde,
    boton de acento). El mensaje llega a Growi por el puente."""
    win = _mascot["win"]
    if win is None:
        return
    box = tk.Toplevel(_root)
    box.title("Escríbeme")
    box.attributes("-topmost", True)
    box.configure(bg=THEME["bg"])
    box.resizable(False, False)
    x = max(0, win.winfo_x() - S(220))
    y = max(0, win.winfo_y() - S(190))
    box.geometry(f"{S(380)}x{S(230)}+{x}+{y}")
    # Cabecera: avatar + saludo.
    head = tk.Frame(box, bg=THEME["bg"])
    head.pack(fill="x", padx=18, pady=(16, 4))
    try:
        img = Image.open(PHOTO).resize((S(40), S(40)), Image.LANCZOS)
        photo = ImageTk.PhotoImage(img)
        tk.Label(head, image=photo, bg=THEME["bg"]).pack(side="left")
        head.image = photo
    except Exception:
        pass
    tk.Label(head, text="¡Hola! ¿Qué necesitas?", font=(FONT, 13, "bold"),
             bg=THEME["bg"], fg=THEME["text"]).pack(side="left", padx=(10, 0))
    # Campo con borde (como los campos de la app).
    field = tk.Frame(box, bg=THEME["line"], padx=1, pady=1)
    field.pack(fill="x", padx=18, pady=10)
    entry = tk.Entry(field, font=(FONT, 11), bg="#FFFFFF", fg=THEME["text"],
                     insertbackground=THEME["text"], borderwidth=0,
                     highlightthickness=0)
    entry.pack(fill="x", ipady=8, padx=8)
    entry.focus_set()
    status = tk.Label(box, text="", font=(FONT, 9), fg=THEME["green_text"],
                      bg=THEME["bg"])
    status.pack()

    def _send(_e=None):
        text = entry.get().strip()
        if not text:
            return
        if mem_comando_ui(text, "mascota"):  # «/nuevo» y «recuerda esto» se hacen aquí, con confirmación
            entry.delete(0, "end")
            status.config(text="Memoria: mira la confirmación")
            return
        MESSAGES.mkdir(parents=True, exist_ok=True)
        name = datetime.now().strftime("%Y%m%d-%H%M%S") + ".txt"
        (MESSAGES / name).write_text(text, encoding="utf-8")
        log(f"mascota: mensaje enviado a Growi ({name})")
        entry.delete(0, "end")
        status.config(text="✓ Enviado, te respondo en el chat")

    entry.bind("<Return>", _send)
    row = tk.Frame(box, bg=THEME["bg"])
    row.pack(pady=(6, 4))
    ttk.Button(row, text="Enviar a Growi", style="Accent.TButton",
               command=_send).pack(side="left", padx=4)
    ttk.Button(row, text="Cerrar", command=box.destroy).pack(side="left", padx=4)
    tk.Label(box, text="Llega a Growi por el puente y te responde en el chat.",
             font=(FONT, 9), fg=THEME["muted"], bg=THEME["bg"]).pack(pady=(2, 10))


def hide_mascot():
    win = _mascot["win"]
    if win is not None:
        try:
            win.destroy()
        except Exception:
            pass
    _mascot["win"] = None
    _mascot["label"] = None
