def show_window():
    """Vuelve la ventana al frente: sirve igual si estaba escondida en la
    bandeja (withdraw) o minimizada (iconify)."""
    if _root is None:
        return
    try:
        _root.deiconify()
        _root.lift()
        # Un instante encima de todo: lift() solo no gana a la ventana que
        # tiene el foco ahora (p. ej. el navegador al hacer doble clic).
        _root.attributes("-topmost", True)
        _root.after(200, lambda: _root.attributes("-topmost", False))
        _root.focus_force()
    except Exception:
        pass


def _a_la_bandeja():
    """Carril A con icono en la bandeja: esconder es withdraw() (sin ventana,
    sin boton en la barra de tareas, sin Alt+Tab). Sin icono no se esconde
    del todo (no habria por donde volver) y el carril B queda como estaba:
    los dos minimizan a la barra de tareas (iconify)."""
    return LANE == "a" and _tray_icon is not None


def hide_to_tray(toast=False):
    """Esconde la ventana en la bandeja (la mascota sigue visible en su
    esquina; puente, runner y proxy siguen igual). El aviso de que sigue
    corriendo sale solo si lo pide la X con el ajuste «minimizar»
    (toast=True) y solo la primera vez; Ctrl+Alt+G nunca avisa."""
    if _root is None:
        return
    try:
        if _a_la_bandeja():
            _root.withdraw()
        else:
            _root.iconify()
    except Exception:
        pass
    log("ventana escondida en la bandeja (el programa sigue corriendo)" if _a_la_bandeja()
        else "ventana minimizada (el programa sigue corriendo)")
    if not toast or _tray_icon is None:
        return
    s = load_settings()
    if s.get("close_toast_shown"):
        return
    s["close_toast_shown"] = True
    save_settings(s)
    try:
        _tray_icon.notify("Sigo en la bandeja. Salir: clic derecho", "Growi Bridge")
    except Exception:
        pass


CLOSE_MODES = (("ask", "Preguntarme"), ("minimize", "Minimizar a la bandeja"),
               ("quit", "Salir del todo"))


def close_mode():
    """Lo que hace la X ahora: 'minimize', 'quit' o 'ask'. Sin eleccion
    guardada, el carril A se queda en la bandeja (por defecto) y el B
    pregunta, como siempre. Se lee en cada clic: el cambio en Ajustes vale
    al momento."""
    m = load_settings().get("on_close")
    if m in ("minimize", "quit", "ask"):
        return m
    return "minimize" if LANE == "a" else "ask"


def _set_close_mode(mode):
    s = load_settings()
    s["on_close"] = mode  # "ask" tambien se guarda: sin clave vale el defecto
    save_settings(s)
    var = _widgets.get("close_var")
    if var is not None and var.get() != mode:
        var.set(mode)
    log("ajustes: al cerrar la ventana -> " + dict(CLOSE_MODES)[mode].lower())


def _ask_close_mode(recordar=True):
    """La X con «Preguntarme»: pregunta que hacer y (si se deja marcado) lo
    recuerda. Devuelve 'minimize', 'quit' o None (cancelar)."""
    res = {"mode": None}
    box = tk.Toplevel(_root)
    box.title("Cerrar Growi Bridge")
    box.configure(bg=THEME["bg"])
    box.resizable(False, False)
    box.transient(_root)
    try:
        x = _root.winfo_x() + max(0, (_root.winfo_width() - S(420)) // 2)
        y = _root.winfo_y() + S(140)
        box.geometry(f"{S(420)}x{S(220)}+{x}+{y}")
    except Exception:
        pass
    tk.Label(box, text="¿Qué hago al cerrar la ventana?", font=(FONT, 13, "bold"),
             bg=THEME["bg"], fg=THEME["text"]).pack(anchor="w", padx=20, pady=(18, 4))
    tk.Label(box, text="Si me quedo en la bandeja sigo recibiendo tareas de Growi. "
             "Si salgo, se paran el puente y el runner.", font=(FONT, 10),
             bg=THEME["bg"], fg=THEME["muted"], wraplength=S(380),
             justify="left").pack(anchor="w", padx=20)
    remember = tk.BooleanVar(value=recordar)
    tk.Checkbutton(box, text="Recordar mi elección (se cambia en Ajustes)",
                   variable=remember, font=(FONT, 10), bg=THEME["bg"],
                   fg=THEME["text"], activebackground=THEME["bg"],
                   selectcolor="#FFFFFF").pack(anchor="w", padx=16, pady=(10, 6))
    row = tk.Frame(box, bg=THEME["bg"])
    row.pack(anchor="w", padx=20, pady=(4, 16))

    def _pick(mode):
        res["mode"] = mode
        if mode and remember.get():
            _set_close_mode(mode)
        box.destroy()

    first = ttk.Button(row, text="Minimizar a la bandeja", style="Accent.TButton",
                       command=lambda: _pick("minimize"))
    first.pack(side="left", padx=(0, 8))
    ttk.Button(row, text="Salir", command=lambda: _pick("quit")).pack(side="left", padx=(0, 8))
    ttk.Button(row, text="Cancelar", command=lambda: _pick(None)).pack(side="left")
    box.bind("<Escape>", lambda _e: _pick(None))
    box.protocol("WM_DELETE_WINDOW", lambda: _pick(None))
    first.focus_set()
    box.grab_set()
    _root.wait_window(box)
    return res["mode"]


def on_close_window():
    """La X de la ventana: hace lo que dice Ajustes (minimizar a la bandeja,
    salir o preguntar). Por defecto, en el carril A, minimiza a la bandeja."""
    mode = close_mode()
    if mode == "ask":
        # Si «Preguntarme» lo elegiste tu en Ajustes, no se pisa por defecto.
        mode = _ask_close_mode(recordar=load_settings().get("on_close") != "ask")
    if mode == "quit":
        quit_app()
    elif mode == "minimize":
        hide_to_tray(toast=True)


_SALIDA = {"hecha": False}


def _al_minimizar(e):
    """El boton minimizar de la ventana (carril A con bandeja): en vez de
    quedarse en la barra de tareas, se esconde en la bandeja como la X."""
    if _root is None or e.widget is not _root or not _a_la_bandeja():
        return
    try:
        if _root.state() == "iconic":
            _root.after_idle(hide_to_tray)
    except Exception:
        pass


def _fin_de_sesion_registrar(icon):
    """Cerrar sesion / apagar Windows: la ventana oculta de la bandeja
    (pystray, de nivel superior, recibe los mensajes de difusion) contesta
    WM_QUERYENDSESSION que si (pystray devolvia 0 = «no apagues») y con
    WM_ENDSESSION corre quit_app() en el hilo de la ventana y lo espera:
    al volver de WM_ENDSESSION Windows puede terminar el proceso."""
    WM_QUERYENDSESSION, WM_ENDSESSION = 0x0011, 0x0016

    def _query(wparam, lparam):
        log("windows: pide cerrar la sesión o apagar; contesto que sí")
        return 1

    def _end(wparam, lparam):
        if not wparam:  # la sesion al final no se cierra: se sigue
            log("windows: el cierre de sesión se canceló; sigo corriendo")
            return 0
        log("windows: se cierra la sesión o se apaga: salgo del todo (puente, runner, bandeja)")
        listo = threading.Event()

        def _salir():
            try:
                quit_app()
            finally:
                listo.set()
        try:
            _root.after(0, _salir)
        except Exception:
            _salir()
        if not listo.wait(15):
            log("windows: la salida no terminó en 15 s; Windows cierra el proceso")
        return 0

    icon._message_handlers[WM_QUERYENDSESSION] = _query
    icon._message_handlers[WM_ENDSESSION] = _end


def quit_app():
    global _tray_icon
    if _SALIDA["hecha"]:  # Salir y luego el final de mainloop: una sola vez
        return
    _SALIDA["hecha"] = True
    log("saliendo de Growi Bridge...")
    try:
        atajos_salir()  # UnregisterHotKey de cada atajo global: quedan libres
    except Exception:
        pass
    try:  # lo pendiente del día, al historial de gasto (t-historial-gasto-045)
        gasto_historial_actualizar([datetime.now().astimezone().date().isoformat()], "al cerrar")
    except Exception:
        pass
    try:
        lib_shutdown()  # descarga en pausa con fsync; el .part se conserva
    except Exception:
        pass
    try:
        stop_sharing()
    except Exception:
        pass
    try:
        hide_mascot()
    except Exception:
        pass
    try:
        stop_runner()
    except Exception:
        pass
    if LANE == "a":  # el carril B nunca arranca el motor local: no lo para
        try:
            srv_al_salir()  # sin VRAM secuestrada ni huerfanos al volver a abrir
        except Exception:
            pass
    try:
        stop_bridge()
    except Exception:
        pass
    if _tray_icon is not None:
        try:
            _tray_icon.stop()
        except Exception:
            pass
        _tray_icon = None
    if _root is not None:
        try:
            _root.quit()
            _root.destroy()
        except Exception:
            pass
    _lock_soltar()


def build_tray():
    global _tray_icon
    if not TRAY_OK:
        log("bandeja: pystray no instalado (pip install pystray pillow); sin icono en la bandeja")
        return None
    try:
        tray_img = TRAY_ICON if TRAY_ICON.is_file() else PHOTO
        image = Image.open(tray_img) if tray_img.is_file() else Image.new("RGBA", (64, 64), (5, 32, 72, 255))
    except Exception:
        image = Image.new("RGBA", (64, 64), (5, 32, 72, 255))
    # Menu corto (reglas P0): Abrir, Paleta, Estado del proxy, Pausar
    # mascota, Salir. Lo demas (puente, runner, pantalla) sigue en la
    # ventana y en Ctrl+K.
    menu = pystray.Menu(
        pystray.MenuItem("Abrir Growi Bridge", lambda: _root.after(0, show_window), default=True),
        pystray.MenuItem(_tray_espera_label, lambda: _root.after(0, abrir_lista_espera)),
        pystray.MenuItem(_tray_permisos_label, lambda: _root.after(0, abrir_permisos)),
        pystray.MenuItem(_tray_asis_label, _tray_asis_menu()),  # asistentes: elegir el activo
        pystray.Menu.SEPARATOR,
        pystray.MenuItem(_tray_paleta_label, lambda: _tray_palette()),
        pystray.MenuItem(lambda _i: f"Auto: {dict(AUTO_NIVELES)[auto_nivel()]} (clic: cambiar)",
                         lambda: _root.after(0, auto_nivel_ciclar)),
        pystray.MenuItem(_tray_proxy_label, lambda: _tray_open_proxy()),
        pystray.MenuItem(_tray_mascot_label, lambda: _root.after(0, toggle_mascot)),
        pystray.Menu.SEPARATOR,
        pystray.MenuItem("Salir", lambda: _root.after(0, quit_app)),
    )
    icon = pystray.Icon("GrowiBridge" + ("B" if LANE == "b" else ""), image, _tray_title(), menu)
    _patch_tray_clicks(icon)
    _fin_de_sesion_registrar(icon)
    try:
        icon.run_detached()
    except AttributeError:
        threading.Thread(target=icon.run, daemon=True).start()
    return icon


# ================================================================ Venezuela primero
# Onboarding de 4 pasos, mapa de disponibilidad (availability.json), proxy
# central y visible (con cambio solo al modelo local si la nube cae), gasto
# visible en la bandeja (tres dineros separados) y tema oscuro siguiendo a
# Windows (Direccion Raycast de DESIGN.md).
AVAIL_FILE = APP_DIR / "availability.json"
_AV = {"rows": {}, "at": 0.0, "running": False, "first": True, "country_direct": "",
       "lock": threading.Lock(), "last_conn": None}
_SP = {"at": 0.0, "data": None, "running": False, "warned": set()}
_TOAST = {"ctx": None}
_OB = {"det": None, "frame": None}

# ---- temas: claro / oscuro Raycast / segun el sistema (ver ESTADO-TEMAS.md)
# Cada tema es un archivo JSON en temas\ (junto a growi-bridge.py): los tokens
# de THEME, la fuente y sus tamanos base, los colores fijos de las superficies
# CustomTkinter (en minusculas) y el mapa de los colores fijos del tema claro
# que el codigo escribe tal cual. Un archivo roto, incompleto o con poco
# contraste no aparece: la app dice por que (nunca un traceback). El tema
# claro de siempre es el de por defecto.
TEMAS_DIR = APP_DIR / "temas"
TEMA_TOKENS = ("bg", "sidebar", "card", "field", "text", "muted", "line", "green",
               "green_text", "blue", "orange", "orange_text", "red")
TEMA_FIJOS = ("seg_bg", "seg_sel", "seg_hover", "accent", "accent_hover", "off_track",
              "on_accent")
TEMA_FUENTE = ("titulo", "seccion", "cuerpo", "pie")
# Colores fijos del tema claro que el codigo escribe en mayusculas (no son
# tokens). Los que valen igual que un token (#FFFFFF, #F5F5F7…) siguen al token.
TEMA_LITERALES = ("#E8E8ED", "#D2D2D7", "#E9E9EA", "#DCEBFF", "#6E6E73", "#FBECEC",
                  "#D8D8DD", "#3A3A3C", "#5A7086")
# Pares texto/fondo que cada tema debe pasar (>= 4,5:1, texto normal).
TEMA_PARES = (("text", "bg"), ("text", "card"), ("text", "field"), ("text", "sidebar"),
              ("muted", "bg"), ("muted", "card"), ("muted", "sidebar"),
              ("green_text", "bg"), ("green_text", "card"), ("blue", "bg"), ("blue", "card"),
              ("orange_text", "bg"), ("orange_text", "card"), ("red", "bg"), ("red", "card"),
              ("on_accent", "accent"), ("on_accent", "accent_hover"), ("text", "seg_bg"),
              ("text", "seg_sel"))
# El tema claro tal como esta escrito en el codigo (la base de todos los mapas
# y el respaldo si temas\claro.json falta o esta roto).
_TEMA_BASE = {
    "id": "claro", "archivo": "(integrado)", "nombre": "Claro", "tipo": "claro",
    "tokens": dict(THEME),
    "fuente": {"familia": FONT, "titulo": 22, "seccion": 11, "cuerpo": 10, "pie": 9},
    "fijos": {"seg_bg": "#e8e8ed", "seg_sel": "#ffffff", "seg_hover": "#dcdce1",
              "accent": "#0066cc", "accent_hover": "#0057b0", "off_track": "#e9e9ea",
              "on_accent": "#ffffff"},
    "mapa": {k: k for k in TEMA_LITERALES},
}
_TEMA = {"actual": _TEMA_BASE, "temas": {}, "errores": [], "tc": {}, "pendiente": None,
         "ultimo": None, "ttk0": None, "leido": 0.0}
_THEME_STATE = {"dark": False}
_COLOR_OPTS = ("bg", "background", "fg", "foreground", "activebackground", "activeforeground",
               "highlightbackground", "highlightcolor", "selectbackground", "selectforeground",
               "insertbackground", "selectcolor", "disabledforeground", "fill", "outline",
               "troughcolor", "readonlybackground")
_HEX6 = re.compile(r"^#[0-9A-Fa-f]{6}$")


def _tema_lum(h):
    def lin(c):
        c = c / 255
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    h = h.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)


def tema_contraste(a, b):
    """Contraste WCAG 2.x entre dos colores #RRGGBB (1.0 a 21.0)."""
    la, lb = sorted((_tema_lum(a), _tema_lum(b)), reverse=True)
    return (la + 0.05) / (lb + 0.05)


def _tema_validar(tid, d):
    """Tema listo para usar o (None, motivo legible)."""
    if not isinstance(d, dict):
        return None, "no es un objeto JSON ({…})"
    nombre = d.get("nombre")
    if not isinstance(nombre, str) or not nombre.strip():
        return None, "le falta «nombre»"
    tipo = d.get("tipo")
    if tipo not in ("claro", "oscuro"):
        return None, "«tipo» debe ser «claro» u «oscuro»"
    toks = d.get("tokens")
    if not isinstance(toks, dict):
        return None, "le falta el bloque «tokens»"
    faltan = [k for k in TEMA_TOKENS if k not in toks]
    if faltan:
        return None, "le falta el token " + ", ".join(f"«{k}»" for k in faltan)
    malos = [k for k in TEMA_TOKENS if not (isinstance(toks[k], str) and _HEX6.match(toks[k]))]
    if malos:
        return None, "el token " + ", ".join(f"«{k}»" for k in malos) + " no es un color #RRGGBB"
    fu = d.get("fuente")
    if not isinstance(fu, dict) or not isinstance(fu.get("familia"), str) or not fu["familia"].strip():
        return None, "le falta «fuente» con su «familia»"
    for k in TEMA_FUENTE:
        if not isinstance(fu.get(k), int) or not 6 <= fu[k] <= 48:
            return None, f"la fuente necesita «{k}» (un tamaño entero entre 6 y 48)"
    fi = d.get("fijos")
    if not isinstance(fi, dict):
        return None, "le falta el bloque «fijos»"
    for k in TEMA_FIJOS:
        if not (isinstance(fi.get(k), str) and _HEX6.match(fi[k])):
            return None, f"le falta el color fijo «{k}» (#rrggbb)"
    ma = d.get("mapa") if d.get("mapa") is not None else {}
    if not isinstance(ma, dict):
        return None, "«mapa» debe ser un objeto {color claro: color de este tema}"
    for k, v in ma.items():
        if k.upper() not in TEMA_LITERALES or not (isinstance(v, str) and _HEX6.match(v)):
            return None, f"«mapa» trae una entrada que no vale: {k}"
    if tipo == "oscuro":
        faltan = [k for k in TEMA_LITERALES if k not in {x.upper() for x in ma}]
        if faltan:
            return None, "un tema oscuro necesita en «mapa» todos los colores fijos: falta " + faltan[0]
    t = {"id": tid, "archivo": f"{tid}.json", "nombre": nombre.strip(), "tipo": tipo,
         "descripcion": str(d.get("descripcion") or ""),
         "tokens": {k: toks[k].upper() for k in TEMA_TOKENS},
         "fuente": {"familia": fu["familia"].strip(), **{k: fu[k] for k in TEMA_FUENTE}},
         "fijos": {k: fi[k].lower() for k in TEMA_FIJOS},
         "mapa": {k: k for k in TEMA_LITERALES}}
    t["mapa"].update({k.upper(): v.upper() for k, v in ma.items()})
    for a, b in TEMA_PARES:
        ca = t["tokens"].get(a) or t["fijos"][a]
        cb = t["tokens"].get(b) or t["fijos"][b]
        r = tema_contraste(ca, cb)
        if r < 4.5:
            return None, (f"contraste {r:.2f}:1 de «{a}» sobre «{b}» ({ca} / {cb}); "
                          "el mínimo es 4,5:1").replace(".", ",", 1)
    return t, None


def tema_cargar():
    """Lee temas\\*.json. Devuelve (temas por id, [(archivo, motivo)])."""
    temas, errores = {}, []
    try:
        files = sorted(TEMAS_DIR.glob("*.json")) if TEMAS_DIR.is_dir() else []
    except OSError as e:
        files = []
        errores.append(("temas", f"no se pudo leer la carpeta ({e.strerror or e})"))
    for f in files:
        try:
            d = json.loads(f.read_text(encoding="utf-8-sig"))
        except ValueError as e:
            errores.append((f.name, f"no es JSON válido (línea {getattr(e, 'lineno', '?')}: "
                                    f"{getattr(e, 'msg', e)})"))
            continue
        except OSError as e:
            errores.append((f.name, f"no se pudo leer ({e.strerror or e})"))
            continue
        t, motivo = _tema_validar(f.stem, d)
        if t is None:
            errores.append((f.name, motivo))
        else:
            temas[t["id"]] = t
    if "claro" not in temas:
        temas["claro"] = _TEMA_BASE  # el claro de siempre nunca falta
    _TEMA["temas"], _TEMA["errores"], _TEMA["leido"] = temas, errores, time.time()
    for nom, mot in errores:
        log(f"temas: {nom} no se cargó: {mot}")
    return temas, errores


def _tema_desde_base(t):
    """{color del claro escrito en el codigo: su color en el tema t} + choques."""
    m, choques = {}, []
    pares = [(_TEMA_BASE["tokens"][k], t["tokens"][k]) for k in TEMA_TOKENS]
    pares += list(t["mapa"].items())
    for c, v in pares:
        if c in m and m[c] != v:
            choques.append(f"{c} → {m[c]} y {v}")
        m.setdefault(c, v)
    inv = {}
    for c, v in m.items():
        if v in inv and inv[v] != c:
            choques.append(f"{v} viene de {inv[v]} y de {c}")
        inv.setdefault(v, c)
    return m, inv, choques


def _tema_tabla(nuevo):
    """Cualquier color conocido (de cualquier tema) -> su color en `nuevo`."""
    dest, _i, _c = _tema_desde_base(nuevo)
    tabla, choques = {}, []
    for t in [_TEMA_BASE] + list(_TEMA["temas"].values()):
        _m, inv, _c2 = _tema_desde_base(t)
        for v, c in inv.items():
            nv = dest.get(c, c)
            if v in tabla and tabla[v] != nv:
                choques.append(f"{v} ({t['nombre']})")
                continue
            tabla[v] = nv
    return tabla, choques


def _tema_fijo(nombre):
    """Color fijo (minusculas) del tema actual: botones grises, acento…"""
    return _TEMA["actual"]["fijos"][nombre]


def _tc(v):
    """Un color del tema que sea, en el tema actual (los de mayusculas)."""
    return _TEMA["tc"].get(v, v) if isinstance(v, str) else v


def _system_dark():
    """Windows: AppsUseLightTheme (1 = claro, 0 = oscuro) en HKCU."""
    try:
        import winreg
        clave = (os.environ.get("GROWI_BRIDGE_TEMA_REGKEY")  # solo para las pruebas
                 or r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
        k = winreg.OpenKey(winreg.HKEY_CURRENT_USER, clave)
        try:
            v, _t = winreg.QueryValueEx(k, "AppsUseLightTheme")
        finally:
            winreg.CloseKey(k)
        return int(v) == 0
    except Exception:
        return False


def tema_modo(s=None):
    """claro / oscuro / sistema (lo guardado en settings.json; por defecto claro)."""
    forced = os.environ.get("GROWI_BRIDGE_THEME", "").strip().lower()
    if forced in ("dark", "oscuro"):
        return "oscuro"
    if forced in ("light", "claro"):
        return "claro"
    if forced in ("system", "sistema"):
        return "sistema"
    m = (s if s is not None else load_settings()).get("apariencia")
    return m if m in ("claro", "oscuro", "sistema") else "claro"


def tema_resolver(modo=None, s=None):
    """(id del tema que toca, frase de por que)."""
    s = s if s is not None else load_settings()
    modo = modo or tema_modo(s)
    temas = _TEMA["temas"] or tema_cargar()[0]
    por = ""
    if modo == "sistema":
        osc = _system_dark()
        tipo = "oscuro" if osc else "claro"
        por = f"Windows usa el modo {'oscuro' if osc else 'claro'}"
    else:
        tipo = modo
    quiero = s.get("tema_" + tipo) or ("oscuro-raycast" if tipo == "oscuro" else "claro")
    if quiero in temas and temas[quiero]["tipo"] == tipo:
        return quiero, por
    del_tipo = sorted(k for k, t in temas.items() if t["tipo"] == tipo)
    if del_tipo:
        return del_tipo[0], por
    return "claro", ((por + "; ") if por else "") + f"no hay ningún tema {tipo} que se pueda usar"


def fuente_instalada(familia):
    """¿Windows tiene esa familia? (registro de fuentes del sistema y del usuario; sin Tk todavía)."""
    if familia.lower() in ("segoe ui", "consolas"):
        return True
    try:
        import winreg
    except ImportError:
        return False
    clave = r"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"
    for raiz in (winreg.HKEY_LOCAL_MACHINE, winreg.HKEY_CURRENT_USER):
        try:
            with winreg.OpenKey(raiz, clave) as k:
                i = 0
                while True:
                    try:
                        nombre = winreg.EnumValue(k, i)[0]
                    except OSError:
                        break
                    if re.match(re.escape(familia) + r"(\s|\(|$)", nombre, re.I):
                        return True
                    i += 1
        except OSError:
            continue
    return False


def _tema_poner(t):
    """Deja `t` como tema actual (THEME, tabla de colores, oscuro o no)."""
    THEME.update(t["tokens"])
    _TEMA["actual"] = t
    _TEMA["tc"] = _tema_tabla(t)[0]
    _THEME_STATE["dark"] = t["tipo"] == "oscuro"
    globals()["PALETTE_RED"] = THEME["red"]


def _fix_font(f):
    """Reglas P0: texto regular >= 12 px y en negrita >= 14 px (a 100 %)."""
    if isinstance(f, tuple) and len(f) >= 2 and isinstance(f[1], int) and f[1] > 0:
        st = " ".join(str(x) for x in f[2:]).lower()
        if "bold" in st and f[1] < 11:
            return (f[0], -S(14)) + tuple(f[2:])
        if f[1] < 9:
            return (f[0], 9) + tuple(f[2:])
    return f


def _filter_kw(cnf):
    if not isinstance(cnf, dict):
        return cnf
    tc = _TEMA["tc"]
    for k, v in list(cnf.items()):
        if k in _COLOR_OPTS and isinstance(v, str) and v in tc:
            cnf[k] = tc[v]
        elif k == "font":
            cnf[k] = _fix_font(v)
    # Boton primario: el texto blanco no se lee sobre el acento rojo del
    # oscuro (2,91:1); va el color «on_accent» del tema (6,59:1).
    fondo = cnf.get("bg", cnf.get("background"))
    if fondo is not None and fondo == THEME["blue"]:
        for k in ("fg", "foreground"):
            if str(cnf.get(k, "")).lower() in ("white", "#ffffff"):
                cnf[k] = _tema_fijo("on_accent")
    return cnf


# ---- movimiento y alto contraste (t-movimiento-contraste)
# Reducir movimiento: settings «reducir_movimiento» = sistema (por defecto: lo
# que diga Windows, SPI_GETCLIENTAREAANIMATION) / animar / nunca. Sin
# movimiento: nada depende de algo que se mueve (botón y mascota quietos, el
# estado sigue escrito). Alto contraste: si Windows tiene un tema de contraste
# (SPI_GETHIGHCONTRAST), la app usa los colores DEL SISTEMA (GetSysColor) para
# texto, fondo, botones y foco en vez de los de marca.
MOVIMIENTO_OPCIONES = (("sistema", "Seguir el sistema"), ("animar", "Siempre animar"), ("nunca", "Nunca animar"))


def animaciones_sistema():
    """True si Windows tiene los efectos de animación encendidos (o si no se puede leer)."""
    try:
        import ctypes
        v = ctypes.c_int(1)
        ok = ctypes.windll.user32.SystemParametersInfoW(0x1042, 0, ctypes.byref(v), 0)  # SPI_GETCLIENTAREAANIMATION
        return bool(v.value) if ok else True
    except Exception:
        return True


def movimiento_permitido():
    pref = load_settings().get("reducir_movimiento") or "sistema"
    if pref == "animar":
        return True
    if pref == "nunca":
        return False
    return animaciones_sistema()


def movimiento_poner(pref):
    if pref not in dict(MOVIMIENTO_OPCIONES):
        return
    s = load_settings()
    s["reducir_movimiento"] = pref
    save_settings(s)
    log(f"apariencia: movimiento «{dict(MOVIMIENTO_OPCIONES)[pref]}» → "
        f"{'anima' if movimiento_permitido() else 'sin animaciones'} (Windows: "
        f"{'animaciones encendidas' if animaciones_sistema() else 'animaciones apagadas'})")


def alto_contraste_sistema():
    """True si Windows tiene puesto un tema de contraste (Night Sky, Aquatic…)."""
    try:
        import ctypes
        from ctypes import wintypes

        class HIGHCONTRASTW(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.UINT), ("dwFlags", wintypes.DWORD), ("lpszDefaultScheme", wintypes.LPWSTR)]
        hc = HIGHCONTRASTW(ctypes.sizeof(HIGHCONTRASTW), 0, None)
        ok = ctypes.windll.user32.SystemParametersInfoW(0x0042, ctypes.sizeof(hc), ctypes.byref(hc), 0)
        return bool(ok and hc.dwFlags & 0x1)  # HCF_HIGHCONTRASTON
    except Exception:
        return False


def _sys_color(idx):
    import ctypes
    c = ctypes.windll.user32.GetSysColor(idx)
    return f"#{c & 0xFF:02x}{(c >> 8) & 0xFF:02x}{(c >> 16) & 0xFF:02x}"


def tema_alto_contraste():
    """Un tema hecho con los colores del sistema (los del tema de contraste)."""
    fondo, texto = _sys_color(5), _sys_color(8)           # COLOR_WINDOW, COLOR_WINDOWTEXT
    cara, cara_txt = _sys_color(15), _sys_color(18)       # COLOR_BTNFACE, COLOR_BTNTEXT
    sel, sel_txt = _sys_color(13), _sys_color(14)         # COLOR_HIGHLIGHT, COLOR_HIGHLIGHTTEXT
    gris, enlace = _sys_color(17), _sys_color(26)         # COLOR_GRAYTEXT, COLOR_HOTLIGHT
    lum = sum(int(fondo[i:i + 2], 16) for i in (1, 3, 5)) / 3
    t = json.loads(json.dumps(_TEMA_BASE))
    t.update(nombre="Contraste del sistema", tipo="oscuro" if lum < 128 else "claro", archivo="(Windows)",
             descripcion="Colores del tema de contraste de Windows (texto, fondo, botones y foco del sistema).")
    t["tokens"].update(bg=fondo, sidebar=cara, card=fondo, field=fondo, text=texto, muted=texto, line=texto,
                       green=sel, green_text=enlace, blue=enlace, orange=sel, orange_text=texto, red=texto)
    t["fijos"].update(seg_bg=cara, seg_sel=sel, seg_hover=sel, accent=sel, accent_hover=enlace, off_track=cara,
                      on_accent=sel_txt)
    t["mapa"] = {k: cara for k in t.get("mapa") or {}}
    t["sistema"] = {"fondo": fondo, "texto": texto, "boton": cara, "boton_texto": cara_txt, "seleccion": sel,
                    "seleccion_texto": sel_txt, "gris": gris, "enlace": enlace}
    return t


def _theme_init():
    """Antes de crear la ventana: lee temas\\, elige el tema (settings.json o
    Windows) y pone el filtro de colores y tamanos minimos de letra en la
    frontera con Tk."""
    if not TK_OK or getattr(tk.BaseWidget, "_growi_theme", False):
        return
    try:
        tema_cargar()
        tid, por = tema_resolver()
        t = _TEMA["temas"].get(tid, _TEMA_BASE)
    except Exception as e:  # nunca un traceback por un tema
        log(f"temas: no se pudo elegir el tema ({type(e).__name__}: {e}); se usa el claro")
        t, por = _TEMA_BASE, ""
    if alto_contraste_sistema():  # Windows en contraste alto: colores del sistema, no los de marca
        t, por = tema_alto_contraste(), "Windows tiene un tema de contraste"
        _TEMA["alto_contraste"] = True
    _tema_poner(t)
    fam = t["fuente"]["familia"]
    if not fuente_instalada(fam):
        log(f"temas: la fuente {fam} no está instalada en este PC: se usa Segoe UI")
        fam = "Segoe UI"
    _TEMA["fuente_en_uso"] = fam
    globals()["FONT"] = fam
    globals()["SECTION_FONT"] = (FONT, t["fuente"]["seccion"], "bold")
    log(f"temas: {t['nombre']} ({t['archivo']}, modo {tema_modo()}{', ' + por if por else ''})")
    orig_init = tk.BaseWidget.__init__
    orig_conf = tk.Misc._configure
    orig_create = tk.Canvas._create

    def __init__(self, master, widgetName, cnf={}, kw={}, extra=()):
        cnf = _filter_kw(dict(tk._cnfmerge((cnf, kw))) if (cnf or kw) else {})
        return orig_init(self, master, widgetName, cnf, {}, extra)

    def _configure(self, cmd, cnf, kw):
        if kw:
            kw = _filter_kw(dict(kw))
        if isinstance(cnf, dict) and cnf:
            cnf = _filter_kw(dict(cnf))
        return orig_conf(self, cmd, cnf, kw)

    def _create(self, itemType, args, kw):
        if kw:
            kw = _filter_kw(dict(kw))
        return orig_create(self, itemType, args, kw)

    tk.BaseWidget.__init__ = __init__
    tk.Misc._configure = _configure
    tk.Canvas._create = _create
    tk.BaseWidget._growi_theme = True


def _C(hexcolor):
    """Un color fijo del tema claro, en el tema que toca."""
    return _tc(hexcolor)


# Estilos ttk que la app toca (no pasan por el filtro de Tk).
_TTK_ESTILOS = ("TButton", "Accent.TButton", "Danger.TButton", "TEntry", "TCombobox",
                "Treeview", "Res.Treeview", "Treeview.Heading", "TCheckbutton", "TScrollbar",
                "Vertical.TScrollbar", "Horizontal.TScrollbar", "TProgressbar",
                "Horizontal.TProgressbar", "TLabel", "TFrame")
# Lo que solo cambia el tema oscuro (para volver a dejarlo como estaba en claro).
_TTK_OSCURO = {"TButton": ("lightcolor", "darkcolor"),
               "TCombobox": ("background", "arrowcolor", "bordercolor"),
               "TScrollbar": ("background", "troughcolor", "arrowcolor", "bordercolor",
                              "lightcolor", "darkcolor"),
               "Vertical.TScrollbar": ("background", "troughcolor", "arrowcolor", "bordercolor",
                                       "lightcolor", "darkcolor"),
               "TEntry": ("insertcolor", "lightcolor", "darkcolor"),
               "Treeview": ("bordercolor", "lightcolor", "darkcolor"),
               "Treeview.Heading": ("bordercolor", "lightcolor", "darkcolor")}


def _theme_styles(style):
    """Estilos ttk del tema actual, completos (al arrancar y al cambiar)."""
    T = THEME
    if _TEMA["ttk0"] is None:  # como estaban antes de oscurecer nada
        s0 = {}
        for n, opts in _TTK_OSCURO.items():
            s0[n] = {o: style.lookup(n, o) for o in opts}
        _TEMA["ttk0"] = {"cfg": s0, "map": {n: style.map(n) for n in
                                            ("Treeview", "TButton", "Vertical.TScrollbar")}}
    big = (FONT, -S(14), "bold")
    # Lo mismo que build_gui fija en claro, con los colores del tema que toca.
    style.configure("TButton", background=_C("#FFFFFF"), foreground=T["text"],
                    borderwidth=1, relief="solid", padding=(S(12), S(6)), font=(FONT, 10))
    style.map("TButton", background=[("active", _C("#F5F5F7"))])
    style.configure("Accent.TButton", background=_tema_fijo("accent"), foreground=_tema_fijo("on_accent"),
                    borderwidth=0, padding=(S(12), S(6)), font=big)
    style.map("Accent.TButton", background=[("disabled", _C("#E8E8ED")),
                                            ("active", _tema_fijo("accent_hover"))],
              foreground=[("disabled", _C("#6E6E73"))])
    style.configure("TEntry", fieldbackground=_C("#FFFFFF"), foreground=T["text"],
                    borderwidth=1, relief="solid", insertcolor=T["text"])
    try:
        style.configure("TButton", bordercolor=_C("#D2D2D7"))
        style.configure("TEntry", bordercolor=_C("#D2D2D7"))
    except Exception:
        pass
    style.configure("TCombobox", fieldbackground=_C("#FFFFFF"), foreground=T["text"])
    style.map("TCombobox", fieldbackground=[("readonly", _C("#FFFFFF"))],
              selectbackground=[("readonly", _C("#FFFFFF"))],
              selectforeground=[("readonly", T["text"])],
              foreground=[("readonly", T["text"])])
    style.configure("Treeview", background=_C("#FFFFFF"), foreground=T["text"],
                    fieldbackground=_C("#FFFFFF"), borderwidth=0, font=(FONT, 10),
                    rowheight=S(FILA_PX))
    style.configure("Treeview.Heading", background=_C("#F5F5F7"), foreground=T["muted"],
                    font=(FONT, -S(14), "bold"))
    style.map("Tareas.Treeview", background=[("selected", "#222224" if _THEME_STATE.get("dark") else _C("#DCEBFF"))],
              foreground=[("selected", T["text"])])
    style.configure("TCheckbutton", background=T["bg"], foreground=T["text"], font=(FONT, 10))
    style.configure("Res.Treeview", background=_C("#FFFFFF"), fieldbackground=_C("#FFFFFF"),
                    foreground=T["text"])
    style.map("Res.Treeview", background=[("selected", _C("#DCEBFF"))],
              foreground=[("selected", T["text"])])
    style.configure("Danger.TButton", foreground=T["red"])
    style.map("Danger.TButton", foreground=[("disabled", "#8E8E93")],
              background=[("disabled", _C("#F5F5F7")), ("active", _C("#FBECEC"))])
    if not _THEME_STATE["dark"]:
        # Volver de un oscuro: lo que solo toca el oscuro, como estaba.
        for n, vals in _TEMA["ttk0"]["cfg"].items():
            for o, v in vals.items():
                try:
                    style.configure(n, **{o: v})
                except Exception:
                    pass
        for n, m in _TEMA["ttk0"]["map"].items():
            try:
                style.map(n, **{k: m.get(k, []) for k in set(m) | {"background", "foreground"}})
            except Exception:
                pass
        if _TEMA.get("fue_oscuro"):  # al arrancar en claro no se toca nada
            try:
                _root.option_add("*TCombobox*Listbox.background", "SystemWindow")
                _root.option_add("*TCombobox*Listbox.foreground", "SystemWindowText")
                _root.option_add("*TCombobox*Listbox.selectBackground", "SystemHighlight")
            except Exception:
                pass
        return
    bd = _C("#D2D2D7")
    style.configure("TButton", background=T["card"], foreground=T["text"],
                    bordercolor=bd, lightcolor=T["card"], darkcolor=T["card"])
    style.map("TButton", background=[("active", _C("#E8E8ED")), ("disabled", T["bg"])],
              foreground=[("disabled", "#8E8E93")])
    # lightcolor/darkcolor: el clam pinta un filo blanco por dentro del borde (el campo Ctrl+K de Tareas, auditoría F12)
    style.configure("TEntry", fieldbackground=T["field"], foreground=T["text"],
                    insertcolor=T["text"], bordercolor=T["line"], lightcolor=T["field"], darkcolor=T["field"])
    style.configure("TCombobox", fieldbackground=T["field"], foreground=T["text"],
                    background=T["card"], arrowcolor=T["text"], bordercolor=bd)
    style.map("TCombobox", fieldbackground=[("readonly", T["field"])],
              selectbackground=[("readonly", T["field"])],
              selectforeground=[("readonly", T["text"])],
              foreground=[("readonly", T["text"])])
    style.configure("Treeview", background=T["field"], foreground=T["text"],
                    fieldbackground=T["field"])
    style.map("Treeview", background=[("selected", _C("#DCEBFF"))],
              foreground=[("selected", T["text"])])
    style.configure("Treeview.Heading", background=T["card"], foreground=T["muted"],
                    bordercolor=T["line"], lightcolor=T["card"], darkcolor=T["card"])
    style.configure("Treeview", bordercolor=T["line"], lightcolor=T["field"], darkcolor=T["field"])
    style.configure("TCheckbutton", background=T["bg"], foreground=T["text"])
    for _sb in ("TScrollbar", "Vertical.TScrollbar"):
        style.configure(_sb, background=_C("#E8E8ED"), troughcolor=T["bg"], arrowcolor=T["muted"],
                        bordercolor=T["bg"], lightcolor=_C("#E8E8ED"), darkcolor=_C("#E8E8ED"))
    style.map("Vertical.TScrollbar", background=[("active", bd)])
    try:
        _root.option_add("*TCombobox*Listbox.background", T["field"])
        _root.option_add("*TCombobox*Listbox.foreground", T["text"])
        _root.option_add("*TCombobox*Listbox.selectBackground", _C("#DCEBFF"))
    except Exception:
        pass


def _dark_titlebar(win, forzar=False):
    """Barra de titulo oscura en Windows 11 (DWMWA_USE_IMMERSIVE_DARK_MODE).
    En claro no se toca al arrancar; al volver de un oscuro (forzar) se apaga."""
    if not _THEME_STATE["dark"] and not forzar:
        return
    try:
        import ctypes
        win.update_idletasks()
        hwnd = ctypes.windll.user32.GetAncestor(win.winfo_id(), 2) or win.winfo_id()
        val = ctypes.c_int(1 if _THEME_STATE["dark"] else 0)
        ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, 20, ctypes.byref(val), 4)
    except Exception:
        pass


# ---- cambio en caliente: se re-pinta todo lo que lee de THEME o de los
# colores conocidos; si algo quedaria con el tema viejo, no se toca nada y se
# pide reiniciar (nunca mitad claro y mitad oscuro).
_TEMA_PISTA_CTK = {"_selected_color": "seg_sel", "_selected_hover_color": "seg_sel",
                   "_unselected_color": "seg_bg", "_unselected_hover_color": "seg_hover",
                   "_hover_color": "seg_hover", "_sb_selected_color": "seg_sel",
                   "_sb_selected_hover_color": "seg_sel", "_sb_unselected_color": "seg_bg",
                   "_sb_fg_color": "seg_bg", "_sb_unselected_hover_color": "seg_hover"}


def _tema_fijo_nuevo(viejo, nuevo, v, pista=None, quieto=()):
    """Un color fijo en minusculas del tema viejo -> el del nuevo (por su papel)."""
    if not isinstance(v, str) or not _HEX6.match(v) or v != v.lower():
        return v
    papeles = [k for k, c in viejo["fijos"].items() if c == v]
    if not papeles or pista in quieto:
        return v
    if pista in papeles:
        return nuevo["fijos"][pista]
    destinos = {nuevo["fijos"][k] for k in papeles}
    return destinos.pop() if len(destinos) == 1 else v


def _tema_widgets(root):
    pila, out = [root], []
    while pila:
        w = pila.pop()
        out.append(w)
        try:
            pila.extend(w.winfo_children())
        except Exception:
            pass
    return out


def _tema_plan(viejo, nuevo, tabla):
    """Lista de cambios (sin aplicar nada) + lo que quedaria con el tema viejo."""
    ctk = sys.modules.get("customtkinter")
    base_ctk = getattr(ctk, "CTkBaseClass", None) if ctk else None
    viejos = ({c.upper() for c in viejo["tokens"].values()} | set(viejo["mapa"].values())) - \
             ({c.upper() for c in nuevo["tokens"].values()} | set(nuevo["mapa"].values()))
    acento_v, acento_n = viejo["fijos"]["accent"], nuevo["fijos"]["accent"]
    oscuro = nuevo["tipo"] == "oscuro"
    plan, quedan = [], []

    def nuevo_color(v, pista=None, quieto=()):
        if not isinstance(v, str):
            return v
        if v in tabla:
            return tabla[v]
        return _tema_fijo_nuevo(viejo, nuevo, v, pista, quieto)

    nuevos_fijos = set(nuevo["fijos"].values())

    def revisar(w, donde, v, es_fondo, quieto=False):
        # Mayusculas = colores de tema: si sigue uno del tema viejo, queda a
        # medias. Minusculas = fijos o calculados: solo un fondo que no pega.
        if quieto or not isinstance(v, str) or not _HEX6.match(v):
            return
        if v == v.upper() and v in viejos:
            quedan.append(f"{type(w).__name__} {donde} {v}")
        elif es_fondo and v not in tabla.values() and v not in nuevos_fijos and (
                (oscuro and _tema_lum(v) > 0.6) or (not oscuro and _tema_lum(v) < 0.02)):
            quedan.append(f"{type(w).__name__} {donde} {v} (color fuera del tema)")

    for w in _tema_widgets(_root):
        try:
            if not w.winfo_exists():
                continue
        except Exception:
            continue
        if base_ctk is not None and isinstance(w, base_ctk):
            # Botones de un control segmentado: el relleno y el texto los pone
            # el control; aqui solo su fondo y sus esquinas.
            seg_hijo = type(getattr(w, "master", None)).__name__ == "CTkSegmentedButton"
            cambios = {}
            interruptor = type(w).__name__ in ("CTkSwitch", "CTkCheckBox", "CTkRadioButton")
            for a, v in list(vars(w).items()):
                if not (a.endswith("_color") or a in ("_accent", "_background_corner_colors")):
                    continue
                if seg_hijo and a in ("_fg_color", "_hover_color", "_text_color",
                                      "_text_color_disabled", "_border_color"):
                    continue
                pista = _TEMA_PISTA_CTK.get(a) or ("seg_bg" if seg_hijo else None)
                if a == "_accent":
                    pista = "accent"
                elif a in ("_text_color",) and getattr(w, "_fg_color", None) == acento_v:
                    pista = "on_accent"
                elif a in ("_fg_color",) and v == acento_v:
                    pista = "accent"
                quieto = ("knob",) if interruptor and a in ("_button_color", "_button_hover_color") else ()
                pista = "knob" if quieto else pista
                if isinstance(v, (tuple, list)) and v and all(isinstance(x, str) for x in v):
                    nv = type(v)(nuevo_color(x, pista, quieto) for x in v)
                else:
                    nv = nuevo_color(v, pista, quieto)
                if nv != v:
                    cambios[a] = nv
                for x in (nv if isinstance(nv, (tuple, list)) else (nv,)):
                    revisar(w, a, x, a in ("_fg_color", "_bg_color"), bool(quieto))
            if cambios:
                plan.append(("ctk", w, cambios))
            continue
        dueno = getattr(w, "master", None)
        if base_ctk is not None and isinstance(dueno, base_ctk) and                 any(v is w for v in vars(dueno).values()):
            continue  # pieza interna de un widget CTk: la re-pinta su dueno
        try:  # CTk envuelve configure() de los contenedores tk: se lee por Misc
            opts = tk.Misc.configure(w) or {}
        except Exception:
            opts = {}
        cambios = {}
        for k in _COLOR_OPTS:
            if k not in opts or k in ("fill", "outline"):
                continue
            v = str(opts[k][-1])
            nv = nuevo_color(v, quieto=("knob",))
            if nv != v:
                cambios[k] = nv
            revisar(w, k, nv, k in ("bg", "background"))
        fondo = cambios.get("bg", str(opts.get("bg", ("",))[-1]) if "bg" in opts else "")
        fg = str(opts["fg"][-1]) if "fg" in opts else ""
        if fondo and fondo in (THEME["blue"], tabla.get(THEME["blue"]), nuevo["tokens"]["blue"]) and \
                fg.lower() in ("white", "#ffffff", viejo["fijos"]["on_accent"]):
            cambios["fg"] = nuevo["fijos"]["on_accent"]
        if cambios:
            plan.append(("tk", w, cambios))
        cls = w.winfo_class()
        if cls == "Canvas":
            try:
                for it in w.find_all():
                    ic = {}
                    for o in ("fill", "outline", "activefill"):
                        try:
                            v = w.itemcget(it, o)
                        except Exception:
                            continue
                        nv = nuevo_color(v, quieto=("knob",))
                        if v and nv != v:
                            ic[o] = nv
                    if ic:
                        plan.append(("item", w, (it, ic)))
            except Exception:
                pass
        elif cls == "Text":
            try:
                for tg in w.tag_names():
                    ic = {}
                    for o in ("foreground", "background", "selectbackground"):
                        v = w.tag_cget(tg, o)
                        nv = nuevo_color(str(v)) if v else v
                        if v and nv != v:
                            ic[o] = nv
                    if ic:
                        plan.append(("tag", w, (tg, ic)))
            except Exception:
                pass
        elif cls == "Treeview":
            try:
                for tg in w.tk.splitlist(w.tk.call(w._w, "tag", "names")):
                    ic = {}
                    for o in ("foreground", "background"):
                        v = str(w.tag_configure(tg, o) or "")
                        nv = nuevo_color(v) if v else v
                        if v and nv != v:
                            ic[o] = nv
                    if ic:
                        plan.append(("ttag", w, (tg, ic)))
            except Exception:
                pass
    return plan, quedan


def _tema_ejecutar(plan):
    hechos, fallos = 0, []
    for kind, w, data in plan:
        try:
            if not w.winfo_exists():
                continue  # la pagina lo rehizo mientras tanto (ya nace con el tema nuevo)
        except Exception:
            continue
        try:
            if kind == "tk":
                w.configure(**data)
            elif kind == "ctk":
                resto = {}
                for a, v in data.items():
                    nom = a[4:] if a.startswith("_sb_") else a[1:]
                    try:  # la API publica (re-pinta tambien sus piezas)
                        w.configure(**{nom: v})
                    except Exception:
                        resto[a] = v
                for a, v in resto.items():
                    setattr(w, a, v)
                if resto and hasattr(w, "_draw"):
                    w._draw(no_color_updates=False)
            elif kind == "item":
                w.itemconfigure(data[0], **data[1])
            elif kind == "tag":
                w.tag_configure(data[0], **data[1])
            elif kind == "ttag":
                w.tag_configure(data[0], **data[1])
            hechos += 1
        except Exception as e:
            if "invalid command name" in str(e) or "bad window path" in str(e):
                continue  # destruido mientras se re-pintaba: no queda nada que pintar
            fallos.append(f"{type(w).__name__}: {type(e).__name__}: {e}")
    return hechos, fallos


def tema_aplicar(tid, origen="ajustes"):
    """Cambia al tema `tid` sin reiniciar. {"estado": igual|aplicado|reinicio|error, …}"""
    t0 = time.perf_counter()
    temas = _TEMA["temas"] or tema_cargar()[0]
    nuevo = temas.get(tid)
    viejo = _TEMA["actual"]
    if nuevo is None:
        return {"estado": "error", "texto": f"El tema «{tid}» no está en la carpeta temas."}
    if nuevo == viejo:
        _TEMA["pendiente"] = None  # se volvio al que se ve: ya no hace falta reiniciar
        return {"estado": "igual", "texto": f"Ya estás en «{nuevo['nombre']}»."}
    if _root is None:
        _tema_poner(nuevo)
        return {"estado": "aplicado", "texto": f"Tema «{nuevo['nombre']}»."}
    motivos = []
    if nuevo["fuente"] != viejo["fuente"]:
        motivos.append("la fuente o sus tamaños cambian (las letras no se re-dibujan en caliente)")
    ch = _tema_desde_base(nuevo)[2] + _tema_desde_base(viejo)[2]
    tabla, ch2 = _tema_tabla(nuevo)
    if ch or ch2:
        motivos.append("colores ambiguos entre temas: " + "; ".join((ch + ch2)[:3]))
    plan, quedan = ([], [])
    if not motivos:
        plan, quedan = _tema_plan(viejo, nuevo, tabla)
        if quedan:
            motivos.append(f"{len(quedan)} elementos no leen de THEME: " + "; ".join(quedan[:4]))
    if motivos:
        _TEMA["pendiente"] = tid
        _TEMA["ultimo"] = {"estado": "reinicio", "lista": quedan, "motivos": motivos}
        log(f"temas: «{nuevo['nombre']}» queda para el reinicio ({origen}): " + " | ".join(motivos))
        return {"estado": "reinicio", "lista": quedan, "motivos": motivos,
                "texto": (f"«{nuevo['nombre']}» queda guardado y se verá al volver a abrir "
                          f"Bridge: {motivos[0]}. Mientras tanto la ventana sigue entera en "
                          f"«{viejo['nombre']}».")}
    _tema_poner(nuevo)
    _TEMA["fue_oscuro"] = _TEMA.get("fue_oscuro") or viejo["tipo"] == "oscuro"
    _TEMA["aplicando"] = True
    # Mientras se re-pinta (CTk tarda unos segundos), una tapa del tema nuevo:
    # nunca se ve la ventana mitad clara y mitad oscura.
    tapa = None
    try:
        _root.update_idletasks()
        tapa = tk.Toplevel(_root)
        tapa.overrideredirect(True)
        tapa.configure(bg=THEME["bg"])
        tapa.geometry(f"{_root.winfo_width()}x{_root.winfo_height()}+{_root.winfo_rootx()}+"
                      f"{_root.winfo_rooty()}")
        tk.Label(tapa, text=f"Cambiando a «{nuevo['nombre']}»…", font=(FONT, 12),
                 bg=THEME["bg"], fg=THEME["muted"]).place(relx=0.5, rely=0.45, anchor="center")
        tapa.attributes("-topmost", True)
        tapa.update()
    except Exception:
        tapa = None
    hechos, fallos = 0, []
    try:
        hechos, fallos = _tema_ejecutar(plan)
        try:
            _theme_styles(ttk.Style())
        except Exception as e:
            fallos.append(f"ttk: {type(e).__name__}: {e}")
        ctk = sys.modules.get("customtkinter")
        if ctk is not None:
            try:
                ctk.set_appearance_mode("dark" if _THEME_STATE["dark"] else "light")
            except Exception as e:
                fallos.append(f"CustomTkinter: {type(e).__name__}: {e}")
        # Tambien las minimizadas u ocultas (la paleta Ctrl+K): si no, al
        # volver a verse traerian la barra de titulo del tema viejo.
        for w in _tema_widgets(_root):
            try:
                if w is not tapa and w.winfo_class() in ("Tk", "Toplevel"):
                    _dark_titlebar(w, forzar=True)
            except Exception:
                pass
        try:
            show = _widgets.get("show_page")
            if show and _widgets.get("pagina_actual"):
                show(_widgets["pagina_actual"])  # la pagina activa de la barra lateral
            refresh_ui()
        except Exception:
            pass
    finally:
        _TEMA["aplicando"] = False
        if tapa is not None:
            try:
                tapa.destroy()
            except Exception:
                pass
    _TEMA["pendiente"] = None
    ms = (time.perf_counter() - t0) * 1000
    _TEMA["ultimo"] = {"estado": "aplicado", "cambios": hechos, "fallos": fallos, "ms": ms}
    log(f"temas: {viejo['nombre']} -> {nuevo['nombre']} en caliente ({origen}): {hechos} "
        f"cambios en {ms:.0f} ms" + (f"; fallos: {fallos[:3]}" if fallos else ""))
    return {"estado": "aplicado", "cambios": hechos, "fallos": fallos, "ms": ms,
            "texto": f"Listo: ahora usas «{nuevo['nombre']}»."}


# ---- Ajustes -> Apariencia: Claro / Oscuro / Segun el sistema (como VS Code)
TEMA_MODOS = (("claro", "Claro"), ("oscuro", "Oscuro"), ("sistema", "Según el sistema"))


def tema_estado_texto():
    t = _TEMA["actual"]
    modo = tema_modo()
    txt = f"Ahora: {t['nombre']} ({t['archivo']})."
    if modo == "sistema":
        txt += f" Sigue a Windows, que usa el modo {'oscuro' if _system_dark() else 'claro'}."
    if _TEMA["pendiente"]:
        p = _TEMA["temas"].get(_TEMA["pendiente"])
        txt += f" Al volver a abrir Bridge: {p['nombre'] if p else _TEMA['pendiente']}."
    return txt


def tema_elegir(modo=None, tid=None):
    """Lo que hace el selector: guarda en settings.json y aplica en caliente."""
    s = load_settings()
    if tid:
        t = _TEMA["temas"].get(tid)
        if t is None:
            return {"estado": "error", "texto": f"El tema «{tid}» ya no está en la carpeta temas."}
        s["tema_" + t["tipo"]] = tid
        modo = t["tipo"]  # elegir por nombre deja ese tema a la vista
    if modo:
        s["apariencia"] = modo
    save_settings(s)
    if "apariencia" in _widgets:
        try:
            _widgets["apariencia"].set(tema_modo(s))
        except Exception:
            pass
    ntid, por = tema_resolver(s=s)
    r = tema_aplicar(ntid, "ajustes")
    if por and "no hay" in por:
        r["texto"] = por[0].upper() + por[1:] + ". " + r.get("texto", "")
    log(f"ajustes: apariencia {tema_modo(s)} -> {ntid} ({r['estado']})")
    _tema_pintar_selector(r)
    if r["estado"] == "reinicio":
        try:
            messagebox.showinfo("Cambiar el tema", r["texto"] + "\n\nCierra Bridge desde la "
                                "bandeja (Salir) y vuelve a abrirlo para verlo.")
        except Exception:
            pass
    return r


def tema_al_abrir_ajustes():
    """Al volver a Ajustes: relee temas\\ y, con «Según el sistema», Windows."""
    if _TEMA.get("aplicando"):
        return
    try:
        tema_cargar()
        r = {"estado": "igual", "texto": ""}  # el mensaje de la vez anterior se va
        if tema_modo() == "sistema" or _TEMA["actual"]["id"] not in _TEMA["temas"]:
            tid, _por = tema_resolver()
            if tid != _TEMA["actual"]["id"] and tid != _TEMA["pendiente"]:
                r = tema_aplicar(tid, "sistema")
                if r["estado"] == "aplicado":
                    r["texto"] = (f"Windows cambió de modo: ahora usas «{_TEMA['actual']['nombre']}».")
        _tema_pintar_selector(r)
    except Exception as e:
        log(f"temas: no se pudo releer ({type(e).__name__}: {e})")


def _tema_nombres():
    return [(k, f"{t['nombre']} ({'claro' if t['tipo'] == 'claro' else 'oscuro'})")
            for k, t in sorted(_TEMA["temas"].items(), key=lambda kv: (kv[1]["tipo"], kv[1]["nombre"]))]


def _tema_pintar_selector(r=None):
    k = _widgets.get("tema_kit")
    if k is None:
        return
    try:
        modo = tema_modo()
        seg = _widgets["tema_seg"]
        if hasattr(seg, "var"):
            seg.var.set(modo)
        else:
            seg.set(dict(TEMA_MODOS)[modo])
        noms = _tema_nombres()
        k.set_values(_widgets["tema_opcion"], [n for _i, n in noms])
        actual = dict(noms).get(_TEMA["pendiente"] or _TEMA["actual"]["id"], "")
        _widgets["tema_opcion"].set(actual)
        k.set_label(_widgets["tema_estado"], tema_estado_texto())
        errs = _TEMA["errores"]
        k.set_label(_widgets["tema_errores"], "\n".join(
            f"No se cargó «{n}»: {m}." for n, m in errs) if errs else "", "red")
        if r is not None:
            col = {"aplicado": "green_text", "igual": "muted", "reinicio": "orange_text"}.get(
                r["estado"], "red")
            k.set_label(_widgets["tema_msg"], r.get("texto", ""), col)
    except Exception as e:
        log(f"temas: selector ({type(e).__name__}: {e})")


def tema_seccion(k, parent):
    """Selector de Apariencia dentro de una fila de Ajustes (kit CTk o tk)."""
    if not _TEMA["temas"]:
        tema_cargar()
    _widgets["tema_kit"] = k
    _widgets["apariencia"] = tk.StringVar(value=tema_modo())
    seg = k.segmented(parent, TEMA_MODOS, lambda m: tema_elegir(modo=m))
    seg.pack(anchor="w", pady=(10, 0))
    _widgets["tema_seg"] = seg
    fila = k.frame(parent)
    fila.pack(anchor="w", fill="x", pady=(10, 0))
    k.label(fila, "Tema por nombre", muted=True, wrap=0).pack(side="left", padx=(0, 10))
    ids = dict((n, i) for i, n in _tema_nombres())
    op = k.option(fila, [n for n in ids], command=lambda n: tema_elegir(
        tid=dict((nn, i) for i, nn in _tema_nombres()).get(n)), width=26)
    op.pack(side="left")
    k.button(fila, "Abrir la carpeta de temas", lambda: (
        TEMAS_DIR.mkdir(exist_ok=True), open_folder(TEMAS_DIR))).pack(side="left", padx=(10, 0))
    _widgets["tema_opcion"] = op
    _widgets["tema_estado"] = k.label(parent, "", muted=True)
    _widgets["tema_estado"].pack(anchor="w", fill="x", pady=(8, 0))
    _widgets["tema_msg"] = k.label(parent, "", muted=True)
    _widgets["tema_msg"].pack(anchor="w", fill="x", pady=(2, 0))
    _widgets["tema_errores"] = k.label(parent, "", color="red")
    _widgets["tema_errores"].pack(anchor="w", fill="x", pady=(2, 0))
    _tema_pintar_selector()


# ---- avisos (toasts): solo lo que importa, <50 letras, clic = su contexto
def toast(text, ctx=None):
    text = str(text)
    if len(text) > 49:
        text = text[:48].rstrip() + "…"
    _TOAST["ctx"] = ctx
    try:
        if _tray_icon is not None:
            _tray_icon.notify(text, "Growi Bridge")
    except Exception:
        pass


def _short(name, n=22):
    name = str(name or "")
    return name if len(name) <= n else name[:n - 1] + "…"


def _open_ctx(ctx):
    """Abre la ventana en el sitio exacto del aviso."""
    show_window()
    show = _widgets.get("show_page")
    if not show:
        return
    if not ctx:
        return
    kind = ctx[0]
    if kind == "tareas":
        show("tareas")
        tree = _widgets.get("tasks_tree")
        if tree is not None and len(ctx) > 1 and ctx[1] in _tasks_rows:
            try:
                tree.selection_set(ctx[1])
                tree.see(ctx[1])
            except Exception:
                pass
    elif kind in ("estado", "proxy", "mapa"):
        show("estado")
    elif kind == "gasto":
        show("tareas")
    elif kind == "modelos":
        show("modelos")


# ---- sondas de red (con y sin el proxy, nunca con el proxy de las variables)
def _probe(url, via_proxy=False, timeout=8, headers=None, max_body=600):
    """(codigo HTTP o None, cuerpo corto, ms, error legible)."""
    if via_proxy:
        purl = proxy_url()
        if not purl:
            return None, "", 0, "no hay proxy guardado"
        handler = urllib.request.ProxyHandler({"http": purl, "https": purl})
    else:
        handler = urllib.request.ProxyHandler({})
    opener = urllib.request.build_opener(handler)
    req = urllib.request.Request(url, headers=dict({"User-Agent": "GrowiBridge"}, **(headers or {})))
    t0 = time.time()
    try:
        with opener.open(req, timeout=timeout) as r:
            body = r.read(max_body).decode("utf-8", "replace")
            return r.status, body, int((time.time() - t0) * 1000), ""
    except urllib.error.HTTPError as e:
        try:
            body = e.read(max_body).decode("utf-8", "replace")
        except Exception:
            body = ""
        return e.code, body, int((time.time() - t0) * 1000), ""
    except Exception as e:
        return None, "", int((time.time() - t0) * 1000), _net_reason(e)


def _net_reason(e):
    s = f"{type(e).__name__}: {e}"
    low = s.lower()
    if "407" in low or "proxy authentication" in low:
        return "el proxy rechazó tu usuario o clave"
    if "timed out" in low or "timeout" in low:
        return "no contesta (tiempo agotado)"
    if "getaddrinfo" in low or "name or service" in low or "11001" in low:
        return "no encuentro la dirección (¿sin internet?)"
    if "refused" in low or "10061" in low:
        return "rechaza la conexión"
    if "tunnel connection failed" in low:
        return "el proxy no deja pasar (" + s.split("Tunnel connection failed:")[-1].strip()[:40] + ")"
    if "10060" in low or "unreachable" in low:
        return "no se puede llegar"
    return s[:90]


def load_availability():
    try:
        d = json.loads(AVAIL_FILE.read_text(encoding="utf-8"))
        if isinstance(d, dict) and isinstance(d.get("filas"), list):
            return d
    except (OSError, ValueError):
        pass
    return None


def _country_name(cfg, code):
    return (cfg.get("paises") or {}).get(code or "", code or "un país desconocido")


def _ip_country(cfg, via_proxy):
    for url in cfg.get("ip_info") or []:
        code, body, ms, err = _probe(url, via_proxy, timeout=cfg.get("timeout_s", 8))
        if code == 200:
            try:
                d = json.loads(body if body.strip().endswith("}") else body + "}")
            except ValueError:
                m = re.search(r'"country(?:_code)?"\s*:\s*"([A-Z]{2})"', body)
                d = {"country": m.group(1)} if m else {}
            c = d.get("country") or d.get("country_code") or ""
            if c:
                return c, d.get("ip") or "", ms, ""
        elif err:
            return "", "", ms, err
    return "", "", 0, "no supe el país"


def _row(fila, estado, frase, accion=None, ms=None, ruta=None, detalle=""):
    return {"id": fila["id"], "nombre": fila.get("nombre", fila["id"]), "estado": estado,
            "frase": frase, "como": fila.get("como", ""), "accion": accion, "ms": ms,
            "ruta": ruta, "detalle": detalle, "at": time.time()}


def _check_nube(cfg, fila):
    url = fila["url"]
    key = api_key_for(fila["clave"]) if fila.get("clave") in API_PROVIDERS else ""
    headers = {}
    if key and fila.get("clave_parametro"):
        url += ("&" if "?" in url else "?") + f"{fila['clave_parametro']}={key}"
    elif key:
        headers = _api_headers(fila["clave"], key)
    marks = [m.lower() for m in fila.get("bloqueo_marcas") or []]
    res, det = {}, []
    routes = [("directo", False)] + ([("proxy", True)] if proxy_url() else [])
    for name, via in routes:
        code, body, ms, err = _probe(url, via, timeout=cfg.get("timeout_s", 8), headers=headers)
        body_l = _scrub(body, key).lower()
        if err:
            res[name] = ("sin_respuesta", ms, err)
        elif any(m in body_l for m in marks):
            res[name] = ("bloqueado", ms, f"HTTP {code}")
        elif code in (fila.get("ok_codigos") or [200]):
            res[name] = ("ok", ms, f"HTTP {code}")
        elif not key and code in (fila.get("sin_clave_codigos") or []):
            res[name] = ("sin_clave", ms, f"HTTP {code}")
        else:
            res[name] = ("raro", ms, f"HTTP {code}")
        det.append(f"{name}: {res[name][0]} ({res[name][2]}, {ms} ms)")
    d, p = res.get("directo"), res.get("proxy")
    detalle = "; ".join(det)
    if d and d[0] == "ok":
        return _row(fila, "ok", fila.get("frase_ok", "Responde."), ("usar", "Usar"), d[1], "directo", detalle)
    if d and d[0] == "sin_clave":
        # Un motor que entra sin clave (sesion propia de su programa) vale
        # igual: entonces la fila lo dice en vez de pedir la clave en APIs.
        mot = get_engine(fila["motor"]) if fila.get("motor") else None
        if mot is not None:
            acc = acceso_motor(mot)
            if acc["ok"] and acc["modo"] == "sesion_cli":
                return _row(fila, "ok", fila.get("frase_motor_ok", "Responde por su programa, sin clave."),
                            ("usar", "Usar"), d[1], "directo", detalle + f"; motor {fila['motor']}: {acc['motivo']}")
            detalle += f"; motor {fila['motor']}: {acc['motivo'][:160]}"
        return _row(fila, "aviso", fila.get("frase_sin_clave", "Responde, falta tu clave."),
                    ("clave", "Poner clave"), d[1], "directo", detalle)
    if p and p[0] in ("ok", "sin_clave"):
        return _row(fila, "ok" if state.get("proxy_on") else "aviso",
                    fila.get("frase_solo_proxy", "Solo responde con el proxy."),
                    ("usar", "Usar"), p[1], "proxy", detalle)
    if any(x and x[0] == "bloqueado" for x in (d, p)):
        return _row(fila, "falla", fila.get("frase_bloqueado", "Bloqueado."), ("porque", "Ver por qué"),
                    None, None, detalle)
    why = (p or d)[2] if (p or d) else "sin datos"
    return _row(fila, "falla", f"No responde ({why}). La ruta que sí anda: el modelo local.",
                ("reintentar", "Reintentar"), None, None, detalle)


def _check_ollama(cfg, fila):
    code, body, ms, err = _probe(fila["url"], False, timeout=4, max_body=200000)
    if code == 200:
        try:
            models = [m.get("name") for m in json.loads(body).get("models") or []]
        except ValueError:
            models = []
        if models:
            names = ", ".join(friendly_model_name(m) for m in models[:2])
            return _row(fila, "ok", fila.get("frase_ok", "").format(n=len(models)) + f" ({names})",
                        ("usar", "Usar"), ms, "local", f"HTTP 200, {len(models)} modelos")
        return _row(fila, "aviso", fila.get("frase_sin_modelo", "Sin modelos."),
                    ("descargar", "Descargar modelo"), ms, "local", "HTTP 200, 0 modelos")
    return _row(fila, "falla", fila.get("frase_caido", "No responde."), ("reintentar", "Reintentar"),
                None, None, err or f"HTTP {code}")


def _check_proxy(cfg, fila):
    pc = proxy_config()
    if not pc.get("host") or not proxy_url():
        return _row(fila, "aviso", fila.get("frase_sin_proxy", "Sin proxy."), ("avanzado", "Ajustes"),
                    None, None, "no hay host ni clave guardados")
    t0 = time.time()
    try:
        socket.create_connection((pc["host"], int(pc["port"])), timeout=cfg.get("timeout_s", 8)).close()
    except Exception as e:
        motivo = f"no llego a {pc['host']}:{pc['port']} ({_net_reason(e)})"
        return _row(fila, "falla", fila.get("frase_caido", "{motivo}").format(motivo=motivo),
                    ("reintentar", "Reintentar"), None, None, motivo)
    tcp_ms = int((time.time() - t0) * 1000)
    code, ip, ms, err = _ip_country(cfg, True)
    if err or not code:
        motivo = err or "no supe por qué país sales"
        return _row(fila, "falla", fila.get("frase_caido", "{motivo}").format(motivo=motivo),
                    ("reintentar", "Reintentar"), None, None, f"TCP ok {tcp_ms} ms; {motivo}")
    pais = _country_name(cfg, code)
    _AV["country_proxy"] = code
    return _row(fila, "ok", fila.get("frase_ok", "Conectado.").format(pais=pais), ("probar", "Probar"),
                ms, "proxy", f"TCP {tcp_ms} ms; IP de salida {ip} ({code})")


def _check_internet(cfg, fila):
    best = None
    for url in fila.get("urls") or []:
        code, body, ms, err = _probe(url, False, timeout=cfg.get("timeout_s", 8))
        if code:
            best = (ms, url, code)
            break
    if not best:
        return _row(fila, "falla", fila.get("frase_caido", "Sin internet."), ("reintentar", "Reintentar"),
                    None, None, "ninguna página respondió")
    code, ip, _ms, _err = _ip_country(cfg, False)
    _AV["country_direct"] = code
    return _row(fila, "ok", fila.get("frase_ok", "Hay internet.").format(pais=_country_name(cfg, code)),
                ("reintentar", "Reintentar"), best[0], "directo", f"{best[1]}: HTTP {best[2]}")


# ---- filas «servicio» del mapa (t-mapa-ampliado): responde / no responde,
# latencia y por que via (directo / proxy / ambas), medido las dos veces.
# Lento = mas de MAPA_LENTO_MS (umbral nuevo, documentado en el ESTADO). Un
# timeout no deja la fila en blanco: «no se pudo comprobar».
MAPA_LENTO_MS = 2000


def _check_servicio(cfg, fila):
    to = cfg.get("timeout_s", 8)
    routes = [("directo", False)] + ([("proxy", True)] if proxy_url() else [])
    res, det = {}, []
    for name, via in routes:
        code, _body, ms, err = _probe(fila["url"], via, timeout=to)
        if err:
            timeout = bool(re.search(r"timed out|timeout|tard", str(err), re.I))
            res[name] = ("timeout" if timeout else "no", ms, err)
        else:
            res[name] = ("si", ms, f"HTTP {code}")
        det.append(f"{name}: {'responde' if res[name][0] == 'si' else 'sin respuesta en ' + str(to) + ' s' if res[name][0] == 'timeout' else 'no responde'} "
                   f"({res[name][2]}, {ms} ms)")
    if not proxy_url():
        det.append("proxy: sin proxy guardado, no se mide")
    si = {k: v for k, v in res.items() if v[0] == "si"}
    detalle = "; ".join(det)
    if not si:
        if all(v[0] == "timeout" for v in res.values()):
            return _row(fila, "falla", f"No se pudo comprobar en {to} s.", ("reintentar", "Reintentar"), None, None,
                        detalle)
        return _row(fila, "falla", "No responde ni directo ni por el proxy.", ("reintentar", "Reintentar"), None,
                    None, detalle)
    via = "ambas" if len(si) == 2 else next(iter(si))
    ms = min(v[1] for v in si.values())
    lento = ms > MAPA_LENTO_MS
    frase = {"ambas": "Responde directo y por el proxy", "directo": "Responde solo directo",
             "proxy": "Responde solo por el proxy"}[via] + f" ({ms} ms)" + (
        f": lento (más de {MAPA_LENTO_MS / 1000:g} s)" if lento else "") + "."
    return _row(fila, "aviso" if lento or via == "proxy" else "ok", frase, ("reintentar", "Reintentar"), ms, via,
                detalle)


def mapa_fila(rid, max_edad_s=900):
    """La fila del mapa si es reciente (para el router y el descargador)."""
    r = (_AV.get("rows") or {}).get(rid)
    if r and time.time() - (r.get("at") or 0) <= max_edad_s:
        return r
    return None


def mapa_permite_nube(motor_id="claude"):
    """Regla de oro del router: si Claude solo llega por el proxy y el mapa
    tiene el proxy en rojo (o «forzar proxy» con el proxy caído), ni se intenta."""
    px, c = mapa_fila("proxy"), mapa_fila(motor_id)
    if _IPX.get("forzar") and _IPX.get("proxy_caido"):
        return False, "el proxy está caído y tienes «Forzar siempre el proxy»"
    if px and px.get("estado") == "falla" and (not c or c.get("ruta") != "directo" or c.get("estado") == "falla"):
        return False, f"el mapa tiene el proxy en rojo ({px.get('frase')}) y {motor_id} no llega directo"
    return True, ""


_CHECKERS = {"nube": _check_nube, "ollama": _check_ollama, "proxy": _check_proxy,
             "internet": _check_internet, "servicio": _check_servicio}


def run_availability(only=None):
    """Comprueba de verdad cada fila de availability.json (en hilos)."""
    cfg = load_availability()
    if cfg is None:
        with _AV["lock"]:
            _AV["rows"] = {"_falta": {"id": "_falta", "nombre": "Mapa", "estado": "falla",
                                      "frase": "Falta availability.json junto al programa.",
                                      "como": "", "accion": None, "ms": None, "ruta": None,
                                      "detalle": "", "at": time.time()}}
        return
    filas = [f for f in cfg["filas"] if not only or f["id"] in only]
    out = {}

    def one(f):
        fn = _CHECKERS.get(f.get("tipo"))
        try:
            out[f["id"]] = fn(cfg, f) if fn else _row(f, "falla", "Tipo de fila desconocido.")
        except Exception as e:
            out[f["id"]] = _row(f, "falla", f"No pude comprobarlo ({type(e).__name__}).",
                                ("reintentar", "Reintentar"))
    ths = [threading.Thread(target=one, args=(f,), daemon=True) for f in filas]
    for t in ths:
        t.start()
    for t in ths:
        t.join(30)
    with _AV["lock"]:
        _AV["rows"].pop("_falta", None)
        _AV["rows"].update(out)
        _AV["at"] = time.time()
        _AV["order"] = [f["id"] for f in cfg["filas"]]
    log("disponibilidad: " + ", ".join(f"{k} {v['estado']}" for k, v in out.items()))


def start_availability(only=None, done=None):
    if _AV["running"]:
        return False
    _AV["running"] = True

    def _run():
        try:
            run_availability(only)
        finally:
            _AV["running"] = False
            _ui_call(_after_availability)
            if done:
                _ui_call(done)
    threading.Thread(target=_run, daemon=True).start()
    _ui_call(_render_avail)  # se llama también desde el hilo del mapa: Tk solo en el de la ventana
    return True


def _availability_loop():
    time.sleep(3)
    while True:
        start_availability()
        cfg = load_availability() or {}
        time.sleep(max(2, int(cfg.get("cada_min") or 10)) * 60)


def conn_state():
    """conectado (la nube responde por la ruta en uso) / local (solo el
    modelo local) / sin (nada) / None (aun sin comprobar)."""
    rows = _AV["rows"]
    if not rows or "claude" not in rows:
        return None
    c, o = rows.get("claude") or {}, rows.get("ollama") or {}
    route_ok = c.get("estado") in ("ok", "aviso") and (
        c.get("ruta") == "directo" or (c.get("ruta") == "proxy" and state.get("proxy_on")))
    # «Forzar siempre el proxy» con el proxy caído: no hay ruta a la nube
    # aunque la directa conteste (forzado = nunca directo). Ver t-ip-estable.
    if _IPX.get("forzar") and _IPX.get("proxy_caido"):
        route_ok = False
    if route_ok:
        return "conectado"
    if o.get("estado") == "ok":
        return "local"
    return "sin"


def conn_text():
    st = conn_state()
    p = (_AV["rows"].get("proxy") or {})
    if st is None:
        return "○ Comprobando la conexión…"
    if st == "conectado":
        if state.get("proxy_on") and p.get("estado") == "ok":
            pais = _country_name(load_availability() or {}, _AV.get("country_proxy"))
            return f"● Conectado — sales por {pais}"
        return "● Conectado"
    if st == "local":
        return "● Solo local (sin nube)"
    return "● Sin conexión"


def _conn_color():
    return {"conectado": THEME["green_text"], "local": THEME["orange_text"],
            "sin": THEME["red"]}.get(conn_state(), THEME["muted"])


def _after_availability():
    st = conn_state()
    prev = _AV.get("last_conn")
    _AV["last_conn"] = st
    if st in ("local", "sin"):
        _AV["nube_fallos"] = _AV.get("nube_fallos", 0) + 1
        if _AV["nube_fallos"] == 1:  # un fallo suelto no alarma: se comprueba otra vez a los 20 s
            t = threading.Timer(20, lambda: start_availability(only=["claude"]))
            t.daemon = True
            t.start()
    elif st == "conectado":
        _AV["nube_fallos"] = 0
    # el aviso sale del estado único: con el runner trabajando en la nube ahora mismo no hay alarma (t-estado-consistencia-045)
    callar = _runner_en_nube_ahora()
    if st == "local" and prev != "local":
        state["nube_caida"] = True
        log("conexión: sin nube; las preguntas de la app van al modelo local")
        if not callar:
            toast("Sin nube: uso el modelo local", ("estado",))
    elif st == "sin" and prev not in ("sin", None):
        state["nube_caida"] = True
        if not callar:
            toast("Sin conexión: ni nube ni modelo local", ("estado",))
    elif st == "conectado":
        if state.get("nube_caida"):
            log("conexión: la nube volvió")
        state["nube_caida"] = False
    _render_avail()
    _refresh_conn_widgets()


# ---------------------------------------------------------------- Salida estable (t-ip-estable)
# Una sola IP de salida estable es la defensa nº 1 frente a los bloqueos por
# cambios de IP o de región. Al arrancar: la IP de salida (y su país) en
# Estado, comparación con la última registrada (ip-salida.json), aviso si
# cambió (Forzar el proxy / Seguir así), ajuste «Forzar siempre el proxy del
# VPS», registro de cada cambio (ip-cambios.log) y detector de Avast VPN (el
# servicio de Windows, buscado por nombre, no asumido) con registro de las
# caídas del túnel (tunel-caidas.log). El detector de Avast vive aquí:
# t-detector-avast no se construye aparte. Nada de esto es un motor: son
# llamadas HTTP cortas y consultas al sistema. El silencio nunca es
# consentimiento: sin respuesta de Leandro no se cambia nada solo.
# ip-salida.json e ip-cambios.log van en share\inbox\ (ahí los busca la
# revisión); en las pruebas aisladas, en la share de la copia.
IPX_FILE = INBOX / "ip-salida.json"
IPX_LOG = INBOX / "ip-cambios.log"
TUNEL_LOG = APP_DIR / "tunel-caidas.log"
# Solo IPv4: ifconfig.me por el proxy devolvía la IPv6 del VPS (2a02:4780:…),
# que no casa con 2.25.244.222 y daría un «cambio» falso (visto el 27 oct).
IPX_URLS = ["https://ipinfo.io/json", "https://api.ipify.org?format=json", "https://ipv4.icanhazip.com"]
IPX_PAIS_URLS = ["https://api.country.is/{ip}", "https://ipinfo.io/{ip}/country"]
IPX_TIMEOUT = 5
IPX_VIGIA_S = 30
_IPX = {"det": None, "res": None, "busy": False, "forzar": False, "aviso_forzado": False,
        "proxy_caido": None, "avast": None, "avast_aviso": False, "avast_dejado": False,
        "avast_msg": "", "tunel": None, "msg": "", "kit": None, "kit_av": None,
        "lock": threading.Lock()}


def _ipx_ruta():
    """La ruta que usa ahora el tráfico de la app y del runner hacia Claude:
    el proxy de las variables (HTTPS_PROXY) o directo."""
    url = os.environ.get("HTTPS_PROXY") or os.environ.get("https_proxy") or ""
    return ("proxy", url) if url else ("directo", "")


def ipx_detectar(via=None):
    """IP pública de salida con una petición corta (timeout IPX_TIMEOUT por
    servicio). via = (ruta, url_del_proxy); por defecto la ruta en uso. Si
    TODO falla por tiempo agotado, un segundo intento con 15 s: el proxy del
    VPS a veces tarda ~13 s en la primera conexión (medido con curl, 27 oct)."""
    det = _ipx_detectar_una(via, IPX_TIMEOUT)
    if not det["ok"] and det.get("solo_tiempo"):
        det2 = _ipx_detectar_una(via, 15)
        det2["ms"] += det["ms"]
        if not det2["ok"]:
            det2["causa"] = "2 intentos; " + det2["causa"]
        det = det2
    det.pop("solo_tiempo", None)
    return det


def _ipx_detectar_una(via, timeout):
    ruta, purl = via or _ipx_ruta()
    opener = urllib.request.build_opener(
        urllib.request.ProxyHandler({"http": purl, "https": purl} if purl else {}))
    errores = []
    t0 = time.time()
    for url in IPX_URLS:
        host = urlparse(url).hostname or url
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "GrowiBridge", "Accept": "application/json"})
            with opener.open(req, timeout=timeout) as r:
                body = r.read(4000).decode("utf-8", "replace").strip()
        except urllib.error.HTTPError as e:
            errores.append(f"{host}: HTTP {e.code}")
            continue
        except Exception as e:
            errores.append(f"{host}: {_net_reason(e)}")
            continue
        ip, pais, org = "", "", ""
        if body.startswith("{"):
            try:
                d = json.loads(body)
            except ValueError:
                d = {}
            ip, pais, org = str(d.get("ip") or ""), str(d.get("country") or ""), str(d.get("org") or "")
        elif body:
            ip = body.split()[0]
        if re.fullmatch(r"\d{1,3}(\.\d{1,3}){3}", ip):
            if not pais:  # el servicio solo dio la IP: el país aparte (petición corta)
                pais = _ipx_pais_de(opener, ip)
            return {"ok": True, "ip": ip, "pais": pais, "org": org, "ruta": ruta, "servicio": host,
                    "ms": int((time.time() - t0) * 1000), "at": _now_iso()}
        errores.append(f"{host}: la respuesta no trae una IP")
    return {"ok": False, "ruta": ruta, "causa": "; ".join(errores) or "ningún servicio respondió",
            "solo_tiempo": bool(errores) and all("tiempo agotado" in x for x in errores),
            "ms": int((time.time() - t0) * 1000), "at": _now_iso()}


def _ipx_pais_de(opener, ip):
    for url in IPX_PAIS_URLS:
        try:
            req = urllib.request.Request(url.format(ip=ip), headers={"User-Agent": "GrowiBridge"})
            with opener.open(req, timeout=IPX_TIMEOUT) as r:
                body = r.read(500).decode("utf-8", "replace").strip()
        except Exception:
            continue
        m = re.search(r'"country"\s*:\s*"([A-Z]{2})"', body) or re.fullmatch(r"([A-Z]{2})", body)
        if m:
            return m.group(1)
    return ""


def _ipx_org_corta(org):
    o = re.sub(r"^AS\d+\s+", "", str(org or "")).strip()
    return re.sub(r",?\s*(C\.A\.|S\.A\.|Inc\.?|Ltd\.?|Limited|LLC)\s*$", "", o, flags=re.I).strip()


def _ipx_pais(code):
    return _country_name(load_availability() or {}, code) if code else "país desconocido"


def _ipx_vps():
    """(host, ip) del proxy del VPS guardado (proxy.json)."""
    host = str(proxy_config().get("host") or "")
    try:
        return host, (socket.gethostbyname(host) if host else "")
    except OSError:
        return host, host


def _ipx_es_vps(ip):
    host, hip = _ipx_vps()
    return bool(ip) and ip in (host, hip)


def _ipx_dice(d):
    """«EEUU (2.25.244.222)»: país e IP, siempre las dos."""
    return f"{_ipx_pais(d.get('pais'))} ({d.get('ip')})"


def ipx_texto(det=None):
    det = det if det is not None else _IPX.get("det")
    if not det:
        return "IP de salida: comprobando…"
    if not det.get("ok"):
        return f"IP de salida: no se pudo detectar ({det.get('causa')})."
    pais = _ipx_pais(det.get("pais"))
    if _ipx_es_vps(det["ip"]):
        return f"Sales por {det['ip']} ({pais}, proxy VPS)"
    if det.get("ruta") == "proxy":
        return f"Sales por {det['ip']} ({pais}, por un proxy que no es tu VPS)"
    org = _ipx_org_corta(det.get("org"))
    return (f"Sales por tu IP de {org} ({pais}, sin proxy): {det['ip']}" if org
            else f"Sales por {det['ip']} ({pais}, sin proxy)")


def _ipx_leer():
    try:
        d = json.loads(IPX_FILE.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}


def _ipx_guardar(d):
    tmp = IPX_FILE.with_name(IPX_FILE.name + ".tmp")
    tmp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(tmp, IPX_FILE)


def _ipx_ahora():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _ipx_append(path, linea):
    try:
        with open(path, "a", encoding="utf-8") as f:
            f.write(linea + "\n")
    except OSError as e:
        log(f"salida: no pude escribir {path.name} ({e})")


def _ipx_lineas(path, prefijo=None):
    try:
        ls = [x for x in path.read_text(encoding="utf-8").splitlines() if x.strip()]
    except OSError:
        return []
    return [x for x in ls if prefijo is None or prefijo in x]


def _ipx_reinicio_desde(iso):
    """True si Windows arrancó después de esa fecha (apagón o reinicio)."""
    try:
        import psutil
        return psutil.boot_time() > datetime.fromisoformat(iso).timestamp()
    except Exception:
        return False


def _ipx_causa(ant, nueva, motivo=None):
    if motivo:
        return motivo
    if any(s.get("estado") == "running" for s in ((_IPX.get("avast") or {}).get("servicios") or [])):
        return "Avast VPN activo"
    if ant.get("ruta") == "proxy" and nueva.get("ruta") == "directo":
        return "proxy apagado o caído (ahora sales directo)"
    if ant.get("ruta") == "directo" and nueva.get("ruta") == "proxy":
        return "proxy encendido"
    if _ipx_reinicio_desde(ant.get("fecha") or ""):
        return "apagón o reinicio del PC desde el último registro"
    a, n = _ipx_org_corta(ant.get("org")), _ipx_org_corta(nueva.get("org"))
    if a and n and a != n:
        return f"cambio de red ({a} → {n})"
    if a and a == n:
        return f"tu proveedor ({n}) te dio otra IP"
    return "desconocida"


def ipx_comparar(det, motivo=None, avisar=True):
    """Compara con la última IP registrada. Devuelve primera | igual | cambio
    | sin_dato. Cada cambio va a ip-cambios.log; si no lo causó una acción
    tuya, deja un aviso pendiente que solo se quita cuando eliges."""
    if not det or not det.get("ok"):
        return "sin_dato"
    nueva = {"ip": det["ip"], "pais": det.get("pais") or "", "org": det.get("org") or "",
             "ruta": det.get("ruta"), "fecha": det["at"]}
    with _IPX["lock"]:
        reg = _ipx_leer()
        ant = reg.get("ultima") if isinstance(reg.get("ultima"), dict) else None
        if not ant or not ant.get("ip"):
            reg["ultima"] = nueva
            reg["primera_vez"] = det["at"]
            reg.setdefault("cambios", 0)
            if not IPX_LOG.exists():  # el registro existe desde el primer arranque (sin contar como cambio)
                _ipx_append(IPX_LOG, f"# {_ipx_ahora()} registro iniciado: referencia {det['ip']} "
                                     f"({_ipx_pais(det.get('pais'))}, {det.get('ruta')}); aquí va una línea por "
                                     "cada cambio de IP de salida")
            res = "primera"
        elif ant["ip"] == det["ip"]:
            ant.update({k: v for k, v in nueva.items() if v})
            reg["ultima"] = ant
            res = "igual"
        else:
            causa = _ipx_causa(ant, nueva, motivo)
            _ipx_append(IPX_LOG, f"{_ipx_ahora()} | anterior {ant['ip']} ({_ipx_pais(ant.get('pais'))}, "
                                 f"{ant.get('ruta') or '?'}) | nueva {nueva['ip']} ({_ipx_pais(nueva['pais'])}, "
                                 f"{nueva['ruta']}) | causa: {causa}")
            reg["ultima"] = nueva
            reg["cambios"] = int(reg.get("cambios") or 0) + 1
            prev = reg.get("aviso_pendiente")
            if prev and (prev.get("anterior") or {}).get("ip") == nueva["ip"]:
                reg.pop("aviso_pendiente", None)  # volviste a la de antes: ya no hay cambio
                avisar = None  # para el log: el aviso se quitó solo
            elif avisar:
                reg["aviso_pendiente"] = {"anterior": (prev or {}).get("anterior") or ant, "nueva": nueva,
                                          "causa": causa, "desde": det["at"]}
            res = "cambio"
        reg["ultimo_resultado"] = res
        _ipx_guardar(reg)
    if res == "primera":
        log(f"salida: primera vez; guardo {det['ip']} ({_ipx_pais(det.get('pais'))}) como referencia, sin aviso")
    elif res == "igual":
        log(f"salida: la misma IP que la última vez ({det['ip']}); solo actualizo la fecha")
    else:
        log(f"salida: CAMBIÓ de {ant['ip']} a {det['ip']} (causa: {causa})"
            + ("; aviso en Estado hasta que elijas" if avisar else
               "; volviste a la IP de antes del aviso: el aviso se quita solo" if avisar is None else ""))
    return res


def ipx_aviso_pendiente():
    return _ipx_leer().get("aviso_pendiente")


def _ipx_proxy_vivo():
    """(True, det) si el proxy del VPS deja salir; (False, motivo) si no."""
    pc = proxy_config()
    purl = proxy_url()
    if not pc.get("host") or not purl:
        return False, "no hay proxy guardado (host y clave)"
    try:
        socket.create_connection((pc["host"], int(pc["port"])), timeout=IPX_TIMEOUT).close()
    except Exception as e:
        return False, f"no llego a {pc['host']}:{pc['port']}, {_net_reason(e)}"
    det = ipx_detectar(("proxy", purl))
    if not det.get("ok"):
        return False, f"{pc['host']}:{pc['port']} acepta la conexión pero no deja salir: {det['causa']}"
    return True, det


def _ipx_internet_directo():
    for url in ("https://www.google.com/generate_204", "https://1.1.1.1/"):
        code, _b, _ms, _e = _probe(url, False, timeout=IPX_TIMEOUT)
        if code:
            return True
    return False


def _ipx_causa_caida(camino):
    if any(s.get("estado") == "running" for s in ((_IPX.get("avast") or {}).get("servicios") or [])):
        return "Avast (Avast VPN está activo)"
    if not _ipx_internet_directo():
        return "red (este PC no tiene internet)"
    if camino.startswith("proxy"):
        return "VPS (internet sí anda, el VPS no responde)"
    return "VPS o Tailscale (internet sí anda)"


def tunel_registrar(camino, causa, detalle=""):
    _ipx_append(TUNEL_LOG, f"{_ipx_ahora()} | cayó: {camino} | causa probable: {causa}"
                + (f" | {detalle}" if detalle else ""))
    log(f"salida: caída de {camino} (causa probable: {causa}) apuntada en {TUNEL_LOG.name}")


def _ipx_proxy_caido(motivo):
    """Proxy forzado y caído: no se inventa conexión. Aviso, modo local
    (lo mismo que la 0.2.0 cuando cae la nube) y registro con la causa."""
    nuevo = not _IPX.get("proxy_caido")
    _IPX["proxy_caido"] = {"motivo": motivo, "at": _now_iso()}
    state["nube_caida"] = True
    if nuevo:
        pc = proxy_config()
        causa = _ipx_causa_caida("proxy")
        tunel_registrar(f"proxy VPS ({pc.get('host')}:{pc.get('port')})", causa, motivo)
        log(f"salida: proxy caído ({motivo}); paso a modo local (modelo local) con aviso")
        toast("Se cayó el proxy. Trabajo con el modelo local.", ("estado",))
    _ui_call(_after_availability)


def _ipx_proxy_volvio():
    if _IPX.get("proxy_caido"):
        desde = _IPX["proxy_caido"].get("at")
        _ipx_append(TUNEL_LOG, f"{_ipx_ahora()} | volvió: proxy VPS | caído desde {desde}")
        log("salida: el proxy volvió; dejo el modo local cuando la nube responda")
    _IPX["proxy_caido"] = None


def ipx_reconectar(origen="aviso"):
    """Enciende el proxy del VPS (variables de la app y del runner), comprueba
    que deja salir y vuelve a medir la salida. Se llama en un hilo."""
    ok, msg = set_proxy_mode("vps")
    if not ok:
        _ipx_proxy_caido(msg)
        return False
    vivo, info = _ipx_proxy_vivo()
    if not vivo:
        _ipx_proxy_caido(info)
        return False
    _ipx_proxy_volvio()
    _IPX["det"] = info
    ipx_comparar(info, motivo=f"forzaste el proxy ({origen})", avisar=False)
    _IPX["aviso_forzado"] = not _ipx_es_vps(info["ip"])
    _ui_call(lambda: start_availability(only=("proxy", "claude", "ollama")))
    return True


def ipx_forzar(on, origen="ajuste"):
    """Ajuste «Forzar siempre el proxy del VPS» (settings.json forzar_proxy).
    Quitarlo es un gesto y no apaga el proxy: solo deja de forzarlo."""
    s = load_settings()
    s["forzar_proxy"] = bool(on)
    save_settings(s)
    _IPX["forzar"] = bool(on)
    log(f"salida: «Forzar siempre el proxy del VPS» {'PUESTO' if on else 'QUITADO'} ({origen})")
    if not on:
        _IPX["aviso_forzado"] = False
        if _IPX.get("proxy_caido"):
            _IPX["proxy_caido"] = None
            _ui_call(_after_availability)
        _ui_call(_ipx_pintar)
        return True
    _IPX["busy"] = True
    _ui_call(_ipx_pintar)
    try:
        return ipx_reconectar(origen)
    finally:
        _IPX["busy"] = False
        _ui_call(_ipx_pintar)


def ipx_responder(eleccion):
    """Respuesta al aviso de cambio: forzar | asumo. Solo aquí se quita."""
    with _IPX["lock"]:
        reg = _ipx_leer()
        av = reg.pop("aviso_pendiente", None)
        reg["ultima_decision"] = {"eleccion": eleccion, "at": _now_iso(), "aviso": av}
        _ipx_guardar(reg)
    if av:
        log(f"salida: ante el cambio {av['anterior'].get('ip')} → {av['nueva'].get('ip')} elegiste "
            f"«{'Forzar el proxy' if eleccion == 'forzar' else 'Seguir así (lo asumo)'}»")
    if eleccion == "forzar":
        threading.Thread(target=ipx_forzar, args=(True, "aviso de cambio de IP"), daemon=True).start()
    _ipx_pintar()


def ipx_volver_a_medir():
    if _IPX["busy"]:
        return

    def _bg():
        _IPX["busy"] = True
        _ui_call(_ipx_pintar)
        try:
            det = ipx_detectar()
            _IPX["det"] = det
            _IPX["res"] = ipx_comparar(det)
            if _IPX["forzar"]:
                _ipx_comprobar_forzado(det)
            avast_comprobar()
        finally:
            _IPX["busy"] = False
            _ui_call(_ipx_pintar)
    threading.Thread(target=_bg, daemon=True).start()


def _ipx_comprobar_forzado(det):
    """Con el forzado puesto: ¿sales por el VPS? ¿el proxy vive?"""
    if det.get("ok") and _ipx_es_vps(det["ip"]):
        _IPX["aviso_forzado"] = False
        _ipx_proxy_volvio()
        return
    vivo, info = _ipx_proxy_vivo()
    if not vivo:
        _ipx_proxy_caido(info)
    else:
        _ipx_proxy_volvio()
    # Sales por otra IP (o no se pudo ver): aviso con «Reconectar por el
    # proxy». No se reconecta solo: lo eliges tú.
    _IPX["aviso_forzado"] = True


# ---- Avast VPN (servicio de Windows): detectar, avisar, parar si lo eliges
def avast_servicios():
    """Servicios cuyo nombre o nombre visible contiene «SecureLine» o
    «Avast» + «VPN» (en este PC se vio SecureLine = «Avast VPN»; se busca
    cada vez, no se asume). Lista de {nombre, visible, estado, inicio}."""
    import psutil
    out = []
    for s in psutil.win_service_iter():
        try:
            name, disp = s.name(), s.display_name()
        except Exception:
            continue
        low = f"{name} {disp}".lower()
        if "secureline" in low or ("avast" in low and "vpn" in low):
            try:
                st, ini = s.status(), s.start_type()
            except Exception:
                st, ini = "?", "?"
            out.append({"nombre": name, "visible": disp, "estado": st, "inicio": ini})
    return out


def avast_comprobar(al_arrancar=False):
    try:
        servs = avast_servicios()
        err = ""
    except Exception as e:
        servs, err = [], f"{type(e).__name__}: {e}"
    antes = _IPX.get("avast") or {}
    corr = [s["nombre"] for s in servs if s["estado"] == "running"]
    _IPX["avast"] = {"servicios": servs, "error": err, "at": _now_iso()}
    if corr:
        if not _IPX["avast_dejado"]:
            _IPX["avast_aviso"] = True
        if al_arrancar or not any(s.get("estado") == "running" for s in antes.get("servicios") or []):
            log(f"salida: Avast VPN está activo (servicio {', '.join(corr)})")
    else:
        _IPX["avast_aviso"] = False
        _IPX["avast_dejado"] = False  # si vuelve a arrancar, se vuelve a avisar
    if al_arrancar:
        log("salida: servicios de Avast VPN encontrados: "
            + (", ".join(f"{s['nombre']} («{s['visible']}», {s['estado']}, inicio {s['inicio']})" for s in servs)
               or (f"ninguno ({err})" if err else "ninguno")))
    return _IPX["avast"]


def _sc(args, timeout=20):
    """sc.exe; devuelve (código, texto). El código de sc es el error de Windows."""
    try:
        rc, out, err = _run_capture(["sc"] + list(args), timeout)
    except Exception as e:
        return -1, f"{type(e).__name__}: {e}"
    return rc, (out + err).strip()


def _sc_motivo(rc, txt):
    m = re.search(r"(?:ERROR|FAILED)\s+(\d+)", txt or "")
    code = int(m.group(1)) if m else rc
    if code == 5:
        return "hace falta administrador"
    if code == 1062:
        return "no estaba corriendo"
    if code == 1060:
        return "ese servicio no existe en este PC"
    if code == 1051:
        return "otro servicio depende de él"
    return f"código {code}: {' '.join((txt or '').split())[:140]}"


def avast_parar(nombre):
    """«Pararlo»: sc stop y se comprueba de verdad que paró. Si no paró, se
    dice por qué (sin fingir)."""
    rc, txt = _sc(["stop", nombre])
    if rc != 0:
        motivo = _sc_motivo(rc, txt)
        msg = (f"No pude pararlo: {motivo}." if motivo != "no estaba corriendo"
               else f"«{nombre}» no estaba corriendo: no hacía falta pararlo.")
        log(f"salida: sc stop {nombre} -> {rc} ({' '.join(txt.split())[:160]})")
        return False, msg
    for _ in range(30):
        st = next((s["estado"] for s in avast_servicios() if s["nombre"] == nombre), "?")
        if st == "stopped":
            log(f"salida: Avast VPN ({nombre}) parado a petición tuya")
            return True, f"Avast VPN («{nombre}») está parado."
        time.sleep(0.5)
    return False, f"Le pedí a «{nombre}» que parara pero sigue en «{st}»; mira services.msc."


def avast_inicio(nombre, modo):
    """Deshabilitado (disabled) o Manual (demand): SOLO si lo eliges."""
    rc, txt = _sc(["config", nombre, "start=", modo])
    if rc != 0:
        return False, f"No pude cambiarlo: {_sc_motivo(rc, txt)}."
    log(f"salida: inicio de {nombre} -> {modo} (lo elegiste tú)")
    return True, ("Deshabilitado: ya no arranca con Windows. Avast VPN (y Claude Desktop por Avast) no "
                  "funcionará hasta que lo vuelvas a Manual." if modo == "disabled"
                  else "Vuelve a Manual: Avast VPN puede arrancar cuando lo abras.")


def _avast_accion(accion):
    servs = [s for s in ((_IPX.get("avast") or {}).get("servicios") or [])]
    if not servs:
        _IPX["avast_msg"] = "No encontré el servicio de Avast VPN en este PC."
        _ipx_pintar()
        return
    if accion == "dejar":
        _IPX["avast_aviso"] = False
        _IPX["avast_dejado"] = True
        _IPX["avast_msg"] = "Lo dejo como está. Si el túnel cae, queda en tunel-caidas.log."
        log("salida: Avast VPN activo y elegiste «Dejarlo»")
        _ipx_pintar()
        return
    if accion in ("disabled", "demand"):
        s0 = servs[0]
        q = ("¿Deshabilitar el servicio «{n}» ({v})? No arrancará con Windows y Avast VPN no funcionará "
             "(tampoco para Claude Desktop) hasta que lo vuelvas a Manual." if accion == "disabled"
             else "¿Volver «{n}» ({v}) a inicio Manual?").format(n=s0["nombre"], v=s0["visible"])
        if not messagebox.askyesno("Avast VPN", q):
            return
    _IPX["avast_msg"] = "⠋ Un momento…"
    _ipx_pintar()

    def _bg():
        msgs, ok_all = [], True
        for s in servs:
            if accion == "parar":
                if s["estado"] != "running":
                    continue
                ok, m = avast_parar(s["nombre"])
            else:
                ok, m = avast_inicio(s["nombre"], accion)
            ok_all = ok_all and ok
            msgs.append(m)
        avast_comprobar()
        _IPX["avast_msg"] = " ".join(msgs) or "Nada que hacer."
        if accion == "parar" and not ok_all:
            _IPX["avast_aviso"] = True  # sigue corriendo: el aviso no se va
        _ui_call(_ipx_pintar)
    threading.Thread(target=_bg, daemon=True).start()


# ---- vigía: túnel (Tailscale), Avast, proxy forzado, latido para apagones
def _ipx_tunel_arriba():
    if _tunel_modo() == "ninguno":
        return None
    return tunel_ip() is not None


def _ipx_apagon_al_arrancar():
    """Si el túnel estaba arriba en el último latido y Windows arrancó
    después, el camino cayó por un apagón o un reinicio."""
    lat = _ipx_leer().get("latido") or {}
    if lat.get("tunel") and lat.get("at") and _ipx_reinicio_desde(lat["at"]):
        try:
            import psutil
            boot = datetime.fromtimestamp(psutil.boot_time()).strftime("%Y-%m-%d %H:%M")
        except Exception:
            boot = "?"
        tunel_registrar("Tailscale (VM↔PC)", "apagón o reinicio del PC",
                        f"último latido {lat['at']}; Windows arrancó {boot}")


def _ipx_latido(tunel):
    with _IPX["lock"]:
        reg = _ipx_leer()
        reg["latido"] = {"at": _now_iso(), "tunel": bool(tunel)}
        _ipx_guardar(reg)


# ---- Tailscale atascado en «Starting…» (t-detector-avast, lo que faltaba
# tras t-ip-estable): el vigia lee `tailscale status --json` (BackendState);
# si lleva mas de TS_STARTING_MIN en Starting, avisa con la causa probable y
# ofrece reiniciar el servicio (con confirmacion). Nunca reinicia solo.
TS_STARTING_MIN = 5
TS_SERVICIO = "Tailscale"


def _ts_exe():
    exe = shutil.which("tailscale") or str(Path(os.environ.get("ProgramFiles", r"C:\Program Files"))
                                           / "Tailscale" / "tailscale.exe")
    return exe if Path(exe).is_file() else None


def tailscale_backend():
    """BackendState de Tailscale (Running / Starting / NeedsLogin / Stopped…) o None."""
    exe = _ts_exe()
    if not exe:
        return None
    try:
        rc, out, _e = _run_capture([exe, "status", "--json"], 10)
        return json.loads(out).get("BackendState") if out.strip().startswith("{") else None
    except Exception:
        return None


def _ts_vigia(estado=None, ahora=None):
    """Un paso del vigia (lo llama _ipx_vigia_paso). estado/ahora: para pruebas."""
    estado = estado if estado is not None else tailscale_backend()
    ahora = ahora or time.time()
    _IPX["ts_estado"] = estado
    if estado == "Starting":
        _IPX.setdefault("ts_starting_desde", ahora)
        mins = (ahora - _IPX["ts_starting_desde"]) / 60
        if mins >= TS_STARTING_MIN and not _IPX.get("ts_aviso"):
            av = [s["nombre"] for s in (avast_servicios() or []) if s.get("estado") == "running"]
            causa = (f"Avast VPN («{', '.join(av)}») está activo y compite por las rutas" if av
                     else "el servicio de Tailscale se quedó colgado arrancando")
            _IPX["ts_aviso"] = {"desde": _IPX["ts_starting_desde"], "causa": causa, "min": round(mins, 1)}
            tunel_registrar("Tailscale (VM↔PC)", causa, f"lleva {mins:.0f} min en «Starting…»")
            toast("Tailscale atascado arrancando", ("estado",))
            log(f"salida: Tailscale lleva {mins:.0f} min en Starting (causa probable: {causa})")
    else:
        if _IPX.get("ts_aviso") and estado == "Running":
            _ipx_append(TUNEL_LOG, f"{_ipx_ahora()} | volvió: Tailscale (VM↔PC) | estaba en «Starting…»")
        _IPX.pop("ts_starting_desde", None)
        _IPX["ts_aviso"] = None
    return _IPX.get("ts_aviso")


def tailscale_reiniciar_ui():
    """Solo si Leandro lo pide: confirma, reinicia el servicio y dice el resultado real."""
    if not messagebox.askyesno("Reiniciar Tailscale",
                               f"Voy a reiniciar el servicio «{TS_SERVICIO}» de Windows (Restart-Service). El túnel "
                               "se corta unos segundos y vuelve a arrancar. Hace falta administrador.\n\n¿Lo reinicio?",
                               default="no"):
        return
    rc, out, err = _run_capture(["powershell", "-NoProfile", "-Command",
                                 f"Restart-Service -Name '{TS_SERVICIO}' -Force -ErrorAction Stop"], 60)
    ok = rc == 0
    log(f"salida: reiniciar el servicio {TS_SERVICIO}: " + ("hecho" if ok else f"falló ({(err or out)[:200]})"))
    messagebox.showinfo("Reiniciar Tailscale", "Servicio reiniciado. En un minuto vuelvo a mirar el túnel." if ok
                        else f"No pude reiniciarlo: {(err or out).strip()[:300]}")


def tunel_caidas_ui():
    """El registro de caídas (tunel-caidas.log), lo más nuevo arriba."""
    lineas = list(reversed(_ipx_lineas(TUNEL_LOG, "|")))
    top = tk.Toplevel(_root)
    top.title("Caídas del túnel")
    top.configure(bg=THEME["bg"])
    tk.Label(top, text=f"{len([x for x in lineas if '| cayó:' in x])} caída(s) en {TUNEL_LOG}. Cada una con su causa "
                       "probable (Avast, apagón, red…).", bg=THEME["bg"], fg=THEME["muted"], font=(FONT, 10),
             wraplength=S(640), justify="left").pack(anchor="w", padx=16, pady=(12, 4))
    txt = tk.Text(top, height=18, width=100, font=("Consolas", 9))
    txt.insert("1.0", "\n".join(lineas) or "Ninguna caída registrada todavía.")
    txt.configure(state="disabled")
    txt.pack(fill="both", expand=True, padx=16, pady=(0, 12))
    _widgets["tunel_caidas_top"] = top
    return top


def _ipx_vigia_paso(n):
    t = _ipx_tunel_arriba()
    prev = _IPX.get("tunel")
    if prev is True and t is False:
        tunel_registrar("Tailscale (VM↔PC)", _ipx_causa_caida("tailscale"),
                        "la IP de Tailscale de este PC desapareció")
        _IPX["tunel_caido_at"] = _now_iso()
    elif prev is False and t is True and _IPX.get("tunel_caido_at"):
        _ipx_append(TUNEL_LOG, f"{_ipx_ahora()} | volvió: Tailscale (VM↔PC) | caído desde {_IPX['tunel_caido_at']}")
        _IPX["tunel_caido_at"] = None
    _IPX["tunel"] = t
    if n % 2 == 0:  # cada ~60 s
        _ts_vigia()  # Tailscale atascado en «Starting…»
        avast_comprobar()
        if _IPX["forzar"] and not _IPX["busy"]:
            vivo, info = _ipx_proxy_vivo()
            if vivo:
                _ipx_proxy_volvio()
            else:
                _ipx_proxy_caido(info)
        _ipx_latido(t)
    _ui_call(_ipx_pintar)


def _ipx_arranque():
    """Al arrancar, en un hilo: no retrasa la ventana; sin internet la app
    arranca igual y Estado dice que no se pudo detectar y por qué."""
    _IPX["busy"] = True
    try:
        _IPX["forzar"] = bool(load_settings().get("forzar_proxy"))
        _ipx_apagon_al_arrancar()
        avast_comprobar(al_arrancar=True)
        _IPX["tunel"] = _ipx_tunel_arriba()
        # El aviso de Avast sale ya, sin esperar a la IP (con el proxy lento,
        # la detección puede tardar ~1 min; visto el 27 oct con SecureLine).
        _ui_call(_ipx_pintar)
        det = ipx_detectar()
        _IPX["det"] = det
        if det.get("ok"):
            _IPX["res"] = ipx_comparar(det)
            log(f"salida: {ipx_texto(det)} (vía {det['servicio']}, {det['ms']} ms)")
        else:
            _IPX["res"] = "sin_dato"
            log(f"salida: IP de salida: no se pudo detectar ({det['causa']})")
        if _IPX["forzar"]:
            _ipx_comprobar_forzado(det)
        _ipx_latido(_IPX["tunel"])
    except Exception as e:
        _IPX["msg"] = f"No pude comprobar la salida ({type(e).__name__}: {e})."
        log(f"salida: {type(e).__name__}: {e}")
    finally:
        _IPX["busy"] = False
        _ui_call(_ipx_pintar)
    n = 0
    while True:
        time.sleep(IPX_VIGIA_S)
        n += 1
        try:
            _ipx_vigia_paso(n)
        except Exception as e:
            log(f"salida: vigía ({type(e).__name__}: {e})")


# ---- interfaz: avisos arriba en Estado + tarjeta «Salida a internet» (CTk con respaldo)
def _ipx_kit(holder, primero):
    if _ctk_wanted():
        try:
            return _KitCtk(holder, global_setup=primero and not isinstance(_GW.get("kit"), _KitCtk)
                           and not isinstance(_EXP.get("kit"), _KitCtk))
        except Exception as e:
            log(f"salida: CustomTkinter no disponible ({type(e).__name__}: {e}); se usa tkinter clásico")
    return _KitTk(holder)


def _build_ipx_ui(avisos_holder, card_holder):
    for i, (holder, fn, key) in enumerate(((avisos_holder, _build_ipx_avisos, "kit_av"),
                                           (card_holder, _build_ipx_card, "kit"))):
        t0 = time.perf_counter()
        kit = _ipx_kit(holder, i == 0)
        try:
            fn(kit, holder)
        except Exception as e:
            if not isinstance(kit, _KitCtk):
                raise
            log(f"salida: CTk falló al dibujar ({type(e).__name__}: {e}); se usa tkinter clásico")
            for ch in holder.winfo_children():
                ch.destroy()
            kit = _KitTk(holder)
            fn(kit, holder)
        _IPX[key] = kit
        log(f"salida: {'avisos' if key == 'kit_av' else 'tarjeta Salida a internet'} con {kit.nombre} "
            f"({(time.perf_counter() - t0) * 1000:.0f} ms)")
    _ipx_pintar()


def _ipx_aviso_card(k, holder, key, color):
    """Un aviso fijo en su hueco (el orden no cambia al mostrar/ocultar)."""
    W = _widgets
    slot = tk.Frame(holder, bg=THEME["bg"])
    slot.pack(fill="x")
    card = k.card(slot)
    W[f"ipx_{key}_card"] = card
    W[f"ipx_{key}_txt"] = k.label(card, "", bold=True, wrap=600, color=color)
    W[f"ipx_{key}_txt"].pack(anchor="w", fill="x", padx=16, pady=(10, 2))
    W[f"ipx_{key}_sub"] = k.label(card, "", muted=True, wrap=600)
    W[f"ipx_{key}_sub"].pack(anchor="w", fill="x", padx=16, pady=(0, 4))
    return k.row(card, pady=(2, 10))


def _build_ipx_avisos(k, holder):
    W = _widgets
    r = _ipx_aviso_card(k, holder, "cambio", "orange_text")
    W["ipx_btn_forzar"] = k.button(r, "Forzar el proxy", lambda: ipx_responder("forzar"), accent=True)
    W["ipx_btn_forzar"].pack(side="left")
    W["ipx_btn_asumo"] = k.button(r, "Seguir así (lo asumo)", lambda: ipx_responder("asumo"))
    W["ipx_btn_asumo"].pack(side="left", padx=(8, 0))
    r = _ipx_aviso_card(k, holder, "forzado", "orange_text")
    W["ipx_btn_reconectar"] = k.button(r, "Reconectar por el proxy", lambda: threading.Thread(
        target=ipx_forzar, args=(True, "reconectar"), daemon=True).start(), accent=True)
    W["ipx_btn_reconectar"].pack(side="left")
    r = _ipx_aviso_card(k, holder, "caido", "red")
    W["ipx_btn_reintentar"] = k.button(r, "Reintentar el proxy", lambda: threading.Thread(
        target=ipx_forzar, args=(True, "reintentar"), daemon=True).start())
    W["ipx_btn_reintentar"].pack(side="left")
    r = _ipx_aviso_card(k, holder, "avast", "orange_text")
    W["ipx_btn_parar"] = k.button(r, "Pararlo", lambda: _avast_accion("parar"))
    W["ipx_btn_parar"].pack(side="left")
    W["ipx_btn_dejar"] = k.button(r, "Dejarlo", lambda: _avast_accion("dejar"))
    W["ipx_btn_dejar"].pack(side="left", padx=(8, 0))


def _ipx_switch(k, parent, on, command):
    if isinstance(k, _KitCtk):
        ctk = k.ctk
        dark = _THEME_STATE["dark"]
        sw = ctk.CTkSwitch(parent, text="", width=46, switch_width=40, switch_height=22,
                           progress_color=THEME["green"], fg_color=_tema_fijo("off_track"),
                           button_color="#ffffff", button_hover_color="#f2f2f2", border_width=2,
                           border_color="transparent", command=lambda: command(bool(sw.get())))
        (sw.select if on else sw.deselect)()
        # Foco de teclado visible (como el piloto): Tab llega, borde azul, Espacio cambia.
        try:
            sw._canvas.configure(takefocus=1)
            sw._canvas.bind("<FocusIn>", lambda e: sw.configure(border_color=THEME["blue"]), add=True)
            sw._canvas.bind("<FocusOut>", lambda e: sw.configure(border_color="transparent"), add=True)
            sw._canvas.bind("<space>", lambda e: (sw.toggle(), "break")[1], add=True)
        except Exception:
            pass
        sw._ctk = True
        return sw
    sw = make_switch(parent, on, command, bg=THEME["card"])
    sw._ctk = False
    return sw


def _ipx_set_switch(sw, on):
    if sw is None:
        return
    if getattr(sw, "_ctk", False):
        if bool(sw.get()) != bool(on):
            (sw.select if on else sw.deselect)()
    else:
        set_switch(sw, on)


