# un motor a otro (la nube cae y va al local, un modelo de una superficie deja
# de estar, una ronda cambia de motor) queda aqui con su motivo; el panel de
# Estado enseña el ultimo. En memoria: «desde que arrancó», sin inventar.
_CAMBIOS_MOTOR = deque(maxlen=20)


def motor_cambio(de, a, motivo):
    _CAMBIOS_MOTOR.append({"at": _now_iso(), "de": str(de), "a": str(a), "motivo": str(motivo)})
    log(f"motores: cambio de {de} a {a} ({motivo})")


def local_fallback_model(model):
    """Si la nube cayo, lo que pide la app va al modelo local (aviso claro)."""
    if not state.get("nube_caida") or conn_state() != "local":
        return model, False
    if model.startswith("ollama:") or model in ("motor:llama", "motor:ollama"):
        return model, False
    nuevo = "ollama:" + (default_ollama_model() or OLLAMA_MODEL)
    motor_cambio(model, nuevo, "la nube no responde: lo que pides desde la app va al modelo local")
    return nuevo, True


# ---- bandeja: icono con distintivo de conexion y numero de cuota
def _tray_kind():
    if state["bridge"] != "corriendo":
        base = "sin"
    else:  # el último estado único calculado (t-estado-consistencia-045), no la sonda por su lado
        base = {"arriba": "ok", "parcial": "local", "abajo": "sin"}.get(_EU.get("nivel"), "idle")
    sync = False
    if TRANSFERS:
        try:
            sync = (datetime.now().astimezone() - datetime.fromisoformat(TRANSFERS[-1][3])
                    ).total_seconds() < 10
        except Exception:
            pass
    pct = _quota_pct()
    pulse = "2" if sync and _tick_n[0] % 2 else ""
    return f"{base}{pulse}|{'' if pct is None else int(pct)}|{_tray_espera_kind()}"


def _tray_espera_kind():
    """Guardrail en el icono: 'eN' = N tareas esperan tu aprobacion; 'nunca'
    = «Hazlo sin preguntar»; 'x' = no se pudo leer el estado; '' = nada."""
    d = _ESP.get("dato")
    if d is None:
        return ""
    if d.get("error"):
        return "x"
    if d.get("n"):
        return f"e{d['n']}"
    return "nunca" if _ESP.get("nivel") == "nunca" else ""


def _tray_distintivo_espera(d, esp):
    """Distintivo del guardrail, encima del personaje, en el mismo lienzo de
    64x64 que el de conexion/sincronizacion (no es otro mecanismo): ambar
    con el numero arriba a la derecha + punto ambar abajo a la izquierda si
    hay tareas en espera (se nota sin leer el numero); rojo con «!» si el
    nivel es «Hazlo sin preguntar»; gris con «?» si no se pudo leer. Borde
    oscuro: se ve sobre la barra clara; el relleno, sobre la oscura."""
    if not esp:
        return
    from PIL import ImageFont
    try:
        font = ImageFont.truetype("segoeuib.ttf", 30)
    except Exception:
        font = None
    edge = "#1D1D1F"
    if esp.startswith("e"):
        n = int(esp[1:])
        txt, fill, ink = (str(n) if n < 10 else "9+"), "#FF9F0A", "#1D1D1F"  # 9,6:1
        d.ellipse([0, 41, 22, 63], fill=fill, outline=edge, width=2)
    elif esp == "nunca":
        txt, fill, ink = "!", "#D70015", "#FFFFFF"  # 5,6:1
    else:
        txt, fill, ink = "?", "#6E6E73", "#FFFFFF"  # 5,1:1
    x0 = 25 if len(txt) == 1 else 13
    d.rounded_rectangle([x0, 0, 63, 37], radius=15, fill=fill, outline=edge, width=2)
    d.text(((x0 + 63) / 2, 19), txt, fill=ink, anchor="mm", font=font)


def _tray_image2(kind):
    """Personaje + distintivo (verde conectado, ambar solo local, rojo sin
    conexion) + el % de Max que mas aprieta, si se puede leer + el
    distintivo del guardrail (tareas en espera / sin preguntar)."""
    try:
        from PIL import ImageDraw, ImageFont
        base = Image.open(TRAY_ICON if TRAY_ICON.is_file() else PHOTO).convert("RGBA")
    except Exception:
        return None
    parts = kind.split("|")
    state_k, pct = parts[0], parts[1]
    esp = parts[2] if len(parts) > 2 else ""
    img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
    small = base.resize((56, 56), Image.LANCZOS)
    img.paste(small, (4, 4), small)
    d = ImageDraw.Draw(img)
    colors = {"ok": "#34C759", "ok2": "#8BE0A4", "local": "#FF9500", "local2": "#FFC266",
              "sin": "#FF3B30", "sin2": "#FF8A80"}
    if state_k in colors:
        d.ellipse([36, 36, 63, 63], fill=colors[state_k], outline="white", width=3)
    if esp:  # tareas en espera / sin preguntar: manda sobre el % de cuota (va en el tooltip)
        _tray_distintivo_espera(d, esp)
        return img
    if pct:
        p = int(pct)
        fill = "#34C759" if p < 75 else "#FF9500" if p < 90 else "#FF3B30"
        try:
            font = ImageFont.truetype("segoeuib.ttf", 26)
        except Exception:
            font = None
        d.rounded_rectangle([0, 0, 40, 30], radius=8, fill=fill, outline="white", width=2)
        d.text((20, 15), str(min(p, 99)), fill="white", anchor="mm", font=font)
    return img


def _tray_tick():
    if _tray_icon is None:
        return
    kind = _tray_kind()
    if kind != _tray_state[0]:
        _tray_state[0] = kind
        img = _tray_image2(kind)
        if img is not None:
            _tray_icon.icon = img


def _patch_tray_clicks(icon):
    """Clic = Tareas filtrada a las que esperan tu aprobacion (sin ninguna,
    Tareas sin filtro, con el desglose del gasto); doble clic = abrir la
    ventana; clic en un aviso = su contexto exacto."""
    try:
        from pystray._util import win32 as pw
    except Exception:
        return
    orig = icon._message_handlers.get(pw.WM_NOTIFY)
    if orig is None:
        return
    pend = {"t": None, "tras_doble": False}

    def _single():
        # Clic: Tareas filtrada a las que esperan tu aprobacion; sin ninguna,
        # Tareas sin filtro (ahi sigue el desglose del gasto) y lo dice.
        pend["t"] = None
        if _root is not None:
            _root.after(0, abrir_lista_espera)

    def handler(wparam, lparam):
        if lparam == 0x0203:  # WM_LBUTTONDBLCLK
            if pend["t"]:
                pend["t"].cancel()
                pend["t"] = None
            # El doble clic acaba con otro WM_LBUTTONUP: ese no es un clic nuevo.
            pend["tras_doble"] = True
            if _root is not None:
                _root.after(0, show_window)
            return 0
        if lparam == 0x0202:  # WM_LBUTTONUP
            if pend["tras_doble"]:
                pend["tras_doble"] = False
                return 0
            if pend["t"]:
                return 0
            try:
                import ctypes
                ms = ctypes.windll.user32.GetDoubleClickTime()
            except Exception:
                ms = 400
            pend["t"] = threading.Timer(ms / 1000.0, _single)
            pend["t"].start()
            return 0
        if lparam == 0x0405:  # NIN_BALLOONUSERCLICK
            ctx = _TOAST.get("ctx")
            if _root is not None:
                _root.after(0, lambda: _open_ctx(ctx))
            return 0
        return orig(wparam, lparam)
    icon._message_handlers[pw.WM_NOTIFY] = handler


