_APR_UI = []  # (etiqueta del vencimiento, pedido): la cuenta atras se repinta sin rehacer la tarjeta


def _vence_linea(apr):
    """«Vence el lun 26/10 a las 05:12, hora de Caracas (quedan 1 h 59 min). Si no respondes, no se hace.»"""
    vts = apr.get("vence_ts")
    if not vts:
        return "Sin vencimiento todavía: el runner se lo pone en su próxima vuelta."
    falta = vts - time.time()
    txt = (f"Vence el {hora_caracas_txt(vts)}, hora de Caracas ({falta_txt(falta)}). "
           "Si no respondes, no se hace.")
    if falta <= 0:
        txt = (f"Venció el {hora_caracas_txt(vts)}, hora de Caracas: ya no vale aprobarla; "
               "el runner la pasa a «necesita decisión» sin ejecutarla.")
    if apr.get("nivel") == "R3":
        txt += " R3: solo se aprueba aquí, en la app."
    if apr.get("prueba"):
        txt += " (temporizador de prueba)"
    return txt


def _vence_color(apr):
    vts = apr.get("vence_ts")
    return THEME["orange_text"] if vts and vts - time.time() < 15 * 60 else THEME["text"]


def _apr_ui_tick():
    for lbl, apr in list(_APR_UI):
        try:
            lbl.config(text=_vence_linea(apr), fg=_vence_color(apr))
        except tk.TclError:
            pass


def _espera_de_verdad(r):
    """Fila que espera tu aprobacion Y cuyo encargo sigue en esperando/: lo
    mismo que cuenta el contador (nunca un Aprobar que ya no puede aprobar)."""
    if r["estado"] != "esperando_aprobacion":
        return False
    name = (r["fam"] or {}).get("archivo_espera")
    return not name or (WAITING / str(name)).is_file()


def _render_approvals(rows):
    """Tarjeta «Esperan tu aprobación»: el plan de cada tarea que quiere
    borrar, publicar, gastar o enviar algo, con Aprobar / Rechazar."""
    box = _widgets.get("approvals_box")
    if box is None:
        return
    waiting = [r for r in rows if _espera_de_verdad(r)]
    fp = tuple((r["id"], r["t"]) for r in waiting)
    if fp == _approvals_fp[0]:
        return
    _approvals_fp[0] = fp
    _clear(box)
    _APR_UI.clear()
    if not waiting:
        box.pack_forget()
        return
    box.pack(fill="x", padx=20, pady=(0, 8), before=_T45.get("fijada_card") or _widgets["tasks_tree"])
    tk.Label(box, text="Esperan tu aprobación", font=SECTION_FONT,
             bg=THEME["card"], fg=THEME["text"]).pack(anchor="w", padx=16, pady=(12, 2))
    for r in waiting:
        plan = (r["fam"] or {}).get("plan") or {}
        acc = plan.get("acciones") or {}
        quiere = ", ".join(f"{k} ({', '.join(v.get('palabras') or [])})" for k, v in acc.items())
        row = tk.Frame(box, bg=THEME["card"])
        row.pack(fill="x", padx=16, pady=6)
        tk.Label(row, text=f"{r['id']} quiere {quiere}", font=(FONT, 10, "bold"),
                 bg=THEME["card"], fg=THEME["text"], wraplength=S(600), justify="left").pack(anchor="w")
        perms = plan.get("permisos") or {}
        tk.Label(row, text=(f"Motor: {_motor_txt(plan.get('motor'), plan)}   "
                            f"Carpeta: {plan.get('cwd')}   "
                            f"Permisos: {perms.get('permission_mode') or 'los normales'}"),
                 font=(FONT, 9), bg=THEME["card"], fg=THEME["muted"], wraplength=S(600),
                 justify="left").pack(anchor="w")
        tk.Label(row, text="Encargo: " + re.sub(r"\s+", " ", plan.get("prompt") or "")[:500],
                 font=(FONT, 9), bg=THEME["card"], fg=THEME["text"], wraplength=S(600),
                 justify="left").pack(anchor="w", pady=(2, 0))
        if re.search(r"\btripo", plan.get("prompt") or "", re.I):
            # El costo Tripo a la vista ANTES de aprobar (t-saldo-tripo).
            try:
                tk.Label(row, text=tripo_linea_aprobacion(), font=(FONT, 9, "bold"), bg=THEME["card"],
                         fg=THEME["orange_text"], wraplength=S(600), justify="left").pack(anchor="w", pady=(2, 0))
            except Exception as e:
                log(f"tripo: no pude poner el costo en la aprobación ({type(e).__name__}: {e})")
        if acc:
            tk.Label(row, text="Lo hizo sensible: " + "; ".join(
                         f"{k}, por «{'», «'.join(v.get('palabras') or ['?'])}»" for k, v in acc.items())
                     + f" (permisos: {GUARDRAIL_CORTO.get(plan.get('nivel'), plan.get('nivel') or '—')})",
                     font=(FONT, 9), bg=THEME["card"], fg=THEME["muted"], wraplength=S(600),
                     justify="left").pack(anchor="w", pady=(2, 0))
        # Nivel R0-R3 con su motivo y el vencimiento (t-vencimiento-aprobacion-030).
        rg = plan.get("riesgo") or {}
        apr = plan.get("aprobacion") or (r["fam"] or {}).get("aprobacion") or {}
        if rg.get("nivel"):
            tk.Label(row, text=f"Nivel {rg['nivel']}" + (f", {rg['nombre']}" if rg.get("nombre") else "")
                     + f". Motivo: {rg.get('motivo') or '—'}",
                     font=(FONT, 9), bg=THEME["card"], fg=THEME["muted"], wraplength=S(600),
                     justify="left").pack(anchor="w", pady=(2, 0))
        vl = tk.Label(row, text=_vence_linea(apr), font=(FONT, 10, "bold"), bg=THEME["card"],
                      fg=_vence_color(apr), wraplength=S(600), justify="left")
        vl.pack(anchor="w", pady=(2, 4))
        _APR_UI.append((vl, apr))
        brow = tk.Frame(row, bg=THEME["card"])
        brow.pack(anchor="w")
        aid = apr.get("approval_id")
        ttk.Button(brow, text="Aprobar", style="Accent.TButton",
                   command=lambda x=r["id"], a=aid: _approve_ui(x, True, a)).pack(side="left", padx=(0, 8))
        ttk.Button(brow, text="Rechazar",
                   command=lambda x=r["id"], a=aid: _approve_ui(x, False, a)).pack(side="left")
        tk.Frame(box, bg=THEME["line"], height=S(1)).pack(fill="x", padx=16)
    tk.Frame(box, bg=THEME["card"], height=S(8)).pack()


# ---- Tareas 0.4.5 (t-tareas-estadisticas-045): encima de la tabla, la fila de
# 3 estadísticas (En curso / Aprobadas hoy / Gasto de hoy), la tarea en curso
# fijada («trabajando ahora», fuera de la tabla: no se va al desplazar) y las
# píldoras de filtro con su contador real. Superficie nueva: CustomTkinter con
# la clásica de respaldo. Números de la cola y de day_by_model (la misma fuente
# que el consumo vivo); nada inventado: sin dato, «sin dato».
TFILTROS = (("todos", "Todos", None, None), ("en_curso", "En curso", ("en_curso", "revisando"), "blue"),
            ("aprobada", "Aprobadas", ("aprobada",), "green_text"),
            ("necesita_decision", "Necesita decisión", ("necesita_decision",), "orange_text"),
            ("sin_revision", "Sin revisión", ("sin_revision",), "muted"),
            ("fallida", "Fallidas", ("fallida",), "red"))
TFILTROS_EXPL = ("Necesita decisión: tras 3 rondas no quedó bien, o su aprobación venció o se denegó; decides tú "
                 "(no se reintenta sola).  Sin revisión: terminó pero el revisor no pudo revisarla; no cuenta "
                 "como aprobada.")
_T45: dict = {"kit": None, "filtro": "todos", "pills": {}, "stats": {}, "fijada": None, "cuentas": {}}


# ---- Tareas: «Buscar o pedirle algo (Ctrl K)» en el encabezado (t-tareas-ctrlk-045). Tkinter clásico (la paleta
# Ctrl+K no se convierte ni se toca). Al escribir, la lista se filtra en vivo por id o por título (el encargo);
# vacío, sin filtro. Intro sin coincidencias: el texto va como encargo nuevo por el camino del compositor
# (_send_ask) con «Automático (recomendado)»: decide el router. Intro con coincidencias: elige la primera.
# Ctrl+K en Tareas pone el foco aquí (si ya lo tiene, abre la paleta de siempre); Esc limpia y vuelve a la lista.
BUSCA_PLACEHOLDER = "Buscar o pedirle algo (Ctrl K)"


def tareas_buscar(rows, q):
    """Las filas cuyo id o título (el encargo) contienen q (sin mayúsculas). q vacío: todas."""
    q = str(q or "").strip().lower()
    if not q:
        return list(rows)
    out = []
    for r in rows:
        fam = r.get("fam") or {}
        titulo = str(fam.get("encargo") or fam.get("titulo") or "")
        if q in str(r.get("id") or "").lower() or q in titulo.lower():
            out.append(r)
    return out


def _busca_construir(parent):
    caja = tk.Frame(parent, bg=THEME["bg"])
    caja.pack(side="right", anchor="s", pady=(0, 4))
    var = tk.StringVar()
    ent = ttk.Entry(caja, textvariable=var, width=34, font=(FONT, 10))
    ent.pack()
    ph = tk.Label(caja, text=BUSCA_PLACEHOLDER, font=(FONT, 10), bg=THEME["field"], fg=THEME["muted"],
                  cursor="xterm")
    ph.bind("<Button-1>", lambda _e: ent.focus_set())
    _T45.update(busca_var=var, busca_entry=ent, busca_ph=ph, busca="")

    def _ph(_e=None):
        try:
            enf = ent.focus_get() is ent
        except Exception:
            enf = False
        if not var.get() and not enf:
            ph.place(in_=ent, x=S(6), rely=0.5, anchor="w")
            ph.lift()
        else:
            ph.place_forget()
    _T45["busca_ph_fn"] = _ph
    var.trace_add("write", lambda *_a: _busca_filtrar())
    ent.bind("<Return>", _busca_intro)
    ent.bind("<Escape>", _busca_esc)
    for ev in ("<FocusIn>", "<FocusOut>"):
        ent.bind(ev, lambda _e: ent.after_idle(_ph), add=True)
    ent.after(60, _ph)
    _widgets["tareas_busca"] = ent


def _busca_filtrar():
    var = _T45.get("busca_var")
    q = var.get().strip() if var is not None else ""
    if q == _T45.get("busca", ""):
        return
    _T45["busca"] = q
    _tasks_fp[0] = None
    _refresh_tasks_ui()
    fn = _T45.get("busca_ph_fn")
    if fn:
        fn()


def _busca_intro(_e=None):
    var = _T45.get("busca_var")
    q = var.get().strip() if var is not None else ""
    if not q:
        return "break"
    tree = _widgets.get("tasks_tree")
    hay = tareas_buscar(_task_rows()[0], q)
    if hay and tree is not None:
        vis = list(tree.get_children())
        primera = next((r["id"] for r in hay if r["id"] in vis), None)
        if primera:
            tree.selection_set(primera)
            tree.focus(primera)
            tree.see(primera)
            tree.focus_set()
            _show_task_detail()
        return "break"
    # nada coincide: encargo nuevo por el camino del compositor, con el router automático
    box, cb, crit = _widgets.get("ask_text"), _widgets.get("ask_engine"), _widgets.get("ask_criterios")
    if box is None:
        return "break"
    prev = cb.get() if cb is not None else None
    crit_txt = crit.get("1.0", "end").strip() if crit is not None else ""
    if crit is not None:
        crit.delete("1.0", "end")  # los criterios a medio escribir en el compositor no se cuelan aquí
    box.delete("1.0", "end")
    box.insert("1.0", q)
    if cb is not None:
        cb.set(AUTO_LABEL)
    _send_ask()
    if cb is not None and prev:
        cb.set(prev)
    if crit is not None and crit_txt:
        crit.insert("1.0", crit_txt)
    try:
        _comp_placeholder()
    except Exception:
        pass
    log(f"tareas: «Buscar o pedirle algo»: sin coincidencias, enviado como encargo («{q[:60]}»)")
    var.set("")
    return "break"


def _busca_esc(_e=None):
    var = _T45.get("busca_var")
    if var is not None:
        var.set("")
    tree = _widgets.get("tasks_tree")
    if tree is not None:
        tree.focus_set()
    return "break"


def tareas_ctrl_k():
    """Ctrl+K dentro de la app con Tareas a la vista: el foco al campo «Buscar o pedirle algo». True si lo tomó;
    False (ya tenía el foco, u otra página) -> la paleta de siempre."""
    ent = _widgets.get("tareas_busca")
    if ent is None or _widgets.get("pagina_actual") != "tareas":
        return False
    try:
        foco = ent.focus_get()
        pal = _palette.get("win")
        if foco is ent or (foco is not None and pal is not None and str(foco).startswith(str(pal))):
            return False  # ya está aquí, o estás en la paleta: Ctrl+K hace lo de siempre
    except Exception:
        pass
    ent.focus_set()
    ent.select_range(0, "end")
    return True


def tareas_filtrar(rows, filtro):
    est = next((e for k, _l, e, _c in TFILTROS if k == filtro), None)
    return list(rows) if not est else [r for r in rows if r["estado"] in est]


def tareas_cuentas(rows):
    return {k: len(tareas_filtrar(rows, k)) for k, _l, _e, _c in TFILTROS}


def tareas_estadisticas(rows):
    """En curso / Aprobadas hoy / Gasto de hoy, de la cola y del día (sin inventar)."""
    hoy = datetime.now().astimezone().date().isoformat()
    lv = _live_active()
    en_curso = {r["id"] for r in rows if r["estado"] in ("en_curso", "revisando")}
    if lv and lv.get("estado") != "terminado":
        en_curso.add(lv.get("raiz") or lv.get("task_id"))
    aprob = sum(1 for r in rows if r["estado"] == "aprobada" and str(r.get("t") or "").startswith(hoy))
    try:
        data = day_by_model()
        real = sum(b["cost"] for k, b in data.items() if k[0] == "real")
        equiv = sum(b["cost"] for k, b in data.items() if k[0] == "equiv")
        gasto = f"${real:.2f}", f"real, ${equiv:.2f} equivalente Max, local $0"
    except Exception as e:
        gasto = "sin dato", f"no se pudo leer el gasto ({type(e).__name__})"
    return {"en_curso": len(en_curso), "aprobadas_hoy": aprob, "gasto": gasto}


def tarea_fijada(rows):
    """La que corre ahora (runner-live.json); si no, otra en curso de la cola; si no, None."""
    lv = _live_active()
    if lv and lv.get("estado") != "terminado":
        v = _live_values(lv, corto=True)
        return {"id": lv.get("raiz") or lv.get("task_id"), "motor": v["motor"], "tiempo": v["tiempo"],
                "costo": v["costo"], "fuente": "en vivo"}
    for r in rows:
        if r["estado"] in ("en_curso", "revisando"):
            return {"id": r["id"], "motor": _motor_txt(r["motor"], r["fam"]), "tiempo": _fmt_secs(r.get("dur")),
                    "costo": _cost_cell(r), "fuente": "cola"}
    return None


def _tareas045_build_stats(tabt):
    """La fila de 3 estadísticas, arriba de la página (debajo del resumen)."""
    k = None
    if _ctk_wanted():
        try:
            k = _KitCtk(tabt)
        except Exception as e:
            log(f"tareas: CustomTkinter no disponible ({type(e).__name__}: {e}); estadísticas clásicas")
    k = k or _KitTk(tabt)
    ctk_on = isinstance(k, _KitCtk)
    _T45.update(kit=k, ctk=ctk_on)
    fila = k.frame(tabt)
    fila.pack(fill="x", padx=20, pady=(4, 6))
    for i, (key, titulo) in enumerate((("en_curso", "En curso"), ("aprobadas_hoy", "Aprobadas hoy"),
                                       ("gasto", "Gasto de hoy"))):
        c = k.card(fila)
        c.grid(row=0, column=i, sticky="nsew", padx=(0 if i == 0 else 6, 0))
        fila.grid_columnconfigure(i, weight=1, uniform="t45")
        k.label(c, titulo, muted=True).pack(anchor="w", padx=14, pady=(10, 0))
        num = k.label(c, "…", bold=True)
        if ctk_on:
            num.configure(font=k.F(24, "semibold"))
        else:
            num.config(font=(FONT, 18, "bold"))
        num.pack(anchor="w", padx=14)
        sub = k.label(c, "", muted=True, wrap=200 if ctk_on else S(200))  # CTk ya escala
        sub.pack(anchor="w", padx=14, pady=(0, 10))
        _T45["stats"][key] = (num, sub)


def _tareas045_build_lista(tabt):
    """Justo encima de la tabla: la tarea fijada y las píldoras de filtro."""
    k = _T45.get("kit")
    if k is None:
        return
    fij = k.card(tabt)
    fij.pack(fill="x", padx=20, pady=(0, 6))
    _T45["fijada"] = (k.label(fij, "", bold=True), k.label(fij, "", muted=True, wrap=640 if _T45["ctk"] else S(640)))
    _T45["fijada"][0].pack(anchor="w", padx=14, pady=(10, 0))
    _T45["fijada"][1].pack(anchor="w", padx=14, pady=(0, 10))
    _T45["fijada_card"] = fij
    pills = k.frame(tabt)
    pills.pack(fill="x", padx=20, pady=(2, 0))
    for key, lab, _e, _c in TFILTROS:
        _T45["pills"][key] = k.button(pills, lab, lambda kk=key: tareas_poner_filtro(kk))

    def acomodar(_e=None):  # las píldoras pasan a otra fila si no caben (ventana estrecha o 150 %)
        ancho, x, fila, col = pills.winfo_width(), 0, 0, 0
        for b in _T45["pills"].values():
            w = b.winfo_reqwidth() + S(6)
            if x and x + w > ancho:
                fila, col, x = fila + 1, 0, 0
            b.grid(row=fila, column=col, padx=(0, 6), pady=(0, 6), sticky="w")
            x, col = x + w, col + 1
    pills.bind("<Configure>", acomodar, add="+")
    _T45["acomodar"] = acomodar
    acomodar()
    ex = k.label(tabt, TFILTROS_EXPL, muted=True, wrap=640 if _T45["ctk"] else S(640))
    ex.pack(anchor="w", padx=20, pady=(4, 2))
    _T45["expl"] = ex


def tareas_poner_filtro(key):
    _T45["filtro"] = key
    _tasks_fp[0] = None  # repinta la tabla ya
    _refresh_tasks_ui()


def _tareas045_pintar(rows):
    k = _T45.get("kit")
    if k is None:
        return
    st = tareas_estadisticas(rows)
    vals = {"en_curso": (str(st["en_curso"]), "corriendo ahora" if st["en_curso"] else "ninguna corriendo"),
            "aprobadas_hoy": (str(st["aprobadas_hoy"]), "revisadas y aprobadas hoy"),
            "gasto": st["gasto"]}
    for key, (num, sub) in _T45["stats"].items():
        k.set_label(num, text=vals[key][0])
        k.set_label(sub, text=vals[key][1])
    cuentas = tareas_cuentas(rows)
    _T45["cuentas"] = cuentas
    for key, lab, _e, col in TFILTROS:
        b = _T45["pills"][key]
        txt = f"{lab}  {cuentas[key]}"
        activo = key == _T45["filtro"]
        if _T45["ctk"]:
            tinte = THEME[col] if col else THEME["text"]
            b.configure(text=txt, text_color=tinte, border_width=2 if activo else 0, border_color=tinte,
                        fg_color=_mezcla(THEME["card"], tinte, 0.14 if activo else 0.06) if col
                        else _tema_fijo("seg_sel" if activo else "seg_bg"))
        else:
            b.config(text=("● " if activo else "") + txt)
    if _T45.get("acomodar"):
        _T45["acomodar"]()  # los contadores cambian el ancho de cada píldora
    _tareas045_fijada(rows)


def _tareas045_fijada(rows=None):
    k = _T45.get("kit")
    if k is None or not _T45.get("fijada"):
        return
    rows = rows if rows is not None else list(_tasks_rows.values())
    f = tarea_fijada(rows)
    t1, t2 = _T45["fijada"]
    if f:
        k.set_label(t1, text=f"● Trabajando ahora: {f['id']}", color="blue")
        k.set_label(t2, text=f"{f['motor']}, lleva {f['tiempo']}, {f['costo']} ({f['fuente']})")
    else:
        k.set_label(t1, text="Ninguna tarea corriendo ahora.", color="muted")
        k.set_label(t2, text="Cuando el runner empiece una, se fija aquí con su motor, su tiempo y su coste.")
    _T45["fijada_dato"] = f


def _refresh_tasks_ui():
    """Pagina Tareas: estado, motor, ronda, costo acumulado y revision de
    cada tarea. Solo re-dibuja si algo cambio."""
    w = _widgets
    tree = w.get("tasks_tree")
    if tree is None:
        return
    _apr_ui_tick()  # la cuenta atras del vencimiento, aunque nada mas cambie
    try:
        RESULTS.mkdir(parents=True, exist_ok=True)
        files = list(RESULTS.glob("*.json"))
        fp = (len(files), max((f.stat().st_mtime for f in files), default=0),
              tuple(sorted(p.name for p in TASKS.glob("*.task.json"))),
              tuple(sorted(p.name for p in WAITING.glob("*.task.json"))), _ESP["filtro"], _T45["filtro"],
              _T45.get("busca", ""))
        if fp == _tasks_fp[0]:
            return
        if _tasks_fp[0] is not None and fp[:2] != _tasks_fp[0][:2]:  # resultados nuevos: la fila de hoy del historial
            _gh_en_fondo([datetime.now().astimezone().date().isoformat()], "resultado nuevo")
        _tasks_fp[0] = fp
        rows, today_total, total = _task_rows()
        sel = tree.selection()
        keep = sel[0] if sel else None
        for item in tree.get_children():
            tree.delete(item)
        _tasks_rows.clear()
        # Filtro «solo las que esperan tu aprobacion» (clic en el contador o
        # en la bandeja); la fila fija de arriba dice que esta puesto.
        vista = [r for r in rows if _espera_de_verdad(r)] if _ESP["filtro"] else rows
        _pa = proyecto_activo()
        if _pa is not None:  # t-proyectos: solo las del proyecto activo (las de otros no se mezclan)
            vista = [r for r in vista if (r.get("fam") or {}).get("proyecto") == _pa["nombre"]]
        base = vista
        vista = tareas_filtrar(vista, _T45["filtro"])  # píldora de filtro (t-tareas-estadisticas-045)
        vista = tareas_buscar(vista, _T45.get("busca", ""))  # «Buscar o pedirle algo» (t-tareas-ctrlk-045)
        for r in vista[:TAREAS_MAX_FILAS]:
            iid = r["id"]
            _tasks_rows[iid] = r
            mod = r.get("modelo")
            tree.insert("", "end", iid=iid, tags=(r["estado"],), values=(
                r["id"], "● " + _estado_txt(r),
                _motor_modelo(_motor_txt(r["motor"], r["fam"]), mod),
                f"{r['ronda']}/{MAX_ROUNDS}" if r["ronda"] is not None else "—",
                _fmt_secs(r.get("dur")),
                (f"{_fmt_tok(r['tin'])} / {_fmt_tok(r['tout'])}"
                 if r.get("tin") is not None or r.get("tout") is not None else "—"),
                _cost_cell(r),
                _rev_summary(r)))
        if keep and keep in _tasks_rows:
            tree.selection_set(keep)
        _tareas045_pintar(base)
        _apply_live_to_tree()  # la fila en curso, con los numeros del vivo
        _show_task_detail()
        _render_approvals(rows)
        if w.get("tasks_summary") is not None:
            waiting = sum(1 for r in rows if r["estado"] == "esperando_aprobacion")
            cola = cola_resumen()
            _pa2 = proyecto_activo()
            w["tasks_summary"].config(
                text=(f"Proyecto: {_pa2['nombre']} (solo sus tareas). " if _pa2 else "")
                     + f"{len(rows)} tareas. El gasto, separado en real, equivalente Max y local, "
                     "va en la tarjeta Gasto."
                     + (f" {waiting} esperan tu aprobación." if waiting else "")
                     + (f" En cola: {cola['pendiente']}." if cola["pendiente"] else "")
                     + (f" Próximo reintento a las {cola['proximo_reintento'][11:19]}."
                        if cola["proximo_reintento"] else "")
                     + (" Costo por tarea completada (con reintentos, rondas y revisiones): " + ", ".join(
                         f"{m} ${x['por_completada']:.2f} ({x['completadas']} de {x['familias']})"
                         for m, x in sorted(_cpc.items()) if x["por_completada"] is not None) + "."
                        if (_cpc := costo_por_tarea_completada()) and any(
                            x["por_completada"] is not None for x in _cpc.values()) else "")
                     + (f" ⚠ Cola en pausa: {_BREAKER['motivo']}. Reanúdala desde la paleta (Ctrl+K)."
                        if _BREAKER["pausado"] else ""))
        if w.get("nav_count_tareas") is not None:
            w["nav_count_tareas"].config(text=str(len(rows)))
    except Exception as e:
        log(f"tareas: no se pudo actualizar la lista ({type(e).__name__}: {e})")


_banner = {"id": None, "t0": 0.0, "shown": False}


def _refresh_banner():
    """Banner mientras un motor trabaja: paso actual + boton Parar."""
    b = _widgets.get("banner")
    if b is None:
        return
    cur, paso = state.get("current"), state.get("paso")
    if cur and paso:
        if _banner["id"] != cur:
            _banner.update(id=cur, t0=time.time())
        secs = int(time.time() - _banner["t0"])
        _widgets["banner_title"].config(text=paso)
        _widgets["banner_sub"].config(
            text=f"Tarea {cur}, lleva {secs // 60}:{secs % 60:02d}. Parar mata el proceso del motor.")
        if not _banner["shown"]:
            b.pack(fill="x", padx=20, pady=(12, 0))
            _banner["shown"] = True
    elif _banner["shown"]:
        b.pack_forget()
        # Tk no encoge el contenedor al quitarle su unico hijo: se fuerza.
        b.master.configure(height=1)
        _banner.update(shown=False, id=None)


def _on_stop_click():
    cur = state.get("current")
    if not cur:
        messagebox.showinfo("Parar", "No hay ninguna tarea corriendo.")
        return
    if not messagebox.askyesno("Parar", f"¿Parar {cur}?\n\nSe mata el proceso del motor y no se "
                                        "crean más rondas de corrección."):
        return
    threading.Thread(target=stop_current_task, daemon=True).start()


def _on_guardrail(level):
    var = _widgets.get("guardrail_var")
    prev = guardrail_level()
    if level == prev:
        return
    if level == "nunca":
        ok = messagebox.askyesno(
            "Hazlo sin preguntar",
            "Con esto Growi podrá borrar, publicar, gastar dinero y enviar mensajes "
            "sin enseñarte el plan antes.\n\n¿Seguro que quieres quitar la pregunta?",
            icon="warning", default="no")
        if ok:
            from tkinter import simpledialog
            typed = simpledialog.askstring(
                "Confirmación doble", "Para confirmarlo, escribe: sin preguntar", parent=_root)
            ok = _norm(typed or "").strip() == "sin preguntar"
            if not ok and typed is not None:
                messagebox.showinfo("Hazlo sin preguntar", "No coincide; se queda como estaba.")
        if not ok:
            if var is not None:
                var.set(prev)
            return
    s = load_settings()
    s["guardrail"] = level
    save_settings(s)
    log("ajustes: permisos -> " + next(l for k, l, _x in GUARDRAIL_LEVELS if k == level))
    _espera_refrescar()  # fila de Tareas y bandeja con el nivel nuevo, al instante


# ---------------------------------------------------------------- guardrail siempre a la vista
# El 25 oct 2026 quedaron 7-9 tareas retenidas en «esperando_aprobacion» sin
# que nadie lo viera. Desde aqui el nivel de permisos y las tareas en espera
# se ven siempre: fila fija arriba de Tareas, icono y tooltip de la bandeja y
# un popup cuando hay tareas esperando. El numero es el REAL: sale de la misma
# cola.db del runner, cruzada con la carpeta esperando/ (donde el runner deja
# el encargo y de donde nunca lo recoge solo). Nada de contador propio ni
# cacheado; si no se puede leer, se dice («No se pudo leer el estado»).
GUARDRAIL_CORTO = {"siempre": "Siempre pregunta", "delicado": "Solo lo delicado",
                   "nunca": "Sin preguntar"}
ESPERA_CADA_S = 2.0      # el hilo lee cada 2 s (y al momento tras aprobar/rechazar)
ESPERA_AGRUPAR_S = 6.0       # las que entran juntas van en UN solo popup (calma tras la ultima)
ESPERA_AGRUPAR_MAX_S = 25.0  # tope: el aviso nunca se retrasa mas que esto
_ESP = {"dato": None, "nivel": None, "wake": threading.Event(), "hilo": False,
        "pintado": None, "avisados": None, "previas": set(), "pend": 0.0, "pend_ini": 0.0,
        "popup": None, "filtro": False, "msg": None, "kit": None}


def _tareas_txt(n):
    return "1 tarea" if n == 1 else f"{n} tareas"


def espera_popup_texto(n):
    return ("1 tarea está esperando por su aprobación" if n == 1
            else f"{n} tareas están esperando por su aprobación")


def espera_tooltip_texto(n):
    return "Ninguna tarea esperando" if not n else f"{_tareas_txt(n)} esperando tu aprobación"


def _rojo_contador():
    # El rojo del tema: en claro #C81E1E (5,74:1 sobre blanco; nunca #FF6363,
    # 2,91:1); en el oscuro Raycast #FF453A (5,63:1), porque #FF6363 es alli
    # el acento de las acciones primarias.
    return THEME["red"]


def tareas_en_espera():
    """Las tareas que esperan tu aprobacion, leidas del mismo estado que usa
    el runner: {"n", "ids", "fuente", "error"}. Con error, n es None (nunca
    un 0 falso). Retenida de verdad = su encargo esta en esperando/ (el
    runner lo aparca ahi y nunca lo recoge solo; Aprobar lo saca). cola.db se
    lee en cada vuelta: si no responde, error; una fila en
    esperando_aprobacion cuyo encargo ya no esta no cuenta (ya no se puede
    aprobar: el numero nunca pasa de las retenidas reales) y un encargo que
    la base aun no apunto si cuenta (sigue retenido: nunca un 0 falso).
    Sin cola.db (cola aun no SQLite), la carpeta es el estado del runner."""
    try:
        files = {p.name for p in WAITING.glob("*.task.json")} if WAITING.is_dir() else set()
    except OSError as e:
        return {"n": None, "ids": (), "fuente": "", "error": f"no se pudo mirar la carpeta de espera ({e})"}
    # Las que aun estan en runner-tasks/ sin clasificar (el runner las mira de
    # una en una): el popup espera a que termine de aparcarlas para avisar UNA vez.
    try:
        en_cola = {p.name for p in TASKS.glob("*.task.json")}
    except OSError:
        en_cola = set()
    rows = None
    if COLA_DB.is_file():
        try:
            con = sqlite3.connect(str(COLA_DB), timeout=1.5)
            try:
                rows = con.execute("SELECT id, archivo FROM tareas "
                                   "WHERE estado='esperando_aprobacion'").fetchall()
                reint = {Path(a or "").name for (a,) in con.execute(
                    "SELECT archivo FROM tareas WHERE estado='en_cola' AND proximo_intento > ?",
                    (time.time(),))}
            finally:
                con.close()
        except sqlite3.Error as e:
            if "no such table" not in str(e):
                return {"n": None, "ids": (), "fuente": "cola.db", "error": f"la cola no responde ({e})"}
    if rows is None:
        ids = sorted(f[:-len(".task.json")] for f in files)
        return {"n": len(ids), "ids": tuple(ids), "fuente": "carpeta esperando", "error": None,
                "por_clasificar": len(en_cola)}
    en_base = {Path(a or f"{t}.task.json").name for t, a in rows}
    # La clave es el nombre del encargo: no cambia entre «recien aparcada» y
    # «apuntada en la base» (asi una misma tarea nunca cuenta como nueva dos veces).
    ids = sorted(f[:-len(".task.json")] for f in files)
    return {"n": len(ids), "ids": tuple(ids), "fuente": "cola.db", "error": None,
            "sin_apuntar": sorted(files - en_base), "solo_en_base": len(en_base - files),
            "por_clasificar": len(en_cola - reint)}


def _espera_hilo():
    while True:
        _ESP["wake"].clear()
        try:
            d = tareas_en_espera()
        except Exception as e:
            d = {"n": None, "ids": (), "fuente": "", "error": f"{type(e).__name__}: {e}"}
        d["at"] = time.time()
        _ESP["dato"] = d
        _ESP["wake"].wait(ESPERA_CADA_S)


def _espera_arrancar():
    if not _ESP["hilo"]:
        _ESP["hilo"] = True
        threading.Thread(target=_espera_hilo, daemon=True, name="guardrail-espera").start()


def _espera_refrescar():
    """Tras aprobar, rechazar o cambiar el nivel: leer ya y repintar ya."""
    _ESP["wake"].set()
    _ESP["pintado"] = None
    if _root is not None:
        for ms in (150, 600):
            try:
                _root.after(ms, _espera_tick)
            except Exception:
                pass


def _espera_tick():
    """Cada segundo, en el hilo de la ventana: pinta la fila de Tareas y la
    bandeja y decide el popup con lo ultimo que leyo el hilo. La base nunca
    se lee aqui (la ventana no se congela aunque este bloqueada)."""
    _espera_arrancar()
    d = _ESP["dato"]
    if d is None:
        return
    nivel = guardrail_level()
    _ESP["nivel"] = nivel
    msg = _ESP["msg"]
    if msg and time.time() - msg[1] > 12:
        _ESP["msg"] = msg = None
    if _ESP["filtro"] and d["error"] is None and not d["n"]:
        _ESP["filtro"] = False  # ya no queda ninguna: vuelve la lista completa
        _ESP["msg"] = msg = ("Ya no queda ninguna tarea esperando; se ven todas.", time.time())
        _tasks_fp[0] = None
        _refresh_tasks_ui()
    huella = (nivel, d["n"], d["ids"], d["error"], _ESP["filtro"], msg and msg[0])
    if huella != _ESP["pintado"]:
        cambio_n = _ESP["pintado"] is None or _ESP["pintado"][1:4] != huella[1:4]
        _ESP["pintado"] = huella
        _espera_pintar_fila(nivel, d)
        _update_tray_title()
        if _tray_icon is not None:
            try:
                _tray_icon.update_menu()
            except Exception:
                pass
        if cambio_n:
            if d["error"]:
                log(f"guardrail: no se pudo leer el estado de las tareas en espera ({d['error']})")
            else:
                log(f"guardrail: {espera_tooltip_texto(d['n'])} (permisos: {GUARDRAIL_CORTO[nivel]}; "
                    f"leído de {d['fuente']})")
                if d.get("sin_apuntar"):
                    log("guardrail: en esperando/ pero aún sin apuntar en cola.db (cuentan): "
                        + ", ".join(d["sin_apuntar"][:5]))
    _espera_popup_decidir(d)


def _espera_pintar_fila(nivel, d):
    W, k = _widgets, _ESP["kit"]
    if k is None or W.get("gv_nivel") is None:
        return
    try:
        rojo = _rojo_contador()
        k.set_label(W["gv_nivel"], GUARDRAIL_CORTO[nivel],
                    {"siempre": "green_text", "delicado": "text", "nunca": rojo}[nivel])
        filtro = False
        if d["error"]:
            k.set_label(W["gv_cont"], "No se pudo leer el estado", rojo)
            nota = (f"No sé cuántas tareas esperan tu aprobación: {d['error']}. "
                    "No muestro un 0 que podría ser falso.")
        else:
            n = d["n"]
            k.set_label(W["gv_cont"], f"{n} esperando tu aprobación", rojo if n else "muted")
            if _ESP["filtro"]:
                filtro = True
                nota = (f"Se ven solo {'la' if n == 1 else 'las'} {_tareas_txt(n)} en espera, "
                        "con su plan y Aprobar o Rechazar.")
            elif nivel == "nunca":
                nota = ("Hazlo sin preguntar: Growi borra, publica, gasta y envía sin enseñarte "
                        "el plan. Cámbialo con «Cambiar nivel».")
            else:
                nota = next(x for kk, _l, x in GUARDRAIL_LEVELS if kk == nivel)
                if n:
                    nota = "Haz clic en el número para ver el plan de cada una. " + nota
        if _ESP["msg"]:
            nota = _ESP["msg"][0] + " " + nota
        k.set_label(W["gv_nota"], nota)
        ver = W.get("gv_ver")
        if ver is not None:
            if filtro and not ver.winfo_ismapped():
                ver.pack(side="right")
            elif not filtro and ver.winfo_ismapped():
                ver.pack_forget()
    except Exception as e:
        log(f"guardrail: no se pudo pintar la fila ({type(e).__name__}: {e})")


def _viendo_tareas():
    """El usuario esta en Tareas viendo la lista: ventana a la vista, en
    Tareas y con una ventana de este proceso en primer plano."""
    if _root is None or _widgets.get("pagina_actual") != "tareas":
        return False
    try:
        if _root.state() not in ("normal", "zoomed") or not _root.winfo_viewable():
            return False
    except Exception:
        return False
    try:
        import ctypes
        u = ctypes.windll.user32
        pid = ctypes.c_ulong()
        u.GetWindowThreadProcessId(u.GetForegroundWindow(), ctypes.byref(pid))
        return pid.value == os.getpid()
    except Exception:
        return True


def _espera_popup_decidir(d):
    """Anti-spam: un popup por evento (las que entran juntas, agrupadas), nunca
    otra vez por la misma espera, y ninguno si ya estas viendo Tareas."""
    if d["error"] is not None or d["n"] is None:
        return
    ids, now = set(d["ids"]), time.time()
    if _ESP["avisados"] is None:  # primera lectura tras arrancar: aviso sin esperar
        _ESP["avisados"], _ESP["previas"] = set(), set(ids)
        if ids:
            _ESP["pend"] = _ESP["pend_ini"] = now
    av = _ESP["avisados"]
    av &= ids  # las que salieron de la espera dejan de contar como avisadas
    nuevas = ids - av
    if nuevas and ids - _ESP["previas"]:
        # Acaba de entrar alguna: el runner aparca de una en una (unos
        # segundos entre cada una), asi que se espera a que se calme.
        if not _ESP["pend"]:
            _ESP["pend_ini"] = now
        _ESP["pend"] = now + ESPERA_AGRUPAR_S
    _ESP["previas"] = set(ids)
    pop = _ESP["popup"]
    if pop is not None:
        try:
            if not ids:
                _espera_popup_cerrar()
            else:
                pop._set_n(len(ids))  # el abierto lleva siempre el total real
        except Exception:
            _ESP["popup"] = None
    if not _ESP["pend"]:
        return
    if not nuevas:
        _ESP["pend"] = 0.0
        return
    # Listo cuando no entra ninguna desde hace ESPERA_AGRUPAR_S y el runner ya
    # clasifico lo que habia en la cola (o, como mucho, ESPERA_AGRUPAR_MAX_S).
    if now < _ESP["pend"] or (d.get("por_clasificar")
                              and now - _ESP["pend_ini"] < ESPERA_AGRUPAR_MAX_S):
        return
    _ESP["pend"] = 0.0
    av |= ids
    if _ESP["popup"] is not None:
        return  # ya hay uno abierto y ya dice el total: no se abre otro
    if _viendo_tareas():
        log(f"guardrail: sin popup ({_tareas_txt(len(ids))} en espera; ya estás viendo Tareas)")
        return
    _espera_popup(len(ids))


def _espera_popup_cerrar():
    pop, _ESP["popup"] = _ESP["popup"], None
    if pop is not None:
        try:
            pop.destroy()
        except Exception:
            pass


def _espera_popup(n):
    """Popup «N tareas están esperando por su aprobación» + «Ver tareas».
    Superficie nueva: CustomTkinter, con la version clasica de respaldo."""
    pop = _ESP["popup"]
    if pop is not None:
        try:
            if pop.winfo_exists():
                pop._set_n(n)
                pop.deiconify()
                pop.lift()
                return
        except Exception:
            pass
    top = tk.Toplevel(_root)
    top.withdraw()
    top.title("Growi Bridge")
    top.configure(bg=THEME["bg"])
    top.resizable(False, False)
    try:
        top.attributes("-topmost", True)
        if ICO.is_file():
            top.iconbitmap(str(ICO))
    except Exception:
        pass
    kit, t0 = None, time.perf_counter()
    if _ctk_wanted():
        try:
            # La escala y el tema de CTk ya los fijo la fila de Tareas al arrancar.
            kit = _KitCtk(top, global_setup=not _widgets.get("gv_ctk"))
            _espera_popup_con(kit, top, n)
        except Exception as e:
            log(f"guardrail: popup sin CustomTkinter ({type(e).__name__}: {e}); se usa el clásico")
            for ch in top.winfo_children():
                try:
                    ch.destroy()
                except Exception:
                    pass
            kit = None
    if kit is None:
        kit = _KitTk(top)
        _espera_popup_con(kit, top, n)
    top._kit = kit.nombre
    top.protocol("WM_DELETE_WINDOW", _espera_popup_cerrar)
    top.update_idletasks()
    w, h = top.winfo_reqwidth(), top.winfo_reqheight()
    top.geometry(f"+{max(0, top.winfo_screenwidth() - w - S(24))}+"
                 f"{max(0, top.winfo_screenheight() - h - S(72))}")
    top.deiconify()
    top.lift()
    _ESP["popup"] = top
    try:
        import winsound
        winsound.MessageBeep(0x40)
    except Exception:
        pass
    log(f"guardrail: popup «{espera_popup_texto(n)}» ({kit.nombre}, "
        f"{(time.perf_counter() - t0) * 1000:.0f} ms)")


def _espera_popup_con(kit, top, n):
    card = kit.card(top)
    card.pack(fill="both", expand=True, padx=12, pady=12)
    titulo = kit.title(card, espera_popup_texto(n))
    titulo.pack(anchor="w", padx=18, pady=(16, 4))
    nivel = GUARDRAIL_CORTO.get(_ESP["nivel"] or guardrail_level(), "")
    kit.label(card, f"Permisos: {nivel}. No se hacen hasta que las apruebes o las "
                    "rechaces en Tareas.", muted=True, wrap=360).pack(anchor="w", padx=18)
    brow = kit.frame(card)
    brow.pack(anchor="e", padx=18, pady=(14, 16))
    kit.button(brow, "Cerrar", _espera_popup_cerrar).pack(side="right")
    ver = kit.button(brow, "Ver tareas", lambda: (_espera_popup_cerrar(), abrir_lista_espera()),
                     accent=True)
    ver.pack(side="right", padx=(0, 8))
    top._ver = ver
    top._titulo = titulo

    def _set_n(m):
        kit.set_label(titulo, espera_popup_texto(m))
    top._set_n = _set_n


def _scroll_a(widget, margen=24):
    """Mueve la pagina que se ve hasta el widget."""
    try:
        _root.update_idletasks()
        for c in _scroll_canvases:
            if c.winfo_ismapped():
                inner = c.winfo_children()[0]
                y = widget.winfo_rooty() - inner.winfo_rooty()
                c.yview_moveto(max(0.0, (y - margen) / max(1, inner.winfo_height())))
                return
    except Exception:
        pass


def abrir_lista_espera(_e=None):
    """Clic en el contador de Tareas, en el icono de la bandeja o en «Ver
    tareas»: Tareas filtrada a las que esperan tu aprobacion, cada una con su
    plan y Aprobar / Rechazar. Si no hay ninguna, Tareas sin filtro y lo dice."""
    d = tareas_en_espera()  # lectura fresca al hacer clic
    d["at"] = time.time()
    _ESP["dato"] = d
    if d["error"]:
        _ESP["filtro"] = False
        _ESP["msg"] = ("No se pudo leer el estado; se ven todas las tareas.", time.time())
    elif d["n"]:
        _ESP["filtro"] = True
        _ESP["msg"] = None
    else:
        _ESP["filtro"] = False
        _ESP["msg"] = ("Ninguna tarea espera tu aprobación; se ven todas.", time.time())
    show_window()
    show = _widgets.get("show_page")
    if show:
        show("tareas")  # repinta la lista ya con el filtro
    _approvals_fp[0] = None
    _tasks_fp[0] = None
    _refresh_tasks_ui()
    _ESP["pintado"] = None
    _espera_tick()
    if _ESP["filtro"] and _widgets.get("approvals_box") is not None:
        _scroll_a(_widgets["approvals_box"])
    log("guardrail: abres Tareas " + (f"filtrada a {_tareas_txt(d['n'])} en espera" if _ESP["filtro"]
                                     else "sin filtro"))


def ver_todas_tareas():
    _ESP["filtro"] = False
    _ESP["msg"] = None
    _tasks_fp[0] = None
    _refresh_tasks_ui()
    _ESP["pintado"] = None
    _espera_tick()


def abrir_permisos():
    """«Cambiar nivel»: Ajustes, en Permisos."""
    show_window()
    show = _widgets.get("show_page")
    if show:
        show("ajustes")
    if _widgets.get("permisos_anchor") is not None:
        _scroll_a(_widgets["permisos_anchor"], margen=48)


def _build_guardrail_fila(holder):
    """Fila fija arriba de Tareas (fuera del scroll: siempre a la vista):
    nivel de permisos, «N esperando tu aprobación» y «Cambiar nivel».
    CustomTkinter o, si no se puede, la version clasica (el mismo codigo)."""
    canvas = next((c for c in holder.winfo_children() if isinstance(c, tk.Canvas)), None)
    slot = tk.Frame(holder, bg=THEME["bg"])
    if canvas is not None:
        slot.pack(side="top", fill="x", before=canvas)
    else:
        slot.pack(side="top", fill="x")
    t0 = time.perf_counter()
    if _ctk_wanted():
        try:
            # Si las tarjetas de Motores ya fijaron la escala y el tema de CTk, no
            # se vuelve a aplicar (re-escalaria todo lo ya dibujado).
            kit = _KitCtk(slot, global_setup=not _MOT.get("ctk"))
            _espera_fila_con(kit, slot)
            _ESP["kit"] = kit
            _widgets["gv_ctk"] = True
            log(f"guardrail: fila de Tareas con CustomTkinter {kit.ctk.__version__} "
                f"({(time.perf_counter() - t0) * 1000:.0f} ms)")
            return
        except Exception as e:
            log(f"guardrail: fila sin CustomTkinter ({type(e).__name__}: {e}); se usa la clásica")
            for ch in slot.winfo_children():
                try:
                    ch.destroy()
                except Exception:
                    pass
    kit = _KitTk(slot)
    _espera_fila_con(kit, slot)
    _ESP["kit"] = kit
    _widgets["gv_ctk"] = False


def _espera_fila_con(kit, slot):
    card = kit.card(slot)
    card.pack(fill="x", padx=20, pady=(14, 2))
    r = kit.frame(card)
    r.pack(fill="x", padx=16, pady=(10, 2))
    kit.label(r, "Permisos", muted=True, wrap=0).pack(side="left", padx=(0, 6))
    nivel = kit.label(r, "", bold=True, wrap=0)
    nivel.pack(side="left")
    cont = kit.label(r, "Leyendo…", bold=True, wrap=0)
    cont.pack(side="left", padx=(28, 0))
    cont.configure(cursor="hand2")
    cont.bind("<Button-1>", abrir_lista_espera)
    kit.button(r, "Cambiar nivel", abrir_permisos).pack(side="right")
    r2 = kit.frame(card)
    r2.pack(fill="x", padx=16, pady=(0, 10))
    ver = kit.button(r2, "Ver todas", ver_todas_tareas)
    nota = kit.label(r2, "", muted=True, wrap=520)
    nota.pack(side="left", fill="x", expand=True)
    _widgets.update(gv_nivel=nivel, gv_cont=cont, gv_nota=nota, gv_ver=ver)


# ---------------------------------------------------------------- librero (descargador GGUF)
# llama-server no tiene pull, ni catalogo, ni verificacion, ni borrado: el
# librero pone las cuatro cosas, solo con la stdlib (t-descargador-gguf, 0.3.0).
# - Se baja a models\<archivo>.part (nunca al .gguf final) con
#   «Range: bytes=<ya_bajado>-» y flush + os.fsync cada LIB_FSYNC_BYTES o
#   LIB_FSYNC_S. Tras cada fsync se reescribe <archivo>.download.json (url,
#   revision, bytes, total, etag, updated_at): «bytes» es lo que YA esta en el
#   disco, asi que tras un corte de luz el .part se recorta a ese numero.
# - Al reintentar: HEAD sin seguir la redireccion. Si responde
#   «Accept-Ranges: bytes» y el ETag y el tamano son los guardados, se sigue
#   donde quedo; si no, se descarta el .part y se empieza de cero diciendo por
#   que. Si el CDN ignora el Range (200 en vez de 206), tambien de cero.
# - Al terminar: tamano exacto, magic «GGUF» en la cabecera y sha256 del archivo
#   completo contra el del catalogo (el que publica la API de HF para ese blob
#   LFS; no se calcula en el PC). Solo si cuadra: os.replace(.part -> .gguf) en
#   la misma carpeta y la entrada de models-library.json. Si ya habia un .gguf
#   (otra revision), se guarda como .bak (enlace duro, sin copiar 5 GB) y no se
#   borra hasta que el nuevo arranque una vez y el usuario lo pida.
# - Un .part o un .gguf sin sha256 verificado nunca se lista como instalado.
# Medido el 26 oct 2026 desde el PC (ESTADO-DESCARGADOR-GGUF): huggingface.co
# responde directo (~11 MB/s) y por el proxy del Bridge (~3 MB/s); /resolve/
# contesta 302 a un CDN con URL firmada (se pide de nuevo en cada intento),
# X-Linked-ETag = sha256 del blob (estable) y el CDN da 206 con Range.
MODELS_DIR = APP_DIR / "models"
LIBRARY_FILE = APP_DIR / "models-library.json"
HF_BASE = "https://huggingface.co"
LIB_RETRY_S = (1, 2, 4, 8, 16)  # backoff de los reintentos de red / 5xx (max. 5)
LIB_FSYNC_BYTES = 16 * 1048576
LIB_FSYNC_S = 2.0
LIB_CHUNK = 1048576
LIB_LOG_S = 10.0  # cada cuanto va el progreso al Registro
LIB_DISK_FACTOR = 1.1  # disco libre >= tamano x 1,1 (viejo + .part conviven)
LIB_SOURCES = ("bridge-downloader", "copia-ollama", "manual")
_LIB = {"job": None, "lock": threading.Lock(), "hash": {}, "scan": None, "ver": 0}


class _LibError(Exception):
    """Error del librero. definitivo=True: no se reintenta (404, 403, sha256)."""

    def __init__(self, msg, definitivo=False):
        super().__init__(msg)
        self.definitivo = definitivo


def lib_load():
    """models-library.json: lo que el librero instalo o registro, con su sha256
    comprobado. Sin archivo o roto -> vacio (nunca inventa entradas)."""
    try:
        data = json.loads(LIBRARY_FILE.read_text(encoding="utf-8"))
        if isinstance(data, dict) and isinstance(data.get("modelos"), list):
            return data
    except (OSError, ValueError):
        pass
    return {"_que_es": ("Modelos GGUF instalados en models\\ con su sha256 comprobado. Lo "
                        "escribe el librero (descargador GGUF) de Growi Bridge; un .part "
                        "o un .gguf sin sha256 verificado nunca aparece aqui. revision = "
                        "commit de Hugging Face fijado (nunca 'main')."),
            "esquema": 1, "modelos": []}


def _write_json_atomic(path, data):
    tmp = Path(str(path) + ".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(json.dumps(data, ensure_ascii=False, indent=2))
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def lib_save(data):
    _write_json_atomic(LIBRARY_FILE, data)
    _LIB["ver"] += 1


def lib_quant(filename):
    m = re.search(r"(IQ\d_[A-Z0-9_]+|Q\d_K_[SML]|Q\d_K|Q\d_\d|Q\d|BF16|F16|F32)",
                  str(filename).upper())
    return m.group(1) if m else None


def lib_installed():
    """Entradas del manifiesto cuyo .gguf (y su mmproj) esta en models\\ con el
    tamano exacto. Lo que falta o cambio de tamano no se lista como instalado."""
    out = []
    for e in lib_load()["modelos"]:
        p = MODELS_DIR / str(e.get("filename") or "")
        ok = bool(e.get("sha256")) and p.is_file() and p.stat().st_size == e.get("size_bytes")
        mm = e.get("mmproj")
        if ok and mm:
            q = MODELS_DIR / str(mm.get("filename") or "")
            ok = q.is_file() and q.stat().st_size == mm.get("size_bytes")
        if ok:
            out.append(e)
    return out


def lib_entry_for(cat_id):
    return next((e for e in lib_installed() if e.get("id") == cat_id), None)


def gguf_header(path):
    """Comprobacion barata de formato: magic «GGUF», version (1-3) y los dos
    contadores de la cabecera (tensores y metadatos) con valores sensatos.
    Devuelve (ok, motivo)."""
    import struct
    try:
        with open(path, "rb") as f:
            head = f.read(24)
    except OSError as e:
        return False, f"no pude leerlo ({e})"
    if len(head) < 24:
        return False, "es demasiado corto para ser un GGUF"
    if head[:4] != b"GGUF":
        return False, f"no empieza por «GGUF» (empieza por {head[:4]!r})"
    ver, n_t, n_kv = struct.unpack("<IQQ", head[4:24])
    if ver not in (1, 2, 3):
        return False, f"version de GGUF desconocida ({ver})"
    if not (0 < n_t < 1_000_000 and 0 <= n_kv < 100_000):
        return False, f"cabecera rara ({n_t} tensores, {n_kv} metadatos)"
    return True, f"GGUF v{ver}, {n_t} tensores, {n_kv} metadatos"


def sha256_file(path, on_progress=None, stop=None):
    """sha256 en trozos de 4 MiB (no carga 5 GB en memoria). on_progress(hecho,
    total) cada ~0,5 s; stop() True -> None (parado)."""
    import hashlib
    h = hashlib.sha256()
    total = Path(path).stat().st_size
    done, t_last = 0, 0.0
    with open(path, "rb") as f:
        while True:
            b = f.read(4 * 1048576)
            if not b:
                break
            h.update(b)
            done += len(b)
            if stop and stop():
                return None
            if on_progress and time.time() - t_last > 0.5:
                t_last = time.time()
                on_progress(done, total)
    if on_progress:
        on_progress(done, total)
    return h.hexdigest()


def _lib_opener(via_proxy, follow=True):
    """Opener de urllib: directo (sin el proxy de las variables) o por el proxy
    del Bridge (proxy.json). follow=False no sigue la redireccion (HEAD)."""
    purl = proxy_url() if via_proxy else ""
    if via_proxy and not purl:
        raise _LibError("no hay proxy guardado en el Bridge", definitivo=True)
    hs = [urllib.request.ProxyHandler({"http": purl, "https": purl} if purl else {})]
    if not follow:
        class _NoRedir(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **k):
                return None
        hs.append(_NoRedir())
    return urllib.request.build_opener(*hs)


def _lib_ua():
    return {"User-Agent": f"GrowiBridge/{VERSION} (librero)"}


def lib_route(repo):
    """(via_proxy, texto para la UI). Directo si huggingface.co contesta; si no,
    por el proxy del Bridge, y se dice. settings «librero_ruta»: auto (por
    defecto) / directo / proxy."""
    pref = str(load_settings().get("librero_ruta") or "auto")
    if pref == "proxy":
        return True, "por el proxy del Bridge (elegido en settings.json)"
    hf = mapa_fila("huggingface") if pref == "auto" else None  # lo que ya midio el mapa (t-mapa-ampliado)
    if hf and hf.get("ruta") == "proxy" and proxy_url():
        return True, f"por el proxy del Bridge (el mapa dice: {hf.get('frase')})"
    if hf and hf.get("ruta") in ("directo", "ambas"):
        return False, f"directo a huggingface.co (el mapa dice: {hf.get('frase')})"
    url = f"{HF_BASE}/api/models/{repo}"
    try:
        _lib_opener(False).open(urllib.request.Request(url, headers=_lib_ua()), timeout=8).close()
        return False, "directo a huggingface.co"
    except urllib.error.HTTPError:
        return False, "directo a huggingface.co"  # contesta (aunque sea un 4xx)
    except Exception as e:
        why = _net_reason(e)
    if pref == "directo" or not proxy_url():
        return False, f"directo a huggingface.co (no contesta: {why}; no hay proxy guardado)"
    return True, f"por el proxy del Bridge (huggingface.co no responde directo: {why})"


def hf_url(repo, revision, filename):
    from urllib.parse import quote
    return f"{HF_BASE}/{repo}/resolve/{quote(revision)}/{quote(filename)}"


def lib_head(url, via_proxy):
    """HEAD a huggingface.co sin seguir la redireccion: ETag del blob
    (X-Linked-ETag = sha256 en los LFS), tamano, Accept-Ranges y commit."""
    req = urllib.request.Request(url, method="HEAD", headers=_lib_ua())
    try:
        r = _lib_opener(via_proxy, follow=False).open(req, timeout=20)
        code, h = r.status, r.headers
        r.close()
    except urllib.error.HTTPError as e:
        code, h = e.code, e.headers
    if code in (401, 403, 404):
        raise _LibError(f"Hugging Face contesta {code} "
                        + {404: "(no existe ese archivo en esa revision)",
                           403: "(acceso prohibido: el repo pide aceptar condiciones o clave)",
                           401: "(pide iniciar sesion: el repo es privado o restringido)"}[code],
                        definitivo=True)
    if code >= 500 or code == 429:
        raise _LibError(f"Hugging Face contesta {code} (problema suyo; reintento)")
    if code not in (200, 301, 302, 307, 308):
        raise _LibError(f"Hugging Face contesta {code} al HEAD", definitivo=code < 500)

    def g(*names):
        for n in names:
            v = h.get(n)
            if v:
                return v
        return None
    etag = (g("X-Linked-ETag", "ETag") or "").strip().strip('"')
    if etag.startswith("W/"):
        etag = etag[2:].strip('"')
    size = g("X-Linked-Size", "Content-Length") if code != 200 else g("Content-Length")
    return {"code": code, "etag": etag, "size": int(size) if size and size.isdigit() else None,
            "ranges": "bytes" in (g("Accept-Ranges") or "").lower(),
            "commit": g("X-Repo-Commit")}


def lib_files_for(cat):
    """Archivos que hay que bajar para un modelo del catalogo (el GGUF y su
    mmproj si lo lleva), con revision y sha256 fijados."""
    g = cat.get("gguf") or {}
    files = [{"rol": "modelo", "hf": g.get("archivo"), "local": g.get("archivo"),
              "bytes": g.get("bytes"), "sha256": g.get("sha256")}]
    mm = g.get("mmproj")
    if isinstance(mm, dict) and mm.get("archivo"):
        stem = Path(str(g.get("archivo"))).stem
        files.append({"rol": "mmproj", "hf": mm["archivo"], "local": f"{stem}.{mm['archivo']}",
                      "bytes": mm.get("bytes"), "sha256": mm.get("sha256")})
    return files


def lib_catalog_problem(cat):
    """None si el catalogo trae todo lo que hace falta para bajarlo con
    garantias; si no, el motivo (en palabras normales)."""
    g = cat.get("gguf")
    if not isinstance(g, dict) or not g.get("repo") or not g.get("archivo"):
        return "no tiene GGUF en el catálogo"
    rev = str(g.get("revision") or "")
    if not re.fullmatch(r"[0-9a-f]{40}", rev):
        return "el catálogo no trae la revisión fijada (commit de Hugging Face); no lo bajo de «main»"
    for f in lib_files_for(cat):
        if not re.fullmatch(r"[0-9a-f]{64}", str(f.get("sha256") or "")):
            return f"el catálogo no trae el sha256 de {f['hf']}: sin él no se puede comprobar"
        if not isinstance(f.get("bytes"), int) or f["bytes"] <= 0:
            return f"el catálogo no trae el tamaño de {f['hf']}"
    return None


def _part_paths(local):
    p = MODELS_DIR / f"{local}.part"
    return p, MODELS_DIR / f"{local}.download.json"


def _read_meta(meta_p):
    try:
        d = json.loads(Path(meta_p).read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None


def lib_partial(cat):
    """(bytes ya bajados, total) de una descarga a medias de este modelo, o None."""
    done = total = 0
    found = False
    for f in lib_files_for(cat):
        part, meta_p = _part_paths(f["local"])
        meta = _read_meta(meta_p)
        total += f["bytes"] or 0
        if meta and part.is_file():
            found = True
            done += min(int(meta.get("bytes") or 0), part.stat().st_size)
    return (done, total) if found else None


def _fmt_mb(n):
    return f"{n / 1048576:,.1f}".replace(",", " ")


def _fmt_eta(s):
    if s is None:
        return "calculando…"
    s = int(s)
    if s < 60:
        return f"{s} s"
    if s < 3600:
        return f"{s // 60} min {s % 60:02d} s"
    return f"{s // 3600} h {s % 3600 // 60:02d} min"


def lib_progress_text(job):
    """«120.3 de 609.5 MB (19.7 %) · 10.8 MB/s · faltan 45 s»: bytes, total,
    velocidad y tiempo restante reales, no solo el %."""
    b, t = job.get("bytes", 0), job.get("total") or 0
    pct = (100.0 * b / t) if t else 0.0
    txt = f"{_fmt_mb(b)} de {_fmt_mb(t)} MB ({pct:.1f} %)"
    if job.get("estado") == "descargando":
        sp = job.get("speed")
        txt += (f", {sp / 1048576:.1f} MB/s, faltan {_fmt_eta(job.get('eta'))}"
                if sp else ", midiendo la velocidad…")
    return txt


def lib_disk_check(cat):
    """(ok, texto). Disco libre >= lo que falta por bajar x 1,1 (la version vieja
    y el .part nuevo conviven hasta verificar)."""
    need = 0
    for f in lib_files_for(cat):
        part, meta_p = _part_paths(f["local"])
        have = part.stat().st_size if part.is_file() and _read_meta(meta_p) else 0
        need += max(0, (f["bytes"] or 0) - have)
    need = int(need * LIB_DISK_FACTOR)
    MODELS_DIR.mkdir(parents=True, exist_ok=True)
    free = shutil.disk_usage(MODELS_DIR).free
    if free < need:
        return False, (f"No hay sitio en el disco: hacen falta {_gb(need / 1e9)} GB libres y "
                       f"quedan {_gb(free / 1e9)} GB. Borra algo (o un modelo que no uses) y "
                       "vuelve a intentarlo.")
    return True, f"disco libre {_gb(free / 1e9)} GB, hacen falta {_gb(need / 1e9)} GB"


def lib_start(cat):
    """Funcion principal del librero: arranca la descarga de un modelo del
    catalogo en un hilo aparte (una sola a la vez). Devuelve (ok, texto)."""
    with _LIB["lock"]:
        j = _LIB["job"]
        if j and j.get("estado") not in ("listo", "error", "cancelado"):
            return False, f"Ya hay una descarga en curso ({j['name']}). Una sola a la vez."
        prob = lib_catalog_problem(cat)
        if prob:
            return False, f"No se puede bajar {cat.get('name')}: {prob}."
        ok, disk = lib_disk_check(cat)
        if not ok:
            return False, disk
        job = {"id": cat["id"], "name": cat.get("name") or cat["id"], "cat": cat,
               "estado": "conectando", "bytes": 0, "total": sum(f["bytes"] for f in lib_files_for(cat)),
               "speed": None, "eta": None, "msg": "", "ruta": "", "aviso": "", "intento": 0,
               "pause": threading.Event(), "cancel": threading.Event(), "borrar": False,
               "t0": time.time()}
        _LIB["job"] = job
    log(f"librero: empieza {job['name']} ({_gb(job['total'] / 1e9)} GB, {disk})")
    threading.Thread(target=_lib_run, args=(job,), daemon=True, name="librero").start()
    return True, f"Descargando {job['name']}…"


def _lib_set(job, estado, msg=None):
    job["estado"] = estado
    if msg is not None:
        job["msg"] = msg


def _lib_run(job):
    cat = job["cat"]
    g = cat["gguf"]
    files = lib_files_for(cat)
    try:
        via, ruta = lib_route(g["repo"])
        job["via"], job["ruta"] = via, ruta
        log(f"librero: {job['name']}: voy {ruta}")
        base = 0
        for f in files:
            _lib_download_file(job, g, f, base)
            if job["cancel"].is_set():
                break
            _lib_verify(job, f)
            base += f["bytes"]
        if job["cancel"].is_set():
            if job["borrar"]:
                for f in files:
                    for p in _part_paths(f["local"]):
                        _rm_quiet(p)
                msg = "Cancelada y borrado lo bajado."
            else:
                msg = "Cancelada. Lo bajado se conserva: «Reanudar» sigue donde quedó."
            _lib_set(job, "cancelado", msg)
            log(f"librero: {job['name']}: {msg}")
            return
        _lib_publish(job, files)
        secs = time.time() - job["t0"]
        _lib_set(job, "listo", f"{job['name']} quedó instalado y comprobado (sha256 OK) "
                               f"en {_fmt_eta(secs)}.")
        log(f"librero: {job['msg']}")
    except _LibError as e:
        _lib_set(job, "error", str(e))
        log(f"librero: {job['name']}: no se pudo: {e}")
    except Exception as e:
        _lib_set(job, "error", f"error inesperado ({type(e).__name__}: {e})")
        log(f"librero: {job['name']}: error inesperado ({type(e).__name__}: {e})")
    finally:
        _LIB["ver"] += 1


def _lib_wait(job, secs):
    """Espera secs (backoff) atenta a pausa y cancelar. True = seguir."""
    t_end = time.time() + secs
    while time.time() < t_end:
        if job["cancel"].is_set():
            return False
        time.sleep(0.2)
    return True


def _lib_hold_paused(job):
    """Mientras esta en pausa: espera a reanudar o cancelar."""
    while job["pause"].is_set() and not job["cancel"].is_set():
        time.sleep(0.2)


def _lib_download_file(job, g, f, base):
    """Baja un archivo a .part con reanudacion. Reintenta con backoff (1, 2, 4,
    8, 16 s) los errores de red y los 5xx: hasta 5 seguidos SIN avanzar (si un
    intento baja algo, la cuenta vuelve a cero). 404/403/401 = error visible,
    sin reintento."""
    url = hf_url(g["repo"], g["revision"], f["hf"])
    part, meta_p = _part_paths(f["local"])
    fallos = 0
    while True:
        if job["cancel"].is_set():
            return
        if job["pause"].is_set():
            _lib_set(job, "pausado", "En pausa. Lo bajado está a salvo en el disco.")
            _lib_hold_paused(job)
            continue
        avance = [False]
        try:
            _lib_attempt(job, url, g, f, part, meta_p, base, avance)
            if job["cancel"].is_set() or job["pause"].is_set():
                continue
            return
        except _LibError as e:
            if e.definitivo:
                raise
            err = str(e)
        except urllib.error.HTTPError as e:
            if e.code in (401, 403, 404) or (400 <= e.code < 500 and e.code not in (408, 429)):
                raise _LibError(f"el servidor contesta {e.code} ({e.reason})", definitivo=True)
            err = f"el servidor contesta {e.code}"
        except (urllib.error.URLError, OSError, http.client.HTTPException, ValueError) as e:
            err = _net_reason(e) if not isinstance(e, http.client.IncompleteRead) else "conexión cortada a mitad"
        fallos = 0 if avance[0] else fallos
        if fallos >= len(LIB_RETRY_S):
            raise _LibError(f"la red falló {fallos + 1} veces seguidas sin avanzar ({err}). "
                            "Lo bajado se conserva: pulsa Reanudar cuando vuelva la conexión.")
        espera = LIB_RETRY_S[fallos]
        fallos += 1
        job["intento"] = fallos
        _lib_set(job, "reintentando",
                 f"Se cortó ({err}). Reintento {fallos} de {len(LIB_RETRY_S)} en {espera} s…")
        log(f"librero: {job['name']}: {job['msg']}")
        if not _lib_wait(job, espera):
            return


def _lib_attempt(job, url, g, f, part, meta_p, base, avance):
    via = job.get("via", False)
    _lib_set(job, "conectando", "Preguntando a Hugging Face…")
    h = lib_head(url, via)
    if h["etag"] and f["sha256"] and re.fullmatch(r"[0-9a-f]{64}", h["etag"]) \
            and h["etag"] != f["sha256"]:
        raise _LibError(f"Hugging Face publica otro sha256 para {f['hf']} en esa revisión "
                        f"({h['etag'][:12]}…) que el del catálogo ({f['sha256'][:12]}…); no lo bajo",
                        definitivo=True)
    total = h["size"] or f["bytes"]
    if f["bytes"] and total != f["bytes"]:
        raise _LibError(f"el tamaño en Hugging Face ({total}) no es el del catálogo ({f['bytes']})",
                        definitivo=True)
    meta = _read_meta(meta_p)
    start = 0
    if part.is_file() and meta:
        motivo = None
        if meta.get("etag") != h["etag"]:
            motivo = "el archivo cambió en el servidor (ETag distinto)"
        elif meta.get("total") != total:
            motivo = "el tamaño en el servidor cambió"
        elif meta.get("revision") != g["revision"]:
            motivo = "es de otra revisión"
        elif not h["ranges"]:
            motivo = "el servidor no acepta continuar una descarga (sin Accept-Ranges: bytes)"
        if motivo:
            job["aviso"] = f"Empiezo de cero: {motivo}."
            log(f"librero: {job['name']}: descarto lo bajado de {f['hf']} y empiezo de cero: {motivo}")
        else:
            start = min(int(meta.get("bytes") or 0), part.stat().st_size)
    elif part.is_file():
        job["aviso"] = "Empiezo de cero: había un .part sin su .download.json (no sé de dónde salió)."
        log(f"librero: {job['name']}: {job['aviso']}")
    meta = {"url": url, "repo": g["repo"], "revision": g["revision"], "archivo": f["hf"],
            "bytes": start, "total": total, "etag": h["etag"], "sha256": f["sha256"],
            "updated_at": _now_iso()}
    hdrs = dict(_lib_ua())
    if start:
        hdrs["Range"] = f"bytes={start}-"
    if start >= total:
        job["bytes"] = base + total
        return
    r = _lib_opener(via).open(urllib.request.Request(url, headers=hdrs), timeout=30)
    try:
        if start and r.status == 200:
            job["aviso"] = ("Empiezo de cero: el servidor no respetó el rango pedido "
                            "(contestó 200 en vez de 206).")
            log(f"librero: {job['name']}: {job['aviso']}")
            start = 0
        elif start and r.status == 206:
            cr = r.headers.get("Content-Range") or ""
            m = re.match(r"bytes (\d+)-", cr)
            if not m or int(m.group(1)) != start:
                raise _LibError(f"el servidor devolvió otro rango ({cr})")
            log(f"librero: {job['name']}: reanudo {f['hf']} desde {_fmt_mb(start)} MB "
                f"(Range: bytes={start}-, 206)")
        mode = "r+b" if start else "wb"
        if start:
            with open(part, "r+b") as fx:
                fx.truncate(start)  # lo que no llego a fsync-arse se descarta
        meta["bytes"] = start
        _write_json_atomic(meta_p, meta)
        _lib_set(job, "descargando", "")
        win = [(time.time(), start)]
        t_sync, b_sync, t_log = time.time(), start, 0.0
        done = start
        with open(part, mode) as out:
            out.seek(start)
            while True:
                if job["cancel"].is_set() or job["pause"].is_set():
                    break
                chunk = r.read(LIB_CHUNK)
                if not chunk:
                    break
                out.write(chunk)
                done += len(chunk)
                avance[0] = True
                now = time.time()
                win.append((now, done))
                while len(win) > 2 and now - win[0][0] > 5:
                    win.pop(0)
                dt = now - win[0][0]
                job["speed"] = (done - win[0][1]) / dt if dt > 0.5 else None
                job["bytes"] = base + done
                job["eta"] = ((job["total"] - job["bytes"]) / job["speed"]) if job["speed"] else None
                if done - b_sync >= LIB_FSYNC_BYTES or now - t_sync >= LIB_FSYNC_S:
                    out.flush()
                    os.fsync(out.fileno())
                    meta["bytes"], meta["updated_at"] = done, _now_iso()
                    _write_json_atomic(meta_p, meta)
                    t_sync, b_sync = now, done
                if now - t_log >= LIB_LOG_S:
                    t_log = now
                    log(f"librero: {job['name']}: {lib_progress_text(job)} ({job.get('ruta')})")
            out.flush()
            os.fsync(out.fileno())
        meta["bytes"], meta["updated_at"] = done, _now_iso()
        _write_json_atomic(meta_p, meta)
    finally:
        try:
            r.close()
        except Exception:
            pass
    if job["cancel"].is_set() or job["pause"].is_set():
        return
    if done < total:
        raise _LibError(f"la conexión se cerró a los {_fmt_mb(done)} de {_fmt_mb(total)} MB")


def _lib_verify(job, f):
    """Verificacion en dos pasos: tamano + cabecera GGUF (barata) y sha256 del
    archivo completo contra el catalogo. Si falla, el .part NO se publica."""
    part, meta_p = _part_paths(f["local"])
    meta = _read_meta(meta_p) or {}
    size = part.stat().st_size
    if size != f["bytes"]:
        raise _LibError(f"{f['hf']}: tamaño {size} en vez de {f['bytes']} (descarga truncada)")
    ok, why = gguf_header(part)
    if not ok:
        meta["verificacion"] = f"cabecera mal: {why}"
        _write_json_atomic(meta_p, meta)
        raise _LibError(f"{f['hf']} no es un GGUF válido: {why}. No se publica.", definitivo=True)
    _lib_set(job, "verificando", "Comprobando el sha256…")
    log(f"librero: {job['name']}: {f['hf']} completo ({why}); compruebo el sha256")

    def prog(d, t):
        job["msg"] = f"Comprobando el sha256 de {f['hf']}: {100.0 * d / t:.0f} %"

    t0 = time.time()
    got = sha256_file(part, prog, stop=job["cancel"].is_set)
    if got is None:
        return
    if got != f["sha256"]:
        meta["verificacion"] = f"sha256 no coincide: {got}"
        meta["updated_at"] = _now_iso()
        _write_json_atomic(meta_p, meta)
        raise _LibError(f"{f['hf']} llegó dañado: su sha256 ({got[:12]}…) no es el del catálogo "
                        f"({f['sha256'][:12]}…). No se publica; «Descargar de nuevo» lo baja limpio.",
                        definitivo=True)
    meta["verificacion"] = "ok"
    meta["sha256_ok_at"] = _now_iso()
    _write_json_atomic(meta_p, meta)
    log(f"librero: {job['name']}: sha256 de {f['hf']} OK ({time.time() - t0:.1f} s)")


def _lib_publish(job, files):
    """Reemplazo atomico: solo con el sha256 ya comprobado, os.replace(.part ->
    .gguf) en la misma carpeta y despues la entrada del manifiesto. El .gguf
    viejo (otra revision) queda como .bak hasta que el nuevo arranque una vez."""
    cat = job["cat"]
    g = cat["gguf"]
    data = lib_load()
    old = next((e for e in data["modelos"] if e.get("id") == cat["id"]), None)
    anterior = None
    for f in files:
        part, meta_p = _part_paths(f["local"])
        if not part.is_file():
            continue  # mmproj ya instalado y comprobado
        if (_read_meta(meta_p) or {}).get("verificacion") != "ok":
            raise _LibError(f"{f['hf']} no está verificado: no se publica", definitivo=True)
        target = MODELS_DIR / f["local"]
        if target.is_file():
            rev = (old or {}).get("revision") or "anterior"
            bak = target.with_name(f"{target.name}.{rev[:8]}.bak")
            if not bak.exists():
                try:
                    os.link(target, bak)  # mismo archivo, sin copiar ni ocupar mas disco
                except OSError:
                    shutil.copy2(target, bak)
            if f["rol"] == "modelo":
                anterior = {"filename": bak.name, "revision": rev, "arranco_nuevo": False}
        os.replace(part, target)
        _rm_quiet(meta_p)
        log(f"librero: {job['name']}: publicado {target.name}")
    main = files[0]
    mm = files[1] if len(files) > 1 else None
    entry = {"id": cat["id"], "name": cat.get("name"), "repo_id": g["repo"],
             "revision": g["revision"], "filename": main["local"], "hf_filename": main["hf"],
             "size_bytes": main["bytes"], "sha256": main["sha256"],
             "quant": g.get("quant") or lib_quant(main["hf"]), "role": cat.get("kind") or None,
             "ctx_default": cat.get("ctx_default"),
             "mmproj": ({"filename": mm["local"], "hf_filename": mm["hf"],
                         "size_bytes": mm["bytes"], "sha256": mm["sha256"]} if mm else None),
             "installed_at": _now_iso(), "verified_at": _now_iso(),
             "source": "bridge-downloader", "anterior": anterior}
    data["modelos"] = [e for e in data["modelos"] if e.get("id") != cat["id"]] + [entry]
    lib_save(data)


def lib_pause():
    j = _LIB["job"]
    if j and j["estado"] in ("descargando", "conectando", "reintentando"):
        j["pause"].set()
        log(f"librero: {j['name']}: en pausa")
        return True
    return False


def lib_resume():
    j = _LIB["job"]
    if j and j["pause"].is_set():
        j["pause"].clear()
        log(f"librero: {j['name']}: reanudo")
        return True
    return False


def lib_cancel(borrar=False):
    j = _LIB["job"]
    if j and j["estado"] not in ("listo", "error", "cancelado"):
        j["borrar"] = bool(borrar)
        j["cancel"].set()
        j["pause"].clear()
        return True
    return False


def lib_discard_partial(cat):
    """«Borrar lo bajado» de una descarga a medias (lo pide el usuario)."""
    for f in lib_files_for(cat):
        for p in _part_paths(f["local"]):
            _rm_quiet(p)
    log(f"librero: borrado lo bajado a medias de {cat.get('name')}")


def lib_shutdown():
    """Al salir de la app: pausa la descarga (fsync + .download.json). El .part
    NO se borra: al volver, «Reanudar» sigue donde quedo."""
    if lib_pause():
        t_end = time.time() + 3
        while _LIB["job"]["estado"] not in ("pausado", "error", "cancelado", "listo") \
                and time.time() < t_end:
            time.sleep(0.1)


def lib_loaded():
    """{nombre de archivo: motivo} de los GGUF que un motor con bloque
    'servidor' (hoy llama-server) tiene cargado (GET /props) o configurado en
    su descriptor. Nada aqui depende del nombre del motor."""
    out = {}
    for mid in engine_ids():
        eng = get_engine(mid)
        srv = (eng or {}).get("servidor")
        if not isinstance(srv, dict):
            continue
        name = eng.get("nombre") or mid
        if srv.get("gguf"):
            out.setdefault(_app_path(srv["gguf"]).name.lower(),
                           f"es el modelo que usa «{name}» (engines.json); cámbialo allí antes")
        hc = (eng.get("healthcheck") or {}).get("url")
        if not hc:
            continue
        u = urlparse(hc)
        try:
            props = _http_local("GET", f"{u.scheme}://{u.netloc}/props", timeout=2)
            mp = str((props or {}).get("model_path") or "")
            if str((props or {}).get("role") or "") == "router":
                # Router: lo cargado lo dice GET /models (model_path es «none»).
                for mod, st in srv_modelos(eng, timeout=2).items():
                    if st in ("loaded", "loading"):
                        out[f"{mod}.gguf".lower()] = (f"está cargado ahora en «{name}» ({u.netloc}, router); "
                                                      "descárgalo antes (POST /models/unload)")
                continue
            if mp:
                out[Path(mp).name.lower()] = (f"está cargado ahora en «{name}» ({u.netloc}); "
                                              "apaga ese servidor o cambia de modelo primero")
        except Exception:
            pass
    return out


def lib_delete(cat_id):
    """Borra el .gguf + su mmproj (si nadie mas lo usa) + su entrada del
    manifiesto. Prohibido si esta cargado o configurado. (ok, texto)."""
    data = lib_load()
    e = next((x for x in data["modelos"] if x.get("id") == cat_id), None)
    if not e:
        return False, "no está en el manifiesto"
    loaded = lib_loaded()
    why = loaded.get(str(e.get("filename")).lower())
    if why:
        return False, f"No se puede borrar {e.get('name')}: {why}."
    gone = []
    for fn in [e.get("filename")] + ([e["mmproj"]["filename"]] if e.get("mmproj") else []):
        if fn and fn == (e.get("mmproj") or {}).get("filename") and any(
                (x.get("mmproj") or {}).get("filename") == fn for x in data["modelos"] if x is not e):
            continue  # el mmproj lo usa otro modelo
        p = MODELS_DIR / fn
        if p.is_file():
            p.unlink()
            gone.append(fn)
    data["modelos"] = [x for x in data["modelos"] if x is not e]
    lib_save(data)
    log(f"librero: borrado {e.get('name')}: {', '.join(gone) or 'sin archivos'} + entrada del manifiesto")
    return True, f"{e.get('name')} se borró ({', '.join(gone) or 'no quedaban archivos'})."


def lib_delete_bak(cat_id):
    data = lib_load()
    e = next((x for x in data["modelos"] if x.get("id") == cat_id), None)
    ant = (e or {}).get("anterior")
    if not ant:
        return False, "no hay versión anterior"
    _rm_quiet(MODELS_DIR / ant["filename"])
    e["anterior"] = None
    lib_save(data)
    log(f"librero: borrada la versión anterior de {e.get('name')} ({ant['filename']})")
    return True, "Versión anterior borrada."


def lib_note_started(gguf_path):
    """Lo llama el arranque de un motor con bloque 'servidor' cuando ya
    responde: si ese GGUF tenia una version anterior (.bak), ya se puede
    ofrecer borrarla (el nuevo arranco una vez)."""
    try:
        name = Path(gguf_path).name
        data = lib_load()
        for e in data["modelos"]:
            if e.get("filename") == name and e.get("anterior") and not e["anterior"].get("arranco_nuevo"):
                e["anterior"]["arranco_nuevo"] = True
                lib_save(data)
                log(f"librero: {name} arrancó bien; su versión anterior ya se puede borrar")
    except Exception:
        pass


def lib_scan():
    """Escaneo de arranque de models\\: todo .gguf sin entrada en el manifiesto
    sale «sin registrar» (con su modelo del catalogo si casa por nombre o por
    tamano) y todo .part con su .download.json sale «a medias». Ninguno de los
    dos cuenta como instalado."""
    data = lib_load()
    known = set()
    for e in data["modelos"]:
        known.add(str(e.get("filename")).lower())
        if e.get("mmproj"):
            known.add(str(e["mmproj"].get("filename")).lower())
        if e.get("anterior"):
            known.add(str(e["anterior"].get("filename")).lower())
    cats = [c for c in load_catalog() if isinstance(c.get("gguf"), dict)]
    sin, medias = [], []
    try:
        items = sorted(MODELS_DIR.iterdir()) if MODELS_DIR.is_dir() else []
    except OSError:
        items = []
    for p in items:
        if not p.is_file():
            continue
        low = p.name.lower()
        if low.endswith(".gguf") and low not in known:
            size = p.stat().st_size
            cat = next((c for c in cats if str(c["gguf"].get("archivo")).lower() == low), None) \
                or next((c for c in cats if c["gguf"].get("bytes") == size), None)
            sin.append({"file": p.name, "size": size, "cat": cat})
        elif low.endswith(".part"):
            meta = _read_meta(MODELS_DIR / (p.name[:-5] + ".download.json"))
            medias.append({"file": p.name, "size": p.stat().st_size, "meta": meta})
    _LIB["scan"] = {"sin": sin, "medias": medias, "t": time.time()}
    return _LIB["scan"]


def lib_register(fname, source, on_done=None):
    """Registra un .gguf que ya esta en models\\ (p. ej. el Hermes copiado de
    Ollama) SIN volver a bajarlo: sha256 del archivo contra el del catalogo; si
    coincide, entrada en el manifiesto. En un hilo; on_done(ok, texto)."""
    p = MODELS_DIR / fname
    if source not in LIB_SOURCES:
        source = "manual"

    def run():
        ok, msg = False, ""
        try:
            size = p.stat().st_size
            cat = next((c for c in load_catalog() if isinstance(c.get("gguf"), dict) and (
                str(c["gguf"].get("archivo")).lower() == fname.lower()
                or c["gguf"].get("bytes") == size)), None)
            if not cat:
                msg = (f"{fname} no está en la librería: no tengo su sha256 para comprobarlo, "
                       "así que no se registra.")
            elif lib_catalog_problem(cat) and "mmproj" not in str(lib_catalog_problem(cat)):
                msg = f"No se registra: {lib_catalog_problem(cat)}."
            else:
                ok_h, why = gguf_header(p)
                if not ok_h:
                    msg = f"{fname} no es un GGUF válido: {why}."
                else:
                    _LIB["hash"][fname] = 0.0
                    t0 = time.time()
                    got = sha256_file(p, lambda d, t: _LIB["hash"].__setitem__(fname, d / t))
                    g = cat["gguf"]
                    if got != g["sha256"]:
                        msg = (f"{fname}: su sha256 ({got[:12]}…) no es el de {cat['name']} en el "
                               f"catálogo ({g['sha256'][:12]}…). No se registra.")
                    else:
                        data = lib_load()
                        data["modelos"] = [e for e in data["modelos"] if e.get("id") != cat["id"]] + [{
                            "id": cat["id"], "name": cat.get("name"), "repo_id": g["repo"],
                            "revision": g["revision"], "filename": fname, "hf_filename": g["archivo"],
                            "size_bytes": size, "sha256": got,
                            "quant": g.get("quant") or lib_quant(g["archivo"]),
                            "role": cat.get("kind") or None, "ctx_default": cat.get("ctx_default"),
                            "mmproj": None, "installed_at": _now_iso(), "verified_at": _now_iso(),
                            "source": source, "anterior": None}]
                        lib_save(data)
                        ok = True
                        msg = (f"{fname} registrado como {cat['name']} (sha256 OK en "
                               f"{time.time() - t0:.0f} s, sin volver a bajarlo).")
        except Exception as e:
            msg = f"No se pudo registrar {fname} ({type(e).__name__}: {e})."
        _LIB["hash"].pop(fname, None)
        log(f"librero: {msg}")
        if on_done:
            on_done(ok, msg)

    threading.Thread(target=run, daemon=True, name="librero-registro").start()


