# ---- Estado: tarjetas de salud y de métrica (t-estado-tarjetas-045). Salud: una tarjeta por servicio (puente,
# runner, proxy) y por motor de engines.json, con punto + estado REAL (el del servicio, la fila del mapa o el
# último healthcheck de motores-salud.json); sin dato, «sin datos». Métricas: número grande + sparkline de los
# últimos 7 días, de los resultados reales (tareas terminadas, tiempo mediano, gasto real y equivalente Max, con
# day_by_model, la misma fuente que el consumo vivo). La gráfica es un Canvas (no se convierte: solo se dibuja).
# El banner de la nube y el mapa no se tocan. CustomTkinter con la versión clásica de respaldo.
_EST: dict = {"kit": None, "ctk": False, "salud": {}, "metricas": {}, "fp": None, "ms": None}
EST_DIAS = 7


def estado_salud_filas():
    """[(clave, nombre, color, texto)] de cada servicio y motor, con su estado real o «sin datos»."""
    out = []
    eu = estado_unico()  # t-estado-consistencia-045: lo mismo que la barra lateral y el botón
    br = eu["puente"] == "arriba"
    out.append(("puente", "Puente", "green" if br else "red" if eu["puente"] == "no_responde" else "muted",
                f"Encendido, puerto {BRIDGE_PORT}" if br else {"no_responde": "No responde",
                                                              "comprobando": "Comprobando…"}.get(eu["puente"],
                                                                                                 "Apagado")))
    rn = eu["runner"] == "arriba" and eu["nivel"] != "abajo"
    abajo = eu["nivel"] == "abajo"  # con el puente abajo ninguna tarjeta de servicio va en verde
    try:
        cola = cola_resumen().get("pendiente") or 0
    except Exception:
        cola = None
    out.append(("runner", "Runner", "green" if rn else "muted",
                ("No se puede comprobar: el puente está apagado" if abajo and eu["runner"] == "arriba" else
                 "Encendido" if rn else "Apagado") + (f", {cola} en cola" if cola is not None else "")))
    p = _AV["rows"].get("proxy") or {}
    if eu["proxy"] == "no_se_usa":
        out.append(("proxy", "Proxy", "muted", "No se usa (apagado o «Sin proxy»)"))
    elif not p:
        out.append(("proxy", "Proxy", "muted", "sin datos: todavía no se probó"))
    elif abajo:
        out.append(("proxy", "Proxy", "muted", "No se comprueba con el puente apagado (última prueba: "
                    + str(p.get("frase") or p.get("estado") or "sin datos") + ")"))
    else:
        # sin responder = aviso (#FA5102), lo mismo que su punto en Servicios y la pastilla «Parcial»
        col = {"ok": "green", "aviso": "orange", "falla": "orange"}.get(p.get("estado"), "muted")
        out.append(("proxy", "Proxy", col, str(p.get("frase") or p.get("estado") or "sin datos")
                    + (f" ({p['ms']} ms)" if p.get("ms") else "")))
    sal = _salud()
    for mid in engine_ids():
        if mid.startswith("_"):
            continue
        nombre = str((engine_raw(mid) or {}).get("nombre") or mid)
        rec = sal.get(mid) if isinstance(sal.get(mid), dict) else None
        if mid in motores_apagados():
            out.append((f"motor:{mid}", nombre, "muted", "Desactivado por ti"))
        elif rec is None:
            out.append((f"motor:{mid}", nombre, "muted", "sin datos: aún no se comprobó"))
        else:
            hora = str(rec.get("hora") or "")[11:16]
            if rec.get("disponible"):
                txt = "Disponible" + (f", {rec['version']}" if rec.get("version") else "")
                out.append((f"motor:{mid}", nombre, "green", txt + (f", comprobado {hora}" if hora else "")))
            else:
                out.append((f"motor:{mid}", nombre, "red", f"No disponible: {str(rec.get('motivo') or '')[:120]}"
                            + (f", {hora}" if hora else "")))
    return out


def estado_metricas(hoy=None):
    """Series de los últimos EST_DIAS días (de más viejo a hoy), de los resultados reales:
    {"dias": [...], "tareas": [n], "mediana_s": [s o None], "real": [$], "equiv": [$]}."""
    hoy = hoy or datetime.now().astimezone().date()
    dias = [(hoy - timedelta(days=i)).isoformat() for i in range(EST_DIAS - 1, -1, -1)]
    n = {d: 0 for d in dias}
    durs = {d: [] for d in dias}
    for f in RESULTS.glob("*.result.json"):
        try:
            r = json.loads(f.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(r, dict) or r.get("ollama_action"):
            continue
        d = str(r.get("finished_at") or "")[:10]
        if d in n:
            n[d] += 1
            if isinstance(r.get("duration_s"), (int, float)):
                durs[d].append(float(r["duration_s"]))
    real, equiv = [], []
    for d in dias:
        dm = day_by_model(d)
        real.append(round(sum(b["cost"] for k, b in dm.items() if k[0] == "real"), 4))
        equiv.append(round(sum(b["cost"] for k, b in dm.items() if k[0] == "equiv"), 4))

    def _mediana(xs):
        xs = sorted(xs)
        if not xs:
            return None
        m = len(xs) // 2
        return xs[m] if len(xs) % 2 else (xs[m - 1] + xs[m]) / 2
    return {"dias": dias, "tareas": [n[d] for d in dias], "mediana_s": [_mediana(durs[d]) for d in dias],
            "real": real, "equiv": equiv}


def _est_lbl(parent, text, color="text", bold=False, size=10, wrap=180):
    """Texto de las tarjetas: tk.Label con el fondo de la tarjeta (un CTkLabel por renglón alargaba el arranque
    ~2 s: Estado es la página que se ve al abrir). La tarjeta en sí sí es CTk (esquinas 10, borde de 1 px)."""
    return tk.Label(parent, text=text, bg=THEME["card"], fg=THEME.get(color, color), anchor="w", justify="left",
                    font=(FONT, size, "bold" if bold else "normal"), wraplength=S(wrap) if wrap else 0)


def _est_ajustar(card, *labels, margen=32):
    """El texto se parte al ancho real de su tarjeta (dos columnas a ventana mínima, también a 150 %)."""
    def _cfg(e):
        for lb in labels:
            try:
                lb.configure(wraplength=max(S(90), e.width - S(margen)))
            except tk.TclError:
                pass
    getattr(card, "_canvas", card).bind("<Configure>", _cfg, add=True)
    return _cfg


def _est_construir(tab):
    """El sitio de las tarjetas se reserva ya; se dibujan nada más abrir la ventana (como t-carga-300ms): Estado es
    la página que se ve al arrancar y dibujarlas dentro de build_gui lo alargaba."""
    holder = tk.Frame(tab, bg=THEME["bg"])
    holder.pack(fill="x")
    _EST["holder"] = holder
    tk.Label(holder, text="⠋ Cargando la salud y las métricas…", font=(FONT, 10), bg=THEME["bg"],
             fg=THEME["muted"]).pack(anchor="w", padx=22, pady=(10, 4))
    tab.after(600, lambda: _est_construir_ya(holder))


def _est_construir_ya(holder):
    for ch in holder.winfo_children():
        ch.destroy()
    t0 = time.perf_counter()
    if _ctk_wanted():
        try:
            _teclado_ctk_patch()
            k = _KitCtk(holder, global_setup=False)
            _est_con(k)
            _EST.update(kit=k, ctk=True)
            _est_pintar(forzar=True)
            _EST["ms"] = round((time.perf_counter() - t0) * 1000)
            log(f"estado: tarjetas con CustomTkinter ({_EST['ms']} ms)")
            return
        except Exception as e:
            log(f"estado: tarjetas sin CustomTkinter ({type(e).__name__}: {e}); se usan las clásicas")
            for ch in holder.winfo_children():
                try:
                    ch.destroy()
                except Exception:
                    pass
    k = _KitTk(holder)
    _est_con(k)
    _EST.update(kit=k, ctk=False)
    _est_pintar(forzar=True)
    _EST["ms"] = round((time.perf_counter() - t0) * 1000)
    log(f"estado: tarjetas clásicas (tkinter) ({_EST['ms']} ms)")


def _est_con(k):
    sec = k.section("Salud", "El estado real de cada servicio y motor: el del propio servicio, la última prueba "
                             "del proxy o el último healthcheck del motor. Sin dato, lo dice.")
    _EST["salud_box"] = k.frame(sec)
    _EST["salud_box"].pack(fill="x", padx=12, pady=(0, 12))
    sec2 = k.section("Métricas", f"Los últimos {EST_DIAS} días, de los resultados reales de la cola.")
    box = k.frame(sec2)
    box.pack(fill="x", padx=12, pady=(0, 12))
    box.grid_columnconfigure(0, weight=1, uniform="m")
    box.grid_columnconfigure(1, weight=1, uniform="m")
    _EST["metricas"] = {}
    for i, (key, titulo) in enumerate((("tareas", "Tareas terminadas hoy"), ("mediana_s", "Tiempo mediano hoy"),
                                       ("real", "Gasto real hoy"), ("equiv", "Equivalente Max hoy"))):
        c = k.card(box)
        c.grid(row=i // 2, column=i % 2, sticky="nsew", padx=4, pady=4)
        _est_lbl(c, titulo, color="muted", size=9, wrap=0).pack(anchor="w", padx=12, pady=(10, 0))
        num = _est_lbl(c, "…", bold=True, size=20, wrap=0)
        num.pack(anchor="w", fill="x", padx=12)
        sub = _est_lbl(c, "", color="muted", size=9)
        sub.pack(anchor="w", fill="x", padx=12)
        _EST.setdefault("ajustes", []).append(_est_ajustar(c, sub))
        cv = tk.Canvas(c, height=S(38), bg=THEME["card"], highlightthickness=0, bd=0)
        cv.pack(fill="x", padx=12, pady=(4, 10))
        cv.bind("<Configure>", lambda e, kk=key: _est_spark(kk, e.width), add=True)
        _EST["metricas"][key] = {"num": num, "sub": sub, "cv": cv, "serie": [], "ancho": S(200)}


def _est_spark(key, ancho=None):
    """La sparkline de una métrica: los 7 días reales, con el de hoy marcado. Sin ningún dato: «sin datos»."""
    m = _EST["metricas"].get(key)
    if not m:
        return
    cv = m["cv"]
    if ancho:
        m["ancho"] = ancho
    w, h, pad = max(m["ancho"], S(60)), S(38), S(4)
    cv.delete("all")
    serie = m["serie"]
    vals = [v for v in serie if v is not None]
    if not vals:
        cv.create_text(pad, h // 2, text="sin datos", anchor="w", fill=THEME["muted"], font=(FONT, 9))
        return
    hi = max(vals) or 1
    paso = (w - 2 * pad) / max(1, len(serie) - 1)
    pts = []
    for i, v in enumerate(serie):
        if v is None:
            continue
        pts.append((pad + i * paso, h - pad - (v / hi) * (h - 2 * pad)))
    col = THEME["blue"]
    if len(pts) >= 2:
        cv.create_line(*[c for p in pts for c in p], fill=col, width=max(1, S(2)), smooth=False)
    x, y = pts[-1]
    r = S(3)
    cv.create_oval(x - r, y - r, x + r, y + r, fill=col, outline=col)
    m["puntos"] = pts


def _est_pintar(forzar=False):
    k = _EST.get("kit")
    if k is None:
        return
    box = _EST["salud_box"]
    filas = estado_salud_filas()
    firma = tuple(filas)
    if forzar or firma != _EST.get("salud_firma"):
        _EST["salud_firma"] = firma
        for ch in box.winfo_children():
            ch.destroy()
        box.grid_columnconfigure(0, weight=1, uniform="s")
        box.grid_columnconfigure(1, weight=1, uniform="s")
        _EST["salud"] = {}
        for i, (key, nombre, col, txt) in enumerate(filas):
            c = k.card(box)
            c.grid(row=i // 2, column=i % 2, sticky="nsew", padx=4, pady=4)
            r = tk.Frame(c, bg=THEME["card"])
            r.pack(fill="x", padx=12, pady=(10, 0))
            punto = _est_lbl(r, "●", color=col, wrap=0)
            punto.pack(side="left")
            nom = _est_lbl(r, nombre, bold=True, wrap=0)
            nom.pack(side="left", padx=(6, 0))
            t = _est_lbl(c, txt, size=9, color="muted" if col == "muted" else
                         {"green": "green_text", "orange": "orange_text", "red": "red"}.get(col, "text"))
            t.pack(anchor="w", fill="x", padx=12, pady=(2, 10))
            _est_ajustar(c, t)
            _est_ajustar(c, nom, margen=56)  # el nombre va detrás del punto
            _EST["salud"][key] = {"nombre": nombre, "color": col, "texto": txt, "punto": punto, "label": t}
    try:
        files = list(RESULTS.glob("*.json"))
        fp = (len(files), max((f.stat().st_mtime for f in files), default=0),
              datetime.now().astimezone().date().isoformat())
    except OSError:
        fp = None
    if not forzar and fp == _EST.get("fp"):
        return
    _EST["fp"] = fp
    try:
        met = estado_metricas()
    except Exception as e:
        log(f"estado: no se pudieron leer las métricas ({type(e).__name__}: {e})")
        met = None
    _EST["datos"] = met
    M = _EST["metricas"]
    if met is None:
        for m in M.values():
            m["num"].config(text="sin datos")
            m["sub"].config(text="no se pudieron leer los resultados")
            m["serie"] = []
            _est_spark_todas()
        return
    hoy_med = met["mediana_s"][-1]
    textos = {
        "tareas": (str(met["tareas"][-1]), f"{sum(met['tareas'])} en {EST_DIAS} días"),
        "mediana_s": (_fmt_secs(hoy_med) if hoy_med is not None else "sin datos",
                      "por tarea terminada hoy" if hoy_med is not None else "hoy no terminó ninguna tarea"),
        "real": (f"${met['real'][-1]:.2f}", f"${sum(met['real']):.2f} en {EST_DIAS} días (dinero pagado)"),
        "equiv": (f"${met['equiv'][-1]:.2f}", f"${sum(met['equiv']):.2f} en {EST_DIAS} días (no es dinero real)"),
    }
    for key, m in M.items():
        num, sub = textos[key]
        m["num"].config(text=num)
        m["sub"].config(text=sub)
        m["serie"] = list(met[key])
        _est_spark(key)


def _est_spark_todas():
    for key in _EST["metricas"]:
        _est_spark(key)


def _ui_call(fn):
    """Pasa una funcion al hilo de la ventana (desde un hilo de fondo): va a
    una cola que _tick vacia cada segundo (tkinter no es seguro entre hilos)."""
    _UI_Q.put(fn)


def _drain_ui_queue():
    for _ in range(50):
        try:
            fn = _UI_Q.get_nowait()
        except queue.Empty:
            return
        try:
            fn()
        except Exception as e:
            log(f"ventana: error en una actualizacion ({type(e).__name__}: {e})")


def _write_model_task(action, model=None, timeout_min=None):
    """La ventana pide las acciones de modelos igual que el asistente: con
    un task en runner-tasks/ que el runner ejecuta."""
    TASKS.mkdir(parents=True, exist_ok=True)
    tid = f"app-{action}-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{secrets.token_hex(2)}"
    data = {"id": tid, "ollama_action": action}
    if model:
        data["model"] = model
    if timeout_min:
        data["timeout_min"] = timeout_min
    tmp = TASKS / f"{tid}.tmp"
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(tmp, TASKS / f"{tid}.task.json")
    _mdl["pending"][tid] = {"action": action, "model": model, "t0": time.time(),
                            "timeout": (timeout_min or 5) * 60}
    return tid


def request_models_list(force=False):
    """Pide la lista de modelos instalados (accion list del runner). Si el
    runner esta apagado, la lee directamente para que la ventana no quede
    vacia."""
    if _mdl["list_req"] and not force:
        return
    _mdl["last_list_ask"] = time.time()
    if state["runner"] == "corriendo":
        _mdl["list_req"] = _write_model_task("list")
        return
    _mdl["list_req"] = "directo"

    def _run():
        ok, out, err = run_model_action("list", timeout_s=60)
        _ui_call(lambda: _apply_models_list(ok, out, err))

    threading.Thread(target=_run, daemon=True).start()


def _mdl_esqueleto(box, texto=None):
    if not box.winfo_exists() or _mdl["installed"] is not None:
        return
    for ch in box.winfo_children():
        if getattr(ch, "_esqueleto", False) or getattr(ch, "_esq_txt", False):
            ch.destroy()
    if texto:
        lb = tk.Label(box, text=texto, font=(FONT, 9), bg=THEME["card"], fg=THEME["muted"])
        lb._esq_txt = True
        lb.pack(anchor="w", padx=16, pady=(6, 0))
    esqueleto(box, filas=3).pack(fill="x")


def _apply_models_list(ok, out, err):
    _mdl["list_req"] = None
    if _mdl.get("carga") is not None:
        _mdl["carga"].fin()
    if ok:
        _mdl["installed"] = parse_ollama_list(out)
        _mdl["list_err"] = ""
    else:
        _mdl["list_err"] = err or "no pude leer tus modelos"
        if _mdl["installed"] is None:
            _mdl["installed"] = []
    cnt = _widgets.get("nav_count_modelos")
    if cnt is not None:
        cnt.config(text=str(len(_mdl["installed"] or [])))
    _refresh_engine_widgets()
    _render_models()


def _humanize_pull_line(line):
    """'pulling 6a07…:  45% ▕██ ▏ 2.1 GB/4.7 GB' -> 'descargando 45 % (2.1 GB de 4.7 GB)'."""
    low = line.lower()
    pct = re.search(r"(\d{1,3})%", line)
    sizes = re.search(r"([\d.]+\s*[KMGT]?B)\s*/\s*([\d.]+\s*[KMGT]?B)", line)
    if pct:
        txt = f"descargando {pct.group(1)} %"
        return txt + (f" ({sizes.group(1)} de {sizes.group(2)})" if sizes else "")
    if "manifest" in low and "pulling" in low:
        return "preparando…"
    if "verifying" in low:
        return "comprobando la descarga…"
    if "writing" in low:
        return "guardando…"
    if "success" in low:
        return "listo"
    if "pulling" in low:
        return "descargando…"
    return line[:80]


def _set_models_progress(text, ok=None):
    lbl = _widgets.get("mdl_progress")
    if lbl is None:
        return
    color = "muted" if ok is None else ("green_text" if ok else "red")
    (_mdl.get("kit") or _KitTk(None)).set_label(lbl, text=text, color=color)


def _models_poll():
    """Cada segundo: progreso de lo que se esta instalando y resultados de
    las acciones de modelos que pidio la ventana."""
    _drain_ui_queue()
    try:
        _lib_ui_tick()  # progreso del librero (descargas y registros)
    except Exception as e:
        log(f"librero: error al pintar el progreso ({type(e).__name__}: {e})")
    for tid, info in list(_mdl["pending"].items()):
        job = MODEL_JOBS.get(tid)
        if info["action"] == "pull" and job and job.get("line"):
            _set_models_progress(
                f"Instalando {friendly_model_name(info['model'] or '')}: "
                f"{_humanize_pull_line(job['line'])}")
        rp = RESULTS / f"{tid}.result.json"
        if not rp.is_file():
            if time.time() - info["t0"] > info["timeout"] + 180:
                _mdl["pending"].pop(tid, None)
                if _mdl["list_req"] == tid:
                    _mdl["list_req"] = None
                _set_models_progress("El runner no respondió. ¿Está encendido en Estado?", False)
                _render_models()
            continue
        try:
            d = json.loads(rp.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue  # todavia se esta escribiendo
        _mdl["pending"].pop(tid, None)
        MODEL_JOBS.pop(tid, None)
        ok = d.get("status") == "ok"
        if info["action"] == "list":
            # Consulta interna de la ventana: no se guarda en el historial.
            _rm_quiet(rp)
            _rm_quiet(DONE / f"{tid}.task.json")
            _apply_models_list(ok, d.get("result", ""), d.get("error"))
            continue
        name = friendly_model_name(info["model"] or "")
        if info["action"] == "pull":
            msg = (f"Listo: {name} quedó instalado y comprobado." if ok
                   else f"No se pudo instalar {name}: {d.get('error')}")
        else:
            msg = (f"{name} se borró de tu PC." if ok
                   else f"No se pudo borrar {name}: {d.get('error')}")
        log(f"modelos: {msg}")
        _set_models_progress(msg, ok)
        request_models_list(force=True)
        _render_models()


def start_pc_check():
    """Boton Comprobar mi PC: detecta GPU, RAM, CPU, disco y Ollama en un
    hilo (la ventana no se congela) y recalcula el semaforo."""
    if _mdl["detecting"]:
        return
    _mdl["detecting"] = True
    log("modelos: comprobando tu PC (GPU, memoria, procesador, disco)")
    _render_models()

    def _run():
        try:
            specs = detect_pc_specs()
        except Exception as e:
            specs = None
            log(f"modelos: no se pudo comprobar el PC ({type(e).__name__}: {e})")

        def _done():
            _mdl["detecting"] = False
            if specs:
                _mdl["specs"] = specs
                _mdl["free_mib"] = (specs.get("gpu") or {}).get("vram_free_mib")
                log(f"modelos: tu PC: {pc_specs_summary(specs)}")
            _render_models()

        _ui_call(_done)

    threading.Thread(target=_run, daemon=True).start()


def _on_models_open():
    _mdl4_al_abrir()  # tarjetas de motor, habilidades y reglas: se dibujan al abrir (t-modelos-tarjetas-045)
    try:
        _cadena_render()
    except Exception as e:
        log(f"respaldo: {type(e).__name__}: {e}")
    """Al abrir la pestana: la primera vez comprueba el PC sola, y pide la
    lista de modelos si aun no la hay. Y el escaneo de arranque de models\\
    (lo que no esta en el manifiesto sale «sin registrar»)."""
    if _mdl["specs"] is None and not _mdl["detecting"] and not PC_SPECS_FILE.is_file():
        start_pc_check()
    try:
        scan = lib_scan()
        if scan["sin"] or scan["medias"]:
            log(f"librero: escaneo de models\\: {len(scan['sin'])} sin registrar "
                f"({', '.join(s['file'] for s in scan['sin']) or '-'}), "
                f"{len(scan['medias'])} a medias")
        _render_models()
        _lib_refresh_loaded()
    except Exception as e:
        log(f"librero: no pude escanear models\\ ({type(e).__name__}: {e})")
    if _mdl["installed"] is None and not _mdl["list_req"]:
        request_models_list()

    # «Cabe ahora mismo»: la VRAM libre de este momento (nvidia-smi), no la
    # de cuando se pulso Comprobar mi PC.
    def _free_now():
        g = _gpu_query()
        if g:
            def _apply():
                _mdl["free_mib"] = g.get("vram_free_mib")
                _render_models()
            _ui_call(_apply)

    threading.Thread(target=_free_now, daemon=True).start()


def _fit_dot(parent, color, bg):
    c = tk.Canvas(parent, width=S(14), height=S(14), bg=bg, highlightthickness=0, bd=0)
    c.create_oval(S(2), S(2), S(12), S(12), fill=FIT_COLORS[color], outline=FIT_COLORS[color])
    return c


def _clear(frame):
    for child in frame.winfo_children():
        child.destroy()


def _runner_needed():
    if state["runner"] == "corriendo":
        return True
    messagebox.showinfo("Modelos", "Enciende el runner (pestaña Estado) para instalar "
                        "o borrar modelos: la ventana se lo pide a él, igual que tu asistente.")
    return False


def _set_default_model(name):
    s = load_settings()
    s["ollama_model"] = name
    if str(s.get("default_engine") or "").startswith("ollama:"):
        s["default_engine"] = "ollama:" + name
    save_settings(s)
    log(f"modelos: {friendly_model_name(name)} es ahora el modelo de tu PC por defecto")
    _refresh_engine_widgets()
    _render_models()


def _remove_model_ui(name, size):
    if not _runner_needed():
        return
    if not messagebox.askyesno(
            "Borrar modelo",
            f"¿Borrar {friendly_model_name(name)} de tu PC?\n\nLibera {size} de disco. "
            "Puedes volver a instalarlo cuando quieras."):
        return
    tid = _write_model_task("rm", name, timeout_min=5)
    log(f"modelos: borrado de {name} pedido al runner ({tid})")
    _set_models_progress(f"Borrando {friendly_model_name(name)}…")
    _render_models()


def _install_model_ui(entry):
    """Antes de instalar: tamaño, VRAM libre de ahora (nvidia-smi) y
    confirmacion si va justo. Los rojos no llegan aqui (boton apagado)."""
    if not _runner_needed():
        return
    plan = model_vram_plan(entry, _mdl["specs"], _mdl.get("free_mib"))
    color = plan["color"]
    if color == "red":
        return
    need_gb = plan["need"]["total"] / 1024 if plan["need"] else entry["vram_gb"]
    ctx_txt = f" con {ctx_k(plan['ctx_anuncio'])} de contexto" if plan["need"] else ""
    _set_models_progress(f"Mirando la memoria libre para {entry['name']}…")

    def _check():
        free = gpu_free_vram_gb()
        _ui_call(lambda: _confirm(free))

    def _confirm(free):
        msg = (f"{entry['name']} ocupa {_gb(entry['size_gb'])} GB en tu disco y necesita "
               f"unos {_gb(need_gb)} GB de VRAM (memoria de video){ctx_txt} para funcionar.")
        if free is not None:
            msg += f"\n\nAhora mismo tienes {_gb(free)} GB de VRAM libre."
            if need_gb > free:
                msg += (" No cabe en la que está libre ahora (otras apps la están usando): "
                        "se instala igual, pero irá lento hasta que cierres algo.")
        if color == "orange":
            msg = "Este modelo va justo en tu PC, ¿seguro?\n\n" + msg
        elif color == "gray":
            msg += "\n\nAún no comprobé tu PC: pulsa Comprobar mi PC para saber si cabe."
        if not messagebox.askyesno("Instalar modelo", msg + "\n\n¿Instalar ahora?"):
            _set_models_progress("")
            return
        tid = _write_model_task("pull", entry["id"], timeout_min=MAX_TIMEOUT_MIN)
        log(f"modelos: instalación de {entry['id']} ({_gb(entry['size_gb'])} GB) "
            f"pedida al runner ({tid})")
        _set_models_progress(f"Instalando {entry['name']}: preparando…")
        _render_models()

    threading.Thread(target=_check, daemon=True).start()


def _render_models():
    """Redibuja el resumen del PC, la lista de instalados y la libreria con
    su semaforo."""
    w = _widgets
    if w.get("mdl_library_box") is None:
        return
    specs = _mdl["specs"]
    bg = THEME["card"]
    if _mdl["detecting"]:
        w["mdl_specs"].configure(text="Comprobando tu PC…")
    else:
        w["mdl_specs"].configure(text=pc_specs_summary(specs))
    detail = "Pulsa Comprobar mi PC: mira tu tarjeta de video, memoria y disco para decirte qué modelos caben."
    if specs:
        cpu = specs.get("cpu") or {}
        cores = f" ({cpu['cores']} núcleos)" if cpu.get("cores") else ""
        free = (specs.get("gpu") or {}).get("vram_free_gb")
        detail = (f"Procesador: {cpu.get('name') or 'desconocido'}{cores}. "
                  + (f"VRAM libre al comprobar: {_gb(free)} GB. " if free is not None else "")
                  + (f"RAM libre: {_gb(specs['ram_free_gb'])} GB. " if specs.get("ram_free_gb") else "")
                  + (f"Ollama {specs['ollama_version']}." if specs.get("ollama_version")
                     else "Ollama no está instalado (hace falta para los modelos de tu PC; es gratis).")
                  + f" Comprobado el {str(specs.get('detected_at', ''))[:16].replace('T', ' a las ')}.")
    w["mdl_specs_detail"].configure(text=detail)
    w["mdl_check_btn"].configure(state="disabled" if _mdl["detecting"] else "normal")

    catalog = load_catalog()
    installed = _mdl["installed"]
    default = default_ollama_model()
    pending = {(i["action"], i["model"]) for i in _mdl["pending"].values()}

    k = _mdl.get("kit") or _KitTk(None)
    free = _mdl.get("free_mib")
    box = w["mdl_installed_box"]
    _clear(box)
    # Primero lo del librero: solo GGUF con sha256 comprobado (manifiesto).
    lib = lib_installed()
    lib_ids = {e["id"] for e in lib}
    for e in lib:
        _lib_fila_instalado(k, box, e, catalog, specs, free)
    if installed is None and not lib:
        # Regla de los 300 ms: el esqueleto solo si la lista tarda; a 1 s, qué pasa.
        c = _mdl.get("carga")
        if c is None or c.hecha:
            _mdl["carga"] = Carga("lista de modelos", mostrar=lambda: _mdl_esqueleto(box),
                                  detalle=lambda t: _mdl_esqueleto(box, t), texto="Leyendo tus modelos (Ollama)…")
        elif c.patron != "nada":  # el repintado de cada segundo lo borro: se vuelve a poner
            _mdl_esqueleto(box, c.texto if c.patron == "carga+detalle" else None)
    elif not installed and lib:
        pass  # sin Ollama (o vacio): lo del librero ya esta arriba
    elif not installed and "no está instalado" in (_mdl["list_err"] or ""):
        k.label(box, "Todavía no tienes modelos comprobados en tu PC. Descarga uno de la "
                     "librería o registra uno de «Sin registrar».",
                muted=True).pack(anchor="w", padx=16, pady=6)
    elif not installed:
        k.label(box, (f"No pude leer tus modelos: {_mdl['list_err']}" if _mdl["list_err"]
                      else "Todavía no tienes modelos en tu PC. Elige uno de la librería."),
                muted=True).pack(anchor="w", padx=16, pady=6)
    for m in installed or []:
        cat = next((c for c in catalog if _same_model(c["id"], m["name"])), None)
        if cat:
            plan = model_vram_plan(cat, specs, free, installed=True)
        else:
            plan = {"color": "gray", "pasos": [], "ctx_pc": 0, "need": None, "aviso": "",
                    "reason": ("No está en la librería: sin datos de su arquitectura no sé "
                               "qué contexto le cabe")}
        right = _mdl_fila(k, box, plan, friendly_model_name(m["name"], catalog),
                          sub=f"{m['size']} en disco, instalado {m['modified']}".strip(", ")
                          + ", en Ollama (no en models\\)")
        if plan["color"] == "red":
            # Un modelo que no cabe no se ofrece como si cupiera: sin «Usar por defecto».
            k.label(right, "No cabe en tu tarjeta", bold=True, color="red", wrap=0).pack(
                side="left", padx=4)
        elif _same_model(m["name"], default):
            k.label(right, "Por defecto", bold=True, color="blue", wrap=0).pack(side="left", padx=4)
        else:
            k.button(right, "Usar por defecto",
                     lambda n=m["name"]: _set_default_model(n)).pack(side="left", padx=4)
        busy = ("rm", m["name"]) in pending
        b = k.button(right, "Borrando…" if busy else "Borrar",
                     lambda n=m["name"], s=m["size"]: _remove_model_ui(n, s))
        k.set_enabled(b, not busy)
        b.pack(side="left")

    box = w["mdl_library_box"]
    _clear(box)
    if not catalog:
        k.label(box, "No encuentro la librería (models-catalog.json junto al programa).",
                muted=True).pack(anchor="w", padx=16, pady=6)
    for c in catalog:
        is_inst = bool(installed) and any(_same_model(c["id"], m["name"]) for m in installed)
        plan = model_vram_plan(c, specs, free, installed=is_inst)
        need = plan.get("need")
        sub = (f"{_gb(c['size_gb'])} GB en disco, necesita ~{_gb(need['total'] / 1024)} GB de VRAM "
               f"con {ctx_k(plan['ctx_anuncio'])} ({_mdl_desglose(need)})" if need else
               f"{_gb(c['size_gb'])} GB en disco")
        right = _mdl_fila(k, box, plan, c["name"], desc=c["use"], sub=sub)
        if c.get("gguf") and not lib_catalog_problem(c):
            _lib_boton_libreria(k, right, c, plan, c["id"] in lib_ids)
            continue
        if is_inst:
            k.label(right, "Instalado", bold=True, color="green_text", wrap=0).pack(side="left", padx=4)
        elif plan["color"] == "red":
            # Rojo = sin boton de instalar; el motivo va en la fila en palabras normales.
            k.label(right, "No cabe", bold=True, color="red", wrap=0).pack(side="left", padx=4)
        elif ("pull", c["id"]) in pending:
            b = k.button(right, "Instalando…", None)
            k.set_enabled(b, False)
            b.pack(side="left")
        else:
            k.button(right, "Instalar", lambda e=c: _install_model_ui(e)).pack(side="left")
    _lib_render_scan(k)
    _lib_ui_tick(force=True)


# ---- librero en la pestana Modelos: progreso, a medias, sin registrar
def _lib_origen(src):
    return {"bridge-downloader": "bajado por el librero", "copia-ollama": "copiado de Ollama",
            "manual": "puesto a mano"}.get(src, src or "origen desconocido")


def _lib_fila_instalado(k, box, e, catalog, specs, free):
    cat = next((c for c in catalog if c["id"] == e.get("id")), None)
    if cat:
        plan = model_vram_plan(cat, specs, free, installed=True)
    else:
        plan = {"color": "gray", "pasos": [], "ctx_pc": 0, "need": None, "aviso": "",
                "reason": "No está en la librería: sin datos de su arquitectura no sé qué contexto le cabe"}
    vis = " + visión (mmproj)" if e.get("mmproj") else ""
    loaded = _LIB.get("loaded") or {}
    ant = e.get("anterior")
    sub = (f"{_gb(e['size_bytes'] / 1e9)} GB en disco{vis}, {e.get('filename')}, "
           f"{e.get('quant') or 'cuantización desconocida'}, revisión {str(e.get('revision'))[:8]}, "
           f"sha256 comprobado, {_lib_origen(e.get('source'))}"
           + (", cargado ahora" if "cargado" in (loaded.get(str(e.get("filename")).lower()) or "")
              else "")
           + (", guarda la versión anterior hasta que esta arranque una vez"
              if ant and not ant.get("arranco_nuevo") else ""))
    right = _mdl_fila(k, box, plan, e.get("name") or e.get("filename"), sub=sub)
    if ant and ant.get("arranco_nuevo"):
        k.button(right, "Borrar versión anterior",
                 lambda i=e["id"], a=ant: _lib_delete_bak_ui(i, a)).pack(side="left", padx=4)
    k.button(right, "Borrar", lambda x=e: _lib_delete_ui(x)).pack(side="left")


def _lib_boton_libreria(k, right, c, plan, instalado):
    j = _LIB["job"]
    activo = j and j["id"] == c["id"] and j["estado"] not in ("listo", "error", "cancelado")
    if instalado:
        k.label(right, "Instalado", bold=True, color="green_text", wrap=0).pack(side="left", padx=4)
    elif plan["color"] == "red":
        k.label(right, "No cabe", bold=True, color="red", wrap=0).pack(side="left", padx=4)
    elif activo:
        b = k.button(right, "Descargando…", None)
        k.set_enabled(b, False)
        b.pack(side="left")
    elif any(s["cat"] and s["cat"]["id"] == c["id"] for s in (_LIB.get("scan") or {}).get("sin", [])):
        # Ya esta en models\ sin registrar: se registra, no se vuelve a bajar.
        k.label(right, "Sin registrar", bold=True, color="orange_text",
                wrap=0).pack(side="left", padx=4)
    else:
        part = lib_partial(c)
        if part and part[1]:
            k.button(right, f"Reanudar ({100.0 * part[0] / part[1]:.0f} %)",
                     lambda e=c: _lib_download_ui(e)).pack(side="left")
        else:
            k.button(right, "Descargar", lambda e=c: _lib_download_ui(e)).pack(side="left")


def _lib_cat_for_meta(meta):
    for c in load_catalog():
        g = c.get("gguf") or {}
        names = [g.get("archivo")] + [((g.get("mmproj") or {}).get("archivo"))]
        if meta and meta.get("repo") == g.get("repo") and meta.get("archivo") in names:
            return c
    return None


def _lib_render_scan(k):
    """Lista del escaneo de arranque (sin registrar) y descargas a medias."""
    scan = _LIB.get("scan") or lib_scan()
    box = _widgets.get("lib_scan_box")
    if box is not None:
        _clear(box)
        _LIB["hash_lbl"] = {}
        if not scan["sin"]:
            k.label(box, "Nada sin registrar: todo lo que hay en models\\ está comprobado.",
                    muted=True).pack(anchor="w", padx=16, pady=6)
        for s in scan["sin"]:
            row = k.frame(box)
            row.pack(fill="x", padx=16, pady=6)
            right = k.frame(row)
            right.pack(side="right", anchor="n")
            mid = k.frame(row)
            mid.pack(side="left", fill="x", expand=True)
            k.label(mid, s["file"], bold=True, wrap=0).pack(anchor="w")
            cat = s["cat"]
            if cat and not lib_catalog_problem(cat):
                txt = (f"{_gb(s['size'] / 1e9)} GB, parece {cat['name']} (el catálogo tiene su "
                       f"sha256 y su revisión {cat['gguf']['revision'][:8]}). Sin registrar: no "
                       "cuenta como instalado.")
            else:
                txt = (f"{_gb(s['size'] / 1e9)} GB, no está en la librería: no tengo su sha256 "
                       "para comprobarlo, así que no se registra.")
            k.label(mid, txt, muted=True, wrap=520).pack(anchor="w")
            lbl = k.label(mid, "", muted=True, color="blue", wrap=520)
            lbl.pack(anchor="w")
            _LIB["hash_lbl"][s["file"]] = lbl
            if cat and not lib_catalog_problem(cat):
                busy = s["file"] in _LIB["hash"]
                b = k.button(right, "Comprobando…" if busy else "Registrar",
                             lambda x=s: _lib_register_ui(x), accent=True)
                k.set_enabled(b, not busy)
                b.pack(side="left")
            tk.Frame(box, bg=THEME["line"], height=S(1)).pack(fill="x", padx=16)
    box = _widgets.get("lib_partials_box")
    if box is not None:
        _clear(box)
        box.configure(height=1)  # vacio: un CTkFrame sin hijos se queda en 200 px
        j = _LIB["job"]
        activo = j and j["estado"] not in ("listo", "error", "cancelado")
        for s in scan["medias"]:
            cat = _lib_cat_for_meta(s["meta"])
            if activo and cat and j["id"] == cat["id"]:
                continue
            meta = s["meta"] or {}
            tot = meta.get("total") or 0
            got = min(int(meta.get("bytes") or 0), s["size"])
            row = k.frame(box)
            row.pack(fill="x", padx=16, pady=4)
            right = k.frame(row)
            right.pack(side="right")
            if meta.get("verificacion", "").startswith("sha256 no coincide"):
                txt = (f"{s['file']}: llegó dañado (sha256 no coincide); no se instaló. "
                       "«Descargar de nuevo» lo baja limpio.")
            elif not meta:
                txt = f"{s['file']}: archivo a medias sin su .download.json (no se puede reanudar)."
            else:
                txt = (f"A medias: {s['file']}: {_fmt_mb(got)} de {_fmt_mb(tot)} MB "
                       f"({100.0 * got / tot if tot else 0:.1f} %). No cuenta como instalado.")
            k.label(row, txt, muted=True, wrap=440).pack(side="left", anchor="w")
            if cat:
                k.button(right, "Descargar de nuevo" if "dañado" in txt else "Reanudar",
                         lambda c=cat, t=txt: _lib_download_ui(c, de_nuevo="dañado" in t),
                         accent=True).pack(side="left", padx=(6, 0))
                k.button(right, "Borrar lo bajado",
                         lambda c=cat: _lib_discard_ui(c)).pack(side="left", padx=(6, 0))


_LIB_ESTADOS = {"conectando": "Conectando", "descargando": "Descargando", "pausado": "En pausa",
                "reintentando": "Reintentando", "verificando": "Comprobando",
                "listo": "Listo", "error": "No se pudo", "cancelado": "Cancelada"}


def _lib_ui_tick(force=False):
    """Cada segundo (desde _models_poll): pinta el progreso de la descarga y
    la comprobacion de sha256 de un registro; redibuja si algo termino."""
    W = _widgets
    if W.get("lib_dl_title") is None:
        return
    k = _mdl.get("kit") or _KitTk(None)
    if _LIB.get("ver_ui") != _LIB["ver"] and not force:
        _LIB["ver_ui"] = _LIB["ver"]
        lib_scan()
        _render_models()
        return
    _LIB["ver_ui"] = _LIB["ver"]
    for fname, frac in list(_LIB["hash"].items()):
        lbl = (_LIB.get("hash_lbl") or {}).get(fname)
        if lbl is not None:
            k.set_label(lbl, text=f"Comprobando su sha256: {100.0 * frac:.0f} %")
    j = _LIB["job"]
    body = W["lib_dl_body"]
    if not j:
        if body.winfo_manager():
            body.pack_forget()
        return
    if not body.winfo_manager():
        body.pack(fill="x", before=W["lib_partials_box"])
    est = j["estado"]
    vivo = est not in ("listo", "error", "cancelado")
    k.set_label(W["lib_dl_title"], text=f"{_LIB_ESTADOS.get(est, est)}: {j['name']}",
                color="red" if est == "error" else "green_text" if est == "listo" else "text")
    k.set_progress(W["lib_dl_bar"], (j["bytes"] / j["total"]) if j["total"] else 0)
    line = lib_progress_text(j)
    if j.get("msg"):
        line = j["msg"] if est in ("listo", "error", "cancelado", "verificando") else f"{line}. {j['msg']}"
    k.set_label(W["lib_dl_line"], text=line, color="red" if est == "error" else "muted")
    ruta = f"Va {j['ruta']}." if j.get("ruta") else ""
    if j.get("aviso"):
        ruta = f"{ruta} {j['aviso']}".strip()
    k.set_label(W["lib_dl_route"], text=ruta,
                color="orange_text" if "proxy" in ruta or j.get("aviso") else "muted")
    k.set_enabled(W["lib_btn_pause"], vivo and est != "pausado" and est != "verificando")
    k.set_enabled(W["lib_btn_resume"], est == "pausado" or (j["pause"].is_set() and vivo))
    k.set_enabled(W["lib_btn_cancel"], vivo)
    k.set_enabled(W["lib_btn_cancel_rm"], vivo)


def _lib_download_ui(cat, de_nuevo=False):
    plan = model_vram_plan(cat, _mdl["specs"], _mdl.get("free_mib"))
    if plan["color"] == "red":
        return
    g = cat["gguf"]
    files = lib_files_for(cat)
    tot = sum(f["bytes"] for f in files)
    part = lib_partial(cat)
    if de_nuevo:
        if not messagebox.askyesno("Descargar de nuevo",
                                   f"Lo bajado de {cat['name']} llegó dañado. ¿Lo borro y lo bajo "
                                   "otra vez desde el principio?"):
            return
        lib_discard_partial(cat)
        part = None
    ok, disk = lib_disk_check(cat)
    if not ok:
        messagebox.showwarning("Sin sitio en el disco", disk)
        return
    hecho = (f"\n\nYa hay {_fmt_mb(part[0])} MB bajados: sigue desde ahí." if part else "")
    msg = (f"Bajar {cat['name']} de Hugging Face ({_gb(tot / 1e9)} GB"
           + (", con su parte de visión" if len(files) > 1 else "") + ").\n\n"
           f"Repositorio {g['repo']}, revisión {g['revision'][:8]} (fija). Se guarda en models\\ y "
           "solo se instala si su sha256 coincide con el del catálogo. Gratis." + hecho
           + "\n\n¿Empezar?")
    if not messagebox.askyesno("Descargar modelo", msg):
        return
    ok, txt = lib_start(cat)
    if not ok:
        messagebox.showwarning("Descargar modelo", txt)
    _render_models()


def _lib_pause_ui():
    lib_pause()
    _lib_ui_tick(force=True)


def _lib_resume_ui():
    j = _LIB["job"]
    if not lib_resume() and j and j["estado"] in ("error", "cancelado"):
        _lib_download_ui(j["cat"])
    _lib_ui_tick(force=True)


def _lib_cancel_ui(borrar):
    j = _LIB["job"]
    if not j:
        return
    if borrar and not messagebox.askyesno(
            "Cancelar y borrar", f"¿Cancelar la descarga de {j['name']} y borrar lo bajado "
            f"({_fmt_mb(j['bytes'])} MB)? Tendrías que empezar de cero."):
        return
    lib_cancel(borrar)
    _lib_ui_tick(force=True)


def _lib_discard_ui(cat):
    if messagebox.askyesno("Borrar lo bajado", f"¿Borrar lo bajado a medias de {cat['name']}? "
                           "Tendrías que empezar de cero."):
        lib_discard_partial(cat)
        lib_scan()
        _render_models()


def _lib_delete_ui(e):
    why = lib_loaded().get(str(e.get("filename")).lower())
    if why:
        messagebox.showwarning("Borrar modelo", f"No se puede borrar {e.get('name')}: {why}.")
        return
    gb_ = _gb(((e.get("size_bytes") or 0) + ((e.get("mmproj") or {}).get("size_bytes") or 0)) / 1e9)
    if not messagebox.askyesno(
            "Borrar modelo", f"¿Borrar {e.get('name')} de tu PC?\n\nSe borran {e.get('filename')}"
            + (" y su parte de visión" if e.get("mmproj") else "")
            + f" ({gb_} GB) y su entrada del manifiesto. Puedes volver a bajarlo cuando quieras."):
        return
    ok, txt = lib_delete(e["id"])
    _set_models_progress(txt, ok)
    if not ok:
        messagebox.showwarning("Borrar modelo", txt)
    lib_scan()
    _render_models()


def _lib_delete_bak_ui(cat_id, ant):
    if messagebox.askyesno("Borrar versión anterior",
                           f"La versión nueva ya arrancó bien. ¿Borrar la anterior "
                           f"({ant['filename']}, revisión {str(ant.get('revision'))[:8]})?"):
        ok, txt = lib_delete_bak(cat_id)
        _set_models_progress(txt, ok)
        lib_scan()
        _render_models()


def _lib_register_ui(s):
    cat = s["cat"]
    ans = messagebox.askyesnocancel(
        "Registrar modelo",
        f"Registrar {s['file']} como {cat['name']} sin volver a bajarlo: calculo su sha256 "
        f"({_gb(s['size'] / 1e9)} GB, tarda un poco) y lo comparo con el del catálogo.\n\n"
        "¿Lo copiaste de Ollama?\nSí = copiado de Ollama; No = lo pusiste a mano; Cancelar = no registrar")
    if ans is None:
        return
    src = "copia-ollama" if ans else "manual"

    def done(ok, msg):
        _ui_call(lambda: (_set_models_progress(msg, ok), lib_scan(), _render_models()))

    lib_register(s["file"], src, done)
    _render_models()


def _lib_refresh_loaded():
    """Que GGUF esta cargado ahora (GET /props a 127.0.0.1), en un hilo."""
    def run():
        try:
            d = lib_loaded()
        except Exception:
            d = {}

        def apply():
            if d != _LIB.get("loaded"):
                _LIB["loaded"] = d
                _render_models()
        _ui_call(apply)

    threading.Thread(target=run, daemon=True).start()


def _mdl_desglose(need):
    """'modelo 4.3 + contexto 1 + trabajo 0.1 GB' (+ visión si lleva mmproj)."""
    parts = [f"modelo {_gb(need['pesos'] / 1024)}", f"contexto {_gb(need['kv'] / 1024)}"
             + ("" if need["exacto"] else " aprox.")]
    if need["mmproj"]:
        parts.append(f"visión {_gb(need['mmproj'] / 1024)}")
    parts.append(f"trabajo {_gb(need['buffers'] / 1024)} GB")
    return " + ".join(parts)


def _mdl_lineas(plan):
    """Las lineas del semaforo: contexto que cabe por paso (4k / 8k / 16k),
    «cabe en tu PC» frente a «cabe ahora mismo», motivo y aviso."""
    out = []
    if plan.get("pasos"):
        chips = ", ".join(f"{ctx_k(p['ctx'])} {'✓' if p['color'] != 'red' else '✗'} "
                           f"{'~' if not p['exacto'] else ''}{round(p['pct'])} %"
                           for p in plan["pasos"])
        out.append((f"Contexto en tu tarjeta: {chips}", None))
        if plan["ctx_pc"]:
            t = f"Cabe en tu PC: hasta {ctx_k(plan['ctx_pc'])} de contexto."
            if plan.get("ctx_ahora") is not None:
                libre = _gb(plan["free_mib"] / 1024)
                t += (f" Ahora mismo, con {libre} GB libres: hasta {ctx_k(plan['ctx_ahora'])}."
                      if plan["ctx_ahora"] else f" Ahora mismo, con {libre} GB libres: no cabe.")
            out.append((t, None))
    out.append((plan["reason"], "red" if plan["color"] == "red" else None))
    if plan.get("aviso"):
        out.append((plan["aviso"], "orange_text"))
    return out


def _mdl_fila(k, box, plan, nombre, desc=None, sub=None):
    """Una fila de En tu PC / Librería con su punto de color (Canvas clasico)
    y sus lineas; devuelve el hueco de la derecha para los botones."""
    row = k.frame(box)
    row.pack(fill="x", padx=16, pady=6)
    _fit_dot(row, plan["color"], THEME["card"]).pack(side="left", padx=(0, 10), anchor="n", pady=4)
    right = k.frame(row)
    right.pack(side="right", anchor="n")
    mid = k.frame(row)
    mid.pack(side="left", fill="x", expand=True)
    k.label(mid, nombre, bold=True, wrap=0).pack(anchor="w")
    if desc:
        k.label(mid, desc, wrap=520).pack(anchor="w")
    if sub:
        k.label(mid, sub, muted=True, wrap=520).pack(anchor="w")
    for txt, color in _mdl_lineas(plan):
        k.label(mid, txt, muted=True, color=color, wrap=520).pack(anchor="w")
    tk.Frame(box, bg=THEME["line"], height=S(1)).pack(fill="x", padx=16)
    return right


def engine_choices():
    """(nombre normal, model del task, frase simple) de quien puede responder."""
    out = [(AUTO_LABEL, "motor:auto",
            "Automático: según lo que pidas, elige el más barato que lo hace bien (Hermes en tu "
            "PC para lo simple, Sonnet para código, Opus para lo grande). Siempre verás quién "
            "respondió y por qué."),
           ("Claude Sonnet", "sonnet", "Claude: el más listo, va por internet."),
           ("Claude Opus", "opus", "Claude Opus: el más potente, para trabajos grandes; va por internet."),
           ("Claude Haiku", "haiku", "Claude Haiku: el más rápido de Claude; va por internet.")]
    llama = get_engine("llama")
    if llama and _llama_installed(llama)[0]:
        out.append(("Local Hermes 3 directo $0", "motor:llama",
                    "Hermes 3 en tu PC, directo (llama.cpp): gratis, privado y rápido."))
    codex = get_engine("codex")
    if codex and _resolve_binary(codex):
        out.append(("Codex (por internet)", "motor:codex",
                    "Codex de OpenAI: otro agente que trabaja en tus carpetas; va por internet."))
    # Motores anadidos con «Nuevo motor» (en_selector), si estan disponibles.
    for mid in engine_ids():
        raw = engine_raw(mid) or {}
        if raw.get("en_selector") and all(m != f"motor:{mid}" for _l, m, _d in out):
            try:
                if engine_status(mid)[0]:
                    out.append((str(raw.get("nombre") or mid), f"motor:{mid}",
                                str(raw.get("frase_selector") or
                                    f"{raw.get('nombre') or mid}: motor añadido con «Nuevo motor».")))
            except Exception:
                pass
    catalog = load_catalog()
    default = default_ollama_model()
    names = [m["name"] for m in (_mdl["installed"] or [])]
    if _mdl["installed"] is None and default:
        names = [default]
    sal = _salud().get("ollama") or {}
    if sal and not sal.get("disponible") and time.time() - _iso_ts(sal.get("hora")) < 600:
        names = []  # el último healthcheck (< 10 min) dice que Ollama no responde: no se ofrece
    names.sort(key=lambda n: 0 if _same_model(n, default) else 1)
    labels = {o[0] for o in out}
    # Las filas de Ollama dicen que van por Ollama: «Local Hermes 3 directo»
    # (llama-server) es el mismo Hermes en otro programa y no deben confundirse.
    ofrase = str((engine_raw("ollama") or {}).get("frase_selector") or "")
    for n in names:
        fn = friendly_model_name(n, catalog)
        label = f"{fn}, Ollama (en tu PC) $0"
        if label in labels:
            label = f"{fn}, Ollama ({n})"
        labels.add(label)
        out.append((label, "ollama:" + n, ofrase if ofrase and _same_model(n, default)
                    else f"{fn} por Ollama: corre en tu PC, gratis y privado."))
    for p in API_ORDER:
        if api_key_for(p):
            lab = API_PROVIDERS[p]["label"]
            out.append((f"{lab} (por internet)", f"api:{p}:{api_model_for(p)}",
                        f"{lab}: otro modelo por internet, con tu clave."))
    off = motores_apagados()
    return [c for c in out if _motor_de_modelo(c[1]) not in off] if off else out


# ---- BYOS visible (t-byos-visible): las suscripciones como suscripciones.
# El estado se detecta EN VIVO (programa instalado, sesion, plan); sin sesion
# la fila dice «no detectada», nunca «conectada». Nunca se lee un token: de
# Claude solo el tipo de plan (_claude_plan) y si hay sesion OAuth; de Codex,
# lo que dice `codex login status`.
_SUSC = {"t": 0.0, "filas": None}
SECCIONES_SELECTOR = ("Automático", "Mi suscripción", "Mis claves", "Local", "Otros motores")
_SECCION_PREFIJO = "── "


def suscripciones_estado(fresca=False):
    if not fresca and _SUSC["filas"] is not None and time.time() - _SUSC["t"] < 300:
        return _SUSC["filas"]
    filas = []
    exe = shutil.which("claude")
    plan = _claude_plan()
    try:
        cred = json.loads((HOME_DIR / ".claude" / ".credentials.json").read_text(encoding="utf-8"))
        oauth = bool(cred.get("claudeAiOauth"))
    except (OSError, ValueError):
        oauth = False
    conectada = bool(exe) and oauth and plan in ("max", "pro")
    filas.append({
        "id": "claude", "servicio": "Claude " + ({"max": "Max", "pro": "Pro"}.get(plan or "", "Max")),
        "estado": "conectada" if conectada else "no detectada", "cli": exe, "sesion": oauth,
        "plan": plan or ("clave de API (no es suscripción)" if plan == "api" else None),
        "detalle": ("Claude Code con sesión " + plan.capitalize() + " (OAuth del propio programa)") if conectada else
                   ("Claude Code no está instalado" if not exe else
                    "hay clave de API (ANTHROPIC_API_KEY): eso no es la suscripción" if plan == "api" else
                    "Claude Code está, pero no hay sesión de suscripción iniciada"),
        "riesgo": "Usar la sesión Max por un proxy desde Venezuela puede hacer que Anthropic suspenda la cuenta. "
                  "Exporta tus conversaciones de vez en cuando: si la cuenta cae, es lo único que se salva."})
    eng = get_engine("codex") or {}
    base = _resolve_binary(eng) if eng else None
    txt, ok = "", False
    if base:
        try:
            r = subprocess.run(base + ["login", "status"], capture_output=True, timeout=30, stdin=subprocess.DEVNULL,
                               env=_ensure_no_proxy(dict(os.environ)), **_oculto())
            txt = _ANSI_RE.sub("", (r.stdout or b"").decode("utf-8", "replace") + (r.stderr or b"").decode("utf-8", "replace")).strip()
            ok = r.returncode == 0
        except (OSError, subprocess.TimeoutExpired) as e:
            txt = f"codex login status falló ({type(e).__name__})"
    chatgpt = ok and bool(re.search(r"chatgpt", txt, re.I))
    filas.append({
        "id": "codex", "servicio": "ChatGPT", "estado": "conectada" if chatgpt else "no detectada",
        "cli": " ".join(base) if base else None, "sesion": chatgpt,
        "plan": "sesión de ChatGPT" if chatgpt else ("clave de API de OpenAI (no es suscripción)"
                                                     if ok and re.search(r"api key", txt, re.I) else None),
        "detalle": ("Codex con " + txt.splitlines()[0][:80]) if ok and txt else
                   ("Codex no está instalado" if not base else f"sin sesión: {txt.splitlines()[0][:80] if txt else '—'}"),
        "riesgo": None})
    _SUSC.update(t=time.time(), filas=filas)
    log("suscripciones: " + "; ".join(f"{f['servicio']} {f['estado']} ({f['detalle']})" for f in filas))
    return filas


def _seccion_de(model, plan, codex_sesion):
    if model == "motor:auto":
        return "Automático"
    if model in ("sonnet", "opus", "haiku"):
        return "Mis claves" if plan == "api" else "Mi suscripción" if plan in ("max", "pro") else None
    if model == "motor:codex":
        return "Mi suscripción" if codex_sesion else "Mis claves"
    if model.startswith("api:"):
        return "Mis claves"
    if model == "motor:llama" or model.startswith("ollama:"):
        return "Local"
    return "Otros motores"


def engine_choices_secciones(choices=None):
    """[(seccion, [(label, model, frase)…])] solo con lo disponible de verdad:
    los Claude van en «Mi suscripción» si hay sesión Max/Pro, en «Mis claves»
    si hay clave de API, y no salen si no hay ninguna de las dos."""
    choices = engine_choices() if choices is None else choices
    plan = _claude_plan()
    codex = next((f for f in (_SUSC["filas"] or []) if f["id"] == "codex"), None)
    grupos = {s: [] for s in SECCIONES_SELECTOR}
    for c in choices:
        sec = _seccion_de(c[1], plan, bool(codex and codex["sesion"]))
        if sec:
            grupos[sec].append(c)
    return [(s, grupos[s]) for s in SECCIONES_SELECTOR if grupos[s]]


def _selector_valores(choices):
    """Valores del desplegable con cabeceras de sección (no elegibles)."""
    out = []
    for sec, items in engine_choices_secciones(choices):
        out.append(f"{_SECCION_PREFIJO}{sec} ──")
        out += [c[0] for c in items]
    return out


def _selector_saltar_cabecera(cb):
    """Si se elige una cabecera, pasa al primer modelo de debajo."""
    v = cb.get()
    if not v.startswith(_SECCION_PREFIJO):
        return
    vals = list(cb.cget("values"))
    i = vals.index(v) if v in vals else -1
    nxt = next((x for x in vals[i + 1:] if not x.startswith(_SECCION_PREFIJO)), None)
    if nxt:
        cb.set(nxt)
        cb.event_generate("<<ComboboxSelected>>")


def _default_engine_label(choices):
    s = load_settings()
    want = "motor:auto" if s.get("motor") == AUTO else str(s.get("default_engine") or "sonnet")
    chat = superficie_modelo("chat", avisar=False)  # el modelo del chat de Tareas, si lo elegiste
    if chat:
        want = chat
    return next((l for l, m, _d in choices if m == want), "Claude Sonnet")


def _refresh_engine_widgets():
    choices = engine_choices()
    _ASK_ENGINES.clear()
    _ASK_ENGINES.update({l: m for l, m, _d in choices})
    labels = [c[0] for c in choices]
    default_label = _default_engine_label(choices)
    valores = _selector_valores(choices)  # con cabeceras: Mi suscripción / Mis claves / Local
    for key in ("ask_engine", "mdl_engine"):
        cb = _widgets.get(key)
        if cb is None:
            continue
        cb.config(values=valores)
        if not getattr(cb, "_secciones", False):
            cb.bind("<<ComboboxSelected>>", lambda _e, c=cb: _selector_saltar_cabecera(c), add="+")
            cb._secciones = True
        if cb.get() not in labels or cb.get() not in valores:
            cb.set(default_label if default_label in valores else next(
                (v for v in valores if not v.startswith(_SECCION_PREFIJO)), default_label))
    _update_engine_desc()


def _update_engine_desc():
    cb = _widgets.get("mdl_engine")
    lbl = _widgets.get("mdl_engine_desc")
    if cb is None or lbl is None:
        return
    label = cb.get()
    choice = next((c for c in engine_choices() if c[0] == label), None)
    text = choice[2] if choice else ""
    if choice and _mdl["show_ids"]:
        text += f"\nNombre exacto: {choice[1]}"
    lbl.configure(text=text)
    _mdl4_motores_pintar()


def _on_engine_pick(_e=None):
    cb = _widgets.get("mdl_engine")
    label = cb.get() if cb is not None else ""
    model = _ASK_ENGINES.get(label)
    if not model:
        return
    s = load_settings()
    if model == "motor:auto":
        # El motor fijo de antes se queda en default_engine por si se vuelve a manual.
        s["motor"] = AUTO
    else:
        s.pop("motor", None)
        s["default_engine"] = model
    if model.startswith("ollama:"):
        s["ollama_model"] = model.split(":", 1)[1]
    save_settings(s)
    ask = _widgets.get("ask_engine")
    if ask is not None:
        ask.set(label)
    log(f"modelos: ahora responde {label}")
    _update_engine_desc()
    _render_models()


def _toggle_ability(key, name, on):
    s = load_settings()
    off = set(s.get("disabled_abilities") or [])
    if on:
        off.discard(key)
    else:
        off.add(key)
    s["disabled_abilities"] = sorted(off)
    save_settings(s)
    log(f"habilidades: '{name}' {'encendida' if on else 'apagada'}")


def _render_abilities():
    box = _widgets.get("mdl_abilities_box")
    if box is None or _mdl4_diferir("habilidades"):
        return
    _clear(box)
    k = getattr(box, "_kit", None) or _KitTk(box)
    filas = [(a["name"], a["desc"], a["on"], lambda on, ky=a["key"], n=a["name"]: _toggle_ability(ky, n, on))
             for a in list_abilities()]
    # herramientas de servidores MCP externos, cada una con su interruptor (t-mcp-streamable-http)
    filas += [(f"MCP, {cid}: {nombre}", desc[:110], on,
               lambda v, c=cid, n=nombre: mcp_herramienta_interruptor(c, n, v))
              for cid, nombre, desc, on in mcp_herramientas_conocidas()]
    for nombre, desc, on, cmd in filas:
        row = k.frame(box)
        row.pack(fill="x", padx=16, pady=5)
        _mdl4_interruptor(k, row, on, cmd).pack(side="right")
        left = k.frame(row)
        left.pack(side="left", fill="x", expand=True)
        k.label(left, nombre, bold=True, wrap=0).pack(anchor="w")
        k.label(left, desc, muted=True, wrap=480).pack(anchor="w", fill="x")
        tk.Frame(box, bg=THEME["line"], height=S(1)).pack(fill="x", padx=16)


def _refresh_channels():
    bg = THEME["card"]
    for key, _name, _desc in CHANNELS:
        dot = _widgets.get(f"chan_{key}_dot")
        txt = _widgets.get(f"chan_{key}_state")
        if dot is None or txt is None:
            continue
        if key == "mascota":
            on = bool(state.get("mascot"))
            msg = "Conectada" if on else "Apagada: enciéndela abajo en la barra lateral"
        else:
            on = state.get("bridge") == "corriendo"
            msg = "Conectado por el puente" if on else "Sin conexión: el puente está apagado"
        color = FIT_COLORS["green"] if on else FIT_COLORS["gray"]
        dot.delete("all")
        dot.create_oval(S(2), S(2), S(12), S(12), fill=color, outline=color)
        txt.config(text=msg, fg=THEME["green_text"] if on else THEME["muted"], bg=bg)


def _render_rules():
    box = _widgets.get("mdl_rules_box")
    if box is None or _mdl4_diferir("reglas"):
        return
    _clear(box)
    k = getattr(box, "_kit", None) or _KitTk(box)
    rules = load_rules()
    if not rules:
        k.label(box, "Sin reglas. Escribe una abajo.", muted=True).pack(anchor="w", padx=16, pady=6)
    for i, r in enumerate(rules):
        row = k.frame(box)
        row.pack(fill="x", padx=16, pady=5)
        _mdl4_interruptor(k, row, r["on"], lambda on, i=i: _toggle_rule(i, on)).pack(side="right")
        k.button(row, "Quitar", lambda i=i: _remove_rule(i)).pack(side="right", padx=8)
        k.label(row, r["text"], wrap=420).pack(side="left", fill="x", expand=True, anchor="w")
        tk.Frame(box, bg=THEME["line"], height=S(1)).pack(fill="x", padx=16)


def _toggle_rule(i, on):
    rules = load_rules()
    if 0 <= i < len(rules):
        rules[i]["on"] = on
        save_rules(rules)
        log(f"reglas: '{rules[i]['text']}' {'activada' if on else 'desactivada'}")


def _remove_rule(i):
    rules = load_rules()
    if 0 <= i < len(rules):
        gone = rules.pop(i)
        save_rules(rules)
        log(f"reglas: quitada '{gone['text']}'")
    _render_rules()


def _add_rule():
    ent = _widgets.get("mdl_rule_entry")
    if ent is None:
        return
    text = ent.get().strip()[:300]
    if not text:
        return
    rules = load_rules()
    rules.append({"text": text, "on": True})
    save_rules(rules)
    ent.delete(0, "end")
    log(f"reglas: añadida '{text}'")
    _render_rules()


def _wrap_al_ancho(lbl, cont, maximo, margen=0):
    """El texto corta al ancho real del contenedor (como mucho `maximo`): a ventana mínima no se sale."""
    def ajustar(e):
        try:
            lbl.config(wraplength=max(S(120), min(maximo, e.width - margen)))
        except tk.TclError:
            pass
    cont.bind("<Configure>", ajustar, add="+")


def _card(parent, title, expl=None):
    card = tk.Frame(parent, bg=THEME["card"], highlightthickness=1, highlightbackground=THEME["line"],
                    highlightcolor=THEME["line"])
    card.pack(fill="x", padx=20, pady=8)
    tk.Label(card, text=title, font=SECTION_FONT, bg=THEME["card"],
             fg=THEME["text"]).pack(anchor="w", padx=16, pady=(12, 2))
    if expl:
        lb = tk.Label(card, text=expl, font=(FONT, 9), bg=THEME["card"], fg=THEME["muted"],
                      wraplength=S(600), justify="left")
        lb.pack(anchor="w", padx=16, pady=(0, 6))
        _wrap_al_ancho(lb, card, S(600), margen=S(36))
    return card


# ---------------------------------------------------------------- Motores (ficha honesta + «Nuevo motor»)
# Superficie nueva de filas y controles: CustomTkinter con la version tkinter
# clasica de respaldo (la regla del piloto de Ajustes: sin customtkinter
# importable, CTk roto al dibujar, "piloto_ctk": false o GROWI_BRIDGE_CTK=0 ->
# clasica). Las dos versiones son el MISMO codigo: solo cambia el juego de
# piezas (_KitCtk / _KitTk). Colores de THEME; esquinas 10 en tarjetas y 8
# en botones.
_MOT = {"sel": None, "ids": {}, "busy": False, "kit": None, "ctk": False}
NUEVO_FORMATOS = (("texto_plano", "Texto normal"), ("json_final", "JSON al final"),
                  ("json_por_lineas", "JSON por líneas"))
_FICHA_COLOR = {"ok": "green_text", "mal": "red", "aviso": "orange_text"}


class _KitTk:
    nombre = "tkinter"

    def __init__(self, page):
        self.page = page

    def section(self, title, expl=None):
        return _card(self.page, title, expl)

    def frame(self, parent):
        return tk.Frame(parent, bg=THEME["card"])

    def card(self, parent):
        return tk.Frame(parent, bg=THEME["card"])

    def title(self, parent, text):
        return tk.Label(parent, text=text, bg=THEME["card"], fg=THEME["text"], justify="left",
                        anchor="w", font=(FONT, 12, "bold"))

    def row(self, card, pady=(0, 8)):
        r = self.frame(card)
        r.pack(fill="x", padx=16, pady=pady)
        return r

    def label(self, parent, text="", muted=False, bold=False, wrap=560, color=None):
        return tk.Label(parent, text=text, bg=THEME["card"], justify="left", anchor="w",
                        font=(FONT, 9 if muted else 10, "bold" if bold else "normal"),
                        fg=THEME.get(color, color) if color else THEME["muted"] if muted else THEME["text"],
                        wraplength=S(wrap) if wrap else 0)

    def set_label(self, lbl, text=None, color=None):
        kw = {}
        if text is not None:
            kw["text"] = text
        if color is not None:
            kw["fg"] = THEME.get(color, color)  # clave de THEME o color literal
        lbl.config(**kw)

    def button(self, parent, text, command, accent=False):
        return ttk.Button(parent, text=text, command=command,
                          style="Accent.TButton" if accent else "TButton")

    def set_enabled(self, w, on):
        w.config(state="normal" if on else "disabled")

    def entry(self, parent, width=40, secret=False):
        return ttk.Entry(parent, width=width, font=(FONT, 10), show="•" if secret else "")

    def option(self, parent, values, command=None, width=34, editable=False):
        cb = ttk.Combobox(parent, values=values, width=width, font=(FONT, 10),
                          state="normal" if editable else "readonly")
        if command:
            cb.bind("<<ComboboxSelected>>", lambda _e: command(cb.get()))
        return cb

    def set_values(self, cb, values):
        cb.config(values=values)

    def segmented(self, parent, options, command):
        f = self.frame(parent)
        f.var = tk.StringVar(value=options[0][0])
        for k, lab in options:
            tk.Radiobutton(f, text=lab, value=k, variable=f.var, bg=THEME["card"],
                           fg=THEME["text"], activebackground=THEME["card"], font=(FONT, 10),
                           selectcolor=THEME["field"],
                           command=lambda: command(f.var.get())).pack(side="left", padx=(0, 12))
        return f

    def seg_get(self, seg):
        return seg.var.get()

    def progress(self, parent):
        return ttk.Progressbar(parent, mode="determinate", maximum=1000)

    def set_progress(self, bar, frac):
        bar.config(value=max(0, min(1000, int(frac * 1000))))


class _KitCtk(_KitTk):
    nombre = "CustomTkinter"
    # Colores fijos (minusculas) del tema actual, temas\*.json -> «fijos»: el
    # filtro de Tk no los cambia; se leen cada vez para que lo que se cree
    # despues de un cambio de tema en caliente salga ya con el tema nuevo.
    seg_bg = property(lambda self: _tema_fijo("seg_bg"))
    seg_sel = property(lambda self: _tema_fijo("seg_sel"))
    seg_hover = property(lambda self: _tema_fijo("seg_hover"))
    accent = property(lambda self: _tema_fijo("accent"))
    accent_hover = property(lambda self: _tema_fijo("accent_hover"))

    def __init__(self, page, global_setup=True):
        import customtkinter as ctk
        super().__init__(page)
        self.ctk = ctk
        dark = _THEME_STATE["dark"]
        # El mismo DPI y tema que ya decidio la app (como en el piloto). Una
        # superficie que se abre despues (el popup del guardrail) no lo vuelve
        # a aplicar: CTk re-escalaria todos sus widgets de la app cada vez.
        if global_setup:
            ctk.deactivate_automatic_dpi_awareness()
            ctk.set_widget_scaling(SCALE)
            ctk.set_appearance_mode("dark" if dark else "light")
        # Fijos en minusculas: propiedades que leen el tema actual (arriba).

    def F(self, px, w=None):
        if w == "semibold":
            return self.ctk.CTkFont(family="Segoe UI Semibold", size=px)
        return self.ctk.CTkFont(family=FONT, size=px, weight=w or "normal")

    def section(self, title, expl=None):
        ctk = self.ctk
        ctk.CTkLabel(self.page, text=title, font=self.F(15, "semibold"), text_color=THEME["muted"],
                     anchor="w", height=1).pack(anchor="w", padx=22, pady=(14, 6))
        card = ctk.CTkFrame(self.page, fg_color=THEME["card"], corner_radius=10, border_width=1,
                            border_color=THEME["line"])
        card.pack(fill="x", padx=20, pady=(0, 6))
        if expl:
            lbl = self.label(card, expl, muted=True)
            lbl.pack(anchor="w", fill="x", padx=16, pady=(12, 4))
        return card

    def frame(self, parent):
        return self.ctk.CTkFrame(parent, fg_color="transparent")

    def card(self, parent):
        return self.ctk.CTkFrame(parent, fg_color=THEME["card"], corner_radius=10, border_width=1,
                                 border_color=THEME["line"])

    def title(self, parent, text):
        return self.ctk.CTkLabel(parent, text=text, anchor="w", justify="left", height=1,
                                 font=self.F(17, "semibold"), text_color=THEME["text"])

    def label(self, parent, text="", muted=False, bold=False, wrap=560, color=None):
        return self.ctk.CTkLabel(parent, text=text, anchor="w", justify="left",
                                 font=self.F(13, "semibold" if bold else None) if not muted else self.F(13),
                                 text_color=THEME.get(color, color) if color else THEME["muted"] if muted else THEME["text"],
                                 wraplength=wrap or 0, height=1)  # CTk ya escala (SCALE)

    def set_label(self, lbl, text=None, color=None):
        kw = {}
        if text is not None:
            kw["text"] = text
        if color is not None:
            kw["text_color"] = THEME.get(color, color)
        lbl.configure(**kw)

    def button(self, parent, text, command, accent=False):
        return self.ctk.CTkButton(
            parent, text=text, command=command, font=self.F(14, "semibold") if accent else self.F(13),
            corner_radius=8, height=32, width=0, border_spacing=10,
            fg_color=self.accent if accent else self.seg_bg,
            hover_color=self.accent_hover if accent else self.seg_hover,
            text_color=_tema_fijo("on_accent") if accent else THEME["text"],
            text_color_disabled=THEME["muted"])

    def set_enabled(self, w, on):
        w.configure(state="normal" if on else "disabled")

    def entry(self, parent, width=40, secret=False):
        return self.ctk.CTkEntry(parent, width=width * 8, height=30, corner_radius=8,
                                 font=self.F(13), border_width=1, border_color=THEME["line"],
                                 fg_color=THEME["field"], text_color=THEME["text"],
                                 **({"show": "•"} if secret else {}))

    def option(self, parent, values, command=None, width=34, editable=False):
        ctk = self.ctk
        kw = dict(values=values or [""], width=width * 8, height=30, corner_radius=8,
                  font=self.F(13), dropdown_font=self.F(13), text_color=THEME["text"],
                  command=command)
        if editable:
            return ctk.CTkComboBox(parent, border_width=1, border_color=THEME["line"],
                                   fg_color=THEME["field"], button_color=self.seg_bg,
                                   button_hover_color=self.seg_hover, **kw)
        return ctk.CTkOptionMenu(parent, fg_color=self.seg_bg, button_color=self.seg_bg,
                                 button_hover_color=self.seg_hover, **kw)

    def set_values(self, cb, values):
        cb.configure(values=values or [""])

    def segmented(self, parent, options, command):
        keys = {lab: k for k, lab in options}
        seg = self.ctk.CTkSegmentedButton(
            parent, values=[lab for _k, lab in options], font=self.F(13), height=30, corner_radius=8,
            border_width=2, fg_color=self.seg_bg, selected_color=self.seg_sel,
            selected_hover_color=self.seg_sel, unselected_color=self.seg_bg,
            unselected_hover_color=self.seg_hover, text_color=THEME["text"],
            command=lambda lab: command(keys[lab]))
        seg.set(options[0][1])
        seg._keys = keys
        return seg

    def seg_get(self, seg):
        return seg._keys.get(seg.get(), "texto_plano")

    def progress(self, parent):
        bar = self.ctk.CTkProgressBar(parent, height=10, corner_radius=8, fg_color=self.seg_bg,
                                      progress_color=self.accent)
        bar.set(0)
        return bar

    def set_progress(self, bar, frac):
        bar.set(max(0.0, min(1.0, frac)))


# ---------------------------------------------------------------- Skills de Bridge (pagina Skills)
# Superficie nueva (t-skills-nativas): una fila por skill con su version, su
# origen, su descripcion y sus requisitos comprobados EN VIVO (programas en el
# PATH, variables de entorno), mas «Validar skills» y los borradores del
# workshop. CustomTkinter con la version clasica de respaldo (el mismo codigo,
# kit _KitCtk / _KitTk, como Motores). Matriz de estados: carga, vacio,
# error, contenido y sin conexion (la carpeta skills\ no esta o no se abre).
_SKV = {"kit": None, "ctk": False, "reqs": {}, "busy": False, "valid": None, "t": None}


def _build_skills_bridge(tab):
    holder = tk.Frame(tab, bg=THEME["bg"])
    holder.pack(fill="x")
    t0 = time.perf_counter()
    if _ctk_wanted():
        try:
            kit = _KitCtk(holder, global_setup=not (_MOT.get("ctk") or _widgets.get("ajustes_ctk")))
            _build_skills_bridge_con(kit)
            _SKV.update(kit=kit, ctk=True)
            _SKV["ms"] = round((time.perf_counter() - t0) * 1000)
            log(f"skills: sección de Bridge con CustomTkinter {kit.ctk.__version__} ({_SKV['ms']} ms)")
            return
        except Exception as e:
            log(f"skills: CustomTkinter no disponible ({type(e).__name__}: {e}); se usa la versión clásica")
            for ch in holder.winfo_children():
                try:
                    ch.destroy()
                except Exception:
                    pass
    kit = _KitTk(holder)
    _build_skills_bridge_con(kit)
    _SKV.update(kit=kit, ctk=False)
    _SKV["ms"] = round((time.perf_counter() - t0) * 1000)
    log(f"skills: sección de Bridge clásica (tkinter) ({_SKV['ms']} ms)")


def _build_skills_bridge_con(k):
    W = _widgets
    card = k.section("Skills de Bridge",
                     "Guías propias que el runner le pasa al motor solo cuando la tarea las pide (las elige por "
                     f"su descripción, máximo {SKILL_MAX_ACTIVAS}). Viven en {SKILLS_DIR}; nada se descarga de "
                     "internet y nada se instala solo.")
    r = k.row(card, pady=(4, 6))
    W["skb_validar"] = k.button(r, "Validar skills", _skb_validar_ui, accent=True)
    W["skb_validar"].pack(side="left")
    W["skb_releer"] = k.button(r, "Volver a leer", lambda: _skb_refrescar(reindexar=True))
    W["skb_releer"].pack(side="left", padx=(10, 0))
    W["skb_abrir"] = k.button(r, "Abrir la carpeta", _skb_abrir)
    W["skb_abrir"].pack(side="left", padx=(10, 0))
    W["skb_estado"] = k.label(card, "Leyendo la carpeta de skills…", color="blue", wrap=600)
    W["skb_estado"].pack(anchor="w", fill="x", padx=16, pady=(0, 6))
    W["skb_valid"] = k.frame(card)
    W["skb_valid"].pack(fill="x", padx=16)
    W["skb_lista"] = k.frame(card)
    W["skb_lista"].pack(fill="x", padx=16, pady=(0, 12))
    card2 = k.section("Borradores",
                      "Lo que el runner propone cuando a una tarea le faltó una skill. Un borrador no se carga "
                      "ni se activa: lo editas y, si te sirve, lo apruebas tú.")
    W["skb_borr"] = k.frame(card2)
    W["skb_borr"].pack(fill="x", padx=16, pady=(0, 12))
    W["skb_borr_card"] = card2
    for f in (W["skb_valid"], W["skb_lista"], W["skb_borr"]):
        try:
            f.configure(height=1)  # vacio no ocupa (un CTkFrame vacio mide 200 px)
        except Exception:
            pass


def _skb_sep(parent):
    tk.Frame(parent, bg=THEME["line"], height=1).pack(fill="x", pady=(6, 6))


def _skb_refrescar(reindexar=False):
    """Comprueba los requisitos en vivo en un hilo y repinta (nunca congela)."""
    if _SKV.get("busy"):
        return
    _SKV["busy"] = True
    k, W = _SKV.get("kit"), _widgets
    if reindexar:
        _SKV["valid"] = None  # el informe de «Validar skills» ya no vale para lo que se va a leer
    if k is not None and W.get("skb_estado") is not None and (reindexar or _SKX["at"] is None):
        k.set_label(W["skb_estado"], "Leyendo la carpeta de skills…", color="blue")

    def _hilo():
        try:
            if reindexar or _SKX["at"] is None:
                skills_indexar("botón Volver a leer" if reindexar else "primer uso")
            _SKV["reqs"] = {x["carpeta"]: skill_requisitos(x) for x in _SKX["skills"]}
            _SKV["t"] = datetime.now().strftime("%H:%M:%S")
        except Exception as e:
            _SKX.update(estado="error", error=f"{type(e).__name__}: {e}")
        finally:
            _SKV["busy"] = False
            _ui_call(_skb_render)

    threading.Thread(target=_hilo, daemon=True).start()


def _skb_render():
    k, W = _SKV.get("kit"), _widgets
    if k is None or W.get("skb_lista") is None:
        return
    lista = W["skb_lista"]
    for ch in lista.winfo_children():
        ch.destroy()
    if _SKV.get("valid") is None:
        for ch in W["skb_valid"].winfo_children():
            ch.destroy()
    est = _SKX["estado"]
    if est == "carga" or _SKX["at"] is None:
        k.set_label(W["skb_estado"], "", color="blue")  # nada en los primeros 300 ms
        c = _SKV.get("carga")
        if c is None or c.hecha:
            _SKV["carga"] = Carga("lista de skills", mostrar=lambda: lista.winfo_exists() and esqueleto(
                lista, filas=4).pack(fill="x"), detalle=lambda t: k.set_label(W["skb_estado"], t, color="blue"),
                texto="Leyendo la carpeta de skills…")
        elif c.patron != "nada":  # el repintado lo borro: se vuelve a poner
            esqueleto(lista, filas=4).pack(fill="x")
            if c.patron == "carga+detalle":
                k.set_label(W["skb_estado"], c.texto, color="blue")
    elif _SKV.get("carga") is not None:
        _SKV["carga"].fin()
    if est == "carga" or _SKX["at"] is None:
        pass
    elif est == "sin_carpeta":
        k.set_label(W["skb_estado"], f"Sin conexión con la carpeta de skills: {SKILLS_DIR} no existe o no se "
                                     "puede abrir. Créala (o vuelve a conectar el disco) y pulsa «Volver a leer».",
                    color="red")
    elif est == "error":
        k.set_label(W["skb_estado"], f"No se pudieron leer las skills: {_SKX.get('error')}. "
                                     "Pulsa «Volver a leer» para reintentar.", color="red")
    elif est == "vacio":
        k.set_label(W["skb_estado"], f"La carpeta está, pero no hay ninguna skill. Crea una carpeta con su "
                                     f"SKILL.md dentro de {SKILLS_DIR}.", color="orange_text")
    else:
        n_ok, n_mal = len(_SKX["skills"]), len(_SKX["rechazadas"])
        k.set_label(W["skb_estado"], f"{n_ok} skill(s) cargada(s)"
                    + (f", {n_mal} no se cargaron (abajo, con el motivo)" if n_mal else "")
                    + f". Leído a las {(_SKX['at'] or '')[11:19]}; requisitos comprobados en vivo a las "
                      f"{_SKV.get('t') or '—'}.", color="muted")
    for sk in _SKX["skills"]:
        fila = k.frame(lista)
        fila.pack(fill="x")
        _skb_sep(fila)
        cab = k.frame(fila)
        cab.pack(fill="x")
        k.label(cab, sk["name"], bold=True, wrap=0).pack(side="left")
        k.label(cab, f"versión {sk['version']}, {sk['origen_txt']}", muted=True, wrap=0).pack(
            side="left", padx=(10, 0))
        k.label(fila, sk["description"], wrap=600).pack(anchor="w", fill="x", pady=(2, 2))
        reqs = _SKV["reqs"].get(sk["carpeta"])
        if reqs is None:
            k.label(fila, "Requisitos: comprobando…", muted=True).pack(anchor="w")
        elif not reqs:
            k.label(fila, "Requisitos: ninguno, lista para usarse", color="green_text").pack(anchor="w")
        else:
            falt = sum(1 for x in reqs if not x["ok"])
            k.label(fila, "Requisitos: todos cumplidos" if not falt else
                    f"Requisitos: falta(n) {falt} de {len(reqs)}",
                    color="green_text" if not falt else "red", bold=True).pack(anchor="w")
            for x in reqs:
                que = ("Programa" if x["tipo"] == "programa" else "Variable") + f" «{x['nombre']}»"
                if x.get("principal"):
                    que += " (credencial principal)"
                k.label(fila, f"{que}: {x['detalle']}", color="green_text" if x["ok"] else "red",
                        wrap=600).pack(anchor="w", padx=(12, 0))
        for a in sk.get("avisos") or []:
            k.label(fila, f"Aviso: {a}", color="orange_text", wrap=600).pack(anchor="w")
    if _SKX["rechazadas"]:
        f = k.frame(lista)
        f.pack(fill="x")
        _skb_sep(f)
        k.label(f, f"No se cargaron ({len(_SKX['rechazadas'])})", bold=True).pack(anchor="w")
        for x in _SKX["rechazadas"]:
            fila = k.frame(lista)
            fila.pack(fill="x", pady=(4, 0))
            est_txt = {"sospechosa": "sospechosa", "tapada": "tapada", "ruta": "ruta no válida"}.get(
                x.get("estado"), "no válida")
            k.label(fila, f"skills\\{x.get('rel')}  ({est_txt})", bold=True, wrap=600).pack(anchor="w")
            k.label(fila, "No se carga: " + "; ".join(x.get("motivos") or []), color="red", wrap=600).pack(
                anchor="w", padx=(12, 0))
            for s in (x.get("secretos") or [])[:3]:
                k.label(fila, f"Evidencia (redactada): {s['archivo']}, línea {s['linea']}: {s['evidencia']}",
                        muted=True, wrap=600).pack(anchor="w", padx=(12, 0))
    for a in _SKX.get("avisos") or []:
        k.label(lista, f"Aviso: {a}", color="orange_text", wrap=600).pack(anchor="w")
    _skb_render_borradores()


def _skb_render_borradores():
    k, W = _SKV.get("kit"), _widgets
    box = W.get("skb_borr")
    if k is None or box is None:
        return
    for ch in box.winfo_children():
        ch.destroy()
    pend = [b for b in _SKX.get("borradores") or []
            if (b.get("meta_borrador") or {}).get("estado", "pendiente") == "pendiente"]
    aprob = len(_SKX.get("borradores") or []) - len(pend)
    if not pend:
        k.label(box, "Ningún borrador esperando." + (f" {aprob} ya aprobado(s)." if aprob else ""),
                muted=True).pack(anchor="w", pady=(4, 0))
        return
    for b in pend:
        mb = b.get("meta_borrador") or {}
        fila = k.frame(box)
        fila.pack(fill="x")
        _skb_sep(fila)
        k.label(fila, f"{b['name']}  (borrador, no activo)", bold=True, wrap=600).pack(anchor="w")
        k.label(fila, b.get("description") or "(sin descripción)", wrap=600).pack(anchor="w", pady=(2, 0))
        k.label(fila, f"Lo propuso el runner el {str(mb.get('creado') or '')[:16].replace('T', ' ')}"
                + (f" en la tarea {mb['tarea']}" if mb.get("tarea") else "") + f". Carpeta: {b['carpeta']}",
                muted=True, wrap=600).pack(anchor="w")
        if b["estado"] != "ok":
            k.label(fila, "Todavía no pasa la validación: " + "; ".join(b["motivos"]), color="red",
                    wrap=600).pack(anchor="w")
        br = k.frame(fila)
        br.pack(anchor="w", pady=(4, 0))
        k.button(br, "Editar", lambda c=b["carpeta"]: _skb_editar(c)).pack(side="left")
        k.button(br, "Aprobar", lambda c=b["carpeta"], n=b["name"]: _skb_aprobar(c, n)).pack(
            side="left", padx=(10, 0))
    if aprob:
        k.label(box, f"{aprob} borrador(es) ya aprobado(s).", muted=True).pack(anchor="w", pady=(6, 0))


def _skb_validar_ui():
    k, W = _SKV.get("kit"), _widgets
