def atajo_registrar_accion(aid, nombre, fn, expl="", ambitos=("paleta", "global"),
                           defecto=None, grupo="bridge"):
    """Da de alta una accion con atajo. fn() se llama en el hilo de la ventana
    (o fn(ambito) si acepta un argumento). Para los comandos guardados:
    aid = "comando:<id>", grupo = "comando"; saldran en las dos listas."""
    try:
        import inspect
        con_ambito = len(inspect.signature(fn).parameters) >= 1
    except (TypeError, ValueError):
        con_ambito = False
    ATAJO_ACCIONES[aid] = {"nombre": nombre, "expl": expl, "fn": fn, "ambitos": tuple(ambitos),
                           "defecto": dict(defecto or {}), "grupo": grupo, "con_ambito": con_ambito}
    if _ATAJOS["listas"]:
        _ui_call(lambda: (atajos_desde_settings(), _atajos_filas_todas()))


def atajo_quitar_accion(aid):
    """Baja de una accion (p. ej. comando borrado): suelta sus atajos sin tocar
    settings.json."""
    for amb in ("paleta", "global"):
        if atajo_actual(aid, amb):
            _atajo_aplicar(aid, amb, "")
        _ATAJOS["error"].pop((aid, amb), None)
    ATAJO_ACCIONES.pop(aid, None)
    if _ATAJOS["listas"]:
        _ui_call(_atajos_filas_todas)


