def _atajo_texto(mods, key):
    return " + ".join([m for m in ATAJO_MODS if m in mods] + [key])


def _atajo_compacto(canon):
    """«Ctrl + K» -> «Ctrl+K» (chips de la paleta y de la barra lateral)."""
    return (canon or "").replace(" + ", "+")


def _atajo_leer(texto):
    """«ctrl+alt+t», «Ctrl + Alt + T», «Control+Mayus+Alt+F9»... ->
    (mods, tecla). ValueError con el motivo en palabras normales."""
    partes = [p.strip() for p in str(texto or "").replace("＋", "+").split("+")]
    if "" in partes and str(texto).strip().endswith("+"):
        partes = [p for p in partes if p] + ["+"]
    partes = [p for p in partes if p]
    if not partes:
        raise ValueError("está vacío.")
    mods, key = set(), None
    for p in partes:
        n = _norm(p).replace(" ", "")
        if n in _ATAJO_ALIAS_MOD:
            mods.add(_ATAJO_ALIAS_MOD[n])
        elif key is not None:
            raise ValueError(f"tiene dos teclas que no son Ctrl, Alt, Mayús ni Win ({key} y {p}).")
        elif len(p) == 1 and p.upper() in _ATAJO_VK:
            key = p.upper()
        elif n.upper() in _ATAJO_VK and n.upper().startswith("F"):
            key = n.upper()
        elif n in _ATAJO_ALIAS_TECLA:
            key = _ATAJO_ALIAS_TECLA[n]
        else:
            raise ValueError(f"«{p}» no es una tecla que Bridge sepa usar en un atajo.")
    if key is None:
        raise ValueError("solo tiene Ctrl, Alt, Mayús o Win: falta la tecla.")
    return frozenset(mods), key


def _atajo_altgr_escribe(key, shift):
    """Ctrl + Alt es AltGr en Windows: si en el teclado de este PC AltGr + key
    escribe algo («@» con la Q en el latinoamericano), devuelve ese caracter."""
    vk = _ATAJO_VK.get(key)
    if vk is None or not key.isalnum() or len(key) != 1 or sys.platform != "win32":
        return None
    try:
        import ctypes
        u = ctypes.windll.user32
        u.GetKeyboardLayout.restype = ctypes.c_void_p
        u.MapVirtualKeyExW.argtypes = [ctypes.c_uint, ctypes.c_uint, ctypes.c_void_p]
        u.ToUnicodeEx.argtypes = [ctypes.c_uint, ctypes.c_uint, ctypes.c_void_p, ctypes.c_wchar_p,
                                  ctypes.c_int, ctypes.c_uint, ctypes.c_void_p]
        hkl = u.GetKeyboardLayout(0)
        ks = (ctypes.c_ubyte * 256)()
        for v in (0x11, 0xA2, 0x12, 0xA5):  # Ctrl, Ctrl izq., Alt, Alt der. (AltGr)
            ks[v] = 0x80
        if shift:
            ks[0x10] = ks[0xA0] = 0x80
        buf = ctypes.create_unicode_buffer(8)
        n = u.ToUnicodeEx(vk, u.MapVirtualKeyExW(vk, 0, hkl), ks, buf, 8, 4, hkl)  # 4: sin tocar el estado
        if n < 0:
            return "un acento"
        ch = buf.value[:n] if n > 0 else ""
        return ch if ch and ch.isprintable() and not ch.isspace() else None
    except Exception:
        return None


def atajo_actual(aid, ambito):
    return _ATAJOS["activos"].get(ambito, {}).get(aid) or ""


def atajo_validar(aid, ambito, texto, probar=True):
    """-> (ok, canon, motivo). Las tres clases de conflicto: (a) otra accion de
    Bridge, (b) reservada por Windows o mala idea, (c) otra app la tiene
    (prueba en vivo con RegisterHotKey + UnregisterHotKey si probar)."""
    try:
        mods, key = _atajo_leer(texto)
    except ValueError as e:
        return False, "", f"«{texto}» no vale: {e}"
    canon = _atajo_texto(mods, key)
    fkey = key.startswith("F") and key[1:].isdigit()
    letra = len(key) == 1
    if canon in _ATAJO_SISTEMA:
        return False, canon, _ATAJO_SISTEMA[canon]
    if "Win" in mods:
        return False, canon, (f"{canon}: Windows se guarda casi todas las combinaciones con la tecla "
                              "Windows (Win + L bloquea, Win + D muestra el escritorio, Win + E, Win + R…) "
                              "y no deja registrarlas. Usa Ctrl + Alt + una letra.")
    if not (mods & {"Ctrl", "Alt"}) and not fkey:
        if mods == {"Mayús"} and letra:
            return False, canon, f"{canon} escribe una {key} mayúscula: añade Ctrl o Alt."
        return False, canon, f"{canon} solo, sin Ctrl ni Alt, se usa para escribir: añade Ctrl o Alt."
    if key in ("Tab", "Esc") or (key == "F10" and not mods):
        return False, canon, f"{key} lo usa Windows para moverse entre ventanas y campos: elige otra tecla."
    if ambito == "global":
        if canon == "Ctrl + K":
            return False, canon, ("Ctrl + K como atajo global pisaría el Ctrl + K del navegador, Slack o "
                                  "VS Code. Déjalo dentro de Bridge o usa Ctrl + Alt + una letra.")
        if canon == "Ctrl + Espacio":
            return False, canon, ("Ctrl + Espacio lo usan el cambio de idioma del teclado y muchos editores. "
                                  "Usa Ctrl + Alt + una letra.")
        if len(mods) < 2:
            return False, canon, (f"{canon} como atajo global se lo quitaría a todas las aplicaciones "
                                  "(copiar, buscar, menús…). Usa Ctrl + Alt + una letra.")
        if mods == {"Ctrl", "Mayús"} and (letra or key == "Espacio"):
            return False, canon, (f"{canon} choca con muchas aplicaciones (Ctrl + Mayús + T reabre "
                                  "pestañas, Ctrl + Mayús + N abre una ventana privada…). "
                                  f"Mejor Ctrl + Alt + {key} o Ctrl + Alt + Mayús + {key}.")
    if {"Ctrl", "Alt"} <= mods:
        ch = _atajo_altgr_escribe(key, "Mayús" in mods)
        if ch:
            return False, canon, (f"En el teclado de este PC, AltGr + {('Mayús + ' if 'Mayús' in mods else '')}"
                                  f"{key} escribe «{ch}» (Ctrl + Alt es lo mismo que AltGr): con este "
                                  "atajo ya no podrías escribirlo. Elige otra letra.")
    if canon in _ATAJO_FIJOS:
        return False, canon, f"{canon} ya es de Bridge: {_ATAJO_FIJOS[canon]}."
    for amb2, tabla in _ATAJOS["activos"].items():
        for aid2, c2 in tabla.items():
            if c2 == canon and (aid2, amb2) != (aid, ambito):
                if aid2 == aid:
                    return False, canon, (f"«{ATAJO_ACCIONES[aid]['nombre']}» ya tiene {canon} "
                                          f"{_ATAJO_AMBITO_TXT[amb2]}; con una basta.")
                n2 = ATAJO_ACCIONES.get(aid2, {}).get("nombre", aid2)
                return False, canon, f"{canon} ya la usa «{n2}» ({_ATAJO_AMBITO_TXT[amb2]})."
    if probar and ambito == "paleta":
        h = _ATAJOS.get("hilo")
        if h is not None and h.vivo:
            ok, err = h.pedir("probar", canon)
            if not ok and err == 1409:
                return False, canon, (f"{canon} ya la usa otra aplicación como atajo de todo Windows: "
                                      "con Bridge delante tampoco llegaría.")
    return True, canon, None


_FILAS_TECLADO = ("1234567890", "QWERTYUIOP", "ASDFGHJKL", "ZXCVBNM")


def _atajo_sugerir(aid, ambito, canon):
    """La combinacion libre mas cercana (misma tecla con el patron seguro,
    luego las teclas vecinas), comprobada en vivo. None si no encuentra."""
    try:
        mods, key = _atajo_leer(canon)
    except ValueError:
        return None
    pos = {ch: (r, c) for r, fila in enumerate(_FILAS_TECLADO) for c, ch in enumerate(fila)}
    if key in pos:
        r0, c0 = pos[key]
        vecinas = sorted((ch for ch in pos if ch != key and ch.isalpha()),
                         key=lambda ch: (abs(pos[ch][0] - r0) * 1.5 + abs(pos[ch][1] - c0)))
    elif key.startswith("F") and key[1:].isdigit():
        n = int(key[1:])
        vecinas = sorted((f"F{i}" for i in range(1, 13) if i not in (n, 12)), key=lambda f: abs(int(f[1:]) - n))
    else:
        vecinas = [ch for fila in _FILAS_TECLADO[1:] for ch in fila]
    seguros = [frozenset({"Ctrl", "Alt"}), frozenset({"Ctrl", "Alt", "Mayús"})]
    if ambito == "paleta" and (mods & {"Ctrl", "Alt"}):
        seguros = [mods] + [m for m in seguros if m != mods]
    cands = [_atajo_texto(m, key) for m in seguros]
    cands += [_atajo_texto(m, k) for m in seguros[:1] for k in vecinas]
    cands += [_atajo_texto(m, k) for m in seguros[1:] for k in vecinas]
    h = _ATAJOS.get("hilo")
    probados = 0
    for c in cands:
        if c == canon or c == atajo_actual(aid, ambito):
            continue
        ok, c2, _m = atajo_validar(aid, ambito, c, probar=False)
        if not ok:
            continue
        if h is not None and h.vivo:
            probados += 1
            if probados > 60:
                return None
            libre, _err = h.pedir("probar", c2)
            if not libre:
                continue
        return c2
    return None


class _HiloAtajos:
    """Atajos globales: RegisterHotKey(NULL, ...) asocia el atajo al hilo que
    lo registra, asi que todo (registrar, soltar, probar) pasa por este hilo y
    su bucle GetMessage. Si el proceso muere, Windows suelta sus atajos al
    acabar el hilo; al salir bien, atajos_salir() los suelta uno a uno."""
    WM_HOTKEY, WM_ORDEN, WM_QUIT = 0x0312, 0x8041, 0x0012
    ID_PRUEBA = 0xBFFE

    _VK_MOD = {0x10: "Mayús", 0xA0: "Mayús", 0xA1: "Mayús", 0x11: "Ctrl", 0xA2: "Ctrl", 0xA3: "Ctrl",
               0x12: "Alt", 0xA4: "Alt", 0xA5: "Alt", 0x5B: "Win", 0x5C: "Win"}

    def __init__(self):
        self.q = queue.Queue()
        self.salida = queue.Queue()  # hacia la ventana (la vacia _atajos_poll): este hilo no toca Tk
        self.tid = None
        self.listo = threading.Event()
        self.vivo = False
        self.reg = {}  # canon -> (id, aid)
        self._sig = 1
        self._u = None
        self._hook = None
        self._mh = set()

    def arrancar(self):
        threading.Thread(target=self._bucle, name="atajos-globales", daemon=True).start()
        return self.listo.wait(3) and self.vivo

    def _bucle(self):
        import ctypes
        from ctypes import wintypes
        u = ctypes.WinDLL("user32", use_last_error=True)
        u.RegisterHotKey.argtypes = [wintypes.HWND, ctypes.c_int, wintypes.UINT, wintypes.UINT]
        u.RegisterHotKey.restype = wintypes.BOOL
        u.UnregisterHotKey.argtypes = [wintypes.HWND, ctypes.c_int]
        u.PostThreadMessageW.argtypes = [wintypes.DWORD, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
        u.GetMessageW.argtypes = [ctypes.POINTER(wintypes.MSG), wintypes.HWND, wintypes.UINT, wintypes.UINT]
        u.PeekMessageW.argtypes = [ctypes.POINTER(wintypes.MSG), wintypes.HWND, wintypes.UINT,
                                   wintypes.UINT, wintypes.UINT]
        self._HOOKPROC = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_int, wintypes.WPARAM, wintypes.LPARAM)
        u.SetWindowsHookExW.argtypes = [ctypes.c_int, self._HOOKPROC, ctypes.c_void_p, wintypes.DWORD]
        u.SetWindowsHookExW.restype = ctypes.c_void_p
        u.UnhookWindowsHookEx.argtypes = [ctypes.c_void_p]
        u.CallNextHookEx.argtypes = [ctypes.c_void_p, ctypes.c_int, wintypes.WPARAM, wintypes.LPARAM]
        u.CallNextHookEx.restype = ctypes.c_ssize_t

        class _KBD(ctypes.Structure):
            _fields_ = [("vkCode", wintypes.DWORD), ("scanCode", wintypes.DWORD),
                        ("flags", wintypes.DWORD), ("time", wintypes.DWORD),
                        ("dwExtraInfo", ctypes.c_size_t)]
        self._KBD = _KBD
        self._u, self._ct = u, ctypes
        msg = wintypes.MSG()
        u.PeekMessageW(ctypes.byref(msg), None, 0, 0, 0)  # crea la cola de mensajes del hilo
        self.tid = ctypes.windll.kernel32.GetCurrentThreadId()
        self.vivo = True
        self.listo.set()
        try:
            while True:
                r = u.GetMessageW(ctypes.byref(msg), None, 0, 0)
                if r in (0, -1):
                    break
                if msg.message == self.WM_HOTKEY:
                    self._disparo(int(msg.wParam))
                elif msg.message == self.WM_ORDEN:
                    self._ordenes()
        finally:
            self._op_capturar(False)
            self._op_soltar_todo()
            self.vivo = False

    def _disparo(self, hid):
        for canon, (h, aid) in list(self.reg.items()):
            if h == hid:
                self.salida.put(("atajo", aid, canon))
                return

    def _ordenes(self):
        while True:
            try:
                op, args, caja = self.q.get_nowait()
            except queue.Empty:
                return
            if caja.get("tarde"):  # quien lo pidio ya se canso de esperar: no se hace
                continue
            try:
                caja["r"] = getattr(self, "_op_" + op)(*args)
            except Exception as e:
                caja["r"] = (False, f"{type(e).__name__}: {e}")
            caja["ev"].set()

    def pedir(self, op, *args, espera=3.0):
        if not self.vivo:
            return (False, "sin hilo")
        caja = {"ev": threading.Event(), "r": None}
        self.q.put((op, args, caja))
        self._u.PostThreadMessageW(self.tid, self.WM_ORDEN, 0, 0)
        if not caja["ev"].wait(espera):
            caja["tarde"] = True
            return (False, "el hilo de atajos no contesta")
        return caja["r"]

    def _gancho(self, n, wp, lp):
        # Solo existe mientras un campo captura (ver _op_capturar): la tecla va
        # al campo y a nadie mas, ni siquiera al atajo global de otra app (asi
        # Bridge puede decir «esa ya la usa otra aplicacion»).
        try:
            if n == 0:
                kb = self._ct.cast(lp, self._ct.POINTER(self._KBD)).contents
                vk, baja = int(kb.vkCode), wp in (0x100, 0x104)
                mod = self._VK_MOD.get(vk)
                if mod:
                    (self._mh.add if baja else self._mh.discard)(mod)
                    self.salida.put(("capt_mod", frozenset(self._mh)))
                    # Tambien se quedan aqui: si Windows viera Alt (o Win) bajar y
                    # subir sin la tecla de en medio, abriria el menu de la
                    # ventana (o Inicio) y la ventana se quedaria parada.
                    return 1
                if baja:
                    self.salida.put(("capt_tecla", frozenset(self._mh), _ATAJO_VK_NOMBRE.get(vk)))
                return 1
        except Exception:
            pass
        return self._u.CallNextHookEx(None, n, wp, lp)

    def _op_capturar(self, on):
        if on and self._hook is None:
            gaks = self._ct.windll.user32.GetAsyncKeyState  # lo que ya estaba pulsado al empezar
            self._mh = {m for vk, m in self._VK_MOD.items() if gaks(vk) & 0x8000}
            self._proc = self._HOOKPROC(self._gancho)
            k32 = self._ct.windll.kernel32
            k32.GetModuleHandleW.restype = self._ct.c_void_p
            self._hook = self._u.SetWindowsHookExW(13, self._proc, k32.GetModuleHandleW(None), 0)  # WH_KEYBOARD_LL
            return (bool(self._hook), None if self._hook else self._ct.get_last_error())
        if not on and self._hook:
            self._u.UnhookWindowsHookEx(self._hook)
            self._hook = None
        return (True, None)

    def _w32(self, canon):
        mods, key = _atajo_leer(canon)
        m = 0x4000  # MOD_NOREPEAT: dejar pulsado no lo repite
        for x in mods:
            m |= _ATAJO_MOD_W32[x]
        return m, _ATAJO_VK[key]

    def _op_registrar(self, canon, aid):
        m, vk = self._w32(canon)
        hid = self._sig
        self._sig += 1
        if self._u.RegisterHotKey(None, hid, m, vk):
            self.reg[canon] = (hid, aid)
            return (True, None)
        return (False, self._ct.get_last_error())

    def _op_soltar(self, canon):
        x = self.reg.pop(canon, None)
        if x is not None:
            self._u.UnregisterHotKey(None, x[0])
        return (True, None)

    def _op_probar(self, canon):
        m, vk = self._w32(canon)
        if self._u.RegisterHotKey(None, self.ID_PRUEBA, m, vk):
            self._u.UnregisterHotKey(None, self.ID_PRUEBA)
            return (True, None)
        return (False, self._ct.get_last_error())

    def _op_pausar(self):
        # Mientras se captura una combinacion: que las de Bridge no se la coman.
        for hid, _aid in self.reg.values():
            self._u.UnregisterHotKey(None, hid)
        return (True, None)

    def _op_reanudar(self):
        fallan = []
        for canon, (hid, aid) in list(self.reg.items()):
            m, vk = self._w32(canon)
            if not self._u.RegisterHotKey(None, hid, m, vk):
                fallan.append((canon, aid))
                self.reg.pop(canon, None)
        return (True, fallan)

    def _op_soltar_todo(self):
        if self._u is None:
            return (True, None)
        for hid, _aid in list(self.reg.values()):
            self._u.UnregisterHotKey(None, hid)
        self.reg.clear()
        return (True, None)

    def salir(self):
        if self.vivo:
            self.pedir("soltar_todo", espera=2.0)
            self._u.PostThreadMessageW(self.tid, self.WM_QUIT, 0, 0)


def _atajo_ejecutar(aid, ambito, canon=None):
    a = ATAJO_ACCIONES.get(aid)
    if a is None:
        return
    if ambito == "global":
        log(f"atajos: {canon or atajo_actual(aid, ambito)} (global) -> {a['nombre']}")
    try:
        if a.get("con_ambito"):
            a["fn"](ambito)
        else:
            a["fn"]()
    except Exception as e:
        log(f"atajos: «{a['nombre']}» fallo ({type(e).__name__}: {e})")


def _atajo_mods_evento(e, extra=()):
    st = int(getattr(e, "state", 0) or 0)
    mods = set(extra)
    if st & 0x4:
        mods.add("Ctrl")
    if st & 0x1:
        mods.add("Mayús")
    if st & 0x20000:
        mods.add("Alt")
    if sys.platform == "win32":
        try:
            import ctypes
            gks = ctypes.windll.user32.GetKeyState
            if (gks(0x5B) | gks(0x5C)) & 0x8000:
                mods.add("Win")
        except Exception:
            pass
    return mods


def _atajo_tecla_evento(e):
    n = _ATAJO_VK_NOMBRE.get(getattr(e, "keycode", None)) if sys.platform == "win32" else None
    if n:
        return n
    ks = getattr(e, "keysym", "") or ""
    if len(ks) == 1 and ks.isascii() and ks.isalnum():
        return ks.upper()
    if ks.startswith("F") and ks[1:].isdigit():
        return ks
    return _ATAJO_KEYSYM.get(ks)


def _atajo_tecla_tk(e):
    """bind_all: los atajos «dentro de Bridge» (Ctrl+K y los elegidos)."""
    if _ATAJOS["capturando"] is not None or not _ATAJOS["tabla"]:
        return None
    if getattr(e, "keysym", "") in _ATAJO_MOD_KEYSYM:
        return None
    key = _atajo_tecla_evento(e)
    if not key:
        return None
    aid = _ATAJOS["tabla"].get(_atajo_texto(_atajo_mods_evento(e), key))
    if aid is None:
        return None
    _atajo_ejecutar(aid, "paleta")
    return "break"


def _atajos_msg_corrupto(e):
    donde = f" (línea {e.lineno}, columna {e.colno})" if hasattr(e, "lineno") else ""
    return (f"settings.json está dañado{donde}: no se puede leer. No he guardado nada ni he "
            "borrado nada. Ábrelo con el Bloc de notas y arréglalo (o pon una copia buena) y "
            "vuelve a intentarlo.")


def _atajos_leer_settings():
    """-> (seccion atajos, error en palabras normales o None). Lee el archivo
    tal cual (load_settings devuelve {} si esta roto y aqui eso no vale)."""
    try:
        raw = SETTINGS_FILE.read_text(encoding="utf-8") if SETTINGS_FILE.exists() else "{}"
    except OSError as e:
        return {}, f"No pude leer settings.json ({e.strerror or e}). No he tocado nada."
    try:
        s = json.loads(raw.lstrip("﻿") or "{}")
    except ValueError as e:
        return {}, _atajos_msg_corrupto(e)
    if not isinstance(s, dict):
        return {}, ("settings.json no tiene la forma de siempre (tiene que empezar por «{»). "
                    "No he guardado nada ni he borrado nada.")
    sec = s.get("atajos")
    return (sec if isinstance(sec, dict) else {}), None


def _atajos_escribir(aid, ambito, canon):
    """Guarda solo atajos[aid][ambito] en settings.json; lo demas no se toca.
    Devuelve None o el error en palabras normales."""
    try:
        raw = SETTINGS_FILE.read_text(encoding="utf-8") if SETTINGS_FILE.exists() else "{}"
        s = json.loads(raw.lstrip("﻿") or "{}")
    except OSError as e:
        return f"No pude leer settings.json ({e.strerror or e})."
    except ValueError as e:
        return _atajos_msg_corrupto(e)
    if not isinstance(s, dict):
        return "settings.json no tiene la forma de siempre. No he guardado nada ni he borrado nada."
    sec = s.get("atajos") if isinstance(s.get("atajos"), dict) else {}
    sec = {"_como": _ATAJOS_COMO, **{k: v for k, v in sec.items() if k != "_como"}}
    ent = _atajo_entrada(sec, aid)
    ent[ambito] = canon
    sec[aid] = ent
    s["atajos"] = sec
    save_settings(s)
    try:
        hecho = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))["atajos"][aid][ambito] == canon
    except Exception:
        hecho = False
    if not hecho:
        return "No se pudo escribir settings.json (¿está abierto en otro programa o es de solo lectura?)."
    return None


def _atajo_entrada(sec, aid):
    """La entrada de una accion como {ambito: combinacion}. A mano tambien
    vale "abrir_paleta": "Ctrl + J" (va a su lista principal)."""
    ent = sec.get(aid)
    if isinstance(ent, dict):
        return {k: v for k, v in ent.items() if k in ("paleta", "global")}
    if isinstance(ent, str):
        a = ATAJO_ACCIONES.get(aid, {})
        principal = next(iter(a.get("defecto") or {}), (a.get("ambitos") or ("paleta",))[0])
        return {principal: ent}
    return {}


def _atajo_configurado(sec, aid, ambito):
    ent = _atajo_entrada(sec, aid)
    if ambito in ent:
        return str(ent.get(ambito) or "").strip()
    return ATAJO_ACCIONES.get(aid, {}).get("defecto", {}).get(ambito, "")


def _atajo_aplicar(aid, ambito, canon):
    """Cambia el atajo activo, sin tocar settings.json. Global: primero se
    registra el nuevo y solo si Windows lo acepta se suelta el viejo (nunca
    a medias). -> (ok, motivo, hay_que_sugerir)."""
    viejo = atajo_actual(aid, ambito)
    if canon == viejo:
        _ATAJOS["error"].pop((aid, ambito), None)
        return True, None, False
    if ambito == "global":
        h = _ATAJOS.get("hilo")
        if canon:
            if h is None or not h.vivo:
                return False, ("En el carril B los atajos globales los lleva el carril A." if LANE == "b"
                               else "Los atajos globales no están disponibles en esta copia de Bridge."), False
            ok, err = h.pedir("registrar", canon, aid)
            if not ok:
                if err == 1409:
                    return False, (f"{canon}: esa combinación ya la usa otra aplicación (o otra copia de "
                                   "Growi Bridge). Bridge no se la quita."), True
                return False, f"{canon}: Windows no la deja registrar (código {err}).", True
        if viejo and h is not None:
            h.pedir("soltar", viejo)
    if canon:
        _ATAJOS["activos"][ambito][aid] = canon
    else:
        _ATAJOS["activos"][ambito].pop(aid, None)
    _ATAJOS["error"].pop((aid, ambito), None)
    _atajos_refrescar()
    return True, None, False


def atajo_guardar(aid, ambito, texto):
    """Valida, aplica en caliente y guarda en settings.json. -> (ok, mensaje,
    sugerencia). Si algo falla, el atajo anterior sigue funcionando."""
    a = ATAJO_ACCIONES.get(aid)
    if a is None or ambito not in a["ambitos"]:
        return False, "Esa acción no tiene atajo en esa lista.", None
    viejo = atajo_actual(aid, ambito)
    sigue = f" Sigue {viejo}." if viejo else ""
    _sec, err = _atajos_leer_settings()  # lo primero: con el archivo roto no se guarda nada
    if err:
        _ATAJOS["settings_error"] = err
        _atajos_refrescar()
        return False, err + sigue, None
    canon = ""
    if (texto or "").strip():
        ok, canon, motivo = atajo_validar(aid, ambito, texto)
        if not ok:
            return False, motivo + sigue, (_atajo_sugerir(aid, ambito, canon) if canon else None)
    if canon == viejo and (aid, ambito) not in _ATAJOS["error"]:
        return True, (f"Ya era {canon}." if canon else "Ya estaba sin atajo."), None
    _sec, err = _atajos_leer_settings()
    if err:
        return False, err + sigue, None
    ok, motivo, sugerir = _atajo_aplicar(aid, ambito, canon)
    if not ok:
        return False, motivo + sigue, (_atajo_sugerir(aid, ambito, canon) if sugerir else None)
    werr = _atajos_escribir(aid, ambito, canon)
    if werr:
        _atajo_aplicar(aid, ambito, viejo)  # vuelve el de antes, entero
        return False, werr + sigue, None
    log(f"atajos: «{a['nombre']}» ({_ATAJO_AMBITO_TXT[ambito]}) {viejo or 'sin atajo'} -> "
        f"{canon or 'sin atajo'} (guardado en settings.json, sin reiniciar)")
    if canon:
        return True, f"Guardado: {canon}. Ya funciona, sin reiniciar.", None
    return True, "Atajo quitado.", None


def atajos_desde_settings(inicio=False):
    """Aplica la seccion «atajos» de settings.json (al arrancar y al editarla a
    mano). Lo que no valga se queda como estaba y lo dice en su fila."""
    sec, err = _atajos_leer_settings()
    _ATAJOS["settings_error"] = err
    if err:
        log(f"atajos: {err}")
        if not inicio:
            _atajos_refrescar()
            return
        sec = {}  # al arrancar con el archivo roto: los de fabrica
    deseo = {(aid, amb): _atajo_configurado(sec, aid, amb)
             for aid, a in ATAJO_ACCIONES.items() for amb in a["ambitos"]}
    cambios = [(k, v) for k, v in deseo.items() if v != atajo_actual(*k) or k in _ATAJOS["error"]]
    for (aid, amb), v in cambios:  # primero se sueltan, luego se ponen
        if not v:
            _atajo_aplicar(aid, amb, "")
    for (aid, amb), v in sorted((c for c in cambios if c[1]), key=lambda c: c[0][1] != "paleta"):
        actual = atajo_actual(aid, amb)
        sigue = f" Sigue {actual}." if actual else ""
        ok, canon, motivo = atajo_validar(aid, amb, v, probar=False)
        if not ok:
            _ATAJOS["error"][(aid, amb)] = ("En settings.json pone «" + v + "» y no vale. " + motivo + sigue)
            log(f"atajos: {ATAJO_ACCIONES[aid]['nombre']}: «{v}» no vale ({motivo})")
            continue
        if canon == actual:
            _ATAJOS["error"].pop((aid, amb), None)
            continue
        ok, motivo, _s = _atajo_aplicar(aid, amb, canon)
        if not ok:
            _ATAJOS["error"][(aid, amb)] = motivo + " Elige otra." + sigue
            log(f"atajos: {ATAJO_ACCIONES[aid]['nombre']}: {motivo}")
    act = [f"{c} ({'global' if amb == 'global' else 'en Bridge'})"
           for amb in ("paleta", "global") for c in _ATAJOS["activos"][amb].values()]
    log(f"atajos: activos {', '.join(act) or 'ninguno'}"
        + (f"; {len(_ATAJOS['error'])} con aviso" if _ATAJOS["error"] else ""))
    _atajos_refrescar()


def atajos_arrancar():
    """Al arrancar (despues de build_gui). Solo el carril A registra globales;
    el mutex de instancia unica ya impide una segunda copia, y si otra app (u
    otra copia de prueba) tiene la combinacion, RegisterHotKey falla y Bridge
    lo dice: nunca se la quita."""
    if LANE == "a" and sys.platform == "win32" and _ATAJOS["hilo"] is None:
        h = _HiloAtajos()
        if h.arrancar():
            _ATAJOS["hilo"] = h
            import atexit
            atexit.register(atajos_salir)
            if _root is not None:
                _root.after(50, _atajos_poll)
        else:
            log("atajos: no arranco el hilo de atajos globales")
    atajos_desde_settings(inicio=True)


def _atajos_poll():
    """Cada 50 ms: lo que mando el hilo de atajos (atajo global pulsado, teclas
    del gancho de captura). El hilo nunca llama a Tk: asi no hay bloqueos."""
    h = _ATAJOS.get("hilo")
    if h is None or _root is None:
        return
    for _ in range(20):
        try:
            ev = h.salida.get_nowait()
        except queue.Empty:
            break
        try:
            if ev[0] == "atajo":
                _atajo_ejecutar(ev[1], "global", ev[2])
            elif _ATAJOS["capturando"] is not None:
                _ATAJOS["capturando"].desde_gancho(ev)
        except Exception as e:
            log(f"atajos: {type(e).__name__}: {e}")
    try:
        _root.after(50, _atajos_poll)
    except Exception:
        pass


def atajos_salir():
    """UnregisterHotKey de todos los globales (cierre limpio)."""
    h = _ATAJOS.get("hilo")
    if h is not None and h.vivo:
        n = len(h.reg)
        h.salir()
        log(f"atajos: {n} atajo(s) global(es) soltado(s) al salir")
    _ATAJOS["hilo"] = None


def _atajos_refrescar():
    """Tras cualquier cambio: tabla de teclas, chips (paleta, barra lateral) y
    los campos de Ajustes -> Atajos."""
    _ATAJOS["tabla"] = {c: aid for aid, c in _ATAJOS["activos"]["paleta"].items() if c}
    chips = {"ventana": "mostrar_ventana", "pedir": "preguntar_rapido", "parar": "parar_tarea"}
    for c in _PALETTE_CMDS:
        aid = chips.get(c.get("id"))
        if aid:
            c["chip"] = _atajo_compacto(atajo_actual(aid, "global") or atajo_actual(aid, "paleta")) or None
    for c in _PALETTE_CMDS:  # comandos de IA: el chip es su atajo propio
        if c.get("cmdia_id"):
            _a = "comando:" + c["cmdia_id"]
            c["chip"] = _atajo_compacto(atajo_actual(_a, "global") or atajo_actual(_a, "paleta")) or None
    kc = _widgets.get("kc_chip")
    if kc is not None:
        try:
            k = _atajo_compacto(atajo_actual("abrir_paleta", "paleta"))
            kc.config(text=k)
            (kc.pack(side="right") if k else kc.pack_forget())
        except Exception:
            pass
    vivos = []
    for campo in _ATAJOS["campos"]:
        if campo.refrescar():
            vivos.append(campo)
    _ATAJOS["campos"] = vivos
    av = _ATAJOS.get("aviso_cfg")
    if av is not None:
        try:
            av.poner(_ATAJOS["settings_error"] or "", "error")
        except Exception:
            pass


class _CampoAtajo:
    """Campo de captura (patron Flow Launcher): clic (o Espacio/Intro con el
    foco) y se PULSA la combinacion; queda validada y guardada. Esc cancela
    sin guardar. Mientras captura, los atajos globales de Bridge se apartan
    para que no se coman la combinacion."""

    def __init__(self, foco, aid, ambito, pintar, msg):
        self.foco, self.aid, self.ambito, self.pintar, self.msg = foco, aid, ambito, pintar, msg
        self.capt = False
        self.vistos = set()
        self._tope = None
        for seq in ("<KeyPress>", "<Alt-KeyPress>"):
            foco.bind(seq, self._tecla)
        foco.bind("<KeyRelease>", self._suelta)
        foco.bind("<FocusOut>", self._fuera)
        _ATAJOS["campos"].append(self)
        self.refrescar()

    def refrescar(self):
        try:
            if not self.foco.winfo_exists():
                return False
            if not self.capt:
                act = atajo_actual(self.aid, self.ambito)
                self.pintar(act or "Sin atajo", False, bool(act))
                err = _ATAJOS["error"].get((self.aid, self.ambito))
                if err:
                    self.msg.poner(err, "error")
            return True
        except Exception:
            return False

    def empezar(self, _e=None):
        if self.capt:
            return "break"
        otro = _ATAJOS["capturando"]
        if otro is not None and otro is not self:
            otro.cancelar(silencio=True)
        self.capt = True
        self.vistos = set()
        _ATAJOS["capturando"] = self
        h = _ATAJOS.get("hilo")
        if h is not None and h.vivo:
            h.pedir("pausar")
            h.pedir("capturar", True)  # gancho de teclado SOLO mientras dura la captura
        try:
            self.foco.focus_set()
            self._tope = self.foco.after(30000, self.cancelar)  # nunca se queda capturando
        except Exception:
            pass
        self.pintar("Pulsa la combinación…", True, False)
        self.msg.poner("Pulsa las teclas a la vez (por ejemplo Ctrl + Alt + T). Esc cancela.", "info")
        return "break"

    def desde_gancho(self, ev):
        """Lo que vio el gancho de teclado (ver _HiloAtajos._gancho)."""
        if not self.capt:
            return
        if ev[0] == "capt_mod":
            m = set(ev[1])
            self.pintar((" + ".join([x for x in ATAJO_MODS if x in m]) + " + …") if m
                        else "Pulsa la combinación…", True, bool(m))
            return
        mods, key = set(ev[1]), ev[2]
        if key == "Esc" and not mods:
            self.cancelar()
        elif not key:
            self.msg.poner("Esa tecla no sirve para un atajo. Prueba con una letra, un número o "
                           "F1 a F12, junto con Ctrl o Alt.", "error")
        else:
            self._fin_captura()
            self.guardar(_atajo_texto(mods, key))

    def _fin_captura(self):
        self.capt = False
        if _ATAJOS["capturando"] is self:
            _ATAJOS["capturando"] = None
        try:
            self.foco.after_cancel(self._tope)
        except Exception:
            pass
        h = _ATAJOS.get("hilo")
        if h is not None and h.vivo:
            h.pedir("capturar", False)
            _ok, fallan = h.pedir("reanudar")
            for canon, aid in fallan or []:
                _ATAJOS["activos"]["global"].pop(aid, None)
                _ATAJOS["error"][(aid, "global")] = (f"{canon} se perdió mientras capturabas: otra "
                                                     "aplicación la tomó. Elige otra.")
                log(f"atajos: {canon} no se pudo recuperar tras capturar (otra aplicacion la tomo)")
            if fallan:
                _atajos_refrescar()

    def cancelar(self, silencio=False):
        if not self.capt:
            return
        self._fin_captura()
        self.refrescar()
        act = atajo_actual(self.aid, self.ambito)
        self.msg.poner("" if silencio else f"Cancelado: sigue {act or 'sin atajo'}.", "info")

    def _mods(self, e):
        return _atajo_mods_evento(e, extra=self.vistos & {"Win"})

    def _tecla(self, e):
        ks = getattr(e, "keysym", "")
        if not self.capt:
            if ks in ("space", "Return") and not (int(e.state or 0) & 0x20005):
                return self.empezar()
            return None
        if ks in _ATAJO_MOD_KEYSYM:
            self.vistos.add(_ATAJO_MOD_KEYSYM[ks])
            m = self._mods(e) | {_ATAJO_MOD_KEYSYM[ks]}
            self.pintar(" + ".join([x for x in ATAJO_MODS if x in m]) + " + …", True, True)
            return "break"
        mods = self._mods(e)
        if ks == "Escape" and not mods:
            self.cancelar()
            return "break"
        key = _atajo_tecla_evento(e)
        if not key:
            self.msg.poner("Esa tecla no sirve para un atajo. Prueba con una letra, un número o "
                           "F1 a F12, junto con Ctrl o Alt.", "error")
            return "break"
        self._fin_captura()
        self.guardar(_atajo_texto(mods, key))
        return "break"

    def _suelta(self, e):
        m = _ATAJO_MOD_KEYSYM.get(getattr(e, "keysym", ""))
        if m:
            self.vistos.discard(m)
        return "break" if self.capt else None

    def _fuera(self, _e=None):
        if self.capt:
            self.cancelar()

    def guardar(self, texto):
        ok, mensaje, sug = atajo_guardar(self.aid, self.ambito, texto)
        self.refrescar()
        self.msg.poner(mensaje, "ok" if ok else "error", sug, self.guardar)
        return ok

    def quitar(self):
        if self.capt:
            self._fin_captura()
        return self.guardar("")


def _atajos_construir(kit, card):
    """Ajustes -> Atajos con el «kit» de widgets que toque (CustomTkinter o
    tkinter clasico): las mismas filas, los mismos manejadores."""
    _ATAJOS["campos"] = []
    _ATAJOS["listas"] = {}
    r = kit["row"](card)
    kit["texto"](r, None, "Haz clic en un campo y pulsa la combinación que quieras: se comprueba, "
                          "se guarda y funciona al momento, sin reiniciar. Esc cancela.")
    _ATAJOS["aviso_cfg"] = kit["msg"](r)
    for ambito, titulo, expl in _ATAJO_LISTAS:
        r = kit["row"](card)
        kit["texto"](r, titulo, expl)
        cont = kit["lista"](card)
        _ATAJOS["listas"][ambito] = (kit, cont)
    _atajos_filas_todas()


def _atajos_filas_todas():
    for ambito, (kit, cont) in list(_ATAJOS["listas"].items()):
        try:
            if not cont.winfo_exists():
                continue
            for ch in cont.winfo_children():
                ch.destroy()
            kit["reset"](cont)
            for aid, a in ATAJO_ACCIONES.items():
                if ambito in a["ambitos"]:
                    _atajo_fila(kit, cont, aid, ambito)
            if ambito == "global" and not any(a["grupo"] == "comando" for a in ATAJO_ACCIONES.values()):
                kit["texto"](kit["row"](cont), None,
                             "Los comandos guardados también podrán tener su atajo: saldrán en estas listas.")
        except Exception as e:
            log(f"atajos: no se pudo dibujar la lista {ambito} ({type(e).__name__}: {e})")
    _atajos_refrescar()


def _atajo_fila(kit, cont, aid, ambito):
    a = ATAJO_ACCIONES[aid]
    r = kit["row"](cont)
    der = kit["frame"](r)
    der.pack(side="right", anchor="n", padx=(16, 0))
    campo, foco, pintar = kit["campo"](der)
    campo.pack(side="left")
    holder = {}
    kit["boton"](der, "Quitar", lambda: holder["c"].quitar()).pack(side="left", padx=(8, 0))
    izq = kit["frame"](r)
    izq.pack(side="left", fill="x", expand=True)
    kit["texto"](izq, a["nombre"] + (" (comando guardado)" if a["grupo"] == "comando" else ""), a["expl"])
    c = _CampoAtajo(foco, aid, ambito, pintar, kit["msg"](izq))
    holder["c"] = c
    kit["al_clic"](campo, c.empezar)
    _widgets[f"atajo_{aid}_{ambito}"] = c
    return c


def _atajos_kit_tk():
    T = THEME

    def row(parent):
        if getattr(parent, "_rows", 0):
            tk.Frame(parent, bg=T["line"], height=S(1)).pack(fill="x", padx=16)
        parent._rows = getattr(parent, "_rows", 0) + 1
        f = tk.Frame(parent, bg=T["card"])
        f.pack(fill="x", padx=16, pady=8)
        return f

    def lista(parent):
        f = tk.Frame(parent, bg=T["card"])
        f.pack(fill="x")
        f._rows = 1
        return f

    def texto(parent, title, expl):
        if title:
            tk.Label(parent, text=title, font=(FONT, 10, "bold"), bg=T["card"], fg=T["text"],
                     anchor="w", justify="left").pack(anchor="w")
        if expl:
            tk.Label(parent, text=expl, font=(FONT, 9), bg=T["card"], fg=T["muted"], anchor="w",
                     justify="left", wraplength=S(370)).pack(anchor="w")

    def campo(parent):
        lab = tk.Label(parent, text="", font=(FONT, 10), bg="#FFFFFF", fg=T["text"], width=20,
                       padx=S(8), pady=S(4), takefocus=1, cursor="hand2", highlightthickness=S(1),
                       highlightbackground=T["line"], highlightcolor=T["blue"])

        def pintar(txt, capt, real):
            lab.config(text=txt, fg=T["text"] if (real or capt) else T["muted"],
                       highlightbackground=T["blue"] if capt else T["line"],
                       highlightthickness=S(2) if capt else S(1))
        return lab, lab, pintar

    class Msg:
        def __init__(self, parent):
            self.lab = tk.Label(parent, text="", font=(FONT, 9), bg=T["card"], anchor="w",
                                justify="left", wraplength=S(370))
            self.btn = ttk.Button(parent, text="")

        def poner(self, txt, tipo, sug=None, usar=None):
            if not txt:
                self.lab.pack_forget()
                self.btn.pack_forget()
                return
            self.lab.config(text=txt, fg={"ok": T["green_text"], "error": T["red"]}.get(tipo, T["muted"]))
            self.lab.pack(anchor="w", pady=(4, 0))
            if sug and usar:
                self.btn.config(text=f"Usar {sug}", command=lambda: usar(sug))
                self.btn.pack(anchor="w", pady=(4, 0))
            else:
                self.btn.pack_forget()

    return {"row": row, "lista": lista, "texto": texto, "campo": campo, "msg": Msg,
            "frame": lambda p: tk.Frame(p, bg=T["card"]),
            "boton": lambda p, t, cmd: ttk.Button(p, text=t, command=cmd),
            "al_clic": lambda w, fn: w.bind("<Button-1>", fn),
            "reset": lambda cont: setattr(cont, "_rows", 1)}


def _atajos_seccion_tk(tab_aj):
    at = tk.Frame(tab_aj, bg=THEME["card"])
    at.pack(fill="x", padx=20, pady=8)
    _widgets["atajos_anchor"] = at
    tk.Label(at, text="Atajos", font=SECTION_FONT, bg=THEME["card"],
             fg=THEME["text"]).pack(anchor="w", padx=16, pady=(12, 2))
    _atajos_construir(_atajos_kit_tk(), at)
    tk.Frame(at, bg=THEME["card"], height=S(8)).pack()


def _atajos_kit_ctk(ctk, row, text_block, F, wrap_to, seg_bg, seg_hover, accent, accent_hover):
    T = THEME

    def lista(parent):
        f = ctk.CTkFrame(parent, fg_color="transparent")
        f.pack(fill="x", padx=2)  # sin tapar el borde fino de la tarjeta
        f._rows = 1
        return f

    def texto(parent, title, expl):
        text_block(parent, title, expl)

    def campo(parent):
        b = ctk.CTkButton(parent, text="", font=F(13), corner_radius=8, height=32, width=190,
                          fg_color=T["field"], hover_color=_C("#F5F5F7"), text_color=T["text"],
                          border_width=1, border_color=T["line"])
        try:
            foco = b._canvas
            foco.configure(takefocus=1)
        except Exception:
            foco = b

        def pintar(txt, capt, real):
            b.configure(text=txt, text_color=T["text"] if (real or capt) else T["muted"],
                        border_color=T["blue"] if capt else T["line"], border_width=2 if capt else 1)
        return b, foco, pintar

    class Msg:
        def __init__(self, parent):
            self.lab = ctk.CTkLabel(parent, text="", font=F(13), anchor="w", justify="left", height=1)
            wrap_to(self.lab, parent)
            self.btn = ctk.CTkButton(parent, text="", font=F(13), corner_radius=8, height=30, width=0,
                                     border_spacing=10, fg_color=accent, hover_color=accent_hover,
                                     text_color=_tema_fijo("on_accent"))

        def poner(self, txt, tipo, sug=None, usar=None):
            if not txt:
                self.lab.pack_forget()
                self.btn.pack_forget()
                return
            self.lab.configure(text=txt, text_color={"ok": T["green_text"], "error": T["red"]}.get(
                tipo, T["muted"]))
            self.lab.pack(anchor="w", fill="x", pady=(6, 0))
            if sug and usar:
                self.btn.configure(text=f"Usar {sug}", command=lambda: usar(sug))
                self.btn.pack(anchor="w", pady=(6, 0))
            else:
                self.btn.pack_forget()

    return {"row": row, "lista": lista, "texto": texto, "campo": campo, "msg": Msg,
            "frame": lambda p: ctk.CTkFrame(p, fg_color="transparent"),
            "boton": lambda p, t, cmd: ctk.CTkButton(p, text=t, command=cmd, font=F(13), corner_radius=8,
                                                     height=32, width=0, border_spacing=10,
                                                     fg_color=seg_bg, hover_color=seg_hover,
                                                     text_color=T["text"]),
            "al_clic": lambda w, fn: w.configure(command=fn),
            "reset": lambda cont: setattr(cont, "_rows", 1)}


# ---------------------------------------------------------------- comandos de IA guardados
# t-comandos-ia-guardados: el mecanismo de Raycast AI Commands (INVESTIGACION-0.3.0
# §5, hilo 5 §4.1). Un comando = titulo + prompt con {seleccion} (el texto
# seleccionado) y {argumento nombre="..."} (un dato que se pide al ejecutar) +
# icono + modelo (el id de un motor de engines.json: el descriptor generico de
# t-motor-generico; aqui NO se crea ni se toca ningun motor) + creatividad (fiel /
# equilibrado / creativo) + salida (mostrar para revisar / reemplazar el texto).
# Los tres integrados viven en el codigo y no se editan: se duplican para
# adaptarlos. Los de Leandro van en comandos-ia.json junto a growi-bridge.py (UNA
# lista; la escribe la app). Archivo danado: no se toca y la app lo dice; un
# comando mal escrito no aparece y la app dice por que. Atajo propio: el mismo
# mecanismo de Ajustes -> Atajos (atajo_registrar_accion("comando:<id>") +
# atajo_guardar, guardado en settings.json -> atajos). La paleta sigue en tkinter
# clasico; el formulario y la ventana del comando son superficies nuevas
# (CustomTkinter con la clasica de respaldo, el kit _KitCtk / _KitTk).
CMDIA_FILE = APP_DIR / "comandos-ia.json"
CMDIA_COMO = ("Comandos de IA guardados de Growi Bridge. Los escribe la app (Ctrl+K -> «Nuevo comando de IA» "
              "o «Editar el comando»); a mano también vale. Campos: id, titulo, prompt ({seleccion} = el texto "
              "seleccionado; {argumento nombre=\"idioma\"} = un dato que se pide al ejecutar), icono, modelo (id "
              "de un motor de engines.json), creatividad (fiel | equilibrado | creativo), salida (mostrar | "
              "reemplazar). Nada de claves aquí. El atajo de cada comando va en settings.json -> atajos -> "
              "\"comando:<id>\".")
CMDIA_ICONOS = (("lista", "≡", "Lista"), ("lapiz", "✎", "Lápiz"), ("idioma", "⇄", "Ida y vuelta"),
                ("texto", "¶", "Párrafo"), ("correo", "✉", "Sobre"), ("estrella", "★", "Estrella"),
                ("visto", "✓", "Visto"), ("pregunta", "?", "Pregunta"), ("rombo", "◆", "Rombo"),
                ("suma", "∑", "Suma"))
# (clave, palabra, explicacion, temperatura para los motores HTTP)
CMDIA_CREATIVIDAD = (("fiel", "Fiel", "Se ciñe al texto: no añade nada que no esté.", 0.2),
                     ("equilibrado", "Equilibrado", "Mejora la forma sin inventar el fondo.", 0.7),
                     ("creativo", "Creativo", "Se permite proponer ideas y frases nuevas.", 1.0))
CMDIA_SALIDAS = (("mostrar", "Mostrar para revisar"), ("reemplazar", "Reemplazar el texto"))
CMDIA_MOTOR_INTEGRADOS = "ollama"  # $0 en el PC: lo gratis primero (regla de Leandro)
CMDIA_INTEGRADOS = (
    {"id": "resumir-3-vinetas", "titulo": "Resumir en 3 viñetas", "icono": "lista",
     "prompt": "Resume {seleccion} en 3 viñetas: contexto, decisión, próximo paso.",
     "modelo": CMDIA_MOTOR_INTEGRADOS, "creatividad": "fiel", "salida": "mostrar"},
    {"id": "mejorar-texto", "titulo": "Mejorar texto", "icono": "lapiz",
     "prompt": "Mejora {seleccion} manteniendo el sentido, en mi tono.",
     "modelo": CMDIA_MOTOR_INTEGRADOS, "creatividad": "equilibrado", "salida": "mostrar"},
    {"id": "traducir", "titulo": "Traducir", "icono": "idioma",
     "prompt": "Traduce {seleccion} a {argumento nombre=\"idioma\"}.",
     "modelo": CMDIA_MOTOR_INTEGRADOS, "creatividad": "fiel", "salida": "mostrar"},
)
_CMDIA = {"firma": False, "comandos": [], "errores": [], "error_archivo": None, "atajos": set(),
          "llamadas": 0, "ventana": None, "form": None, "lock": threading.Lock()}
_CMDIA_SEL_RE = re.compile(r"\{\s*selecci[oó]n\s*\}", re.I)
_CMDIA_ARG_RE = re.compile(r"\{\s*argumento\s+nombre\s*=\s*[\"'“”«»]([^\"'“”«»{}]{1,40})[\"'“”«»]\s*\}", re.I)
_CMDIA_ID_RE = re.compile(r"^[a-z0-9][a-z0-9-]{0,47}$")


def cmdia_icono(clave):
    return next((g for k, g, _n in CMDIA_ICONOS if k == clave), "¶")


def cmdia_argumentos(prompt):
    """Los datos que pide el prompt, en orden y sin repetir («idioma»...)."""
    vistos = []
    for m in _CMDIA_ARG_RE.finditer(prompt or ""):
        n = m.group(1).strip()
        if n and _norm(n) not in [_norm(v) for v in vistos]:
            vistos.append(n)
    return vistos


def cmdia_usa_seleccion(prompt):
    return bool(_CMDIA_SEL_RE.search(prompt or ""))


def cmdia_dato_txt(nombre):
    """«idioma» -> «Idioma» (el nombre del dato tal cual, en palabras normales)."""
    n = str(nombre or "").strip()
    return n[:1].upper() + n[1:]


def cmdia_validar(d, donde="el comando"):
    """-> (comando normalizado, None) o (None, motivo en palabras normales).
    Lo que falta y tiene un valor obvio (icono, creatividad, salida) se rellena;
    lo que esta mal escrito no se adivina."""
    if not isinstance(d, dict):
        return None, f"{donde} no es un comando: cada uno va entre llaves {{ … }}."
    cid = d.get("id")
    if not isinstance(cid, str) or not _CMDIA_ID_RE.match(cid):
        return None, (f"{donde}: el «id» tiene que ser una palabra corta en minúsculas, números y guiones "
                      f"(p. ej. «resumir-correo»); pone {json.dumps(cid, ensure_ascii=False)}.")
    titulo = d.get("titulo")
    if not isinstance(titulo, str) or not titulo.strip():
        return None, f"{donde} («{cid}») no tiene «titulo»: es el nombre que sale en la paleta."
    if len(titulo.strip()) > 60:
        return None, f"{donde} («{cid}»): el título pasa de 60 letras ({len(titulo.strip())})."
    prompt = d.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        return None, f"«{titulo.strip()}» no tiene «prompt»: es lo que se le pide a la IA."
    if len(prompt) > 8000:
        return None, f"«{titulo.strip()}»: el prompt pasa de 8000 letras ({len(prompt)})."
    for tipo, rx in _SECRETO_RES:
        if rx.search(prompt) or rx.search(titulo):
            return None, (f"«{titulo.strip()}» lleva algo que parece una clave ({tipo}). Las claves no van en "
                          "los comandos (viven en Ajustes → Claves): este comando no se carga.")
    icono = d.get("icono") or "texto"
    if icono not in [k for k, _g, _n in CMDIA_ICONOS]:
        return None, (f"«{titulo.strip()}»: el icono «{icono}» no existe. Vale uno de: "
                      + ", ".join(k for k, _g, _n in CMDIA_ICONOS) + ".")
    modelo = d.get("modelo")
    if not isinstance(modelo, str) or not modelo.strip():
        return None, f"«{titulo.strip()}» no dice qué «modelo» usa (el id de un motor de engines.json)."
    crea = d.get("creatividad") or "equilibrado"
    if crea not in [k for k, *_r in CMDIA_CREATIVIDAD]:
        return None, f"«{titulo.strip()}»: la creatividad «{crea}» no existe (fiel, equilibrado o creativo)."
    salida = d.get("salida") or "mostrar"
    if salida not in [k for k, _l in CMDIA_SALIDAS]:
        return None, f"«{titulo.strip()}»: la salida «{salida}» no existe (mostrar o reemplazar)."
    if salida == "reemplazar" and not cmdia_usa_seleccion(prompt):
        return None, (f"«{titulo.strip()}» reemplaza el texto pero su prompt no lleva {{seleccion}}: no "
                      "sabría qué texto sustituir.")
    out = {"id": cid, "titulo": titulo.strip(), "prompt": prompt.strip(), "icono": icono,
           "modelo": modelo.strip(), "creatividad": crea, "salida": salida}
    for k in ("basado_en", "creado", "modificado"):
        if isinstance(d.get(k), str) and d.get(k):
            out[k] = d[k]
    return out, None


def _cmdia_leer_archivo():
    """-> (lista cruda | None, error en palabras normales | None). Sin archivo:
    lista vacia (todavia no guardaste ninguno). Nunca lanza."""
    try:
        if not CMDIA_FILE.exists():
            return [], None
        raw = CMDIA_FILE.read_text(encoding="utf-8")
    except OSError as e:
        return None, f"No pude leer comandos-ia.json ({e.strerror or e}). No he tocado nada."
    try:
        data = json.loads(raw.lstrip("﻿") or "{}")
    except ValueError as e:
        donde = f" (línea {e.lineno}, columna {e.colno})" if hasattr(e, "lineno") else ""
        return None, (f"comandos-ia.json está dañado{donde}: no se puede leer, así que tus comandos guardados "
                      "no aparecen (los integrados sí). No lo he tocado ni borrado. Ábrelo con el Bloc de notas "
                      "y arréglalo (o pon una copia buena).")
    if isinstance(data, list):
        return data, None
    if not isinstance(data, dict) or not isinstance(data.get("comandos", []), list):
        return None, ("comandos-ia.json no tiene la forma de siempre (un «{» con una lista «comandos»): tus "
                      "comandos guardados no aparecen. No lo he tocado.")
    return data.get("comandos", []), None


def cmdia_cargar(forzar=False):
    """Lee comandos-ia.json si cambio (o forzar). Rellena _CMDIA y da de alta
    los atajos de cada comando. -> True si releyo."""
    try:
        st = CMDIA_FILE.stat()
        firma = (st.st_mtime_ns, st.st_size)
    except OSError:
        firma = None
    if not forzar and firma == _CMDIA["firma"]:
        return False
    lista, err = _cmdia_leer_archivo()
    comandos, errores = [], []
    ids = {c["id"] for c in CMDIA_INTEGRADOS}
    for i, d in enumerate(lista or [], start=1):
        c, motivo = cmdia_validar(d, f"El comando nº {i}")
        if c is None:
            errores.append(motivo)
            continue
        if c["id"] in ids:
            errores.append(f"«{c['titulo']}»: el id «{c['id']}» ya lo usa otro comando"
                           + (" integrado" if c["id"] in {x['id'] for x in CMDIA_INTEGRADOS} else "")
                           + ": cámbialo para que aparezca.")
            continue
        ids.add(c["id"])
        comandos.append(c)
    with _CMDIA["lock"]:
        _CMDIA.update(firma=firma, comandos=comandos, errores=errores, error_archivo=err)
    if err or errores:
        for m in ([err] if err else []) + errores:
            log(f"comandos-ia: {m}")
    log(f"comandos-ia: {len(CMDIA_INTEGRADOS)} integrados + {len(comandos)} tuyos"
        + (f"; {len(errores)} no se cargaron" if errores else "") + ("; archivo dañado" if err else ""))
    _cmdia_registrar_atajos()
    return True


def cmdia_todos():
    integ = [dict(c, integrado=True) for c in CMDIA_INTEGRADOS]
    return integ + [dict(c, integrado=False) for c in _CMDIA["comandos"]]


def cmdia_buscar(cid):
    return next((c for c in cmdia_todos() if c["id"] == cid), None)


def cmdia_nuevo_id(titulo, ocupados=None):
    base = re.sub(r"[^a-z0-9]+", "-", _norm(titulo)).strip("-")[:40] or "comando"
    ocupados = set(ocupados if ocupados is not None else (c["id"] for c in cmdia_todos()))
    cid, n = base, 2
    while cid in ocupados:
        cid = f"{base}-{n}"
        n += 1
    return cid


def _cmdia_escribir(lista):
    """Escribe la lista entera (archivo temporal + os.replace: nunca a medias)
    y comprueba que quedo bien. -> None o el error en palabras normales."""
    data = {"_como": CMDIA_COMO, "esquema": 1, "comandos": lista}
    tmp = CMDIA_FILE.with_name(CMDIA_FILE.name + ".tmp")
    try:
        tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        os.replace(tmp, CMDIA_FILE)
        vuelta = json.loads(CMDIA_FILE.read_text(encoding="utf-8"))["comandos"]
    except (OSError, ValueError, KeyError) as e:
        return f"No se pudo escribir comandos-ia.json ({type(e).__name__}: {e}). ¿Está abierto en otro programa?"
    if vuelta != lista:
        return "comandos-ia.json no quedó como debía (lo escribió otro a la vez): vuelve a guardar."
    return None


def cmdia_guardar(d, id_anterior=None):
    """Alta o cambio de UN comando (lo demas del archivo no se toca). ->
    (ok, mensaje, comando)."""
    c, motivo = cmdia_validar(d)
    if c is None:
        return False, motivo, None
    if c["id"] in {x["id"] for x in CMDIA_INTEGRADOS}:
        return False, "Ese id es de un comando integrado: los integrados se duplican, no se pisan.", None
    with _CMDIA["lock"]:
        lista, err = _cmdia_leer_archivo()
        if err:
            return False, err + " Por eso no he guardado nada.", None
        lista = list(lista)
        ahora = datetime.now(TZ_CARACAS).strftime("%Y-%m-%d %H:%M")
        viejo = id_anterior or c["id"]
        pos = next((i for i, x in enumerate(lista) if isinstance(x, dict) and x.get("id") == viejo), None)
        if pos is None and any(isinstance(x, dict) and x.get("id") == c["id"] for x in lista):
            return False, f"Ya hay otro comando con el id «{c['id']}».", None
        if pos is not None:
            c.setdefault("creado", lista[pos].get("creado") or ahora)
            c["modificado"] = ahora
            lista[pos] = c
        else:
            c["creado"] = c["modificado"] = ahora
            lista.append(c)
        werr = _cmdia_escribir(lista)
    if werr:
        return False, werr, None
    if id_anterior and id_anterior != c["id"]:
        _cmdia_quitar_atajo(id_anterior)
    log(f"comandos-ia: «{c['titulo']}» guardado en {CMDIA_FILE.name} ({'cambio' if pos is not None else 'nuevo'}; "
        f"motor {c['modelo']}, {c['creatividad']}, salida {c['salida']})")
    cmdia_cargar(forzar=True)
    cmdia_paleta_sync()
    return True, f"Guardado en {CMDIA_FILE.name}. Ya está en la paleta (Ctrl+K).", c


def cmdia_borrar(cid):
    """Quita UN comando del archivo (solo tras la confirmacion del formulario)."""
    with _CMDIA["lock"]:
        lista, err = _cmdia_leer_archivo()
        if err:
            return False, err
        nueva = [x for x in lista if not (isinstance(x, dict) and x.get("id") == cid)]
        if len(nueva) == len(lista):
            return False, "Ese comando ya no está en el archivo."
        werr = _cmdia_escribir(nueva)
    if werr:
        return False, werr
    _cmdia_quitar_atajo(cid)
    log(f"comandos-ia: comando «{cid}» borrado de {CMDIA_FILE.name} (lo pediste tú en el formulario)")
    cmdia_cargar(forzar=True)
    cmdia_paleta_sync()
    return True, "Borrado."


# ---- motor: solo el descriptor (t-motor-generico); nada de motores propios
def cmdia_motor_basico(mid):
    """(ok, motivo) sin llamar a nada: el motor esta descrito en engines.json y
    sirve para un turno de texto."""
    if not mid:
        return False, "el comando no dice qué motor usa"
    try:
        eng = get_engine(mid)
    except Exception as e:
        return False, f"no se pudo leer engines.json ({type(e).__name__})"
    if eng is None:
        return False, f"«{mid}» no está descrito en engines.json"
    t = eng.get("tipo")
    if t == "_mal_formado":
        return False, "su descriptor está mal formado: " + "; ".join(eng.get("_problemas") or [])[:200]
    if t not in ("cli_sincrono", "api_sincrona"):
        return False, f"«{eng.get('nombre') or mid}» no sirve para un turno de texto (tipo {t or 'sin tipo'})"
    return True, ""


def cmdia_motor_vivo(mid):
    ok, why = cmdia_motor_basico(mid)
    if not ok:
        return ok, why
    try:
        return engine_status(mid)
    except Exception as e:
        return False, f"no se pudo comprobar ({type(e).__name__}: {e})"


def cmdia_motor_nombre(mid):
    try:
        raw = engine_raw(mid) if mid else None
    except Exception:
        raw = None
    return str((raw or {}).get("nombre") or mid or "sin motor")


def cmdia_motor_costo(mid):
    try:
        raw = engine_raw(mid) or {}
    except Exception:
        raw = {}
    c = (raw.get("salida") or {}).get("costo")
    if isinstance(c, (int, float)) and c == 0:
        return "gratis, en tu PC"
    return "lo que cobre ese motor (sesión o clave suya)"


def cmdia_armar_prompt(cmd, texto, args):
    """El prompt que recibe el motor: {seleccion} -> «el TEXTO de abajo» (el texto
    va al final, entre comillas triples) y cada {argumento} -> su valor."""
    vals = {_norm(k): v for k, v in (args or {}).items()}
    p = _CMDIA_ARG_RE.sub(lambda m: vals.get(_norm(m.group(1).strip()), m.group(0)), cmd["prompt"])
    usa = cmdia_usa_seleccion(p)
    p = _CMDIA_SEL_RE.sub("el TEXTO de abajo", p)
    crea = next((e for k, _p, e, _t in CMDIA_CREATIVIDAD if k == cmd.get("creatividad")), "")
    p += ("\n\nResponde solo con el resultado, sin introducción ni comentarios."
          + (f" Creatividad pedida: {cmd.get('creatividad')} ({crea[:1].lower() + crea[1:]})" if crea else ""))
    if usa:
        p += f'\n\nTEXTO:\n"""\n{texto}\n"""'
    return p


def _cmdia_llamar(mid, prompt, temperatura, timeout_min=5):
    """Un turno de texto con el motor, leyendo SOLO su descriptor (como el de la
    memoria). La creatividad va como temperatura en los motores HTTP; en los CLI
    (que no la exponen) solo va escrita en el prompt. -> dict."""
    eng = get_engine(mid) or {}
    out = {"motor": mid, "ok": False, "texto": "", "error": None, "segundos": None, "cost_usd": None,
           "temperatura": None}
    t0 = time.time()
    _CMDIA["llamadas"] += 1
    try:
        if eng.get("tipo") == "cli_sincrono":
            rt = {"id": f"comando-ia-{int(t0)}", "cwd": str(INBOX), "timeout_min": timeout_min,
                  "modelo": None, "session_id": None, "prompt": "", "allowed_tools": None,
                  "permission_mode": None}
            r = _base_result(rt, mid)
            _run_cli_engine(rt, mid, eng, r, prompt, abilities=False, rol="revision")
            out.update(ok=r.get("status") == "ok", texto=r.get("result") or "", error=r.get("error"),
                       cost_usd=r.get("cost_usd"))
        elif eng.get("tipo") == "api_sincrona":
            model = _local_model(eng, {}) or None
            ok, why = (ensure_llama_server(eng, model) if eng.get("servidor")
                       else engine_status_rt(eng, autostart=True))
            if not ok:
                raise LocalCallError(f"no disponible: {why}")
            body = _fill(eng.get("cuerpo") or {}, {"mensajes": [{"role": "user", "content": prompt}],
                                                    "modelo": model, "prompt": prompt})
            if (eng.get("modelo") or {}).get("campo"):
                body[eng["modelo"]["campo"]] = model
            if isinstance(body, dict):
                if "/api/" in str(eng.get("url") or ""):  # Ollama nativo: options.temperature
                    body["options"] = dict(body.get("options") or {}, temperature=temperatura)
                else:  # compatible con OpenAI (llama-server)
                    body["temperature"] = temperatura
                out["temperatura"] = temperatura
            data = _http_local("POST", eng["url"], body, timeout=timeout_min * 60)
            txt = _get_path(data, (eng.get("salida") or {}).get("texto"))
            out.update(ok=isinstance(txt, str) and bool(txt.strip()), texto=txt or "", cost_usd=0.0,
                       error=None if txt else "respondió sin texto")
        else:
            out["error"] = f"el motor {mid} ({eng.get('tipo')}) no sirve para un turno de texto"
    except Exception as e:
        out["error"] = f"{type(e).__name__}: {e}"[:300]
    out["segundos"] = round(time.time() - t0, 2)
    return out


def cmdia_ejecutar(cmd, texto="", args=None):
    """Corre el comando (en un hilo de fondo: puede tardar). Nunca inventa: sin
    texto, sin un dato o sin motor, no llama a nada y lo dice. -> dict con ok,
    texto, error, tipo_error (sin_seleccion | falta_dato | motor_no_disponible |
    motor) y segundos."""
    args = dict(args or {})
    if not cmd.get("modelo") or cmd.get("modelo") in ("superficie", "por defecto"):
        # sin motor propio: el de la superficie «Comandos de IA guardados» (o el principal)
        cmd = dict(cmd, modelo=_motor_de_modelo(superficie_modelo("comando")) or default_motor())
    base = {"ok": False, "texto": "", "error": None, "tipo_error": None, "segundos": None,
            "motor": cmd.get("modelo")}
    if cmdia_usa_seleccion(cmd["prompt"]) and not (texto or "").strip():
        return dict(base, tipo_error="sin_seleccion", error=(
            "Este comando trabaja sobre el texto seleccionado y no hay ninguno. Selecciónalo en Bridge antes "
            "de abrir la paleta, pégalo en «Texto seleccionado» o usa «Pegar lo copiado». No se ejecutó nada."))
    for n in cmdia_argumentos(cmd["prompt"]):
        if not str(args.get(n) or "").strip():
            return dict(base, tipo_error="falta_dato", dato=n, error=(
                f"Falta «{cmdia_dato_txt(n)}»: escríbelo antes de ejecutar. No se ejecutó nada."))
    ok, why = cmdia_motor_vivo(cmd.get("modelo"))
    if not ok:
        log(f"comandos-ia: «{cmd['titulo']}»: motor no disponible ({why}); no se ejecuta")
        return dict(base, tipo_error="motor_no_disponible",
                    error=f"Motor no disponible: {why}. No se ejecutó: no hay resultado.")
    temp = next((t for k, _p, _e, t in CMDIA_CREATIVIDAD if k == cmd.get("creatividad")), 0.7)
    prompt = cmdia_armar_prompt(cmd, texto, args)
    r = _cmdia_llamar(cmd["modelo"], prompt, temp)
    log(f"comandos-ia: «{cmd['titulo']}» con {cmd['modelo']} ({cmd['creatividad']}): "
        + (f"{len(r['texto'])} letras en {r['segundos']} s" if r["ok"] else f"falló ({r['error']})"))
    if not r["ok"]:
        return dict(base, tipo_error="motor", segundos=r["segundos"],
                    error=f"El motor no dio un resultado: {r['error'] or 'respondió vacío'}. No hay resultado.")
    txt = r["texto"].strip()
    if len(txt) >= 6 and txt.startswith('"""') and txt.endswith('"""'):  # devolvio las marcas del TEXTO
        txt = txt[3:-3].strip()
    return dict(base, ok=True, texto=txt, segundos=r["segundos"], cost_usd=r["cost_usd"],
                temperatura=r.get("temperatura"))


# ---- el texto seleccionado (en Bridge, pegado o copiado)
def cmdia_captura_seleccion():
    """Lo seleccionado AHORA en un campo de texto de Bridge -> {w, a, b, texto,
    fuente} o None. Se mira al abrir la paleta, antes de que se lleve el foco."""
    try:
        w = _root.focus_get() if _root is not None else None
    except Exception:
        w = None
    if w is None:
        return None
    try:
        if isinstance(w, tk.Text):
            a, b = w.index("sel.first"), w.index("sel.last")
            t = w.get(a, b)
        elif isinstance(w, (tk.Entry, ttk.Entry)):
            if not w.selection_present():
                return None
            a, b = w.index("sel.first"), w.index("sel.last")
            t = w.get()[int(a):int(b)]
        else:
            return None
    except (tk.TclError, ValueError):
        return None
    if not t.strip():
        return None
    return {"w": w, "a": a, "b": b, "texto": t, "fuente": "Lo que tenías seleccionado en Bridge."}


def _cmdia_portapapeles():
    try:
        t = _root.clipboard_get() if _root is not None else ""
    except Exception:
        t = ""
    return t if isinstance(t, str) and t.strip() else ""


def cmdia_lanzar(cid, desde="paleta"):
    """Abre la ventana del comando con el texto seleccionado. desde: paleta (lo
    seleccionado al abrir la paleta), atajo (dentro de Bridge), global (otra
    aplicacion: lo que tengas copiado) o copiado."""
    cmdia_cargar()
    cmd = cmdia_buscar(cid)
    if cmd is None:
        log(f"comandos-ia: el comando «{cid}» ya no existe")
        try:
            messagebox.showwarning("Comandos de IA", f"El comando «{cid}» ya no existe (¿lo borraste o se dañó "
                                   "comandos-ia.json?).")
        except Exception:
            pass
        return None
    origen = None
    if desde == "paleta":
        origen = _palette.pop("origen", None)
    elif desde == "atajo":
        origen = cmdia_captura_seleccion()
    if origen is None and desde in ("global", "copiado"):
        clip = _cmdia_portapapeles()
        if clip:
            origen = {"portapapeles": True, "texto": clip,
                      "fuente": "Lo que tenías copiado (Ctrl + C). Cámbialo aquí si no es."}
    log(f"comandos-ia: abres «{cmd['titulo']}» (desde {desde}; "
        + (f"{len(origen['texto'])} letras de texto)" if origen else "sin texto)"))
    return cmdia_ventana(cmd, origen)


# ---- superficies nuevas: CustomTkinter con la clasica de respaldo (el kit)
def _cmdia_kit(top):
    """El kit de la regla del piloto: CTk si se puede; si no, el clasico."""
    if _ctk_wanted():
        try:
            setup = not (_widgets.get("gv_ctk") or _MOT.get("ctk") or _widgets.get("ajustes_ctk"))
            return _KitCtk(top, global_setup=setup)
        except Exception as e:
            log(f"comandos-ia: sin CustomTkinter ({type(e).__name__}: {e}); se usa la versión clásica")
    return _KitTk(top)


def _cmdia_textbox(kit, parent, alto=5):
    if isinstance(kit, _KitCtk):
        return kit.ctk.CTkTextbox(parent, height=alto * 22, corner_radius=8, border_width=1,
                                  border_color=THEME["line"], fg_color=THEME["field"],
                                  text_color=THEME["text"], font=kit.F(13), wrap="word")
    return tk.Text(parent, height=alto, wrap="word", font=(FONT, 10), bg=THEME["field"], fg=THEME["text"],
                   relief="flat", highlightthickness=1, highlightbackground=THEME["line"],
                   highlightcolor=THEME["blue"], insertbackground=THEME["text"], padx=S(6), pady=S(4))


def _cmdia_tb_get(tb):
    return tb.get("1.0", "end-1c")


def _cmdia_tb_set(tb, texto):
    tb.delete("1.0", "end")
    tb.insert("1.0", texto or "")


def _cmdia_ventana_base(titulo, ancho=600):
    top = tk.Toplevel(_root)
    top.withdraw()
    top.title(titulo)
    top.configure(bg=THEME["bg"])
    top.attributes("-topmost", True)
    try:
        if ICO.is_file():
            top.iconbitmap(str(ICO))
    except Exception:
        pass
    holder = tk.Frame(top, bg=THEME["bg"])
    holder.pack(fill="both", expand=True)
    canvas = tk.Canvas(holder, bg=THEME["bg"], highlightthickness=0, bd=0, width=S(ancho))
    sb = ttk.Scrollbar(holder, orient="vertical", command=canvas.yview)
    inner = tk.Frame(canvas, bg=THEME["bg"])
    wid = canvas.create_window((0, 0), window=inner, anchor="nw")
    inner.bind("<Configure>", lambda _e: canvas.configure(scrollregion=canvas.bbox("all")))
    canvas.bind("<Configure>", lambda e: canvas.itemconfig(wid, width=e.width))
    canvas.configure(yscrollcommand=sb.set)
    canvas.pack(side="left", fill="both", expand=True)
    sb.pack(side="right", fill="y")
    top._canvas, top._inner = canvas, inner
    return top, inner


def _cmdia_mostrar(top, ancho=600):
    """Tamano a la medida (sin pasar de la pantalla) y delante."""
    top.update_idletasks()
    inner, canvas = top._inner, top._canvas
    h = min(inner.winfo_reqheight() + S(4), top.winfo_screenheight() - S(150))
    sbw = max((ch.winfo_reqwidth() for ch in canvas.master.winfo_children() if ch is not canvas), default=0)
    w = max(S(ancho), inner.winfo_reqwidth()) + sbw  # + la barra de desplazamiento, que no se tapa
    try:
        x = _root.winfo_rootx() + max(0, (_root.winfo_width() - w) // 2) if _root.winfo_viewable() else \
            (top.winfo_screenwidth() - w) // 2
    except Exception:
        x = S(80)
    top.geometry(f"{w}x{h}+{max(0, x)}+{S(30)}")
    canvas.configure(height=h)
    top.deiconify()
    top.lift()
    try:
        top.focus_force()
    except Exception:
        pass

    def _rueda(e):
        canvas.yview_scroll(-1 if e.delta > 0 else 1, "units")
    top.bind("<MouseWheel>", _rueda)


def _cmdia_guardrail_txt():
    lv = guardrail_level()
    return lv, next((l for k, l, _x in GUARDRAIL_LEVELS if k == lv), lv)


def cmdia_ventana(cmd, origen=None):
    """La ventana del comando: texto seleccionado, los datos que pide, Ejecutar y
    el resultado segun su salida. -> el estado (dict) para las pruebas."""
    if _root is None:
        return None
    viejo = _CMDIA.get("ventana")
    try:
        if viejo and viejo["top"].winfo_exists():
            viejo["top"].destroy()
    except Exception:
        pass
    t0 = time.perf_counter()
    top, inner = _cmdia_ventana_base(f"Comando de IA: {cmd['titulo']}")
    kit = _cmdia_kit(inner)
    try:
        st = _cmdia_ventana_con(kit, top, inner, cmd, origen)
    except Exception as e:
        if isinstance(kit, _KitTk) and not isinstance(kit, _KitCtk):
            raise
        log(f"comandos-ia: la ventana falló con CustomTkinter ({type(e).__name__}: {e}); se usa la clásica")
        for ch in inner.winfo_children():
            ch.destroy()
        kit = _KitTk(inner)
        st = _cmdia_ventana_con(kit, top, inner, cmd, origen)
    st["kit"] = kit.nombre
    _CMDIA["ventana"] = st
    _cmdia_mostrar(top)
    log(f"comandos-ia: ventana «{cmd['titulo']}» ({kit.nombre}, {(time.perf_counter() - t0) * 1000:.0f} ms)")
    return st


def _cmdia_ventana_con(kit, top, inner, cmd, origen):
    usa_sel = cmdia_usa_seleccion(cmd["prompt"])
    datos = cmdia_argumentos(cmd["prompt"])
    salida_txt = dict(CMDIA_SALIDAS).get(cmd["salida"], cmd["salida"]).lower()
    crea_txt = next((p for k, p, _e, _t in CMDIA_CREATIVIDAD if k == cmd["creatividad"]), cmd["creatividad"])
    st = {"top": top, "cmd": cmd, "origen": origen, "resultado": None, "deshacer": None, "confirm": None,
          "corriendo": False}
    card = kit.card(inner)
    card.pack(fill="both", expand=True, padx=12, pady=12)
    kit.title(card, f"{cmdia_icono(cmd['icono'])}  {cmd['titulo']}").pack(anchor="w", padx=18, pady=(16, 2))
    kit.label(card, f"Creatividad: {crea_txt.lower()}. Al terminar: {salida_txt}."
              + (" Comando integrado (para cambiarlo, duplícalo)." if cmd.get("integrado") else ""),
              muted=True, wrap=540).pack(anchor="w", fill="x", padx=18)
    ok_b, why_b = cmdia_motor_basico(cmd["modelo"])
    st["motor_lbl"] = kit.label(card, "", wrap=540)
    st["motor_lbl"].pack(anchor="w", fill="x", padx=18, pady=(6, 0))
    nombre = f"{cmdia_motor_nombre(cmd['modelo'])} ({cmd['modelo']})"
    if ok_b:
        kit.set_label(st["motor_lbl"], f"Motor: {nombre}. Comprobando si está disponible…", color="blue")
    else:
        kit.set_label(st["motor_lbl"], f"Motor no disponible: {why_b}. Este comando no se puede ejecutar "
                                       "hasta que ese motor exista en engines.json.", color="red")
    st["tb"] = None
    if usa_sel:
        kit.label(card, "Texto seleccionado", bold=True).pack(anchor="w", padx=18, pady=(14, 0))
        st["fuente"] = kit.label(card, (origen or {}).get("fuente") or
                                 "No había nada seleccionado: pega aquí el texto o usa «Pegar lo copiado».",
                                 muted=True, wrap=540)
        st["fuente"].pack(anchor="w", fill="x", padx=18)
        tb = _cmdia_textbox(kit, card, 6)
        tb.pack(fill="x", padx=18, pady=(6, 0))
        _cmdia_tb_set(tb, (origen or {}).get("texto") or "")
        st["tb"] = tb
        r = kit.frame(card)
        r.pack(anchor="w", padx=18, pady=(6, 0))

        def _pegar():
            clip = _cmdia_portapapeles()
            if not clip:
                kit.set_label(st["estado"], "No hay texto copiado (el portapapeles está vacío o no es texto).",
                              color="orange_text")
                return
            _cmdia_tb_set(tb, clip)
            st["origen"] = {"portapapeles": True, "texto": clip, "fuente": "Lo que tenías copiado (Ctrl + C)."}
            kit.set_label(st["fuente"], "Lo que tenías copiado (Ctrl + C).")
        kit.button(r, "Pegar lo copiado", _pegar).pack(side="left")
    st["datos"] = {}
    for n in datos:
        kit.label(card, cmdia_dato_txt(n), bold=True).pack(anchor="w", padx=18, pady=(12, 0))
        kit.label(card, f"El comando lo pide antes de correr (en el prompt: {{argumento nombre=\"{n}\"}}).",
                  muted=True, wrap=540).pack(anchor="w", fill="x", padx=18)
        e = kit.entry(card, width=40)
        e.pack(anchor="w", padx=18, pady=(6, 0))
        st["datos"][n] = e
    brow = kit.frame(card)
    brow.pack(fill="x", padx=18, pady=(16, 4))
    st["btn"] = kit.button(brow, "Ejecutar", lambda: _cmdia_correr(kit, st), accent=True)
    st["btn"].pack(side="left")
    kit.button(brow, "Cerrar", top.destroy).pack(side="left", padx=(8, 0))
    if not ok_b:
        kit.set_enabled(st["btn"], False)
    st["estado"] = kit.label(card, "", wrap=540)
    st["estado"].pack(anchor="w", fill="x", padx=18, pady=(4, 0))
    # Resultado: aparece al terminar (se revisa aqui antes de usarlo).
    res = kit.frame(card)
    st["res_frame"] = res
    kit.label(res, "Resultado (revísalo antes de usarlo; puedes retocarlo aquí)", bold=True).pack(anchor="w")
    st["res_tb"] = _cmdia_textbox(kit, res, 8)
    st["res_tb"].pack(fill="x", pady=(6, 0))
    rr = kit.frame(res)
    rr.pack(anchor="w", pady=(8, 0))

    def _copiar():
        t = _cmdia_tb_get(st["res_tb"])
        _root.clipboard_clear()
        _root.clipboard_append(t)
        kit.set_label(st["estado"], f"Copiado ({len(t)} letras). Pégalo con Ctrl + V donde quieras.",
                      color="green_text")
        log(f"comandos-ia: «{cmd['titulo']}»: resultado copiado ({len(t)} letras)")
    kit.button(rr, "Copiar", _copiar).pack(side="left")
    if usa_sel:
        st["btn_reemp"] = kit.button(rr, "Reemplazar el texto", lambda: cmdia_reemplazar(kit, st))
        st["btn_reemp"].pack(side="left", padx=(8, 0))
        st["btn_desh"] = kit.button(rr, "Deshacer el reemplazo", lambda: _cmdia_deshacer(kit, st))
    top.bind("<Escape>", lambda _e: top.destroy())
    top.bind("<Control-Return>", lambda _e: _cmdia_correr(kit, st))
    st["seguir"] = lambda: _cmdia_correr(kit, st)
    if ok_b:
        def _bg():
            ok, why = cmdia_motor_vivo(cmd["modelo"])
            st["motor_vivo"] = (ok, why)
        threading.Thread(target=_bg, daemon=True).start()

        def _pinta_vivo(n=0):
            v = st.get("motor_vivo")
            if v is None and n < 200:
                top.after(100, lambda: _pinta_vivo(n + 1))
                return
            try:
                if v and v[0]:
                    kit.set_label(st["motor_lbl"], f"Motor: {nombre}, disponible ({v[1]}). Costo: "
                                                   f"{cmdia_motor_costo(cmd['modelo'])}.", color="green_text")
                else:
                    kit.set_label(st["motor_lbl"], f"Motor no disponible ahora: {(v or (0, 'sin respuesta'))[1]}. "
                                                   "Si lo ejecutas, se vuelve a comprobar; sin motor no hay "
                                                   "resultado.", color="red")
            except Exception:
                pass
        top.after(100, _pinta_vivo)
    # Foco: el primer dato que falte, o Ejecutar.
    primero = next(iter(st["datos"].values()), None)
    try:
        (primero or st["btn"]).focus_set()
    except Exception:
        pass
    return st


def _cmdia_correr(kit, st):
    if st["corriendo"]:
        return
    cmd = st["cmd"]
    texto = _cmdia_tb_get(st["tb"]) if st["tb"] is not None else ""
    args = {n: e.get() for n, e in st["datos"].items()}
    # Lo que no necesita al motor se comprueba aqui mismo (sin hilo): no se llama a nada.
    if cmdia_usa_seleccion(cmd["prompt"]) and not texto.strip():
        r = cmdia_ejecutar(cmd, texto, args)
        kit.set_label(st["estado"], r["error"], color="red")
        st["ultimo"] = r
        return
    falta = [n for n in cmdia_argumentos(cmd["prompt"]) if not str(args.get(n) or "").strip()]
    if falta:
        r = cmdia_ejecutar(cmd, texto, args)
        kit.set_label(st["estado"], r["error"], color="red")
        st["ultimo"] = r
        try:
            st["datos"][falta[0]].focus_set()
        except Exception:
            pass
        return
    st["corriendo"] = True
    st["texto_usado"] = texto
    kit.set_enabled(st["btn"], False)
    kit.set_label(st["estado"], f"Ejecutando con {cmdia_motor_nombre(cmd['modelo'])}… (puede tardar un poco)",
                  color="blue")
    caja = {}
    threading.Thread(target=lambda: caja.setdefault("r", cmdia_ejecutar(cmd, texto, args)), daemon=True).start()

    def _espera():
        if "r" not in caja:
            try:
                st["top"].after(150, _espera)
            except Exception:
                pass
            return
        st["corriendo"] = False
        try:
            if not st["top"].winfo_exists():
                return
        except Exception:
            return
        _cmdia_resultado(kit, st, caja["r"])
    st["top"].after(150, _espera)


def _cmdia_resultado(kit, st, r):
    cmd = st["cmd"]
    st["ultimo"] = r
    kit.set_enabled(st["btn"], True)
    if not r["ok"]:
        st["resultado"] = None
        st["res_frame"].pack_forget()
        kit.set_label(st["estado"], r["error"], color="red")
        if r["tipo_error"] == "motor_no_disponible":
            kit.set_label(st["motor_lbl"], r["error"].split(". No se ejecutó")[0] + ".", color="red")
        return
    st["resultado"] = r["texto"]
    _cmdia_tb_set(st["res_tb"], r["texto"])
    st["res_frame"].pack(fill="x", padx=18, pady=(8, 16))
    if st.get("btn_desh") is not None:
        st["btn_desh"].pack_forget()
    kit.set_label(st["estado"], f"Listo en {r['segundos']} s con {cmdia_motor_nombre(cmd['modelo'])}. "
                  + ("Revísalo abajo antes de usarlo." if cmd["salida"] == "mostrar"
                     else "Ahora se sustituye el texto seleccionado (según tus permisos)."), color="green_text")
    _cmdia_mostrar(st["top"])
    if cmd["salida"] == "reemplazar":
        cmdia_reemplazar(kit, st)


def cmdia_reemplazar(kit, st):
    """Sustituir el texto seleccionado es una escritura: pasa por el guardrail.
    «Preguntarme siempre»: confirmacion con el texto completo. Los otros niveles:
    se hace y se dice (con «Deshacer»). Nunca en silencio."""
    nuevo = _cmdia_tb_get(st["res_tb"]) if st.get("res_tb") is not None else (st.get("resultado") or "")
    if not nuevo.strip():
        kit.set_label(st["estado"], "No hay resultado con el que reemplazar.", color="orange_text")
        return
    original = _cmdia_tb_get(st["tb"]) if st["tb"] is not None else ""
    nivel, nivel_txt = _cmdia_guardrail_txt()
    if nivel == "siempre":
        kit.set_label(st["estado"], f"Permisos: {nivel_txt}. Esperando tu sí para reemplazar el texto…",
                      color="orange_text")
        st["confirm"] = cmdia_confirmar(st, original, nuevo, nivel_txt,
                                        lambda: _cmdia_hacer_reemplazo(kit, st, original, nuevo, True),
                                        lambda: kit.set_label(st["estado"], "No se reemplazó nada (lo "
                                                              "cancelaste). El resultado sigue aquí para "
                                                              "revisarlo o copiarlo.", color="muted"))
        return
    _cmdia_hacer_reemplazo(kit, st, original, nuevo, False, nivel_txt)


def _cmdia_hacer_reemplazo(kit, st, original, nuevo, confirmado, nivel_txt=None, deshacer=False):
    st["confirm"] = None
    o = st.get("origen") or {}
    donde = "en esta ventana"
    w = o.get("w")
    if w is not None and o.get("texto") == original:
        try:
            if not w.winfo_exists():
                raise tk.TclError("el campo ya no existe")
            if isinstance(w, tk.Text):
                if w.get(o["a"], o["b"]) != original:
                    pos = w.search(original, "1.0", "end", exact=True)
                    if not pos:
                        raise tk.TclError("el texto de origen cambió")
                    o["a"], o["b"] = pos, f"{pos}+{len(original)}c"
                w.delete(o["a"], o["b"])
                w.insert(o["a"], nuevo)
                o["b"] = f"{o['a']}+{len(nuevo)}c"
            else:
                full = w.get()
                a = int(o["a"])
                if full[a:a + len(original)] != original:
                    a = full.find(original)
                    if a < 0:
                        raise tk.TclError("el texto de origen cambió")
                w.delete(a, a + len(original))
                w.insert(a, nuevo)
                o["a"], o["b"] = a, a + len(nuevo)
            donde = "en el campo de Bridge donde lo seleccionaste"
        except (tk.TclError, ValueError) as e:
            kit.set_label(st["estado"], f"No reemplacé nada: {e} desde que lo seleccionaste (no sustituyo a "
                                        "ciegas). Usa «Copiar» y pégalo tú.", color="red")
            log(f"comandos-ia: «{st['cmd']['titulo']}»: reemplazo NO hecho ({e})")
            return
    elif o.get("portapapeles") and o.get("texto") == original:
        _root.clipboard_clear()
        _root.clipboard_append(nuevo)
        donde = "en el portapapeles (pégalo con Ctrl + V donde estaba)"
    if st["tb"] is not None:
        _cmdia_tb_set(st["tb"], nuevo)
    o["texto"] = nuevo
    st["origen"] = o
    st["deshacer"] = (original, nuevo)
    st["reemplazado"] = {"confirmado": confirmado, "donde": donde, "antes": original, "despues": nuevo}
    if st.get("btn_desh") is not None:
        st["btn_desh"].pack(side="left", padx=(8, 0))
    if confirmado:
        msg, col = f"Reemplazado {donde}, con tu confirmación.", "green_text"
    else:
        msg, col = (f"Reemplazado {donde} sin preguntar (permisos: {nivel_txt}). «Deshacer el reemplazo» lo "
                    "deja como estaba.", "orange_text")
    kit.set_label(st["estado"], msg, color=col)
    if not deshacer:
        log(f"comandos-ia: «{st['cmd']['titulo']}»: reemplazo {len(original)} -> {len(nuevo)} letras {donde} "
            + ("(confirmado por ti)" if confirmado else f"(sin preguntar: {nivel_txt})"))


def _cmdia_deshacer(kit, st):
    d = st.get("deshacer")
    if not d:
        return
    antes, despues = d
    st["deshacer"] = None
    # Deshacer es volver a escribir: el mismo camino, sin pedir permiso (devuelve lo tuyo).
    _cmdia_hacer_reemplazo(kit, st, despues, antes, True, deshacer=True)
    st["deshacer"] = None
    if st.get("btn_desh") is not None:
        st["btn_desh"].pack_forget()
    kit.set_label(st["estado"], "Deshecho: el texto volvió a como estaba.", color="muted")
    log(f"comandos-ia: «{st['cmd']['titulo']}»: reemplazo deshecho")


def cmdia_confirmar(st, original, nuevo, nivel_txt, si, no):
    """Confirmacion del guardrail con el texto COMPLETO (no bloquea el hilo de
    la ventana: devuelve el estado y llama a si() o a no())."""
    top = tk.Toplevel(st["top"])
    top.withdraw()
    top.title("¿Reemplazar el texto?")
    top.configure(bg=THEME["bg"])
    top.attributes("-topmost", True)
    top.transient(st["top"])
    kit = _cmdia_kit(top)
    c = {"top": top, "hecho": False}

    def _fin(fn):
        if c["hecho"]:
            return
        c["hecho"] = True
        try:
            top.grab_release()
            top.destroy()
        except Exception:
            pass
        fn()

    def _con(k):
        card = k.card(top)
        card.pack(fill="both", expand=True, padx=12, pady=12)
        k.title(card, "¿Reemplazar el texto seleccionado?").pack(anchor="w", padx=18, pady=(16, 2))
        k.label(card, f"Permisos: {nivel_txt}. Reemplazar es una escritura: nada cambia hasta que digas que sí.",
                muted=True, wrap=520).pack(anchor="w", fill="x", padx=18)
        k.label(card, f"Texto nuevo, completo ({len(nuevo)} letras)", bold=True).pack(anchor="w", padx=18,
                                                                                     pady=(12, 0))
        t1 = _cmdia_textbox(k, card, 7)
        t1.pack(fill="x", padx=18, pady=(4, 0))
        _cmdia_tb_set(t1, nuevo)
        t1.configure(state="disabled")
        k.label(card, f"Se sustituye este texto ({len(original)} letras)", bold=True).pack(anchor="w", padx=18,
                                                                                          pady=(12, 0))
        t2 = _cmdia_textbox(k, card, 4)
        t2.pack(fill="x", padx=18, pady=(4, 0))
        _cmdia_tb_set(t2, original)
        t2.configure(state="disabled")
        brow = k.frame(card)
        brow.pack(anchor="e", padx=18, pady=(14, 16))
        k.button(brow, "Cancelar", lambda: _fin(no)).pack(side="right")
        c["si_btn"] = k.button(brow, "Reemplazar", lambda: _fin(si), accent=True)
        c["si_btn"].pack(side="right", padx=(0, 8))
        c["texto_nuevo"] = _cmdia_tb_get(t1)
    try:
        _con(kit)
    except Exception as e:
        if not isinstance(kit, _KitCtk):
            raise
        log(f"comandos-ia: confirmación sin CustomTkinter ({type(e).__name__}: {e}); se usa la clásica")
        for ch in top.winfo_children():
            ch.destroy()
        kit = _KitTk(top)
        _con(kit)
    c["kit"] = kit.nombre
    c["si"], c["no"] = (lambda: _fin(si)), (lambda: _fin(no))
    top.protocol("WM_DELETE_WINDOW", lambda: _fin(no))
    top.bind("<Escape>", lambda _e: _fin(no))
    top.update_idletasks()
    x = st["top"].winfo_rootx() + S(30)
    y = st["top"].winfo_rooty() + S(30)
    top.geometry(f"+{max(0, x)}+{max(0, y)}")
    top.deiconify()
    top.lift()
    try:
        top.grab_set()
        top.focus_force()
    except Exception:
        pass
    log(f"comandos-ia: «{st['cmd']['titulo']}»: pido confirmación para reemplazar ({nivel_txt})")
    return c


# ---- formulario «Nuevo comando de IA» (5 campos + salida + atajo)
def _cmdia_motores_opciones(actual=None):
    try:
        ids = engine_ids()
    except Exception:
        ids = []
    ops = [f"{cmdia_motor_nombre(m)} ({m})" for m in ids]
    if actual and actual not in ids:
        ops.append(actual)
    return ops


def _cmdia_motor_de_opcion(txt):
    t = (txt or "").strip()
    m = re.search(r"\(([A-Za-z0-9_.:-]+)\)\s*$", t)
    return m.group(1) if m else t


def cmdia_formulario(cid=None, duplicar=None):
    """Nuevo comando (cid None), editar uno tuyo (cid) o duplicar uno (integrado
    o tuyo) para adaptarlo. -> el estado (dict) para las pruebas."""
    if _root is None:
        return None
    cmdia_cargar()
    base, modo = None, "nuevo"
    if cid:
        base = cmdia_buscar(cid)
        if base is None:
            messagebox.showwarning("Comandos de IA", f"El comando «{cid}» ya no existe.")
            return None
        if base.get("integrado"):
            duplicar, base, cid = cid, None, None
        else:
            modo = "editar"
    if duplicar:
        b = cmdia_buscar(duplicar)
        if b is not None:
            base = dict(b, titulo=(b["titulo"] + " (mi versión)")[:60], basado_en=b["id"])
            base.pop("id", None)
            modo = "duplicar"
    viejo = _CMDIA.get("form")
    try:
        if viejo and viejo["top"].winfo_exists():
            viejo["top"].destroy()
    except Exception:
        pass
    t0 = time.perf_counter()
    titulo = {"nuevo": "Nuevo comando de IA", "editar": "Editar comando de IA",
              "duplicar": "Duplicar comando de IA"}[modo]
    top, inner = _cmdia_ventana_base(titulo, ancho=620)
    kit = _cmdia_kit(inner)
    try:
        st = _cmdia_form_con(kit, top, inner, titulo, base, cid)
    except Exception as e:
        if not isinstance(kit, _KitCtk):
            raise
        log(f"comandos-ia: el formulario falló con CustomTkinter ({type(e).__name__}: {e}); se usa el clásico")
        for ch in inner.winfo_children():
            ch.destroy()
        kit = _KitTk(inner)
        st = _cmdia_form_con(kit, top, inner, titulo, base, cid)
    st["kit"], st["modo"] = kit.nombre, modo
    st["ms"] = round((time.perf_counter() - t0) * 1000)
    _CMDIA["form"] = st
    _cmdia_mostrar(top, ancho=620)
    log(f"comandos-ia: formulario «{titulo}» ({kit.nombre}, {st['ms']} ms)")
    return st


def _cmdia_form_con(kit, top, inner, titulo, base, cid):
    base = base or {}
    st = {"top": top, "cid": cid, "basado_en": base.get("basado_en")}
    card = kit.card(inner)
    card.pack(fill="both", expand=True, padx=12, pady=12)
    st["titulo_lbl"] = kit.title(card, titulo)
    st["titulo_lbl"].pack(anchor="w", padx=18, pady=(16, 2))
    kit.label(card, "Un comando guarda un prompt para no reescribirlo en cada tarea. Sale en la paleta "
                    "(Ctrl+K) y trabaja sobre el texto que tengas seleccionado.", muted=True,
              wrap=560).pack(anchor="w", fill="x", padx=18)
    if _CMDIA.get("error_archivo"):
        kit.label(card, _CMDIA["error_archivo"], color="red", wrap=560).pack(anchor="w", fill="x", padx=18,
                                                                            pady=(8, 0))

    def campo(t, expl):
        kit.label(card, t, bold=True).pack(anchor="w", padx=18, pady=(14, 0))
        if expl:
            kit.label(card, expl, muted=True, wrap=560).pack(anchor="w", fill="x", padx=18)

    # 1. Titulo
    campo("Título", "El nombre con el que lo buscas en la paleta (máximo 60 letras).")
    st["titulo"] = kit.entry(card, width=48)
    st["titulo"].pack(anchor="w", padx=18, pady=(6, 0))
    st["titulo"].insert(0, base.get("titulo") or "")
    # 2. Prompt
    campo("Prompt", "Lo que le pides a la IA. Escribe {seleccion} donde va el texto seleccionado y "
                    "{argumento nombre=\"idioma\"} para un dato que se te pregunta al ejecutar.")
    st["prompt"] = _cmdia_textbox(kit, card, 6)
    st["prompt"].pack(fill="x", padx=18, pady=(6, 0))
    _cmdia_tb_set(st["prompt"], base.get("prompt") or "")
    pr = kit.frame(card)
    pr.pack(anchor="w", padx=18, pady=(6, 0))

    def _ins(t):
        st["prompt"].insert("insert", t)
        st["prompt"].focus_set()
    kit.button(pr, "Añadir {seleccion}", lambda: _ins("{seleccion}")).pack(side="left")
    kit.button(pr, "Añadir un dato que se pide", lambda: _ins('{argumento nombre="dato"}')).pack(side="left",
                                                                                                padx=(8, 0))
    # 3. Icono
    campo("Icono", "Lo que se ve a la izquierda del título en la paleta.")
    ic_ops = [f"{g}  {n}" for _k, g, n in CMDIA_ICONOS]
    st["icono"] = kit.option(card, ic_ops, width=24)
    st["icono"].pack(anchor="w", padx=18, pady=(6, 0))
    ic = base.get("icono") or "texto"
    st["icono"].set(next((f"{g}  {n}" for k, g, n in CMDIA_ICONOS if k == ic), ic_ops[3]))
    # 4. Modelo
    campo("Modelo", "El motor que responde (de los descritos en Modelos → Motores). Los locales no cuestan "
                    "nada. Si el motor no existe, el comando sale como «motor no disponible».")
    actual = base.get("modelo") or CMDIA_MOTOR_INTEGRADOS
    st["modelo"] = kit.option(card, _cmdia_motores_opciones(actual), width=48, editable=True,
                              command=lambda _v: _cmdia_form_motor(kit, st))
    st["modelo"].pack(anchor="w", padx=18, pady=(6, 0))
    st["modelo"].set(f"{cmdia_motor_nombre(actual)} ({actual})" if engine_raw(actual) else actual)
    st["modelo_lbl"] = kit.label(card, "", muted=True, wrap=560)
    st["modelo_lbl"].pack(anchor="w", fill="x", padx=18, pady=(4, 0))
    st["modelo"].bind("<FocusOut>", lambda _e: _cmdia_form_motor(kit, st), add="+")  # id escrito a mano
    _cmdia_form_motor(kit, st)
    # 5. Creatividad
    campo("Creatividad", None)
    crea_ops = [(k, p) for k, p, _e, _t in CMDIA_CREATIVIDAD]
    st["crea_lbl"] = None
    st["creatividad"] = kit.segmented(card, crea_ops, lambda k: _cmdia_form_crea(kit, st, k))
    st["creatividad"].pack(anchor="w", padx=18, pady=(6, 0))
    st["crea_lbl"] = kit.label(card, "", muted=True, wrap=560)
    st["crea_lbl"].pack(anchor="w", fill="x", padx=18, pady=(4, 0))
    _kit_seg_set(kit, st["creatividad"], base.get("creatividad") or "equilibrado")
    _cmdia_form_crea(kit, st, base.get("creatividad") or "equilibrado")
    # Salida
    campo("Al terminar", "«Mostrar para revisar» abre el resultado antes de usarlo. «Reemplazar el texto» "
                         "sustituye lo seleccionado (es una escritura: pasa por tus permisos).")
    st["salida"] = kit.segmented(card, list(CMDIA_SALIDAS), lambda _k: None)
    st["salida"].pack(anchor="w", padx=18, pady=(6, 0))
    _kit_seg_set(kit, st["salida"], base.get("salida") or "mostrar")
    # Atajo propio (mecanismo de t-atajos-personalizables)
    campo("Atajo (opcional)", "Pulsa la combinación en el campo: se comprueba que no choque y funciona al "
                              "momento. «En cualquier aplicación» usa lo que tengas copiado (Ctrl + C).")
    st["atajo_frame"] = kit.frame(card)
    st["atajo_frame"].pack(fill="x", padx=18, pady=(6, 0))
    _cmdia_form_atajo(kit, st)
    # Botones
    brow = kit.frame(card)
    brow.pack(fill="x", padx=18, pady=(18, 4))
    st["guardar"] = kit.button(brow, "Guardar", lambda: cmdia_form_guardar(kit, st), accent=True)
    st["guardar"].pack(side="left")
    kit.button(brow, "Cerrar", top.destroy).pack(side="left", padx=(8, 0))
    st["borrar"] = kit.button(brow, "Borrar este comando", lambda: _cmdia_form_borrar(kit, st))
    if cid:
        st["borrar"].pack(side="right")
    st["estado"] = kit.label(card, "", wrap=560)
    st["estado"].pack(anchor="w", fill="x", padx=18, pady=(6, 16))
    top.bind("<Escape>", lambda _e: top.destroy())

    def _al_cerrar(e):
        # Cerrar el formulario a mitad de una captura suelta el gancho de teclado.
        if e.widget is top:
            for c in (st.get("campos_atajo") or {}).values():
                if c.capt:
                    try:
                        c._fin_captura()
                    except Exception:
                        pass
    top.bind("<Destroy>", _al_cerrar, add="+")
    st["titulo"].focus_set()
    return st


def _cmdia_form_motor(kit, st):
    mid = _cmdia_motor_de_opcion(st["modelo"].get())
    ok, why = cmdia_motor_basico(mid)
    if ok:
        kit.set_label(st["modelo_lbl"], f"«{mid}»: descrito en engines.json. Costo: {cmdia_motor_costo(mid)}. "
                                        "Si está encendido se comprueba al ejecutar.", color="muted")
    else:
        kit.set_label(st["modelo_lbl"], f"Motor no disponible: {why}. Se puede guardar, pero no se ejecutará "
                                        "hasta que ese motor exista.", color="red")


def _cmdia_form_crea(kit, st, k):
    if st.get("crea_lbl") is not None:
        kit.set_label(st["crea_lbl"], next((e for kk, _p, e, _t in CMDIA_CREATIVIDAD if kk == k), ""))


def _cmdia_form_atajo(kit, st):
    fr = st["atajo_frame"]
    for ch in fr.winfo_children():
        ch.destroy()
    st["campos_atajo"] = {}
    if not (callable(globals().get("atajo_guardar")) and callable(globals().get("atajo_registrar_accion"))):
        kit.label(fr, "Los atajos llegan con t-atajos-personalizables.", muted=True).pack(anchor="w")
        return
    if not st.get("cid"):
        kit.label(fr, "Guarda el comando primero: luego, aquí mismo, pulsas su combinación.",
                  muted=True, wrap=560).pack(anchor="w", fill="x")
        return
    aid = f"comando:{st['cid']}"
    if aid not in ATAJO_ACCIONES:
        _cmdia_registrar_atajos()
    if isinstance(kit, _KitCtk):
        ak = _atajos_kit_ctk(kit.ctk, None, None, kit.F, lambda lab, _p: lab.configure(wraplength=540),
                             kit.seg_bg, kit.seg_hover, kit.accent, kit.accent_hover)
    else:
        ak = _atajos_kit_tk()
    for ambito, nombre in (("global", "En cualquier aplicación"), ("paleta", "Con Bridge delante")):
        r = kit.frame(fr)
        r.pack(fill="x", pady=(0, 2))
        # El mensaje va debajo, a lo ancho (no se corta). tk.Frame y no CTkFrame:
        # vacio, un CTkFrame ocupa 200 px de alto.
        mh = tk.Frame(fr, bg=THEME["card"])
        mh.pack(fill="x", pady=(0, 8))
        der = kit.frame(r)
        der.pack(side="right", anchor="n")
        campo, foco, pintar = ak["campo"](der)
        campo.pack(side="left")
        holder = {}
        ak["boton"](der, "Quitar", lambda h=holder: h["c"].quitar()).pack(side="left", padx=(8, 0))
        izq = kit.frame(r)
        izq.pack(side="left", fill="x", expand=True)
        kit.label(izq, nombre).pack(anchor="w")
        c = _CampoAtajo(foco, aid, ambito, pintar, ak["msg"](mh))
        holder["c"] = c
        ak["al_clic"](campo, c.empezar)
        st["campos_atajo"][ambito] = c


def cmdia_form_guardar(kit, st):
    mid = _cmdia_motor_de_opcion(st["modelo"].get())
    ic_txt = st["icono"].get()
    icono = next((k for k, g, n in CMDIA_ICONOS if f"{g}  {n}" == ic_txt or k == ic_txt), "texto")
    titulo = st["titulo"].get().strip()
    d = {"id": st.get("cid") or cmdia_nuevo_id(titulo or "comando"), "titulo": titulo,
         "prompt": _cmdia_tb_get(st["prompt"]).strip(), "icono": icono, "modelo": mid,
         "creatividad": kit.seg_get(st["creatividad"]), "salida": kit.seg_get(st["salida"])}
    if st.get("basado_en"):
        d["basado_en"] = st["basado_en"]
    ok, msg, c = cmdia_guardar(d, id_anterior=st.get("cid"))
    if not ok:
        kit.set_label(st["estado"], "No se guardó: " + msg, color="red")
        return False
    nuevo = not st.get("cid")
    st["cid"] = c["id"]
    okm, why = cmdia_motor_basico(c["modelo"])
    extra = "" if okm else f" Ojo: motor no disponible ({why}); sale así marcado en la paleta."
    kit.set_label(st["estado"], msg + extra, color="green_text" if okm else "orange_text")
    if nuevo:
        kit.set_label(st["titulo_lbl"], "Editar comando de IA")
        st["top"].title("Editar comando de IA")
        st["borrar"].pack(side="right")
        _cmdia_form_atajo(kit, st)
        _cmdia_mostrar(st["top"], ancho=620)
    return True


def _cmdia_form_borrar(kit, st):
    cid = st.get("cid")
    c = cmdia_buscar(cid) if cid else None
    if c is None:
        return
    if not messagebox.askyesno("Borrar el comando", f"¿Borrar el comando «{c['titulo']}»?\n\nSe quita de "
                               f"{CMDIA_FILE.name} y de la paleta. Los demás comandos no se tocan.",
                               icon="warning", default="no", parent=st["top"]):
        kit.set_label(st["estado"], "No se borró nada.", color="muted")
        return
    ok, msg = cmdia_borrar(cid)
    if ok:
        st["top"].destroy()
    else:
        kit.set_label(st["estado"], "No se borró: " + msg, color="red")


# ---- atajos de los comandos (t-atajos-personalizables)
def _cmdia_fn_atajo(cid):
    def fn(ambito="paleta"):
        cmdia_lanzar(cid, "global" if ambito == "global" else "atajo")
    return fn


def _cmdia_registrar_atajos():
    if not callable(globals().get("atajo_registrar_accion")):
        return
    vivos = set()
    for c in cmdia_todos():
        aid = f"comando:{c['id']}"
        vivos.add(aid)
        a = ATAJO_ACCIONES.get(aid)
        if a is None or a.get("nombre") != c["titulo"]:
            atajo_registrar_accion(aid, c["titulo"], _cmdia_fn_atajo(c["id"]),
                                   "Comando de IA" + (" integrado" if c.get("integrado") else "")
                                   + ": abre su ventana con el texto seleccionado.",
                                   ambitos=("paleta", "global"), grupo="comando")
    for aid in list(_CMDIA["atajos"] - vivos):
        _cmdia_quitar_atajo(aid.split(":", 1)[1])
    _CMDIA["atajos"] = vivos


def _cmdia_quitar_atajo(cid):
    aid = f"comando:{cid}"
    if aid in ATAJO_ACCIONES:
        try:
            atajo_quitar_accion(aid)
        except Exception as e:
            log(f"comandos-ia: no se pudo soltar el atajo de «{cid}» ({type(e).__name__}: {e})")
    _CMDIA["atajos"].discard(aid)


# ---- paleta Ctrl+K (tkinter clasico, como dice el veredicto del piloto)
def cmdia_paleta_items():
    items = [{"id": "cmdia_nuevo", "cmdia": True, "label": "Nuevo comando de IA", "chip": None, "danger": False,
              "keys": "nuevo comando ia crear guardar prompt plantilla ai command raycast",
              "fn": lambda: cmdia_formulario(), "more": []},
             {"id": "cmdia_archivo", "cmdia": True, "label": "Abrir el archivo de comandos de IA", "chip": None,
              "danger": False, "keys": "comandos ia archivo json editar a mano",
              "fn": _cmdia_abrir_archivo, "more": []}]
    for c in cmdia_todos():
        ok, _why = cmdia_motor_basico(c["modelo"])
        more = []
        if not c.get("integrado"):
            more.append(("Editar el comando", lambda i=c["id"]: cmdia_formulario(i)))
        more.append(("Duplicar para adaptarlo", lambda i=c["id"]: cmdia_formulario(duplicar=i)))
        more.append(("Ejecutar con lo copiado", lambda i=c["id"]: cmdia_lanzar(i, "copiado")))
        atj = _atajo_compacto(atajo_actual(f"comando:{c['id']}", "global")
                              or atajo_actual(f"comando:{c['id']}", "paleta")) if callable(
            globals().get("atajo_actual")) else ""
        items.append({"id": f"cmdia:{c['id']}", "cmdia": True, "cmdia_id": c["id"],
                      "icon": cmdia_icono(c["icono"]),
                      "label": c["titulo"] + ("" if ok else " (motor no disponible)"),
                      "keys": "comando ia " + ("integrado " if c.get("integrado") else "") + c["prompt"][:120],
                      "fn": lambda i=c["id"]: cmdia_lanzar(i, "paleta"), "chip": atj or None,
                      "danger": False, "more": more})
    n_err = len(_CMDIA["errores"]) + (1 if _CMDIA["error_archivo"] else 0)
    if n_err:  # el aviso va primero en su seccion: que se vea sin buscarlo
        items.insert(0, {"id": "_cmdia_errores", "cmdia": True, "icon": "!",
                      "label": ("Comandos de IA: el archivo está dañado (ver por qué)" if _CMDIA["error_archivo"]
                                else f"Comandos de IA: {len(_CMDIA['errores'])} no se cargaron (ver por qué)"),
                      "keys": "comandos ia error danado no se cargaron", "fn": cmdia_ver_errores,
                      "chip": None, "danger": False, "more": []})
    return items


def cmdia_paleta_sync(forzar=False):
    """Pone los comandos (y sus avisos) en la lista de la paleta. Barato: solo
    relee el archivo si cambio."""
    try:
        cmdia_cargar(forzar=forzar)
        _PALETTE_CMDS[:] = [c for c in _PALETTE_CMDS if not c.get("cmdia")] + cmdia_paleta_items()
    except Exception as e:
        log(f"comandos-ia: no se pudieron poner en la paleta ({type(e).__name__}: {e})")


def cmdia_ver_errores():
    partes = ([_CMDIA["error_archivo"]] if _CMDIA["error_archivo"] else []) + list(_CMDIA["errores"])
    if not partes:
        partes = ["Todos los comandos se cargaron bien."]
    messagebox.showwarning("Comandos de IA", "\n\n".join(partes) + f"\n\nArchivo: {CMDIA_FILE}")


def _cmdia_abrir_archivo():
    if not CMDIA_FILE.exists():
        werr = _cmdia_escribir([])
        if werr:
            messagebox.showwarning("Comandos de IA", werr)
            return
        cmdia_cargar(forzar=True)
    os.startfile(str(CMDIA_FILE))


cmdia_cargar(forzar=True)  # al importar: los atajos de cada comando quedan dados de alta


# ---------------------------------------------------------------- asistentes personalizados (perfiles)
# t-asistentes-perfiles (INVESTIGACION-0.3.0 §5, hilo 5 §3). Un «asistente propio»
# NO es un modelo nuevo: es nombre + foto + para qué sirve + instrucciones +
# modelo por defecto (un id de motor de engines.json: el descriptor generico de
# t-motor-generico; aqui NO se crea ningun motor) + modelo de revision + canales
# + skills (nombres que resuelve t-skills-nativas) + tono + carpetas que ve (y con
# que permiso) + guardrail. Cada perfil es un archivo asistentes\<id>.md junto a
# growi-bridge.py: frontmatter YAML + cuerpo Markdown con las instrucciones (el
# mismo patron que SKILL.md y MEMORY.md: se lee en el Bloc de notas y se respalda
# copiando la carpeta). Un perfil mal escrito no aparece y la app dice por que;
# nunca rompe la app. El activo va en settings.json -> asistente_activo y lo usa
# el runner desde la siguiente tarea (instrucciones, modelo, carpetas, revision).
# La memoria larga (MEMORY.md) es compartida; cada perfil suma sus notas propias
# en memory\asistentes\<id>.md (no una copia). Un solo usuario en un solo PC
# (hilo 5 §6.1): sin cuentas ni login. Ningun perfil baja el guardrail a «Hazlo
# sin preguntar» sin escribir SIN PREGUNTAR (y al activarlo se pide el si otra vez).
ASIS_DIR = Path(os.environ.get("GROWI_BRIDGE_ASISTENTES") or (APP_DIR / "asistentes"))
ASIS_NOTAS_DIR = MEMORY_DIR / "asistentes"
ASIS_PRINCIPAL = "growi"
ASIS_MAX_BYTES = 256 * 1024
ASIS_CONFIRMA = "SIN PREGUNTAR"
ASIS_CLAVES = {"nombre", "para_que", "foto", "modelo", "modelo_revision", "tono", "canales", "skills",
               "carpetas", "guardrail", "confirmacion_guardrail", "creado", "modificado"}
# (clave, palabra, lo que se le dice al motor)
ASIS_TONOS = (("formal", "Formal", "Trato de usted, frases completas y sin modismos."),
              ("cercano", "Cercano", "Tuteo venezolano natural, cálido y claro, sin «tío» ni «pana» forzados."),
              ("directo", "Directo", "Tuteo, al grano: primero la respuesta o el número y luego lo mínimo "
                                     "para entenderlo. Sin relleno."),
              ("guaro", "Guaro", "Tuteo venezolano guaro (de Lara), directo y sin personaje forzado: el habla "
                                 "sale natural, nunca de caricatura; sin «tío» ni «pana» forzados."))
ASIS_CANALES = (("paleta", "Paleta (Ctrl+K)"), ("bandeja", "Bandeja"), ("whatsapp", "WhatsApp"))
ASIS_PERMISOS = (("lectura", "Solo leer"), ("escritura", "Leer y escribir"))
ASIS_CARPETAS_MODOS = (("todas", "Todas las de Carpetas"), ("estas", "Solo estas"),
                       ("ninguna", "Ninguna de trabajo"))
