    st["nombre"].pack(anchor="w", padx=18, pady=(6, 0))
    st["nombre"].insert(0, b.get("nombre") or "")
    # Foto
    campo("Foto", "Una imagen de tu PC (PNG o JPG). Si no pones ninguna, o la imagen ya no está, sale un "
                  "círculo con la inicial: nunca se rompe.")
