    kit.button(fr, "Elegir…", _elegir_foto).pack(side="left", padx=(8, 0))
    st["foto_lbl"] = kit.label(card, "", muted=True, wrap=W)
    st["foto_lbl"].pack(anchor="w", fill="x", padx=18, pady=(4, 0))
    st["foto"].bind("<FocusOut>", lambda _e: _asis_form_foto(kit, st), add="+")
    # Para que sirve
