    st["para_que"] = kit.entry(card, width=66)
    st["para_que"].pack(anchor="w", padx=18, pady=(6, 0))
    st["para_que"].insert(0, b.get("para_que") or "")
    # Modelo por defecto
    campo("Modelo por defecto", "El motor que trabaja cuando la tarea no dice cuál (de los descritos en Modelos → "
                                "Motores). Aquí no se crea ningún motor.")
    actual = b.get("modelo") or "claude"
    st["modelo"] = kit.option(card, _cmdia_motores_opciones(actual), width=50, editable=True,
                              command=lambda _v: _asis_form_motor(kit, st))
    st["modelo"].pack(anchor="w", padx=18, pady=(6, 0))
    st["modelo"].set(f"{cmdia_motor_nombre(actual)} ({actual})" if engine_raw(actual) else actual)
    st["modelo_lbl"] = kit.label(card, "", muted=True, wrap=W)
