    st["gr_conf_frame"] = tk.Frame(card, bg=THEME["card"])
    st["gr_conf_frame"].pack(fill="x", padx=18)
    _kit_seg_set(kit, st["guardrail"], b.get("guardrail") or "siempre")
    _asis_form_guardrail(kit, st, b.get("guardrail") or "siempre", inicial=True)
    # Botones
    brow = kit.frame(card)
    brow.pack(fill="x", padx=18, pady=(18, 4))
    st["guardar"] = kit.button(brow, "Guardar", lambda: asis_form_guardar(kit, st), accent=True)
    st["guardar"].pack(side="left")
    kit.button(brow, "Cerrar", top.destroy).pack(side="left", padx=(8, 0))
    st["abrir"] = kit.button(brow, "Abrir el archivo (avanzado)", lambda: _asis_abrir(st.get("aid")))
