def _asis_form_foto(kit, st):
    p = {"id": st.get("aid") or "_form", "nombre": st["nombre"].get() or "?", "foto": st["foto"].get().strip()}
    for ch in st["foto_holder"].winfo_children():
        ch.destroy()
    asis_foto_label(st["foto_holder"], p, 44, bg=THEME["card"]).pack()
    q, why = asis_foto_ruta(p)
    kit.set_label(st["foto_lbl"], f"Se ve así en la paleta y en el aviso ({q.name})." if q else
                  why[:1].upper() + why[1:] + ".", color="muted" if q or not p["foto"] else "orange_text")


def _asis_form_motor(kit, st):
    mid = _cmdia_motor_de_opcion(st["modelo"].get())
    ok, why = asis_motor_ok(mid)
    kit.set_label(st["modelo_lbl"], f"«{mid}»: descrito en engines.json. Costo: {cmdia_motor_costo(mid)}." if ok
                  else f"Motor no disponible: {why}. Se puede guardar, pero sus tareas irán con el motor de por "
                       "defecto hasta que exista.", color="muted" if ok else "red")


def _asis_form_tono(kit, st, k):
    if st.get("tono_lbl") is not None:
        kit.set_label(st["tono_lbl"], next((x for kk, _p, x in ASIS_TONOS if kk == k), ""))


def _asis_form_skills(kit, st):
    nombres = [x.strip() for x in st["skills"].get().split(",") if x.strip()]
    res, faltan, nota = asis_estado_skills({"skills": nombres})
    if not nombres:
        kit.set_label(st["skills_lbl"], "Sin skills fijas: el runner elige por la descripción, como siempre.",
                      color="muted")
    elif nota:
        kit.set_label(st["skills_lbl"], f"Se guardan los nombres: {nota}.", color="orange_text")
    elif faltan:
        kit.set_label(st["skills_lbl"], "No están entre las skills de Bridge: " + ", ".join(faltan)
                      + ". Se guardan los nombres, pero no se inventan." + (" Están: " + ", ".join(
                          s["name"] for s in res) + "." if res else ""), color="orange_text")
    else:
        kit.set_label(st["skills_lbl"], "Están todas: " + ", ".join(s["name"] for s in res) + ".",
                      color="green_text")


def _asis_form_carpetas(kit, st):
    fr = st["carp_frame"]
    for ch in fr.winfo_children():
        ch.destroy()
    modo = kit.seg_get(st["carp_modo"])
    lab = lambda t, color=None: tk.Label(fr, text=t, bg=THEME["card"], fg=THEME.get(color or "muted"),
                                         font=(FONT, 9), anchor="w", justify="left",
                                         wraplength=S(570)).pack(anchor="w", fill="x")
    if modo == "todas":
        lab("Ve las mismas carpetas que la página Carpetas: " + ", ".join(load_folders()) + ".")
        return
    if modo == "ninguna":
        lab("Sin carpetas de trabajo: sus tareas solo usan su espacio propio (asistentes\\<nombre>-espacio).")
        return
    st.setdefault("carp_perm", {})
    for i, (ruta, perm) in enumerate(st["carpetas"]):
        r = kit.frame(fr)
        r.pack(fill="x", pady=(2, 2))
        okd = Path(ruta).is_dir()
        dentro = okd and _inside_any(Path(ruta).resolve(), load_folders())
        kit.button(r, "Quitar", lambda i=i: (st["carpetas"].pop(i), _asis_form_carpetas(kit, st))).pack(
            side="right")
        seg = kit.segmented(r, list(ASIS_PERMISOS), lambda k, i=i: st["carpetas"].__setitem__(
            i, (st["carpetas"][i][0], k)))
        _kit_seg_set(kit, seg, perm)
        seg.pack(side="right", padx=(0, 8))
        kit.label(r, ruta, wrap=300).pack(side="left", fill="x", expand=True)
        if not okd:
            lab("    Esa carpeta no existe: créala o quítala (las tareas no podrán trabajar ahí).", "red")
        elif not dentro:
            lab("    Está fuera de las carpetas permitidas (página Carpetas): no se usará.", "orange_text")
    add = kit.frame(fr)
    add.pack(fill="x", pady=(6, 0))
    ent = kit.entry(add, width=46)
    ent.pack(side="left")

    def _anadir(ruta=None):
        ruta = (ruta or ent.get()).strip().strip('"')
        if not ruta:
            return
        if not Path(ruta).is_absolute():
            kit.set_label(st["estado"], "La carpeta tiene que ser una ruta completa (p. ej. C:\\Users\\...).",
                          color="red")
            return
        if all(Path(r) != Path(ruta) for r, _p in st["carpetas"]):
            st["carpetas"].append((str(Path(ruta)), "lectura"))
        _asis_form_carpetas(kit, st)

    def _elegir():
        d = filedialog.askdirectory(parent=st["top"], title="Carpeta que ve el asistente")
        if d:
            _anadir(str(Path(d)))
    kit.button(add, "Añadir", _anadir).pack(side="left", padx=(8, 0))
    kit.button(add, "Elegir…", _elegir).pack(side="left", padx=(8, 0))
    st["carp_entry"], st["carp_anadir"] = ent, _anadir
    if not st["carpetas"]:
        lab("Todavía ninguna: escribe la ruta o pulsa «Elegir…». Permiso nuevo: solo leer.")


def _asis_form_guardrail(kit, st, k, inicial=False):
    if st.get("gr_lbl") is None:
        return
    kit.set_label(st["gr_lbl"], next((x for kk, _l, x in GUARDRAIL_LEVELS if kk == k), ""),
                  color="red" if k == "nunca" else "muted")
    fr = st["gr_conf_frame"]
    for ch in fr.winfo_children():
        ch.destroy()
    st["gr_conf"] = None
    if k == "nunca":
        kit.label(fr, f"Para bajar los permisos, escribe {ASIS_CONFIRMA} (sin eso no se guarda):",
                  bold=True, color="red", wrap=570).pack(anchor="w", pady=(6, 0))
        st["gr_conf"] = kit.entry(fr, width=24)
        st["gr_conf"].pack(anchor="w", pady=(4, 0))
        if inicial:
            st["gr_conf"].insert(0, ASIS_CONFIRMA)  # ya estaba confirmado en el archivo


def asis_nuevo_id(nombre, actual=None):
    base = re.sub(r"[^a-z0-9]+", "-", _norm(nombre)).strip("-")[:40] or "asistente"
    ocupados = {p["id"] for p in asis_todos()} - {actual}
    try:
        ocupados |= {f.stem for f in ASIS_DIR.glob("*.md")} - {actual}
    except OSError:
        pass
    aid, n = base, 2
    while aid in ocupados:
        aid = f"{base}-{n}"
        n += 1
    return aid


def asis_guardar(d, aid_anterior=None):
    """Escribe asistentes\\<id>.md (temporal + os.replace) y lo relee con el
    mismo validador que al arrancar. -> (ok, mensaje, perfil)."""
    if d.get("guardrail") == "nunca" and _norm(d.get("confirmacion") or "").strip() != _norm(ASIS_CONFIRMA):
        return False, (f"Para «Hazlo sin preguntar» tienes que escribir {ASIS_CONFIRMA}. No se guardó nada: los "
                       "permisos no se bajan sin eso."), None
    aid = aid_anterior or asis_nuevo_id(d.get("nombre") or "")
    ahora = datetime.now(TZ_CARACAS).strftime("%Y-%m-%d %H:%M")
    d = dict(d, id=aid, creado=d.get("creado") or ahora, modificado=ahora)
    texto = asis_a_markdown(d)
    try:
        fm, cuerpo = skill_partir(texto)
        meta = yaml_minimo(fm)
    except ValueError as e:
        return False, f"No se guardó: el archivo no saldría bien ({e}).", None
    p, prob, _av = asis_validar(meta, cuerpo, aid)
    if p is None:
        return False, "No se guardó: " + "; ".join(prob) + ".", None
    otro = next((x for x in asis_todos() if _norm(x["nombre"]) == _norm(p["nombre"]) and x["id"] != aid), None)
    if otro:
        return False, f"No se guardó: ya hay un asistente que se llama «{otro['nombre']}».", None
    dest = ASIS_DIR / f"{aid}.md"
    tmp = dest.with_name(dest.name + ".tmp")
    try:
        ASIS_DIR.mkdir(parents=True, exist_ok=True)
        tmp.write_text(texto, encoding="utf-8")
        os.replace(tmp, dest)
    except OSError as e:
        return False, f"No se pudo escribir {dest.name} ({e.strerror or e}). ¿Está abierto en otro programa?", None
    asis_cargar(forzar=True)
    vuelta, err = asis_leer_archivo(dest)
    if vuelta is None:
        return False, f"{dest.name} se escribió, pero al releerlo no carga: {err}", None
    log(f"asistentes: «{vuelta['nombre']}» guardado en {dest} ({'cambio' if aid_anterior else 'nuevo'}; modelo "
        f"{vuelta['modelo']}, tono {vuelta['tono']}, permisos {asis_guardrail_txt(vuelta['guardrail'])})")
    asis_paleta_sync()
    try:
        if _tray_icon is not None:
            _tray_icon.update_menu()
    except Exception:
        pass
    return True, f"Guardado en asistentes\\{dest.name}. Ya está en la paleta (Ctrl+K) y en la bandeja.", vuelta


def asis_form_guardar(kit, st):
    modo = kit.seg_get(st["carp_modo"])
    carp = "todas" if modo == "todas" else ([] if modo == "ninguna" else list(st["carpetas"]))
    rev = st["revision"].get()
    d = {"nombre": st["nombre"].get().strip(), "foto": st["foto"].get().strip(),
         "para_que": st["para_que"].get().strip(), "modelo": _cmdia_motor_de_opcion(st["modelo"].get()),
         "modelo_revision": "" if rev == "El de siempre" else _cmdia_motor_de_opcion(rev),
         "tono": kit.seg_get(st["tono"]), "instrucciones": _cmdia_tb_get(st["instrucciones"]).strip(),
         "canales": [k for k, get in st["canales"].items() if get()],
         "skills": [x.strip() for x in st["skills"].get().split(",") if x.strip()],
         "carpetas": carp, "guardrail": kit.seg_get(st["guardrail"]),
         "confirmacion": st["gr_conf"].get() if st.get("gr_conf") is not None else "", "creado": st.get("creado")}
    if modo == "estas" and not carp:
        kit.set_label(st["estado"], "No se guardó: elegiste «Solo estas» pero no hay ninguna carpeta. Añade una o "
                                    "elige «Ninguna de trabajo».", color="red")
        return False
    ok, msg, p = asis_guardar(d, aid_anterior=st.get("aid"))
    if not ok:
        kit.set_label(st["estado"], msg, color="red")
        if d["guardrail"] == "nunca" and st.get("gr_conf") is not None:
            st["gr_conf"].focus_set()
        return False
    nuevo = not st.get("aid")
    st["aid"], st["creado"] = p["id"], p["creado"]
    okm, why = asis_motor_ok(p["modelo"])
    kit.set_label(st["estado"], msg + ("" if okm else f" Ojo: motor no disponible ({why})."),
                  color="green_text" if okm else "orange_text")
    if nuevo:
        kit.set_label(st["titulo_lbl"], "Editar asistente")
        st["top"].title("Editar asistente")
        st["abrir"].pack(side="right")
    return True


def _asis_abrir(aid):
    if aid and (ASIS_DIR / f"{aid}.md").exists():
        os.startfile(str(ASIS_DIR / f"{aid}.md"))


def _asis_abrir_notas(aid):
    p = asis_buscar(aid)
    if p is None:
        return
    f = ASIS_NOTAS_DIR / f"{aid}.md"
    if not f.exists():
        try:
            ASIS_NOTAS_DIR.mkdir(parents=True, exist_ok=True)
            f.write_text(f"# Notas propias de {p['nombre']}\n\nSolo para este asistente. La memoria larga "
                         "(MEMORY.md) es la de todos; aquí va lo que solo le sirve a él. Solo se añade.\n",
                         encoding="utf-8")
        except OSError as e:
            messagebox.showwarning("Asistentes", f"No pude crear sus notas ({e}).")
            return
    os.startfile(str(f))


def asis_recordar(texto, aid=None):
    """«recuerda esto» solo para el asistente activo: se anade a sus notas
    propias (nunca se reescribe). -> (ok, mensaje)."""
    p = asis_buscar(aid) if aid else asis_activo()
    if p is None:
        return False, "No hay ningún asistente activo."
    h = (texto.split(":", 1)[-1] if ":" in texto else texto).strip()
    if not h:
        return False, "No hay nada que recordar."
    f = ASIS_NOTAS_DIR / f"{p['id']}.md"
    try:
        ASIS_NOTAS_DIR.mkdir(parents=True, exist_ok=True)
        nuevo = not f.exists()
        with open(f, "a", encoding="utf-8") as fh:
            if nuevo:
                fh.write(f"# Notas propias de {p['nombre']}\n\nSolo para este asistente; la memoria larga es la "
                         "compartida. Solo se añade.\n")
            fh.write(f"\n## {datetime.now(TZ_CARACAS).strftime('%Y-%m-%d %H:%M')}\n- {h}\n")
    except OSError as e:
        return False, f"No se pudo guardar en las notas de {p['nombre']} ({e})."
    log(f"asistentes: recordado solo para «{p['nombre']}» en {f}: «{h[:80]}»")
    try:
        toast(f"Guardado en las notas de {p['nombre']}", ("page", "registro"))
    except Exception:
        pass
    return True, f"Guardado en las notas propias de {p['nombre']} ({f.name})."


# ---- paleta Ctrl+K (tkinter clasico, como dice el veredicto del piloto)
def asis_paleta_items():
    act = asis_activo()
    items = []
    for p in asis_todos():
        if "paleta" not in p["canales"]:
            continue
        es = act is not None and p["id"] == act["id"]
        items.append({"id": f"asis:{p['id']}", "asis": True, "asis_id": p["id"], "foto": p,
                      "label": f"{p['nombre']} (activo)" if es else f"Usar {p['nombre']}",
                      "keys": "asistente perfil cambiar usar " + p["nombre"] + " " + p.get("para_que", ""),
                      "fn": (lambda: None) if es else (lambda i=p["id"]: asis_cambiar(i, "la paleta")),
                      "chip": None, "danger": False,
                      "more": [("Editar el asistente", lambda i=p["id"]: asis_formulario(i)),
                               ("Abrir su archivo", lambda i=p["id"]: _asis_abrir(i)),
                               ("Abrir sus notas propias", lambda i=p["id"]: _asis_abrir_notas(i))]})
    items += [{"id": "asis_nuevo", "asis": True, "label": "Nuevo asistente", "chip": None, "danger": False,
               "keys": "nuevo asistente perfil crear personalizado propio otro", "fn": lambda: asis_formulario(),
               "more": []},
              {"id": "asis_carpeta", "asis": True, "label": "Abrir la carpeta de asistentes", "chip": None,
               "danger": False, "keys": "asistentes perfiles carpeta archivos editar a mano",
               "fn": lambda: (ASIS_DIR.mkdir(parents=True, exist_ok=True), os.startfile(str(ASIS_DIR))),
               "more": []}]
    n_err = len(_ASIS["errores"]) + (1 if _ASIS["error_dir"] else 0)
    if n_err:  # el aviso va primero en su seccion
        items.insert(0, {"id": "_asis_errores", "asis": True, "icon": "!",
                         "label": f"Asistentes: {n_err} no se cargaron (ver por qué)",
                         "keys": "asistentes perfiles error no se cargaron", "fn": asis_ver_errores,
                         "chip": None, "danger": False, "more": []})
    return items


def asis_paleta_sync(forzar=False):
    try:
        asis_cargar(forzar=forzar)
        _PALETTE_CMDS[:] = [c for c in _PALETTE_CMDS if not c.get("asis")] + asis_paleta_items()
    except Exception as e:
        log(f"asistentes: no se pudieron poner en la paleta ({type(e).__name__}: {e})")


def asis_ver_errores():
    partes = ([_ASIS["error_dir"]] if _ASIS["error_dir"] else []) + [f"{n}: {m}." for n, m in _ASIS["errores"]]
    if not partes:
        partes = ["Todos los asistentes se cargaron bien."]
    messagebox.showwarning("Asistentes", "Estos archivos no se cargaron (no aparecen hasta que se arreglen; los "
                                         "demás sí):\n\n" + "\n\n".join(partes) + f"\n\nCarpeta: {ASIS_DIR}")


