def _tray_asis_items():
    out = []
    act = asis_activo()
    for p in asis_todos():
        if "bandeja" not in p["canales"]:
            continue
        out.append(pystray.MenuItem(p["nombre"], (lambda i: (lambda: _root.after(
            0, lambda: asis_cambiar(i, "la bandeja"))))(p["id"]),
            checked=(lambda i: (lambda _it: (asis_activo() or {}).get("id") == i))(p["id"]), radio=True))
    if not out:
        out.append(pystray.MenuItem("No hay asistentes en la bandeja", None, enabled=False))
    out.append(pystray.Menu.SEPARATOR)
